0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2.5 4h2.3l2.2 11.2h11.2l2-8.2H6\"/><path d=\"M7.5 17.5h11\"/><circle cx=\"9\" cy=\"20\" r=\"1\"/><circle cx=\"17.5\" cy=\"20\" r=\"1\"/></svg></span>\n                <span class=\"mobile-menu-commerce__card-copy\"><strong>سبد خرید</strong><small><?php echo esc_html( $cart_count ? $cart_count_text . ' کالا در سبد' : 'مشاهده‌ی سبد خرید' ); ?></small></span>\n                <?php if ( $cart_count > 0 ) : ?><span class=\"mobile-menu-commerce__count\" aria-hidden=\"true\"><?php echo esc_html( $cart_count_text ); ?></span><?php endif; ?>\n            </a>\n            <?php if ( $signed_in ) : ?>\n                <a class=\"mobile-menu-commerce__card mobile-menu-commerce__card--account\" href=\"<?php echo esc_url( $account_url ); ?>\"<?php echo genosys_site_visibility( 'header_show_account' ) ? '' : ' hidden'; ?>>\n                    <span class=\"mobile-menu-commerce__card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"7.5\" r=\"3.4\"/><path d=\"M4.8 20c.4-4.1 3-6.2 7.2-6.2s6.8 2.1 7.2 6.2\"/></svg></span>\n                    <span class=\"mobile-menu-commerce__card-copy\"><strong>حساب کاربری</strong><small>اطلاعات و آدرس‌ها</small></span>\n                </a>\n            <?php else : ?>\n                <a class=\"mobile-menu-commerce__card mobile-menu-commerce__card--login\" href=\"<?php echo esc_url( $login_url ); ?>\"<?php echo genosys_site_visibility( 'header_show_account' ) ? '' : ' hidden'; ?>>\n                    <span class=\"mobile-menu-commerce__card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"7.5\" r=\"3.4\"/><path d=\"M4.8 20c.4-4.1 3-6.2 7.2-6.2s6.8 2.1 7.2 6.2\"/></svg></span>\n                    <span class=\"mobile-menu-commerce__card-copy\"><strong><?php echo esc_html( genosys_site_setting( 'header_login_text' ) ); ?></strong><small>با شماره‌ی موبایل و کد تأیید</small></span>\n                </a>\n            <?php endif; ?>\n        </div>\n        <div class=\"mobile-menu-commerce__secondary\">\n            <?php if ( $signed_in ) : ?>\n                <a class=\"mobile-menu-commerce__secondary-link\" href=\"<?php echo esc_url( $orders_url ); ?>\">\n                    <span class=\"mobile-menu-commerce__card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 8.5h14l-1.2 11H6.2L5 8.5Z\"/><path d=\"M9 9V6a3 3 0 0 1 6 0v3\"/></svg></span>\n                    <span class=\"mobile-menu-commerce__card-copy\"><strong>سفارشات</strong><small>پیگیری و سابقه‌ی خرید</small></span>\n                    <?php if ( $order_count > 0 ) : ?><span class=\"mobile-menu-commerce__count\" aria-hidden=\"true\"><?php echo esc_html( $order_count_text ); ?></span><?php endif; ?>\n                </a>\n                <a class=\"mobile-menu-commerce__secondary-link mobile-menu-commerce__secondary-link--logout\" href=\"<?php echo esc_url( wp_logout_url( home_url( '/' ) ) ); ?>\">\n                    <span class=\"mobile-menu-commerce__card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M13 4H6.5A2.5 2.5 0 0 0 4 6.5v11A2.5 2.5 0 0 0 6.5 20H13\"/><path d=\"m14 8 4 4-4 4m4-4H9\"/></svg></span>\n                    <span class=\"mobile-menu-commerce__card-copy\"><strong>خروج</strong></span>\n                </a>\n            <?php else : ?>\n                <a class=\"mobile-menu-commerce__secondary-link\" href=\"<?php echo esc_url( home_url( '/fans-club/' ) ); ?>\">\n                    <span class=\"mobile-menu-commerce__card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3.5 9h17v11h-17zM2.5 6h19v3h-19zM12 6v14\"/><path d=\"M12 6C9 6 7 5.2 7 3.7 7 2.5 7.8 2 9 2c1.7 0 3 1.8 3 4Zm0 0c3 0 5-0.8 5-2.3C17 2.5 16.2 2 15 2c-1.7 0-3 1.8-3 4Z\"/></svg></span>\n                    <span class=\"mobile-menu-commerce__card-copy\"><strong>باشگاه مشتریان</strong><small>مزایا و پیشنهادهای ویژه</small></span>\n                </a>\n                <a class=\"mobile-menu-commerce__secondary-link\" href=\"<?php echo esc_url( $orders_url ); ?>\">\n                    <span class=\"mobile-menu-commerce__card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 8.5h14l-1.2 11H6.2L5 8.5Z\"/><path d=\"M9 9V6a3 3 0 0 1 6 0v3\"/></svg></span>\n                    <span class=\"mobile-menu-commerce__card-copy\"><strong>پیگیری سفارش</strong><small>با شماره‌ی سفارش</small></span>\n                </a>\n            <?php endif; ?>\n        </div>\n    </section>\n    <?php\n    return ob_get_clean();\n}\n\n/** Keep RTL without a duplicate HTML dir attribute. */\nfunction genosys_language_attributes( $attributes ) {\n    return trim( str_replace( array( 'dir=\"rtl\"', 'dir=\"ltr\"' ), '', $attributes ) ) . ' dir=\"rtl\"';\n}\nadd_filter( 'language_attributes', 'genosys_language_attributes' );\n\n/** The homepage products card follows its configured or existing destination. */\nfunction genosys_home_card_url( $card ) {\n    $custom = get_theme_mod( 'genosys_' . $card . '_link', '' );\n    if ( is_string( $custom ) && '' !== trim( $custom ) ) {\n        return $custom;\n    }\n    $locations = get_nav_menu_locations();\n    if ( ! empty( $locations['primary'] ) ) {\n        $items = wp_get_nav_menu_items( $locations['primary'] );\n        if ( $items ) {\n            foreach ( $items as $item ) {\n                if ( 'محصولات' === trim( wp_strip_all_tags( $item->title ) ) && ! empty( $item->url ) ) {\n                    return $item->url;\n                }\n            }\n        }\n    }\n    return home_url( '/products/' );\n}\n\nfunction genosys_customize_home_cards( $wp_customize ) {\n    $wp_customize->add_section( 'genosys_home_cards', array( 'title' => 'کارت‌های صفحه اصلی', 'priority' => 35 ) );\n    $cards = array(\n        'products' => array( 'label' => 'پیوند مشاهده محصولات', 'description' => 'اگر خالی باشد، از پیوند محصولات در منوی اصلی استفاده می‌شود.' ),\n    );\n    foreach ( $cards as $card => $control ) {\n        $setting = 'genosys_' . $card . '_link';\n        $wp_customize->add_setting( $setting, array( 'default' => '', 'sanitize_callback' => 'esc_url_raw' ) );\n        $wp_customize->add_control( $setting, array( 'label' => $control['label'], 'description' => $control['description'], 'section' => 'genosys_home_cards', 'type' => 'url' ) );\n    }\n}\nadd_action( 'customize_register', 'genosys_customize_home_cards' );\n\n/** Hide MailPoet's optional marketing opt-in from WooCommerce checkout. */\nadd_filter( 'mailpoet_woocommerce_checkout_optin_template', '__return_empty_string' );\n\nrequire_once get_theme_file_path( '/inc/contact.php' );\nrequire_once get_theme_file_path( '/inc/contact-settings.php' );\nrequire_once get_theme_file_path( '/inc/contact-route.php' );\nrequire_once get_theme_file_path( '/inc/brand.php' );\nrequire_once get_theme_file_path( '/inc/company.php' );\nrequire_once get_theme_file_path( '/inc/site-settings.php' );\nrequire_once get_theme_file_path( '/inc/settings-dashboard.php' );\nrequire_once get_theme_file_path( '/inc/css-editor.php' );\nrequire_once get_theme_file_path( '/inc/css-editor-view.php' );\nrequire_once get_theme_file_path( '/inc/php-editor-validator.php' );\nrequire_once get_theme_file_path( '/inc/php-editor.php' );\nrequire_once get_theme_file_path( '/inc/php-editor-view.php' );\nrequire_once get_theme_file_path( '/inc/products.php' );\nrequire_once get_theme_file_path( '/inc/single-product.php' );\nrequire_once get_theme_file_path( '/inc/fans-club.php' );\nrequire_once get_theme_file_path( '/inc/login.php' );\nrequire_once get_theme_file_path( '/inc/login-auth.php' );\nrequire_once get_theme_file_path( '/inc/order-access.php' );\nrequire_once get_theme_file_path( '/inc/theme-settings.php' );\nrequire_once get_theme_file_path( '/inc/jalali-date.php' );\nrequire_once get_theme_file_path( '/inc/order-sms.php' );\nrequire_once get_theme_file_path( '/inc/order-status-sms.php' );\nrequire_once get_theme_file_path( '/inc/cart-animation.php' );\nrequire_once get_theme_file_path( '/inc/checkout-integration.php' );\nrequire_once get_theme_file_path( '/inc/receipts.php' );\nrequire_once get_theme_file_path( '/inc/receipt-sms.php' );\nrequire_once get_theme_file_path( '/inc/receipt-admin.php' );\nrequire_once get_theme_file_path( '/inc/customer-orders.php' );\nrequire_once get_theme_file_path( '/inc/account-dashboard.php' );\nrequire_once get_theme_file_path( '/inc/account-notifications.php' );\nrequire_once get_theme_file_path( '/inc/account-phone-change.php' );\nrequire_once get_theme_file_path( '/inc/shop.php' );\nrequire_once get_theme_file_path( '/inc/product-search.php' );\nrequire_once get_theme_file_path( '/inc/packages.php' );\nrequire_once get_theme_file_path( '/inc/package-visibility.php' );\nrequire_once get_theme_file_path( '/inc/package-builder.php' );\nrequire_once get_theme_file_path( '/inc/package-publishing.php' );\nrequire_once get_theme_file_path( '/inc/package-list-data.php' );\nrequire_once get_theme_file_path( '/inc/package-list.php' );\nrequire_once get_theme_file_path( '/inc/club-members.php' );\nrequire_once get_theme_file_path( '/inc/club-sms.php' );\nrequire_once get_theme_file_path( '/inc/club-admin.php' );\n","sha256":"34f037c553e02a31ac876ddcc7fb52982d21f596997ab48bed3ef460a26310e3"},"header.php":{"content":"<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?>\n<!doctype html>\n<html <?php language_attributes(); ?>>\n<head>\n<meta charset=\"<?php bloginfo( 'charset' ); ?>\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<?php wp_head(); ?>\n</head>\n<body <?php body_class(); ?>>\n<?php wp_body_open(); ?>\n<a class=\"skip-link\" href=\"#main\">رفتن به محتوای اصلی</a>\n<?php\n$on_banner = ( is_front_page() && ! is_404() && genosys_home_has_first_slider() ) || genosys_is_brand();\n$brand_name = (string) genosys_site_setting( 'site_name', 'ژنوسیس' );\n$mobile_logo_id = (int) get_theme_mod( 'custom_logo', 0 );\n$mobile_logo_fallback = $mobile_logo_id ? wp_get_attachment_image_url( $mobile_logo_id, 'full' ) : '';\n$mobile_logo = genosys_site_url( 'header_logo_home', $mobile_logo_fallback ?: get_theme_file_uri( '/assets/images/genosys-logo-light-1.2.4.svg' ) );\n?>\n<header class=\"site-header <?php echo $on_banner ? 'site-header--banner' : 'site-header--standard'; ?>\">\n<div class=\"header-inner\">\n<div class=\"site-branding\">\n<?php\n$header_logo = genosys_site_setting( $on_banner ? 'header_logo_home' : 'header_logo_internal', '' );\nif ( '' === $header_logo && has_custom_logo() ) : the_custom_logo(); else :\n?>\n<a class=\"brand-link\" href=\"<?php echo esc_url( home_url( '/' ) ); ?>\" aria-label=\"<?php echo esc_attr( $brand_name . ' — صفحه اصلی' ); ?>\">\n<img class=\"brand-logo\" src=\"<?php echo esc_url( ( '' !== $header_logo ? $header_logo : get_theme_file_uri( $on_banner ? '/assets/images/genosys-logo-light-1.2.4.svg' : '/assets/images/genosys-logo-1.1.1.svg' ) ) ); ?>\" alt=\"<?php echo esc_attr( $brand_name ); ?>\" width=\"265\" height=\"58\">\n</a>\n<?php endif; ?>\n</div>\n<nav id=\"primary-navigation\" class=\"primary-navigation\" aria-label=\"منوی اصلی\">\n<div class=\"mobile-menu-topbar\">\n<a class=\"mobile-menu-brand\" href=\"<?php echo esc_url( home_url( '/' ) ); ?>\" aria-label=\"<?php echo esc_attr( $brand_name . ' — صفحه اصلی' ); ?>\"><img src=\"<?php echo esc_url( $mobile_logo ); ?>\" alt=\"<?php echo esc_attr( $brand_name ); ?>\" width=\"265\" height=\"58\"></a>\n<button class=\"mobile-menu-close\" type=\"button\" aria-label=\"بستن منو\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\" focusable=\"false\"><path d=\"m5 5 14 14M19 5 5 19\"/></svg></button>\n</div>\n<?php echo genosys_mobile_menu_commerce(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Links and account data are escaped in the renderer. ?>\n<?php wp_nav_menu( array( 'theme_location' => 'primary', 'container' => false, 'menu_id' => 'primary-menu', 'menu_class' => 'primary-menu', 'fallback_cb' => 'genosys_fallback_menu', 'depth' => 2 ) ); ?>\n</nav>\n<?php echo genosys_header_actions(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Links and account data are escaped in the renderer. ?>\n<button class=\"menu-toggle\" type=\"button\" aria-controls=\"primary-navigation\" aria-expanded=\"false\" aria-label=\"باز کردن منو\"><svg class=\"menu-open-icon\" viewBox=\"0 0 28 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3.3\" stroke-linecap=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M4 4h20M6 12h16M4 20h20\"/></svg><svg class=\"menu-close-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\" focusable=\"false\"><path d=\"m5 5 14 14M19 5 5 19\"/></svg></button>\n</div>\n</header>\n\r\n","sha256":"cf8f86c5584b118e9d90d9c4f3c80e4d820ccc88432af91d21c949cc379d0560"},"inc/account-dashboard.php":{"content":"<?php\n/** Private customer dashboard and current-customer profile updates. */\ndefined( 'ABSPATH' ) || exit;\n\n/** Account root and native address editing share this shell; other endpoints retain their routes. */\nfunction genosys_is_account_dashboard() {\n\treturn is_user_logged_in() && function_exists( 'is_account_page' ) && function_exists( 'is_wc_endpoint_url' ) && is_account_page() && ( ! is_wc_endpoint_url() || is_wc_endpoint_url( 'edit-address' ) );\n}\n\nfunction genosys_account_dashboard_template( $template ) {\n\treturn genosys_is_account_dashboard() ? get_theme_file_path( '/page-account-dashboard.php' ) : $template;\n}\nadd_filter( 'template_include', 'genosys_account_dashboard_template', 99 );\n\nfunction genosys_account_dashboard_nocache() {\n\tif ( genosys_is_account_dashboard() ) {\n\t\tif ( ! defined( 'DONOTCACHEPAGE' ) ) {\n\t\t\tdefine( 'DONOTCACHEPAGE', true );\n\t\t}\n\t\tnocache_headers();\n\t}\n}\nadd_action( 'template_redirect', 'genosys_account_dashboard_nocache', 1 );\n\nfunction genosys_account_dashboard_assets() {\n\tif ( ! genosys_is_account_dashboard() ) {\n\t\treturn;\n\t}\n\twp_enqueue_style( 'genosys-account-dashboard', get_theme_file_uri( '/assets/css/account-dashboard.css' ), array( 'genosys-style' ), '1.5.81' );\n\twp_enqueue_script( 'genosys-account-dashboard', get_theme_file_uri( '/assets/js/account-dashboard.js' ), array(), '1.5.83', true );\n\twp_localize_script( 'genosys-account-dashboard', 'genosysAccountDashboard', array(\n\t\t'ajaxUrl' => admin_url( 'admin-ajax.php' ),\n\t\t'nonce' => wp_create_nonce( 'genosys_account_dashboard' ),\n\t\t'saveAction' => 'genosys_account_save',\n\t\t'avatarAction' => 'genosys_account_avatar',\n\t\t'notificationAction' => 'genosys_account_notifications_save',\n\t\t'notificationGetAction' => 'genosys_account_notifications_get',\n\t\t'phoneRequestAction' => 'genosys_account_phone_request',\n\t\t'phoneResendAction' => 'genosys_account_phone_resend',\n\t\t'phoneVerifyAction' => 'genosys_account_phone_verify',\n\t) );\n}\nadd_action( 'wp_enqueue_scripts', 'genosys_account_dashboard_assets', 20 );\n\nfunction genosys_account_dashboard_body_class( $classes ) {\n\tif ( genosys_is_account_dashboard() ) {\n\t\t$classes[] = 'genosys-account-dashboard';\n\t}\n\treturn $classes;\n}\nadd_filter( 'body_class', 'genosys_account_dashboard_body_class' );\n\nfunction genosys_account_dashboard_digits_ascii( $value ) {\n\treturn strtr( (string) $value, array( '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4', '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9', '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4', '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9' ) );\n}\n\nfunction genosys_account_dashboard_digits( $value ) {\n\treturn function_exists( 'genosys_persian_number' ) ? genosys_persian_number( $value ) : (string) $value;\n}\n\nfunction genosys_account_dashboard_shamsi( $timestamp ) {\n\treturn function_exists( 'genosys_sms_shamsi_date' ) ? substr( genosys_account_dashboard_digits_ascii( genosys_sms_shamsi_date( $timestamp ) ), 0, 10 ) : '';\n}\n\n/** Validate against the theme's established calendar, including leap-day and future dates. */\nfunction genosys_account_dashboard_birth( $day, $month, $year ) {\n\t$empty = array( 'day' => '', 'month' => '', 'year' => '' );\n\t$raw = array_map( 'genosys_account_dashboard_digits_ascii', array( $day, $month, $year ) );\n\tif ( array( '', '', '' ) === $raw ) {\n\t\treturn $empty;\n\t}\n\tforeach ( $raw as $part ) {\n\t\tif ( ! preg_match( '/^[0-9]{1,4}$/D', $part ) ) {\n\t\t\treturn new WP_Error( 'invalid_birth', 'تاریخ تولد معتبر را کامل انتخاب کنید.' );\n\t\t}\n\t}\n\tlist( $d, $m, $y ) = array_map( 'intval', $raw );\n\t$today = genosys_account_dashboard_shamsi( time() );\n\tif ( ! $today || $y < 1200 || $y > (int) substr( $today, 0, 4 ) || $m < 1 || $m > 12 || $d < 1 || $d > ( $m <= 6 ? 31 : 30 ) ) {\n\t\treturn new WP_Error( 'invalid_birth', 'تاریخ تولد معتبر انتخاب کنید.' );\n\t}\n\t$canonical = sprintf( '%04d/%02d/%02d', $y, $m, $d );\n\tif ( $canonical > $today ) {\n\t\treturn new WP_Error( 'future_birth', 'تاریخ تولد نمی‌تواند در آینده باشد.' );\n\t}\n\t// Nowruz falls within this bounded Gregorian range in the supported years.\n\t$start = null;\n\tfor ( $march = 19; $march <= 22; $march++ ) {\n\t\t$date = new DateTimeImmutable( sprintf( '%04d-03-%02d 12:00:00', $y + 621, $march ), wp_timezone() );\n\t\tif ( sprintf( '%04d/01/01', $y ) === genosys_account_dashboard_shamsi( $date->getTimestamp() ) ) {\n\t\t\t$start = $date;\n\t\t\tbreak;\n\t\t}\n\t}\n\t$offset = $m <= 6 ? ( $m - 1 ) * 31 + $d - 1 : 186 + ( $m - 7 ) * 30 + $d - 1;\n\tif ( ! $start || $canonical !== genosys_account_dashboard_shamsi( $start->modify( '+' . $offset . ' days' )->getTimestamp() ) ) {\n\t\treturn new WP_Error( 'invalid_birth', 'روز انتخاب‌شده برای این ماه و سال معتبر نیست.' );\n\t}\n\treturn array( 'day' => (string) $d, 'month' => (string) $m, 'year' => (string) $y );\n}\n\nfunction genosys_account_dashboard_saved_birth( $user_id ) {\n\t$raw = get_user_meta( $user_id, 'genosys_birth_date', true );\n\t$stored = is_scalar( $raw ) ? genosys_account_dashboard_digits_ascii( $raw ) : '';\n\tif ( preg_match( '/^([0-9]{4})\\/([0-9]{2})\\/([0-9]{2})$/D', $stored, $parts ) ) {\n\t\t$birth = genosys_account_dashboard_birth( $parts[3], $parts[2], $parts[1] );\n\t\tif ( ! is_wp_error( $birth ) ) {\n\t\t\treturn $birth;\n\t\t}\n\t}\n\treturn array( 'day' => '', 'month' => '', 'year' => '' );\n}\n\n/** Genuine account age; club enrolment is a separate explicit datum. */\nfunction genosys_account_dashboard_age( $registered ) {\n\t$today = new DateTimeImmutable( 'now', wp_timezone() );\n\t$date = DateTimeImmutable::createFromFormat( '!Y-m-d H:i:s', (string) $registered, new DateTimeZone( 'UTC' ) );\n\tif ( ! $date || '0000-00-00 00:00:00' === $registered || $date > $today ) {\n\t\treturn array( 'days' => 0, 'duration' => 'امروز' );\n\t}\n\t$interval = $date->setTimezone( wp_timezone() )->diff( $today );\n\t$parts = array();\n\tif ( $interval->y ) {\n\t\t$parts[] = genosys_account_dashboard_digits( $interval->y ) . ' سال';\n\t}\n\tif ( $interval->m ) {\n\t\t$parts[] = genosys_account_dashboard_digits( $interval->m ) . ' ماه';\n\t}\n\tif ( ! $parts && $interval->days ) {\n\t\t$parts[] = genosys_account_dashboard_digits( $interval->days ) . ' روز';\n\t}\n\treturn array( 'days' => (int) $interval->days, 'duration' => $parts ? implode( ' و ', $parts ) . ' پیش' : 'امروز' );\n}\n\n/** The caller can only receive the signed-in customer's data. No public cache. */\nfunction genosys_account_dashboard_context() {\n\tif ( ! is_user_logged_in() || ! function_exists( 'WC' ) ) {\n\t\treturn array();\n\t}\n\t$user = get_userdata( get_current_user_id() );\n\tif ( ! $user ) {\n\t\treturn array();\n\t}\n\t$user_id = (int) $user->ID;\n\t$customer = new WC_Customer( $user_id );\n\t$first = (string) get_user_meta( $user_id, 'first_name', true );\n\t$last = (string) get_user_meta( $user_id, 'last_name', true );\n\t$name = trim( $first . ' ' . $last );\n\tif ( '' === $name ) {\n\t\t$name = $user->display_name;\n\t}\n\t$trusted_phone = function_exists( 'genosys_sms_normalize_phone' ) ? genosys_sms_normalize_phone( (string) get_user_meta( $user_id, 'genosys_phone', true ) ) : '';\n\t$phone = $trusted_phone ?: (string) $customer->get_billing_phone();\n\t$age = genosys_account_dashboard_age( $user->user_registered );\n\t$club = in_array( get_user_meta( $user_id, 'genosys_club_member', true ), array( true, 1, '1', 'yes' ), true );\n\t$type = $club ? 'member' : ( $age['days'] < 30 ? 'new' : 'returning' );\n\t$type = apply_filters( 'genosys_account_membership_type', $type, $user, $club );\n\t$type = in_array( $type, array( 'member', 'new', 'returning' ), true ) ? $type : ( $club ? 'member' : 'new' );\n\t// A presentation filter cannot invent a club enrolment.\n\tif ( 'member' === $type && ! $club ) {\n\t\t$type = $age['days'] < 30 ? 'new' : 'returning';\n\t}\n\t$labels = array( 'member' => 'عضو باشگاه مشتریان', 'new' => 'کاربر جدید', 'returning' => 'کاربر قدیمی' );\n\t$since = '';\n\t$joined = get_user_meta( $user_id, 'genosys_club_joined_at', true );\n\tif ( $club && is_scalar( $joined ) && preg_match( '/^[1-9][0-9]{8,10}$/D', (string) $joined ) && (int) $joined <= time() ) {\n\t\t$ymd = explode( '/', genosys_account_dashboard_shamsi( (int) $joined ) );\n\t\t$months = array( '', 'فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند' );\n\t\tif ( 3 === count( $ymd ) && isset( $months[ (int) $ymd[1] ] ) ) {\n\t\t\t$since = $months[ (int) $ymd[1] ] . ' ' . genosys_account_dashboard_digits( $ymd[0] );\n\t\t}\n\t}\n\t$avatar_raw = get_user_meta( $user_id, 'genosys_avatar_id', true );\n\t$avatar_id = is_scalar( $avatar_raw ) && preg_match( '/^[1-9][0-9]*$/D', (string) $avatar_raw ) ? (int) $avatar_raw : 0;\n\t$avatar = $avatar_id && (int) get_post_field( 'post_author', $avatar_id ) === $user_id && wp_attachment_is_image( $avatar_id ) ? wp_get_attachment_image_url( $avatar_id, 'medium' ) : '';\n\t$addresses = array();\n\t$address_count = 0;\n\tforeach ( array( 'billing' => 'آدرس صورتحساب', 'shipping' => 'آدرس ارسال' ) as $key => $label ) {\n\t\t$address = 'billing' === $key ? $customer->get_billing() : $customer->get_shipping();\n\t\t$exists = '' !== trim( (string) ( $address['address_1'] ?? '' ) . (string) ( $address['city'] ?? '' ) . (string) ( $address['postcode'] ?? '' ) );\n\t\t$formatted = $exists && WC()->countries ? WC()->countries->get_formatted_address( $address ) : '';\n\t\t$formatted = html_entity_decode( wp_strip_all_tags( preg_replace( '/<br\\s*\\/?\\s*>/i', \"\\n\", $formatted ) ), ENT_QUOTES, 'UTF-8' );\n\t\t$addresses[] = array( 'key' => $key, 'label' => $label, 'formatted' => $formatted, 'editUrl' => wc_get_endpoint_url( 'edit-address', $key, wc_get_page_permalink( 'myaccount' ) ), 'exists' => $exists );\n\t\t$address_count += (int) $exists;\n\t}\n\t$ids = function_exists( 'genosys_customer_orders_history' ) ? genosys_customer_orders_history() : array();\n\t$orders_count = 0;\n\t$orders_active_count = 0;\n\t$notifications = array();\n\t$authorized_orders = array();\n\t$order_urls = array();\n\tforeach ( $ids as $id ) {\n\t\t$order = wc_get_order( $id );\n\t\tif ( ! $order || ! function_exists( 'genosys_order_access_can_view' ) || ! genosys_order_access_can_view( $order ) ) {\n\t\t\tcontinue;\n\t\t}\n\t\t$orders_count++;\n\t\t$authorized_orders[ (int) $id ] = $order;\n\t\t// The orders view renders twelve authorized orders per page in this history order.\n\t\t$order_page = (int) ceil( $orders_count / 12 );\n\t\t$order_urls[ (int) $id ] = ( function_exists( 'genosys_customer_orders_url' ) ? genosys_customer_orders_url( 'all', $order_page ) : wc_get_account_endpoint_url( 'orders' ) ) . '#gco-order-' . (int) $id;\n\t\tif ( ! $order->has_status( array( 'cancelled', 'failed', 'refunded', 'completed', 'delivered' ) ) ) {\n\t\t\t$orders_active_count++;\n\t\t}\n\t}\n\tif ( function_exists( 'wc_get_order_notes' ) ) {\n\t\tforeach ( array_chunk( array_keys( $authorized_orders ), 200 ) as $order_ids ) {\n\t\t\tforeach ( wc_get_order_notes( array( 'order__in' => $order_ids, 'type' => 'customer', 'limit' => 30, 'orderby' => 'date_created_gmt', 'order' => 'DESC' ) ) as $note ) {\n\t\t\t\t$comment = get_comment( $note->id );\n\t\t\t\t$id = $comment ? (int) $comment->comment_post_ID : 0;\n\t\t\t\t// Recheck the canonical visibility flag even if another plugin widens the query.\n\t\t\t\tif ( ! $comment || ! isset( $authorized_orders[ $id ] ) || 'order_note' !== $comment->comment_type || '1' !== (string) $comment->comment_approved || empty( $note->customer_note ) || 1 !== (int) get_comment_meta( $note->id, 'is_customer_note', true ) ) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\t$order = $authorized_orders[ $id ];\n\t\t\t\t$date = $note->date_created;\n\t\t\t\t$stamp = $date ? $date->getTimestamp() : 0;\n\t\t\t\t$notifications[] = array( 'id' => (int) $note->id, 'orderId' => (int) $id, 'orderNumber' => (string) $order->get_order_number(), 'content' => html_entity_decode( wp_strip_all_tags( $note->content ), ENT_QUOTES, 'UTF-8' ), 'dateISO' => $stamp ? gmdate( DATE_ATOM, $stamp ) : '', 'dateText' => $stamp && function_exists( 'genosys_sms_shamsi_date' ) ? genosys_sms_shamsi_date( $stamp ) : '', 'url' => $order_urls[ $id ] );\n\t\t\t}\n\t\t}\n\t}\n\tusort( $notifications, static function ( $a, $b ) { return strcmp( $b['dateISO'], $a['dateISO'] ) ?: $b['id'] <=> $a['id']; } );\n\treturn array(\n\t\t'userId' => $user_id, 'firstName' => $first, 'lastName' => $last, 'displayName' => $name,\n\t\t'email' => (string) $user->user_email, 'birth' => genosys_account_dashboard_saved_birth( $user_id ),\n\t\t'phone' => $phone, 'phoneVerified' => '' !== $trusted_phone, 'avatarUrl' => $avatar ?: '',\n\t\t'membershipType' => $type, 'membershipLabel' => $labels[ $type ], 'memberDurationText' => $age['duration'], 'daysMember' => $age['days'],\n\t\t'clubActive' => $club, 'clubSinceText' => $since, 'ordersCount' => $orders_count, 'ordersActiveCount' => $orders_active_count,\n\t\t'addresses' => $addresses, 'addressCount' => $address_count, 'notifications' => array_slice( $notifications, 0, 30 ),\n\t\t'notificationPreferences' => genosys_account_notification_preferences( $user_id ),\n\t\t'ordersUrl' => wc_get_account_endpoint_url( 'orders' ), 'accountUrl' => wc_get_page_permalink( 'myaccount' ),\n\t\t'logoutUrl' => wc_logout_url( wc_get_page_permalink( 'myaccount' ) ), 'clubUrl' => home_url( '/fans-club/' ),\n\t);\n}\n\nfunction genosys_account_dashboard_error( $message, $status = 400, $field = '' ) {\n\t$data = array( 'message' => $message );\n\tif ( $field ) {\n\t\t$data['field'] = $field;\n\t}\n\twp_send_json_error( $data, $status );\n}\n\n/** Same authenticated, nonce-bound checks for both current-customer mutations. */\nfunction genosys_account_dashboard_authorize( $allowed ) {\n\tnocache_headers();\n\tif ( 'POST' !== ( $_SERVER['REQUEST_METHOD'] ?? '' ) ) {\n\t\tgenosys_account_dashboard_error( 'روش درخواست معتبر نیست.', 405 );\n\t}\n\tif ( ! is_user_logged_in() ) {\n\t\tgenosys_account_dashboard_error( 'برای ویرایش حساب وارد شوید.', 401 );\n\t}\n\t$nonce = isset( $_POST['nonce'] ) && is_string( $_POST['nonce'] ) ? wp_unslash( $_POST['nonce'] ) : '';\n\tif ( ! wp_verify_nonce( $nonce, 'genosys_account_dashboard' ) ) {\n\t\tgenosys_account_dashboard_error( 'اعتبار درخواست منقضی شده است. صفحه را تازه کنید.', 403 );\n\t}\n\tforeach ( $_POST as $key => $value ) {\n\t\tif ( ! in_array( $key, array_merge( array( 'action', 'nonce' ), $allowed ), true ) || ! is_string( $value ) ) {\n\t\t\tgenosys_account_dashboard_error( 'اطلاعات ارسال‌شده معتبر نیست.', 400 );\n\t\t}\n\t}\n\treturn get_current_user_id();\n}\n\nfunction genosys_account_dashboard_request( $key ) {\n\treturn isset( $_POST[ $key ] ) && is_string( $_POST[ $key ] ) ? trim( wp_unslash( $_POST[ $key ] ) ) : '';\n}\n\n/** No phone, club, role, user-ID or historical-order fields can be changed here. */\nfunction genosys_account_dashboard_save() {\n\t$id = genosys_account_dashboard_authorize( array( 'first_name', 'last_name', 'email', 'birth_day', 'birth_month', 'birth_year' ) );\n\t$values = array();\n\tforeach ( array( 'first_name' => 'نام', 'last_name' => 'نام خانوادگی' ) as $key => $label ) {\n\t\t$raw = genosys_account_dashboard_request( $key );\n\t\t$value = sanitize_text_field( $raw );\n\t\t$length = function_exists( 'mb_strlen' ) ? mb_strlen( $value, 'UTF-8' ) : preg_match_all( '/./us', $value );\n\t\tif ( '' === $value || $length > 100 || preg_match( '/[|\\x00-\\x1F\\x7F]/', $raw ) ) {\n\t\t\tgenosys_account_dashboard_error( $label . ' معتبر وارد کنید (حداکثر ۱۰۰ نویسه).', 400, $key );\n\t\t}\n\t\t$values[ $key ] = $value;\n\t}\n\t$email_raw = genosys_account_dashboard_request( 'email' );\n\t$email = sanitize_email( $email_raw );\n\tif ( '' !== $email_raw && ( ! is_email( $email_raw ) || $email !== $email_raw || strlen( $email ) > 100 ) ) {\n\t\tgenosys_account_dashboard_error( 'ایمیل معتبر وارد کنید.', 400, 'email' );\n\t}\n\t$existing = '' !== $email ? email_exists( $email ) : false;\n\tif ( $existing && (int) $existing !== $id ) {\n\t\tgenosys_account_dashboard_error( 'این ایمیل برای حساب دیگری ثبت شده است.', 409, 'email' );\n\t}\n\t$birth = genosys_account_dashboard_birth( genosys_account_dashboard_request( 'birth_day' ), genosys_account_dashboard_request( 'birth_month' ), genosys_account_dashboard_request( 'birth_year' ) );\n\tif ( is_wp_error( $birth ) ) {\n\t\tgenosys_account_dashboard_error( $birth->get_error_message(), 400, 'birth_day' );\n\t}\n\t$updated = wp_update_user( array( 'ID' => $id, 'first_name' => $values['first_name'], 'last_name' => $values['last_name'], 'display_name' => trim( $values['first_name'] . ' ' . $values['last_name'] ), 'user_email' => $email ) );\n\tif ( is_wp_error( $updated ) ) {\n\t\tgenosys_account_dashboard_error( 'ذخیره اطلاعات انجام نشد. دوباره تلاش کنید.', 500 );\n\t}\n\tforeach ( $values as $key => $value ) {\n\t\tupdate_user_meta( $id, 'billing_' . $key, $value );\n\t}\n\tupdate_user_meta( $id, 'billing_email', $email );\n\tif ( '' === $birth['year'] ) {\n\t\tdelete_user_meta( $id, 'genosys_birth_date' );\n\t} else {\n\t\tupdate_user_meta( $id, 'genosys_birth_date', sprintf( '%04d/%02d/%02d', $birth['year'], $birth['month'], $birth['day'] ) );\n\t}\n\tclean_user_cache( $id );\n\twp_set_current_user( $id );\n\twp_send_json_success( array( 'context' => genosys_account_dashboard_context(), 'message' => 'اطلاعات حساب با موفقیت ذخیره شد.' ) );\n}\nadd_action( 'wp_ajax_genosys_account_save', 'genosys_account_dashboard_save' );\nadd_action( 'wp_ajax_nopriv_genosys_account_save', 'genosys_account_dashboard_save' );\n\n/** A customer may upload their own avatar without general media-library access. */\nfunction genosys_account_dashboard_avatar() {\n\t$id = genosys_account_dashboard_authorize( array( 'operation' ) );\n\t$operation = genosys_account_dashboard_request( 'operation' );\n\tif ( 'remove' === $operation ) {\n\t\tdelete_user_meta( $id, 'genosys_avatar_id' );\n\t\twp_send_json_success( array( 'context' => genosys_account_dashboard_context(), 'message' => 'عکس حساب حذف شد.' ) );\n\t}\n\tif ( 'upload' !== $operation || 1 !== count( $_FILES ) || empty( $_FILES['avatar'] ) || ! is_array( $_FILES['avatar'] ) ) {\n\t\tgenosys_account_dashboard_error( 'تصویر معتبر انتخاب کنید.', 400 );\n\t}\n\t$file = $_FILES['avatar'];\n\tif ( ! isset( $file['error'], $file['tmp_name'], $file['name'] ) || ! is_scalar( $file['error'] ) || ! is_string( $file['tmp_name'] ) || ! is_string( $file['name'] ) || UPLOAD_ERR_OK !== (int) $file['error'] || ! is_uploaded_file( $file['tmp_name'] ) ) {\n\t\tgenosys_account_dashboard_error( 'بارگذاری تصویر انجام نشد. دوباره تلاش کنید.', 400 );\n\t}\n\t$size = filesize( $file['tmp_name'] );\n\tif ( false === $size || $size < 1 || $size > 5 * MB_IN_BYTES ) {\n\t\tgenosys_account_dashboard_error( 'حجم تصویر باید حداکثر ۵ مگابایت باشد.', 400 );\n\t}\n\trequire_once ABSPATH . 'wp-admin/includes/file.php';\n\trequire_once ABSPATH . 'wp-admin/includes/image.php';\n\trequire_once ABSPATH . 'wp-admin/includes/media.php';\n\t$mimes = array( 'jpg|jpeg' => 'image/jpeg', 'png' => 'image/png', 'webp' => 'image/webp' );\n\t$checked = wp_check_filetype_and_ext( $file['tmp_name'], $file['name'], $mimes );\n\t$dimensions = wp_getimagesize( $file['tmp_name'] );\n\tif ( empty( $checked['ext'] ) || empty( $checked['type'] ) || ! in_array( $checked['type'], $mimes, true ) || ! $dimensions || empty( $dimensions[0] ) || empty( $dimensions[1] ) || $dimensions[0] * $dimensions[1] > 40000000 || $dimensions['mime'] !== $checked['type'] ) {\n\t\tgenosys_account_dashboard_error( 'فقط تصویر معتبر JPG، PNG یا WebP قابل انتخاب است.', 400 );\n\t}\n\t// The image editor must actually decode the file before it enters media storage.\n\t$editor = wp_get_image_editor( $file['tmp_name'] );\n\tif ( is_wp_error( $editor ) || ! $editor->get_size() ) {\n\t\tgenosys_account_dashboard_error( 'تصویر قابل خواندن نیست. تصویر دیگری انتخاب کنید.', 400 );\n\t}\n\tunset( $editor );\n\t$attachment_id = media_handle_upload( 'avatar', 0, array( 'post_author' => $id, 'post_title' => 'تصویر حساب ' . $id ), array( 'test_form' => false, 'mimes' => $mimes ) );\n\tif ( is_wp_error( $attachment_id ) ) {\n\t\tgenosys_account_dashboard_error( 'ذخیره تصویر انجام نشد. دوباره تلاش کنید.', 500 );\n\t}\n\tupdate_user_meta( $id, 'genosys_avatar_id', $attachment_id );\n\twp_send_json_success( array( 'context' => genosys_account_dashboard_context(), 'message' => 'عکس حساب با موفقیت تغییر کرد.' ) );\n}\nadd_action( 'wp_ajax_genosys_account_avatar', 'genosys_account_dashboard_avatar' );\nadd_action( 'wp_ajax_nopriv_genosys_account_avatar', 'genosys_account_dashboard_avatar' );\n","sha256":"682221792e8cf2b4f770374bb0b8629f0bc7c587cb40c446e4165c145c0c3818"},"inc/account-notifications.php":{"content":"<?php\n/** Current-customer notification choices and an explicitly subscribed monthly digest. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_account_notification_keys() {\n\treturn array( 'order_status_sms', 'payment_sms', 'promotions', 'newsletter' );\n}\n\n/** Preserve actual historic club consent; a membership badge alone is not consent. */\nfunction genosys_account_notification_club_consent( $user_id ) {\n\tif ( ! $user_id || ! function_exists( 'genosys_club_member_raw' ) ) { return false; }\n\t$ids = get_posts( array( 'post_type' => 'genosys_club_member', 'post_status' => 'private', 'posts_per_page' => 20, 'fields' => 'ids', 'no_found_rows' => true, 'suppress_filters' => true, 'meta_query' => array( array( 'key' => '_genosys_club_owner_user', 'value' => (int) $user_id ) ) ) );\n\tforeach ( $ids as $id ) {\n\t\t$record = genosys_club_member_raw( $id );\n\t\tif ( $record && (int) ( $record['userId'] ?? 0 ) === (int) $user_id && 'active' === ( $record['status'] ?? '' ) && true === ( $record['data']['consent'] ?? false ) ) { return true; }\n\t}\n\treturn false;\n}\n\nfunction genosys_account_notification_preferences( $user_id = 0, $fresh = false ) {\n\t$user_id = $user_id ? (int) $user_id : get_current_user_id();\n\tif ( $fresh ) { wp_cache_delete( $user_id, 'user_meta' ); }\n\t$defaults = array( 'order_status_sms' => true, 'payment_sms' => true, 'promotions' => null, 'newsletter' => false );\n\t$result = array();\n\tforeach ( $defaults as $key => $default ) {\n\t\t$value = get_user_meta( $user_id, 'genosys_notify_' . $key, true );\n\t\tif ( metadata_exists( 'user', $user_id, 'genosys_notify_' . $key ) ) {\n\t\t\t$result[ $key ] = in_array( $value, array( '1', 1, true ), true );\n\t\t} else {\n\t\t\t$result[ $key ] = null === $default ? genosys_account_notification_club_consent( $user_id ) : $default;\n\t\t}\n\t}\n\treturn $result;\n}\n\n/** An atomic named lock avoids duplicate first-time usermeta rows and lost same-key writes. */\nfunction genosys_account_notification_lock( $scope, $ttl = 60 ) {\n\tglobal $wpdb;\n\t$key = 'genosys_notification_lock_' . hash( 'sha256', (string) $scope );\n\t$value = time() . ':' . wp_generate_uuid4();\n\tif ( add_option( $key, $value, '', false ) ) { return array( $key, $value ); }\n\t$old = get_option( $key );\n\tif ( is_string( $old ) && (int) $old < time() - $ttl ) {\n\t\t$deleted = $wpdb->query( $wpdb->prepare( \"DELETE FROM {$wpdb->options} WHERE option_name = %s AND option_value = %s\", $key, $old ) );\n\t\tif ( $deleted ) { wp_cache_delete( $key, 'options' ); if ( add_option( $key, $value, '', false ) ) { return array( $key, $value ); } }\n\t}\n\treturn false;\n}\n\nfunction genosys_account_notification_unlock( $lock ) {\n\tif ( ! $lock ) { return; }\n\tglobal $wpdb;\n\t$wpdb->query( $wpdb->prepare( \"DELETE FROM {$wpdb->options} WHERE option_name = %s AND option_value = %s\", $lock[0], $lock[1] ) );\n\twp_cache_delete( $lock[0], 'options' );\n}\n\nfunction genosys_account_notifications_get() {\n\t$user_id = genosys_account_dashboard_authorize( array() );\n\twp_send_json_success( array( 'preferences' => genosys_account_notification_preferences( $user_id, true ), 'message' => '' ) );\n}\nadd_action( 'wp_ajax_genosys_account_notifications_get', 'genosys_account_notifications_get' );\nadd_action( 'wp_ajax_nopriv_genosys_account_notifications_get', 'genosys_account_notifications_get' );\n\n/** The write touches one key only; concurrent switches cannot overwrite one another. */\nfunction genosys_account_notifications_save() {\n\t$user_id = genosys_account_dashboard_authorize( array( 'preference', 'enabled' ) );\n\t$key = isset( $_POST['preference'] ) && is_string( $_POST['preference'] ) ? wp_unslash( $_POST['preference'] ) : '';\n\t$value = isset( $_POST['enabled'] ) && is_string( $_POST['enabled'] ) ? wp_unslash( $_POST['enabled'] ) : '';\n\tif ( ! in_array( $key, genosys_account_notification_keys(), true ) || ! in_array( $value, array( '1', '0' ), true ) ) { genosys_account_dashboard_error( 'گزینه و وضعیت اعلان معتبر نیست.', 400 ); }\n\t$user = get_userdata( $user_id );\n\tif ( 'newsletter' === $key && '1' === $value && ( ! $user || ! is_email( $user->user_email ) ) ) { genosys_account_dashboard_error( 'برای دریافت خبرنامه ابتدا ایمیل معتبر خود را در اطلاعات حساب ثبت کنید.', 400, 'newsletter' ); }\n\t$lock = genosys_account_notification_lock( 'preference:' . $user_id . ':' . $key );\n\tif ( ! $lock ) { genosys_account_dashboard_error( 'ذخیره این گزینه در حال انجام است. دوباره تلاش کنید.', 409 ); }\n\ttry {\n\t\t$before = genosys_account_notification_preferences( $user_id, true );\n\t\tif ( 'newsletter' === $key && '1' === $value && ( ! $before['newsletter'] || ! get_user_meta( $user_id, 'genosys_newsletter_unsubscribe_key', true ) ) ) {\n\t\t\t$token = bin2hex( random_bytes( 32 ) );\n\t\t\tupdate_user_meta( $user_id, 'genosys_newsletter_unsubscribe_key', $token );\n\t\t\tif ( $token !== get_user_meta( $user_id, 'genosys_newsletter_unsubscribe_key', true ) ) { throw new RuntimeException( 'token_write_failed' ); }\n\t\t}\n\t\tupdate_user_meta( $user_id, 'genosys_notify_' . $key, $value );\n\t\twp_cache_delete( $user_id, 'user_meta' );\n\t\tif ( $value !== get_user_meta( $user_id, 'genosys_notify_' . $key, true ) ) { throw new RuntimeException( 'preference_write_failed' ); }\n\t\t$preferences = genosys_account_notification_preferences( $user_id );\n\t} catch ( Throwable $error ) {\n\t\tgenosys_account_notification_unlock( $lock );\n\t\tgenosys_account_dashboard_error( 'ذخیره تنظیمات انجام نشد. دوباره تلاش کنید.', 500 );\n\t}\n\tgenosys_account_notification_unlock( $lock );\n\twp_send_json_success( array( 'preferences' => $preferences, 'preference' => $key, 'enabled' => '1' === $value, 'message' => 'تنظیمات اعلان‌ها ذخیره شد.' ) );\n}\nadd_action( 'wp_ajax_genosys_account_notifications_save', 'genosys_account_notifications_save' );\nadd_action( 'wp_ajax_nopriv_genosys_account_notifications_save', 'genosys_account_notifications_save' );\n\n/** Only an account's verified login phone can connect a guest message to its preferences. */\nfunction genosys_account_notification_phone_user( $phone ) {\n\t$phone = genosys_sms_normalize_phone( $phone );\n\tif ( ! $phone ) { return 0; }\n\t$ids = get_users( array( 'meta_key' => 'genosys_phone', 'meta_value' => $phone, 'number' => 2, 'fields' => 'ID', 'count_total' => false ) );\n\treturn count( $ids ) > 1 ? -1 : ( 1 === count( $ids ) ? (int) $ids[0] : 0 );\n}\n\nfunction genosys_account_notification_order_allowed( $order, $key, $phone = '' ) {\n\tif ( ! in_array( $key, array( 'order_status_sms', 'payment_sms' ), true ) || ! $order instanceof WC_Order ) { return false; }\n\t$user_id = (int) $order->get_customer_id();\n\t$recipient_id = genosys_account_notification_phone_user( $phone ?: $order->get_billing_phone() );\n\tif ( $recipient_id < 0 ) { return false; }\n\tforeach ( array_unique( array_filter( array( $user_id, $recipient_id ) ) ) as $account_id ) {\n\t\tif ( get_userdata( $account_id ) && ! genosys_account_notification_preferences( $account_id, true )[ $key ] ) { return false; }\n\t}\n\treturn true;\n}\n\n/** Account opt-out suppresses promotional sends, without cancelling club membership. */\nfunction genosys_account_notification_club_allowed( $member ) {\n\tif ( ! is_array( $member ) || 'active' !== ( $member['status'] ?? '' ) ) { return false; }\n\t$user_id = (int) ( $member['userId'] ?? 0 );\n\t$consent = ! empty( $member['consent'] );\n\tif ( $user_id > 0 && get_userdata( $user_id ) && ! empty( $member['id'] ) && function_exists( 'genosys_club_member_raw' ) ) {\n\t\t$record = genosys_club_member_raw( (int) $member['id'] );\n\t\t$owned = $record && 'active' === ( $record['status'] ?? '' ) && (int) ( $record['userId'] ?? 0 ) === $user_id && (int) get_post_meta( (int) $member['id'], '_genosys_club_owner_user', true ) === $user_id;\n\t\twp_cache_delete( $user_id, 'user_meta' );\n\t\tif ( $owned && metadata_exists( 'user', $user_id, 'genosys_notify_promotions' ) ) {\n\t\t\t// A later explicit choice by the real owner supersedes the historical signup choice.\n\t\t\t$consent = genosys_account_notification_preferences( $user_id )['promotions'];\n\t\t}\n\t}\n\tif ( ! $consent ) { return false; }\n\t$recipient_id = genosys_account_notification_phone_user( $member['phone'] ?? '' );\n\tif ( $recipient_id < 0 ) { return false; }\n\tforeach ( array_unique( array_filter( array( $user_id, $recipient_id ) ) ) as $account_id ) {\n\t\tif ( get_userdata( $account_id ) && ! genosys_account_notification_preferences( $account_id, true )['promotions'] ) { return false; }\n\t}\n\treturn true;\n}\n\n/** WordPress has no calendar-month recurrence; schedule each next calendar month explicitly. */\nfunction genosys_newsletter_next_month( $from = 0 ) {\n\t$now = new DateTimeImmutable( '@' . ( $from ?: time() ) );\n\treturn $now->setTimezone( wp_timezone() )->modify( 'first day of next month' )->setTime( 10, 0, 0 )->getTimestamp();\n}\n\nfunction genosys_newsletter_schedule() {\n\tif ( ! wp_next_scheduled( 'genosys_newsletter_monthly' ) ) { wp_schedule_single_event( genosys_newsletter_next_month(), 'genosys_newsletter_monthly' ); }\n}\nadd_action( 'init', 'genosys_newsletter_schedule' );\n\nfunction genosys_newsletter_stop() {\n\twp_clear_scheduled_hook( 'genosys_newsletter_monthly' );\n\t// Completed/in-progress issue records contain no subscriber addresses.\n\t$events = _get_cron_array();\n\tforeach ( is_array( $events ) ? $events : array() as $hooks ) {\n\t\tforeach ( $hooks['genosys_newsletter_batch'] ?? array() as $event ) { wp_clear_scheduled_hook( 'genosys_newsletter_batch', $event['args'] ); }\n\t}\n}\nadd_action( 'switch_theme', 'genosys_newsletter_stop' );\n\n/** Snapshot only public, readable editorial content and normal catalog products. */\nfunction genosys_newsletter_content_ids( $cutoff ) {\n\t$result = array();\n\tforeach ( array( 'post', 'product' ) as $type ) {\n\t\t$args = array( 'post_type' => $type, 'post_status' => 'publish', 'posts_per_page' => 6, 'fields' => 'ids', 'no_found_rows' => true, 'has_password' => false, 'orderby' => 'date', 'order' => 'DESC', 'date_query' => array( array( 'before' => gmdate( 'Y-m-d H:i:s', $cutoff ), 'column' => 'post_date_gmt', 'inclusive' => true ) ) );\n\t\tif ( 'product' === $type && taxonomy_exists( 'product_type' ) ) { $args['tax_query'] = array( array( 'taxonomy' => 'product_type', 'field' => 'slug', 'terms' => array( 'genosys_package' ), 'operator' => 'NOT IN' ) ); }\n\t\tforeach ( get_posts( $args ) as $id ) {\n\t\t\tif ( 'product' === $type ) { $product = function_exists( 'wc_get_product' ) ? wc_get_product( $id ) : false; if ( ! $product || ! in_array( $product->get_catalog_visibility(), array( 'visible', 'catalog' ), true ) ) { continue; } }\n\t\t\t$result[ $type ][] = (int) $id;\n\t\t\tif ( count( $result[ $type ] ) >= 3 ) { break; }\n\t\t}\n\t}\n\treturn $result;\n}\n\nfunction genosys_newsletter_monthly() {\n\tgenosys_newsletter_schedule();\n\t$issue = ( new DateTimeImmutable( 'now', wp_timezone() ) )->format( 'Y-m' );\n\t$lock = genosys_account_notification_lock( 'newsletter-issue:' . $issue );\n\tif ( ! $lock ) { return; }\n\tglobal $wpdb;\n\t$key = 'genosys_newsletter_issue_' . str_replace( '-', '_', $issue );\n\ttry {\n\t\t$state = get_option( $key );\n\t\tif ( ! is_array( $state ) ) {\n\t\t\t$state = array( 'issue' => $issue, 'cursor' => 0, 'maximum' => (int) $wpdb->get_var( \"SELECT MAX(ID) FROM {$wpdb->users}\" ), 'content' => genosys_newsletter_content_ids( time() ), 'created' => time(), 'complete' => false );\n\t\t\tif ( ! add_option( $key, $state, '', false ) && ! is_array( get_option( $key ) ) ) { throw new RuntimeException( 'issue_write_failed' ); }\n\t\t}\n\t\tif ( empty( $state['complete'] ) && ! wp_next_scheduled( 'genosys_newsletter_batch', array( $issue ) ) ) { wp_schedule_single_event( time() + 10, 'genosys_newsletter_batch', array( $issue ) ); }\n\t} catch ( Throwable $issue_error ) {\n\t\twp_schedule_single_event( time() + 300, 'genosys_newsletter_monthly' );\n\t} finally { genosys_account_notification_unlock( $lock ); }\n}\nadd_action( 'genosys_newsletter_monthly', 'genosys_newsletter_monthly' );\n\nfunction genosys_newsletter_unsubscribe_url( $user_id ) {\n\t$token = get_user_meta( $user_id, 'genosys_newsletter_unsubscribe_key', true );\n\tif ( ! is_string( $token ) || ! preg_match( '/^[a-f0-9]{64}$/D', $token ) ) { return ''; }\n\treturn add_query_arg( array( 'action' => 'genosys_newsletter_unsubscribe', 'subscriber' => (int) $user_id, 'token' => $token ), admin_url( 'admin-post.php' ) );\n}\n\nfunction genosys_newsletter_message( $user, $state, $unsubscribe ) {\n\t$preferences = add_query_arg( 'ga_tab', 'notifications', function_exists( 'wc_get_page_permalink' ) ? wc_get_page_permalink( 'myaccount' ) : home_url( '/my-account/' ) );\n\t$html = '<!doctype html><html lang=\"fa\" dir=\"rtl\"><head><meta charset=\"utf-8\"></head><body style=\"margin:0;background:#f7f5f5;font-family:Tahoma,Arial,sans-serif;color:#242126\"><div style=\"max-width:640px;margin:28px auto;padding:32px;background:white;border-radius:24px\"><h1 style=\"color:#bf0b30;font-size:24px\">' . esc_html( 'خبرنامه ماهانه ' . get_bloginfo( 'name' ) ) . '</h1><p>' . esc_html( trim( $user->first_name . ' ' . $user->last_name ) ?: $user->display_name ) . ' عزیز، سلام</p><p>تازه‌های ژنوسیس را در این ماه ببینید.</p>';\n\tforeach ( array( 'post' => 'تازه‌های مجله', 'product' => 'جدیدترین محصولات' ) as $type => $title ) {\n\t\t$items = '';\n\t\tforeach ( $state['content'][ $type ] ?? array() as $id ) {\n\t\t\t$post = get_post( $id );\n\t\t\tif ( ! $post || 'publish' !== $post->post_status || $post->post_password || $type !== $post->post_type ) { continue; }\n\t\t\tif ( 'product' === $type ) { $product = function_exists( 'wc_get_product' ) ? wc_get_product( $id ) : false; if ( ! $product || ! in_array( $product->get_catalog_visibility(), array( 'visible', 'catalog' ), true ) || $product->is_type( 'genosys_package' ) ) { continue; } }\n\t\t\t$items .= '<li style=\"margin:12px 0\"><a style=\"color:#bf0b30\" href=\"' . esc_url( get_permalink( $id ) ) . '\">' . esc_html( get_the_title( $id ) ) . '</a></li>';\n\t\t}\n\t\tif ( $items ) { $html .= '<h2 style=\"font-size:18px\">' . esc_html( $title ) . '</h2><ul>' . $items . '</ul>'; }\n\t}\n\t$html .= '<p><a href=\"' . esc_url( home_url( '/' ) ) . '\">مشاهده وب‌سایت</a></p><hr style=\"border:0;border-top:1px solid #eee\"><p style=\"font-size:12px;color:#777\">این خبرنامه با انتخاب شما در تنظیمات حساب ارسال شده است.</p><p><a href=\"' . esc_url( $preferences ) . '\">تنظیمات اعلان‌ها</a> · <a href=\"' . esc_url( $unsubscribe ) . '\">لغو اشتراک خبرنامه</a></p></div></body></html>';\n\treturn $html;\n}\n\n/** At most twenty-five recipients per request, with fresh consent before each handoff. */\nfunction genosys_newsletter_batch( $issue ) {\n\tif ( ! is_string( $issue ) || ! preg_match( '/^[0-9]{4}-(0[1-9]|1[0-2])$/D', $issue ) ) { return; }\n\t$lock = genosys_account_notification_lock( 'newsletter-issue:' . $issue, 600 );\n\tif ( ! $lock ) { return; }\n\tglobal $wpdb;\n\t$key = 'genosys_newsletter_issue_' . str_replace( '-', '_', $issue );\n\t$again = false;\n\ttry {\n\t\t$state = get_option( $key );\n\t\tif ( ! is_array( $state ) || ! empty( $state['complete'] ) ) { return; }\n\t\t$again = true;\n\t\t$ids = $wpdb->get_col( $wpdb->prepare( \"SELECT DISTINCT u.ID FROM {$wpdb->users} u INNER JOIN {$wpdb->usermeta} m ON m.user_id = u.ID WHERE m.meta_key = %s AND m.meta_value = '1' AND u.ID > %d AND u.ID <= %d ORDER BY u.ID ASC LIMIT 25\", 'genosys_notify_newsletter', (int) $state['cursor'], (int) $state['maximum'] ) );\n\t\tif ( $wpdb->last_error ) { throw new RuntimeException( 'subscriber_query_failed' ); }\n\t\tforeach ( $ids as $id ) {\n\t\t\t$id = (int) $id;\n\t\t\t$user_lock = genosys_account_notification_lock( 'preference:' . $id . ':newsletter' );\n\t\t\tif ( ! $user_lock ) { break; }\n\t\t\ttry {\n\t\t\t\t$user = get_userdata( $id );\n\t\t\t\t$unsubscribe = genosys_newsletter_unsubscribe_url( $id );\n\t\t\t\t$attempt = get_user_meta( $id, 'genosys_newsletter_last_attempt', true );\n\t\t\t\tif ( $user && is_email( $user->user_email ) && $unsubscribe && genosys_account_notification_preferences( $id, true )['newsletter'] && ( ! is_array( $attempt ) || strcmp( (string) ( $attempt['issue'] ?? '' ), $issue ) < 0 ) ) {\n\t\t\t\t\t$claim = array( 'issue' => $issue, 'timestamp' => time(), 'status' => 'attempting' );\n\t\t\t\t\tupdate_user_meta( $id, 'genosys_newsletter_last_attempt', $claim );\n\t\t\t\t\tif ( $claim !== get_user_meta( $id, 'genosys_newsletter_last_attempt', true ) ) { throw new RuntimeException( 'mail_claim_failed' ); }\n\t\t\t\t\t$headers = array( 'Content-Type: text/html; charset=UTF-8', 'List-Unsubscribe: <' . $unsubscribe . '>', 'List-Unsubscribe-Post: List-Unsubscribe=One-Click' );\n\t\t\t\t\ttry {\n\t\t\t\t\t\t$accepted = wp_mail( $user->user_email, 'خبرنامه ماهانه ' . wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ), genosys_newsletter_message( $user, $state, $unsubscribe ), $headers );\n\t\t\t\t\t\t$claim['status'] = $accepted ? 'accepted' : 'failed';\n\t\t\t\t\t} catch ( Throwable $mail_error ) { $claim['status'] = 'unconfirmed'; }\n\t\t\t\t\tupdate_user_meta( $id, 'genosys_newsletter_last_attempt', $claim );\n\t\t\t\t}\n\t\t\t\t$state['cursor'] = $id;\n\t\t\t\tupdate_option( $key, $state, false );\n\t\t\t} finally { genosys_account_notification_unlock( $user_lock ); }\n\t\t}\n\t\t$state['complete'] = count( $ids ) < 25 && ( ! $ids || (int) end( $ids ) === (int) $state['cursor'] );\n\t\tupdate_option( $key, $state, false );\n\t\t$again = ! $state['complete'];\n\t} catch ( Throwable $batch_error ) {\n\t\tif ( function_exists( 'wc_get_logger' ) ) { wc_get_logger()->warning( 'Monthly newsletter batch will resume.', array( 'source' => 'genosys-newsletter', 'issue' => $issue ) ); }\n\t} finally {\n\t\tgenosys_account_notification_unlock( $lock );\n\t\tif ( $again && ! wp_next_scheduled( 'genosys_newsletter_batch', array( $issue ) ) ) { wp_schedule_single_event( time() + 60, 'genosys_newsletter_batch', array( $issue ) ); }\n\t}\n}\nadd_action( 'genosys_newsletter_batch', 'genosys_newsletter_batch' );\n\n/** Email scanners can view the confirmation safely; only an explicit POST unsubscribes. */\nfunction genosys_newsletter_unsubscribe() {\n\tnocache_headers();\n\t$source = 'POST' === ( $_SERVER['REQUEST_METHOD'] ?? '' ) ? array_merge( $_GET, $_POST ) : $_GET;\n\t$id = isset( $source['subscriber'] ) && is_string( $source['subscriber'] ) && preg_match( '/^[1-9][0-9]*$/D', $source['subscriber'] ) ? (int) $source['subscriber'] : 0;\n\t$token = isset( $source['token'] ) && is_string( $source['token'] ) ? wp_unslash( $source['token'] ) : '';\n\t$stored = $id ? get_user_meta( $id, 'genosys_newsletter_unsubscribe_key', true ) : '';\n\tif ( ! $id || ! preg_match( '/^[a-f0-9]{64}$/D', $token ) || ! is_string( $stored ) || ! hash_equals( $stored, $token ) ) { wp_die( 'پیوند لغو اشتراک معتبر نیست.', '', array( 'response' => 400 ) ); }\n\tif ( 'POST' === ( $_SERVER['REQUEST_METHOD'] ?? '' ) ) {\n\t\t$lock = genosys_account_notification_lock( 'preference:' . $id . ':newsletter' );\n\t\tif ( ! $lock ) { wp_die( 'درخواست دیگری در حال انجام است. دوباره تلاش کنید.', '', array( 'response' => 409 ) ); }\n\t\twp_cache_delete( $id, 'user_meta' );\n\t\t$fresh_token = get_user_meta( $id, 'genosys_newsletter_unsubscribe_key', true );\n\t\tif ( ! is_string( $fresh_token ) || ! hash_equals( $fresh_token, $token ) ) { genosys_account_notification_unlock( $lock ); wp_die( 'پیوند لغو اشتراک معتبر نیست.', '', array( 'response' => 400 ) ); }\n\t\tupdate_user_meta( $id, 'genosys_notify_newsletter', '0' );\n\t\t$success = '0' === get_user_meta( $id, 'genosys_notify_newsletter', true );\n\t\tgenosys_account_notification_unlock( $lock );\n\t\twp_die( $success ? 'اشتراک خبرنامه شما لغو شد.' : 'لغو اشتراک انجام نشد. دوباره تلاش کنید.', '', array( 'response' => $success ? 200 : 500 ) );\n\t}\n\t$action = admin_url( 'admin-post.php' );\n\t$html = '<div dir=\"rtl\"><h1>لغو اشتراک خبرنامه</h1><p>برای توقف خبرنامه‌های ماهانه، دکمه زیر را انتخاب کنید.</p><form method=\"post\" action=\"' . esc_url( $action ) . '\"><input type=\"hidden\" name=\"action\" value=\"genosys_newsletter_unsubscribe\"><input type=\"hidden\" name=\"subscriber\" value=\"' . esc_attr( $id ) . '\"><input type=\"hidden\" name=\"token\" value=\"' . esc_attr( $token ) . '\"><button type=\"submit\">لغو اشتراک</button></form></div>';\n\twp_die( $html, 'لغو اشتراک خبرنامه', array( 'response' => 200 ) );\n}\nadd_action( 'admin_post_genosys_newsletter_unsubscribe', 'genosys_newsletter_unsubscribe' );\nadd_action( 'admin_post_nopriv_genosys_newsletter_unsubscribe', 'genosys_newsletter_unsubscribe' );\n","sha256":"9a77deb4af46314b079dc2e03907da1ca49fddfb5ea6da131d0d7880c5664069"},"inc/account-phone-change.php":{"content":"<?php\n/** Session-bound verification changes the current customer's credential, never their identity. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_account_phone_binding( $user_id ) {\n\t$session = wp_get_session_token();\n\treturn $session ? hash_hmac( 'sha256', 'account-phone-change:' . (int) $user_id . ':' . $session, wp_salt( 'auth' ) ) : '';\n}\n\nfunction genosys_account_phone_error( $code, $message, $status = 400, $extra = array() ) {\n\twp_send_json_error( array_merge( array( 'code' => $code, 'message' => $message, 'serverTime' => time() ), $extra ), $status );\n}\n\n/** Separate purpose, strict fields, and a current authenticated WordPress session. */\nfunction genosys_account_phone_authorize( $fields ) {\n\tnocache_headers();\n\tif ( 'POST' !== ( $_SERVER['REQUEST_METHOD'] ?? '' ) ) { genosys_account_phone_error( 'invalid_method', 'روش درخواست معتبر نیست.', 405 ); }\n\tif ( ! is_user_logged_in() ) { genosys_account_phone_error( 'signed_out', 'برای تغییر شماره وارد حساب شوید.', 401 ); }\n\t$nonce = isset( $_POST['nonce'] ) && is_string( $_POST['nonce'] ) ? wp_unslash( $_POST['nonce'] ) : '';\n\tif ( ! wp_verify_nonce( $nonce, 'genosys_account_dashboard' ) ) { genosys_account_phone_error( 'invalid_request', 'اعتبار درخواست منقضی شده است. صفحه را تازه کنید.', 403 ); }\n\tforeach ( $_POST as $key => $value ) {\n\t\tif ( ! is_string( $value ) || ! in_array( $key, array_merge( array( 'action', 'nonce' ), $fields ), true ) ) { genosys_account_phone_error( 'invalid_request', 'اطلاعات درخواست معتبر نیست.' ); }\n\t}\n\tif ( ! genosys_account_phone_binding( get_current_user_id() ) ) { genosys_account_phone_error( 'session_mismatch', 'دوباره وارد حساب شوید.', 403 ); }\n\treturn get_current_user_id();\n}\n\nfunction genosys_account_phone_value( $key ) {\n\treturn isset( $_POST[ $key ] ) && is_string( $_POST[ $key ] ) ? wp_unslash( $_POST[ $key ] ) : '';\n}\n\nfunction genosys_account_phone_challenge_key( $token ) {\n\treturn 'genosys_account_phone_challenge_' . $token;\n}\n\nfunction genosys_account_phone_read( $token, $user_id ) {\n\tif ( ! is_string( $token ) || ! preg_match( '/^[a-f0-9]{64}$/D', $token ) ) { return new WP_Error( 'expired_code', 'کد جدید دریافت کنید.' ); }\n\t$record = get_transient( genosys_account_phone_challenge_key( $token ) );\n\tif ( ! is_array( $record ) || 'account-phone-change' !== ( $record['purpose'] ?? '' ) || (int) ( $record['userId'] ?? 0 ) !== (int) $user_id || ! isset( $record['binding'] ) || ! is_string( $record['binding'] ) || ! hash_equals( $record['binding'], genosys_account_phone_binding( $user_id ) ) ) { return new WP_Error( 'session_mismatch', 'درخواست به این نشست حساب تعلق ندارد. کد جدید دریافت کنید.' ); }\n\tif ( $token !== get_transient( 'genosys_account_phone_active_' . $user_id ) ) { return new WP_Error( 'expired_code', 'این کد دیگر فعال نیست. کد جدید دریافت کنید.' ); }\n\twp_cache_delete( $user_id, 'user_meta' );\n\t$old = genosys_sms_normalize_phone( (string) get_user_meta( $user_id, 'genosys_phone', true ) );\n\tif ( $old !== ( $record['oldPhone'] ?? null ) ) { return new WP_Error( 'expired_code', 'شماره حساب تغییر کرده است. کد جدید دریافت کنید.' ); }\n\treturn $record;\n}\n\nfunction genosys_account_phone_deadlines( $token, $record ) {\n\treturn array( 'challengeId' => $token, 'phone' => $record['phone'], 'expiresAt' => (int) $record['expires'], 'resendAt' => (int) $record['resendAt'], 'serverTime' => time() );\n}\n\nfunction genosys_account_phone_release( $locks ) {\n\tforeach ( array_reverse( $locks ) as $lock ) { delete_option( $lock ); }\n}\n\n/** Existing login limits are shared; account limits also cover switching target numbers. */\nfunction genosys_account_phone_rate( $user_id, $phone ) {\n\t$wait = genosys_sms_rate_error( $phone );\n\tforeach ( array( 'hour' => 5, 'day' => 10 ) as $window => $limit ) {\n\t\t$counter = genosys_sms_counter( 'genosys_account_phone_' . $window . '_' . genosys_sms_fingerprint( (string) $user_id ) );\n\t\tif ( $counter['count'] >= $limit ) { $wait = max( $wait, $counter['reset'] - time() ); }\n\t}\n\t$cooldown = (int) get_transient( 'genosys_account_phone_cool_' . $user_id );\n\treturn max( 0, $wait, $cooldown - time() );\n}\n\nfunction genosys_account_phone_send( $resend = false ) {\n\t$user_id = genosys_account_phone_authorize( $resend ? array( 'challengeId' ) : array( 'phone' ) );\n\t$user_lock = genosys_account_notification_lock( 'phone-change-user:' . $user_id, 600 );\n\tif ( ! $user_lock ) { genosys_account_phone_error( 'busy', 'درخواست دیگری در حال انجام است. کمی بعد تلاش کنید.', 429, array( 'retry_after' => 5 ) ); }\n\t$locks = array();\n\t$error = null;\n\t$response = null;\n\ttry {\n\t\tif ( $resend ) {\n\t\t\t$record = genosys_account_phone_read( genosys_account_phone_value( 'challengeId' ), $user_id );\n\t\t\tif ( is_wp_error( $record ) ) { throw new RuntimeException( $record->get_error_code() ); }\n\t\t\t$phone = $record['phone'];\n\t\t} else {\n\t\t\t$raw = genosys_account_dashboard_digits_ascii( genosys_account_phone_value( 'phone' ) );\n\t\t\tif ( strlen( $raw ) > 24 || preg_match( '/[^0-9+\\s().-]/u', $raw ) ) { throw new RuntimeException( 'invalid_phone' ); }\n\t\t\t$phone = genosys_sms_normalize_phone( $raw );\n\t\t\tif ( ! $phone ) { throw new RuntimeException( 'invalid_phone' ); }\n\t\t}\n\t\twp_cache_delete( $user_id, 'user_meta' );\n\t\t$old = genosys_sms_normalize_phone( (string) get_user_meta( $user_id, 'genosys_phone', true ) );\n\t\tif ( $phone === $old ) { throw new RuntimeException( 'phone_unchanged' ); }\n\t\tif ( ! genosys_sms_api_key() || ! genosys_sms_template_id() ) { throw new RuntimeException( 'not_configured' ); }\n\t\tforeach ( array( 'ip:' . genosys_sms_client_ip(), 'phone:' . $phone ) as $scope ) {\n\t\t\t$lock = genosys_sms_claim_lock( $scope );\n\t\t\tif ( ! $lock ) { throw new RuntimeException( 'busy' ); }\n\t\t\t$locks[] = $lock;\n\t\t}\n\t\t$retry = genosys_account_phone_rate( $user_id, $phone );\n\t\tif ( $retry ) { $error = array( 'code' => 'rate_limited', 'retry_after' => $retry ); throw new RuntimeException( 'rate_limited' ); }\n\t\t$existing = genosys_sms_find_existing_user( $phone );\n\t\tif ( is_wp_error( $existing ) || ( $existing && (int) $existing->ID !== (int) $user_id ) ) { throw new RuntimeException( 'phone_in_use' ); }\n\t\t// Charge attempts before the provider call, including provider rejection/timeouts.\n\t\t$resend_at = time() + 120;\n\t\tset_transient( 'genosys_account_phone_cool_' . $user_id, $resend_at, 120 );\n\t\tset_transient( 'genosys_sms_cool_' . genosys_sms_fingerprint( $phone ), $resend_at, 120 );\n\t\t$counter_windows = array( 'genosys_sms_day_' . genosys_sms_fingerprint( $phone ) => DAY_IN_SECONDS, 'genosys_sms_hour_' . genosys_sms_fingerprint( genosys_sms_client_ip() ) => HOUR_IN_SECONDS, 'genosys_account_phone_hour_' . genosys_sms_fingerprint( (string) $user_id ) => HOUR_IN_SECONDS, 'genosys_account_phone_day_' . genosys_sms_fingerprint( (string) $user_id ) => DAY_IN_SECONDS );\n\t\tforeach ( $counter_windows as $counter_key => $window ) {\n\t\t\t$before = genosys_sms_counter( $counter_key );\n\t\t\tgenosys_sms_increment_counter( $counter_key, $window );\n\t\t\t$after = genosys_sms_counter( $counter_key );\n\t\t\tif ( $after['count'] < $before['count'] + 1 ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\t}\n\t\tif ( $resend_at !== (int) get_transient( 'genosys_account_phone_cool_' . $user_id ) || $resend_at !== (int) get_transient( 'genosys_sms_cool_' . genosys_sms_fingerprint( $phone ) ) ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\t$token = bin2hex( random_bytes( 32 ) );\n\t\t$code = (string) random_int( 100000, 999999 );\n\t\t$binding = genosys_account_phone_binding( $user_id );\n\t\t$hash = hash_hmac( 'sha256', 'account-phone-change:' . $user_id . ':' . $binding . ':' . $token . ':' . $phone . ':' . $code, wp_salt( 'auth' ) );\n\t\t$sent = genosys_smsir_send_code( $phone, $code );\n\t\tunset( $code );\n\t\tif ( is_wp_error( $sent ) ) { $error = array( 'code' => 'sms_unavailable', 'retry_after' => max( 1, $resend_at - time() ) ); throw new RuntimeException( 'sms_unavailable' ); }\n\t\t$record = array( 'purpose' => 'account-phone-change', 'userId' => (int) $user_id, 'binding' => $binding, 'oldPhone' => $old, 'phone' => $phone, 'hash' => $hash, 'expires' => time() + 120, 'resendAt' => $resend_at, 'attempts' => 0, 'consumed' => false );\n\t\tif ( ! set_transient( genosys_account_phone_challenge_key( $token ), $record, 900 ) || ! set_transient( 'genosys_account_phone_active_' . $user_id, $token, 900 ) ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\t$response = genosys_account_phone_deadlines( $token, $record );\n\t\t$response['message'] = 'کد تأیید به شماره جدید ارسال شد.';\n\t} catch ( Throwable $exception ) {\n\t\tif ( ! $error ) { $error = array( 'code' => $exception->getMessage() ); }\n\t} finally {\n\t\tgenosys_account_phone_release( $locks );\n\t\tgenosys_account_notification_unlock( $user_lock );\n\t}\n\tif ( $error ) { genosys_account_phone_fail( $error ); }\n\twp_send_json_success( $response );\n}\n\nfunction genosys_account_phone_fail( $error ) {\n\t$messages = array(\n\t\t'invalid_phone' => array( 'شماره موبایل معتبر وارد کنید.', 400, 'phone' ),\n\t\t'phone_unchanged' => array( 'شماره جدید با شماره فعلی یکسان است.', 400, 'phone' ),\n\t\t'phone_in_use' => array( 'این شماره قابل اتصال به حساب شما نیست. شماره دیگری انتخاب کنید.', 409, 'phone' ),\n\t\t'busy' => array( 'درخواست دیگری در حال انجام است. کمی بعد دوباره تلاش کنید.', 429, '' ),\n\t\t'rate_limited' => array( 'برای دریافت کد بعدی کمی صبر کنید.', 429, '' ),\n\t\t'session_mismatch' => array( 'این درخواست به نشست فعلی تعلق ندارد. کد جدید دریافت کنید.', 403, '' ),\n\t\t'expired_code' => array( 'اعتبار کد تمام شده است. کد جدید دریافت کنید.', 400, 'code' ),\n\t\t'invalid_code' => array( 'کد واردشده صحیح نیست.', 400, 'code' ),\n\t\t'attempts_exhausted' => array( 'تعداد تلاش‌ها تمام شد. کد جدید دریافت کنید.', 400, 'code' ),\n\t\t'not_configured' => array( 'ارسال کد در حال حاضر در دسترس نیست.', 503, '' ),\n\t\t'sms_unavailable' => array( 'ارسال کد انجام نشد. کمی بعد دوباره تلاش کنید.', 503, '' ),\n\t\t'storage_unavailable' => array( 'ذخیره درخواست انجام نشد. دوباره کد دریافت کنید.', 503, '' ),\n\t);\n\t$code = isset( $messages[ $error['code'] ?? '' ] ) ? $error['code'] : 'storage_unavailable';\n\t$item = $messages[ $code ];\n\tunset( $error['code'] );\n\tif ( $item[2] ) { $error['field'] = $item[2]; }\n\tif ( 'busy' === $code && ! isset( $error['retry_after'] ) ) { $error['retry_after'] = 5; }\n\tif ( isset( $error['retry_after'] ) ) { $error['resendAt'] = time() + (int) $error['retry_after']; }\n\tgenosys_account_phone_error( $code, $item[0], $item[1], $error );\n}\n\nfunction genosys_account_phone_request() { genosys_account_phone_send( false ); }\nfunction genosys_account_phone_resend() { genosys_account_phone_send( true ); }\nadd_action( 'wp_ajax_genosys_account_phone_request', 'genosys_account_phone_request' );\nadd_action( 'wp_ajax_nopriv_genosys_account_phone_request', 'genosys_account_phone_request' );\nadd_action( 'wp_ajax_genosys_account_phone_resend', 'genosys_account_phone_resend' );\nadd_action( 'wp_ajax_nopriv_genosys_account_phone_resend', 'genosys_account_phone_resend' );\n\nfunction genosys_account_phone_order_proof( $order ) {\n\treturn hash_hmac( 'sha256', 'account-phone-order:' . get_current_user_id() . ':' . $order->get_id() . ':' . $order->get_order_key(), wp_salt( 'auth' ) );\n}\n\n/** Exact historical guest orders only; an old number never becomes a lasting wildcard. */\nfunction genosys_account_phone_guest_snapshot( $old_phone ) {\n\tglobal $wpdb;\n\t$grants = array();\n\tif ( ! $old_phone ) { return $grants; }\n\tif ( ! function_exists( 'wc_get_orders' ) ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t$batch = 1;\n\tdo {\n\t\t$orders = wc_get_orders( array( 'type' => 'shop_order', 'customer_id' => 0, 'limit' => 200, 'page' => $batch, 'orderby' => 'ID', 'order' => 'ASC', 'return' => 'objects' ) );\n\t\tif ( ! is_array( $orders ) || $wpdb->last_error ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\tforeach ( $orders as $order ) {\n\t\t\tif ( genosys_order_access_valid_order( $order ) && 0 === (int) $order->get_customer_id() && $old_phone === genosys_sms_normalize_phone( $order->get_billing_phone() ) && genosys_order_access_can_view( $order ) && $order->get_order_key() ) { $grants[ $order->get_id() ] = genosys_account_phone_order_proof( $order ); }\n\t\t}\n\t\t$batch++;\n\t} while ( 200 === count( $orders ) );\n\treturn $grants;\n}\n\nfunction genosys_account_phone_historical_order_allowed( $order ) {\n\tif ( ! is_user_logged_in() || ! genosys_order_access_valid_order( $order ) || 0 !== (int) $order->get_customer_id() || ! $order->get_order_key() ) { return false; }\n\t$grants = get_user_meta( get_current_user_id(), 'genosys_account_guest_order_grants', true );\n\t$proof = is_array( $grants ) ? ( $grants[ $order->get_id() ] ?? '' ) : '';\n\treturn is_string( $proof ) && preg_match( '/^[a-f0-9]{64}$/D', $proof ) && hash_equals( $proof, genosys_account_phone_order_proof( $order ) );\n}\n\nfunction genosys_account_phone_historical_order_ids() {\n\tif ( ! is_user_logged_in() ) { return array(); }\n\t$grants = get_user_meta( get_current_user_id(), 'genosys_account_guest_order_grants', true );\n\t$ids = array();\n\tforeach ( is_array( $grants ) ? $grants : array() as $id => $proof ) {\n\t\tif ( preg_match( '/^[1-9][0-9]*$/D', (string) $id ) && is_string( $proof ) && preg_match( '/^[a-f0-9]{64}$/D', $proof ) ) { $ids[] = (int) $id; }\n\t}\n\treturn $ids;\n}\n\nfunction genosys_account_phone_verify() {\n\t$user_id = genosys_account_phone_authorize( array( 'challengeId', 'code' ) );\n\t$token = genosys_account_phone_value( 'challengeId' );\n\t$code = genosys_account_dashboard_digits_ascii( genosys_account_phone_value( 'code' ) );\n\tif ( ! preg_match( '/^[0-9]{6}$/D', $code ) ) { genosys_account_phone_fail( array( 'code' => 'invalid_code' ) ); }\n\t$user_lock = genosys_account_notification_lock( 'phone-change-user:' . $user_id, 600 );\n\tif ( ! $user_lock ) { genosys_account_phone_fail( array( 'code' => 'busy' ) ); }\n\t$locks = array(); $error = null; $changed = false; $transaction = false;\n\tglobal $wpdb;\n\ttry {\n\t\t$record = genosys_account_phone_read( $token, $user_id );\n\t\tif ( is_wp_error( $record ) ) { throw new RuntimeException( $record->get_error_code() ); }\n\t\tif ( ! empty( $record['consumed'] ) || (int) $record['expires'] <= time() ) { throw new RuntimeException( 'expired_code' ); }\n\t\tif ( (int) $record['attempts'] >= 5 ) { throw new RuntimeException( 'attempts_exhausted' ); }\n\t\t$hash = hash_hmac( 'sha256', 'account-phone-change:' . $user_id . ':' . $record['binding'] . ':' . $token . ':' . $record['phone'] . ':' . $code, wp_salt( 'auth' ) );\n\t\tunset( $code );\n\t\tif ( ! hash_equals( $record['hash'], $hash ) ) {\n\t\t\t$record['attempts']++;\n\t\t\tif ( ! set_transient( genosys_account_phone_challenge_key( $token ), $record, 900 ) ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\t\t$error = genosys_account_phone_deadlines( $token, $record );\n\t\t\t$error['code'] = $record['attempts'] >= 5 ? 'attempts_exhausted' : 'invalid_code';\n\t\t\tthrow new RuntimeException( $error['code'] );\n\t\t}\n\t\t// A full scan is outside the shared 25-second phone locks and has no 50-order browser cap.\n\t\t$grants = genosys_account_phone_guest_snapshot( $record['oldPhone'] );\n\t\t$phones = array_unique( array_filter( array( $record['oldPhone'], $record['phone'] ) ) ); sort( $phones, SORT_STRING );\n\t\tforeach ( $phones as $phone ) {\n\t\t\t$lock = genosys_sms_claim_lock( 'phone:' . $phone );\n\t\t\tif ( ! $lock ) { throw new RuntimeException( 'busy' ); }\n\t\t\t$locks[] = $lock;\n\t\t}\n\t\twp_cache_delete( $user_id, 'user_meta' );\n\t\tif ( $record['oldPhone'] !== genosys_sms_normalize_phone( (string) get_user_meta( $user_id, 'genosys_phone', true ) ) ) { throw new RuntimeException( 'expired_code' ); }\n\t\t$existing = genosys_sms_find_existing_user( $record['phone'] );\n\t\tif ( is_wp_error( $existing ) || ( $existing && (int) $existing->ID !== (int) $user_id ) ) { throw new RuntimeException( 'phone_in_use' ); }\n\t\t$table = $wpdb->get_row( $wpdb->prepare( 'SHOW TABLE STATUS LIKE %s', $wpdb->esc_like( $wpdb->usermeta ) ), ARRAY_A );\n\t\tif ( ! is_array( $table ) || 'innodb' !== strtolower( (string) ( $table['Engine'] ?? '' ) ) ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\tif ( (int) $record['expires'] <= time() ) { throw new RuntimeException( 'expired_code' ); }\n\t\t$record['consumed'] = true;\n\t\tif ( ! set_transient( genosys_account_phone_challenge_key( $token ), $record, 900 ) ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\tif ( false === $wpdb->query( 'START TRANSACTION' ) ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\t$transaction = true;\n\t\t$stored = get_user_meta( $user_id, 'genosys_account_guest_order_grants', true );\n\t\t$all_grants = array_replace( is_array( $stored ) ? $stored : array(), $grants );\n\t\tupdate_user_meta( $user_id, 'genosys_account_guest_order_grants', $all_grants );\n\t\tupdate_user_meta( $user_id, 'genosys_phone', $record['phone'] );\n\t\t$billing = (string) get_user_meta( $user_id, 'billing_phone', true );\n\t\t$update_billing = '' === trim( $billing ) || ( $record['oldPhone'] && $record['oldPhone'] === genosys_sms_normalize_phone( $billing ) );\n\t\tif ( $update_billing ) { update_user_meta( $user_id, 'billing_phone', $record['phone'] ); }\n\t\t$changed_at = time();\n\t\tupdate_user_meta( $user_id, 'genosys_phone_changed_at', $changed_at );\n\t\twp_cache_delete( $user_id, 'user_meta' );\n\t\tif ( $all_grants !== get_user_meta( $user_id, 'genosys_account_guest_order_grants', true ) || $record['phone'] !== get_user_meta( $user_id, 'genosys_phone', true ) || (string) $changed_at !== (string) get_user_meta( $user_id, 'genosys_phone_changed_at', true ) || ( $update_billing && $record['phone'] !== get_user_meta( $user_id, 'billing_phone', true ) ) ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\t$sessions = WP_Session_Tokens::get_instance( $user_id );\n\t\t$sessions->destroy_others( wp_get_session_token() );\n\t\tif ( ! $sessions->verify( wp_get_session_token() ) || 1 !== count( $sessions->get_all() ) ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\tif ( false === $wpdb->query( 'COMMIT' ) ) { throw new RuntimeException( 'storage_unavailable' ); }\n\t\t$transaction = false; $changed = true;\n\t\tdelete_transient( genosys_account_phone_challenge_key( $token ) );\n\t\tdelete_transient( 'genosys_account_phone_active_' . $user_id );\n\t\t// Already issued login OTPs for either credential cannot bridge the change.\n\t\tforeach ( $phones as $phone ) {\n\t\t\t$active = 'genosys_sms_active_' . genosys_sms_fingerprint( $phone );\n\t\t\t$old_token = get_transient( $active );\n\t\t\tif ( is_string( $old_token ) && preg_match( '/^[a-f0-9]{32}$/D', $old_token ) ) { delete_transient( 'genosys_sms_otp_' . $old_token ); }\n\t\t\tdelete_transient( $active );\n\t\t}\n\t} catch ( Throwable $exception ) {\n\t\tif ( $transaction ) { $wpdb->query( 'ROLLBACK' ); }\n\t\tif ( ! $error ) { $error = array( 'code' => $exception->getMessage() ); }\n\t} finally {\n\t\twp_cache_delete( $user_id, 'user_meta' ); clean_user_cache( $user_id );\n\t\tgenosys_account_phone_release( $locks );\n\t\tgenosys_account_notification_unlock( $user_lock );\n\t}\n\tif ( ! $changed ) { genosys_account_phone_fail( $error ?: array( 'code' => 'storage_unavailable' ) ); }\n\ttry { $context = genosys_account_dashboard_context(); } catch ( Throwable $error ) { $context = array( 'userId' => $user_id, 'phone' => $record['phone'], 'phoneVerified' => true ); }\n\twp_send_json_success( array( 'context' => $context, 'message' => 'شماره موبایل با موفقیت تغییر کرد.' ) );\n}\nadd_action( 'wp_ajax_genosys_account_phone_verify', 'genosys_account_phone_verify' );\nadd_action( 'wp_ajax_nopriv_genosys_account_phone_verify', 'genosys_account_phone_verify' );\n","sha256":"2103675681384381c6a054096cf2b3a986244670d2a95b311e9625f4a70572d4"},"inc/brand.php":{"content":"<?php\n/** Serve the brand story immediately, with or without a saved WordPress Page. */\ndefined( 'ABSPATH' ) || exit;\n\n/** Resolve only playable videos selected from this site's media library. */\nfunction genosys_brand_video_attachment( $id ) {\n\tif ( ! ( is_int( $id ) || is_string( $id ) ) || ! preg_match( '/^[1-9][0-9]*$/D', (string) $id ) ) { return array(); }\n\t$id = (int) $id;\n\tif ( 'attachment' !== get_post_type( $id ) || ! in_array( get_post_status( $id ), array( 'inherit', 'publish' ), true ) ) { return array(); }\n\t$type = get_post_mime_type( $id );\n\tif ( ! in_array( $type, array( 'video/mp4', 'video/webm', 'video/ogg' ), true ) ) { return array(); }\n\t$url = wp_get_attachment_url( $id );\n\tif ( ! is_string( $url ) || ! in_array( strtolower( (string) wp_parse_url( $url, PHP_URL_SCHEME ) ), array( 'http', 'https' ), true ) ) { return array(); }\n\t$url = esc_url_raw( $url, array( 'http', 'https' ) );\n\treturn $url ? array( 'id' => $id, 'url' => $url, 'type' => $type ) : array();\n}\n\nfunction genosys_brand_uploaded_video() {\n\treturn genosys_brand_video_attachment( genosys_site_setting( 'brand_video_id', 0 ) );\n}\n\nfunction genosys_brand_request_path() {\n\tif ( is_admin() || empty( $_SERVER['REQUEST_URI'] ) || ! is_string( $_SERVER['REQUEST_URI'] ) ) { return false; }\n\t$request = wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH );\n\t$brand = wp_parse_url( home_url( '/brand/' ), PHP_URL_PATH );\n\treturn is_string( $request ) && is_string( $brand ) && untrailingslashit( $request ) === untrailingslashit( $brand );\n}\n\nfunction genosys_register_brand_route() {\n\tadd_rewrite_rule( '^brand/?$', 'index.php?genosys_brand=1', 'top' );\n\tif ( '1' !== get_option( 'genosys_brand_route_v1' ) ) {\n\t\tflush_rewrite_rules( false );\n\t\tupdate_option( 'genosys_brand_route_v1', '1', false );\n\t}\n}\nadd_action( 'init', 'genosys_register_brand_route', 20 );\n\nfunction genosys_brand_query_vars( $vars ) {\n\t$vars[] = 'genosys_brand';\n\treturn $vars;\n}\nadd_filter( 'query_vars', 'genosys_brand_query_vars' );\n\n/** Also match the physical URL so plain permalink installations can render it. */\nfunction genosys_brand_parse_request( $wp ) {\n\tif ( ! genosys_brand_request_path() ) { return; }\n\tforeach ( array( 'error', 'p', 'page_id', 'attachment_id', 'name', 'pagename', 's' ) as $key ) { unset( $wp->query_vars[ $key ] ); }\n\t$wp->query_vars['genosys_brand'] = '1';\n}\nadd_action( 'parse_request', 'genosys_brand_parse_request', 99 );\n\nfunction genosys_is_brand() {\n\treturn genosys_brand_request_path() && '1' === (string) get_query_var( 'genosys_brand' );\n}\n\nfunction genosys_brand_main_query( $query ) {\n\tif ( ! $query->is_main_query() || ! genosys_brand_request_path() || '1' !== (string) $query->get( 'genosys_brand' ) ) { return; }\n\t$query->is_home = false;\n\t$query->is_404 = false;\n\t$query->set( 'post__in', array( 0 ) );\n\t$query->set( 'posts_per_page', 1 );\n\t$query->set( 'ignore_sticky_posts', true );\n}\nadd_action( 'parse_query', 'genosys_brand_main_query' );\n\nfunction genosys_brand_pre_handle_404( $preempt, $query ) {\n\tif ( $query->is_main_query() && genosys_brand_request_path() && '1' === (string) $query->get( 'genosys_brand' ) ) {\n\t\t$query->is_404 = false;\n\t\tstatus_header( 200 );\n\t\treturn true;\n\t}\n\treturn $preempt;\n}\nadd_filter( 'pre_handle_404', 'genosys_brand_pre_handle_404', 10, 2 );\n\nfunction genosys_brand_template( $template ) {\n\treturn genosys_is_brand() ? get_theme_file_path( '/page-brand.php' ) : $template;\n}\nadd_filter( 'template_include', 'genosys_brand_template', 99 );\n\nfunction genosys_brand_document_title( $title ) {\n\treturn genosys_is_brand() ? 'برند ژنوسیس | ' . get_bloginfo( 'name' ) : $title;\n}\nadd_filter( 'pre_get_document_title', 'genosys_brand_document_title' );\n\nfunction genosys_brand_canonical_redirect( $redirect ) {\n\treturn genosys_is_brand() ? false : $redirect;\n}\nadd_filter( 'redirect_canonical', 'genosys_brand_canonical_redirect' );\n\nfunction genosys_brand_body_class( $classes ) {\n\tif ( genosys_is_brand() ) { $classes[] = 'genosys-brand-page'; }\n\treturn $classes;\n}\nadd_filter( 'body_class', 'genosys_brand_body_class' );\n","sha256":"2afe06c9b6bf81eb413d2aec1e3327bd58aff598c2de1cc4af997870dbaa54ff"},"inc/cart-animation.php":{"content":"<?php\n/** AJAX bridge for the single-product basket animation, using WooCommerce's form handler. */\n\ndefined( 'ABSPATH' ) || exit;\n\n/**\n * The animation endpoint is processed after wp_loaded. Do not let a native form\n * field accidentally submit the cart once before the endpoint validates it.\n */\nfunction genosys_cart_animation_defer_native_form() {\n\tif ( isset( $_GET['wc-ajax'] ) && is_string( $_GET['wc-ajax'] ) && 'genosys_product_add_to_cart' === wp_unslash( $_GET['wc-ajax'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended\n\t\tremove_action( 'wp_loaded', array( 'WC_Form_Handler', 'add_to_cart_action' ), 20 );\n\t}\n}\nadd_action( 'wp_loaded', 'genosys_cart_animation_defer_native_form', 19 );\n\n/** Keep the usual WooCommerce fragments available to other cart components. */\nfunction genosys_cart_animation_fragments() {\n\tob_start();\n\twoocommerce_mini_cart();\n\t$mini_cart = ob_get_clean();\n\n\treturn apply_filters(\n\t\t'woocommerce_add_to_cart_fragments',\n\t\tarray( 'div.widget_shopping_cart_content' => '<div class=\"widget_shopping_cart_content\">' . $mini_cart . '</div>' )\n\t);\n}\n\n/**\n * Add the exact submitted product; the client animates only confirmed additions.\n * WC AJAX runs after WooCommerce has initialized the customer session and cart.\n */\nfunction genosys_cart_animation_add_to_cart() {\n\tif ( 'POST' !== ( isset( $_SERVER['REQUEST_METHOD'] ) ? $_SERVER['REQUEST_METHOD'] : '' ) ) {\n\t\twp_send_json_error( array( 'message' => 'درخواست نامعتبر است.' ), 405 );\n\t}\n\n\t$nonce = isset( $_POST['security'] ) && is_string( $_POST['security'] ) ? sanitize_text_field( wp_unslash( $_POST['security'] ) ) : '';\n\tif ( ! wp_verify_nonce( $nonce, 'genosys_product_add_to_cart' ) ) {\n\t\twp_send_json_error( array( 'message' => 'این صفحه منقضی شده است. صفحه را تازه کنید و دوباره تلاش کنید.' ), 403 );\n\t}\n\tif ( ! function_exists( 'WC' ) || ! WC()->cart || ! WC()->session || ! class_exists( 'WC_Form_Handler' ) ) {\n\t\twp_send_json_error( array( 'message' => 'سبد خرید در دسترس نیست. صفحه را تازه کنید.' ), 503 );\n\t}\n\n\t$product_id = isset( $_POST['genosys_product_id'] ) && is_scalar( $_POST['genosys_product_id'] ) ? absint( wp_unslash( $_POST['genosys_product_id'] ) ) : 0;\n\t$product    = $product_id ? wc_get_product( $product_id ) : false;\n\tif ( ! $product || ! $product->is_type( array( 'simple', 'variable', 'variation', 'genosys_package' ) ) ) {\n\t\twp_send_json_error( array( 'message' => 'محصول انتخاب‌شده برای این درخواست معتبر نیست.' ), 400 );\n\t}\n\tif ( isset( $_POST['quantity'] ) && ! is_scalar( $_POST['quantity'] ) ) {\n\t\twp_send_json_error( array( 'message' => 'تعداد محصول معتبر نیست.' ), 400 );\n\t}\n\tif ( isset( $_POST['variation_id'] ) && ! is_scalar( $_POST['variation_id'] ) ) {\n\t\twp_send_json_error( array( 'message' => 'گزینه‌های محصول معتبر نیست.' ), 400 );\n\t}\n\tforeach ( $_POST as $key => $value ) {\n\t\tif ( 0 === strpos( $key, 'attribute_' ) && ! is_scalar( $value ) ) {\n\t\t\twp_send_json_error( array( 'message' => 'گزینه‌های محصول معتبر نیست.' ), 400 );\n\t\t}\n\t}\n\n\t$previous_notices = wc_get_notices();\n\twc_clear_notices();\n\t$was_added = false;\n\t$unexpected_error = false;\n\t$track_addition = function () use ( &$was_added ) {\n\t\t$was_added = true;\n\t};\n\t$no_redirect = function () {\n\t\treturn false;\n\t};\n\t$no_cart_redirect = function () {\n\t\treturn 'no';\n\t};\n\t$had_post_id    = array_key_exists( 'add-to-cart', $_POST );\n\t$had_request_id = array_key_exists( 'add-to-cart', $_REQUEST );\n\t$old_post_id    = $had_post_id ? $_POST['add-to-cart'] : null;\n\t$old_request_id = $had_request_id ? $_REQUEST['add-to-cart'] : null;\n\t$_POST['add-to-cart']    = (string) $product_id;\n\t$_REQUEST['add-to-cart'] = (string) $product_id;\n\n\tadd_filter( 'woocommerce_add_to_cart_redirect', $no_redirect, PHP_INT_MAX );\n\tadd_filter( 'pre_option_woocommerce_cart_redirect_after_add', $no_cart_redirect, PHP_INT_MAX );\n\tadd_action( 'woocommerce_add_to_cart', $track_addition, PHP_INT_MAX, 0 );\n\t$buffer_level = ob_get_level();\n\tob_start();\n\ttry {\n\t\t// Preserves Woo's simple/variable validation, attributes, stock and extension hooks.\n\t\tWC_Form_Handler::add_to_cart_action();\n\t\tif ( $was_added && ! wc_notice_count( 'error' ) ) {\n\t\t\tdo_action( 'woocommerce_ajax_added_to_cart', $product_id );\n\t\t}\n\t} catch ( Throwable $error ) {\n\t\t$unexpected_error = true;\n\t\twc_add_notice( 'نتیجه افزودن محصول مشخص نشد. پیش از تلاش دوباره، سبد خرید را بررسی کنید.', 'error' );\n\t} finally {\n\t\twhile ( ob_get_level() > $buffer_level ) {\n\t\t\tob_end_clean();\n\t\t}\n\t\tremove_filter( 'woocommerce_add_to_cart_redirect', $no_redirect, PHP_INT_MAX );\n\t\tremove_filter( 'pre_option_woocommerce_cart_redirect_after_add', $no_cart_redirect, PHP_INT_MAX );\n\t\tremove_action( 'woocommerce_add_to_cart', $track_addition, PHP_INT_MAX );\n\t\tif ( $had_post_id ) {\n\t\t\t$_POST['add-to-cart'] = $old_post_id;\n\t\t} else {\n\t\t\tunset( $_POST['add-to-cart'] );\n\t\t}\n\t\tif ( $had_request_id ) {\n\t\t\t$_REQUEST['add-to-cart'] = $old_request_id;\n\t\t} else {\n\t\t\tunset( $_REQUEST['add-to-cart'] );\n\t\t}\n\t}\n\n\t$errors  = wc_get_notices( 'error' );\n\t$success = $was_added && ! $unexpected_error && empty( $errors );\n\t$message = $success ? 'به سبد خرید اضافه شد' : 'افزودن محصول انجام نشد. گزینه‌ها و تعداد محصول را بررسی کنید.';\n\tif ( ! empty( $errors ) ) {\n\t\t$message = implode( ' ', array_map( function ( $notice ) {\n\t\t\treturn html_entity_decode( wp_strip_all_tags( $notice['notice'] ), ENT_QUOTES, get_bloginfo( 'charset' ) );\n\t\t}, $errors ) );\n\t}\n\t$notices = wc_print_notices( true );\n\t// The current response shows its own notices; preserve notices from earlier requests.\n\twc_set_notices( $previous_notices );\n\t$data = array(\n\t\t'message'    => $message,\n\t\t'notices'    => $notices,\n\t\t'cart_count' => WC()->cart->get_cart_contents_count(),\n\t\t'cart_hash'  => WC()->cart->get_cart_hash(),\n\t\t'cart_url'   => wc_get_cart_url(),\n\t\t'fragments'  => array(),\n\t);\n\tif ( $success ) {\n\t\t// Cart persistence must not be reported as failed because a fragment renderer fails.\n\t\t$buffer_level = ob_get_level();\n\t\ttry {\n\t\t\t$data['fragments'] = genosys_cart_animation_fragments();\n\t\t} catch ( Throwable $error ) {\n\t\t\twhile ( ob_get_level() > $buffer_level ) {\n\t\t\t\tob_end_clean();\n\t\t\t}\n\t\t}\n\t\twp_send_json_success( $data );\n\t}\n\n\twp_send_json_error( $data, $unexpected_error ? 500 : 400 );\n}\nadd_action( 'wc_ajax_genosys_product_add_to_cart', 'genosys_cart_animation_add_to_cart' );\n","sha256":"0746a5891feffbd14e2fcebf2b8088ceddb75a49e1ecd78427fa554a1651eee6"},"inc/checkout-integration.php":{"content":"<?php\n/**\n * WooCommerce data and processing for the Genosys classic checkout.\n *\n * Keep WooCommerce in charge of field validation, shipping selection, coupons,\n * order creation, stock and payment processing. The theme only renders its data.\n *\n * @package Genosys\n */\n\ndefined( 'ABSPATH' ) || exit;\n\n/** Localize digits in HTML text without corrupting tags or entity codes. */\nfunction genosys_checkout_localize_html( $html ) {\n\tif ( ! function_exists( 'genosys_persian_number' ) ) {\n\t\treturn $html;\n\t}\n\t$parts = function_exists( 'wp_html_split' ) ? wp_html_split( $html ) : array( $html );\n\tforeach ( $parts as &$part ) {\n\t\tif ( '' !== $part && '<' !== $part[0] ) {\n\t\t\t$part = esc_html( genosys_persian_number( html_entity_decode( $part, ENT_QUOTES, 'UTF-8' ) ) );\n\t\t}\n\t}\n\treturn implode( '', $parts );\n}\n\n/** A formatted WooCommerce amount with Persian digits in text nodes only. */\nfunction genosys_checkout_price( $amount ) {\n\treturn genosys_checkout_localize_html( wc_price( $amount ) );\n}\n\n/** Render an actual Woo checkout field, retaining its extensions and validation. */\nfunction genosys_checkout_render_field( $checkout, $key, $overrides = array() ) {\n\tif ( ! $checkout || ! method_exists( $checkout, 'get_checkout_fields' ) ) {\n\t\treturn;\n\t}\n\t$field = null;\n\tforeach ( $checkout->get_checkout_fields() as $fields ) {\n\t\tif ( isset( $fields[ $key ] ) ) {\n\t\t\t$field = $fields[ $key ];\n\t\t\tbreak;\n\t\t}\n\t}\n\tif ( ! is_array( $field ) ) {\n\t\treturn;\n\t}\n\t$field = array_merge( $field, $overrides );\n\t$value = $checkout->get_value( $key );\n\tif ( '' === (string) $value && is_user_logged_in() ) {\n\t\tif ( 'billing_first_name' === $key ) {\n\t\t\t$value = (string) get_user_meta( get_current_user_id(), 'first_name', true );\n\t\t} elseif ( 'billing_last_name' === $key ) {\n\t\t\t$value = (string) get_user_meta( get_current_user_id(), 'last_name', true );\n\t\t} elseif ( 'billing_email' === $key ) {\n\t\t\t$value = (string) wp_get_current_user()->user_email;\n\t\t}\n\t}\n\tif ( 'billing_phone' === $key && '' === (string) $value && is_user_logged_in() ) {\n\t\t$value = (string) get_user_meta( get_current_user_id(), 'genosys_phone', true );\n\t}\n\tif ( 'billing_country' === $key && '' === (string) $value ) {\n\t\t$value = WC()->countries->get_base_country();\n\t}\n\twoocommerce_form_field( $key, $field, $value );\n}\n\n/** Do not lose checkout fields inserted by Woo extensions. */\nfunction genosys_checkout_render_extra_fields( $checkout, $fieldset, $exclude = array() ) {\n\tif ( ! $checkout || ! method_exists( $checkout, 'get_checkout_fields' ) ) {\n\t\treturn;\n\t}\n\tforeach ( $checkout->get_checkout_fields( $fieldset ) as $key => $field ) {\n\t\tif ( ! in_array( $key, $exclude, true ) ) {\n\t\t\tgenosys_checkout_render_field( $checkout, $key );\n\t\t}\n\t}\n}\n\n/** Match the visible contact/address requirements without bypassing Woo validation. */\nfunction genosys_checkout_optional_email( $fields ) {\n\tif ( isset( $fields['billing']['billing_email'] ) ) {\n\t\t$fields['billing']['billing_email']['required'] = ! is_user_logged_in() && (bool) apply_filters( 'woocommerce_checkout_registration_required', 'yes' !== get_option( 'woocommerce_enable_guest_checkout' ) );\n\t}\n\tforeach ( array( 'billing_first_name', 'billing_last_name', 'billing_phone', 'billing_state', 'billing_city', 'billing_address_1', 'billing_postcode' ) as $key ) {\n\t\tif ( isset( $fields['billing'][ $key ] ) ) {\n\t\t\t$fields['billing'][ $key ]['required'] = true;\n\t\t}\n\t}\n\treturn $fields;\n}\nadd_filter( 'woocommerce_checkout_fields', 'genosys_checkout_optional_email', 20 );\n\n/** The custom checkout only ships within Iran, including older saved addresses. */\nfunction genosys_checkout_iran_posted_data( $data ) {\n\tif ( ! empty( $data['genosys_checkout_layout'] ) || isset( $_POST['genosys_checkout_layout'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Missing -- Woo verifies the checkout nonce before processing.\n\t\t$data['billing_country']  = 'IR';\n\t\t$data['shipping_country'] = 'IR';\n\t}\n\treturn $data;\n}\nadd_filter( 'woocommerce_checkout_posted_data', 'genosys_checkout_iran_posted_data', 20 );\n\n/** Match the SMS sign-in number format when placing an order. */\nfunction genosys_checkout_validate_mobile( $data, $errors ) {\n\tif ( ! isset( $_POST['genosys_checkout_layout'] ) || '1' !== (string) wp_unslash( $_POST['genosys_checkout_layout'] ) || empty( $data['billing_phone'] ) || ! function_exists( 'genosys_sms_normalize_phone' ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Missing -- Woo verifies its checkout nonce before this validation hook.\n\t\treturn;\n\t}\n\tif ( '' === genosys_sms_normalize_phone( (string) $data['billing_phone'] ) && ! $errors->get_error_message( 'billing_phone_validation' ) ) {\n\t\t$errors->add( 'billing_phone_genosys_validation', 'شماره موبایل معتبر نیست.', array( 'id' => 'billing_phone' ) );\n\t}\n}\nadd_action( 'woocommerce_after_checkout_validation', 'genosys_checkout_validate_mobile', 10, 2 );\n\n/** Keep the replacement rates confined to this theme's checkout and Woo AJAX. */\nfunction genosys_checkout_is_shipping_context() {\n\tif ( function_exists( 'is_checkout' ) && is_checkout() && ! ( function_exists( 'is_order_received_page' ) && is_order_received_page() ) && ! ( function_exists( 'is_checkout_pay_page' ) && is_checkout_pay_page() ) ) {\n\t\treturn true;\n\t}\n\tif ( isset( $_POST['genosys_checkout_layout'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Missing -- Context check only, no mutation.\n\t\treturn true;\n\t}\n\tif ( isset( $_POST['post_data'] ) && is_string( $_POST['post_data'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Missing -- Context check only.\n\t\tparse_str( wp_unslash( $_POST['post_data'] ), $posted );\n\t\treturn ! empty( $posted['genosys_checkout_layout'] );\n\t}\n\treturn false;\n}\n\n/** Ensure an older foreign customer address cannot select an overseas zone. */\nfunction genosys_checkout_iran_shipping_packages( $packages ) {\n\tif ( ! genosys_checkout_is_shipping_context() || ! is_array( $packages ) ) {\n\t\treturn $packages;\n\t}\n\tforeach ( $packages as &$package ) {\n\t\tif ( is_array( $package ) ) {\n\t\t\tif ( isset( $package['destination'] ) && is_array( $package['destination'] ) ) {\n\t\t\t\t$package['destination']['country'] = 'IR';\n\t\t\t}\n\t\t\t// Woo caches package rates; a new schema key refreshes previous sessions.\n\t\t\t$package['genosys_checkout_shipping_version'] = '2';\n\t\t}\n\t}\n\tunset( $package );\n\treturn $packages;\n}\nadd_filter( 'woocommerce_cart_shipping_packages', 'genosys_checkout_iran_shipping_packages', 20 );\n\n/** Tipax is paid upon receipt; Post charges the amount saved in theme settings. */\nfunction genosys_checkout_shipping_rates( $rates, $package ) {\n\tif ( ! genosys_checkout_is_shipping_context() || ! is_array( $rates ) || ! is_array( $package ) || ! class_exists( 'WC_Shipping_Rate' ) ) {\n\t\treturn $rates;\n\t}\n\tif ( isset( $package['destination']['country'] ) && 'IR' !== strtoupper( (string) $package['destination']['country'] ) ) {\n\t\treturn $rates;\n\t}\n\n\t$tipax = new WC_Shipping_Rate( 'genosys_tipax', 'تیپاکس', 0, array(), 'genosys_tipax' );\n\tif ( method_exists( $tipax, 'set_description' ) ) {\n\t\t$tipax->set_description( 'کرایه هنگام تحویل توسط مشتری پرداخت می‌شود' );\n\t}\n\t$tipax->add_meta_data( 'نحوه پرداخت کرایه', 'پس کرایه' );\n\t$checkout_rates = array( $tipax->get_id() => $tipax );\n\n\t$cost = get_option( 'genosys_shipping_cost', '' );\n\tif ( '' !== $cost && is_numeric( $cost ) && (float) $cost >= 0 ) {\n\t\t$taxes = array();\n\t\tif ( function_exists( 'wc_tax_enabled' ) && wc_tax_enabled() && class_exists( 'WC_Tax' ) && function_exists( 'WC' ) && WC()->customer && ! WC()->customer->get_is_vat_exempt() ) {\n\t\t\t$taxes = WC_Tax::calc_shipping_tax( (float) $cost, WC_Tax::get_shipping_tax_rates() );\n\t\t}\n\t\t$post = new WC_Shipping_Rate( 'genosys_post', 'پست', (float) $cost, $taxes, 'genosys_post' );\n\t\tif ( method_exists( $post, 'set_description' ) ) {\n\t\t\t$post->set_description( 'ارسال به سراسر کشور' );\n\t\t}\n\t\t$checkout_rates[ $post->get_id() ] = $post;\n\t}\n\n\t// Preserve coupon-provided free shipping as an additional valid Woo rate.\n\tif ( function_exists( 'WC' ) && WC()->cart ) {\n\t\tforeach ( WC()->cart->get_coupons() as $coupon ) {\n\t\t\tif ( is_object( $coupon ) && method_exists( $coupon, 'get_free_shipping' ) && $coupon->get_free_shipping() ) {\n\t\t\t\tforeach ( $rates as $rate ) {\n\t\t\t\t\tif ( $rate instanceof WC_Shipping_Rate && 'free_shipping' === $rate->get_method_id() ) {\n\t\t\t\t\t\t$checkout_rates[ $rate->get_id() ] = $rate;\n\t\t\t\t\t\tbreak 2;\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n\treturn $checkout_rates;\n}\nadd_filter( 'woocommerce_package_rates', 'genosys_checkout_shipping_rates', 20, 2 );\n\n/** Available rates with Woo's real shipping_method[index] input names. */\nfunction genosys_checkout_render_shipping_methods() {\n\tif ( ! function_exists( 'WC' ) || ! WC()->cart || ! WC()->cart->needs_shipping() ) {\n\t\techo '<p class=\"gco-shipping-options__message\">این سفارش نیازی به ارسال ندارد.</p>';\n\t\treturn;\n\t}\n\n\t$packages = WC()->shipping()->get_packages();\n\t$chosen   = WC()->session ? (array) WC()->session->get( 'chosen_shipping_methods', array() ) : array();\n\tif ( ! $packages ) {\n\t\techo '<p class=\"gco-shipping-options__message\">برای نمایش روش‌های ارسال، نشانی تحویل را کامل کنید.</p>';\n\t\treturn;\n\t}\n\n\tforeach ( $packages as $index => $package ) {\n\t\t$rates = isset( $package['rates'] ) && is_array( $package['rates'] ) ? $package['rates'] : array();\n\t\tif ( count( $packages ) > 1 ) {\n\t\t\tprintf( '<h3 class=\"gco-shipping-options__package\">%s</h3>', esc_html( sprintf( 'بسته %s', function_exists( 'genosys_persian_number' ) ? genosys_persian_number( (string) ( $index + 1 ) ) : (string) ( $index + 1 ) ) ) );\n\t\t}\n\t\tif ( ! $rates ) {\n\t\t\techo '<p class=\"gco-shipping-options__message\">برای این نشانی، روش ارسالی در دسترس نیست.</p>';\n\t\t\tcontinue;\n\t\t}\n\t\t$selected = isset( $chosen[ $index ] ) && isset( $rates[ $chosen[ $index ] ] ) ? $chosen[ $index ] : key( $rates );\n\t\tforeach ( $rates as $rate ) {\n\t\t\tif ( ! $rate instanceof WC_Shipping_Rate ) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\t$id          = $rate->get_id();\n\t\t\t$input_id    = 'shipping_method_' . (int) $index . '_' . sanitize_title( $id );\n\t\t\t$is_selected = $selected === $id;\n\t\t\t$cost        = (float) $rate->get_cost();\n\t\t\tif ( WC()->cart->display_prices_including_tax() ) {\n\t\t\t\t$cost += (float) $rate->get_shipping_tax();\n\t\t\t}\n\t\t\t$price = 'genosys_tipax' === $rate->get_method_id() ? 'پس کرایه' : ( $cost > 0 ? genosys_checkout_price( $cost ) : ( 'free_shipping' === $rate->get_method_id() || 'genosys_post' === $rate->get_method_id() ? 'رایگان' : '' ) );\n\t\t\t$description = 'genosys_tipax' === $rate->get_method_id() ? 'کرایه هنگام تحویل توسط مشتری پرداخت می‌شود' : ( 'genosys_post' === $rate->get_method_id() ? 'ارسال به سراسر کشور' : ( method_exists( $rate, 'get_description' ) ? $rate->get_description() : '' ) );\n\t\t\t?>\n\t\t\t<label class=\"gco-shipping-option<?php echo $is_selected ? ' is-selected' : ''; ?>\" for=\"<?php echo esc_attr( $input_id ); ?>\">\n\t\t\t\t<input class=\"shipping_method gco-shipping-option__input\" type=\"radio\" name=\"shipping_method[<?php echo esc_attr( (string) $index ); ?>]\" data-index=\"<?php echo esc_attr( (string) $index ); ?>\" id=\"<?php echo esc_attr( $input_id ); ?>\" value=\"<?php echo esc_attr( $id ); ?>\" <?php checked( $is_selected ); ?> />\n\t\t\t\t<span class=\"gco-shipping-option__radio\" aria-hidden=\"true\"></span>\n\t\t\t\t<span class=\"gco-shipping-option__text\"><strong class=\"gco-shipping-option__name\"><?php echo esc_html( $rate->get_label() ); ?></strong><?php if ( $description ) : ?><small class=\"gco-shipping-option__description\"><?php echo esc_html( $description ); ?></small><?php endif; ?></span>\n\t\t\t\t<?php if ( '' !== $price ) : ?><strong class=\"gco-shipping-option__price\"><?php echo wp_kses_post( $price ); ?></strong><?php endif; ?>\n\t\t\t</label>\n\t\t\t<?php\n\t\t}\n\t}\n}\n\n/** Live cart and total summary. Must be wrapped in .woocommerce-checkout-review-order-table. */\nfunction genosys_checkout_render_summary() {\n\t$cart = function_exists( 'WC' ) && WC() ? WC()->cart : null;\n\tif ( ! $cart ) {\n\t\treturn;\n\t}\n\t$prices_include_tax = $cart->display_prices_including_tax();\n\t$sale_savings       = 0.0;\n\tforeach ( $cart->get_cart() as $item ) {\n\t\t$product = isset( $item['data'] ) ? $item['data'] : null;\n\t\tif ( ! $product || ! $product->exists() ) {\n\t\t\tcontinue;\n\t\t}\n\t\t$regular = $product->get_regular_price();\n\t\tif ( '' !== $regular && (float) $regular > (float) $product->get_price() ) {\n\t\t\t$sale_savings += max( 0, wc_get_price_to_display( $product, array( 'price' => (float) $regular, 'display_context' => 'cart' ) ) - wc_get_price_to_display( $product, array( 'display_context' => 'cart' ) ) ) * (int) $item['quantity'];\n\t\t}\n\t}\n\t$subtotal = (float) $cart->get_subtotal() + ( $prices_include_tax ? (float) $cart->get_subtotal_tax() : 0 );\n\t$discount = (float) $cart->get_discount_total() + ( $prices_include_tax ? (float) $cart->get_discount_tax() : 0 );\n\t$shipping = (float) $cart->get_shipping_total() + ( $prices_include_tax ? (float) $cart->get_shipping_tax() : 0 );\n\t?>\n\t<h2 class=\"gco-summary__title\" id=\"gco-summary-heading\">سفارش شما</h2>\n\t<div class=\"gco-summary__items\">\n\t\t<?php foreach ( $cart->get_cart() as $item ) : ?>\n\t\t\t<?php\n\t\t\t$product = isset( $item['data'] ) ? $item['data'] : null;\n\t\t\tif ( ! $product || ! $product->exists() || empty( $item['quantity'] ) ) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\t$quantity = (int) $item['quantity'];\n\t\t\t?>\n\t\t\t<div class=\"gco-summary__item\">\n\t\t\t\t<span class=\"gco-summary__thumb\"><?php echo wp_kses_post( $product->get_image( 'woocommerce_thumbnail', array( 'loading' => 'lazy' ) ) ); ?><span class=\"gco-summary__quantity\"><?php echo esc_html( function_exists( 'genosys_persian_number' ) ? genosys_persian_number( (string) $quantity ) : (string) $quantity ); ?></span></span>\n\t\t\t<span class=\"gco-summary__name\"><?php echo esc_html( $product->get_name() ); ?><?php echo wp_kses_post( wc_get_formatted_cart_item_data( $item ) ); ?></span>\n\t\t\t\t<strong class=\"gco-summary__line-price\"><?php echo wp_kses_post( genosys_checkout_localize_html( $cart->get_product_subtotal( $product, $quantity ) ) ); ?></strong>\n\t\t\t</div>\n\t\t<?php endforeach; ?>\n\t</div>\n\t<div class=\"gco-summary__totals\">\n\t\t<div class=\"gco-summary__row\"><span>جمع کالاها</span><strong><?php echo wp_kses_post( genosys_checkout_price( $subtotal + $sale_savings ) ); ?></strong></div>\n\t\t<?php if ( $sale_savings + $discount > 0 ) : ?><div class=\"gco-summary__row gco-summary__row--discount\"><span>سود شما از تخفیف</span><strong><?php echo wp_kses_post( genosys_checkout_price( $sale_savings + $discount ) ); ?></strong></div><?php endif; ?>\n\t\t<div class=\"gco-summary__row\"><span>هزینه ارسال</span><strong><?php\n\t\t\tif ( ! $cart->needs_shipping() ) {\n\t\t\t\techo '—';\n\t\t\t} elseif ( $cart->has_calculated_shipping() && $cart->get_shipping_methods() ) {\n\t\t\t\techo $shipping > 0 ? wp_kses_post( genosys_checkout_price( $shipping ) ) : esc_html( genosys_checkout_selected_shipping_label() );\n\t\t\t} else {\n\t\t\t\techo 'پس از انتخاب نشانی';\n\t\t\t}\n\t\t?></strong></div>\n\t\t<?php foreach ( $cart->get_fees() as $fee ) : ?><div class=\"gco-summary__row\"><span><?php echo esc_html( $fee->name ); ?></span><strong><?php echo wp_kses_post( genosys_checkout_price( $fee->total + ( $prices_include_tax ? $fee->tax : 0 ) ) ); ?></strong></div><?php endforeach; ?>\n\t\t<?php if ( ! $prices_include_tax && $cart->get_total_tax() > 0 ) : ?><div class=\"gco-summary__row\"><span>مالیات</span><strong><?php echo wp_kses_post( genosys_checkout_price( $cart->get_total_tax() ) ); ?></strong></div><?php endif; ?>\n\t</div>\n\t<?php if ( function_exists( 'wc_coupons_enabled' ) && wc_coupons_enabled() ) : ?>\n\t\t<div class=\"gco-summary__coupon\">\n\t\t\t<label class=\"screen-reader-text\" for=\"gco-coupon-code\">کد تخفیف</label>\n\t\t\t<input type=\"text\" id=\"gco-coupon-code\" name=\"gco_coupon_code\" placeholder=\"کد تخفیف دارید؟\" autocomplete=\"off\" />\n\t\t\t<button type=\"button\" data-gco-apply-coupon>اعمال</button>\n\t\t</div>\n\t\t<?php foreach ( $cart->get_applied_coupons() as $code ) : ?><p class=\"gco-summary__applied-coupon\"><?php echo esc_html( $code ); ?> <a href=\"<?php echo esc_url( add_query_arg( 'remove_coupon', rawurlencode( $code ), wc_get_checkout_url() ) ); ?>\" class=\"woocommerce-remove-coupon\" data-coupon=\"<?php echo esc_attr( $code ); ?>\">حذف</a></p><?php endforeach; ?>\n\t<?php endif; ?>\n\t<div class=\"gco-summary__total\"><span>مبلغ قابل پرداخت</span><strong><?php echo wp_kses_post( genosys_checkout_price( $cart->get_total( 'edit' ) ) ); ?></strong></div>\n\t<?php $shipping_note = genosys_checkout_selected_shipping_description(); if ( $shipping_note ) : ?><p class=\"gco-summary__shipping-note\"><?php echo esc_html( $shipping_note ); ?></p><?php endif; ?>\n\t<?php\n}\n\n/** Label for a zero-cost rate, without calling an unpaid method \"free\". */\nfunction genosys_checkout_selected_shipping_label() {\n\tif ( ! function_exists( 'WC' ) || ! WC()->shipping() || ! WC()->session ) {\n\t\treturn 'در زمان تحویل';\n\t}\n\t$chosen = (array) WC()->session->get( 'chosen_shipping_methods', array() );\n\tforeach ( WC()->shipping()->get_packages() as $index => $package ) {\n\t\tif ( isset( $chosen[ $index ], $package['rates'][ $chosen[ $index ] ] ) ) {\n\t\t\t$rate = $package['rates'][ $chosen[ $index ] ];\n\t\t\treturn 'genosys_tipax' === $rate->get_method_id() ? 'پس کرایه' : ( 'free_shipping' === $rate->get_method_id() || 'genosys_post' === $rate->get_method_id() ? 'رایگان' : $rate->get_label() );\n\t\t}\n\t}\n\treturn 'در زمان تحویل';\n}\n\n/** Show the selected Woo shipping rate's own explanation, if configured. */\nfunction genosys_checkout_selected_shipping_description() {\n\tif ( ! function_exists( 'WC' ) || ! WC()->shipping() || ! WC()->session ) {\n\t\treturn '';\n\t}\n\t$chosen = (array) WC()->session->get( 'chosen_shipping_methods', array() );\n\tforeach ( WC()->shipping()->get_packages() as $index => $package ) {\n\t\tif ( isset( $chosen[ $index ], $package['rates'][ $chosen[ $index ] ] ) ) {\n\t\t\t$rate = $package['rates'][ $chosen[ $index ] ];\n\t\t\tif ( 'genosys_tipax' === $rate->get_method_id() ) {\n\t\t\t\treturn 'کرایه هنگام تحویل توسط مشتری پرداخت می‌شود';\n\t\t\t}\n\t\t\tif ( 'genosys_post' === $rate->get_method_id() ) {\n\t\t\t\treturn 'ارسال به سراسر کشور';\n\t\t\t}\n\t\t\tif ( method_exists( $rate, 'get_description' ) ) {\n\t\t\t\treturn trim( wp_strip_all_tags( $rate->get_description() ) );\n\t\t\t}\n\t\t}\n\t}\n\treturn '';\n}\n\n/** Replace Woo's stock order table fragment and refresh shipping when address changes. */\nfunction genosys_checkout_order_review_fragments( $fragments ) {\n\t$post_data = array();\n\tif ( isset( $_POST['post_data'] ) && is_string( $_POST['post_data'] ) ) {\n\t\twp_parse_str( wp_unslash( $_POST['post_data'] ), $post_data );\n\t}\n\tif ( empty( $post_data['genosys_checkout_layout'] ) || ! function_exists( 'WC' ) || ! WC()->cart ) {\n\t\treturn $fragments;\n\t}\n\tob_start();\n\techo '<div class=\"gco-summary-inner woocommerce-checkout-review-order-table\">';\n\tgenosys_checkout_render_summary();\n\techo '</div>';\n\t$fragments['.woocommerce-checkout-review-order-table'] = ob_get_clean();\n\tob_start();\n\techo '<div class=\"gco-shipping-options\">';\n\tgenosys_checkout_render_shipping_methods();\n\techo '</div>';\n\t$fragments['.gco-shipping-options'] = ob_get_clean();\n\treturn $fragments;\n}\nadd_filter( 'woocommerce_update_order_review_fragments', 'genosys_checkout_order_review_fragments', 20 );\n\n/** The SMS login phone is the fallback for WP administrators without billing data. */\nfunction genosys_checkout_phone_default( $value, $key ) {\n\tif ( 'billing_phone' !== $key || null !== $value || ! is_user_logged_in() ) {\n\t\treturn $value;\n\t}\n\t$billing_phone = (string) get_user_meta( get_current_user_id(), 'billing_phone', true );\n\tif ( '' !== $billing_phone ) {\n\t\treturn null;\n\t}\n\t$phone = (string) get_user_meta( get_current_user_id(), 'genosys_phone', true );\n\treturn '' !== $phone ? $phone : null;\n}\nadd_filter( 'woocommerce_checkout_get_value', 'genosys_checkout_phone_default', 10, 2 );\n\n/** Expose the card-to-card gateway to Woo's native checkout processing. */\nfunction genosys_checkout_add_card_gateway( $gateways ) {\n\tif ( class_exists( 'Genosys_WC_Gateway_Card_To_Card' ) ) {\n\t\t$gateways[] = 'Genosys_WC_Gateway_Card_To_Card';\n\t}\n\treturn $gateways;\n}\nadd_filter( 'woocommerce_payment_gateways', 'genosys_checkout_add_card_gateway' );\n\n/** Normalize a configured card number for spacing and copy, including Persian digits. */\nfunction genosys_checkout_card_digits( $raw ) {\n\t$ascii = strtr( (string) $raw, array(\n\t\t'۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',\n\t\t'۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',\n\t\t'٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',\n\t\t'٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',\n\t) );\n\treturn preg_replace( '/\\D+/', '', $ascii );\n}\n\n/** Register after Woo's payment gateway base is available. */\nfunction genosys_checkout_define_card_gateway() {\n\tif ( ! class_exists( 'WC_Payment_Gateway' ) || class_exists( 'Genosys_WC_Gateway_Card_To_Card' ) ) {\n\t\treturn;\n\t}\n\tclass Genosys_WC_Gateway_Card_To_Card extends WC_Payment_Gateway {\n\t\tpublic function __construct() {\n\t\t\t$this->id                 = 'genosys_card_to_card';\n\t\t\t$this->method_title       = 'کارت به کارت ژنوسیس';\n\t\t\t$this->method_description = 'پرداخت دستی؛ سفارش تا تأیید رسید در حالت در انتظار بررسی می‌ماند.';\n\t\t\t$this->title              = 'کارت به کارت';\n\t\t\t$this->description        = 'اطلاعات کارت و ارسال رسید پس از ثبت سفارش نمایش داده می‌شود.';\n\t\t\t$this->has_fields         = false;\n\t\t\t$this->supports           = array( 'products' );\n\t\t\t$this->enabled            = 'yes';\n\t\t}\n\n\t\tpublic function is_available() {\n\t\t\tforeach ( array( 'genosys_checkout_card_number', 'genosys_checkout_card_holder', 'genosys_checkout_bank_name', 'genosys_checkout_whatsapp' ) as $key ) {\n\t\t\t\tif ( '' === trim( (string) get_option( $key, '' ) ) ) {\n\t\t\t\t\treturn false;\n\t\t\t\t}\n\t\t\t}\n\t\t\tif ( 16 !== strlen( genosys_checkout_card_digits( get_option( 'genosys_checkout_card_number', '' ) ) ) || '' === genosys_checkout_whatsapp_receipt_url() ) {\n\t\t\t\treturn false;\n\t\t\t}\n\t\t\treturn parent::is_available();\n\t\t}\n\n\t\tpublic function process_payment( $order_id ) {\n\t\t\t$order = wc_get_order( $order_id );\n\t\t\tif ( ! $order ) {\n\t\t\t\twc_add_notice( 'ثبت سفارش انجام نشد. لطفاً دوباره تلاش کنید.', 'error' );\n\t\t\t\treturn array( 'result' => 'failure' );\n\t\t\t}\n\t\t\t// Preserve the payment instructions used for this order if settings change later.\n\t\t\t$order->update_meta_data( '_genosys_payment_bank', (string) get_option( 'genosys_checkout_bank_name', '' ) );\n\t\t\t$order->update_meta_data( '_genosys_payment_card', genosys_checkout_card_digits( get_option( 'genosys_checkout_card_number', '' ) ) );\n\t\t\t$order->update_meta_data( '_genosys_payment_holder', (string) get_option( 'genosys_checkout_card_holder', '' ) );\n\t\t\t$order->update_meta_data( '_genosys_payment_whatsapp', (string) get_option( 'genosys_checkout_whatsapp', '' ) );\n\t\t\t// WooCommerce reduces stock when the order enters on-hold. Do not mark paid.\n\t\t\t$order->update_status( 'on-hold', 'در انتظار واریز کارت‌به‌کارت و بررسی رسید پرداخت.' );\n\t\t\tif ( function_exists( 'genosys_package_order_has_packages' ) && genosys_package_order_has_packages( $order ) ) {\n\t\t\t\t$fresh = wc_get_order( $order_id ); $fresh->read_meta_data( true );\n\t\t\t\t$stock_error = $fresh->get_meta( '_genosys_package_stock_error', true );\n\t\t\t\t$error = is_array( $stock_error ) ? 'reduce' === ( $stock_error['operation'] ?? '' ) : (bool) $stock_error;\n\t\t\t\t$complete = $fresh->get_data_store()->get_stock_reduced( $order_id );\n\t\t\t\tif ( 'yes' === get_option( 'woocommerce_manage_stock' ) ) {\n\t\t\t\t\tforeach ( $fresh->get_items() as $item ) {\n\t\t\t\t\t\tif ( ! $item->get_meta( '_genosys_package_components', true ) ) { continue; }\n\t\t\t\t\t\t$ledger = $item->get_meta( '_genosys_package_stock_ledger', true );\n\t\t\t\t\t\t$complete = $complete && is_array( $ledger ) && isset( $ledger['remaining'], $ledger['refunded'] ) && (float) $ledger['remaining'] + (float) $ledger['refunded'] >= (float) $item->get_quantity();\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif ( $error || ! $complete ) {\n\t\t\t\t\t$fresh->update_status( 'failed', 'ثبت سفارش به‌علت عدم تأیید موجودی اجزای پکیج متوقف شد.' );\n\t\t\t\t\twc_release_stock_for_order( $fresh );\n\t\t\t\t\twc_add_notice( 'موجودی محصولات پکیج برای ثبت سفارش تأیید نشد. سبد خرید را بررسی کنید و دوباره تلاش کنید.', 'error' );\n\t\t\t\t\treturn array( 'result' => 'failure' );\n\t\t\t\t}\n\t\t\t}\n\t\t\tWC()->cart->empty_cart();\n\t\t\treturn array(\n\t\t\t\t'result'   => 'success',\n\t\t\t\t'redirect' => $this->get_return_url( $order ),\n\t\t\t);\n\t\t}\n\t}\n}\nadd_action( 'after_setup_theme', 'genosys_checkout_define_card_gateway', 20 );\nadd_action( 'init', 'genosys_checkout_define_card_gateway', 5 );\n\n/** A WhatsApp receipt link for the order-received screen. */\nfunction genosys_checkout_whatsapp_receipt_url( $order_number = '', $saved_phone = null ) {\n\t$phone = genosys_checkout_card_digits( null === $saved_phone ? get_option( 'genosys_checkout_whatsapp', '' ) : $saved_phone );\n\tif ( 0 === strpos( $phone, '00' ) ) {\n\t\t$phone = substr( $phone, 2 );\n\t} elseif ( 0 === strpos( $phone, '0' ) ) {\n\t\t$phone = '98' . substr( $phone, 1 );\n\t} elseif ( 0 === strpos( $phone, '9' ) ) {\n\t\t$phone = '98' . $phone;\n\t}\n\tif ( '' === $phone ) {\n\t\treturn '';\n\t}\n\t$message = '' !== (string) $order_number\n\t\t? 'سلام، تصویر رسید پرداخت سفارش شماره ' . $order_number . ' را ارسال می‌کنم.'\n\t\t: 'سلام، درباره ارسال رسید پرداخت سفارش ژنوسیس پیام می‌دهم.';\n\treturn 'https://wa.me/' . rawurlencode( $phone ) . '?text=' . rawurlencode( $message );\n}\n\n/** Show the saved payment instructions only after the order has been placed. */\nfunction genosys_checkout_card_thankyou( $order_id ) {\n\t$order = wc_get_order( $order_id );\n\tif ( ! $order || 'genosys_card_to_card' !== $order->get_payment_method() ) {\n\t\treturn;\n\t}\n\t$card        = genosys_checkout_card_digits( $order->get_meta( '_genosys_payment_card', true ) );\n\t$card_print = trim( chunk_split( $card, 4, ' ' ) );\n\t$holder      = (string) $order->get_meta( '_genosys_payment_holder', true );\n\t$bank        = (string) $order->get_meta( '_genosys_payment_bank', true );\n\t$saved_phone = (string) $order->get_meta( '_genosys_payment_whatsapp', true );\n\t$whatsapp   = genosys_checkout_whatsapp_receipt_url( $order->get_order_number(), $saved_phone );\n\t?>\n\t<section class=\"gco-receipt-instructions\" dir=\"rtl\">\n\t\t<h2>پرداخت کارت به کارت</h2>\n\t\t<?php if ( $order->is_paid() ) : ?>\n\t\t\t<p>پرداخت این سفارش ثبت شده است.</p>\n\t\t<?php elseif ( 16 === strlen( $card ) && '' !== $bank && '' !== $holder && '' !== $whatsapp ) : ?>\n\t\t\t<p class=\"gco-payment__intro\">سفارش شما ثبت شد. مبلغ <?php echo wp_kses_post( $order->get_formatted_order_total() ); ?> را به کارت زیر واریز کنید و سپس تصویر فیش واریزی را در کادر زیر بارگذاری کنید.</p>\n\t\t\t<div class=\"gco-bank-card\" aria-label=\"کارت بانکی برای پرداخت\">\n\t\t\t\t<div class=\"gco-bank-card__top\"><span class=\"gco-bank-card__bank\"><small>نام بانک</small><strong><?php echo esc_html( $bank ); ?></strong></span><span class=\"gco-bank-card__chip\" aria-hidden=\"true\"></span></div>\n\t\t\t\t<div class=\"gco-bank-card__number\" dir=\"ltr\"><?php echo esc_html( $card_print ); ?></div>\n\t\t\t\t<div class=\"gco-bank-card__bottom\"><span class=\"gco-bank-card__holder\"><small>به نام</small><strong><?php echo esc_html( $holder ); ?></strong></span><span class=\"gco-bank-card__brand\" aria-hidden=\"true\">GENOSYS</span></div>\n\t\t\t</div>\n\t\t\t<button class=\"gco-copy-card\" type=\"button\" data-gco-copy-card data-card-number=\"<?php echo esc_attr( $card ); ?>\"><svg viewBox=\"0 0 24 24\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"11\" height=\"11\" rx=\"2\"/><path d=\"M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3\"/></svg><span>کپی شماره کارت</span></button>\n\t\t\t<?php get_template_part( 'woocommerce/checkout/receipt-uploader', null, array( 'receipt_order' => $order ) ); ?>\n\t\t\t<ol class=\"gco-payment__instructions\"><li>مبلغ قابل پرداخت را به کارت بالا واریز کنید.</li><li>تصویر فیش واریزی را در کادر بالا انتخاب کنید.</li><li>پس از تأیید پرداخت، سفارش شما ارسال می‌شود.</li></ol>\n\t\t<?php else : ?>\n\t\t\t<p>سفارش شما ثبت شد، اما اطلاعات کارت این سفارش در دسترس نیست. لطفاً با پشتیبانی تماس بگیرید.</p>\n\t\t<?php endif; ?>\n\t</section>\n\t<?php\n}\nadd_action( 'woocommerce_thankyou_genosys_card_to_card', 'genosys_checkout_card_thankyou' );\n","sha256":"c5b019b9d20dfb419d513fa680b3496369bb7074ea0fada3ccb999d001e6f136"},"inc/club-admin.php":{"content":"<?php\n/** Customer-club administration. Membership data and permissions live in club-members.php. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_club_admin_menu() {\n\tif ( ! function_exists( 'genosys_club_capability' ) ) { return; }\n\tadd_menu_page( 'باشگاه مشتریان', 'باشگاه مشتریان', genosys_club_capability(), 'genosys-club-members', 'genosys_club_admin_page', 'dashicons-groups', 57 );\n}\nadd_action( 'admin_menu', 'genosys_club_admin_menu', 25 );\n\nfunction genosys_club_admin_assets( $hook ) {\n\tif ( 'toplevel_page_genosys-club-members' !== $hook ) { return; }\n\twp_enqueue_style( 'genosys-club-admin', get_theme_file_uri( '/assets/css/club-admin.css' ), array(), '1.5.85' );\n\twp_enqueue_script( 'genosys-club-admin', get_theme_file_uri( '/assets/js/club-admin.js' ), array(), '1.5.85', true );\n\twp_localize_script( 'genosys-club-admin', 'genosysClubAdmin', array( 'ajaxUrl' => admin_url( 'admin-ajax.php' ), 'nonce' => wp_create_nonce( 'genosys_club_admin' ), 'smsCanConfigure' => current_user_can( 'manage_options' ) && ! defined( 'GENOSYS_CLUB_SMS_SENDER' ), 'smsSender' => function_exists( 'genosys_club_sms_sender' ) ? genosys_club_sms_sender() : '' ) );\n}\nadd_action( 'admin_enqueue_scripts', 'genosys_club_admin_assets' );\n\nfunction genosys_club_admin_body_class( $classes ) {\n\t$screen = function_exists( 'get_current_screen' ) ? get_current_screen() : null;\n\treturn $screen && 'toplevel_page_genosys-club-members' === $screen->id ? $classes . ' genosys-club-adminpage' : $classes;\n}\nadd_filter( 'admin_body_class', 'genosys_club_admin_body_class' );\n\nfunction genosys_club_admin_icons() {\n\t$icons = array(\n\t\t'people' => '<circle cx=\"9\" cy=\"7\" r=\"3\"/><path d=\"M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m3 11v-3a6 6 0 0 0-3-5\"/>',\n\t\t'sparkle' => '<path d=\"m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6L12 3Z\"/>',\n\t\t'star' => '<path d=\"m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.4-5.7-3-5.7 3 1.1-6.4L2.8 9.7l6.4-.9L12 3Z\"/>',\n\t\t'chart' => '<path d=\"M4 20V10m5 10V4m5 16v-8m5 8V7\"/>',\n\t\t'search' => '<circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 5 5\"/>',\n\t\t'download' => '<path d=\"M12 3v12m-5-5 5 5 5-5M5 19v2h14v-2\"/>',\n\t\t'chevron' => '<path d=\"m6 9 6 6 6-6\"/>',\n\t\t'left' => '<path d=\"m15 5-7 7 7 7\"/>',\n\t\t'right' => '<path d=\"m9 5 7 7-7 7\"/>',\n\t\t'close' => '<path d=\"m6 6 12 12M18 6 6 18\"/>',\n\t\t'check' => '<path d=\"m5 12 4 4L19 6\"/>',\n\t);\n\techo '<svg class=\"gca__sprite\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\"><defs>';\n\tforeach ( $icons as $name => $paths ) { echo '<symbol id=\"gca-i-' . esc_attr( $name ) . '\" viewBox=\"0 0 24 24\">' . $paths . '</symbol>'; }\n\techo '</defs></svg>';\n}\n\nfunction genosys_club_admin_page() {\n\tif ( ! function_exists( 'genosys_club_can_manage' ) || ! genosys_club_can_manage() ) { wp_die( 'اجازه دسترسی به این صفحه را ندارید.', '', array( 'response' => 403 ) ); }\n\t$context = genosys_club_admin_context();\n\t?>\n\t<main class=\"gca\" data-club-admin dir=\"rtl\">\n\t\t<?php genosys_club_admin_icons(); ?>\n\t\t<header class=\"gca__header\"><div><h1>اعضای باشگاه مشتریان</h1><p>اعضایی که پرسشنامه‌ی باشگاه را تکمیل کرده‌اند؛ برای دیدن جزئیات هر عضو روی او کلیک کنید.</p></div><div class=\"gca__header-actions\"><button class=\"gca__button gca__button--outline\" type=\"button\" data-club-sms-bulk>ارسال پیامک گروهی</button><a class=\"gca__button\" data-club-export href=\"<?php echo esc_url( $context['exportUrl'] ?? '' ); ?>\"><svg aria-hidden=\"true\"><use href=\"#gca-i-download\"></use></svg>خروجی CSV</a></div></header>\n\t\t<section class=\"gca__stats\" aria-label=\"آمار اعضای باشگاه\" data-club-stats></section>\n\t\t<section class=\"gca__panel\" aria-label=\"فهرست اعضا\">\n\t\t\t<div class=\"gca__tabs\" role=\"group\" aria-label=\"وضعیت عضویت\"><button type=\"button\" class=\"gca__tab is-active\" data-club-status=\"active\" aria-pressed=\"true\">اعضای فعال <span data-club-count=\"active\"></span></button><button type=\"button\" class=\"gca__tab\" data-club-status=\"cancelled\" aria-pressed=\"false\">لغو شده <span data-club-count=\"cancelled\"></span></button></div>\n\t\t\t<div class=\"gca__filters\"><label class=\"gca__search\"><svg aria-hidden=\"true\"><use href=\"#gca-i-search\"></use></svg><span class=\"gca__sr-only\">جستجوی عضو</span><input type=\"search\" data-club-filter=\"search\" placeholder=\"جستجو در نام، موبایل، ایمیل\" autocomplete=\"off\"></label><div class=\"gca__select\"><label class=\"gca__sr-only\" for=\"gca-filter-audience\">نوع عضو</label><select id=\"gca-filter-audience\" data-club-filter=\"audience\"><option value=\"\">همه‌ی اعضا</option><option value=\"consumer\">مصرف کننده</option><option value=\"clinic\">کلینیک / بیوتی تراپیست</option></select></div><div class=\"gca__select\"><label class=\"gca__sr-only\" for=\"gca-filter-skin\">نوع پوست</label><select id=\"gca-filter-skin\" data-club-filter=\"skin\"><option value=\"\">همه‌ی انواع پوست</option></select></div><div class=\"gca__select\"><label class=\"gca__sr-only\" for=\"gca-filter-city\">شهر</label><select id=\"gca-filter-city\" data-club-filter=\"city\"><option value=\"\">همه‌ی شهرها</option></select></div><div class=\"gca__select\"><label class=\"gca__sr-only\" for=\"gca-filter-rating\">رضایت</label><select id=\"gca-filter-rating\" data-club-filter=\"rating\"><option value=\"\">همه‌ی رضایت‌ها</option><option value=\"5\">۵ ستاره</option><option value=\"4\">۴ ستاره</option><option value=\"3\">۳ ستاره</option><option value=\"2\">۲ ستاره</option><option value=\"1\">۱ ستاره</option></select></div><div class=\"gca__select\"><label class=\"gca__sr-only\" for=\"gca-filter-source\">منبع آشنایی</label><select id=\"gca-filter-source\" data-club-filter=\"source\"><option value=\"\">همه‌ی منابع آشنایی</option></select></div><div class=\"gca__select\"><label class=\"gca__sr-only\" for=\"gca-filter-sort\">ترتیب نمایش</label><select id=\"gca-filter-sort\" data-club-filter=\"sort\"><option value=\"newest\">جدیدترین عضو</option><option value=\"oldest\">قدیمی‌ترین عضو</option></select></div><p class=\"gca__result\" data-club-results role=\"status\"></p></div>\n\t\t\t<div class=\"gca__list-message\" data-club-list-message role=\"alert\" hidden></div>\n\t\t\t<div class=\"gca__table-scroll\" data-club-table-scroll><table class=\"gca__table\"><thead><tr><th scope=\"col\">عضو</th><th scope=\"col\">نوع عضو</th><th scope=\"col\">شهر</th><th scope=\"col\">نوع پوست و دغدغه / خدمات</th><th scope=\"col\">رضایت</th><th scope=\"col\">سفارش‌ها</th><th scope=\"col\">تاریخ عضویت</th><th scope=\"col\"><span class=\"gca__sr-only\">عملیات</span></th></tr></thead><tbody data-club-members></tbody></table></div>\n\t\t\t<nav class=\"gca__pagination\" data-club-pagination aria-label=\"صفحه‌های اعضا\"></nav>\n\t\t</section>\n\t\t<p class=\"gca__toast\" role=\"status\" data-club-notice hidden></p>\n\t\t<noscript><p class=\"gca__no-script\">برای جستجو و مشاهده‌ی جزئیات اعضا، جاوااسکریپت مرورگر را فعال کنید.</p></noscript>\n\t\t<dialog class=\"gca__drawer\" data-club-drawer aria-labelledby=\"gca-detail-title\"><header class=\"gca__drawer-header\"><h2 id=\"gca-detail-title\">جزئیات عضو</h2><div class=\"gca__drawer-navigation\"><button class=\"gca__round\" type=\"button\" data-club-next aria-label=\"عضو بعدی\"><svg aria-hidden=\"true\"><use href=\"#gca-i-right\"></use></svg></button><button class=\"gca__round\" type=\"button\" data-club-prev aria-label=\"عضو قبلی\"><svg aria-hidden=\"true\"><use href=\"#gca-i-left\"></use></svg></button><button class=\"gca__round\" type=\"button\" data-club-close aria-label=\"بستن جزئیات\"><svg aria-hidden=\"true\"><use href=\"#gca-i-close\"></use></svg></button></div></header><div class=\"gca__drawer-body\" data-club-detail></div></dialog>\n\t\t<dialog class=\"gca__sms-dialog\" data-club-sms-dialog aria-labelledby=\"gca-sms-title\"><header><h2 id=\"gca-sms-title\">ارسال پیامک</h2><button class=\"gca__round\" type=\"button\" data-club-sms-close aria-label=\"بستن\"><svg aria-hidden=\"true\"><use href=\"#gca-i-close\"></use></svg></button></header><p data-club-sms-recipients role=\"status\">در حال بررسی گیرندگان…</p><p class=\"gca__sms-hint\" data-club-sms-provider hidden></p><label for=\"gca-sms-text\">متن پیامک</label><textarea id=\"gca-sms-text\" rows=\"5\" maxlength=\"1000\" data-club-sms-text placeholder=\"متن پیامک را بنویسید…\"></textarea><div class=\"gca__sms-meta\"><span data-club-sms-length>۰ / ۱۰۰۰</span><span>فقط اعضای موافق دریافت پیامک</span></div><p data-club-sms-review hidden></p><p class=\"gca__sms-error\" data-club-sms-error role=\"alert\" hidden></p><div class=\"gca__sms-actions\"><button class=\"gca__button\" type=\"button\" data-club-sms-review-button disabled>بررسی ارسال</button><button class=\"gca__button\" type=\"button\" data-club-sms-confirm hidden>تأیید و ارسال پیامک</button><button class=\"gca__button gca__button--outline\" type=\"button\" data-club-sms-cancel>انصراف</button></div><?php if ( current_user_can( 'manage_options' ) && ! defined( 'GENOSYS_CLUB_SMS_SENDER' ) ) : ?><details class=\"gca__sms-settings\"><summary>تنظیم خط فرستنده</summary><label class=\"gca__sr-only\" for=\"gca-sms-sender\">شماره خط فرستنده</label><div class=\"gca__sender-fields\"><input id=\"gca-sms-sender\" type=\"text\" inputmode=\"numeric\" maxlength=\"24\" data-club-sms-sender placeholder=\"شماره خط فرستنده\" value=\"<?php echo esc_attr( function_exists( 'genosys_club_sms_sender' ) ? genosys_club_sms_sender() : '' ); ?>\"><button class=\"gca__button gca__button--outline\" type=\"button\" data-club-sms-sender-save>ذخیره خط فرستنده</button></div><p>کلید API از تنظیمات سرویس پیامک قالب خوانده می‌شود.</p></details><?php endif; ?></dialog>\n\t\t<script type=\"application/json\" data-club-initial><?php echo wp_json_encode( $context, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT ); ?></script>\n\t</main>\n\t<?php\n}\n","sha256":"db4997fa70d7403a857532b4dab5c61eefc777ae01149e7695b3621cba5900a8"},"inc/club-members.php":{"content":"<?php\n/** Private, consent-based club registrations and permission-scoped administration. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_club_register_storage() {\n\tregister_post_type( 'genosys_club_member', array(\n\t\t'label' => 'اعضای باشگاه مشتریان', 'public' => false, 'publicly_queryable' => false,\n\t\t'show_ui' => false, 'show_in_menu' => false, 'show_in_rest' => false,\n\t\t'exclude_from_search' => true, 'rewrite' => false, 'query_var' => false,\n\t\t'supports' => array(), 'map_meta_cap' => false,\n\t\t'capabilities' => array_fill_keys( array( 'edit_post', 'read_post', 'delete_post', 'edit_posts', 'edit_others_posts', 'publish_posts', 'read_private_posts', 'create_posts', 'delete_posts', 'delete_private_posts', 'delete_published_posts', 'delete_others_posts', 'edit_private_posts', 'edit_published_posts' ), 'do_not_allow' ),\n\t) );\n}\nadd_action( 'init', 'genosys_club_register_storage' );\n\nfunction genosys_club_can_manage() {\n\treturn current_user_can( 'manage_woocommerce' ) || current_user_can( 'manage_options' );\n}\n\nfunction genosys_club_capability() {\n\treturn current_user_can( 'manage_woocommerce' ) ? 'manage_woocommerce' : 'manage_options';\n}\n\nfunction genosys_club_ascii( $value ) {\n\treturn strtr( (string) $value, array( '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4', '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9', '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4', '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9' ) );\n}\n\nfunction genosys_club_digits( $value ) {\n\treturn function_exists( 'genosys_persian_number' ) ? genosys_persian_number( $value ) : (string) $value;\n}\n\nfunction genosys_club_normalize( $text ) {\n\t$text = strtr( genosys_club_ascii( wp_strip_all_tags( (string) $text ) ), array( 'ي' => 'ی', 'ى' => 'ی', 'ك' => 'ک', '‌' => ' ' ) );\n\t$text = trim( preg_replace( '/\\s+/u', ' ', (string) preg_replace( '/[\\x{064B}-\\x{065F}\\x{0670}ـ]/u', '', $text ) ) );\n\treturn function_exists( 'mb_strtolower' ) ? mb_strtolower( $text, 'UTF-8' ) : strtolower( $text );\n}\n\nfunction genosys_club_length( $text ) {\n\treturn function_exists( 'mb_strlen' ) ? mb_strlen( $text, 'UTF-8' ) : strlen( $text );\n}\n\nfunction genosys_club_labels() {\n\treturn array(\n\t\t'skin' => array( 'نرمال', 'خشک', 'چرب', 'مختلط', 'حساس' ),\n\t\t'concerns' => array( 'لک و یکدستی', 'چین و چروک', 'آکنه و جوش', 'خشکی و کدری', 'ریزش مو', 'آفتاب‌سوختگی', 'حساسیت و قرمزی' ),\n\t\t'categories' => array( 'مراقبت پوست', 'مراقبت مو و پوست سر', 'ضد آفتاب', 'دور چشم', 'آرایشی' ),\n\t\t'services' => array( 'فیشیال و پاکسازی', 'جوانسازی پوست', 'خدمات لک و آکنه', 'مراقبت مو و پوست سر', 'مراقبت پس از خدمات زیبایی', 'سایر' ),\n\t\t'client_needs' => array( 'آبرسانی و مراقبت روتین', 'لک و تیرگی', 'آکنه و چربی پوست', 'چین و چروک', 'پوست حساس', 'مراقبت مو و پوست سر', 'سایر' ),\n\t\t'source' => array( 'instagram' => 'اینستاگرام', 'friends' => 'دوستان و آشنایان', 'search' => 'جستجوی اینترنتی', 'store' => 'فروشگاه یا کلینیک', 'other' => 'سایر' ),\n\t\t'age_range' => array( 'under-18' => 'زیر ۱۸ سال', '18-24' => '۱۸ تا ۲۴ سال', '25-34' => '۲۵ تا ۳۴ سال', '35-44' => '۳۵ تا ۴۴ سال', '45-54' => '۴۵ تا ۵۴ سال', '55-plus' => '۵۵ سال به بالا' ),\n\t\t'activity' => array( 'clinic' => 'کلینیک زیبایی', 'therapist' => 'بیوتی تراپیست مستقل', 'facial-center' => 'مرکز فیشیال و مراقبت پوست', 'other' => 'سایر' ),\n\t\t'experience' => array( 'starting' => 'در حال راه‌اندازی', 'under-one' => 'کمتر از ۱ سال', 'one-three' => '۱ تا ۳ سال', 'three-five' => '۳ تا ۵ سال', 'five-ten' => '۵ تا ۱۰ سال', 'over-ten' => 'بیشتر از ۱۰ سال' ),\n\t\t'monthly_consumption' => array( 'under-five' => 'کمتر از ۵ عدد در ماه', 'five-ten' => '۵ تا ۱۰ عدد در ماه', 'eleven-twenty' => '۱۱ تا ۲۰ عدد در ماه', 'over-twenty' => 'بیشتر از ۲۰ عدد در ماه', 'unknown' => 'هنوز برآوردی ندارم' ),\n\t\t'monthly_clients' => array( 'under-twenty' => 'تا ۲۰ نفر', 'twenty-fifty' => '۲۱ تا ۵۰ نفر', 'fifty-hundred' => '۵۱ تا ۱۰۰ نفر', 'hundred-twohundred' => '۱۰۱ تا ۲۰۰ نفر', 'over-twohundred' => 'بیشتر از ۲۰۰ نفر' ),\n\t);\n}\n\nfunction genosys_club_error( $message, $status = 400, $field = '', $extra = array() ) {\n\t$data = array_merge( array( 'message' => $message ), $extra );\n\tif ( $field ) { $data['field'] = $field; }\n\tnocache_headers();\n\twp_send_json_error( $data, $status );\n}\n\n/** Iranian mobile or fixed-line syntax, without granting credential verification. */\nfunction genosys_club_phone( $value, $fixed = false ) {\n\tif ( ! is_string( $value ) ) { return ''; }\n\t$value = genosys_club_ascii( trim( $value ) );\n\tif ( preg_match( '/[^0-9+\\s().-]/u', $value ) ) { return ''; }\n\t$value = preg_replace( '/[\\s().-]/u', '', $value );\n\tif ( 0 === strpos( $value, '+98' ) ) { $value = '0' . substr( $value, 3 ); }\n\telseif ( 0 === strpos( $value, '0098' ) ) { $value = '0' . substr( $value, 4 ); }\n\telseif ( preg_match( '/^98[0-9]{10}$/D', $value ) ) { $value = '0' . substr( $value, 2 ); }\n\treturn preg_match( $fixed ? '/^0[1-8][0-9]{9}$/D' : '/^09[0-9]{9}$/D', $value ) ? $value : '';\n}\n\n/** The server validates every step; browser validation is only a convenience. */\nfunction genosys_club_validate( $input ) {\n\tif ( ! is_array( $input ) || count( $input ) > 30 ) { return new WP_Error( 'invalid', 'اطلاعات پرسشنامه معتبر نیست.' ); }\n\t$audience = isset( $input['audience'] ) && is_string( $input['audience'] ) ? $input['audience'] : '';\n\tif ( ! in_array( $audience, array( 'consumer', 'clinic' ), true ) ) { return new WP_Error( 'audience', 'نوع عضویت را انتخاب کنید.', array( 'field' => 'audience' ) ); }\n\tif ( ! isset( $input['consent'] ) || true !== $input['consent'] ) { return new WP_Error( 'consent', 'برای ثبت عضویت، موافقت خود را مشخص کنید.', array( 'field' => 'consent' ) ); }\n\t$labels = genosys_club_labels(); $data = array( 'audience' => $audience, 'consent' => true );\n\t$fields = 'consumer' === $audience ? array( 'full_name' => 150, 'email' => 254, 'city' => 100, 'message' => 3000 ) : array( 'clinic_name' => 150, 'contact_name' => 150, 'clinic_city' => 100, 'clinic_message' => 3000 );\n\tforeach ( $fields as $key => $limit ) {\n\t\t$value = isset( $input[ $key ] ) ? $input[ $key ] : '';\n\t\tif ( ! is_string( $value ) || genosys_club_length( $value ) > $limit ) { return new WP_Error( 'length', 'طول یا قالب اطلاعات واردشده معتبر نیست.', array( 'field' => $key ) ); }\n\t\t$data[ $key ] = in_array( $key, array( 'message', 'clinic_message' ), true ) ? sanitize_textarea_field( $value ) : sanitize_text_field( $value );\n\t}\n\t$names = 'consumer' === $audience ? array( 'full_name' ) : array( 'clinic_name', 'contact_name' );\n\tforeach ( $names as $key ) { if ( '' === $data[ $key ] ) { return new WP_Error( 'name', 'نام را وارد کنید.', array( 'field' => $key ) ); } }\n\t$phone_key = 'consumer' === $audience ? 'phone' : 'contact_phone';\n\t$data[ $phone_key ] = genosys_club_phone( isset( $input[ $phone_key ] ) ? $input[ $phone_key ] : '' );\n\tif ( ! $data[ $phone_key ] ) { return new WP_Error( 'phone', 'شماره موبایل معتبر وارد کنید.', array( 'field' => $phone_key ) ); }\n\tif ( 'consumer' === $audience ) {\n\t\tif ( $data['email'] && ( ! is_email( $data['email'] ) || sanitize_email( $data['email'] ) !== $data['email'] ) ) { return new WP_Error( 'email', 'ایمیل معتبر وارد کنید.', array( 'field' => 'email' ) ); }\n\t\tforeach ( array( 'rating' => array( 1, 5 ), 'recommend' => array( 0, 10 ) ) as $key => $range ) {\n\t\t\t$value = isset( $input[ $key ] ) && ( is_string( $input[ $key ] ) || is_int( $input[ $key ] ) ) ? genosys_club_ascii( $input[ $key ] ) : '';\n\t\t\tif ( ! preg_match( '/^[0-9]{1,2}$/D', $value ) || (int) $value < $range[0] || (int) $value > $range[1] ) { return new WP_Error( 'rating', 'امتیاز معتبر را انتخاب کنید.', array( 'field' => $key ) ); }\n\t\t\t$data[ $key ] = (int) $value;\n\t\t}\n\t\t$skin = isset( $input['skin'] ) && is_string( $input['skin'] ) ? $input['skin'] : '';\n\t\tif ( ! in_array( $skin, $labels['skin'], true ) ) { return new WP_Error( 'skin', 'نوع پوست را انتخاب کنید.', array( 'field' => 'skin' ) ); }\n\t\t$data['skin'] = $skin;\n\t} else {\n\t\t$landline = isset( $input['clinic_landline'] ) ? $input['clinic_landline'] : '';\n\t\tif ( ! is_string( $landline ) || genosys_club_length( $landline ) > 30 ) { return new WP_Error( 'landline', 'شماره ثابت معتبر نیست.', array( 'field' => 'clinic_landline' ) ); }\n\t\t$data['clinic_landline'] = '' === trim( $landline ) ? '' : genosys_club_phone( $landline, true );\n\t\tif ( '' !== trim( $landline ) && ! $data['clinic_landline'] ) { return new WP_Error( 'landline', 'شماره ثابت را با پیش‌شماره وارد کنید.', array( 'field' => 'clinic_landline' ) ); }\n\t}\n\t$enums = 'consumer' === $audience ? array( 'age_range' => false, 'source' => false ) : array( 'activity' => false, 'experience' => true, 'monthly_consumption' => true, 'monthly_clients' => false );\n\tforeach ( $enums as $key => $required ) {\n\t\t$value = isset( $input[ $key ] ) ? $input[ $key ] : '';\n\t\tif ( ! is_string( $value ) || ( '' === $value && $required ) || ( '' !== $value && ! isset( $labels[ $key ][ $value ] ) ) ) { return new WP_Error( 'choice', 'گزینه معتبر را انتخاب کنید.', array( 'field' => $key ) ); }\n\t\t$data[ $key ] = $value;\n\t}\n\t$lists = 'consumer' === $audience ? array( 'concerns' => false, 'categories' => false ) : array( 'services' => true, 'client_needs' => true );\n\tforeach ( $lists as $key => $required ) {\n\t\t$values = isset( $input[ $key ] ) ? $input[ $key ] : array();\n\t\tif ( ! is_array( $values ) || count( $values ) > count( $labels[ $key ] ) || ( $required && ! $values ) ) { return new WP_Error( 'choices', 'حداقل یک گزینه معتبر انتخاب کنید.', array( 'field' => $key ) ); }\n\t\tforeach ( $values as $value ) { if ( ! is_string( $value ) || ! in_array( $value, $labels[ $key ], true ) ) { return new WP_Error( 'choices', 'گزینه انتخاب‌شده معتبر نیست.', array( 'field' => $key ) ); } }\n\t\t$data[ $key ] = array_values( array_unique( $values ) );\n\t}\n\treturn $data;\n}\n\nfunction genosys_club_same_origin() {\n\t$origin = isset( $_SERVER['HTTP_ORIGIN'] ) ? wp_unslash( $_SERVER['HTTP_ORIGIN'] ) : '';\n\tif ( ! $origin ) { return true; }\n\t$origin_parts = wp_parse_url( $origin );\n\tforeach ( array( home_url(), site_url() ) as $allowed ) {\n\t\t$parts = wp_parse_url( $allowed );\n\t\tif ( isset( $origin_parts['host'], $origin_parts['scheme'], $parts['host'], $parts['scheme'] ) && strtolower( $origin_parts['host'] ) === strtolower( $parts['host'] ) && $origin_parts['scheme'] === $parts['scheme'] && ( isset( $origin_parts['port'] ) ? (int) $origin_parts['port'] : ( 'https' === $origin_parts['scheme'] ? 443 : 80 ) ) === ( isset( $parts['port'] ) ? (int) $parts['port'] : ( 'https' === $parts['scheme'] ? 443 : 80 ) ) ) { return true; }\n\t}\n\treturn false;\n}\n\n/** The random cookie proves browser ownership only. It never proves a phone number. */\nfunction genosys_club_browser( $create = false ) {\n\t$value = isset( $_COOKIE['genosys_club_browser'] ) && is_string( $_COOKIE['genosys_club_browser'] ) ? wp_unslash( $_COOKIE['genosys_club_browser'] ) : '';\n\tif ( ! preg_match( '/^[a-f0-9]{64}$/D', $value ) ) {\n\t\tif ( ! $create || headers_sent() ) { return ''; }\n\t\ttry { $value = bin2hex( random_bytes( 32 ) ); } catch ( Exception