update_post_meta( $id, '_genosys_club_joined', $record['joined'] );\n\t\t\t$stored = genosys_club_member_raw( $id );\n\t\t\tif ( ! $stored || $stored['status'] !== $status || get_post_meta( $id, '_genosys_club_status', true ) !== $status || (int) get_post_meta( $id, '_genosys_club_joined', true ) !== (int) $record['joined'] || ! genosys_club_update_membership_flag( (int) $record['userId'] ) ) { throw new RuntimeException( 'status write failed' ); }\n\t\t\tif ( false === $wpdb->query( 'COMMIT' ) ) { throw new RuntimeException( 'commit failed' ); }\n\t\t}\n\t} catch ( Throwable $e ) {\n\t\tif ( $started ) { $wpdb->query( 'ROLLBACK' ); }\n\t\tclean_post_cache( $id ); wp_cache_delete( $id, 'post_meta' );\n\t\tif ( $record['userId'] ) { clean_user_cache( $record['userId'] ); wp_cache_delete( $record['userId'], 'user_meta' ); }\n\t\t$failed = true;\n\t}\n\tforeach ( $locks as $held ) { genosys_club_unlock( $held ); }\n\tif ( $failed ) { genosys_club_error( 'وضعیت ذخیره نشد.', 500 ); }\n\twp_send_json_success( array( 'member' => genosys_club_member_data( $id ) ) );\n}\nadd_action( 'wp_ajax_genosys_club_status', 'genosys_club_ajax_status' );\n\n/** Only exact record references may be released; another enrollment's claims are never removed. */\nfunction genosys_club_claim_member_id( $claim ) {\n\t$value = is_array( $claim ) ? ( $claim['memberId'] ?? null ) : null;\n\treturn ( is_int( $value ) && $value > 0 ) || ( is_string( $value ) && preg_match( '/^[1-9][0-9]{0,17}$/D', $value ) ) ? (int) $value : 0;\n}\n\nfunction genosys_club_record_user_ids( $id, $record ) {\n\t$post = get_post( $id );\n\t$ids = array( (int) ( $record['userId'] ?? 0 ), (int) get_post_meta( $id, '_genosys_club_owner_user', true ), $post ? (int) $post->post_author : 0 );\n\t$ids = array_values( array_unique( array_filter( $ids, static function ( $value ) { return $value > 0; } ) ) );\n\tsort( $ids, SORT_NUMERIC );\n\treturn $ids;\n}\n\n/** Administrator deletion releases this record's two claims and preserves every other membership. */\nfunction genosys_club_delete_member( $id ) {\n\tif ( ! genosys_club_can_manage() ) { return new WP_Error( 'forbidden', 'دسترسی مجاز نیست.' ); }\n\t$record = genosys_club_member_raw( $id );\n\tif ( ! $record ) { return new WP_Error( 'not_found', 'عضو پیدا نشد.' ); }\n\t$user_ids = genosys_club_record_user_ids( $id, $record );\n\t$browser = (string) get_post_meta( $id, '_genosys_club_owner_browser', true );\n\t$scopes = array_map( static function ( $user_id ) { return 'user:' . $user_id; }, $user_ids );\n\t$scopes[] = 'enrollment';\n\t$scopes[] = 'member:' . $id;\n\t$scopes[] = 'browser:' . $browser;\n\t$locks = array(); $claims = array(); $started = false;\n\tglobal $wpdb;\n\ttry {\n\t\tforeach ( $scopes as $scope ) {\n\t\t\t$lock = genosys_club_lock( $scope, 600 );\n\t\t\tif ( ! $lock ) { return new WP_Error( 'busy', 'درخواست دیگری در حال انجام است. دوباره تلاش کنید.' ); }\n\t\t\t$locks[] = $lock;\n\t\t}\n\t\tclean_post_cache( $id ); wp_cache_delete( $id, 'post_meta' );\n\t\t$record = genosys_club_member_raw( $id );\n\t\tif ( ! $record ) { return new WP_Error( 'not_found', 'عضو پیدا نشد.' ); }\n\t\tif ( $user_ids !== genosys_club_record_user_ids( $id, $record ) || $browser !== (string) get_post_meta( $id, '_genosys_club_owner_browser', true ) ) { return new WP_Error( 'busy', 'اطلاعات عضو هم‌زمان تغییر کرده است. دوباره تلاش کنید.' ); }\n\t\tforeach ( array( $wpdb->posts, $wpdb->postmeta, $wpdb->usermeta, $wpdb->options, $wpdb->comments, $wpdb->commentmeta, $wpdb->term_relationships ) as $table_name ) {\n\t\t\t$table = $wpdb->get_row( $wpdb->prepare( 'SHOW TABLE STATUS LIKE %s', $wpdb->esc_like( $table_name ) ), ARRAY_A );\n\t\t\tif ( ! is_array( $table ) || 'innodb' !== strtolower( (string) ( $table['Engine'] ?? '' ) ) ) { throw new RuntimeException( 'transaction unavailable' ); }\n\t\t}\n\t\tif ( false === $wpdb->query( 'START TRANSACTION' ) ) { throw new RuntimeException( 'transaction unavailable' ); }\n\t\t$started = true;\n\t\t// Existing untyped and new typed claims may all refer to this one record.\n\t\t$cursor = 0;\n\t\tdo {\n\t\t\t$rows = $wpdb->get_results( $wpdb->prepare( \"SELECT option_id, option_name, option_value FROM {$wpdb->options} WHERE option_name LIKE %s AND option_id > %d ORDER BY option_id ASC LIMIT 200\", $wpdb->esc_like( 'genosys_club_enrolled_' ) . '%', $cursor ), ARRAY_A );\n\t\t\tif ( $wpdb->last_error ) { throw new RuntimeException( 'claim read failed' ); }\n\t\t\tforeach ( $rows as $row ) {\n\t\t\t\t$cursor = (int) $row['option_id'];\n\t\t\t\tif ( genosys_club_claim_member_id( maybe_unserialize( $row['option_value'] ) ) !== (int) $id ) { continue; }\n\t\t\t\t$claims[] = $row['option_name'];\n\t\t\t\tif ( 1 !== $wpdb->query( $wpdb->prepare( \"DELETE FROM {$wpdb->options} WHERE option_id = %d AND option_value = %s\", $cursor, $row['option_value'] ) ) ) { throw new RuntimeException( 'claim delete failed' ); }\n\t\t\t\twp_cache_delete( $row['option_name'], 'options' );\n\t\t\t}\n\t\t} while ( count( $rows ) === 200 );\n\t\t$deleted = wp_delete_post( (int) $id, true );\n\t\tif ( ! $deleted || (int) $deleted->ID !== (int) $id ) { throw new RuntimeException( 'record delete failed' ); }\n\t\t$remaining_post = $wpdb->get_var( $wpdb->prepare( \"SELECT COUNT(*) FROM {$wpdb->posts} WHERE ID = %d\", $id ) );\n\t\tif ( $wpdb->last_error || '0' !== (string) $remaining_post ) { throw new RuntimeException( 'record delete failed' ); }\n\t\t$remaining_meta = $wpdb->get_var( $wpdb->prepare( \"SELECT COUNT(*) FROM {$wpdb->postmeta} WHERE post_id = %d\", $id ) );\n\t\tif ( $wpdb->last_error || '0' !== (string) $remaining_meta ) { throw new RuntimeException( 'metadata delete failed' ); }\n\t\t$remaining_comments = $wpdb->get_var( $wpdb->prepare( \"SELECT COUNT(*) FROM {$wpdb->comments} WHERE comment_post_ID = %d\", $id ) );\n\t\tif ( $wpdb->last_error || '0' !== (string) $remaining_comments ) { throw new RuntimeException( 'comment delete failed' ); }\n\t\t$remaining_terms = $wpdb->get_var( $wpdb->prepare( \"SELECT COUNT(*) FROM {$wpdb->term_relationships} WHERE object_id = %d\", $id ) );\n\t\tif ( $wpdb->last_error || '0' !== (string) $remaining_terms ) { throw new RuntimeException( 'relationship delete failed' ); }\n\t\tforeach ( $user_ids as $user_id ) {\n\t\t\tif ( ! genosys_club_update_membership_flag( $user_id ) ) { throw new RuntimeException( 'membership write failed' ); }\n\t\t}\n\t\tif ( false === $wpdb->query( 'COMMIT' ) ) { throw new RuntimeException( 'commit failed' ); }\n\t\t$started = false;\n\t\treturn true;\n\t} catch ( Throwable $e ) {\n\t\tif ( $started ) { $wpdb->query( 'ROLLBACK' ); }\n\t\treturn new WP_Error( 'database', 'اطلاعات حذف نشد. دوباره تلاش کنید.' );\n\t} finally {\n\t\t// WordPress caches are not transactional, including a rollback after wp_delete_post().\n\t\tclean_post_cache( $id ); wp_cache_delete( $id, 'post_meta' );\n\t\tforeach ( $user_ids as $user_id ) { clean_user_cache( $user_id ); wp_cache_delete( $user_id, 'user_meta' ); }\n\t\tforeach ( $claims as $key ) { wp_cache_delete( $key, 'options' ); }\n\t\twp_cache_delete( 'alloptions', 'options' ); wp_cache_delete( 'notoptions', 'options' );\n\t\tforeach ( array_reverse( $locks ) as $held ) { genosys_club_unlock( $held ); }\n\t}\n}\n\nfunction genosys_club_ajax_delete() {\n\tgenosys_club_admin_authorize();\n\tforeach ( $_POST as $key => $value ) {\n\t\tif ( ! is_string( $value ) || ! in_array( $key, array( 'action', 'nonce', 'id', 'confirm', 'filters' ), true ) ) { genosys_club_error( 'درخواست معتبر نیست.', 400 ); }\n\t}\n\tif ( ! isset( $_POST['confirm'] ) || 'delete' !== wp_unslash( $_POST['confirm'] ) ) { genosys_club_error( 'حذف کامل عضویت باید تأیید شود.', 400 ); }\n\t$filters = isset( $_POST['filters'] ) ? json_decode( wp_unslash( $_POST['filters'] ), true ) : array();\n\tif ( ! is_array( $filters ) ) { genosys_club_error( 'فیلترها معتبر نیستند.', 400 ); }\n\t$id = genosys_club_admin_id();\n\t$result = genosys_club_delete_member( $id );\n\tif ( is_wp_error( $result ) ) {\n\t\t$status = 'busy' === $result->get_error_code() ? 409 : ( 'not_found' === $result->get_error_code() ? 404 : ( 'forbidden' === $result->get_error_code() ? 403 : 500 ) );\n\t\tgenosys_club_error( $result->get_error_message(), $status );\n\t}\n\twp_send_json_success( array( 'deletedId' => (int) $id, 'context' => genosys_club_admin_context( $filters ), 'message' => 'این عضویت به‌طور کامل حذف شد. ثبت دوباره همین نوع عضویت امکان‌پذیر است.' ) );\n}\nadd_action( 'wp_ajax_genosys_club_delete', 'genosys_club_ajax_delete' );\n\n/** Leading zeroes and spreadsheet formula characters stay literal in CSV readers. */\nfunction genosys_club_csv_cell( $value, $phone = false ) {\n\t$value = str_replace( array( \"\\r\", \"\\n\", \"\\t\", \"\\0\" ), ' ', (string) $value );\n\tif ( $phone && '' !== $value ) { return \"'\" . $value; }\n\treturn preg_match( '/^[\\s\\x{FEFF}]*(?:[=+@-]|[\\x{FF1D}\\x{FF0B}\\x{FF0D}\\x{FF20}])/u', $value ) ? \"'\" . $value : $value;\n}\n\nfunction genosys_club_export() {\n\tnocache_headers();\n\t$nonce = isset( $_GET['_wpnonce'] ) && is_string( $_GET['_wpnonce'] ) ? wp_unslash( $_GET['_wpnonce'] ) : '';\n\tif ( ! genosys_club_can_manage() || ! wp_verify_nonce( $nonce, 'genosys_club_admin' ) ) { wp_die( 'دسترسی مجاز نیست.', 'دسترسی مجاز نیست', array( 'response' => 403 ) ); }\n\t$filters = isset( $_GET['filters'] ) && is_string( $_GET['filters'] ) ? json_decode( wp_unslash( $_GET['filters'] ), true ) : array();\n\t$filters = genosys_club_filters( $filters ); $filters['page'] = 1;\n\tif ( headers_sent() ) { wp_die( 'خروجی در دسترس نیست.' ); }\n\theader( 'Content-Type: text/csv; charset=UTF-8' ); header( 'Content-Disposition: attachment; filename=\"genosys-club-members-' . wp_date( 'Y-m-d' ) . '.csv\"' ); header( 'X-Content-Type-Options: nosniff' );\n\t$output = fopen( 'php://output', 'w' ); fwrite( $output, \"\\xEF\\xBB\\xBF\" );\n\tfputcsv( $output, array( 'شناسه', 'نوع عضو', 'نام', 'موبایل', 'ایمیل', 'شهر', 'وضعیت', 'تاریخ عضویت', 'نوع پوست', 'دغدغه‌ها', 'دسته محصولات', 'رضایت از ۵', 'احتمال معرفی از ۱۰', 'منبع آشنایی', 'نظر', 'نام کلینیک', 'شماره ثابت', 'نوع فعالیت', 'سابقه کاری', 'خدمات', 'نیاز مشتریان', 'مصرف ماهانه', 'مشتریان ماهانه', 'رضایت به دریافت اطلاعات' ) );\n\tdo {\n\t\t$args = genosys_club_query_args( $filters, 100 ); $args['no_found_rows'] = true; $ids = get_posts( $args );\n\t\tforeach ( $ids as $id ) {\n\t\t\t$m = genosys_club_member_data( $id, false, false ); if ( ! $m ) { continue; }\n\t\t\t$row = array( $m['id'], $m['audienceLabel'], $m['name'], genosys_club_csv_cell( $m['phone'], true ), $m['email'], $m['city'], 'active' === $m['status'] ? 'فعال' : 'لغو شده', $m['joinedText'], $m['skinLabel'], implode( '، ', $m['concerns'] ), implode( '، ', $m['categories'] ), null === $m['rating'] ? '' : $m['rating'], null === $m['nps'] ? '' : $m['nps'], $m['sourceLabel'], $m['message'], $m['clinicName'], genosys_club_csv_cell( $m['landline'], true ), $m['activityLabel'], $m['experienceLabel'], implode( '، ', $m['services'] ), implode( '، ', $m['clientNeeds'] ), $m['consumptionLabel'], $m['monthlyClientsLabel'], $m['consent'] ? 'موافق' : 'ناموافق' );\n\t\t\tforeach ( $row as $key => $value ) { if ( ! in_array( $key, array( 3, 16 ), true ) ) { $row[ $key ] = genosys_club_csv_cell( $value ); } }\n\t\t\tfputcsv( $output, $row );\n\t\t}\n\t\t++$filters['page'];\n\t} while ( count( $ids ) === 100 );\n\tfclose( $output ); exit;\n}\nadd_action( 'admin_post_genosys_club_export', 'genosys_club_export' );\n","sha256":"440d134cfd826155dc0648f1bd94b966163eefe428fae7bac14d2e189edbced1"},"inc/club-sms.php":{"content":"<?php\n/** Explicit admin-reviewed club SMS. No enrollment/read operation sends messages. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_club_sms_sender() {\n\t$sender = defined( 'GENOSYS_CLUB_SMS_SENDER' ) ? GENOSYS_CLUB_SMS_SENDER : get_option( 'genosys_club_sms_sender', '' );\n\treturn is_scalar( $sender ) && preg_match( '/^[1-9][0-9]{2,14}$/D', (string) $sender ) ? (string) $sender : '';\n}\n\nfunction genosys_club_sms_available() {\n\treturn '' !== genosys_sms_api_key() && '' !== genosys_club_sms_sender();\n}\n\nfunction genosys_club_sms_authorize() {\n\tnocache_headers();\n\tif ( 'POST' !== ( $_SERVER['REQUEST_METHOD'] ?? '' ) || ! genosys_club_can_manage() ) {\n\t\twp_send_json_error( array( 'message' => 'اجازه‌ی ارسال پیامک ندارید.' ), 403 );\n\t}\n\tcheck_ajax_referer( 'genosys_club_admin', 'nonce' );\n}\n\nfunction genosys_club_sms_settings() {\n\tgenosys_club_sms_authorize();\n\tif ( ! current_user_can( 'manage_options' ) || defined( 'GENOSYS_CLUB_SMS_SENDER' ) ) {\n\t\twp_send_json_error( array( 'message' => 'تنظیم خط ارسال توسط مدیر سایت انجام می‌شود.' ), 403 );\n\t}\n\t$sender = isset( $_POST['sender'] ) && is_string( $_POST['sender'] ) ? trim( wp_unslash( $_POST['sender'] ) ) : '';\n\tif ( ! preg_match( '/^[1-9][0-9]{2,14}$/D', $sender ) ) {\n\t\twp_send_json_error( array( 'message' => 'شماره خط ارسال SMS.ir را با ارقام انگلیسی وارد کنید.' ), 400 );\n\t}\n\tupdate_option( 'genosys_club_sms_sender', $sender, false );\n\twp_send_json_success( array( 'available' => genosys_club_sms_available(), 'message' => 'خط ارسال ذخیره شد. کلید API از تنظیمات سرویس پیامک قالب خوانده می‌شود.' ) );\n}\nadd_action( 'wp_ajax_genosys_club_sms_settings', 'genosys_club_sms_settings' );\n\nfunction genosys_club_sms_preview() {\n\tgenosys_club_sms_authorize();\n\t$filters = isset( $_POST['filters'] ) && is_string( $_POST['filters'] ) ? json_decode( wp_unslash( $_POST['filters'] ), true ) : array();\n\t$filters = is_array( $filters ) ? $filters : array();\n\t$cancelled_view = isset( $filters['status'] ) && 'cancelled' === $filters['status'];\n\t$filters['status'] = 'active';\n\t$single = isset( $_POST['member_id'] ) ? absint( $_POST['member_id'] ) : 0;\n\t$ids = $single ? array( $single ) : ( $cancelled_view ? array() : genosys_club_filtered_member_ids( $filters ) );\n\t$recipients = array();\n\tforeach ( $ids as $id ) {\n\t\t$member = genosys_club_member_data( $id, false, false );\n\t\tif ( ! is_array( $member ) || 'active' !== $member['status'] ) { continue; }\n\t\tif ( function_exists( 'genosys_account_notification_club_allowed' ) ? ! genosys_account_notification_club_allowed( $member ) : empty( $member['consent'] ) ) { continue; }\n\t\t$phone = genosys_sms_normalize_phone( $member['phone'] );\n\t\tif ( $phone && ! isset( $recipients[ $phone ] ) ) { $recipients[ $phone ] = (int) $id; }\n\t}\n\t$count = count( $recipients );\n\t$available = genosys_club_sms_available() && $count > 0 && $count <= 100;\n\t$message = $available ? 'گیرندگان بررسی شدند؛ متن را پیش از تأیید نهایی مرور کنید.' : ( $count > 100 ? 'حداکثر ۱۰۰ گیرنده در هر ارسال پشتیبانی می‌شود. با فیلترها گروه کوچک‌تری انتخاب کنید.' : ( 0 === $count ? 'عضو فعالِ موافق دریافت پیامک در این انتخاب وجود ندارد.' : 'ابتدا کلید API سرویس پیامک و شماره خط ارسال SMS.ir را تنظیم کنید.' ) );\n\t$campaign = '';\n\tif ( $available ) {\n\t\t$campaign = bin2hex( random_bytes( 16 ) );\n\t\tset_transient( 'genosys_club_sms_' . $campaign, array( 'actor' => get_current_user_id(), 'recipients' => $recipients, 'sender' => genosys_club_sms_sender(), 'created' => time() ), 15 * MINUTE_IN_SECONDS );\n\t}\n\twp_send_json_success( array( 'campaignId' => $campaign, 'count' => $count, 'available' => $available, 'message' => $message ) );\n}\nadd_action( 'wp_ajax_genosys_club_sms_preview', 'genosys_club_sms_preview' );\n\n/** Provider contract: https://github.com/cryptommer/smsir/blob/main/src/Classes/Send.php */\nfunction genosys_club_sms_request( $phones, $text, $sender ) {\n\t$result = array( 'sent' => 0, 'failed' => 0, 'unconfirmed' => count( $phones ) );\n\t$response = wp_remote_post( 'https://api.sms.ir/v1/send/bulk', array(\n\t\t'timeout' => 15, 'redirection' => 0,\n\t\t'headers' => array( 'X-API-KEY' => genosys_sms_api_key(), 'Content-Type' => 'application/json', 'Accept' => 'application/json' ),\n\t\t'body' => wp_json_encode( array( 'lineNumber' => (int) $sender, 'MessageText' => $text, 'Mobiles' => array_values( $phones ), 'SendDateTime' => null ) ),\n\t) );\n\tif ( is_wp_error( $response ) ) { return $result; }\n\t$http = (int) wp_remote_retrieve_response_code( $response );\n\t$body = json_decode( wp_remote_retrieve_body( $response ), true );\n\tif ( $http >= 400 && $http < 500 ) { return array( 'sent' => 0, 'failed' => count( $phones ), 'unconfirmed' => 0 ); }\n\tif ( $http < 200 || $http >= 300 || ! is_array( $body ) ) { return $result; }\n\t$status = $body['status'] ?? $body['Status'] ?? null;\n\t$data = $body['data'] ?? $body['Data'] ?? array();\n\t$message_ids = is_array( $data ) ? ( $data['messageIds'] ?? $data['MessageIds'] ?? null ) : null;\n\tif ( ! in_array( $status, array( 1, '1' ), true ) || ! is_array( $message_ids ) || count( $message_ids ) !== count( $phones ) ) { return $result; }\n\t$result = array( 'sent' => 0, 'failed' => 0, 'unconfirmed' => 0 );\n\tforeach ( $message_ids as $message_id ) {\n\t\tif ( ( is_int( $message_id ) || is_string( $message_id ) ) && preg_match( '/^[1-9][0-9]*$/D', (string) $message_id ) ) { ++$result['sent']; }\n\t\telseif ( null === $message_id || 0 === $message_id || '0' === $message_id ) { ++$result['failed']; }\n\t\telse { ++$result['unconfirmed']; }\n\t}\n\treturn $result;\n}\n\nfunction genosys_club_sms_send() {\n\tgenosys_club_sms_authorize();\n\t$campaign_id = isset( $_POST['campaign_id'] ) && is_string( $_POST['campaign_id'] ) ? wp_unslash( $_POST['campaign_id'] ) : '';\n\t$request_id = isset( $_POST['request_id'] ) && is_string( $_POST['request_id'] ) ? wp_unslash( $_POST['request_id'] ) : '';\n\t$text = isset( $_POST['text'] ) && is_string( $_POST['text'] ) ? trim( sanitize_textarea_field( wp_unslash( $_POST['text'] ) ) ) : '';\n\tif ( ! preg_match( '/^[a-f0-9]{32}$/D', $campaign_id ) || ! preg_match( '/^[a-f0-9]{32}$/D', $request_id ) || '' === $text || genosys_club_length( $text ) > 1000 ) {\n\t\twp_send_json_error( array( 'message' => 'متن پیامک و تأیید گیرندگان معتبر نیست.' ), 400 );\n\t}\n\t$claim_key = 'genosys_club_sms_attempt_' . $campaign_id;\n\t$previous = get_option( $claim_key );\n\tif ( is_array( $previous ) ) {\n\t\tif ( (int) $previous['actor'] !== get_current_user_id() ) { wp_send_json_error( array( 'message' => 'دسترسی مجاز نیست.' ), 403 ); }\n\t\tif ( ! hash_equals( $previous['request'], $request_id ) || ! hash_equals( $previous['textHash'], hash( 'sha256', $text ) ) ) {\n\t\t\twp_send_json_error( array( 'message' => 'متن این ارسال تغییر کرده است. ارسال قبلی را در پنل سرویس بررسی کنید.' ), 409 );\n\t\t}\n\t\tif ( isset( $previous['result'] ) ) { wp_send_json_success( $previous['result'] ); }\n\t\twp_send_json_error( array( 'message' => 'این ارسال قبلاً آغاز شده است. برای جلوگیری از پیامک تکراری، وضعیت را در پنل سرویس بررسی کنید.' ), 409 );\n\t}\n\t$campaign = get_transient( 'genosys_club_sms_' . $campaign_id );\n\tif ( ! is_array( $campaign ) || (int) $campaign['actor'] !== get_current_user_id() || ! genosys_club_sms_available() || $campaign['sender'] !== genosys_club_sms_sender() ) {\n\t\twp_send_json_error( array( 'message' => 'تأیید گیرندگان منقضی شده است. فهرست را دوباره بررسی کنید.' ), 409 );\n\t}\n\t$scopes = array(); $locks = array();\n\tforeach ( $campaign['recipients'] as $id ) {\n\t\t$record = genosys_club_member_raw( $id );\n\t\tif ( ! $record ) { wp_send_json_error( array( 'message' => 'فهرست گیرندگان تغییر کرده است. دوباره بررسی کنید.' ), 409 ); }\n\t\t$scopes[] = 'browser:' . get_post_meta( $id, '_genosys_club_owner_browser', true );\n\t\tif ( $record['userId'] ) { $scopes[] = 'user:' . (int) $record['userId']; }\n\t}\n\t$scopes = array_unique( $scopes ); sort( $scopes );\n\tforeach ( $scopes as $scope ) {\n\t\t$lock = genosys_club_lock( $scope );\n\t\tif ( ! $lock ) {\n\t\t\tforeach ( $locks as $held ) { genosys_club_unlock( $held ); }\n\t\t\twp_send_json_error( array( 'message' => 'درخواست دیگری در حال انجام است. کمی بعد تلاش کنید.' ), 409 );\n\t\t}\n\t\t$locks[] = $lock;\n\t}\n\tforeach ( $campaign['recipients'] as $phone => $id ) {\n\t\t// Scope discovery may have cached a record before a concurrent cancellation committed.\n\t\twp_cache_delete( (int) $id, 'post_meta' );\n\t\t$fresh = genosys_club_member_raw( $id );\n\t\t$required = array( 'browser:' . get_post_meta( $id, '_genosys_club_owner_browser', true ) );\n\t\tif ( $fresh && $fresh['userId'] ) { $required[] = 'user:' . (int) $fresh['userId']; }\n\t\tif ( ! $fresh || array_diff( $required, $scopes ) ) {\n\t\t\tforeach ( $locks as $held ) { genosys_club_unlock( $held ); }\n\t\t\twp_send_json_error( array( 'message' => 'مالکیت گیرندگان تغییر کرده است؛ فهرست را دوباره بررسی کنید.' ), 409 );\n\t\t}\n\t\t$member = genosys_club_member_data( $id, false, false );\n\t\tif ( ! is_array( $member ) || 'active' !== $member['status'] || genosys_sms_normalize_phone( $member['phone'] ) !== (string) $phone || ( function_exists( 'genosys_account_notification_club_allowed' ) ? ! genosys_account_notification_club_allowed( $member ) : empty( $member['consent'] ) ) ) {\n\t\t\tforeach ( $locks as $held ) { genosys_club_unlock( $held ); }\n\t\t\twp_send_json_error( array( 'message' => 'وضعیت گیرندگان تغییر کرده است؛ پیش از ارسال فهرست را دوباره بررسی کنید.' ), 409 );\n\t\t}\n\t}\n\t// Atomic durable claim precedes the only outbound request. Even ambiguous timeouts cannot auto-retry.\n\t$claim = array( 'actor' => get_current_user_id(), 'created' => time(), 'request' => $request_id, 'textHash' => hash( 'sha256', $text ) );\n\t$claimed = add_option( $claim_key, $claim, '', false );\n\tforeach ( $locks as $held ) { genosys_club_unlock( $held ); }\n\tif ( ! $claimed ) { wp_send_json_error( array( 'message' => 'ارسال قبلاً آغاز شده است.' ), 409 ); }\n\twp_schedule_single_event( time() + DAY_IN_SECONDS, 'genosys_club_sms_cleanup', array( $claim_key ) );\n\t$phones = array();\n\tforeach ( $campaign['recipients'] as $phone => $id ) {\n\t\t$member = genosys_club_member_data( $id, false, false );\n\t\tif ( function_exists( 'genosys_account_notification_club_allowed' ) ? genosys_account_notification_club_allowed( $member ) : ( is_array( $member ) && 'active' === $member['status'] && ! empty( $member['consent'] ) ) ) { $phones[] = (string) $phone; }\n\t}\n\t$result = $phones ? genosys_club_sms_request( $phones, $text, $campaign['sender'] ) : array( 'sent' => 0, 'failed' => 0, 'unconfirmed' => 0 );\n\t$result['message'] = sprintf( 'پذیرفته‌شده توسط سرویس: %d؛ ناموفق: %d؛ وضعیت نامشخص: %d. پذیرش سرویس به معنی تحویل قطعی نیست.', $result['sent'], $result['failed'], $result['unconfirmed'] );\n\t$claim['result'] = $result;\n\tupdate_option( $claim_key, $claim, false );\n\tdelete_transient( 'genosys_club_sms_' . $campaign_id );\n\twp_send_json_success( $result );\n}\nadd_action( 'wp_ajax_genosys_club_sms_send', 'genosys_club_sms_send' );\n\nfunction genosys_club_sms_cleanup( $key ) {\n\tif ( is_string( $key ) && preg_match( '/^genosys_club_sms_attempt_[a-f0-9]{32}$/D', $key ) ) { delete_option( $key ); }\n}\nadd_action( 'genosys_club_sms_cleanup', 'genosys_club_sms_cleanup' );\n","sha256":"2f4aed2e00b50e137673ff3eef6c8398b491fa1e2d61f6300c3d2476b222be80"},"inc/company.php":{"content":"<?php\n/** Serve the company introduction immediately, with or without a saved WordPress Page. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_company_request_path() {\n\tif ( is_admin() || empty( $_SERVER['REQUEST_URI'] ) || ! is_string( $_SERVER['REQUEST_URI'] ) ) { return false; }\n\t$request = wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH );\n\t$company = wp_parse_url( home_url( '/company/' ), PHP_URL_PATH );\n\treturn is_string( $request ) && is_string( $company ) && untrailingslashit( $request ) === untrailingslashit( $company );\n}\n\nfunction genosys_register_company_route() {\n\tadd_rewrite_rule( '^company/?$', 'index.php?genosys_company=1', 'top' );\n\tif ( '1' !== get_option( 'genosys_company_route_v1' ) ) {\n\t\tflush_rewrite_rules( false );\n\t\tupdate_option( 'genosys_company_route_v1', '1', false );\n\t}\n}\nadd_action( 'init', 'genosys_register_company_route', 20 );\n\nfunction genosys_company_query_vars( $vars ) {\n\t$vars[] = 'genosys_company';\n\treturn $vars;\n}\nadd_filter( 'query_vars', 'genosys_company_query_vars' );\n\n/** Match the physical URL too, including plain and subdirectory permalink installations. */\nfunction genosys_company_parse_request( $wp ) {\n\tif ( ! genosys_company_request_path() ) { return; }\n\tforeach ( array( 'error', 'p', 'page_id', 'attachment_id', 'name', 'pagename', 's' ) as $key ) { unset( $wp->query_vars[ $key ] ); }\n\t$wp->query_vars['genosys_company'] = '1';\n}\nadd_action( 'parse_request', 'genosys_company_parse_request', 99 );\n\nfunction genosys_is_company() {\n\treturn genosys_company_request_path() && '1' === (string) get_query_var( 'genosys_company' );\n}\n\nfunction genosys_company_main_query( $query ) {\n\tif ( ! $query->is_main_query() || ! genosys_company_request_path() || '1' !== (string) $query->get( 'genosys_company' ) ) { return; }\n\t$query->is_home = false;\n\t$query->is_404 = false;\n\t$query->set( 'post__in', array( 0 ) );\n\t$query->set( 'posts_per_page', 1 );\n\t$query->set( 'ignore_sticky_posts', true );\n}\nadd_action( 'parse_query', 'genosys_company_main_query' );\n\nfunction genosys_company_pre_handle_404( $preempt, $query ) {\n\tif ( $query->is_main_query() && genosys_company_request_path() && '1' === (string) $query->get( 'genosys_company' ) ) {\n\t\t$query->is_404 = false;\n\t\tstatus_header( 200 );\n\t\treturn true;\n\t}\n\treturn $preempt;\n}\nadd_filter( 'pre_handle_404', 'genosys_company_pre_handle_404', 10, 2 );\n\nfunction genosys_company_template( $template ) {\n\treturn genosys_is_company() ? get_theme_file_path( '/page-company.php' ) : $template;\n}\nadd_filter( 'template_include', 'genosys_company_template', 99 );\n\nfunction genosys_company_document_title( $title ) {\n\treturn genosys_is_company() ? 'شرکت ژنوسیس | ' . get_bloginfo( 'name' ) : $title;\n}\nadd_filter( 'pre_get_document_title', 'genosys_company_document_title' );\n\nfunction genosys_company_canonical_redirect( $redirect ) {\n\treturn genosys_is_company() ? false : $redirect;\n}\nadd_filter( 'redirect_canonical', 'genosys_company_canonical_redirect' );\n\nfunction genosys_company_body_class( $classes ) {\n\tif ( genosys_is_company() ) { $classes[] = 'genosys-company-page'; }\n\treturn $classes;\n}\nadd_filter( 'body_class', 'genosys_company_body_class' );\n","sha256":"28134984b64e6bd96130a05916bda12172f36eaba58dfae090497bf0ed622ecf"},"inc/contact-route.php":{"content":"<?php\n/** The contact page is available immediately, including without a saved Page. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_contact_request_path() {\n\tif ( is_admin() || empty( $_SERVER['REQUEST_URI'] ) || ! is_string( $_SERVER['REQUEST_URI'] ) ) { return false; }\n\t$request = wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH );\n\t$contact = wp_parse_url( home_url( '/contact/' ), PHP_URL_PATH );\n\treturn is_string( $request ) && is_string( $contact ) && untrailingslashit( $request ) === untrailingslashit( $contact );\n}\n\nfunction genosys_register_contact_route() {\n\tadd_rewrite_rule( '^contact/?$', 'index.php?genosys_contact=1', 'top' );\n\tif ( '1' !== get_option( 'genosys_contact_route_v1' ) ) {\n\t\tflush_rewrite_rules( false );\n\t\tupdate_option( 'genosys_contact_route_v1', '1', false );\n\t}\n}\nadd_action( 'init', 'genosys_register_contact_route', 20 );\n\nfunction genosys_contact_query_vars( $vars ) {\n\t$vars[] = 'genosys_contact';\n\treturn $vars;\n}\nadd_filter( 'query_vars', 'genosys_contact_query_vars' );\n\n/** Match the physical URL as well as the rewrite, including plain permalinks. */\nfunction genosys_contact_parse_request( $wp ) {\n\tif ( ! genosys_contact_request_path() ) { return; }\n\tforeach ( array( 'error', 'p', 'page_id', 'attachment_id', 'name', 'pagename', 's' ) as $key ) { unset( $wp->query_vars[ $key ] ); }\n\t$wp->query_vars['genosys_contact'] = '1';\n}\nadd_action( 'parse_request', 'genosys_contact_parse_request', 99 );\n\nfunction genosys_is_contact() {\n\treturn genosys_contact_request_path() && '1' === (string) get_query_var( 'genosys_contact' );\n}\n\nfunction genosys_contact_main_query( $query ) {\n\tif ( ! $query->is_main_query() || ! genosys_contact_request_path() || '1' !== (string) $query->get( 'genosys_contact' ) ) { return; }\n\t$query->is_home = false;\n\t$query->is_404 = false;\n\t$query->set( 'post__in', array( 0 ) );\n\t$query->set( 'posts_per_page', 1 );\n\t$query->set( 'ignore_sticky_posts', true );\n}\nadd_action( 'parse_query', 'genosys_contact_main_query' );\n\nfunction genosys_contact_pre_handle_404( $preempt, $query ) {\n\tif ( $query->is_main_query() && genosys_contact_request_path() && '1' === (string) $query->get( 'genosys_contact' ) ) {\n\t\t$query->is_404 = false;\n\t\tstatus_header( 200 );\n\t\treturn true;\n\t}\n\treturn $preempt;\n}\nadd_filter( 'pre_handle_404', 'genosys_contact_pre_handle_404', 10, 2 );\n\nfunction genosys_contact_template( $template ) {\n\treturn genosys_is_contact() ? get_theme_file_path( '/page-contact.php' ) : $template;\n}\nadd_filter( 'template_include', 'genosys_contact_template', 99 );\n\nfunction genosys_contact_document_title( $title ) {\n\treturn genosys_is_contact() ? genosys_site_setting( 'contact_page_title', 'تماس با ما' ) . ' | ' . get_bloginfo( 'name' ) : $title;\n}\nadd_filter( 'pre_get_document_title', 'genosys_contact_document_title' );\n\nfunction genosys_contact_canonical_redirect( $redirect ) {\n\treturn genosys_is_contact() ? false : $redirect;\n}\nadd_filter( 'redirect_canonical', 'genosys_contact_canonical_redirect' );\n\nfunction genosys_contact_body_class( $classes ) {\n\tif ( genosys_is_contact() ) { $classes[] = 'genosys-contact-page'; }\n\treturn $classes;\n}\nadd_filter( 'body_class', 'genosys_contact_body_class' );\n\nfunction genosys_contact_no_cache() {\n\tif ( genosys_is_contact() ) { nocache_headers(); }\n}\nadd_action( 'template_redirect', 'genosys_contact_no_cache', 1 );\n","sha256":"44a3b4dc7f621776e37d5358fcb943ac1fc0864e19febb45d25a0819c42d29ec"},"inc/contact-settings.php":{"content":"<?php\n/** Contact fields are part of the existing theme-settings save transaction. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_contact_settings_types() {\n\t$types = array();\n\tforeach ( genosys_contact_defaults() as $key=>$value ) { if ( ! is_array($value) ) { $types[$key]='text'; } }\n\tforeach ( array('contact_description_line1','contact_description_line2','contact_address','contact_form_description','contact_form_success','contact_faq_description') as $key ) { $types[$key]='textarea'; }\n\tforeach ( array('phone','whatsapp','telegram','email') as $channel ) { $types['contact_'.$channel.'_url']='contact_link'; }\n\tforeach ( array('instagram','telegram','whatsapp','linkedin') as $network ) { $types['contact_social_'.$network]='url'; }\n\t$types['contact_privacy_url']='url';\n\t$types['contact_notification_enabled']='bool';\n\t$types['contact_notification_email']='contact_email';\n\treturn $types;\n}\n\nfunction genosys_contact_settings_sanitize( $input, $result, $previous, $defaults ) {\n\tforeach ( genosys_contact_settings_types() as $key=>$type ) {\n\t\tif ( ! array_key_exists($key,$input) ) { continue; }\n\t\t$old=$previous[$key]??($defaults[$key]??'');\n\t\tif ( ! is_scalar($input[$key]) || is_bool($input[$key]) ) { genosys_settings_invalid($key); continue; }\n\t\t$value=trim((string)$input[$key]);\n\t\tif ( 'contact_link'===$type ) {\n\t\t\t$clean=genosys_contact_link($value,array('http','https','tel','mailto'));\n\t\t\tif(''!==$value&&(''===$clean||strlen($clean)>2000)){genosys_settings_invalid($key);continue;}\n\t\t\t$result[$key]=$clean;\n\t\t} elseif ( 'contact_email'===$type ) {\n\t\t\tif(''!==$value&&(!is_email($value)||strlen($value)>254)){genosys_settings_invalid($key);continue;}\n\t\t\t$result[$key]=sanitize_email($value);\n\t\t} else { $result[$key]=genosys_settings_clean_value($value,$type,$key,$old); }\n\t}\n\tif ( array_key_exists('contact_hours',$input) ) {\n\t\tif ( ! is_array($input['contact_hours']) || 7!==count($input['contact_hours']) ) { genosys_settings_invalid('ساعات پاسخگویی'); }\n\t\telse {\n\t\t\t$old=$previous['contact_hours']??$defaults['contact_hours'];$rows=array();$valid=true;\n\t\t\tforeach($defaults['contact_hours'] as $index=>$base){\n\t\t\t\t$row=$input['contact_hours'][$index]??null;\n\t\t\t\tif(!is_array($row)||!is_string($row['label']??null)||!is_string($row['open']??null)||!is_string($row['close']??null)||!is_scalar($row['closed']??null)){ $valid=false; break; }\n\t\t\t\t$open=genosys_contact_ascii($row['open']);$close=genosys_contact_ascii($row['close']);$closed=(string)$row['closed'];\n\t\t\t\tif(!genosys_contact_time_valid($open)||!genosys_contact_time_valid($close)||!in_array($closed,array('0','1'),true)||('0'===$closed&&$open>=$close)){ $valid=false;break; }\n\t\t\t\t$label=sanitize_text_field($row['label']);\n\t\t\t\tif(''===$label||genosys_contact_length($label)>40){$valid=false;break;}\n\t\t\t\t$rows[]=array('label'=>$label,'open'=>$open,'close'=>$close,'closed'=>(int)$closed);\n\t\t\t}\n\t\t\tif($valid){$result['contact_hours']=$rows;}else{genosys_settings_invalid('ساعات پاسخگویی؛ پایان هر روز کاری باید بعد از شروع باشد');}\n\t\t}\n\t}\n\t$faq_present=isset($input['contact_faq_present'])&&is_string($input['contact_faq_present'])&&'1'===$input['contact_faq_present'];\n\tif ( array_key_exists('contact_faq',$input) ) {\n\t\tif(!is_array($input['contact_faq'])||count($input['contact_faq'])>30){genosys_settings_invalid('سؤال‌های رایج');}\n\t\telse{\n\t\t\t$rows=array();$valid=true;\n\t\t\tforeach(array_values($input['contact_faq']) as $row){\n\t\t\t\tif(!is_array($row)||!is_string($row['question']??null)||!is_string($row['answer']??null)){$valid=false;break;}\n\t\t\t\t$question=sanitize_text_field($row['question']);$answer=sanitize_textarea_field($row['answer']);\n\t\t\t\tif(''===$question&&''===$answer){continue;}\n\t\t\t\tif(''===$question||''===$answer||genosys_contact_length($question)>300||genosys_contact_length($answer)>3000){$valid=false;break;}\n\t\t\t\t$rows[]=array('question'=>$question,'answer'=>$answer);\n\t\t\t}\n\t\t\tif($valid){$result['contact_faq']=$rows;}else{genosys_settings_invalid('پرسش و پاسخ کامل؛ پرسش حداکثر ۳۰۰ و پاسخ حداکثر ۳۰۰۰ نویسه');}\n\t\t}\n\t} elseif ( $faq_present ) { $result['contact_faq']=array(); }\n\treturn $result;\n}\n\nfunction genosys_contact_settings_faq_row( $index, $row ) {\n\techo '<div class=\"gs-repeater__row\"><div style=\"flex:1;min-width:0\">';\n\tgenosys_settings_field('contact-faq-question-'.$index,'پرسش','text',array('name'=>'site[contact_faq]['.$index.'][question]','value'=>$row['question']??'','hint'=>'حداکثر ۳۰۰ نویسه'));\n\tgenosys_settings_field('contact-faq-answer-'.$index,'پاسخ','textarea',array('name'=>'site[contact_faq]['.$index.'][answer]','value'=>$row['answer']??'','hint'=>'متن ساده، حداکثر ۳۰۰۰ نویسه؛ شکست خط در سایت حفظ می‌شود.'));\n\techo '</div><button type=\"button\" class=\"gs-icon-button gs-danger\" data-remove-row aria-label=\"حذف پرسش و پاسخ\">'.genosys_settings_icon('trash').'</button></div>';\n}\n\nfunction genosys_render_contact_settings() {\n\tgenosys_settings_card_open('صفحه تماس با ما','مقادیر این بخش در /contact/ نمایش داده می‌شوند. شماره‌ها، نشانی و شبکه‌های اجتماعی را با اطلاعات واقعی مجموعه تکمیل کنید.');\n\techo '<div class=\"gs-card__actions\">';genosys_settings_link(home_url('/contact/'),'مشاهده صفحه تماس');genosys_settings_link(admin_url('admin.php?page=genosys-contact-messages'),'پیام‌های دریافت‌شده');echo '</div><div class=\"gs-grid\">';\n\tforeach(array('contact_page_title'=>'عنوان صفحه در مرورگر','contact_hero_before'=>'ابتدای عنوان','contact_hero_highlight'=>'بخش رنگی عنوان','contact_hero_after'=>'ادامه عنوان','contact_description_line1'=>'خط اول معرفی','contact_description_line2'=>'خط دوم معرفی','contact_copy_label'=>'متن دکمه کپی','contact_copied_label'=>'متن پس از کپی','contact_empty_label'=>'متن اطلاعات تکمیل‌نشده') as $key=>$label){genosys_settings_field($key,$label);}\n\techo '</div></section>';\n\tgenosys_settings_card_open('راه‌های ارتباطی','پیوند اختیاری است؛ با خالی گذاشتن آن، تماس، ایمیل، تلگرام و واتساپ از مقدار واردشده ساخته می‌شوند. اطلاعات خالی، دکمه فعال نخواهد داشت.');\n\tforeach(array('phone'=>'تلفن پشتیبانی','whatsapp'=>'واتساپ','telegram'=>'تلگرام','email'=>'ایمیل') as $channel=>$label){echo '<div class=\"gs-editor-row\"><h3>'.esc_html($label).'</h3><div class=\"gs-grid\">';genosys_settings_field('contact_'.$channel.'_label','عنوان کارت');genosys_settings_field('contact_'.$channel.'_value','شماره / شناسه / نشانی','text',array('ltr'=>true));genosys_settings_field('contact_'.$channel.'_button','متن دکمه');genosys_settings_field('contact_'.$channel.'_url','پیوند اختیاری','text',array('ltr'=>true,'hint'=>'پیوند کامل https://، tel: یا mailto:'));echo '</div></div>';}\n\techo '</section>';\n\tgenosys_settings_card_open('ساعات پاسخگویی','نشان وضعیت بر اساس ساعت و منطقه زمانی تنظیم‌شده در وردپرس محاسبه می‌شود. پایان کار هر روز باید پس از شروع همان روز باشد.');echo '<div class=\"gs-grid\">';\n\tforeach(array('contact_hours_title'=>'عنوان کادر ساعات','contact_today_label'=>'متن امروز','contact_hours_closed'=>'متن روز تعطیل','contact_status_open'=>'وضعیت در ساعات پاسخگویی','contact_status_closed'=>'وضعیت خارج از ساعات پاسخگویی','contact_status_open_detail'=>'توضیح وضعیت باز','contact_status_closed_detail'=>'توضیح وضعیت بسته') as $key=>$label){genosys_settings_field($key,$label,'text',array('hint'=>'contact_status_open_detail'===$key?'برای ساعت پایان کار از {time} استفاده کنید.':''));}\n\techo '</div>';\n\t$hours=genosys_contact_page_data()['hours'];\n\tforeach($hours as $index=>$row){echo '<div class=\"gs-editor-row\"><div class=\"gs-grid\">';genosys_settings_field('contact-hour-label-'.$index,'روز هفته','text',array('name'=>'site[contact_hours]['.$index.'][label]','value'=>$row['label']));genosys_settings_field('contact-hour-closed-'.$index,'وضعیت','select',array('name'=>'site[contact_hours]['.$index.'][closed]','value'=>$row['closed']?1:0,'options'=>array(0=>'روز کاری',1=>'تعطیل')));genosys_settings_field('contact-hour-open-'.$index,'شروع پاسخگویی','time',array('name'=>'site[contact_hours]['.$index.'][open]','value'=>$row['open'],'ltr'=>true));genosys_settings_field('contact-hour-close-'.$index,'پایان پاسخگویی','time',array('name'=>'site[contact_hours]['.$index.'][close]','value'=>$row['close'],'ltr'=>true));echo '</div></div>';}\n\techo '</section>';\n\tgenosys_settings_card_open('دفتر و شبکه‌های اجتماعی','پیوند خالی، آیکن آن شبکه را پنهان می‌کند.');echo '<div class=\"gs-grid\">';\n\tforeach(array('contact_address_label'=>'عنوان نشانی دفتر','contact_address'=>'نشانی دفتر','contact_postal_label'=>'عنوان کد پستی','contact_postal'=>'کد پستی') as $key=>$label){genosys_settings_field($key,$label,'contact_address'===$key?'textarea':'text');}\n\tforeach(array('instagram'=>'اینستاگرام','telegram'=>'تلگرام','whatsapp'=>'واتساپ','linkedin'=>'لینکدین') as $network=>$label){genosys_settings_field('contact_social_'.$network,'پیوند '.$label,'url');}echo '</div></section>';\n\tgenosys_settings_card_open('فرم تماس','پیام‌های واقعی و پیوست‌ها در صندوق خصوصی مدیر ذخیره می‌شوند. تصویر JPG، PNG، WebP یا PDF تا ۵ مگابایت پذیرفته می‌شود.');echo '<div class=\"gs-grid\">';\n\tforeach(array('contact_form_title'=>'عنوان فرم','contact_form_description'=>'توضیح فرم','contact_topic_label'=>'عنوان موضوع','contact_topic_support'=>'موضوع پشتیبانی','contact_topic_consultation'=>'موضوع مشاوره','contact_topic_partnership'=>'موضوع همکاری','contact_topic_feedback'=>'موضوع پیشنهاد و انتقاد','contact_topic_other'=>'موضوع سایر','contact_name_label'=>'راهنمای نام','contact_mobile_label'=>'راهنمای موبایل','contact_email_input_label'=>'راهنمای ایمیل','contact_message_label'=>'راهنمای پیام','contact_attachment_label'=>'عنوان پیوست','contact_attachment_hint'=>'توضیح پیوست','contact_consent_before'=>'متن قبل از پیوند حریم خصوصی','contact_privacy_label'=>'متن پیوند حریم خصوصی','contact_consent_after'=>'متن بعد از پیوند حریم خصوصی','contact_submit_label'=>'متن دکمه ارسال','contact_form_success'=>'پیام ثبت موفق') as $key=>$label){genosys_settings_field($key,$label,in_array($key,array('contact_form_description','contact_form_success'),true)?'textarea':'text');}\n\tgenosys_settings_field('contact_privacy_url','پیوند حریم خصوصی','url',array('hint'=>'خالی یعنی صفحه حریم خصوصی انتخاب‌شده در تنظیمات وردپرس.'));\n\tgenosys_settings_field('contact_notification_enabled','اعلان ایمیلی مدیر','select',array('options'=>array(0=>'غیرفعال',1=>'فعال'),'hint'=>'ارسال ایمیل تنها پس از ثبت پیام انجام می‌شود؛ خود پیام همیشه در صندوق خصوصی نگهداری می‌شود.'));\n\tgenosys_settings_field('contact_notification_email','ایمیل دریافت اعلان','email',array('ltr'=>true,'hint'=>'هیچ اطلاعات خصوصی یا فایل پیوستی در اعلان ارسال نمی‌شود.'));echo '</div></section>';\n\tgenosys_settings_card_open('سؤال‌های رایج','تا ۳۰ پرسش و پاسخ اضافه کنید. حذف همه ردیف‌ها، فهرست سؤال‌های صفحه را خالی می‌کند.');echo '<div class=\"gs-grid\">';\n\tforeach(array('contact_faq_before'=>'ابتدای عنوان','contact_faq_highlight'=>'بخش رنگی عنوان','contact_faq_after'=>'ادامه عنوان','contact_faq_description'=>'توضیح بخش') as $key=>$label){genosys_settings_field($key,$label);}echo '</div>';\n\techo '<input type=\"hidden\" name=\"site[contact_faq_present]\" value=\"1\"><div class=\"gs-repeater gs-spacing\" data-repeater=\"contact_faq\" data-max-rows=\"30\"><div class=\"gs-repeater__rows\">';\n\tforeach(genosys_contact_setting('faq') as $index=>$row){genosys_contact_settings_faq_row($index,$row);}\n\techo '</div><p class=\"gs-empty\"'.(genosys_contact_setting('faq')?' hidden':'').'>هنوز پرسشی اضافه نشده است.</p><template data-row-template>';genosys_contact_settings_faq_row('__INDEX__',array());echo '</template><button type=\"button\" class=\"gs-outline\" data-add-row>+ افزودن پرسش و پاسخ</button></div></section>';\n}\n","sha256":"facadf97a7157ad7ec126f6821dce9f88defc20dd1b49f35c8c1a3823761f817"},"inc/contact.php":{"content":"<?php\n/** Contact presentation and a private, local message inbox. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_contact_defaults() {\n\treturn array(\n\t\t'contact_page_title'=>'تماس با ما',\n\t\t'contact_hero_before'=>'با ما در', 'contact_hero_highlight'=>'تماس', 'contact_hero_after'=>'باشید',\n\t\t'contact_description_line1'=>'سؤال، پیشنهاد یا نیاز به مشاوره‌ی تخصصی پوست و مو دارید؟ تیم ژنوسیس',\n\t\t'contact_description_line2'=>'همین‌جاست؛ از هر راهی که راحت‌ترید با ما در ارتباط باشید.',\n\t\t'contact_status_open'=>'هم‌اکنون پاسخگو هستیم', 'contact_status_closed'=>'اکنون خارج از ساعات پاسخگویی هستیم',\n\t\t'contact_status_open_detail'=>'تا ساعت {time} امروز', 'contact_status_closed_detail'=>'در ساعات پاسخگویی همراه شما هستیم',\n\t\t'contact_phone_label'=>'تلفن پشتیبانی', 'contact_phone_value'=>'', 'contact_phone_button'=>'تماس', 'contact_phone_url'=>'',\n\t\t'contact_whatsapp_label'=>'واتساپ', 'contact_whatsapp_value'=>'', 'contact_whatsapp_button'=>'شروع گفتگو', 'contact_whatsapp_url'=>'',\n\t\t'contact_telegram_label'=>'تلگرام', 'contact_telegram_value'=>'', 'contact_telegram_button'=>'ارسال پیام', 'contact_telegram_url'=>'',\n\t\t'contact_email_label'=>'ایمیل', 'contact_email_value'=>'', 'contact_email_button'=>'ارسال ایمیل', 'contact_email_url'=>'',\n\t\t'contact_copy_label'=>'کپی', 'contact_copied_label'=>'کپی شد', 'contact_empty_label'=>'به‌زودی اعلام می‌شود',\n\t\t'contact_hours_title'=>'ساعات پاسخگویی', 'contact_hours_closed'=>'تعطیل', 'contact_today_label'=>'امروز',\n\t\t'contact_hours'=>array(\n\t\t\tarray('label'=>'شنبه','open'=>'09:00','close'=>'18:00','closed'=>0),\n\t\t\tarray('label'=>'یکشنبه','open'=>'09:00','close'=>'18:00','closed'=>0),\n\t\t\tarray('label'=>'دوشنبه','open'=>'09:00','close'=>'18:00','closed'=>0),\n\t\t\tarray('label'=>'سه‌شنبه','open'=>'09:00','close'=>'18:00','closed'=>0),\n\t\t\tarray('label'=>'چهارشنبه','open'=>'09:00','close'=>'18:00','closed'=>0),\n\t\t\tarray('label'=>'پنجشنبه','open'=>'09:00','close'=>'14:00','closed'=>0),\n\t\t\tarray('label'=>'جمعه','open'=>'09:00','close'=>'18:00','closed'=>1),\n\t\t),\n\t\t'contact_address_label'=>'نشانی دفتر مرکزی', 'contact_address'=>'', 'contact_postal_label'=>'کد پستی', 'contact_postal'=>'',\n\t\t'contact_social_instagram'=>'', 'contact_social_telegram'=>'', 'contact_social_whatsapp'=>'', 'contact_social_linkedin'=>'',\n\t\t'contact_form_title'=>'پیامتان را برای ما بنویسید', 'contact_form_description'=>'معمولاً ظرف چند ساعت کاری پاسخ می‌دهیم.',\n\t\t'contact_topic_label'=>'موضوع پیام', 'contact_topic_support'=>'پشتیبانی سفارش', 'contact_topic_consultation'=>'مشاوره‌ی پوست و مو',\n\t\t'contact_topic_partnership'=>'همکاری و نمایندگی', 'contact_topic_feedback'=>'پیشنهاد و انتقاد', 'contact_topic_other'=>'سایر',\n\t\t'contact_name_label'=>'نام و نام خانوادگی', 'contact_mobile_label'=>'شماره موبایل', 'contact_email_input_label'=>'ایمیل (اختیاری)',\n\t\t'contact_message_label'=>'پیام شما', 'contact_attachment_label'=>'پیوست فایل (اختیاری)',\n\t\t'contact_attachment_hint'=>'تصویر یا PDF تا ۵ مگابایت', 'contact_consent_before'=>'با ثبت پیام،',\n\t\t'contact_privacy_label'=>'قوانین حریم خصوصی', 'contact_consent_after'=>'را می‌پذیرم.', 'contact_privacy_url'=>'',\n\t\t'contact_submit_label'=>'ارسال پیام', 'contact_form_success'=>'پیام شما با موفقیت ثبت شد. همکاران ما در ساعات پاسخگویی با شما تماس می‌گیرند.',\n\t\t'contact_notification_enabled'=>0, 'contact_notification_email'=>'',\n\t\t'contact_faq_before'=>'پاسخ', 'contact_faq_highlight'=>'سؤال‌های', 'contact_faq_after'=>'رایج',\n\t\t'contact_faq_description'=>'شاید پاسخ شما همین‌جا باشد.',\n\t\t'contact_faq'=>array(\n\t\t\tarray('question'=>'سفارش من چه زمانی ارسال می‌شود؟','answer'=>'برای اطلاع از وضعیت و زمان ارسال سفارش خود، بخش «سفارشات من» در حساب کاربری را بررسی کنید یا با پشتیبانی در ارتباط باشید.'),\n\t\t\tarray('question'=>'چطور فیش واریزی را ارسال کنم؟','answer'=>'وارد حساب کاربری شوید و در بخش «سفارشات من»، جزئیات سفارش را باز کنید. اگر سفارش امکان بارگذاری فیش داشته باشد، فایل فیش را از همان بخش ارسال کنید.'),\n\t\t\tarray('question'=>'محصولات اصل هستند؟','answer'=>'برای دریافت اطلاعات اصالت، مشخصات و روش استفاده‌ی هر محصول با تیم پشتیبانی تماس بگیرید.'),\n\t\t\tarray('question'=>'برای مشاوره‌ی تخصصی پوست و مو چه کنم؟','answer'=>'در فرم همین صفحه، موضوع «مشاوره‌ی پوست و مو» را انتخاب کنید و پرسش خود را برای ما بنویسید.'),\n\t\t\tarray('question'=>'چگونه به باشگاه مشتریان بپیوندم؟','answer'=>'از بخش «باشگاه مشتریان» سایت، نوع عضویت خود را انتخاب و پرسشنامه را تکمیل کنید.'),\n\t\t),\n\t);\n}\n\nfunction genosys_contact_setting( $key ) {\n\t$key = 0 === strpos( $key, 'contact_' ) ? $key : 'contact_' . $key;\n\t$defaults = genosys_contact_defaults();\n\treturn genosys_site_setting( $key, $defaults[ $key ] ?? '' );\n}\n\nfunction genosys_contact_ascii( $value ) {\n\treturn strtr( (string) $value, array('۰'=>'0','۱'=>'1','۲'=>'2','۳'=>'3','۴'=>'4','۵'=>'5','۶'=>'6','۷'=>'7','۸'=>'8','۹'=>'9','٠'=>'0','١'=>'1','٢'=>'2','٣'=>'3','٤'=>'4','٥'=>'5','٦'=>'6','٧'=>'7','٨'=>'8','٩'=>'9') );\n}\n\nfunction genosys_contact_digits( $value ) {\n\treturn strtr( (string) $value, array('0'=>'۰','1'=>'۱','2'=>'۲','3'=>'۳','4'=>'۴','5'=>'۵','6'=>'۶','7'=>'۷','8'=>'۸','9'=>'۹') );\n}\n\nfunction genosys_contact_length( $value ) {\n\treturn function_exists( 'mb_strlen' ) ? mb_strlen( $value, 'UTF-8' ) : preg_match_all( '/./us', $value, $unused );\n}\n\nfunction genosys_contact_time_valid( $value ) {\n\treturn is_string( $value ) && (bool) preg_match( '/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/D', $value );\n}\n\nfunction genosys_contact_link( $value, $schemes = array( 'http', 'https' ) ) {\n\tif ( ! is_string( $value ) || '' === trim( $value ) ) { return ''; }\n\t$value = trim( $value );\n\t$scheme = strtolower( (string) wp_parse_url( $value, PHP_URL_SCHEME ) );\n\tif ( ! in_array( $scheme, $schemes, true ) ) { return ''; }\n\tif ( in_array( $scheme, array('http','https'), true ) && ( ! preg_match('~^https?://~i',$value) || ! wp_parse_url($value,PHP_URL_HOST) ) ) { return ''; }\n\tif ( 'tel' === $scheme && ! preg_match('/^tel:\\+?[0-9() .-]{6,30}$/Di',$value) ) { return ''; }\n\tif ( 'mailto' === $scheme && ! is_email( substr($value,7) ) ) { return ''; }\n\treturn esc_url_raw( $value, $schemes );\n}\n\n/** This model is shared by the contact template and public form validation. */\nfunction genosys_contact_page_data( $at = null ) {\n\t$data = array();\n\tforeach ( array('hero_before','hero_highlight','hero_after','description_line1','description_line2','copy_label','copied_label','empty_label','hours_title','today_label','address_label','address','postal_label','postal') as $key ) { $data[ $key ] = (string) genosys_contact_setting( $key ); }\n\t$data['channels'] = array();\n\tforeach ( array('phone','whatsapp','telegram','email') as $channel ) {\n\t\t$value = (string) genosys_contact_setting( $channel . '_value' );\n\t\t$url = genosys_contact_link( genosys_contact_setting( $channel . '_url' ), array('http','https','tel','mailto') );\n\t\tif ( ! $url && '' !== $value ) {\n\t\t\t$number = preg_replace( '/[^0-9+]/', '', genosys_contact_ascii( $value ) );\n\t\t\tif ( 'phone' === $channel && preg_match( '/^\\+?[0-9]{6,16}$/D', $number ) ) { $url = 'tel:' . $number; }\n\t\t\tif ( 'email' === $channel && is_email( $value ) ) { $url = 'mailto:' . sanitize_email( $value ); }\n\t\t\tif ( 'telegram' === $channel && preg_match( '/^@?([A-Za-z][A-Za-z0-9_]{3,31})$/D', $value, $matches ) ) { $url = 'https://t.me/' . $matches[1]; }\n\t\t\tif ( 'whatsapp' === $channel ) {\n\t\t\t\t$number = ltrim( $number, '+' );\n\t\t\t\tif ( 0 === strpos( $number, '00' ) ) { $number = substr( $number, 2 ); }\n\t\t\t\tif ( preg_match( '/^09[0-9]{9}$/D', $number ) ) { $number = '98' . substr( $number, 1 ); }\n\t\t\t\tif ( preg_match( '/^[1-9][0-9]{7,14}$/D', $number ) ) { $url = 'https://wa.me/' . $number; }\n\t\t\t}\n\t\t}\n\t\t$data['channels'][ $channel ] = array('label'=>(string)genosys_contact_setting($channel.'_label'),'value'=>$value,'button'=>(string)genosys_contact_setting($channel.'_button'),'url'=>$url,'copy'=>$value,'placeholder'=>$data['empty_label']);\n\t}\n\t$defaults = genosys_contact_defaults();\n\t$hours = genosys_contact_setting( 'hours' );\n\t$now = $at instanceof DateTimeInterface ? (new DateTimeImmutable( $at->format( 'Y-m-d H:i:s.u' ), $at->getTimezone() ))->setTimezone( wp_timezone() ) : current_datetime();\n\t$today = ( (int) $now->format( 'w' ) + 1 ) % 7;\n\t$time = $now->format( 'H:i' );\n\t$data['hours'] = array();\n\t$is_open = false;\n\t$closing = '';\n\tforeach ( $defaults['contact_hours'] as $index => $base ) {\n\t\t$row = isset( $hours[ $index ] ) && is_array( $hours[ $index ] ) ? $hours[ $index ] : $base;\n\t\t$open = genosys_contact_time_valid( $row['open'] ?? null ) ? $row['open'] : $base['open'];\n\t\t$close = genosys_contact_time_valid( $row['close'] ?? null ) ? $row['close'] : $base['close'];\n\t\t$closed = ! empty( $row['closed'] ) || $open >= $close;\n\t\t$format = static function( $clock ) { $hour = (string) (int) substr( $clock, 0, 2 ); return genosys_contact_digits( ':00' === substr( $clock, -3 ) ? $hour : $hour . ':' . substr( $clock, 3, 2 ) ); };\n\t\t$data['hours'][] = array('day'=>$index,'label'=>is_string($row['label']??null)?$row['label']:$base['label'],'open'=>$open,'close'=>$close,'closed'=>$closed,'today'=>$index===$today,'today_label'=>$data['today_label'],'text'=>$closed?(string)genosys_contact_setting('hours_closed'):$format($open).' تا '.$format($close));\n\t\tif ( $index === $today ) { $is_open = ! $closed && $time >= $open && $time < $close; $closing = $format( $close ); }\n\t}\n\t$data['status'] = array('open'=>$is_open,'label'=>(string)genosys_contact_setting($is_open?'status_open':'status_closed'),'detail'=>str_replace('{time}',$closing,(string)genosys_contact_setting($is_open?'status_open_detail':'status_closed_detail')));\n\t$data['socials'] = array();\n\tforeach ( array('instagram','telegram','whatsapp','linkedin') as $network ) { $data['socials'][$network] = genosys_contact_link( genosys_contact_setting( 'social_' . $network ) ); }\n\t$form = array();\n\tforeach ( array('title'=>'form_title','description'=>'form_description','topic_label'=>'topic_label','name_label'=>'name_label','mobile_label'=>'mobile_label','email_label'=>'email_input_label','message_label'=>'message_label','attachment_label'=>'attachment_label','attachment_hint'=>'attachment_hint','consent_before'=>'consent_before','privacy_label'=>'privacy_label','consent_after'=>'consent_after','submit_label'=>'submit_label','success'=>'form_success') as $key=>$setting ) { $form[$key] = (string) genosys_contact_setting( $setting ); }\n\t$form['topics'] = array();\n\tforeach ( array('support','consultation','partnership','feedback','other') as $topic ) { $form['topics'][$topic] = (string) genosys_contact_setting( 'topic_' . $topic ); }\n\t$form['privacy_url'] = genosys_contact_link( genosys_contact_setting('privacy_url') ) ?: get_privacy_policy_url();\n\t$data['form'] = $form;\n\t$data['faq'] = array('before'=>(string)genosys_contact_setting('faq_before'),'highlight'=>(string)genosys_contact_setting('faq_highlight'),'after'=>(string)genosys_contact_setting('faq_after'),'description'=>(string)genosys_contact_setting('faq_description'),'items'=>array());\n\t$faqs = genosys_contact_setting( 'faq' );\n\tforeach ( array_slice( is_array($faqs)?$faqs:array(), 0, 30 ) as $row ) {\n\t\tif ( is_array($row) && is_string($row['question']??null) && is_string($row['answer']??null) && '' !== trim($row['question']) && '' !== trim($row['answer']) ) { $data['faq']['items'][] = array('question'=>$row['question'],'answer'=>$row['answer']); }\n\t}\n\treturn $data;\n}\n\nfunction genosys_contact_register_messages() {\n\t// These are already primitive administrator capabilities. Mapping them again\n\t// would register manage_options as a post meta-capability for the whole site.\n\tregister_post_type( 'genosys_contact', array('label'=>'پیام‌های تماس','public'=>false,'publicly_queryable'=>false,'exclude_from_search'=>true,'show_ui'=>false,'show_in_menu'=>false,'show_in_rest'=>false,'rewrite'=>false,'query_var'=>false,'can_export'=>false,'supports'=>array('title'),'capability_type'=>'genosys_contact','map_meta_cap'=>false,'capabilities'=>array('read_post'=>'manage_options','edit_post'=>'manage_options','delete_post'=>'manage_options','read'=>'manage_options','edit_posts'=>'manage_options','edit_others_posts'=>'manage_options','edit_private_posts'=>'manage_options','edit_published_posts'=>'manage_options','publish_posts'=>'manage_options','read_private_posts'=>'manage_options','delete_posts'=>'manage_options','delete_private_posts'=>'manage_options','delete_published_posts'=>'manage_options','delete_others_posts'=>'manage_options','create_posts'=>'manage_options')) );\n}\nadd_action( 'init', 'genosys_contact_register_messages' );\n\nfunction genosys_contact_post_text( $key, $alias = '' ) {\n\t$value = $_POST[ $key ] ?? ( $alias ? ( $_POST[ $alias ] ?? '' ) : '' );\n\treturn is_string( $value ) ? trim( wp_unslash( $value ) ) : null;\n}\n\nfunction genosys_contact_error( $message, $status = 400, $fields = array() ) {\n\t$data = array('message'=>$message);\n\tif ( $fields ) { $data['fields'] = $fields; }\n\twp_send_json_error( $data, $status );\n}\n\n/** The browser never receives a URL for an attachment: it remains private post metadata. */\nfunction genosys_contact_read_attachment() {\n\tif ( ! isset( $_FILES['attachment'] ) ) { return null; }\n\t$file = $_FILES['attachment'];\n\tif ( ! is_array($file) || ! isset($file['error']) || is_array($file['error']) || ! is_numeric($file['error']) ) { return new WP_Error('attachment','فایل پیوست معتبر نیست.'); }\n\tif ( UPLOAD_ERR_NO_FILE === (int)$file['error'] ) { return null; }\n\tif ( UPLOAD_ERR_OK !== (int)$file['error'] ) { return new WP_Error('attachment','فایل به‌طور کامل دریافت نشد یا حجم آن بیش از حد مجاز است.'); }\n\tif ( ! is_string($file['tmp_name']??null) || ! is_string($file['name']??null) || ! is_uploaded_file($file['tmp_name']) ) { return new WP_Error('attachment','فایل پیوست معتبر نیست.'); }\n\t$size = filesize( $file['tmp_name'] );\n\tif ( false === $size || $size < 1 || $size > 5*1024*1024 ) { return new WP_Error('attachment','حجم فایل باید حداکثر ۵ مگابایت باشد.'); }\n\t$name = sanitize_file_name( $file['name'] );\n\t$extension = strtolower( pathinfo( $name, PATHINFO_EXTENSION ) );\n\t$allowed = array('jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','pdf'=>'application/pdf');\n\tif ( ! isset($allowed[$extension]) || strlen($name)>255 ) { return new WP_Error('attachment','تنها فایل JPG، PNG، WebP یا PDF قابل ارسال است.'); }\n\t$bytes = file_get_contents( $file['tmp_name'], false, null, 0, 5*1024*1024+1 );\n\tif ( ! is_string($bytes) || strlen($bytes)!==$size ) { return new WP_Error('attachment','خواندن فایل پیوست ممکن نشد.'); }\n\t$mime = function_exists('finfo_open') ? (new finfo(FILEINFO_MIME_TYPE))->buffer($bytes) : '';\n\t$checked = wp_check_filetype_and_ext( $file['tmp_name'], $name, array('jpg|jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','pdf'=>'application/pdf') );\n\tif ( empty($checked['ext']) || empty($checked['type']) || $checked['type'] !== $allowed[$extension] ) { return new WP_Error('attachment','محتوای فایل با پسوند آن مطابقت ندارد.'); }\n\tif ( 'pdf' === $extension ) { $valid = 'application/pdf'===$mime && 0===strpos($bytes,'%PDF-'); }\n\telse { $detected = wp_get_image_mime($file['tmp_name']); $valid = $allowed[$extension]===$detected && (!$mime || $mime===$detected); }\n\tif ( ! $valid ) { return new WP_Error('attachment','محتوای فایل با نوع مجاز آن مطابقت ندارد.'); }\n\treturn array('filename'=>$name,'mime'=>$allowed[$extension],'bytes'=>$size,'base64'=>base64_encode($bytes),'sha256'=>hash('sha256',$bytes));\n}\n\nfunction genosys_contact_submit() {\n\tif ( 'POST' !== ($_SERVER['REQUEST_METHOD']??'') ) { genosys_contact_error('روش ارسال معتبر نیست.',405); }\n\t$nonce = genosys_contact_post_text('nonce');\n\tif ( ! is_string($nonce) || ! wp_verify_nonce($nonce,'genosys_contact_submit') ) { genosys_contact_error('اعتبار فرم تمام شده است. صفحه را تازه کنید و دوباره بفرستید.',403); }\n\t$trap = genosys_contact_post_text('website');\n\tif ( null === $trap ) { genosys_contact_error('اطلاعات فرم معتبر نیست.'); }\n\tif ( '' !== $trap ) { wp_send_json_success(array('message'=>(string)genosys_contact_setting('form_success'))); }\n\t$ip = isset($_SERVER['REMOTE_ADDR']) && is_string($_SERVER['REMOTE_ADDR']) ? $_SERVER['REMOTE_ADDR'] : 'unknown';\n\t$rate_key = 'genosys_contact_rate_' . substr(hash_hmac('sha256',$ip,wp_salt('nonce')),0,32);\n\t$attempts = (int)get_transient($rate_key);\n\tif ( $attempts >= 6 ) { genosys_contact_error('تعداد درخواست‌ها زیاد است. کمی بعد دوباره تلاش کنید.',429); }\n\tset_transient($rate_key,$attempts+1,15*MINUTE_IN_SECONDS);\n\t$name = genosys_contact_post_text('fullname','name');\n\t$mobile = genosys_contact_post_text('mobile','phone');\n\t$email = genosys_contact_post_text('email');\n\t$topic = genosys_contact_post_text('topic');\n\t$message = genosys_contact_post_text('message');\n\t$consent = genosys_contact_post_text('consent','privacy');\n\t$errors = array();\n\tif ( ! is_string($name) || genosys_contact_length($name)<2 || genosys_contact_length($name)>100 || sanitize_text_field($name)!==$name ) { $errors['fullname']='نام و نام خانوادگی را به‌درستی وارد کنید (۲ تا ۱۰۰ نویسه).'; }\n\tif ( is_string($mobile) ) { $mobile = preg_replace('/[\\s()\\-]/u','',genosys_contact_ascii($mobile)); if (0===strpos($mobile,'0098')){$mobile='0'.substr($mobile,4);} elseif(0===strpos($mobile,'+98')){$mobile='0'.substr($mobile,3);} }\n\tif ( ! is_string($mobile) || ! preg_match('/^09[0-9]{9}$/D',$mobile) ) { $errors['mobile']='شماره موبایل معتبر وارد کنید.'; }\n\tif ( ! is_string($email) || (''!==$email && (strlen($email)>254 || !is_email($email))) ) { $errors['email']='ایمیل معتبر وارد کنید یا این کادر را خالی بگذارید.'; }\n\tif ( ! is_string($topic) || !in_array($topic,array('support','consultation','partnership','feedback','other'),true) ) { $errors['topic']='موضوع پیام را انتخاب کنید.'; }\n\tif ( ! is_string($message) || genosys_contact_length($message)<1 || genosys_contact_length($message)>500 || wp_check_invalid_utf8($message)!==$message ) { $errors['message']='پیام باید بین ۱ تا ۵۰۰ نویسه باشد.'; }\n\tif ( '1' !== $consent ) { $errors['consent']='پذیرش قوانین حریم خصوصی لازم است.'; }\n\tif ( $errors ) { genosys_contact_error('لطفاً اطلاعات مشخص‌شده را اصلاح کنید.',400,$errors); }\n\t$mobile_key='genosys_contact_mobile_'.substr(hash_hmac('sha256',$mobile,wp_salt('nonce')),0,32);\n\tif ( (int)get_transient($mobile_key)>=3 ) { genosys_contact_error('پیام‌های قبلی این شماره دریافت شده است. کمی بعد دوباره تلاش کنید.',429); }\n\t$attachment=genosys_contact_read_attachment();\n\tif ( is_wp_error($attachment) ) { genosys_contact_error($attachment->get_error_message(),400,array('attachment'=>$attachment->get_error_message())); }\n\t$data=genosys_contact_page_data();\n\t$id=wp_insert_post(wp_slash(array('post_type'=>'genosys_contact','post_status'=>'private','post_title'=>$name.' — '.$data['form']['topics'][$topic],'post_content'=>'','post_author'=>get_current_user_id())),true);\n\tif ( is_wp_error($id) || !$id ) { genosys_contact_error('ثبت پیام ممکن نشد. لطفاً کمی بعد دوباره تلاش کنید.',500); }\n\t$record=array('fullname'=>sanitize_text_field($name),'mobile'=>$mobile,'email'=>sanitize_email($email),'topic'=>$topic,'topic_label'=>$data['form']['topics'][$topic],'message'=>sanitize_textarea_field($message),'consent'=>true,'submitted_at'=>current_time('mysql'),'user_id'=>get_current_user_id());\n\t$stored=add_post_meta($id,'_genosys_contact_data',wp_slash($record),true);\n\t$file_stored=null===$attachment?true:add_post_meta($id,'_genosys_contact_attachment',wp_slash($attachment),true);\n\tif ( !$stored || !$file_stored ) { wp_delete_post($id,true); genosys_contact_error('ثبت پیام کامل نشد. لطفاً دوباره تلاش کنید.',500); }\n\tset_transient($mobile_key,(int)get_transient($mobile_key)+1,HOUR_IN_SECONDS);\n\tif ( '1'===(string)genosys_contact_setting('notification_enabled') ) {\n\t\t$recipient=(string)genosys_contact_setting('notification_email');\n\t\tif ( is_email($recipient) ) {\n\t\t\ttry { wp_mail($recipient,'پیام تازه در صفحه تماس ژنوسیس','یک پیام تازه در بخش تماس ثبت شد. برای مشاهده، وارد مدیریت سایت شوید: '.admin_url('admin.php?page=genosys-contact-messages&message='.$id)); }\n\t\t\tcatch ( Throwable $error ) { /* The private message is already saved; a mail transport cannot turn it into a duplicate submission. */ }\n\t\t}\n\t}\n\twp_send_json_success(array('message'=>(string)genosys_contact_setting('form_success')));\n}\nadd_action('wp_ajax_genosys_contact_submit','genosys_contact_submit');\nadd_action('wp_ajax_nopriv_genosys_contact_submit','genosys_contact_submit');\n\nfunction genosys_contact_admin_menu() {\n\tadd_submenu_page('genosys-theme-settings','پیام‌های تماس','پیام‌های تماس','manage_options','genosys-contact-messages','genosys_contact_render_inbox');\n}\nadd_action('admin_menu','genosys_contact_admin_menu',30);\n\nfunction genosys_contact_render_inbox() {\n\tif(!current_user_can('manage_options')){wp_die('اجازه مشاهده پیام‌ها را ندارید.','',array('response'=>403));}\n\techo '<div class=\"wrap\" dir=\"rtl\"><h1>پیام‌های تماس</h1><p>پیام‌ها و فایل‌های این بخش خصوصی هستند و تنها مدیران سایت به آن‌ها دسترسی دارند.</p>';\n\t$id=isset($_GET['message'])&&is_scalar($_GET['message'])?absint($_GET['message']):0;\n\tif($id){\n\t\t$post=get_post($id);\n\t\tif(!$post||'genosys_contact'!==$post->post_type){echo '<div class=\"notice notice-error\"><p>پیام پیدا نشد.</p></div></div>';return;}\n\t\t$record=get_post_meta($id,'_genosys_contact_data',true);$record=is_array($record)?$record:array();\n\t\techo '<p><a class=\"button\" href=\"'.esc_url(admin_url('admin.php?page=genosys-contact-messages')).'\">بازگشت به پیام‌ها</a></p><table class=\"widefat striped\"><tbody>';\n\t\tforeach(array('fullname'=>'نام و نام خانوادگی','mobile'=>'موبایل','email'=>'ایمیل','topic_label'=>'موضوع','submitted_at'=>'تاریخ ثبت') as $key=>$label){echo '<tr><th scope=\"row\">'.esc_html($label).'</th><td>'.esc_html(is_scalar($record[$key]??null)?$record[$key]:'—').'</td></tr>';}\n\t\techo '<tr><th scope=\"row\">پیام</th><td style=\"white-space:pre-wrap\">'.esc_html(is_string($record['message']??null)?$record['message']:'').'</td></tr></tbody></table>';\n\t\t$file=get_post_meta($id,'_genosys_contact_attachment',true);\n\t\tif(is_array($file)&&isset($file['filename'])){$url=wp_nonce_url(admin_url('admin-post.php?action=genosys_contact_download&id='.$id),'genosys_contact_download_'.$id);echo '<p><a class=\"button button-primary\" href=\"'.esc_url($url).'\">دریافت پیوست خصوصی: '.esc_html($file['filename']).'</a></p>';}\n\t\techo '</div>';return;\n\t}\n\t$page=isset($_GET['paged'])&&is_scalar($_GET['paged'])?max(1,absint($_GET['paged'])):1;\n\t$query=new WP_Query(array('post_type'=>'genosys_contact','post_status'=>'private','posts_per_page'=>20,'paged'=>$page,'orderby'=>'date','order'=>'DESC'));\n\techo '<table class=\"widefat striped\"><thead><tr><th>نام</th><th>موبایل</th><th>موضوع</th><th>تاریخ</th><th>جزئیات</th></tr></thead><tbody>';\n\tforeach($query->posts as $post){$record=get_post_meta($post->ID,'_genosys_contact_data',true);$record=is_array($record)?$record:array();echo '<tr>';foreach(array('fullname','mobile','topic_label','submitted_at') as $key){echo '<td>'.esc_html(is_scalar($record[$key]??null)?$record[$key]:'—').'</td>';}echo '<td><a class=\"button\" href=\"'.esc_url(add_query_arg('message',$post->ID,admin_url('admin.php?page=genosys-contact-messages'))).'\">مشاهده</a></td></tr>';}\n\tif(!$query->posts){echo '<tr><td colspan=\"5\">هنوز پیامی ثبت نشده است.</td></tr>';}\n\techo '</tbody></table>';\n\tif($query->max_num_pages>1){echo '<div class=\"tablenav\"><div class=\"tablenav-pages\">'.wp_kses_post(paginate_links(array('base'=>add_query_arg('paged','%#%',admin_url('admin.php?page=genosys-contact-messages')),'format'=>'','current'=>$page,'total'=>$query->max_num_pages))).'</div></div>';}\n\techo '</div>';\n}\n\nfunction genosys_contact_download() {\n\tif(!current_user_can('manage_options')){wp_die('اجازه دریافت فایل را ندارید.','',array('response'=>403));}\n\t$id=isset($_GET['id'])&&is_scalar($_GET['id'])?absint($_GET['id']):0;\n\t$nonce=$_GET['_wpnonce']??'';\n\tif(!is_string($nonce)||!wp_verify_nonce($nonce,'genosys_contact_download_'.$id)){wp_die('اعتبار پیوند دریافت فایل تمام شده است.','',array('response'=>403));}\n\t$post=get_post($id);$file=$post&&'genosys_contact'===$post->post_type?get_post_meta($id,'_genosys_contact_attachment',true):null;\n\tif(!is_array($file)||!is_string($file['base64']??null)||!is_string($file['sha256']??null)){wp_die('فایل پیدا نشد.','',array('response'=>404));}\n\t$bytes=base64_decode($file['base64'],true);\n\t$allowed=array('image/jpeg','image/png','image/webp','application/pdf');\n\tif(!is_string($bytes)||strlen($bytes)>5*1024*1024||!hash_equals($file['sha256'],hash('sha256',$bytes))||!in_array($file['mime']??'', $allowed,true)){wp_die('فایل معتبر نیست.','',array('response'=>404));}\n\tnocache_headers();header('X-Content-Type-Options: nosniff');header('Content-Security-Policy: sandbox');header('Content-Type: application/octet-stream');header('Content-Length: '.strlen($bytes));\n\t$filename=sanitize_file_name(is_string($file['filename']??null)?$file['filename']:'attachment');\n\theader('Content-Disposition: attachment; filename=\"attachment.'.sanitize_key(pathinfo($filename,PATHINFO_EXTENSION)).'\"; filename*=UTF-8\\'\\''.rawurlencode($filename));\n\techo $bytes;exit;\n}\nadd_action('admin_post_genosys_contact_download','genosys_contact_download');\nadd_action('admin_post_nopriv_genosys_contact_download','genosys_contact_download');\n","sha256":"10853cb31ad17d856bf816c38b260ddbfb5eb09b0a2e3c4d9631ccd61c3cf55a"},"inc/css-editor-view.php":{"content":"<?php\n/** The CSS editor's presentation. Source reads and writes live in css-editor.php. */\ndefined( 'ABSPATH' ) || exit;\n\n/** Small, consistent outline icons for the editor controls. */\nfunction genosys_css_editor_icon( $name ) {\n\t$paths = array(\n\t\t'file'       => '<path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z\"/><path d=\"M14 2v6h6m-10 4-2 2 2 2m4-4 2 2-2 2\"/>',\n\t\t'desktop'    => '<rect x=\"3\" y=\"3\" width=\"18\" height=\"13\" rx=\"2\"/><path d=\"M8 21h8m-4-5v5\"/>',\n\t\t'mobile'     => '<rect x=\"7\" y=\"2\" width=\"10\" height=\"20\" rx=\"2\"/><path d=\"M11 18h2\"/>',\n\t\t'undo'       => '<path d=\"m9 4-5 5 5 5M4 9h9a6 6 0 0 1 0 12\"/>',\n\t\t'redo'       => '<path d=\"m15 4 5 5-5 5m5-5h-9a6 6 0 0 0 0 12\"/>',\n\t\t'copy'       => '<rect x=\"8\" y=\"8\" width=\"12\" height=\"13\" rx=\"2\"/><path d=\"M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h3\"/>',\n\t\t'download'   => '<path d=\"M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3\"/>',\n\t\t'moon'       => '<path d=\"M20.8 13.4A8.8 8.8 0 0 1 10.6 3.2a9 9 0 1 0 10.2 10.2Z\"/>',\n\t\t'wrap'       => '<path d=\"M3 5h18M3 10h14a4 4 0 0 1 0 8h-4m3-3-3 3 3 3M3 15h5M3 20h5\"/>',\n\t\t'fullscreen' => '<path d=\"M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5\"/>',\n\t\t'reload'     => '<path d=\"M20 7v5h-5M4 17v-5h5\"/><path d=\"M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1\"/>',\n\t\t'external'   => '<path d=\"M14 3h7v7m0-7L10 14M11 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-6\"/>',\n\t\t'arrow'      => '<path d=\"m9 5 7 7-7 7\"/>',\n\t);\n\treturn '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\">' . ( $paths[ $name ] ?? $paths['file'] ) . '</svg>';\n}\n\n/**\n * Render the editor without a form or named inputs; saving uses its own endpoint.\n *\n * @param array  $files       Actual theme CSS file manifest.\n * @param string $preview_url Protected, read-only front-end preview URL.\n */\nfunction genosys_render_css_editor( $files = array(), $preview_url = '' ) {\n\tif ( empty( $files ) && function_exists( 'genosys_css_editor_files' ) ) {\n\t\t$files = genosys_css_editor_files();\n\t}\n\t$preview_url = $preview_url ?: home_url( '/' );\n\t$first_file  = ! empty( $files[0]['path'] ) ? $files[0]['path'] : '';\n\t?>\n\t<div class=\"gsce\" data-css-editor dir=\"rtl\">\n\t\t<header class=\"gsce__heading\">\n\t\t\t<div><h2>ویرایشگر CSS</h2><p>کدهای ظاهری قالب را ببینید، ویرایش کنید و از همین‌جا ذخیره کنید.</p></div>\n\t\t\t<span class=\"gsce__save-state\" data-css-save-status role=\"status\" aria-live=\"polite\">در حال بارگذاری فایل‌ها…</span>\n\t\t</header>\n\t\t<div class=\"gsce__message\" data-css-message role=\"status\" aria-live=\"polite\" hidden></div>\n\t\t<div class=\"gsce__workspace\">\n\t\t\t<aside class=\"gsce__files\" aria-label=\"فایل‌های استایل قالب\">\n\t\t\t\t<button type=\"button\" class=\"gsce__panel-resize gsce__panel-resize--files\" data-css-files-resize aria-label=\"تغییر عرض فهرست فایل‌ها با کشیدن لبهٔ چپ\" title=\"لبهٔ چپ را برای بزرگ یا کوچک کردن فهرست فایل‌ها بکشید\"><span aria-hidden=\"true\"></span></button>\n\t\t\t\t<h3>فایل‌های استایل</h3>\n\t\t\t\t<div class=\"gsce__file-list\" role=\"tablist\" aria-label=\"فایل‌های CSS\" aria-orientation=\"vertical\">\n\t\t\t\t\t<?php foreach ( $files as $index => $file ) :\n\t\t\t\t\t\t$path  = isset( $file['path'] ) ? (string) $file['path'] : '';\n\t\t\t\t\t\t$label = ! empty( $file['label'] ) ? (string) $file['label'] : basename( $path );\n\t\t\t\t\t\t$admin = isset( $file['scope'] ) && 'admin' === $file['scope'];\n\t\t\t\t\t\t?>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__file\" data-css-file=\"<?php echo esc_attr( $path ); ?>\" role=\"tab\" aria-selected=\"<?php echo 0 === $index ? 'true' : 'false'; ?>\" aria-controls=\"genosys-css-editor-panel\" tabindex=\"<?php echo 0 === $index ? '0' : '-1'; ?>\">\n\t\t\t\t\t\t\t<span class=\"gsce__file-icon\"><?php echo genosys_css_editor_icon( 'file' ); ?></span>\n\t\t\t\t\t\t\t<span class=\"gsce__file-info\"><strong><?php echo esc_html( $label ); ?></strong><code dir=\"ltr\"><?php echo esc_html( $path ); ?></code><?php if ( $admin ) : ?><small>پنل مدیریت</small><?php endif; ?></span>\n\t\t\t\t\t\t\t<span class=\"gsce__file-dirty\" data-file-dirty hidden aria-label=\"ذخیره‌نشده\"></span>\n\t\t\t\t\t\t</button>\n\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"gsce__help\"><p>ذخیره: <kbd>Ctrl</kbd> + <kbd>S</kbd></p><p>تورفتگی: <kbd>Tab</kbd></p><p>تغییرات را در پیش‌نمایش زنده می‌بینید؛ فایل اصلی فقط با ذخیره‌سازی تغییر می‌کند.</p></div>\n\t\t\t</aside>\n\n\t\t\t<section class=\"gsce__editor\" id=\"genosys-css-editor-panel\" aria-label=\"ویرایش کد CSS\">\n\t\t\t\t<div class=\"gsce__toolbar\">\n\t\t\t\t\t<code class=\"gsce__current-file\" data-css-current-file dir=\"ltr\"><?php echo esc_html( $first_file ); ?></code>\n\t\t\t\t\t<div class=\"gsce__tools\" role=\"group\" aria-label=\"ابزارهای ویرایش کد\">\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"undo\" title=\"واگرد\" aria-label=\"واگرد\"><?php echo genosys_css_editor_icon( 'undo' ); ?></button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"redo\" title=\"از نو\" aria-label=\"از نو\"><?php echo genosys_css_editor_icon( 'redo' ); ?></button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"copy\" title=\"کپی کد\" aria-label=\"کپی کد\"><?php echo genosys_css_editor_icon( 'copy' ); ?></button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"download\" title=\"دانلود فایل CSS\" aria-label=\"دانلود فایل CSS\"><?php echo genosys_css_editor_icon( 'download' ); ?></button>\n\t\t\t\t\t</div>\n\t\t\t\t\t<label class=\"screen-reader-text\" for=\"genosys-css-history\">تاریخچه نسخه‌ها</label><select id=\"genosys-css-history\" class=\"gsce__select\" data-css-history data-css-draft-input aria-label=\"تاریخچه نسخه‌ها\"><option value=\"\">تاریخچه‌ی نسخه‌ها</option></select>\n\t\t\t\t\t<div class=\"gsce__tools\" role=\"group\" aria-label=\"نمایش ویرایشگر\">\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button gsce__font-button\" data-css-action=\"font-decrease\" title=\"کوچک کردن متن\" aria-label=\"کوچک کردن متن\">−A</button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button gsce__font-button\" data-css-action=\"font-increase\" title=\"بزرگ کردن متن\" aria-label=\"بزرگ کردن متن\">+A</button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"wrap\" title=\"شکستن خط‌های بلند\" aria-label=\"شکستن خط‌های بلند\" aria-pressed=\"false\"><?php echo genosys_css_editor_icon( 'wrap' ); ?></button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"theme\" title=\"تغییر روشنایی ویرایشگر\" aria-label=\"تغییر روشنایی ویرایشگر\" aria-pressed=\"false\"><?php echo genosys_css_editor_icon( 'moon' ); ?></button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"fullscreen\" title=\"تمام‌صفحه کردن ویرایشگر\" aria-label=\"تمام‌صفحه کردن ویرایشگر\" aria-pressed=\"false\"><?php echo genosys_css_editor_icon( 'fullscreen' ); ?></button>\n\t\t\t\t\t</div>\n\t\t\t\t\t<button type=\"button\" class=\"gsce__button gsce__button--reset\" data-css-action=\"reset\" title=\"بازیابی کد اصلی فایل انتخاب‌شده از نسخهٔ نصب‌شدهٔ قالب؛ برای اعمال دائمی ذخیره‌سازی را بزنید\">بازنشانی</button>\n\t\t\t\t\t<button type=\"button\" class=\"gsce__button gsce__button--save\" data-css-action=\"save\" title=\"ذخیره فایل انتخاب‌شده\" disabled>ذخیره‌سازی</button>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"gsce__code-area\"><label class=\"screen-reader-text\" for=\"genosys-css-code\">کد CSS فایل انتخاب‌شده</label><textarea id=\"genosys-css-code\" class=\"gsce__code\" data-css-code data-css-draft-input dir=\"ltr\" spellcheck=\"false\" autocapitalize=\"off\" autocomplete=\"off\" wrap=\"off\" aria-describedby=\"genosys-css-editor-note\"></textarea></div>\n\t\t\t\t<footer class=\"gsce__statusbar\"><span data-css-cursor>سطر ۱، ستون ۱</span><span data-css-validation role=\"status\" aria-live=\"polite\">در انتظار بارگذاری کد</span><span class=\"gsce__status-note\" id=\"genosys-css-editor-note\">پیش‌نمایش زنده</span></footer>\n\t\t\t</section>\n\n\t\t\t<section class=\"gsce__preview\" aria-label=\"پیش‌نمایش زنده وب‌سایت\">\n\t\t\t\t<button type=\"button\" class=\"gsce__panel-resize\" data-css-panel-resize aria-label=\"تغییر عرض کادر پیش‌نمایش با کشیدن لبهٔ راست\" title=\"لبهٔ راست را برای بزرگ یا کوچک کردن کادر بکشید\"><span aria-hidden=\"true\"></span></button>\n\t\t\t\t<header class=\"gsce__preview-heading\"><h3>پیش‌نمایش زنده</h3><div class=\"gsce__tools\" role=\"group\" aria-label=\"اندازه پیش‌نمایش\"><button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"preview-desktop\" aria-label=\"نمایش دسکتاپ\" title=\"نمایش دسکتاپ\" aria-pressed=\"true\"><?php echo genosys_css_editor_icon( 'desktop' ); ?></button><button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"preview-mobile\" aria-label=\"نمایش موبایل\" title=\"نمایش موبایل\" aria-pressed=\"false\"><?php echo genosys_css_editor_icon( 'mobile' ); ?></button><button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"preview-fullscreen\" aria-label=\"نمایش تمام‌عرض پیش‌نمایش\" title=\"نمایش تمام‌عرض\" aria-pressed=\"false\"><?php echo genosys_css_editor_icon( 'fullscreen' ); ?></button></div></header>\n\t\t\t\t<div class=\"gsce__preview-controls\">\n\t\t\t\t\t<label class=\"screen-reader-text\" for=\"genosys-css-preview-page\">صفحه پیش‌نمایش</label><select id=\"genosys-css-preview-page\" class=\"gsce__select\" data-css-preview-page data-css-draft-input><option value=\"<?php echo esc_url( home_url( '/' ) ); ?>\">صفحه اصلی</option></select>\n\t\t\t\t\t<div class=\"gsce__preview-address\"><label class=\"screen-reader-text\" for=\"genosys-css-preview-path\">مسیر صفحه در همین وب‌سایت</label><input id=\"genosys-css-preview-path\" data-css-preview-path data-css-draft-input type=\"text\" value=\"/\" placeholder=\"/shop/\" dir=\"ltr\" aria-label=\"مسیر صفحه در همین وب‌سایت\"><button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"preview-open\" title=\"نمایش این مسیر\" aria-label=\"نمایش این مسیر\"><?php echo genosys_css_editor_icon( 'arrow' ); ?></button><button type=\"button\" class=\"gsce__icon-button\" data-css-action=\"preview-reload\" title=\"بارگذاری دوباره پیش‌نمایش\" aria-label=\"بارگذاری دوباره پیش‌نمایش\"><?php echo genosys_css_editor_icon( 'reload' ); ?></button></div>\n\t\t\t\t\t<div class=\"gsce__preview-dimensions\"><label for=\"genosys-css-preview-width\">عرض<input id=\"genosys-css-preview-width\" type=\"number\" min=\"240\" max=\"2560\" step=\"1\" value=\"1440\" data-css-preview-width data-css-draft-input dir=\"ltr\" inputmode=\"numeric\"><span>px</span></label><span class=\"gsce__dimensions-cross\" aria-hidden=\"true\">×</span><label for=\"genosys-css-preview-height\">ارتفاع<input id=\"genosys-css-preview-height\" type=\"number\" min=\"240\" max=\"1600\" step=\"1\" value=\"900\" data-css-preview-height data-css-draft-input dir=\"ltr\" inputmode=\"numeric\"><span>px</span></label></div>\n\t\t\t\t</div>\n\t\t\t\t<p class=\"gsce__preview-note\" data-css-preview-note role=\"status\" aria-live=\"polite\" hidden></p>\n\t\t\t\t<div class=\"gsce__preview-stage\" data-css-preview-stage>\n\t\t\t\t\t<div class=\"gsce__preview-viewport\" data-css-preview-viewport><div class=\"gsce__preview-scale\" data-css-preview-scale><iframe class=\"gsce__preview-frame\" data-css-preview-frame data-preview-src=\"<?php echo esc_url( $preview_url ); ?>\" title=\"پیش‌نمایش زنده وب‌سایت\" sandbox=\"allow-same-origin allow-scripts\" referrerpolicy=\"same-origin\"></iframe></div><button type=\"button\" class=\"gsce__resize-handle\" data-css-preview-resize aria-label=\"تغییر اندازه پیش‌نمایش با کشیدن\" title=\"برای تغییر اندازه بکشید\"><span aria-hidden=\"true\"></span></button></div>\n\t\t\t\t</div>\n\t\t\t\t<p class=\"gsce__preview-hint\"><span class=\"gsce__panel-drag-hint\">لبهٔ راست کادر را برای تغییر عرض آن بکشید. </span>گوشهٔ پایین پیش‌نمایش را بکشید یا اندازهٔ دلخواه را وارد کنید.</p>\n\t\t\t</section>\n\t\t</div>\n\t</div>\n\t<?php\n}\n","sha256":"0b7e14defcd5a41e29555313f034f6bf92e2b08bb7c6635353d5fad05535e514"},"inc/css-editor.php":{"content":"<?php\n/** Real CSS source editing. Drafts live only in the editor; writes are explicit. */\ndefined( 'ABSPATH' ) || exit;\n\n// This is the shipped bundle version, independent of the editable style.css header.\nconst GENOSYS_CSS_EDITOR_BASELINE_VERSION = '1.5.86';\n\nfunction genosys_css_editor_allowed() {\n\treturn current_user_can( 'manage_options' ) && current_user_can( 'edit_themes' )\n\t\t&& ! ( defined( 'DISALLOW_FILE_EDIT' ) && DISALLOW_FILE_EDIT )\n\t\t&& ! ( defined( 'DISALLOW_FILE_MODS' ) && DISALLOW_FILE_MODS )\n\t\t&& wp_is_file_mod_allowed( 'genosys_css_editor' );\n}\n\n/** Use this running theme's physical directory, never a caller-supplied theme. */\nfunction genosys_css_editor_root() {\n\t$root = realpath( dirname( __DIR__ ) );\n\t$active = realpath( get_template_directory() );\n\treturn $root && $active && wp_normalize_path( $root ) === wp_normalize_path( $active ) ? $root : false;\n}\n\n/** A symlinked theme directory is supported; symlinks within it are not editable. */\nfunction genosys_css_editor_resolve( $relative ) {\n\t$root = genosys_css_editor_root();\n\tif ( ! $root || ! is_string( $relative ) || ! preg_match( '#^(?:style\\.css|assets/css/[A-Za-z0-9_./-]+\\.css)$#D', $relative )\n\t\t|| false !== strpos( $relative, '..' ) || false !== strpos( $relative, '//' ) || 0 !== validate_file( $relative ) ) {\n\t\treturn false;\n\t}\n\t$path = $root;\n\tforeach ( explode( '/', $relative ) as $piece ) {\n\t\t$path .= DIRECTORY_SEPARATOR . $piece;\n\t\tif ( is_link( $path ) ) { return false; }\n\t}\n\t$real = realpath( $path );\n\t$prefix = trailingslashit( wp_normalize_path( $root ) );\n\tif ( ! $real || 0 !== strpos( wp_normalize_path( $real ), $prefix ) || ! is_file( $real ) || 'css' !== strtolower( pathinfo( $real, PATHINFO_EXTENSION ) ) ) { return false; }\n\treturn $real;\n}\n\nfunction genosys_css_editor_files() {\n\t$root = genosys_css_editor_root();\n\tif ( ! $root ) { return array(); }\n\t$labels = array(\n\t\t'style.css'=>'استایل اصلی و صفحه اصلی', 'account-menu.css'=>'منوی حساب و نوار موبایل',\n\t\t'products.css'=>'کارت محصولات', 'featured-products.css'=>'محصولات منتخب', 'home-categories.css'=>'دسته‌بندی‌های صفحه اصلی',\n\t\t'footer.css'=>'فوتر', 'shop.css'=>'فروشگاه', 'single-product.css'=>'صفحه محصول',\n\t\t'add-to-cart-animation.css'=>'انیمیشن افزودن به سبد', 'cart.css'=>'سبد خرید', 'checkout.css'=>'تسویه حساب',\n\t\t'account-dashboard.css'=>'حساب کاربری', 'customer-orders.css'=>'سفارش‌های مشتری', 'order-access.css'=>'دسترسی سفارش',\n        'fans-club.css'=>'باشگاه مشتریان', 'contact.css'=>'تماس با ما', 'brand.css'=>'صفحه برند', 'company.css'=>'صفحه شرکت', 'login.css'=>'ورود به حساب', 'receipt-uploader.css'=>'بارگذاری فیش',\n\t\t'package-builder.css'=>'مدیریت افزودن پکیج', 'package-list.css'=>'مدیریت لیست پکیج‌ها',\n\t\t'receipt-admin.css'=>'مدیریت فیش‌ها', 'club-admin.css'=>'مدیریت باشگاه مشتریان',\n\t\t'settings-dashboard.css'=>'تنظیمات قالب', 'css-editor.css'=>'ویرایشگر CSS', 'php-editor.css'=>'ویرایشگر PHP',\n\t);\n\t$admin = array( 'package-builder.css','package-list.css','receipt-admin.css','club-admin.css','settings-dashboard.css','css-editor.css','php-editor.css' );\n\t$paths = array( 'style.css' );\n\t$directory = $root . '/assets/css';\n\tif ( is_dir( $directory ) && ! is_link( $directory ) ) {\n\t\ttry {\n\t\t\t$iterator = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $directory, FilesystemIterator::SKIP_DOTS ) );\n\t\t\tforeach ( $iterator as $entry ) {\n\t\t\t\tif ( $entry->isFile() && ! $entry->isLink() && 'css' === strtolower( $entry->getExtension() ) ) {\n\t\t\t\t\t$paths[] = substr( wp_normalize_path( $entry->getPathname() ), strlen( trailingslashit( wp_normalize_path( $root ) ) ) );\n\t\t\t\t}\n\t\t\t}\n\t\t} catch ( UnexpectedValueException $exception ) { /* An unreadable folder simply has no editable files. */ }\n\t}\n\t$paths = array_values( array_unique( $paths ) );\n\tsort( $paths, SORT_NATURAL );\n\t$paths = array_merge( array( 'style.css' ), array_diff( $paths, array( 'style.css' ) ) );\n\t$files = array();\n\tforeach ( $paths as $path ) {\n\t\t$real = genosys_css_editor_resolve( $path );\n\t\tif ( ! $real || ! is_readable( $real ) ) { continue; }\n\t\t$name = basename( $path );\n\t\t$files[] = array(\n\t\t\t'path'=>$path, 'label'=>$labels[ $name ] ?? $name,\n\t\t\t'scope'=>in_array( $name, $admin, true ) ? 'admin' : 'frontend',\n\t\t\t'url'=>trailingslashit( get_template_directory_uri() ) . $path,\n\t\t\t'readonly'=>! genosys_css_editor_allowed() || ! is_writable( $real ) || ! is_writable( dirname( $real ) ),\n\t\t);\n\t}\n\treturn $files;\n}\n\nfunction genosys_css_editor_preview_url( $url ) {\n\treturn add_query_arg( array( 'genosys_css_preview'=>'1', '_genosys_css_nonce'=>wp_create_nonce( 'genosys_css_preview' ) ), $url );\n}\n\nfunction genosys_css_editor_bootstrap() {\n\tstatic $code_editor = null;\n\tif ( null === $code_editor ) {\n\t\t$code_editor = genosys_css_editor_allowed() ? wp_enqueue_code_editor( array( 'type'=>'text/css', 'codemirror'=>array( 'lineNumbers'=>true, 'lineWrapping'=>false, 'indentUnit'=>2, 'tabSize'=>2, 'direction'=>'ltr' ) ) ) : false;\n\t}\n\t$pages = array( array( 'label'=>'صفحه اصلی', 'url'=>genosys_css_editor_preview_url( home_url( '/' ) ) ) );\n\tif ( function_exists( 'wc_get_page_permalink' ) ) {\n\t\t$shop = wc_get_page_permalink( 'shop' );\n\t\tif ( $shop && home_url( '/' ) !== $shop ) { $pages[] = array( 'label'=>'فروشگاه', 'url'=>genosys_css_editor_preview_url( $shop ) ); }\n\t\t$products = wc_get_products( array( 'status'=>'publish', 'limit'=>1, 'return'=>'ids' ) );\n\t\tif ( $products ) { $pages[] = array( 'label'=>'صفحه محصول', 'url'=>genosys_css_editor_preview_url( get_permalink( reset( $products ) ) ) ); }\n\t}\n\t$pages[] = array( 'label'=>'باشگاه مشتریان', 'url'=>genosys_css_editor_preview_url( home_url( '/fans-club/' ) ) );\n\t$pages[] = array( 'label'=>'حساب کاربری', 'url'=>genosys_css_editor_preview_url( home_url( '/my-account/' ) ) );\n\t$pages[] = array( 'label'=>'شرکت', 'url'=>genosys_css_editor_preview_url( home_url( '/company/' ) ) );\n\treturn array(\n\t\t'ajaxUrl'=>admin_url( 'admin-ajax.php' ), 'nonce'=>wp_create_nonce( 'genosys_css_editor' ),\n\t\t'files'=>genosys_css_editor_files(), 'previewUrl'=>$pages[0]['url'], 'previewPages'=>$pages,\n\t\t'codeEditor'=>$code_editor, 'allowed'=>genosys_css_editor_allowed(), 'maxBytes'=>1048576,\n\t\t'baselineVersion'=>GENOSYS_CSS_EDITOR_BASELINE_VERSION,\n\t\t'reason'=>genosys_css_editor_allowed() ? '' : 'ویرایش فایل‌های قالب برای حساب شما یا در تنظیمات امنیتی وردپرس غیرفعال است.',\n\t);\n}\n\nfunction genosys_css_editor_error( $code, $message, $status = 400, $extra = array() ) {\n\twp_send_json_error( array_merge( array( 'code'=>$code, 'message'=>$message ), $extra ), $status );\n}\n\n/** Every source endpoint uses the same permission, method and nonce checks. */\nfunction genosys_css_editor_request_file() {\n\tif ( ! genosys_css_editor_allowed() ) { genosys_css_editor_error( 'forbidden', 'شما اجازهٔ ویرایش فایل‌های قالب را ندارید.', 403 ); }\n\tif ( 'POST' !== ( $_SERVER['REQUEST_METHOD'] ?? '' ) ) { genosys_css_editor_error( 'method', 'روش درخواست معتبر نیست.', 405 ); }\n\t$nonce = isset( $_POST['nonce'] ) && is_string( $_POST['nonce'] ) ? wp_unslash( $_POST['nonce'] ) : '';\n\tif ( ! wp_verify_nonce( $nonce, 'genosys_css_editor' ) ) { genosys_css_editor_error( 'nonce', 'نشست شما منقضی شده است؛ صفحه را دوباره باز کنید.', 403 ); }\n\t$file = isset( $_POST['file'] ) && is_string( $_POST['file'] ) ? wp_unslash( $_PO