f ( false === $written || 0 === $written ) { fclose( $handle ); throw new RuntimeException( 'write' ); }\n\t\t\t\t$offset += $written;\n\t\t\t}\n\t\t\t$flushed = @fflush( $handle );\n\t\t\tif ( function_exists( 'fsync' ) ) { $flushed = @fsync( $handle ) && $flushed; }\n\t\t\tfclose( $handle );\n\t\t\tif ( ! $flushed || hash( 'sha256', $content ) !== @hash_file( 'sha256', $temp ) ) { throw new RuntimeException( 'write' ); }\n\t\t\t@chmod( $temp, fileperms( $real ) & 0777 );\n\t\t\t// External tools do not share our lock; check their writes again before commit.\n\t\t\tif ( $real !== genosys_css_editor_resolve( $file ) || ! hash_equals( $expected, (string) @hash_file( 'sha256', $real ) ) ) {\n\t\t\t\t$error = array( 'conflict', 'نسخهٔ سرور هنگام ذخیره تغییر کرد؛ دوباره فایل را بارگذاری کنید.', 409 );\n\t\t\t} elseif ( ! @rename( $temp, $real ) ) { throw new RuntimeException( 'rename' ); }\n\t\t\telse {\n\t\t\t\t$temp = false;\n\t\t\t\tclearstatcache( true, $real );\n\t\t\t\t$remembered = genosys_css_editor_remember( $file, $content );\n\t\t\t\t$result = genosys_css_editor_payload( $file, $real, $content );\n\t\t\t\tif ( ! $remembered ) { $result['historyWarning'] = 'فایل ذخیره شد؛ افزودن این نسخه به تاریخچه ممکن نشد.'; }\n\t\t\t}\n\t\t}\n\t} catch ( RuntimeException $exception ) {\n\t\t$error = array( 'write', 'ذخیرهٔ امن فایل ممکن نشد؛ فایل فعلی سایت حفظ شده است. دسترسی فایل و فضای میزبان را بررسی کنید.', 500 );\n\t} finally {\n\t\tif ( $temp && is_file( $temp ) ) { @unlink( $temp ); }\n\t\t@flock( $lock, LOCK_UN );\n\t\tfclose( $lock );\n\t}\n\tif ( $error ) { genosys_css_editor_error( $error[0], $error[1], $error[2] ); }\n\twp_send_json_success( $result );\n}\nadd_action( 'wp_ajax_genosys_css_editor_save', 'genosys_css_editor_save' );\n\n/** Real file hashes invalidate old fixed enqueue versions after editor saves. */\nfunction genosys_css_editor_asset_version( $src ) {\n\t$root = genosys_css_editor_root();\n\tif ( ! $root || ! is_string( $src ) ) { return $src; }\n\t$base = wp_parse_url( trailingslashit( get_template_directory_uri() ) );\n\t$url = wp_parse_url( html_entity_decode( $src, ENT_QUOTES, 'UTF-8' ) );\n\tif ( ! $base || ! $url || ( isset( $url['host'] ) && strcasecmp( $url['host'], $base['host'] ?? '' ) ) || ( isset( $url['port'] ) && (int) $url['port'] !== (int) ( $base['port'] ?? 0 ) ) ) { return $src; }\n\t$prefix = $base['path'] ?? '';\n\t$path = rawurldecode( $url['path'] ?? '' );\n\tif ( 0 !== strpos( $path, $prefix ) ) { return $src; }\n\t$relative = substr( $path, strlen( $prefix ) );\n\t$real = genosys_css_editor_resolve( $relative );\n\tif ( ! $real ) { return $src; }\n\tstatic $hashes = array();\n\tif ( ! isset( $hashes[ $real ] ) ) { $hashes[ $real ] = @hash_file( 'sha256', $real ); }\n\treturn $hashes[ $real ] ? add_query_arg( 'genosys_css', substr( $hashes[ $real ], 0, 16 ), $src ) : $src;\n}\nadd_filter( 'style_loader_src', 'genosys_css_editor_asset_version', 99 );\n\nfunction genosys_css_editor_is_preview() {\n\treturn ! empty( $GLOBALS['genosys_css_editor_preview_context'] ) || ( isset( $_GET['genosys_css_preview'] ) && is_string( $_GET['genosys_css_preview'] ) && '1' === $_GET['genosys_css_preview'] );\n}\n\n/** CSS image/import loads are native browser requests, outside fetch/XHR guards. */\nfunction genosys_css_editor_preview_referrer() {\n\t$referrer = isset( $_SERVER['HTTP_REFERER'] ) && is_string( $_SERVER['HTTP_REFERER'] ) ? wp_unslash( $_SERVER['HTTP_REFERER'] ) : '';\n\t$ref = wp_parse_url( $referrer );\n\t$home = wp_parse_url( home_url( '/' ) );\n\tif ( ! $ref || ! $home || empty( $ref['host'] ) || empty( $ref['scheme'] )\n\t\t|| strtolower( $ref['scheme'] ) !== strtolower( $home['scheme'] ?? '' )\n\t\t|| 0 !== strcasecmp( $ref['host'], $home['host'] ?? '' )\n\t\t|| (int) ( $ref['port'] ?? ( 'https' === strtolower( $ref['scheme'] ) ? 443 : 80 ) ) !== (int) ( $home['port'] ?? ( 'https' === strtolower( $home['scheme'] ?? '' ) ? 443 : 80 ) ) ) { return false; }\n\t$query = array();\n\twp_parse_str( $ref['query'] ?? '', $query );\n\treturn isset( $query['genosys_css_preview'], $query['_genosys_css_nonce'] )\n\t\t&& is_string( $query['genosys_css_preview'] ) && '1' === $query['genosys_css_preview']\n\t\t&& is_string( $query['_genosys_css_nonce'] ) && wp_verify_nonce( $query['_genosys_css_nonce'], 'genosys_css_preview' );\n}\n\n/** Preview is a private view of the actual frontend, never an action endpoint. */\nfunction genosys_css_editor_preview_gate() {\n\t$explicit = isset( $_GET['genosys_css_preview'] );\n\t$referred = ! $explicit && genosys_css_editor_allowed() && genosys_css_editor_preview_referrer();\n\tif ( ! $explicit && ! $referred ) { return; }\n\t$nonce = isset( $_GET['_genosys_css_nonce'] ) && is_string( $_GET['_genosys_css_nonce'] ) ? wp_unslash( $_GET['_genosys_css_nonce'] ) : '';\n\tif ( ! genosys_css_editor_allowed() || ( $explicit && ( ! genosys_css_editor_is_preview() || ! wp_verify_nonce( $nonce, 'genosys_css_preview' ) ) ) ) {\n\t\twp_die( 'پیش‌نمایش فقط در نشست معتبر مدیر قابل مشاهده است.', 'پیش‌نمایش CSS', array( 'response'=>403 ) );\n\t}\n\t$GLOBALS['genosys_css_editor_preview_context'] = true;\n\t$method = $_SERVER['REQUEST_METHOD'] ?? '';\n\t$blocked = array( 'action','wc-ajax','wc-api','add-to-cart','remove_item','undo_item','remove_coupon','apply_coupon','update_cart','proceed','order_again','cancel_order','download_file','customer-logout','delete-payment-method','set-default-payment-method','rest_route' );\n\t$unsafe = ! in_array( $method, array( 'GET','HEAD' ), true ) || is_admin() || ( defined( 'REST_REQUEST' ) && REST_REQUEST );\n\tforeach ( $blocked as $key ) { if ( isset( $_REQUEST[ $key ] ) ) { $unsafe = true; } }\n\t$path = wp_parse_url( $_SERVER['REQUEST_URI'] ?? '', PHP_URL_PATH );\n\tif ( preg_match( '#/(?:wp-admin|wp-json|wc-api|customer-logout|delete-payment-method|set-default-payment-method)(?:/|$)|/wp-login\\.php(?:/|$)#i', rawurldecode( (string) $path ) ) ) { $unsafe = true; }\n\tif ( $unsafe ) { wp_die( 'عملیات و ارسال فرم در پیش‌نمایش غیرفعال است.', 'پیش‌نمایش CSS', array( 'response'=>403 ) ); }\n\tif ( ! defined( 'DONOTCACHEPAGE' ) ) { define( 'DONOTCACHEPAGE', true ); }\n\tnocache_headers();\n\tif ( ! headers_sent() ) {\n\t\theader( 'Referrer-Policy: same-origin' );\n\t\theader( 'X-Robots-Tag: noindex, nofollow', true );\n\t\t// An additional policy intersects with existing CSP; never replace its rules.\n\t\theader( \"Content-Security-Policy: form-action 'none'; base-uri 'self'\", false );\n\t}\n\tshow_admin_bar( false );\n}\nadd_action( 'init', 'genosys_css_editor_preview_gate', -100000 );\n\n/** Run before theme scripts so the real page remains visually accurate but read-only. */\nfunction genosys_css_editor_preview_guard() {\n\tif ( ! genosys_css_editor_is_preview() ) { return; }\n\t$config = array( 'nonce'=>wp_create_nonce( 'genosys_css_preview' ), 'origin'=>home_url( '/' ) );\n\t?>\n\t<script id=\"genosys-css-preview-guard\">\n\t(function(config){'use strict';\n\t var origin=new URL(config.origin,location.href).origin;\n\t function safe(value,method){try{var u=new URL(value,location.href);if(u.origin!==origin||!/^(GET|HEAD)$/i.test(method||'GET')||/\\/(wp-admin|wp-json|wc-api|customer-logout|delete-payment-method|set-default-payment-method)(\\/|$)|\\/wp-login\\.php/i.test(decodeURIComponent(u.pathname)))return false;var bad=['action','wc-ajax','wc-api','add-to-cart','remove_item','undo_item','remove_coupon','apply_coupon','update_cart','proceed','order_again','cancel_order','download_file','customer-logout','delete-payment-method','set-default-payment-method','rest_route'];return !bad.some(function(k){return u.searchParams.has(k);});}catch(e){return false;}}\n\t function decorate(value){var u=new URL(value,location.href);u.searchParams.set('genosys_css_preview','1');u.searchParams.set('_genosys_css_nonce',config.nonce);return u.href;}\n\t var fetchOriginal=window.fetch;if(fetchOriginal)window.fetch=function(input,init){var method=(init&&init.method)||(input&&input.method)||'GET',url=typeof input==='string'||input instanceof URL?String(input):input.url;if(!safe(url,method))return Promise.reject(new TypeError('Read-only CSS preview'));return fetchOriginal.apply(this,arguments);};\n\t var openOriginal=XMLHttpRequest.prototype.open;XMLHttpRequest.prototype.open=function(method,url){if(!safe(url,method))throw new DOMException('Read-only CSS preview','SecurityError');return openOriginal.apply(this,arguments);};\n\t if(navigator.sendBeacon)try{navigator.sendBeacon=function(){return false;};}catch(e){}\n\t window.open=function(){return null;};\n\t document.addEventListener('submit',function(e){e.preventDefault();e.stopImmediatePropagation();},true);\n\t document.addEventListener('click',function(e){var a=e.target&&e.target.closest?e.target.closest('a'):null;if(!a)return;var href=a.getAttribute('href');if(!href||href.charAt(0)==='#')return;e.preventDefault();e.stopImmediatePropagation();if(safe(a.href,'GET'))location.assign(decorate(a.href));},true);\n\t window.genosysCSSReadOnlyPreview=true;\n\t})(<?php echo wp_json_encode( $config, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT ); ?>);\n\t</script>\n\t<?php\n}\nadd_action( 'wp_head', 'genosys_css_editor_preview_guard', -100000 );\n","sha256":"8870b34aa4759242d94d1c2d277987468c9c377a6d0ff9ad8d76a7f762ab56fb"},"inc/customer-orders.php":{"content":"<?php\n/**\n * Authorized WooCommerce orders: scoped routing and read-only presentation.\n *\n * @package Genosys\n */\n\ndefined( 'ABSPATH' ) || exit;\n\n/** Leave every other account endpoint and the account dashboard untouched. */\nfunction genosys_is_customer_orders() {\n\treturn function_exists( 'is_account_page' ) && function_exists( 'is_wc_endpoint_url' ) && is_account_page() && is_wc_endpoint_url( 'orders' );\n}\n\nfunction genosys_customer_orders_template( $template ) {\n\treturn genosys_is_customer_orders() ? get_theme_file_path( '/page-account-orders.php' ) : $template;\n}\nadd_filter( 'template_include', 'genosys_customer_orders_template', 99 );\n\n/** Customer information and receipt nonces must never enter a public page cache. */\nfunction genosys_customer_orders_nocache() {\n\tif ( genosys_is_customer_orders() ) {\n\t\tif ( ! defined( 'DONOTCACHEPAGE' ) ) {\n\t\t\tdefine( 'DONOTCACHEPAGE', true );\n\t\t}\n\t\tnocache_headers();\n\t}\n}\nadd_action( 'template_redirect', 'genosys_customer_orders_nocache', 1 );\n\n/** Localize only visible text, never URLs, markup, or numeric database values. */\nfunction genosys_customer_orders_digits( $value ) {\n\treturn function_exists( 'genosys_persian_number' ) ? genosys_persian_number( $value ) : strtr( (string) $value, array( '0' => '۰', '1' => '۱', '2' => '۲', '3' => '۳', '4' => '۴', '5' => '۵', '6' => '۶', '7' => '۷', '8' => '۸', '9' => '۹' ) );\n}\n\n/** Historical amounts retain their own order currency and WooCommerce formatting. */\nfunction genosys_customer_orders_price( $amount, $order = null ) {\n\t$currency = is_object( $order ) && method_exists( $order, 'get_currency' ) ? $order->get_currency() : ( is_string( $order ) ? $order : '' );\n\t$html     = wc_price( $amount, array( 'currency' => $currency ) );\n\tif ( function_exists( 'genosys_checkout_localize_html' ) ) {\n\t\treturn wp_kses_post( genosys_checkout_localize_html( $html ) );\n\t}\n\t$parts = wp_html_split( $html );\n\tforeach ( $parts as &$part ) {\n\t\tif ( '' !== $part && '<' !== $part[0] ) {\n\t\t\t$part = esc_html( genosys_customer_orders_digits( html_entity_decode( $part, ENT_QUOTES, 'UTF-8' ) ) );\n\t\t}\n\t}\n\treturn wp_kses_post( implode( '', $parts ) );\n}\n\n/** The six reference filters are always present; unsupported stages show zero. */\nfunction genosys_customer_orders_filter_labels() {\n\treturn array(\n\t\t'all'       => 'همه',\n\t\t'pending'   => 'در انتظار پرداخت',\n\t\t'review'    => 'در حال بررسی',\n\t\t'preparing' => 'در حال آماده‌سازی',\n\t\t'shipped'   => 'ارسال شده',\n\t\t'delivered' => 'تحویل شده',\n\t\t'cancelled' => 'لغو شده',\n\t);\n}\n\n/** This classification describes existing data; it never changes an order status. */\nfunction genosys_customer_orders_classification( $order, $receipt = null ) {\n\t$status = (string) $order->get_status();\n\t$labels = genosys_customer_orders_filter_labels();\n\tif ( in_array( $status, array( 'pending', 'on-hold' ), true ) ) {\n\t\t$group = $receipt ? 'review' : 'pending';\n\t\t$note  = $receipt ? 'در انتظار تأیید پرداخت' : ( function_exists( 'genosys_receipt_order_is_eligible' ) && genosys_receipt_order_is_eligible( $order ) ? 'منتظر فیش' : 'منتظر پرداخت' );\n\t\treturn array( 'group' => $group, 'label' => $labels[ $group ], 'stage' => 2, 'stageNote' => $note );\n\t}\n\t$known = array( 'processing' => array( 'preparing', 3 ), 'shipped' => array( 'shipped', 4 ), 'delivered' => array( 'delivered', 5 ), 'completed' => array( 'delivered', 5 ), 'cancelled' => array( 'cancelled', 0 ) );\n\tif ( isset( $known[ $status ] ) ) {\n\t\t$group = $known[ $status ][0];\n\t\treturn array( 'group' => $group, 'label' => $labels[ $group ], 'stage' => $known[ $status ][1], 'stageNote' => '' );\n\t}\n\t// Custom and exceptional statuses keep WooCommerce's real caption and a separate filter.\n\t$exception_labels = array( 'failed' => 'پرداخت ناموفق', 'refunded' => 'مسترد شده' );\n\treturn array( 'group' => sanitize_key( $status ), 'label' => isset( $exception_labels[ $status ] ) ? $exception_labels[ $status ] : wc_get_order_status_name( $status ), 'stage' => 0, 'stageNote' => '' );\n}\n\n/** Reject foreign orders even if a caller supplies an otherwise valid WC_Order. */\nfunction genosys_customer_order_presentation( $order ) {\n\tif ( ! genosys_order_access_can_view( $order ) ) {\n\t\treturn null;\n\t}\n\t$receipt = function_exists( 'genosys_receipt_get_current' ) ? genosys_receipt_get_current( $order ) : null;\n\tif ( $receipt && function_exists( 'genosys_receipt_customer_descriptor' ) ) {\n\t\t$receipt = genosys_receipt_customer_descriptor( $order, $receipt );\n\t}\n\t$data     = genosys_customer_orders_classification( $order, $receipt );\n\t$date     = $order->get_date_created();\n\t$eligible = function_exists( 'genosys_receipt_order_is_eligible' ) && genosys_receipt_order_is_eligible( $order );\n\t$config   = $eligible && function_exists( 'genosys_receipt_customer_context' ) ? genosys_receipt_customer_context( $order ) : null;\n\t$data['status']          = (string) $order->get_status();\n\t$data['statuskey']       = $data['group'];\n\t$data['receipt']         = $receipt;\n\t$data['receiptEligible'] = $eligible;\n\t$data['receiptConfig']   = $config;\n\t$data['customerConfig']  = $config;\n\t// WC_DateTime::date() shifts the timestamp first; emit the real instant so\n\t// browser formatting applies the configured store timezone exactly once.\n\t$data['dateISO']         = $date ? gmdate( DATE_ATOM, $date->getTimestamp() ) : '';\n\t$data['dateText']        = $date ? genosys_customer_orders_digits( wp_date( 'j F Y، ساعت H:i', $date->getTimestamp(), wp_timezone() ) ) : '';\n\treturn $data;\n}\n\n/** GET links work without JavaScript and retain the configured Woo account URL. */\nfunction genosys_customer_orders_url( $filter = 'all', $page = 1 ) {\n\t$url  = wc_get_account_endpoint_url( 'orders' );\n\t$args = array();\n\tif ( 'all' !== $filter ) {\n\t\t$args['gco_status'] = sanitize_key( $filter );\n\t}\n\tif ( $page > 1 ) {\n\t\t$args['gco_page'] = absint( $page );\n\t}\n\treturn $args ? add_query_arg( $args, $url ) : $url;\n}\n\n/**\n * Merge account-owned orders, verified-phone guest orders and browser grants.\n * Never reassign customer_id or match another registered customer's billing phone.\n */\nfunction genosys_customer_orders_history() {\n\t$history = array();\n\t$queries = array();\n\tif ( is_user_logged_in() ) {\n\t\t$queries[] = array( 'customer_id' => get_current_user_id() );\n\t}\n\tif ( genosys_order_access_phone() ) {\n\t\t// Woo's native phone query uses exact matches. Historical numbers may have\n\t\t// spaces, Arabic/Persian digits or international prefixes, so normalize\n\t\t// guest orders in bounded CRUD batches for both CPT and HPOS storage.\n\t\t$queries[] = array( 'customer_id' => 0 );\n\t}\n\tforeach ( $queries as $query ) {\n\t\t$batch = 1;\n\t\tdo {\n\t\t\t$orders = wc_get_orders( array_merge( array( 'type' => 'shop_order', 'limit' => 200, 'page' => $batch, 'orderby' => 'date', 'order' => 'DESC', 'return' => 'objects', 'paginate' => false ), $query ) );\n\t\t\tforeach ( $orders as $order ) {\n\t\t\t\tif ( ! genosys_order_access_can_view( $order ) ) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\t$date = $order->get_date_created();\n\t\t\t\t$history[ $order->get_id() ] = $date ? $date->getTimestamp() : 0;\n\t\t\t}\n\t\t\t$batch++;\n\t\t} while ( count( $orders ) === 200 );\n\t}\n\t$granted_ids = genosys_order_access_order_ids();\n\tif ( function_exists( 'genosys_account_phone_historical_order_ids' ) ) { $granted_ids = array_unique( array_merge( $granted_ids, genosys_account_phone_historical_order_ids() ) ); }\n\tforeach ( $granted_ids as $id ) {\n\t\tif ( isset( $history[ $id ] ) ) {\n\t\t\tcontinue;\n\t\t}\n\t\t$order = wc_get_order( $id );\n\t\tif ( genosys_order_access_can_view( $order ) ) {\n\t\t\t$date = $order->get_date_created();\n\t\t\t$history[ $id ] = $date ? $date->getTimestamp() : 0;\n\t\t}\n\t}\n\t// Date first, then ID, keeps merged histories and pagination deterministic.\n\t$ids = array_keys( $history );\n\tusort( $ids, static function ( $a, $b ) use ( $history ) {\n\t\treturn $history[ $b ] <=> $history[ $a ] ?: $b <=> $a;\n\t} );\n\treturn $ids;\n}\n\n/**\n * Count the complete history through Woo CRUD, in bounded batches for both stores.\n * Receipt-derived filters cannot be inferred from Woo status counts alone.\n */\nfunction genosys_customer_orders_context() {\n\tstatic $context = null;\n\tif ( null !== $context ) {\n\t\treturn $context;\n\t}\n\t$labels  = genosys_customer_orders_filter_labels();\n\t$context = array( 'orders' => array(), 'filters' => array(), 'total' => 0, 'filteredTotal' => 0, 'pages' => 1, 'currentPage' => 1, 'filter' => 'all', 'missingCount' => 0, 'missingOrderId' => 0, 'missingOrderURL' => '' );\n\tforeach ( $labels as $key => $label ) {\n\t\t$context['filters'][ $key ] = array( 'label' => $label, 'count' => 0, 'url' => genosys_customer_orders_url( $key ) );\n\t}\n\tif ( ! function_exists( 'wc_get_orders' ) || ! genosys_order_access_has_proof() ) {\n\t\treturn $context;\n\t}\n\t$requested   = isset( $_GET['gco_status'] ) && is_scalar( $_GET['gco_status'] ) ? sanitize_key( wp_unslash( (string) $_GET['gco_status'] ) ) : 'all';\n\t$page_raw    = isset( $_GET['gco_page'] ) && is_scalar( $_GET['gco_page'] ) ? wp_unslash( (string) $_GET['gco_page'] ) : get_query_var( 'orders', 1 );\n\t$page        = max( 1, absint( $page_raw ) );\n\t$groups      = array_fill_keys( array_keys( $labels ), array() );\n\tforeach ( genosys_customer_orders_history() as $order_id ) {\n\t\t$order = wc_get_order( $order_id );\n\t\t// Recheck authority at presentation time even if a query plugin widens scope.\n\t\tif ( ! genosys_order_access_can_view( $order ) ) {\n\t\t\tcontinue;\n\t\t}\n\t\t$receipt = function_exists( 'genosys_receipt_get_current' ) ? genosys_receipt_get_current( $order ) : null;\n\t\t$data    = genosys_customer_orders_classification( $order, $receipt );\n\t\t$key     = $data['group'];\n\t\t$id      = (int) $order->get_id();\n\t\tif ( ! isset( $groups[ $key ] ) ) {\n\t\t\t$groups[ $key ]            = array();\n\t\t\t$context['filters'][ $key ] = array( 'label' => $data['label'], 'count' => 0, 'url' => genosys_customer_orders_url( $key ) );\n\t\t}\n\t\t$groups['all'][] = $id;\n\t\t$groups[ $key ][] = $id;\n\t\t$context['filters']['all']['count']++;\n\t\t$context['filters'][ $key ]['count']++;\n\t\tif ( function_exists( 'genosys_receipt_order_is_eligible' ) && genosys_receipt_order_is_eligible( $order ) ) {\n\t\t\t$context['missingCount']++;\n\t\t\tif ( ! $context['missingOrderId'] ) {\n\t\t\t\t$context['missingOrderId']  = $id;\n\t\t\t\t$missing_group              = $key;\n\t\t\t\t$missing_page               = (int) ceil( count( $groups[ $key ] ) / 12 );\n\t\t\t\t$context['missingOrderURL'] = genosys_customer_orders_url( $missing_group, $missing_page ) . '#gco-order-' . $id;\n\t\t\t}\n\t\t}\n\t}\n\t$filter                   = isset( $groups[ $requested ] ) ? $requested : 'all';\n\t$context['total']         = count( $groups['all'] );\n\t$context['filteredTotal'] = count( $groups[ $filter ] );\n\t$context['pages']         = max( 1, (int) ceil( $context['filteredTotal'] / 12 ) );\n\t$context['currentPage']   = min( $page, $context['pages'] );\n\t$context['filter']        = $filter;\n\tforeach ( array_slice( $groups[ $filter ], ( $context['currentPage'] - 1 ) * 12, 12 ) as $id ) {\n\t\t$order = wc_get_order( $id );\n\t\tif ( genosys_order_access_can_view( $order ) ) {\n\t\t\t$context['orders'][] = $order;\n\t\t}\n\t}\n\treturn $context;\n}\n","sha256":"e6d0c2f231cd534d6ca2cd87f8743cb6354b22021965a177c8dd8867f8dd0c73"},"inc/fans-club.php":{"content":"<?php\n/** Self-contained route for the customer and professional club questionnaires. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_register_fans_club_route() {\n\tadd_rewrite_rule( '^fans-club/?$', 'index.php?genosys_fans_club=1', 'top' );\n\tif ( '1' !== get_option( 'genosys_fans_club_route_v1' ) ) {\n\t\tflush_rewrite_rules( false );\n\t\tupdate_option( 'genosys_fans_club_route_v1', '1', false );\n\t}\n}\nadd_action( 'init', 'genosys_register_fans_club_route', 20 );\n\nfunction genosys_fans_club_query_var( $vars ) {\n\t$vars[] = 'genosys_fans_club';\n\treturn $vars;\n}\nadd_filter( 'query_vars', 'genosys_fans_club_query_var' );\n\nfunction genosys_fans_club_request_path() {\n\tif ( empty( $_SERVER['REQUEST_URI'] ) ) {\n\t\treturn false;\n\t}\n\t$request_path = wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH );\n\t$club_path    = wp_parse_url( home_url( '/fans-club/' ), PHP_URL_PATH );\n\treturn is_string( $request_path ) && is_string( $club_path ) && untrailingslashit( $request_path ) === untrailingslashit( $club_path );\n}\n\nfunction genosys_is_fans_club() {\n\treturn genosys_fans_club_request_path() && '1' === (string) get_query_var( 'genosys_fans_club' );\n}\n\n/** Account identity and membership state must never be served from a public page cache. */\nfunction genosys_fans_club_require_account() {\n\tif ( ! genosys_fans_club_request_path() ) { return; }\n\tif ( ! defined( 'DONOTCACHEPAGE' ) ) { define( 'DONOTCACHEPAGE', true ); }\n\tnocache_headers();\n\tif ( ! is_user_logged_in() ) {\n\t\twp_safe_redirect( add_query_arg( 'redirect_to', home_url( '/fans-club/' ), home_url( '/login/' ) ) );\n\t\texit;\n\t}\n}\nadd_action( 'template_redirect', 'genosys_fans_club_require_account', -1 );\n\nfunction genosys_fans_club_main_query( $query ) {\n\tif ( $query->is_main_query() && genosys_fans_club_request_path() && $query->get( 'genosys_fans_club' ) ) {\n\t\t$query->is_home = false;\n\t\t$query->is_404  = false;\n\t}\n}\nadd_action( 'parse_query', 'genosys_fans_club_main_query' );\n\nfunction genosys_fans_club_status( $preempt, $query ) {\n\tif ( genosys_fans_club_request_path() && $query->get( 'genosys_fans_club' ) ) {\n\t\t$query->is_404 = false;\n\t\tstatus_header( 200 );\n\t\treturn true;\n\t}\n\treturn $preempt;\n}\nadd_filter( 'pre_handle_404', 'genosys_fans_club_status', 10, 2 );\n\nfunction genosys_fans_club_template( $template ) {\n\treturn genosys_is_fans_club() ? get_theme_file_path( '/page-fans-club.php' ) : $template;\n}\nadd_filter( 'template_include', 'genosys_fans_club_template', 99 );\n\nfunction genosys_fans_club_title( $title ) {\n\treturn genosys_is_fans_club() ? 'باشگاه مشتریان | ' . get_bloginfo( 'name' ) : $title;\n}\nadd_filter( 'pre_get_document_title', 'genosys_fans_club_title' );\n\nfunction genosys_fans_club_canonical( $redirect ) {\n\treturn genosys_is_fans_club() ? false : $redirect;\n}\nadd_filter( 'redirect_canonical', 'genosys_fans_club_canonical' );\n\nfunction genosys_fans_club_body_class( $classes ) {\n\tif ( genosys_is_fans_club() ) {\n\t\t$classes[] = 'genosys-fans-club';\n\t}\n\treturn $classes;\n}\nadd_filter( 'body_class', 'genosys_fans_club_body_class' );\n","sha256":"5c035b25ea26d93550b0ebe186855b0ee07b230414c97d2df6446681da757d46"},"inc/jalali-date.php":{"content":"<?php\n/** Shamsi formatting for order SMS dates, independent of date-format filters. */\ndefined( 'ABSPATH' ) || exit;\n\n/*\n * Gregorian-to-Jalali conversion adapted from jalaali-js v1.2.8 (jalCal/d2j),\n * based on Kazimierz M. Borkowski's Persian calendar algorithm.\n * https://github.com/jalaali/jalaali-js/tree/v1.2.8\n *\n * MIT License\n * Copyright (c) 2020 Behrang Norouzinia\n *\n * Permission is hereby granted, free of charge, to any person obtaining a copy\n * of this software and associated documentation files (the \"Software\"), to deal\n * in the Software without restriction, including without limitation the rights\n * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n * copies of the Software, and to permit persons to whom the Software is\n * furnished to do so, subject to the following conditions:\n *\n * The above copyright notice and this permission notice shall be included in all\n * copies or substantial portions of the Software.\n *\n * THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\n * IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\n * FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\n * AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\n * LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\n * OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\n * SOFTWARE.\n */\n\n/**\n * Format a real Unix timestamp as YYYY/MM/DD HH:MM in the site's timezone.\n *\n * @param int $timestamp Unix timestamp, without an added local offset.\n * @return string Shamsi date and time, with Persian digits when available.\n */\nfunction genosys_sms_shamsi_date( $timestamp ): string {\n\t// Native formatting bypasses wp_date/date_i18n calendar-conversion filters.\n\t$local_date = ( new DateTimeImmutable( '@' . (int) $timestamp ) )->setTimezone( wp_timezone() );\n\t$gy         = (int) $local_date->format( 'Y' );\n\t$jy         = $gy - 621;\n\t$breaks     = array( -61, 9, 38, 199, 426, 686, 756, 818, 1111, 1181, 1210, 1635, 2060, 2097, 2192, 2262, 2324, 2394, 2456, 3178 );\n\tif ( $jy < $breaks[0] || $jy >= $breaks[ count( $breaks ) - 1 ] ) {\n\t\tthrow new RangeException( 'SMS date is outside the supported Jalali calendar range.' );\n\t}\n\n\t$leap_j = -14;\n\t$jp     = $breaks[0];\n\t$jump   = 0;\n\tforeach ( array_slice( $breaks, 1 ) as $jm ) {\n\t\t$jump = $jm - $jp;\n\t\tif ( $jy < $jm ) {\n\t\t\tbreak;\n\t\t}\n\t\t$leap_j += intdiv( $jump, 33 ) * 8 + intdiv( $jump % 33, 4 );\n\t\t$jp      = $jm;\n\t}\n\t$n       = $jy - $jp;\n\t$leap_j += intdiv( $n, 33 ) * 8 + intdiv( $n % 33 + 3, 4 );\n\tif ( 4 === $jump % 33 && 4 === $jump - $n ) {\n\t\t++$leap_j;\n\t}\n\t$leap_g = intdiv( $gy, 4 ) - intdiv( ( intdiv( $gy, 100 ) + 1 ) * 3, 4 ) - 150;\n\t$march  = 20 + $leap_j - $leap_g;\n\tif ( $jump - $n < 6 ) {\n\t\t$n = $n - $jump + intdiv( $jump + 4, 33 ) * 33;\n\t}\n\t$leap = ( ( $n + 1 ) % 33 - 1 ) % 4;\n\tif ( -1 === $leap ) {\n\t\t$leap = 4;\n\t}\n\n\t// The native Gregorian day-of-year replaces a Julian-day round trip.\n\t$gregorian_leap = 0 === $gy % 4 && ( 0 !== $gy % 100 || 0 === $gy % 400 );\n\t$k              = (int) $local_date->format( 'z' ) - ( 59 + (int) $gregorian_leap + $march - 1 );\n\tif ( $k >= 0 && $k <= 185 ) {\n\t\t$jm = 1 + intdiv( $k, 31 );\n\t\t$jd = $k % 31 + 1;\n\t} else {\n\t\tif ( $k >= 0 ) {\n\t\t\t$k -= 186;\n\t\t} else {\n\t\t\t--$jy;\n\t\t\t$k += 179 + ( 1 === $leap ? 1 : 0 );\n\t\t}\n\t\t$jm = 7 + intdiv( $k, 30 );\n\t\t$jd = $k % 30 + 1;\n\t}\n\t$date_text = sprintf( '%04d/%02d/%02d %s', $jy, $jm, $jd, $local_date->format( 'H:i' ) );\n\treturn function_exists( 'genosys_persian_number' ) ? genosys_persian_number( $date_text ) : $date_text;\n}\n","sha256":"476f7d20c5a274172f4467622400f3b8ea60eaa9eac788b2ffe36f7699ad98bf"},"inc/login-auth.php":{"content":"<?php\n/** SMS verification and customer sign-in for the standalone login page. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_sms_api_key() {\n\tif ( defined( 'GENOSYS_SMSIR_API_KEY' ) ) {\n\t\treturn trim( (string) GENOSYS_SMSIR_API_KEY );\n\t}\n\treturn trim( (string) get_option( 'genosys_smsir_api_key', '' ) );\n}\n\nfunction genosys_sms_template_id() {\n\treturn absint( get_option( 'genosys_smsir_template_id', 163300 ) );\n}\n\nfunction genosys_sms_parameter_name() {\n\t$name = (string) get_option( 'genosys_smsir_parameter_name', 'CODE' );\n\treturn preg_match( '/^[A-Za-z][A-Za-z0-9_]*$/', $name ) ? $name : 'CODE';\n}\n\nfunction genosys_sms_login_script_settings() {\n\tif ( ! genosys_is_login() ) {\n\t\treturn;\n\t}\n\twp_add_inline_script(\n\t\t'genosys-login',\n\t\t'window.genosysLogin = ' . wp_json_encode( array(\n\t\t\t'ajaxUrl' => admin_url( 'admin-ajax.php' ),\n\t\t\t'nonce'   => wp_create_nonce( 'genosys_sms_login' ),\n\t\t\t'homeUrl' => home_url( '/' ),\n\t\t\t'returnUrl' => genosys_login_return_url( isset( $_GET['redirect_to'] ) && is_string( $_GET['redirect_to'] ) ? wp_unslash( $_GET['redirect_to'] ) : '' ),\n\t\t) ) . ';',\n\t\t'before'\n\t);\n}\nadd_action( 'wp_enqueue_scripts', 'genosys_sms_login_script_settings', 20 );\n\nfunction genosys_sms_normalize_phone( $value ) {\n\tif ( ! is_string( $value ) ) {\n\t\treturn '';\n\t}\n\t$digits = strtr( trim( $value ), array(\n\t\t'۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',\n\t\t'۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',\n\t\t'٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',\n\t\t'٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',\n\t) );\n\t$digits = preg_replace( '/[^0-9+]/', '', $digits );\n\tif ( 0 === strpos( $digits, '+98' ) ) {\n\t\t$digits = '0' . substr( $digits, 3 );\n\t} elseif ( 0 === strpos( $digits, '0098' ) ) {\n\t\t$digits = '0' . substr( $digits, 4 );\n\t} elseif ( 0 === strpos( $digits, '98' ) ) {\n\t\t$digits = '0' . substr( $digits, 2 );\n\t}\n\tif ( preg_match( '/^9[0-9]{9}$/', $digits ) ) {\n\t\t$digits = '0' . $digits;\n\t}\n\treturn preg_match( '/^09[0-9]{9}$/', $digits ) ? $digits : '';\n}\n\nfunction genosys_sms_fingerprint( $value ) {\n\treturn hash_hmac( 'sha256', $value, wp_salt( 'nonce' ) );\n}\n\nfunction genosys_sms_client_ip() {\n\t// Do not trust user-controlled forwarding headers for rate limits.\n\treturn isset( $_SERVER['REMOTE_ADDR'] ) ? (string) $_SERVER['REMOTE_ADDR'] : 'unknown';\n}\n\nfunction genosys_sms_counter( $key ) {\n\t$value = get_transient( $key );\n\tif ( ! is_array( $value ) || empty( $value['reset'] ) || (int) $value['reset'] <= time() ) {\n\t\treturn array( 'count' => 0, 'reset' => 0 );\n\t}\n\treturn array( 'count' => isset( $value['count'] ) ? (int) $value['count'] : 0, 'reset' => (int) $value['reset'] );\n}\n\nfunction genosys_sms_increment_counter( $key, $period ) {\n\t$value = genosys_sms_counter( $key );\n\t$reset = $value['reset'] > time() ? $value['reset'] : time() + $period;\n\tset_transient( $key, array( 'count' => $value['count'] + 1, 'reset' => $reset ), max( 1, $reset - time() ) );\n}\n\nfunction genosys_sms_rate_error( $phone ) {\n\t$phone_hash = genosys_sms_fingerprint( $phone );\n\t$ip_hash    = genosys_sms_fingerprint( genosys_sms_client_ip() );\n\t$cooldown   = (int) get_transient( 'genosys_sms_cool_' . $phone_hash );\n\tif ( $cooldown > time() ) {\n\t\treturn $cooldown - time();\n\t}\n\t$phone_count = genosys_sms_counter( 'genosys_sms_day_' . $phone_hash );\n\tif ( $phone_count['count'] >= 5 ) {\n\t\treturn max( 1, $phone_count['reset'] - time() );\n\t}\n\t$ip_count = genosys_sms_counter( 'genosys_sms_hour_' . $ip_hash );\n\tif ( $ip_count['count'] >= 20 ) {\n\t\treturn max( 1, $ip_count['reset'] - time() );\n\t}\n\treturn 0;\n}\n\nfunction genosys_sms_claim_lock( $value ) {\n\t$key   = 'genosys_sms_lock_' . genosys_sms_fingerprint( $value );\n\t$until = time() + 25;\n\tif ( add_option( $key, $until, '', false ) ) {\n\t\treturn $key;\n\t}\n\tif ( (int) get_option( $key, 0 ) <= time() ) {\n\t\tdelete_option( $key );\n\t\tif ( add_option( $key, $until, '', false ) ) {\n\t\t\treturn $key;\n\t\t}\n\t}\n\treturn false;\n}\n\nfunction genosys_sms_json_error( $code, $message, $status = 400, $extra = array() ) {\n\twp_send_json_error( array_merge( array( 'code' => $code, 'message' => $message ), $extra ), $status );\n}\n\nfunction genosys_sms_validate_ajax() {\n\tif ( is_user_logged_in() ) {\n\t\tgenosys_sms_json_error( 'signed_in', 'شما هم‌اکنون وارد حساب خود شده‌اید.', 403 );\n\t}\n\tif ( ! check_ajax_referer( 'genosys_sms_login', 'nonce', false ) ) {\n\t\tgenosys_sms_json_error( 'invalid_request', 'صفحه را تازه‌سازی کنید و دوباره تلاش کنید.', 403 );\n\t}\n}\n\nfunction genosys_smsir_send_code( $phone, $code ) {\n\t$api_key = genosys_sms_api_key();\n\tif ( '' === $api_key || ! genosys_sms_template_id() ) {\n\t\treturn new WP_Error( 'not_configured', 'SMS service is not configured.' );\n\t}\n\t$response = wp_remote_post( 'https://api.sms.ir/v1/send/verify/', array(\n\t\t'timeout'     => 15,\n\t\t'redirection' => 0,\n\t\t'headers'     => array(\n\t\t\t'X-API-KEY'    => $api_key,\n\t\t\t'Content-Type' => 'application/json',\n\t\t\t'Accept'       => 'application/json',\n\t\t),\n\t\t'body'        => wp_json_encode( array(\n\t\t\t'mobile'     => $phone,\n\t\t\t'templateId' => genosys_sms_template_id(),\n\t\t\t'parameters' => array( array( 'name' => genosys_sms_parameter_name(), 'value' => $code ) ),\n\t\t) ),\n\t) );\n\tif ( is_wp_error( $response ) ) {\n\t\treturn new WP_Error( 'sms_unavailable', 'SMS provider request failed.' );\n\t}\n\t$http_status = (int) wp_remote_retrieve_response_code( $response );\n\t$body        = json_decode( wp_remote_ret