preserve_name, PHP_INT_MAX );\n\t}\n\tif ( is_wp_error( $user_id ) ) {\n\t\treturn $user_id;\n\t}\n\treturn get_user_by( 'id', $user_id );\n}\n\nfunction genosys_sms_profile_key( $token ) {\n\treturn 'genosys_sms_profile_' . genosys_sms_fingerprint( $token );\n}\n\nfunction genosys_sms_ajax_verify() {\n\tgenosys_sms_validate_ajax();\n\t$request_id = isset( $_POST['request_id'] ) && is_string( $_POST['request_id'] ) ? wp_unslash( $_POST['request_id'] ) : '';\n\t$raw_code   = isset( $_POST['code'] ) && is_string( $_POST['code'] ) ? wp_unslash( $_POST['code'] ) : '';\n\t$code       = strtr( $raw_code, array(\n\t\t'۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',\n\t\t'۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',\n\t\t'٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',\n\t\t'٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',\n\t) );\n\tif ( ! preg_match( '/^[a-f0-9]{32}$/', $request_id ) || ! preg_match( '/^[0-9]{6}$/', $code ) ) {\n\t\tgenosys_sms_json_error( 'invalid_code', 'کد ۶ رقمی را کامل وارد کنید.' );\n\t}\n\t$verify_lock = genosys_sms_claim_lock( 'verify:' . $request_id );\n\tif ( ! $verify_lock ) {\n\t\tgenosys_sms_json_error( 'busy', 'چند لحظه صبر کنید و دوباره تلاش کنید.', 429 );\n\t}\n\t$otp_key = 'genosys_sms_otp_' . $request_id;\n\t$record  = get_transient( $otp_key );\n\tif ( ! is_array( $record ) || empty( $record['phone'] ) || empty( $record['hash'] ) || empty( $record['expires'] ) || $record['expires'] <= time() ) {\n\t\tdelete_option( $verify_lock );\n\t\tgenosys_sms_json_error( 'expired_code', 'زمان اعتبار کد تمام شده است. کد جدید دریافت کنید.', 400 );\n\t}\n\t$active_key = 'genosys_sms_active_' . genosys_sms_fingerprint( $record['phone'] );\n\tif ( $request_id !== get_transient( $active_key ) ) {\n\t\tdelete_option( $verify_lock );\n\t\tgenosys_sms_json_error( 'expired_code', 'زمان اعتبار کد تمام شده است. کد جدید دریافت کنید.', 400 );\n\t}\n\t$expected = hash_hmac( 'sha256', $record['phone'] . ':' . $code, wp_salt( 'auth' ) );\n\tif ( ! hash_equals( $record['hash'], $expected ) ) {\n\t\t$record['attempts'] = isset( $record['attempts'] ) ? (int) $record['attempts'] + 1 : 1;\n\t\tif ( $record['attempts'] >= 5 ) {\n\t\t\tdelete_transient( $otp_key );\n\t\t\tdelete_transient( $active_key );\n\t\t} else {\n\t\t\tset_transient( $otp_key, $record, max( 1, $record['expires'] - time() ) );\n\t\t}\n\t\tdelete_option( $verify_lock );\n\t\tgenosys_sms_json_error( 'invalid_code', 'کد واردشده صحیح نیست.' );\n\t}\n\n\t// A phone change, registration, and login must resolve the same credential serially.\n\t$phone_lock = genosys_sms_claim_lock( 'phone:' . $record['phone'] );\n\tif ( ! $phone_lock ) {\n\t\tdelete_option( $verify_lock );\n\t\tgenosys_sms_json_error( 'busy', 'چند لحظه صبر کنید و دوباره تلاش کنید.', 429 );\n\t}\n\tif ( $record !== get_transient( $otp_key ) || $request_id !== get_transient( $active_key ) || $record['expires'] <= time() ) {\n\t\tdelete_option( $phone_lock ); delete_option( $verify_lock );\n\t\tgenosys_sms_json_error( 'expired_code', 'این کد دیگر فعال نیست. کد جدید دریافت کنید.', 400 );\n\t}\n\t// Consume the OTP before touching accounts or auth cookies; it cannot be replayed.\n\tdelete_transient( $otp_key );\n\tdelete_transient( $active_key );\n\t$user = genosys_sms_find_existing_user( $record['phone'] );\n\tif ( is_wp_error( $user ) ) {\n\t\tdelete_option( $phone_lock );\n\t\tdelete_option( $verify_lock );\n\t\tif ( 'phone_not_enrolled' === $user->get_error_code() ) {\n\t\t\tgenosys_sms_json_error( 'phone_not_enrolled', 'این شماره برای ورود به حساب فعلی فعال نشده است. پس از ورود معمول به حساب، شماره ورود پیامکی را در تنظیمات ثبت کنید.', 409 );\n\t\t}\n\t\tgenosys_sms_json_error( 'ambiguous_phone', 'این شماره به چند حساب متصل است. با پشتیبانی تماس بگیرید.', 409 );\n\t}\n\tif ( ! $user ) {\n\t\t// A verified new number receives a short-lived, single-use registration handoff.\n\t\t// The account and auth cookie are created only after the profile is completed.\n\t\t$token = bin2hex( random_bytes( 32 ) );\n\t\t$profile = array( 'phone' => $record['phone'], 'expires' => time() + 600 );\n\t\tif ( ! set_transient( genosys_sms_profile_key( $token ), $profile, 600 ) ) {\n\t\t\tdelete_option( $phone_lock );\n\t\t\tdelete_option( $verify_lock );\n\t\t\tgenosys_sms_json_error( 'storage_unavailable', 'تأیید شماره انجام شد، اما تکمیل حساب در دسترس نیست. لطفاً دوباره تلاش کنید.', 503 );\n\t\t}\n\t\tdelete_option( $phone_lock ); delete_option( $verify_lock );\n\t\twp_send_json_success( array( 'needs_profile' => true, 'registration_token' => $token ) );\n\t}\n\tif ( is_wp_error( $user ) || ! $user ) {\n\t\tdelete_option( $phone_lock );\n\t\tdelete_option( $verify_lock );\n\t\tgenosys_sms_json_error( 'account_unavailable', 'ورود انجام نشد. لطفاً دوباره تلاش کنید.', 503 );\n\t}\n\tif ( is_multisite() && ( ! empty( $user->spam ) || ! empty( $user->deleted ) ) ) {\n\t\tdelete_option( $phone_lock );\n\t\tdelete_option( $verify_lock );\n\t\tgenosys_sms_json_error( 'account_unavailable', 'ورود به این حساب امکان‌پذیر نیست.', 403 );\n\t}\n\t$user = genosys_sms_maybe_rename_legacy_customer( $user, $record['phone'] );\n\tif ( ! get_user_meta( $user->ID, 'genosys_phone', true ) ) {\n\t\tadd_user_meta( $user->ID, 'genosys_phone', $record['phone'], true );\n\t}\n\twp_cache_delete( $user->ID, 'user_meta' );\n\tif ( $record['phone'] !== genosys_sms_normalize_phone( (string) get_user_meta( $user->ID, 'genosys_phone', true ) ) ) {\n\t\tdelete_option( $phone_lock ); delete_option( $verify_lock );\n\t\tgenosys_sms_json_error( 'account_unavailable', 'ثبت شماره ورود انجام نشد. دوباره تلاش کنید.', 503 );\n\t}\n\twp_set_current_user( $user->ID, $user->user_login );\n\twp_set_auth_cookie( $user->ID, true );\n\tdo_action( 'wp_login', $user->user_login, $user );\n\tdelete_option( $phone_lock );\n\tdelete_option( $verify_lock );\n\twp_send_json_success( array( 'redirect' => genosys_login_return_url( isset( $_POST['redirect_to'] ) && is_string( $_POST['redirect_to'] ) ? wp_unslash( $_POST['redirect_to'] ) : '' ) ) );\n}\nadd_action( 'wp_ajax_nopriv_genosys_sms_verify', 'genosys_sms_ajax_verify' );\nadd_action( 'wp_ajax_genosys_sms_verify', 'genosys_sms_ajax_verify' );\n\nfunction genosys_sms_profile_error( $code, $message, $status, $profile_lock, $phone_lock = false, $extra = array() ) {\n\tif ( $phone_lock ) {\n\t\tdelete_option( $phone_lock );\n\t}\n\tdelete_option( $profile_lock );\n\tgenosys_sms_json_error( $code, $message, $status, $extra );\n}\n\nfunction genosys_sms_ajax_complete() {\n\tgenosys_sms_validate_ajax();\n\t$token = isset( $_POST['registration_token'] ) && is_string( $_POST['registration_token'] ) ? wp_unslash( $_POST['registration_token'] ) : '';\n\tif ( ! preg_match( '/^[a-f0-9]{64}$/', $token ) ) {\n\t\tgenosys_sms_json_error( 'invalid_registration', 'زمان تکمیل اطلاعات پایان یافته است. دوباره شماره خود را تأیید کنید.', 400 );\n\t}\n\t$profile_lock = genosys_sms_claim_lock( 'profile:' . $token );\n\tif ( ! $profile_lock ) {\n\t\tgenosys_sms_json_error( 'busy', 'چند لحظه صبر کنید و دوباره تلاش کنید.', 429 );\n\t}\n\t$profile_key = genosys_sms_profile_key( $token );\n\t$profile = get_transient( $profile_key );\n\tif ( ! is_array( $profile ) || empty( $profile['phone'] ) || empty( $profile['expires'] ) || $profile['expires'] <= time() || $profile['phone'] !== genosys_sms_normalize_phone( $profile['phone'] ) ) {\n\t\tgenosys_sms_profile_error( 'invalid_registration', 'زمان تکمیل اطلاعات پایان یافته است. دوباره شماره خود را تأیید کنید.', 400, $profile_lock );\n\t}\n\n\t$first_name = isset( $_POST['first_name'] ) && is_string( $_POST['first_name'] ) ? trim( sanitize_text_field( wp_unslash( $_POST['first_name'] ) ) ) : '';\n\t$last_name  = isset( $_POST['last_name'] ) && is_string( $_POST['last_name'] ) ? trim( sanitize_text_field( wp_unslash( $_POST['last_name'] ) ) ) : '';\n\t$raw_email  = isset( $_POST['email'] ) && is_string( $_POST['email'] ) ? trim( wp_unslash( $_POST['email'] ) ) : '';\n\t$email      = '' === $raw_email ? '' : sanitize_email( $raw_email );\n\t$first_len  = function_exists( 'mb_strlen' ) ? mb_strlen( $first_name, 'UTF-8' ) : strlen( $first_name );\n\t$last_len   = function_exists( 'mb_strlen' ) ? mb_strlen( $last_name, 'UTF-8' ) : strlen( $last_name );\n\tif ( '' === $first_name || $first_len > 80 ) {\n\t\tgenosys_sms_profile_error( 'invalid_first_name', 'نام خود را وارد کنید (حداکثر ۸۰ نویسه).', 400, $profile_lock, false, array( 'field' => 'first_name' ) );\n\t}\n\tif ( preg_match( '/[|\\x00-\\x1F\\x7F]/', $first_name ) ) {\n\t\tgenosys_sms_profile_error( 'invalid_first_name', 'نام معتبر وارد کنید.', 400, $profile_lock, false, array( 'field' => 'first_name' ) );\n\t}\n\tif ( '' === $last_name || $last_len > 80 ) {\n\t\tgenosys_sms_profile_error( 'invalid_last_name', 'نام خانوادگی خود را وارد کنید (حداکثر ۸۰ نویسه).', 400, $profile_lock, false, array( 'field' => 'last_name' ) );\n\t}\n\tif ( preg_match( '/[|\\x00-\\x1F\\x7F]/', $last_name ) || mb_strlen( $first_name . ' ' . $last_name, 'UTF-8' ) > 60 ) {\n\t\tgenosys_sms_profile_error( 'invalid_last_name', 'نام و نام خانوادگی باید کوتاه‌تر از ۶۰ نویسه باشند.', 400, $profile_lock, false, array( 'field' => 'last_name' ) );\n\t}\n\tif ( '' !== $raw_email && ( '' === $email || ! is_email( $email ) ) ) {\n\t\tgenosys_sms_profile_error( 'invalid_email', 'ایمیل معتبر نیست.', 400, $profile_lock, false, array( 'field' => 'email' ) );\n\t}\n\n\t$phone_lock = genosys_sms_claim_lock( 'phone:' . $profile['phone'] );\n\tif ( ! $phone_lock ) {\n\t\tgenosys_sms_profile_error( 'busy', 'چند لحظه صبر کنید و دوباره تلاش کنید.', 429, $profile_lock );\n\t}\n\t// Another flow may have claimed this number after its OTP was verified.\n\t$existing = genosys_sms_find_existing_user( $profile['phone'] );\n\tif ( is_wp_error( $existing ) || $existing ) {\n\t\tdelete_transient( $profile_key );\n\t\tgenosys_sms_profile_error( 'phone_in_use', 'این شماره به حسابی متصل شده است. لطفاً دوباره وارد شوید.', 409, $profile_lock, $phone_lock );\n\t}\n\tif ( '' !== $email && email_exists( $email ) ) {\n\t\tgenosys_sms_profile_error( 'email_in_use', 'این ایمیل قبلاً ثبت شده است.', 409, $profile_lock, $phone_lock, array( 'field' => 'email' ) );\n\t}\n\t$user = genosys_sms_create_customer( $profile['phone'], $first_name, $last_name, $email );\n\tif ( is_wp_error( $user ) || ! $user ) {\n\t\tif ( is_wp_error( $user ) && 'existing_user_email' === $user->get_error_code() ) {\n\t\t\tgenosys_sms_profile_error( 'email_in_use', 'این ایمیل قبلاً ثبت شده است.', 409, $profile_lock, $phone_lock, array( 'field' => 'email' ) );\n\t\t}\n\t\tgenosys_sms_profile_error( 'account_unavailable', 'ساخت حساب انجام نشد. لطفاً دوباره تلاش کنید.', 503, $profile_lock, $phone_lock );\n\t}\n\tdelete_transient( $profile_key );\n\twp_set_current_user( $user->ID, $user->user_login );\n\twp_set_auth_cookie( $user->ID, true );\n\tdo_action( 'wp_login', $user->user_login, $user );\n\tdelete_option( $phone_lock );\n\tdelete_option( $profile_lock );\n\twp_send_json_success( array( 'redirect' => genosys_login_return_url( isset( $_POST['redirect_to'] ) && is_string( $_POST['redirect_to'] ) ? wp_unslash( $_POST['redirect_to'] ) : '' ) ) );\n}\nadd_action( 'wp_ajax_nopriv_genosys_sms_complete', 'genosys_sms_ajax_complete' );\nadd_action( 'wp_ajax_genosys_sms_complete', 'genosys_sms_ajax_complete' );\n\nfunction genosys_sms_admin_menu() {\n\tadd_options_page( 'ورود پیامکی ژنوسیس', 'ورود پیامکی ژنوسیس', 'manage_options', 'genosys-sms-login', 'genosys_sms_settings_page' );\n}\nadd_action( 'admin_menu', 'genosys_sms_admin_menu' );\n\nfunction genosys_sms_save_settings() {\n\tif ( ! current_user_can( 'manage_options' ) ) {\n\t\twp_die( esc_html__( 'You are not allowed to manage these settings.', 'genosys' ) );\n\t}\n\tcheck_admin_referer( 'genosys_sms_save_settings' );\n\t$template_id = isset( $_POST['template_id'] ) ? absint( wp_unslash( $_POST['template_id'] ) ) : 0;\n\t$name = isset( $_POST['parameter_name'] ) && is_string( $_POST['parameter_name'] ) ? trim( wp_unslash( $_POST['parameter_name'] ) ) : '';\n\t$key = isset( $_POST['api_key'] ) && is_string( $_POST['api_key'] ) ? trim( wp_unslash( $_POST['api_key'] ) ) : '';\n\t$login_phone_input = isset( $_POST['login_phone'] ) && is_string( $_POST['login_phone'] ) ? trim( wp_unslash( $_POST['login_phone'] ) ) : '';\n\t$login_phone = '' === $login_phone_input ? '' : genosys_sms_normalize_phone( $login_phone_input );\n\t$valid_key = '' === $key || ( strlen( $key ) >= 16 && strlen( $key ) <= 200 && preg_match( '/^[\\x21-\\x7E]+$/D', $key ) );\n\tif ( ! $template_id || ! preg_match( '/^[A-Za-z][A-Za-z0-9_]*$/', $name ) || ! $valid_key || ( '' !== $login_phone_input && '' === $login_phone ) ) {\n\t\twp_safe_redirect( add_query_arg( 'genosys_error', 'invalid', admin_url( 'options-general.php?page=genosys-sms-login' ) ) );\n\t\texit;\n\t}\n\twp_cache_delete( get_current_user_id(), 'user_meta' );\n\t$old_login_phone = genosys_sms_normalize_phone( (string) get_user_meta( get_current_user_id(), 'genosys_phone', true ) );\n\t$credential_phones = array_unique( array_filter( array( $old_login_phone, $login_phone ) ) );\n\tsort( $credential_phones, SORT_STRING );\n\t$credential_locks = array();\n\tforeach ( $credential_phones as $credential_phone ) {\n\t\t$credential_lock = genosys_sms_claim_lock( 'phone:' . $credential_phone );\n\t\tif ( ! $credential_lock ) {\n\t\t\tforeach ( $credential_locks as $held ) { delete_option( $held ); }\n\t\t\twp_safe_redirect( add_query_arg( 'genosys_error', 'busy', admin_url( 'options-general.php?page=genosys-sms-login' ) ) ); exit;\n\t\t}\n\t\t$credential_locks[] = $credential_lock;\n\t}\n\twp_cache_delete( get_current_user_id(), 'user_meta' );\n\tif ( $old_login_phone !== genosys_sms_normalize_phone( (string) get_user_meta( get_current_user_id(), 'genosys_phone', true ) ) ) {\n\t\tforeach ( $credential_locks as $held ) { delete_option( $held ); }\n\t\twp_safe_redirect( add_query_arg( 'genosys_error', 'busy', admin_url( 'options-general.php?page=genosys-sms-login' ) ) ); exit;\n\t}\n\tif ( '' !== $login_phone ) {\n\t\t$existing = genosys_sms_find_existing_user( $login_phone );\n\t\tif ( ( is_wp_error( $existing ) && 'phone_not_enrolled' !== $existing->get_error_code() ) || ( $existing && ! is_wp_error( $existing ) && (int) $existing->ID !== get_current_user_id() ) ) {\n\t\t\tforeach ( $credential_locks as $held ) { delete_option( $held ); }\n\t\t\twp_safe_redirect( add_query_arg( 'genosys_error', 'duplicate', admin_url( 'options-general.php?page=genosys-sms-login' ) ) );\n\t\t\texit;\n\t\t}\n\t}\n\tupdate_option( 'genosys_smsir_template_id', $template_id, false );\n\tupdate_option( 'genosys_smsir_parameter_name', $name, false );\n\tif ( '' !== $key && ! defined( 'GENOSYS_SMSIR_API_KEY' ) ) {\n\t\tupdate_option( 'genosys_smsir_api_key', $key, false );\n\t}\n\tif ( '' === $login_phone ) {\n\t\tdelete_user_meta( get_current_user_id(), 'genosys_phone' );\n\t} else {\n\t\tupdate_user_meta( get_current_user_id(), 'genosys_phone', $login_phone );\n\t}\n\tforeach ( $credential_locks as $held ) { delete_option( $held ); }\n\twp_safe_redirect( add_query_arg( 'genosys_saved', '1', admin_url( 'options-general.php?page=genosys-sms-login' ) ) );\n\texit;\n}\nadd_action( 'admin_post_genosys_sms_save_settings', 'genosys_sms_save_settings' );\n\nfunction genosys_sms_settings_page() {\n\tif ( ! current_user_can( 'manage_options' ) ) {\n\t\treturn;\n\t}\n\t$key_is_constant = defined( 'GENOSYS_SMSIR_API_KEY' );\n\t$key_is_set      = '' !== genosys_sms_api_key();\n\t?>\n\t<div class=\"wrap\" dir=\"rtl\">\n\t\t<h1>ورود پیامکی ژنوسیس</h1>\n\t\t<?php if ( isset( $_GET['genosys_saved'] ) ) : ?>\n\t\t\t<div class=\"notice notice-success is-dismissible\"><p>تنظیمات ذخیره شد.</p></div>\n\t\t<?php elseif ( isset( $_GET['genosys_error'] ) ) : ?>\n\t\t\t<div class=\"notice notice-error\"><p><?php echo 'duplicate' === $_GET['genosys_error'] ? 'این شماره به حساب دیگری متصل است.' : 'یکی از مقادیر واردشده معتبر نیست.'; ?></p></div>\n\t\t<?php endif; ?>\n\t\t<p>کد ورود از طریق قالب تأیید پیامک sms.ir ارسال می‌شود. کلید API فقط روی سرور ذخیره می‌شود و در صفحه ورود نمایش داده نمی‌شود.</p>\n\t\t<form method=\"post\" action=\"<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>\">\n\t\t\t<input type=\"hidden\" name=\"action\" value=\"genosys_sms_save_settings\">\n\t\t\t<?php wp_nonce_field( 'genosys_sms_save_settings' ); ?>\n\t\t\t<table class=\"form-table\" role=\"presentation\">\n\t\t\t\t<tr>\n\t\t\t\t\t<th scope=\"row\"><label for=\"genosys-sms-key\">کلید API پیامک</label></th>\n\t\t\t\t\t<td>\n\t\t\t\t\t\t<?php if ( $key_is_constant ) : ?>\n\t\t\t\t\t\t\t<p>کلید از <code>wp-config.php</code> خوانده می‌شود.</p>\n\t\t\t\t\t\t<?php else : ?>\n\t\t\t\t\t\t\t<input id=\"genosys-sms-key\" name=\"api_key\" type=\"password\" class=\"regular-text\" autocomplete=\"new-password\" placeholder=\"<?php echo esc_attr( $key_is_set ? 'کلید ذخیره شده است؛ برای تغییر، کلید جدید را وارد کنید' : 'کلید API را وارد کنید' ); ?>\">\n\t\t\t\t\t\t<?php endif; ?>\n\t\t\t\t\t</td>\n\t\t\t\t</tr>\n\t\t\t\t<tr>\n\t\t\t\t\t<th scope=\"row\"><label for=\"genosys-sms-template\">شناسه قالب</label></th>\n\t\t\t\t\t<td><input id=\"genosys-sms-template\" name=\"template_id\" type=\"number\" min=\"1\" class=\"small-text\" value=\"<?php echo esc_attr( genosys_sms_template_id() ); ?>\" required></td>\n\t\t\t\t</tr>\n\t\t\t\t<tr>\n\t\t\t\t\t<th scope=\"row\"><label for=\"genosys-sms-parameter\">نام متغیر کد در قالب</label></th>\n\t\t\t\t\t<td><input id=\"genosys-sms-parameter\" name=\"parameter_name\" type=\"text\" class=\"regular-text\" value=\"<?php echo esc_attr( genosys_sms_parameter_name() ); ?>\" required><p class=\"description\">برای متغیر <code>#CODE#</code> فقط نام <code>CODE</code> ارسال می‌شود. حروف بزرگ و کوچک را مطابق قالب پنل تنظیم کنید.</p></td>\n\t\t\t\t</tr>\n\t\t\t\t<tr>\n\t\t\t\t\t<th scope=\"row\"><label for=\"genosys-sms-login-phone\">شماره ورود این مدیر</label></th>\n\t\t\t\t\t<td><input id=\"genosys-sms-login-phone\" name=\"login_phone\" type=\"tel\" class=\"regular-text\" value=\"<?php echo esc_attr( (string) get_user_meta( get_current_user_id(), 'genosys_phone', true ) ); ?>\" placeholder=\"09123456789\"><p class=\"description\">برای ورود پیامکی به حساب مدیر، شماره خود را اینجا ثبت کنید. شماره‌های صورتحساب به‌تنهایی اجازه ورود به حساب مدیر را نمی‌دهند.</p></td>\n\t\t\t\t</tr>\n\t\t\t</table>\n\t\t\t<?php submit_button( 'ذخیره تنظیمات' ); ?>\n\t\t</form>\n\t</div>\n\t<?php\n}\n","sha256":"a0f9fc38b9f88b0994a95a23411aeaa63de009d01d8bd0dc4793caed21183a4f"},"inc/login.php":{"content":"<?php\n/** Standalone phone-login route. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_register_login_route() {\n\tadd_rewrite_rule( '^login/?$', 'index.php?genosys_login=1', 'top' );\n\tif ( '1' !== get_option( 'genosys_login_route_v1' ) ) {\n\t\tflush_rewrite_rules( false );\n\t\tupdate_option( 'genosys_login_route_v1', '1', false );\n\t}\n}\nadd_action( 'init', 'genosys_register_login_route', 20 );\n\nfunction genosys_login_query_var( $vars ) {\n\t$vars[] = 'genosys_login';\n\treturn $vars;\n}\nadd_filter( 'query_vars', 'genosys_login_query_var' );\n\nfunction genosys_login_request_path() {\n\tif ( empty( $_SERVER['REQUEST_URI'] ) ) {\n\t\treturn false;\n\t}\n\t$request_path = wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH );\n\t$login_path   = wp_parse_url( home_url( '/login/' ), PHP_URL_PATH );\n\treturn is_string( $request_path ) && is_string( $login_path ) && untrailingslashit( $request_path ) === untrailingslashit( $login_path );\n}\n\nfunction genosys_is_login() {\n\treturn genosys_login_request_path() && '1' === (string) get_query_var( 'genosys_login' );\n}\n\nfunction genosys_login_main_query( $query ) {\n\tif ( $query->is_main_query() && genosys_login_request_path() && $query->get( 'genosys_login' ) ) {\n\t\t$query->is_home = false;\n\t\t$query->is_404  = false;\n\t}\n}\nadd_action( 'parse_query', 'genosys_login_main_query' );\n\nfunction genosys_login_status( $preempt, $query ) {\n\tif ( genosys_login_request_path() && $query->get( 'genosys_login' ) ) {\n\t\t$query->is_404 = false;\n\t\tstatus_header( 200 );\n\t\treturn true;\n\t}\n\treturn $preempt;\n}\nadd_filter( 'pre_handle_404', 'genosys_login_status', 10, 2 );\n\n/** Only this explicit, same-site return route is accepted by the public SMS flow. */\nfunction genosys_login_return_url( $value ) {\n\t$club = home_url( '/fans-club/' );\n\t$path = wp_parse_url( $club, PHP_URL_PATH );\n\tif ( is_string( $value ) && ( $value === $club || $value === untrailingslashit( $club ) || $value === $path || $value === untrailingslashit( $path ) ) ) {\n\t\treturn $club;\n\t}\n\treturn home_url( '/' );\n}\n\nfunction genosys_login_redirect_signed_in() {\n\tif ( genosys_login_request_path() && is_user_logged_in() ) {\n\t\twp_safe_redirect( genosys_login_return_url( isset( $_GET['redirect_to'] ) && is_string( $_GET['redirect_to'] ) ? wp_unslash( $_GET['redirect_to'] ) : '' ) );\n\t\texit;\n\t}\n}\nadd_action( 'template_redirect', 'genosys_login_redirect_signed_in', 0 );\n\nfunction genosys_login_no_cache() {\n\tif ( genosys_is_login() ) {\n\t\tnocache_headers();\n\t}\n}\nadd_action( 'template_redirect', 'genosys_login_no_cache', 1 );\n\nfunction genosys_login_template( $template ) {\n\treturn genosys_is_login() ? get_theme_file_path( '/page-login.php' ) : $template;\n}\nadd_filter( 'template_include', 'genosys_login_template', 99 );\n\nfunction genosys_login_title( $title ) {\n\treturn genosys_is_login() ? 'ورود به حساب کاربری | ' . get_bloginfo( 'name' ) : $title;\n}\nadd_filter( 'pre_get_document_title', 'genosys_login_title' );\n\nfunction genosys_login_canonical( $redirect ) {\n\treturn genosys_is_login() ? false : $redirect;\n}\nadd_filter( 'redirect_canonical', 'genosys_login_canonical' );\n\nfunction genosys_login_body_class( $classes ) {\n\tif ( genosys_is_login() ) {\n\t\t$classes[] = 'genosys-login-page';\n\t}\n\treturn $classes;\n}\nadd_filter( 'body_class', 'genosys_login_body_class' );\n","sha256":"54e7bfd02752f4e518a2487bd32ae1bcd91b243108317f4dda4ccc1a7eb54085"},"inc/order-access.php":{"content":"<?php\n/**\n * Read-only order access for verified phone owners and the guest checkout browser.\n * Guest verification is purpose-bound and never signs in or creates an account.\n *\n * @package Genosys\n */\n\ndefined( 'ABSPATH' ) || exit;\n\n/** The browser holds an opaque bearer token; personal data stays on the server. */\nfunction genosys_order_access_cookie_name() {\n\treturn 'genosys_order_access';\n}\n\nfunction genosys_order_access_token() {\n\t$name  = genosys_order_access_cookie_name();\n\t$token = isset( $_COOKIE[ $name ] ) && is_string( $_COOKIE[ $name ] ) ? wp_unslash( $_COOKIE[ $name ] ) : '';\n\treturn preg_match( '/^[a-f0-9]{64}$/', $token ) ? $token : '';\n}\n\nfunction genosys_order_access_record_key( $token ) {\n\treturn 'genosys_order_access_browser_' . genosys_sms_fingerprint( 'order-browser:' . $token );\n}\n\nfunction genosys_order_access_set_cookie( $token, $expires ) {\n\tif ( headers_sent() ) {\n\t\treturn false;\n\t}\n\t$stored = setcookie( genosys_order_access_cookie_name(), $token, array(\n\t\t'expires'  => (int) $expires,\n\t\t'path'     => defined( 'COOKIEPATH' ) && COOKIEPATH ? COOKIEPATH : '/',\n\t\t'domain'   => defined( 'COOKIE_DOMAIN' ) && COOKIE_DOMAIN ? COOKIE_DOMAIN : '',\n\t\t'secure'   => is_ssl(),\n\t\t'httponly' => true,\n\t\t'samesite' => 'Lax',\n\t) );\n\tif ( $stored ) {\n\t\t$_COOKIE[ genosys_order_access_cookie_name() ] = $token;\n\t}\n\treturn $stored;\n}\n\n/** Do not extend an expired proof merely because its cookie remains present. */\nfunction genosys_order_access_record( $create = false ) {\n\t$token  = genosys_order_access_token();\n\t$record = $token ? get_transient( genosys_order_access_record_key( $token ) ) : false;\n\tif ( is_array( $record ) && isset( $record['expires'], $record['orders'] ) && (int) $record['expires'] > time() && is_array( $record['orders'] ) ) {\n\t\treturn $record;\n\t}\n\tif ( ! $create || headers_sent() ) {\n\t\treturn false;\n\t}\n\t$token  = bin2hex( random_bytes( 32 ) );\n\t$record = array( 'expires' => time() + 30 * DAY_IN_SECONDS, 'orders' => array(), 'phone' => '', 'phone_expires' => 0, 'phone_user_id' => 0 );\n\tif ( ! set_transient( genosys_order_access_record_key( $token ), $record, 30 * DAY_IN_SECONDS ) || ! genosys_order_access_set_cookie( $token, $record['expires'] ) ) {\n\t\tdelete_transient( genosys_order_access_record_key( $token ) );\n\t\treturn false;\n\t}\n\treturn $record;\n}\n\nfunction genosys_order_access_save_record( $record, $renew = false ) {\n\t$token = genosys_order_access_token();\n\tif ( ! $token || ! is_array( $record ) || empty( $record['expires'] ) ) {\n\t\treturn false;\n\t}\n\t$key     = genosys_order_access_record_key( $token );\n\t$current = get_transient( $key );\n\t// A concurrent clear/revocation must not be undone by an older request.\n\tif ( ! is_array( $current ) || empty( $current['expires'] ) || (int) $current['expires'] <= time() ) {\n\t\treturn false;\n\t}\n\tif ( $renew ) {\n\t\t$record['expires'] = time() + 30 * DAY_IN_SECONDS;\n\t}\n\t$ttl = (int) $record['expires'] - time();\n\tif ( $ttl <= 0 ) {\n\t\treturn false;\n\t}\n\t$saved = set_transient( $key, $record, $ttl );\n\t// WordPress also returns false for an unchanged value.\n\tif ( ! $saved && get_transient( $key ) !== $record ) {\n\t\treturn false;\n\t}\n\treturn ! $renew || genosys_order_access_set_cookie( $token, $record['expires'] );\n}\n\n/** Serialize short browser-record writes, never the external SMS request. */\nfunction genosys_order_access_browser_lock( $token ) {\n\tfor ( $attempt = 0; $attempt < 8; $attempt++ ) {\n\t\t$lock = genosys_sms_claim_lock( 'order-access-browser:' . $token );\n\t\tif ( $lock ) {\n\t\t\treturn $lock;\n\t\t}\n\t\tusleep( 25000 );\n\t}\n\treturn false;\n}\n\nfunction genosys_order_access_mutate_record( $callback, $renew = false ) {\n\t$token = genosys_order_access_token();\n\t$lock  = $token ? genosys_order_access_browser_lock( $token ) : false;\n\tif ( ! $lock ) {\n\t\treturn false;\n\t}\n\ttry {\n\t\t$record = genosys_order_access_record();\n\t\tif ( ! $record ) {\n\t\t\treturn false;\n\t\t}\n\t\t$updated = call_user_func( $callback, $record );\n\t\treturn is_array( $updated ) && genosys_order_access_save_record( $updated, $renew );\n\t} finally {\n\t\tdelete_option( $lock );\n\t}\n}\n\n/** A nonce from another guest's cached page cannot authenticate this browser. */\nfunction genosys_order_access_nonce_action() {\n\t$token = genosys_order_access_token();\n\treturn $token ? 'genosys_order_access_' . genosys_sms_fingerprint( 'order-nonce:' . $token ) : '';\n}\n\nfunction genosys_order_access_client_config() {\n\t$record = genosys_order_access_record( true );\n\treturn array(\n\t\t'ajaxUrl'       => admin_url( 'admin-ajax.php' ),\n\t\t'nonce'         => $record ? wp_create_nonce( genosys_order_access_nonce_action() ) : '',\n\t\t'requestAction' => 'genosys_order_access_request',\n\t\t'verifyAction'  => 'genosys_order_access_verify',\n\t\t'clearAction'   => 'genosys_order_access_clear',\n\t);\n}\n\n/** Billing phone is editable contact information, never an account credential. */\nfunction genosys_order_access_phone() {\n\t$user_id = get_current_user_id();\n\tif ( is_user_logged_in() ) {\n\t\t$phone = genosys_sms_normalize_phone( (string) get_user_meta( $user_id, 'genosys_phone', true ) );\n\t\tif ( $phone ) {\n\t\t\treturn $phone;\n\t\t}\n\t}\n\t$record = genosys_order_access_record();\n\t// A guest or another account's phone proof is never inherited after sign-in/out.\n\treturn $record && ! empty( $record['phone_expires'] ) && (int) $record['phone_expires'] > time() && isset( $record['phone'], $record['phone_user_id'] ) && (int) $record['phone_user_id'] === $user_id ? genosys_sms_normalize_phone( $record['phone'] ) : '';\n}\n\nfunction genosys_order_access_valid_order( $order ) {\n\treturn $order instanceof WC_Order && $order->get_id() > 0 && 'shop_order' === $order->get_type() && ! in_array( $order->get_status(), array( 'draft', 'auto-draft', 'checkout-draft', 'trash' ), true );\n}\n\n/** All phone and browser grants are limited to orders that still belong to a guest. */\nfunction genosys_order_access_can_view( $order ) {\n\tif ( ! genosys_order_access_valid_order( $order ) ) {\n\t\treturn false;\n\t}\n\t$owner = (int) $order->get_customer_id();\n\tif ( $owner > 0 ) {\n\t\treturn is_user_logged_in() && get_current_user_id() === $owner;\n\t}\n\t$phone = genosys_order_access_phone();\n\tif ( $phone && $phone === genosys_sms_normalize_phone( (string) $order->get_billing_phone() ) ) {\n\t\treturn true;\n\t}\n\tif ( function_exists( 'genosys_account_phone_historical_order_allowed' ) && genosys_account_phone_historical_order_allowed( $order ) ) { return true; }\n\t$record = genosys_order_access_record();\n\t$grant  = $record && isset( $record['orders'][ $order->get_id() ] ) ? $record['orders'][ $order->get_id() ] : null;\n\treturn is_array( $grant ) && isset( $grant['key'], $grant['expires'] ) && is_string( $grant['key'] ) && '' !== $grant['key'] && (int) $grant['expires'] > time() && hash_equals( (string) $order->get_order_key(), $grant['key'] );\n}\n\nfunction genosys_order_access_order_ids() {\n\t$record = genosys_order_access_record();\n\t$ids    = array();\n\tif ( ! $record || ! function_exists( 'wc_get_order' ) ) {\n\t\treturn $ids;\n\t}\n\tforeach ( array_slice( $record['orders'], -50, null, true ) as $id => $grant ) {\n\t\tif ( ! is_array( $grant ) || empty( $grant['expires'] ) || (int) $grant['expires'] <= time() ) {\n\t\t\tcontinue;\n\t\t}\n\t\t$order = wc_get_order( absint( $id ) );\n\t\tif ( $order && 0 === (int) $order->get_customer_id() && genosys_order_access_can_view( $order ) ) {\n\t\t\t$ids[] = (int) $order->get_id();\n\t\t}\n\t}\n\treturn array_values( array_unique( $ids ) );\n}\n\nfunction genosys_order_access_has_proof() {\n\treturn is_user_logged_in() || '' !== genosys_order_access_phone() || (bool) genosys_order_access_order_ids();\n}\n\n/** Only server-side checkout data or a constant-time validated order key creates a grant. */\nfunction genosys_order_access_grant_order( $order ) {\n\tif ( ! genosys_order_access_valid_order( $order ) || 0 !== (int) $order->get_customer_id() || '' === (string) $order->get_order_key() ) {\n\t\treturn false;\n\t}\n\t$record = genosys_order_access_record( true );\n\tif ( ! $record ) {\n\t\treturn false;\n\t}\n\treturn genosys_order_access_mutate_record( function ( $current ) use ( $order ) {\n\t\t$id = (int) $order->get_id();\n\t\tunset( $current['orders'][ $id ] );\n\t\t$current['orders'][ $id ] = array( 'key' => (string) $order->get_order_key(), 'expires' => time() + 30 * DAY_IN_SECONDS );\n\t\t$current['orders']        = array_slice( $current['orders'], -50, null, true );\n\t\treturn $current;\n\t}, true );\n}\n\nfunction genosys_order_access_classic_checkout( $order_id, $posted_data, $order ) {\n\tif ( ! $order instanceof WC_Order && function_exists( 'wc_get_order' ) ) {\n\t\t$order = wc_get_order( $order_id );\n\t}\n\tgenosys_order_access_grant_order( $order );\n}\nadd_action( 'woocommerce_checkout_order_processed', 'genosys_order_access_classic_checkout', 2, 3 );\nadd_action( 'woocommerce_store_api_checkout_order_processed', 'genosys_order_access_grant_order', 2, 1 );\n\n/** Run before WooCommerce clears order_awaiting_payment on the received page. */\nfunction genosys_order_access_bootstrap() {\n\tif ( ! function_exists( 'wc_get_order' ) ) {\n\t\treturn;\n\t}\n\t$orders_page = function_exists( 'genosys_is_customer_orders' ) && genosys_is_customer_orders();\n\t$received    = function_exists( 'is_wc_endpoint_url' ) && is_wc_endpoint_url( 'order-received' );\n\t$checkout    = function_exists( 'is_checkout' ) && is_checkout();\n\tif ( ! $orders_page && ! $received && ! $checkout ) {\n\t\treturn;\n\t}\n\tif ( ! defined( 'DONOTCACHEPAGE' ) ) {\n\t\tdefine( 'DONOTCACHEPAGE', true );\n\t}\n\tnocache_headers();\n\tif ( $received ) {\n\t\tglobal $wp;\n\t\t$order_id = isset( $wp->query_vars['order-received'] ) ? absint( $wp->query_vars['order-received'] ) : absint( get_query_var( 'order-received', 0 ) );\n\t\t$key      = isset( $_GET['key'] ) && is_string( $_GET['key'] ) ? wp_unslash( $_GET['key'] ) : '';\n\t\t$order    = $order_id ? wc_get_order( $order_id ) : null;\n\t\tif ( genosys_order_access_valid_order( $order ) && '' !== $key && hash_equals( (string) $order->get_order_key(), $key ) ) {\n\t\t\tgenosys_order_access_grant_order( $order );\n\t\t}\n\t}\n\t// The Woo session is server-side and bound to its own signed checkout cookie.\n\t$record = genosys_order_access_record();\n\tif ( ( $orders_page || $received ) && empty( $record['ignore_checkout_session'] ) && function_exists( 'WC' ) && WC()->session && WC()->session->has_session() ) {\n\t\tforeach ( array( 'order_awaiting_payment', 'store_api_draft_order' ) as $session_key ) {\n\t\t\t$order_id = absint( WC()->session->get( $session_key, 0 ) );\n\t\t\tif ( $order_id ) {\n\t\t\t\tgenosys_order_access_grant_order( wc_get_order( $order_id ) );\n\t\t\t}\n\t\t}\n\t}\n\t// Establish a stable token before the first checkout AJAX request/two tabs.\n\tif ( $orders_page || $checkout ) {\n\t\tgenosys_order_access_record( true );\n\t}\n}\nadd_action( 'template_redirect', 'genosys_order_access_bootstrap', 0 );\n\nfunction genosys_order_access_request_string( $key ) {\n\treturn isset( $_POST[ $key ] ) && is_string( $_POST[ $key ] ) ? wp_unslash( $_POST[ $key ] ) : '';\n}\n\nfunction genosys_order_access_validate_ajax() {\n\tif ( 'POST' !== ( isset( $_SERVER['REQUEST_METHOD'] ) ? $_SERVER['REQUEST_METHOD'] : '' ) || ! genosys_order_access_record() || ! check_ajax_referer( genosys_order_access_nonce_action(), 'nonce', false ) ) {\n\t\tgenosys_sms_json_error( 'invalid_request', 'صفحه را تازه‌سازی کنید و دوباره تلاش کنید.', 403 );\n\t}\n}\n\nfunction genosys_order_access_otp_key( $request_id ) {\n\treturn 'genosys_order_access_otp_' . $request_id;\n}\n\nfunction genosys_order_access_active_key( $phone ) {\n\treturn 'genosys_order_access_active_' . genosys_sms_fingerprint( $phone );\n}\n\nfunction genosys_order_access_delete_otp( $request_id, $phone ) {\n\tdelete_transient( genosys_order_access_otp_key( $request_id ) );\n\t$key = genosys_order_access_active_key( $phone );\n\tif ( $request_id === get_transient( $key ) ) {\n\t\tdelete_transient( $key );\n\t}\n}\n\n/** Reuse the existing provider and its global phone/IP limits, with a separate OTP purpose. */\nfunction genosys_order_access_ajax_request() {\n\tgenosys_order_access_validate_ajax();\n\t$phone = genosys_sms_normalize_phone( genosys_order_access_request_string( 'phone' ) );\n\tif ( ! $phone ) {\n\t\tgenosys_sms_json_error( 'invalid_phone', 'شماره تماس معتبر نیست (مثال: 09123456789).' );\n\t}\n\tif ( '' === genosys_sms_api_key() || ! genosys_sms_template_id() ) {\n\t\tgenosys_sms_json_error( 'not_configured', 'ارسال کد در حال حاضر در دسترس نیست. لطفاً بعداً تلاش کنید.', 503 );\n\t}\n\t$retry = genosys_sms_rate_error( $phone );\n\tif ( $retry > 0 ) {\n\t\tgenosys_sms_json_error( 'rate_limited', 'برای دریافت کد بعدی کمی صبر کنید.', 429, array( 'retry_after' => $retry ) );\n\t}\n\t$ip_lock = genosys_sms_claim_lock( 'ip:' . genosys_sms_client_ip() );\n\tif ( ! $ip_lock ) {\n\t\tgenosys_sms_json_error( 'busy', 'چند لحظه صبر کنید و دوباره تلاش کنید.', 429, array( 'retry_after' => 5 ) );\n\t}\n\t$phone_lock = genosys_sms_claim_lock( 'phone:' . $phone );\n\tif ( ! $phone_lock ) {\n\t\tdelete_option( $ip_lock );\n\t\tgenosys_sms_json_error( 'busy', 'چند لحظه صبر کنید و دوباره تلاش کنید.', 429, array( 'retry_after' => 5 ) );\n\t}\n\t$result     = null;\n\t$request_id = '';\n\ttry {\n\t\t$retry = genosys_sms_rate_error( $phone );\n\t\tif ( $retry > 0 ) {\n\t\t\t$result = new WP_Error( 'rate_limited', 'برای دریافت کد بعدی کمی صبر کنید.', array( 'status' => 429, 'retry_after' => $retry ) );\n\t\t} else {\n\t\t\t$code       = (string) random_int( 100000, 999999 );\n\t\t\t$request_id = bin2hex( random_bytes( 16 ) );\n\t\t\t$sent       = genosys_smsir_send_code( $phone, $code );\n\t\t\tif ( is_wp_error( $sent ) ) {\n\t\t\t\t$result = new WP_Error( 'sms_unavailable', 'ارسال کد انجام نشد. لطفاً دوباره تلاش کنید.', array( 'status' => 503 ) );\n\t\t\t} else {\n\t\t\t\t$phone_hash = genosys_sms_fingerprint( $phone );\n\t\t\t\t$ip_hash    = genosys_sms_fingerprint( genosys_sms_client_ip() );\n\t\t\t\tset_transient( 'genosys_sms_cool_' . $phone_hash, time() + 120, 120 );\n\t\t\t\tgenosys_sms_increment_counter( 'genosys_sms_day_' . $phone_hash, DAY_IN_SECONDS );\n\t\t\t\tgenosys_sms_increment_counter( 'genosys_sms_hour_' . $ip_hash, HOUR_IN_SECONDS );\n\t\t\t\t$otp = array(\n\t\t\t\t\t'purpose'  => 'orders',\n\t\t\t\t\t'browser'  => genosys_sms_fingerprint( 'order-browser:' . genosys_order_access_token() ),\n\t\t\t\t\t'user_id'  => get_current_user_id(),\n\t\t\t\t\t'phone'    => $phone,\n\t\t\t\t\t'hash'     => hash_hmac( 'sha256', 'genosys-order-access:' . $phone . ':' . $code, wp_salt( 'auth' ) ),\n\t\t\t\t\t'expires'  => time() + 120,\n\t\t\t\t\t'attempts' => 0,\n\t\t\t\t);\n\t\t\t\t$active_key = genosys_order_access_active_key( $phone );\n\t\t\t\t$old_id     = get_transient( $active_key );\n\t\t\t\tif ( ! set_transient( genosys_order_access_otp_key( $request_id ), $otp, 120 ) || ! set_transient( $active_key, $request_id, 120 ) ) {\n\t\t\t\t\tgenosys_order_access_delete_otp( $request_id, $phone );\n\t\t\t\t\t$result = new WP_Error( 'storage_unavailable', 'ارسال کد در حال حاضر در دسترس نیست. لطفاً بعداً تلاش کنید.', array( 'status' => 503 ) );\n\t\t\t\t} elseif ( is_string( $old_id ) && preg_match( '/^[a-f0-9]{32}$/', $old_id ) ) {\n\t\t\t\t\tdelete_transient( genosys_order_access_otp_key( $old_id ) );\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t} catch ( Throwable $exception ) {\n\t\t$result = new WP_Error( 'sms_unavailable', 'ارسال کد انجام نشد. لطفاً دوباره تلاش کنید.', array( 'status' => 503 ) );\n\t} finally {\n\t\tdelete_option( $phone_lock );\n\t\tdelete_option( $ip_lock );\n\t}\n\tif ( is_wp_error( $result ) ) {\n\t\t$data = $result->get_error_data();\n\t\tgenosys_sms_json_error( $result->get_error_code(), $result->get_error_message(), isset( $data['status'] ) ? $data['status'] : 400, isset( $data['retry_after'] ) ? array( 'retry_after' => $data['retry_after'] ) : array() );\n\t}\n\twp_send_json_success( array( 'request_id' => $request_id, 'expires_in' => 120 ) );\n}\nadd_action( 'wp_ajax_nopriv_genosys_order_access_request', 'genosys_order_access_ajax_request' );\nadd_action( 'wp_ajax_genosys_order_access_request', 'genosys_order_access_ajax_request' );\n\nfunction genosys_order_access_ajax_verify() {\n\tgenosys_order_access_validate_ajax();\n\t$request_id = genosys_order_access_request_string( 'request_id' );\n\tif ( ! preg_match( '/^[a-f0-9]{32}$/', $request_id ) ) {\n\t\tgenosys_sms_json_error( 'invalid_code', 'کد تأیید معتبر نیست یا منقضی شده است.' );\n\t}\n\t$lock = genosys_sms_claim_lock( 'order-access-otp:' . $request_id );\n\tif ( ! $lock ) {\n\t\tgenosys_sms_json_error( 'busy', 'چند لحظه صبر کنید و دوباره تلاش کنید.', 429 );\n\t}\n\t$result = new WP_Error( 'invalid_code', 'کد تأیید معتبر نیست یا منقضی شده است.' );\n\t$phone  = '';\n\ttry {\n\t\t$otp     = get_transient( genosys_order_access_otp_key( $request_id ) );\n\t\t$browser = genosys_sms_fingerprint( 'order-browser:' . genosys_order_access_token() );\n\t\tif ( is_array( $otp ) && isset( $otp['purpose'], $otp['browser'], $otp['user_id'], $otp['phone'], $otp['hash'], $otp['expires'], $otp['attempts'] ) && 'orders' === $otp['purpose'] && is_string( $otp['browser'] ) && hash_equals( $otp['browser'], $browser ) && (int) $otp['user_id'] === get_current_user_id() && (int) $otp['expires'] > time() && (int) $otp['attempts'] < 5 && $request_id === get_transient( genosys_order_access_active_key( $otp['phone'] ) ) ) {\n\t\t\t$code = strtr( trim( genosys_order_access_request_string( 'code' ) ), array( '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4', '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9', '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4', '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9' ) );\n\t\t\t$otp['attempts']++;\n\t\t\tif ( ! set_transient( genosys_order_access_otp_key( $request_id ), $otp, max( 1, (int) $otp['expires'] - time() ) ) ) {\n\t\t\t\t$result = new WP_Error( 'storage_unavailable', 'تأیید شماره انجام نشد. دوباره تلاش کنید.' );\n\t\t\t} elseif ( preg_match( '/^[0-9]{6}$/', $code ) && hash_equals( $otp['hash'], hash_hmac( 'sha256', 'genosys-order-access:' . $otp['phone'] . ':' . $code, wp_salt( 'auth' ) ) ) ) {\n\t\t\t\t$saved = genosys_order_access_mutate_record( function ( $current ) use ( $otp ) {\n\t\t\t\t\t$current['phone']         = $otp['phone'];\n\t\t\t\t\t$current['phone_expires'] = time() + 12 * HOUR_IN_SECONDS;\n\t\t\t\t\t$current['phone_user_id'] = get_current_user_id();\n\t\t\t\t\treturn $current;\n\t\t\t\t}, true );\n\t\t\t\tif ( $saved ) {\n\t\t\t\t\t$phone  = $otp['phone'];\n\t\t\t\t\t$result = true;\n\t\t\t\t\tgenosys_order_access_delete_otp( $request_id, $phone );\n\t\t\t\t} else {\n\t\t\t\t\t$result = new WP_Error( 'storage_unavailable', 'تأیید شماره انجام نشد. دوباره تلاش کنید.' );\n\t\t\t\t}\n\t\t\t} elseif ( (int) $otp['attempts'] >= 5 ) {\n\t\t\t\tgenosys_order_access_delete_otp( $request_id, $otp['phone'] );\n\t\t\t}\n\t\t}\n\t} catch ( Throwable $exception ) {\n\t\t$result = new WP_Error( 'storage_unavailable', 'تأیید شماره انجام نشد. دوباره تلاش کنید.' );\n\t} finally {\n\t\tdelete_option( $lock );\n\t}\n\tif ( is_wp_error( $result ) ) {\n\t\tgenosys_sms_json_error( $result->get_error_code(), $result->get_error_message() );\n\t}\n\twp_send_json_success( array( 'verified' => true, 'phone' => $phone, 'nonce' => wp_create_nonce( genosys_order_access_nonce_action() ) ) );\n}\nadd_action( 'wp_ajax_nopriv_genosys_order_access_verify', 'genosys_order_access_ajax_verify' );\nadd_action( 'wp_ajax_genosys_order_access_verify', 'genosys_order_access_ajax_verify' );\n\n/** Forget this browser's guest proof, without affecting WordPress authentication. */\nfunction genosys_order_access_ajax_clear() {\n\tgenosys_order_access_validate_ajax();\n\t$token = genosys_order_access_token();\n\t$lock  = genosys_order_access_browser_lock( $token );\n\tif ( ! $lock ) {\n\t\tgenosys_sms_json_error( 'busy', 'چند لحظه صبر کنید و دوباره تلاش کنید.', 429 );\n\t}\n\ttry {\n\t\tdelete_transient( genosys_order_access_record_key( $token ) );\n\t} finally {\n\t\tdelete_option( $lock );\n\t}\n\tunset( $_COOKIE[ genosys_order_access_cookie_name() ] );\n\t$record = genosys_order_access_record( true );\n\tif ( ! $record ) {\n\t\tgenosys_sms_json_error( 'storage_unavailable', 'دوباره تلاش کنید.', 503 );\n\t}\n\t// A subsequent visit must not restore a proof the visitor deliberately forgot.\n\tif ( ! genosys_order_access_mutate_record( function ( $current ) {\n\t\t$current['ignore_checkout_session'] = true;\n\t\treturn $current;\n\t} ) ) {\n\t\tgenosys_sms_json_error( 'storage_unavailable', 'دوباره تلاش کنید.', 503 );\n\t}\n\twp_send_json_success( array( 'verified' => false, 'phone' => '', 'nonce' => wp_create_nonce( genosys_order_access_nonce_action() ) ) );\n}\nadd_action( 'wp_ajax_nopriv_genosys_order_access_clear', 'genosys_order_access_ajax_clear' );\nadd_action( 'wp_ajax_genosys_order_access_clear', 'genosys_order_access_ajax_clear' );\n","sha256":"e377999248266c00754eac30433c0a65fb9633bee05f0ce3d1362c2efdeda5cc"},"inc/order-sms.php":{"content":"<?php\n/** Customer order-submission SMS, separate from login codes and payment handling. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_order_sms_template_id() {\n\t$value = get_option( 'genosys_order_sms_template_id', '' );\n\tif ( ! is_scalar( $value ) || is_bool( $value ) ) {\n\t\treturn 0;\n\t}\n\t$value = genosys_checkout_ascii_digits( trim( (string) $value ) );\n\treturn preg_match( '/^[1-9][0-9]{0,9}$/D', $value ) && (float) $value <= 2147483647 ? (int) $value : 0;\n}\n\n/** Log only an internal reason and order ID; never provider bodies or credentials. */\nfunction genosys_order_sms_log( $order_id, $reason ) {\n\tif ( function_exists( 'wc_get_logger' ) ) {\n\t\twc_get_logger()->warning( 'Order submission SMS could not be confirmed.', array( 'source' => 'genosys-order-sms', 'order_id' => absint( $order_id ), 'reason' => sanitize_key( $reason ) ) );\n\t}\n}\n\n/** Enqueue after validated checkout submission, never on order/page reads. */\nfunction genosys_order_sms_queue( $order ) {\n\tif ( ! $order instanceof WC_Order || 'shop_order' !== $order->get_type() || ! $order->get_id() || $order->has_status( array( 'checkout-draft', 'trash' ) ) || ! genosys_order_sms_template_id() || '' === genosys_sms_api_key() || '' === genosys_sms_normalize_phone( $order->get_billing_phone() ) ) {\n\t\treturn;\n\t}\n\ttry {\n\t\t$order->read_meta_data( true );\n\t\tif ( $order->get_meta( '_genosys_order_sms_attempted_at', true ) ) {\n\t\t\treturn;\n\t\t}\n\t\t$args = array( (int) $order->get_id() );\n\t\tif ( function_exists( 'as_enqueue_async_action' ) ) {\n\t\t\t$queued = as_enqueue_async_action( 'genosys_order_sms_send', $args, 'genosys-order-sms', true );\n\t\t\tif ( $queued || ( function_exists( 'as_has_scheduled_action' ) && as_has_scheduled_action( 'genosys_order_sms_send', $args, 'genosys-order-sms' ) ) ) {\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t\tif ( ! wp_next_scheduled( 'genosys_order_sms_send', $args ) && ! wp_schedule_single_event( time(), 'genosys_order_sms_send', $args ) ) {\n\t\t\tgenosys_order_sms_log( $order->get_id(), 'queue_unavailable' );\n\t\t}\n\t} catch ( Throwable $exception ) {\n\t\tgenosys_order_sms_log( $order->get_id(), 'queue_unavailable' );\n\t}\n}\n\nfunction genosys_order_sms_classic_checkout( $order_id, $posted_data, $order ) {\n\tgenosys_order_sms_queue( $order instanceof WC_Order ? $order : wc_get_order( $order_id ) );\n}\nadd_action( 'woocommerce_checkout_order_processed', 'genosys_order_sms_classic_checkout', 20, 3 );\nadd_action( 'woocommerce_store_api_checkout_order_processed', 'genosys_order_sms_queue', 20, 1 );\n\n/** Serialize workers without sharing the login or receipt-upload locks. */\nfunction genosys_order_sms_lock( $order_id, $event_id = '' ) {\n\tglobal $wpdb;\n\t$name = 'genosys_order_sms_lock_' . absint( $order_id );\n\tif ( '' !== $event_id ) {\n\t\t$name .= '_' . md5( (string) $event_id );\n\t}\n\t$value = wp_json_encode( array( 'time' => time(), 'token' => wp_generate_uuid4() ) );\n\tif ( add_option( $name, $value, '', false ) ) {\n\t\treturn array( $name, $value );\n\t}\n\t$old = get_option( $name, '' );\n\t$row = is_string( $old ) ? json_decode( $old, true ) : null;\n\tif ( is_array( $row ) && isset( $row['time'] ) && time() - (int) $row['time'] > 120 ) {\n\t\t$deleted = $wpdb->query( $wpdb->prepare( \"DELETE FROM {$wpdb->options} WHERE option_name = %s AND option_value = %s\", $name, $old ) );\n\t\tif ( $deleted ) {\n\t\t\twp_cache_delete( $name, 'options' );\n\t\t\tif ( add_option( $name, $value, '', false ) ) {\n\t\t\t\treturn array( $name, $value );\n\t\t\t}\n\t\t}\n\t}\n\treturn false;\n}\n\nfunction genosys_order_sms_unlock( $lock ) {\n\tglobal $wpdb;\n\tif ( is_array( $lock ) && 2 === count( $lock ) ) {\n\t\t$wpdb->query( $wpdb->prepare( \"DELETE FROM {$wpdb->options} WHERE option_name = %s AND option_value = %s\", $lock[0], $lock[1] ) );\n\t\twp_cache_delete( $lock[0], 'options' );\n\t}\n}\n\n/** Build only the template's three values from saved WooCommerce order data. */\nfunction genosys_order_sms_parameters( $order ) {\n\t$name = trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() );\n\t$date = $order->get_date_created();\n\tif ( ! $date ) {\n\t\treturn null;\n\t}\n\t// Use the real instant; WC_DateTime::date() adds a local offset before formatting.\n\t$date_text = genosys_sms_shamsi_date( $date->getTimestamp() );\n\treturn array(\n\t\tarray( 'name' => 'NAME', 'value' => sanitize_text_field( '' !== $name ? $name : 'مشتری' ) ),\n\t\tarray( 'name' => 'ORDERID', 'value' => sanitize_text_field( (string) $order->get_order_number() ) ),\n\t\tarray( 'name' => 'DATE', 'value' => sanitize_text_field( $date_text ) ),\n\t);\n}\n\n/** Shared provider transport; callers persist their own attempt before sending. */\nfunction genosys_order_sms_request( $phone, $template_id, $parameters, $api_key ) {\n\t$response = wp_remote_post( 'https://api.sms.ir/v1/send/verify/', array(\n\t\t'timeout' => 15,\n\t\t'redirection' => 0,\n\t\t'headers' => array( 'X-API-KEY' => $api_key, 'Content-Type' => 'application/json', 'Accept' => 'application/json' ),\n\t\t'body' => wp_json_encode( array( 'mobile' => $phone, 'templateId' => $template_id, 'parameters' => $parameters ) ),\n\t) );\n\t$http_status = is_wp_error( $response ) ? 0 : (int) wp_remote_retrieve_response_code( $response );\n\t$body = is_wp_error( $response ) ? null : json_decode( wp_remote_retrieve_body( $response ), true );\n\t$message_id = is_array( $body ) && isset( $body['data']['messageId'] ) && ( is_string( $body['data']['messageId'] ) || is_int( $body['data']['messageId'] ) ) ? (string) $body['data']['messageId'] : '';\n\t$sent = $http_status >= 200 && $http_status < 300 && is_array( $body ) && isset( $body['status'] ) && in_array( $body['status'], array( 1, '1' ), true ) && preg_match( '/^[1-9][0-9]*$/D', $message_id );\n\treturn array(\n\t\t'status' => $sent ? 'sent' : ( $http_status >= 400 && $http_status < 500 ? 'failed' : 'unconfirmed' ),\n\t\t'message_id' => $sent ? $message_id : '',\n\t\t'reason' => $sent ? '' : ( is_wp_error( $response ) ? 'provider_unavailable' : 'provider_rejected' ),\n\t);\n}\n\n/** A durable attempt claim prevents duplicate sends, including ambiguous timeouts. */\nfunction genosys_order_sms_send( $order_id ) {\n\tif ( ! function_exists( 'wc_get_order' ) ) {\n\t\treturn;\n\t}\n\t$order_id = absint( $order_id );\n\t$lock = $order_id ? genosys_order_sms_lock( $order_id ) : false;\n\tif ( ! $lock ) {\n\t\treturn;\n\t}\n\ttry {\n\t\t$order = wc_get_order( $order_id );\n\t\tif ( ! $order instanceof WC_Order || 'shop_order' !== $order->get_type() || $order->has_status( array( 'checkout-draft', 'trash' ) ) ) {\n\t\t\treturn;\n\t\t}\n\t\t$order->read_meta_data( true );\n\t\tif ( $order->get_meta( '_genosys_order_sms_attempted_at', true ) ) {\n\t\t\treturn;\n\t\t}\n\t\t$template_id = genosys_order_sms_template_id();\n\t\t$api_key = genosys_sms_api_key();\n\t\t$phone = genosys_sms_normalize_phone( $order->get_billing_phone() );\n\t\t$parameters = genosys_order_sms_parameters( $order );\n\t\tif ( ! $template_id || '' === $api_key || '' === $phone || ! $parameters ) {\n\t\t\treturn;\n\t\t}\n\t\t$attempted_at = time();\n\t\t$order->update_meta_data( '_genosys_order_sms_attempted_at', $attempted_at );\n\t\t$order->update_meta_data( '_genosys_order_sms_template_id', $template_id );\n\t\t$order->update_meta_data( '_genosys_order_sms_status', 'attempting' );\n\t\t$order->save_meta_data();\n\t\t$order->read_meta_data( true );\n\t\tif ( $attempted_at !== (int) $order->get_meta( '_genosys_order_sms_attempted_at', true ) ) {\n\t\t\tthrow new RuntimeException( 'claim_unavailable' );\n\t\t}\n\t\t$result = genosys_order_sms_request( $phone, $template_id, $parameters, $api_key );\n\t\tif ( 'sent' === $result['status'] ) {\n\t\t\t$order->update_meta_data( '_genosys_order_sms_status', 'sent' );\n\t\t\t$order->update_meta_data( '_genosys_order_sms_message_id', $result['message_id'] );\n\t\t\t$order->update_meta_data( '_genosys_order_sms_sent_at', time() );\n\t\t} else {\n\t\t\t$order->update_meta_data( '_genosys_order_sms_status', $result['status'] );\n\t\t\tgenosys_order_sms_log( $order_id, $result['reason'] );\n\t\t}\n\t\t$order->save_meta_data();\n\t} catch ( Throwable $exception ) {\n\t\tgenosys_order_sms_log( $order_id, 'send_unconfirmed' );\n\t} finally {\n\t\tgenosys_order_sms_unlock( $lock );\n\t}\n}\nadd_action( 'genosys_order_sms_send', 'genosys_order_sms_send', 10, 1 );\n","sha256":"32db89bffa0a4e236e2ff7bf9089e92b0178b25d9b6718a0e06dd4f323e6ad9f"},"inc/order-status-sms.php":{"content":"<?php\n/** Customer notifications for saved WooCommerce status changes. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_order_status_sms_template_id() {\n\t$value = get_option( 'genosys_order_status_sms_template_id', '' );\n\tif ( ! is_scalar( $value ) || is_bool( $value ) ) {\n\t\treturn 0;\n\t}\n\t$value = genosys_checkout_ascii_digits( trim( (string) $value ) );\n\treturn preg_match( '/^[1-9][0-9]{0,9}$/D', $value ) && (float) $value <= 2147483647 ? (int) $value : 0;\n}\n\nfunction genosys_order_status_sms_log( $order_id, $reason ) {\n\tif ( function_exists( 'wc_get_logger' ) ) {\n\t\twc_get_logger()->warning( 'Order status SMS could not be confirmed.', array( 'source' => 'genosys-order-status-sms', 'order_id' => absint( $order_id ), 'reason' => sanitize_key( $reason ) ) );\n\t}\n}\n\n/** Suppress only the first checkout request's immediate gateway status setup. */\nfunction genosys_order_status_sms_initial_request( $order_id, $mark = false ) {\n\tstatic $initial_orders = array();\n\tif ( $mark ) {\n\t\t$initial_orders[ absint( $order_id ) ] = true;\n\t}\n\treturn isset( $initial_orders[ absint( $order_id ) ] );\n}\n\nfunction genosys_order_status_sms_initialize_checkout( $order ) {\n\tif ( ! $order instanceof WC_Order || 'shop_order' !== $order->get_type() || ! $order->get_id() ) {\n\t\treturn;\n\t}\n\ttry {\n\t\t$order->read_meta_data( true );\n\t\tif ( ! $order->get_meta( '_genosys_order_status_sms_checkout_initialized', true ) ) {\n\t\t\tgenosys_order_status_sms_initial_request( $order->get_id(), true );\n\t\t\t$order->update_meta_data( '_genosys_order_status_sms_checkout_initialized', time() );\n\t\t\t$order->save_meta_data();\n\t\t}\n\t} catch ( Throwable $exception ) {\n\t\tgenosys_order_status_sms_log( $order->get_id(), 'initialization_unavailable' );\n\t}\n}\n\nfunction genosys_order_status_sms_initialize_classic( $order_id, $posted_data, $order ) {\n\tgenosys_order_status_sms_initialize_checkout( $order instanceof WC_Order ? $order : wc_get_order( $order_id ) );\n}\nadd_action( 'woocommerce_checkout_order_processed', 'genosys_order_status_sms_initialize_classic', 1, 3 );\nadd_action( 'woocommerce_store_api_checkout_order_processed', 'genosys_order_status_sms_initialize_checkout', 1, 1 );\n\nfunction genosys_order_status_sms_event_key( $event_id ) {\n\treturn is_string( $event_id ) && preg_match( '/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/D', $event_id ) ? '_genosys_order_status_sms_event_' . str_replace( '-', '', $event_id ) : '';\n}\n\n/** Persist an immutable snapshot alongside each actual status save. */\nfunction genosys_order_status_sms_capture( $order ) {\n\tif ( ! $order instanceof WC_Order || 'shop_order' !== $order->get_type() || ! $order->get_id() || genosys_order_status_sms_initial_request( $order->get_id() ) ) {\n\t\treturn;\n\t}\n\ttry {\n\t\t$changes = $order->get_changes();\n\t\tif ( ! isset( $changes['status'] ) ) {\n\t\t\treturn;\n\t\t}\n\t\t// WC_Data::get_data() contains persisted properties, before dirty changes.\n\t\t$data = $order->get_data();\n\t\t$from = isset( $data['status'] ) ? (string) $data['status'] : '';\n\t\t$to = (string) $changes['status'];\n\t\t$ignored = array( '', 'draft', 'auto-draft', 'checkout-draft', 'trash' );\n\t\t$template_id = genosys_order_status_sms_template_id();\n\t\t$phone = genosys_sms_normalize_phone( $order->get_billing_phone() );\n\t\tif ( function_exists( 'genosys_account_notification_order_allowed' ) && ! genosys_account_notification_order_allowed( $order, 'order_status_sms', $phone ) ) { return; }\n\t\tif ( $from === $to || in_array( $from, $ignored, true ) || in_array( $to, $ignored, true ) || ! $template_id || '' === genosys_sms_api_key() || '' === $phone ) {\n\t\t\treturn;\n\t\t}\n\t\t$event_id = wp_generate_uuid4();\n\t\t$name = trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() );\n\t\t$event = array(\n\t\t\t'id' => $event_id,\n\t\t\t'from' => $from,\n\t\t\t'to' => $to,\n\t\t\t'template_id' => $template_id,\n\t\t\t'phone' => $phone,\n\t\t\t'parameters' => array(\n\t\t\t\tarray( 'name' => 'NAME', 'value' => sanitize_text_field( '' !== $name ? $name : 'مشتری' ) ),\n\t\t\t\tarray( 'name' => 'STATUS', 'value' => sanitize_text_field( wc_get_order_status_name( $to ) ) ),\n\t\t\t),\n\t\t\t'created_at' => time(),\n\t\t\t'attempted_at' => 0,\n\t\t\t'status' => 'pending',\n\t\t);\n\t\t$order->update_meta_data( '_genosys_order_status_sms_transition_id', $event_id );\n\t\t$order->update_meta_data( genosys_order_status_sms_event_key( $event_id ), $event );\n\t} catch ( Throwable $exception ) {\n\t\tgenosys_order_status_sms_log( $order->get_id(), 'snapshot_unavailable' );\n\t}\n}\nadd_action( 'woocommerce_before_order_object_save', 'genosys_order_status_sms_capture', 9999, 1 );\n\nfunction genosys_order_status_sms_enqueue_event( $order_id, $event_id ) {\n\tif ( function_exists( 'genosys_account_notification_order_allowed' ) ) {\n\t\t$order = wc_get_order( $order_id );\n\t\tif ( ! $order instanceof WC_Order ) { return; }\n\t\t$order->read_meta_data( true );\n\t\t$key = genosys_order_status_sms_event_key( $event_id );\n\t\t$event = $key ? $order->get_meta( $key, true ) : null;\n\t\tif ( ! genosys_account_notification_order_allowed( $order, 'order_status_sms', is_array( $event ) ? ( $event['phone'] ?? '' ) : '' ) ) {\n\t\t\tif ( is_array( $event ) && empty( $event['attempted_at'] ) ) {\n\t\t\t\t$event['attempted_at'] = time(); $event['status'] = 'suppressed';\n\t\t\t\t$order->update_meta_data( $key, $event ); $order->save_meta_data();\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t}\n\t$args = array( (int) $order_id, $event_id );\n\tif ( function_exists( 'as_enqueue_async_action' ) ) {\n\t\t$queued = as_enqueue_async_action( 'genosys_order_status_sms_send', $args, 'genosys-order-status-sms', true );\n\t\tif ( $queued || ( function_exists( 'as_has_scheduled_action' ) && as_has_scheduled_action( 'genosys_order_status_sms_send', $args, 'genosys-order-status-sms' ) ) ) {\n\t\t\treturn;\n\t\t}\n\t}\n\tif ( ! wp_next_scheduled( 'genosys_order_status_sms_send', $args ) && ! wp_schedule_single_event( time(), 'genosys_order_status_sms_send', $args ) ) {\n\t\tgenosys_order_status_sms_log( $order_id, 'queue_unavailable' );\n\t}\n}\n\n/** Nested status hooks can change the shared object; use saved event records. */\nfunction genosys_order_status_sms_queue( $order_id, $from, $to, $order ) {\n\tif ( ! $order instanceof WC_Order || 'shop_order' !== $order->get_type() || absint( $order_id ) !== $order->get_id() || $from === $to || genosys_order_status_sms_initial_request( $order_id ) ) {\n\t\treturn;\n\t}\n\ttry {\n\t\t$saved_order = wc_get_order( $order_id );\n\t\tif ( ! $saved_order instanceof WC_Order || 'shop_order' !== $saved_order->get_type() ) {\n\t\t\treturn;\n\t\t}\n\t\t$saved_order->read_meta_data( true );\n\t\tforeach ( $saved_order->get_meta_data() as $meta ) {\n\t\t\t$row = $meta->get_data();\n\t\t\t$event = $row['value'];\n\t\t\t$event_id = is_array( $event ) ? ( $event['id'] ?? '' ) : '';\n\t\t\tif ( ! $event_id || $row['key'] !== genosys_order_status_sms_event_key( $event_id ) || $from !== ( $event['from'] ?? '' ) || $to !== ( $event['to'] ?? '' ) || ! empty( $event['attempted_at'] ) ) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\tgenosys_order_status_sms_enqueue_event( $order_id, $event_id );\n\t\t}\n\t} catch ( Throwable $exception ) {\n\t\tgenosys_order_status_sms_log( $order_id, 'queue_unavailable' );\n\t}\n}\nadd_action( 'woocommerce_order_status_changed', 'genosys_order_status_sms_queue', 1, 4 );\n\n/** Each event is claimed once; changing an order again creates a separate event. */\nfunction genosys_order_status_sms_send( $order_id, $event_id ) {\n\t$order_id = absint( $order_id );\n\t$event_key = genosys_order_status_sms_event_key( $event_id );\n\tif ( ! $order_id || ! $event_key || ! function_exists( 'wc_get_order' ) ) {\n\t\treturn;\n\t}\n\t$lock = genosys_order_sms_lock( $order_id, $event_id );\n\tif ( ! $lock ) {\n\t\treturn;\n\t}\n\ttry {\n\t\t$order = wc_get_order( $order_id );\n\t\tif ( ! $order instanceof WC_Order || 'shop_order' !== $order->get_type() ) {\n\t\t\treturn;\n\t\t}\n\t\t$order->read_meta_data( true );\n\t\t$event = $order->get_meta( $event_key, true );\n\t\t$api_key = genosys_sms_api_key();\n\t\tif ( ! is_array( $event ) || $event_id !== ( $event['id'] ?? '' ) || ! empty( $event['attempted_at'] ) || ! genosys_order_status_sms_template_id() || '' === $api_key || empty( $event['template_id'] ) || empty( $event['phone'] ) || $event['phone'] !== genosys_sms_normalize_phone( $event['phone'] ) || ! isset( $event['parameters'] ) || ! is_array( $event['parameters'] ) || 2 !== count( $event['parameters'] ) || 'NAME' !== ( $event['parameters'][0]['name'] ?? '' ) || 'STATUS' !== ( $event['parameters'][1]['name'] ?? '' ) ) {\n\t\t\treturn;\n\t\t}\n\t\tif ( function_exists( 'genosys_account_notification_order_allowed' ) && ! genosys_account_notification_order_allowed( $order, 'order_status_sms', $event['phone'] ) ) {\n\t\t\t$event['attempted_at'] = time(); $event['status'] = 'suppressed';\n\t\t\t$order->update_meta_data( $event_key, $event ); $order->save_meta_data();\n\t\t\treturn;\n\t\t}\n\t\t$event['attempted_at'] = time();\n\t\t$event['status'] = 'attempting';\n\t\t$order->update_meta_data( $event_key, $event );\n\t\t$order->save_meta_data();\n\t\t$order->read_meta_data( true );\n\t\t$claim = $order->get_meta( $event_key, true );\n\t\tif ( ! is_array( $claim ) || $event['attempted_at'] !== ( $claim['attempted_at'] ?? 0 ) || 'attempting' !== ( $claim['status'] ?? '' ) ) {\n\t\t\tthrow new RuntimeException( 'claim_unavailable' );\n\t\t}\n\t\t$result = genosys_order_sms_request( $event['phone'], (int) $event['template_id'], $event['parameters'], $api_key );\n\t\t$event['status'] = $result['status'];\n\t\tif ( 'sent' === $result['status'] ) {\n\t\t\t$event['message_id'] = $result['message_id'];\n\t\t\t$event['sent_at'] = time();\n\t\t} else {\n\t\t\tgenosys_order_status_sms_log( $order_id, $result['reason'] );\n\t\t}\n\t\t$order->update_meta_data( $event_key, $event );\n\t\t$order->save_meta_data();\n\t} catch ( Throwable $exception ) {\n\t\tgenosys_order_status_sms_log( $order_id, 'send_unconfirmed' );\n\t} finally {\n\t\tgenosys_order_sms_unlock( $lock );\n\t}\n}\nadd_action( 'genosys_order_status_sms_send', 'genosys_order_status_sms_send', 10, 2 );\n","sha256":"f0d56367c222fa6e8d24b0dbf7650e58ab07b9f6302bd6308bb34beb68589b25"},"inc/package-builder.php":{"content":"<?php\n/** Package editing with WordPress media and a protected WooCommerce component catalog. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_package_builder_menu() {\n\tif ( function_exists( 'wc_get_product' ) ) {\n\t\tadd_submenu_page( 'woocommerce', 'افزودن پکیج', 'افزودن پکیج', 'manage_woocommerce', 'genosys-add-package', 'genosys_package_builder_page' );\n\t}\n}\nadd_action( 'admin_menu', 'genosys_package_builder_menu', 20 );\n\nfunction genosys_package_builder_decimals() {\n\treturn max( 0, min( 6, (int) wc_get_price_decimals() ) );\n}\n\nfunction genosys_package_builder_current() {\n\t$id = isset( $_GET['package_id'] ) && is_scalar( $_GET['package_id'] ) ? absint( $_GET['package_id'] ) : 0; // Read-only authenticated edit selection.\n\t$product = $id ? wc_get_product( $id ) : null;\n\treturn $product && genosys_is_package_product( $product ) && current_user_can( 'edit_post', $id ) ? $product : null;\n}\n\nfunction genosys_package_builder_assets( $hook ) {\n\tif ( 'woocommerce_page_genosys-add-package' !== $hook ) { return; }\n\twp_enqueue_media();\n\t$editing = genosys_package_builder_current();\n\twp_enqueue_style( 'genosys-package-builder', get_theme_file_uri( '/assets/css/package-builder.css' ), array(), '1.5.55' );\n\twp_enqueue_script( 'genosys-package-builder', get_theme_file_uri( '/assets/js/package-builder.js' ), array( 'media-views' ), '1.5.55', true );\n\twp_localize_script( 'genosys-package-builder', 'genosysPackageBuilder', array(\n\t\t'endpoint' => admin_url( 'admin-ajax.php' ), 'action' => 'genosys_package_products',\n\t\t'nonce' => wp_create_nonce( 'genosys_package_catalog' ),\n\t\t'saveAction' => 'genosys_package_save', 'saveNonce' => wp_create_nonce( 'genosys_package_save' ),\n\t\t'packageId' => $editing ? $editing->get_id() : 0, 'package' => $editing ? genosys_package_builder_data( $editing ) : null,\n\t\t'readOnly' => ! current_user_can( 'edit_products' ),\n\t\t'currencySymbol' => html_entity_decode( get_woocommerce_currency_symbol(), ENT_QUOTES, 'UTF-8' ),\n\t\t'priceDecimals' => genosys_package_builder_decimals(),\n\t\t'decimalSeparator' => wc_get_price_decimal_separator(), 'thousandSeparator' => wc_get_price_thousand_separator(),\n\t\t'slugBase' => home_url( '/' . trim( wc_get_permalink_structure()['product_rewrite_slug'], '/' ) . '/' ), 'maxItems' => 24,\n\t) );\n}\nadd_action( 'admin_enqueue_scripts', 'genosys_package_builder_assets' );\n\nfunction genosys_package_builder_icon( $name ) {\n\t$paths = array(\n\t\t'chevron' => '<path d=\"m6 9 6 6 6-6\"/>',\n\t\t'upload' => '<path d=\"M12 16V3m-5 5 5-5 5 5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5\"/>',\n\t\t'image' => '<rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"3\"/><circle cx=\"8\" cy=\"8\" r=\"2\"/><path d=\"m3 17 5-5 4 4 4-7 5 8\"/>',\n\t\t'heart' => '<path d=\"M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z\"/>',\n\t\t'check' => '<path d=\"m6 12 4 4 8-8\"/>',\n\t\t'bottle' => '<path d=\"M9 3h6m-5 0v5l-4 5v7a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1v-7l-4-5V3\"/>',\n\t\t'list' => '<path d=\"M10 6h11M10 12h11M10 18h11M4 6h.01M4 12h.01M4 18h.01\"/>',\n\t\t'ordered' => '<path d=\"M10 6h11M10 12h11M10 18h11M3 4h2v5M3 12h3v2l-3 3h3M3 20h3\"/>',\n\t);\n\treturn '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">' . ( $paths[ $name ] ?? $paths['image'] ) . '</svg>';\n}\n\n/** Published physical products and variations; no package, attachment, stock, or option writes. */\nfunction genosys_package_catalog_payload( $product ) {\n\tif ( ! $product || 'publish' !== $product->get_status() || ! $product->is_type( array( 'simple', 'variation' ) ) ) { return null; }\n\t$parent = $product->is_type( 'variation' ) ? wc_get_product( $product->get_parent_id() ) : null;\n\tif ( $product->is_type( 'variation' ) && ( ! $parent || ! $parent->is_type( 'variable' ) || 'publish' !== $parent->get_status() ) ) { return null; }\n\t$name = $product->get_name();\n\tif ( $parent ) { $name = $parent->get_name() . ' — ' . wc_get_formatted_variation( $product, true, true, false ); }\n\t$name = html_entity_decode( wp_strip_all_tags( $name ), ENT_QUOTES, 'UTF-8' );\n\t$pool_id = (int) $product->get_stock_managed_by_id();\n\t$pool = $pool_id === $product->get_id() ? $product : wc_get_product( $pool_id );\n\t$managed = $pool && $pool->managing_stock();\n\t$quantity = $managed ? $pool->get_stock_quantity() : null;\n\t$quantity = is_numeric( $quantity ) ? max( 0, (float) $quantity ) : null;\n\t$status = $product->get_stock_status();\n\t$state = 'outofstock' === $status ? 'outofstock' : ( null === $quantity ? 'unmanaged' : ( $quantity <= 5 ? 'low' : 'available' ) );\n\t$stock_label = null === $quantity ? ( $managed ? 'تعداد نامشخص' : 'بدون مدیریت تعداد' ) : genosys_persian_number( (string) $quantity ) . ' عدد';\n\tif ( 'outofstock' === $status ) { $stock_label = 'ناموجود'; }\n\telseif ( 'onbackorder' === $status || ( $product->backorders_allowed() && null !== $quantity && $quantity <= 0 ) ) {\n\t\t$state = 'backorder'; $stock_label = ( null === $quantity ? '' : genosys_persian_number( (string) $quantity ) . ' عدد · ' ) . 'پیش‌فروش';\n\t}\n\t$price = '' === $product->get_price() ? null : (float) genosys_package_display_price( $product->get_price( 'edit' ), $product );\n\t$image = $product->get_image_id() ? wp_get_attachment_image_url( $product->get_image_id(), 'thumbnail' ) : '';\n\treturn array(\n\t\t'id' => $product->get_id(), 'name' => $name, 'sku' => $product->get_sku(),\n\t\t'price' => $price, 'price_minor' => null === $price ? null : (int) round( $price * ( 10 ** genosys_package_builder_decimals() ) ),\n\t\t'image' => $image ?: '', 'stock_quantity' => $quantity, 'stock_pool_id' => $pool_id,\n\t\t'stock_status' => $status, 'stock_label' => $stock_label, 'stock_state' => $state, 'backorders' => $product->backorders_allowed(),\n\t);\n}\n\nfunction genosys_package_catalog_ajax() {\n\tif ( ! current_user_can( 'manage_woocommerce' ) || ! function_exists( 'wc_get_product' ) ) {\n\t\twp_send_json_error( array( 'message' => 'اجازه مشاهده این فهرست را ندارید.' ), 403 );\n\t}\n\tif ( ! check_ajax_referer( 'genosys_package_catalog', 'nonce', false ) ) {\n\t\twp_send_json_error( array( 'message' => 'صفحه را تازه کنید و دوباره تلاش کنید.' ), 403 );\n\t}\n\tglobal $wpdb;\n\t$raw = isset( $_GET['q'] ) && is_string( $_GET['q'] ) ? wp_unslash( $_GET['q'] ) : '';\n\t$query = trim( preg_replace( '/\\s+/u', ' ', strtr( sanitize_text_field( $raw ), genosys_product_search_character_map() ) ) );\n\t$query = function_exists( 'mb_substr' ) ? mb_substr( $query, 0, 160, 'UTF-8' ) : wp_html_excerpt( $query, 160, '' );\n\t$page = isset( $_GET['page'] ) && is_scalar( $_GET['page'] ) ? max( 1, min( 10000, absint( $_GET['page'] ) ) ) : 1;\n\t$lookup = $wpdb->prefix . 'wc_product_meta_lookup';\n\t$where = \"p.post_status = 'publish' AND ((p.post_type = 'product' AND NOT EXISTS (\n\t\tSELECT 1 FROM {$wpdb->term_relationships} rel INNER JOIN {$wpdb->term_taxonomy} tax ON tax.term_taxonomy_id = rel.term_taxonomy_id\n\t\tINNER JOIN {$wpdb->terms} term ON term.term_id = tax.term_id\n\t\tWHERE rel.object_id = p.ID AND tax.taxonomy = 'product_type' AND term.slug <> 'simple'\n\t)) OR (p.post_type = 'product_variation' AND parent.post_type = 'product' AND parent.post_status = 'publish'))\";\n\tif ( '' !== $query ) {\n\t\t$words = preg_split( '/\\s+/u', $query, -1, PREG_SPLIT_NO_EMPTY ); $titles = array();\n\t\tforeach ( $words as $word ) {\n\t\t\t$title = genosys_product_search_normalized_sql( 'p.post_title', $word );\n\t\t\t$parent_title = genosys_product_search_normalized_sql( 'parent.post_title', $word );\n\t\t\t$like = '%' . $wpdb->esc_like( $word ) . '%';\n\t\t\t$titles[] = $wpdb->prepare( \"({$title} LIKE %s OR {$parent_title} LIKE %s)\", $like, $like );\n\t\t}\n\t\t$sku = genosys_product_search_normalized_sql( 'catalog.sku', $query );\n\t\t$where .= ' AND ((' . implode( ' AND ', $titles ) . ') OR ' . $wpdb->prepare( \"{$sku} LIKE %s\", '%' . $wpdb->esc_like( $query ) . '%' ) . ')';\n\t}\n\t$sql = $wpdb->prepare( \"SELECT p.ID FROM {$wpdb->posts} p LEFT JOIN {$wpdb->posts} parent ON parent.ID = p.post_parent\n\t\tLEFT JOIN {$lookup} catalog ON catalog.product_id = p.ID WHERE {$where} ORDER BY p.post_title ASC, p.ID ASC LIMIT %d OFFSET %d\", 21, ( $page - 1 ) * 20 );\n\t$ids = $wpdb->get_col( $sql ); // phpcs:ignore WordPress.DB.PreparedSQL.NotPrepared -- Query clauses and pagination are prepared; identifiers are internal.\n\t$products = array();\n\tforeach ( array_slice( $ids, 0, 20 ) as $id ) {\n\t\t$product = genosys_package_catalog_payload( wc_get_product( $id ) );\n\t\tif ( $product ) { $products[] = $product; }\n\t}\n\twp_send_json_success( array( 'products' => $products, 'page' => $page, 'has_more' => count( $ids ) > 20 ) );\n}\nadd_action( 'wp_ajax_genosys_package_products', 'genosys_package_catalog_ajax' );\nadd_action( 'wp_ajax_nopriv_genosys_package_products', 'genosys_package_catalog_ajax' );\n\nfunction genosys_package_builder_row( $index ) {\n\t$id = 'gpk-product-' . sanitize_key( (string) $index );\n\t$number = is_numeric( $index ) ? genosys_persian_number( (string) ( (int) $index + 1 ) ) : '';\n\t?>\n\t<div class=\"gpk__item\" data-package-row>\n\t\t<span class=\"gpk__number\" data-row-number><?php echo esc_html( $number ); ?></span>\n\t\t<div class=\"gpk__picker\" data-picker>\n\t\t\t<button type=\"button\" class=\"gpk__picker-trigger\" data-picker-trigger role=\"combobox\" aria-haspopup=\"listbox\" aria-expanded=\"false\" aria-controls=\"<?php echo esc_attr( $id . '-options' ); ?>\" aria-label=\"انتخاب محصول <?php echo esc_attr( $number ); ?>\">\n\t\t\t\t<span class=\"gpk__picker-thumb\" data-picked-thumb hidden></span>\n\t\t\t\t<span class=\"gpk__picker-copy\"><span class=\"gpk__picker-name\" data-picked-name>یک محصول انتخاب کنید...</span><span class=\"gpk__picker-price\" data-picked-price hidden></span></span>\n\t\t\t\t<span class=\"gpk__chevron\"><?php echo genosys_package_builder_icon( 'chevron' ); ?></span>\n\t\t\t</button>\n\t\t\t<div class=\"gpk__picker-popover\" data-picker-popover hidden>\n\t\t\t\t<input type=\"search\" class=\"gpk__search\" data-product-search placeholder=\"جستجوی محصول...\" aria-label=\"جستجوی محصول با نام یا SKU\" autocomplete=\"off\">\n\t\t\t\t<div class=\"gpk__options\" id=\"<?php echo esc_attr( $id . '-options' ); ?>\" data-product-options role=\"listbox\" aria-label=\"محصولات فروشگاه\"></div>\n\t\t\t\t<p class=\"gpk__picker-status\" data-picker-status role=\"status\" aria-live=\"polite\"></p>\n\t\t\t\t<button type=\"button\" class=\"gpk__load-more\" data-load-more hidden>نمایش محصولات بیشتر</button>\n\t\t\t</div>\n\t\t</div>\n\t\t<div class=\"gpk__stock\" data-row-stock><span>موجودی</span><strong data-stock-value>—</strong></div>\n\t\t<div class=\"gpk__stepper\"><button type=\"button\" data-qty-step=\"1\" aria-label=\"افزایش تعداد\">+</button><input class=\"gpk__qty\" data-item-qty type=\"text\" inputmode=\"numeric\" value=\"1\" aria-label=\"تعداد محصول\" maxlength=\"4\"><button type=\"button\" data-qty-step=\"-1\" aria-label=\"کاهش تعداد\">−</button></div>\n\t\t<button type=\"button\" class=\"gpk__row-remove\" data-remove-product aria-label=\"حذف محصول از پکیج\" hidden>×</button>\n\t</div>\n\t<?php\n}\n\nfunction genosys_package_builder_page() {\n\tif ( ! current_user_can( 'manage_woocommerce' ) || ! function_exists( 'wc_get_product' ) ) { wp_die( 'اجازه دسترسی به این صفحه را ندارید.', '', array( 'response' => 403 ) ); }\n\t$editing = genosys_package_builder_current();\n\tif ( ! empty( $_GET['package_id'] ) && ! $editing ) { wp_die( 'پکیج برای ویرایش در دسترس نیست.', '', array( 'response' => 403 ) ); }\n\t$terms = get_terms( array( 'taxonomy' => 'product_cat', 'hide_empty' => false ) );\n\tif ( is_wp_error( $terms ) ) { $terms = array(); }\n\t$currency = html_entity_decode( get_woocommerce_currency_symbol(), ENT_QUOTES, 'UTF-8' );\n\t?>\n\t<div class=\"wrap gpk\" dir=\"rtl\" data-package-builder>\n\t\t<div class=\"gpk__header\"><div><p class=\"gpk__breadcrumb\"><a href=\"<?php echo esc_url( admin_url( 'edit.php?post_type=product&product_type=genosys_package' ) ); ?>\">پکیج‌ها</a> / <?php echo $editing ? 'ویرایش پکیج' : 'افزودن پکیج'; ?></p><h1><?php echo $editing ? 'ویرایش پکیج' : 'افزودن پکیج جدید'; ?></h1></div><span class=\"gpk__draft\" data-package-status-label>پیش‌نویس</span></div>\n\t\t<div class=\"gpk__layout\">\n\t\t\t<div class=\"gpk__main\">\n\t\t\t\t<section class=\"gpk__card\">\n\t\t\t\t\t<label class=\"gpk__label\" for=\"gpk-name\">نام پکیج <em>*</em></label><input id=\"gpk-name\" class=\"gpk__name\" data-package-name type=\"text\" maxlength=\"200\" placeholder=\"مثلاً: پکیج جوانسازی و درخشندگی پوست\" autocomplete=\"off\">\n\t\t\t\t\t<p class=\"gpk__permalink\">پیوند یکتا: <span dir=\"ltr\" data-package-slug><?php echo esc_html( home_url( '/package/…' ) ); ?></span></p>\n\t\t\t\t\t<label class=\"gpk__label\" id=\"gpk-description-label\">توضیحات پکیج</label><div class=\"gpk__editor\"><div class=\"gpk__toolbar\" role=\"toolbar\" aria-label=\"قالب‌بندی توضیحات\"><button type=\"button\" data-format=\"bold\" aria-label=\"پررنگ\"><b>B</b></button><button type=\"button\" data-format=\"italic\" aria-label=\"مورب\"><i>I</i></button><button type=\"button\" data-format=\"insertUnorderedList\" aria-label=\"فهرست نشانه‌دار\"><?php echo genosys_package_builder_icon( 'list' ); ?></button><button type=\"button\" data-format=\"insertOrderedList\" aria-label=\"فهرست شماره‌دار\"><?php echo genosys_package_builder_icon( 'ordered' ); ?></button></div><div class=\"gpk__editor-body\" data-package-editor contenteditable=\"true\" role=\"textbox\" aria-multiline=\"true\" aria-labelledby=\"gpk-description-label\" data-placeholder=\"توضیح کوتاهی درباره‌ی پکیج و کاربرد محصولات داخل آن بنویسید...\"></div></div>\n\t\t\t\t</section>\n\t\t\t\t<section class=\"gpk__card\">\n\t\t\t\t\t<h2 class=\"gpk__card-heading\">محتوای پکیج</h2><p>حداقل دو محصول متفاوت را از میان محصولات فعلی فروشگاه انتخاب کنید. موجودی هر محصول جلوی آن نمایش داده می‌شود.</p>\n\t\t\t\t\t<div class=\"gpk__items\" data-package-items><?php genosys_package_builder_row( 0 ); genosys_package_builder_row( 1 ); ?></div>\n\t\t\t\t\t<template data-package-row-template><?php genosys_package_builder_row( '__INDEX__' ); ?></template>\n\t\t\t\t\t<button class=\"gpk__add\" data-add-product type=\"button\">+ افزودن محصول دیگر</button>\n\t\t\t\t\t<div class=\"gpk__metrics\"><div class=\"gpk__metric\"><span>مجموع قیمت محصولات</span><strong data-total-price>—</strong></div><div class=\"gpk__metric\"><span>موجودی پکیج (محاسبه‌شده)</span><strong data-package-stock>—</strong></div><div class=\"gpk__metric\"><span>تعداد محصولات</span><strong data-product-count>—</strong></div></div>\n\t\t\t\t\t<p>موجودی پکیج خودکار از موجودی محصولات محاسبه می‌شود. با هر فروش، از موجودی تک‌تک محصولات کم می‌شود.</p>\n\t\t\t\t</section>\n\t\t\t\t<section class=\"gpk__card\">\n\t\t\t\t\t<h2 class=\"gpk__card-heading\">قیمت‌گذاری</h2><p>قیمت نهایی پکیج را تعیین کنید؛ مجموع قیمت محصولات به‌عنوان قیمت قبل از تخفیف نمایش داده می‌شود.</p>\n\t\t\t\t\t<div class=\"gpk__pricing-grid\"><div><label class=\"gpk__label\" for=\"gpk-price\">قیمت پکیج <em>*</em></label><div class=\"gpk__price-field\"><input id=\"gpk-price\" data-package-price type=\"text\" inputmode=\"decimal\" placeholder=\"0\" autocomplete=\"off\"><span><?php echo esc_html( $currency ); ?></span></div></div><div><label class=\"gpk__label\" for=\"gpk-sku\">شناسه‌ی پکیج (SKU)</label><input id=\"gpk-sku\" data-package-sku type=\"text\" dir=\"ltr\" placeholder=\"PKG-001\" maxlength=\"100\" autocomplete=\"off\"></div></div>\n\t\t\t\t\t<div class=\"gpk__discounts\"><button type=\"button\" data-discount=\"10\">پیشنهاد قیمت با ۱۰٪ تخفیف</button><button type=\"button\" data-discount=\"15\">۱۵٪ تخفیف</button><button type=\"button\" data-discount=\"20\">۲۰٪ تخفیف</button></div>\n\t\t\t\t</section>\n\t\t\t</div>\n\t\t\t<aside class=\"gpk__aside\" aria-label=\"تنظیمات و پیش‌نمایش پکیج\">\n\t\t\t\t<section class=\"gpk__card\"><h2 class=\"gpk__card-heading\">انتشار</h2><ul class=\"gpk__publish-checks\"><?php foreach ( array( 'name' => 'نام پکیج', 'products' => 'حداقل دو محصول متفاوت', 'image' => 'تصویر پکیج', 'price' => 'قیمت پکیج' ) as $key => $label ) : ?><li class=\"gpk__check\" data-check=\"<?php echo esc_attr( $key ); ?>\"><span class=\"gpk__check-marker\" aria-hidden=\"true\"><?php echo genosys_package_builder_icon( 'check' ); ?></span><span><?php echo esc_html( $label ); ?></span></li><?php endforeach; ?></ul>\n\t\t\t\t\t<div class=\"gpk__publish-fields\"><label class=\"gpk__label\" for=\"gpk-status\">وضعیت</label><select id=\"gpk-status\" data-package-status><option value=\"publish\">منتشر شده</option><option value=\"draft\">پیش‌نویس</option><option value=\"pending\">در انتظار بررسی</option></select><label class=\"gpk__label\" for=\"gpk-visibility\">نمایان بودن</label><select id=\"gpk-visibility\" data-package-visibility><option value=\"public\">عمومی</option><option value=\"private\">خصوصی</option><option value=\"hidden\">پنهان</option></select></div>\n\t\t\t\t\t<div class=\"gpk__publish-actions\"><button type=\"button\" class=\"gpk__button gpk__button--outline\" data-package-action=\"draft\">ذخیره پیش‌نویس</button><button type=\"button\" class=\"gpk__button gpk__button--primary\" data-package-action=\"publish\">انتشار پکیج</button></div>\n\t\t\t\t</section>\n\t\t\t\t<section class=\"gpk__card\"><h2 class=\"gpk__card-heading\">تصویر پکیج</h2><p>یک تصویر برای کل پکیج (نسبت پیشنهادی ۴:۵).</p><input type=\"hidden\" data-package-image value=\"0\"><div class=\"gpk__upload\" data-package-upload role=\"button\" tabindex=\"0\" aria-label=\"انتخاب تصویر از رسانه وردپرس\"><img class=\"gpk__upload-preview\" data-upload-preview alt=\"پیش‌نمایش تصویر پکیج\" hidden><div class=\"gpk__upload-copy\" data-upload-copy><span class=\"gpk__upload-icon\"><?php echo genosys_package_builder_icon( 'upload' ); ?></span><strong>انتخاب تصویر پکیج از رسانه</strong><p>برای انتخاب یا بارگذاری تصویر کلیک کنید</p><span class=\"gpk__formats\"><b dir=\"ltr\">JPG · PNG · WebP</b> — حداکثر ۵ مگابایت</span></div></div><p data-image-error role=\"alert\" hidden></p><div class=\"gpk__image-actions\"><button type=\"button\" class=\"gpk__button gpk__button--outline\" data-image-change hidden>تغییر تصویر</button><button type=\"button\" class=\"gpk__button gpk__button--outline\" data-image-remove hidden>حذف</button></div></section>\n\t\t\t\t<section class=\"gpk__card\"><h2 class=\"gpk__card-heading\">دسته‌بندی</h2><p>پکیج‌ها فقط در دسته‌بندی پکیج‌های ویژه نمایش داده می‌شوند.</p><div class=\"gpk__categories\"><?php $special = genosys_package_special_category(); ?><label><input type=\"checkbox\" data-package-category value=\"<?php echo esc_attr( $special ? $special->term_id : 0 ); ?>\" checked disabled><span>پکیج‌های ویژه</span></label></div></section>\n\t\t\t\t<section class=\"gpk__card\"><h2 class=\"gpk__card-heading\">پیش‌نمایش کارت</h2><p>این‌گونه در فروشگاه دیده می‌شود.</p><div class=\"gpk__preview\"><div class=\"gpk__preview-bg\"><img data-preview-image alt=\"تصویر پکیج\" hidden></div><span class=\"gpk__preview-icon\" data-preview-icon><?php echo genosys_package_builder_icon( 'image' ); ?></span><button type=\"button\" class=\"gpk__favorite\" data-preview-favorite aria-label=\"پسندیدن پیش‌نمایش\" aria-pressed=\"false\"><?php echo genosys_package_builder_icon( 'heart' ); ?></button><span data-preview-discount hidden></span><div class=\"gpk__preview-info\"><h3 class=\"gpk__preview-name\" data-preview-name>نام پکیج</h3><p class=\"gpk__preview-category\">پکیج <span data-preview-count>۰</span> محصول</p><div class=\"gpk__preview-price\"><del data-preview-original hidden></del><span data-preview-price>—</span></div></div></div></section>\n\t\t\t</aside>\n\t\t</div>\n\t\t<template data-product-icon><?php echo genosys_package_builder_icon( 'bottle' ); ?></template>\n\t\t<div class=\"gpk__toast\" data-package-message role=\"status\" aria-live=\"polite\" hidden></div>\n\t</div>\n\t<?php\n}\n","sha256":"f1fdf1e349f0580323836f637b2aeac1ca558fe9b97d09bcab637cdf8467d035"},"inc/package-list-data.php":{"content":"<?php\n/** Live package-list data and permission-protected, reversible administrative actions. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_package_list_state( $source = null, $unslash = true ) {\n\t$source = is_array( $source ) ? $source : $_GET;\n\t$read = static function ( $key ) use ( $source, $unslash ) { return isset( $source[ $key ] ) && is_string( $source[ $key ] ) ? ( $unslash ? wp_unslash( $source[ $key ] ) : $source[ $key ] ) : ''; };\n\t$status = sanitize_key( $read( 'gpl_status' ) ); $order = sanitize_key( $read( 'gpl_order' ) );\n\t$search = sanitize_text_field( $read( 'gpl_search' ) );\n\t$search = function_exists( 'mb_substr' ) ? mb_substr( $search, 0, 160, 'UTF-8' ) : wp_html_excerpt( $search, 160, '' );\n\t$page = $read( 'gpl_page' );\n\treturn array(\n\t\t'status' => in_array( $status, array( 'all', 'published', 'draft', 'pending', 'outofstock', 'trash' ), true ) ? $status : 'all',\n\t\t'search' => $search, 'order' => in_array( $order, array( 'latest', 'oldest', 'price_asc', 'price_desc', 'name' ), true ) ? $order : 'latest',\n\t\t'page' => preg_match( '/^[0-9]{1,9}$/D', $page ) ? max( 1, (int) $page ) : 1,\n\t);\n}\n\nfunction genosys_package_list_url( $changes = array() ) {\n\t$state = genosys_package_list_state();\n\t$args = array( 'page' => 'genosys-package-list', 'gpl_status' => $state['status'], 'gpl_search' => $state['search'], 'gpl_order' => $state['order'], 'gpl_page' => $state['page'] );\n\tforeach ( array( 'gpl_status', 'gpl_search', 'gpl_order', 'gpl_page', 'gpl_notice', 'gpl_message' ) as $key ) { if ( array_key_exists( $key, $changes ) ) { $args[ $key ] = $changes[ $key ]; } }\n\t$normalized = genosys_package_list_state( array_map( 'strval', array_intersect_key( $args, array_flip( array( 'gpl_status', 'gpl_search', 'gpl_order', 'gpl_page' ) ) ) ), false );\n\tforeach ( array( 'status', 'search', 'order', 'page' ) as $key ) { $args[ 'gpl_' . $key ] = $normalized[ $key ]; }\n\t// WordPress expects new argument values to be encoded before add_query_arg().\n\t$args = array_map( static function ( $value ) { return rawurlencode( (string) $value ); }, $args );\n\treturn add_query_arg( $args, admin_url( 'admin.php' ) );\n}\n\nfunction genosys_package_list_normalize( $text ) {\n\t$map = function_exists( 'genosys_product_search_character_map' ) ? genosys_product_search_character_map() : array( 'ي' => 'ی', 'ى' => 'ی', 'ك' => 'ک', '‌' => ' ', '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4', '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9' );\n\t$text = strtr( html_entity_decode( wp_strip_all_tags( (string) $text ), ENT_QUOTES, 'UTF-8' ), $map );\n\t$text = preg_replace( '/[\\x{064B}-\\x{065F}\\x{0670}ـ]/u', '', $text );\n\t$text = trim( (string) preg_replace( '/\\s+/u', ' ', $text ) );\n\treturn function_exists( 'mb_strtolower' ) ? mb_strtolower( $text, 'UTF-8' ) : strtolower( $text );\n}\n\nfunction genosys_package_list_can_read( $id ) {\n\t$post = get_post( $id );\n\tif ( ! $post || ! in_array( $post->post_type, array( 'product', 'product_variation' ), true ) ) { return false; }\n\t$status = 'trash' === $post->post_status ? get_post_meta( $id, '_wp_trash_meta_status', true ) : $post->post_status;\n\tif ( 'private' === $status && (int) $post->post_author !== get_current_user_id() && ! current_user_can( 'read_private_products' ) && ! current_user_can( 'edit_private_products' ) ) { return false; }\n\treturn current_user_can( 'read_post', $id ) || current_user_can( 'edit_post', $id );\n}\n\nfunction genosys_package_list_search_text( $product ) {\n\t$text = array( $product->get_name(), $product->get_sku(), (string) $product->get_id(), '#' . $product->get_id() );\n\tforeach ( genosys_package_components( $product ) as $row ) {\n\t\t$component = wc_get_product( $row['product_id'] );\n\t\tif ( ! $component || ! genosys_package_list_can_read( $component->get_id() ) ) { continue; }\n\t\t$parent = $component->is_type( 'variation' ) ? wc_get_product( $component->get_parent_id() ) : null;\n\t\tif ( $parent && ! genosys_package_list_can_read( $parent->get_id() ) ) { continue; }\n\t\t$text[] = $component->get_name(); $text[] = $component->get_sku();\n\t\tif ( $component->is_type( 'variation' ) ) {\n\t\t\t$text[] = wc_get_formatted_variation( $component, true, true, false );\n\t\t\tif ( $parent && genosys_package_list_can_read( $parent->get_id() ) ) { $text[] = $parent->get_name(); $text[] = $parent->get_sku(); }\n\t\t}\n\t}\n\treturn genosys_package_list_normalize( implode( ' ', $text ) );\n}\n\n/** Counts are permission-scoped live totals; status/search affect the six-item result page. */\nfunction genosys_package_list_context() {\n\t$state = genosys_package_list_state(); $counts = array_fill_keys( array( 'all', 'published', 'draft', 'pending', 'outofstock', 'trash' ), 0 );\n\t$result = array_merge( $state, array( 'per_page' => 6, 'products' => array(), 'filtered_total' => 0, 'total' => 0, 'pages' => 1, 'counts' => $counts, 'stats' => array( 'all' => 0, 'published' => 0, 'low' => 0, 'outofstock' => 0 ) ) );\n\tif ( ! function_exists( 'wc_get_product' ) || ! current_user_can( 'manage_woocommerce' ) ) { return $result; }\n\tglobal $wpdb;\n\t// An administrative inventory read must not inherit the storefront's package-category visibility filters.\n\t$ids = $wpdb->get_col( $wpdb->prepare( \"SELECT DISTINCT p.ID FROM {$wpdb->posts} p INNER JOIN {$wpdb->term_relationships} rel ON rel.object_id = p.ID INNER JOIN {$wpdb->term_taxonomy} tax ON tax.term_taxonomy_id = rel.term_taxonomy_id INNER JOIN {$wpdb->terms} term ON term.term_id = tax.term_id WHERE p.post_type = %s AND p.post_status IN ('publish','private','draft','auto-draft','pending','trash') AND tax.taxonomy = %s AND term.slug = %s ORDER BY p.ID DESC\", 'product', 'product_type', 'genosys_package' ) );\n\t$terms = preg_split( '/\\s+/u', genosys_package_list_normalize( $state['search'] ), -1, PREG_SPLIT_NO_EMPTY );\n\t$threshold = max( 0, (float) get_option( 'woocommerce_notify_low_stock_amount', 2 ) ); $matches = array();\n\tforeach ( $ids as $id ) {\n\t\tif ( ! genosys_package_list_can_read( $id ) ) { continue; }\n\t\t$product = wc_get_product( $id );\n\t\tif ( ! genosys_is_package_product( $product ) ) { continue; }\n\t\t$status = $product->get_status(); $published = in_array( $status, array( 'publish', 'private' ), true );\n\t\t$stock = $published ? genosys_package_stock( $product ) : null;\n\t\t$groups = array();\n\t\tif ( 'trash' === $status ) { $groups[] = 'trash'; }\n\t\telse { $groups[] = 'all'; if ( $published ) { $groups[] = 'published'; if ( 0 === $stock ) { $groups[] = 'outofstock'; } elseif ( null !== $stock && $stock <= $threshold ) { ++$result['stats']['low']; } } elseif ( in_array( $status, array( 'draft', 'auto-draft' ), true ) ) { $groups[] = 'draft'; } elseif ( 'pending' === $status ) { $groups[] = 'pending'; } }\n\t\tforeach ( $groups as $group ) { ++$result['counts'][ $group ]; }\n\t\tif ( ! in_array( $state['status'], $groups, true ) ) { continue; }\n\t\tif ( $terms ) {\n\t\t\t$haystack = genosys_package_list_search_text( $product ); $found = true;\n\t\t\tforeach ( $terms as $term ) { if ( false === strpos( $haystack, $term ) ) { $found = false; break; } }\n\t\t\tif ( ! $found ) { continue; }\n\t\t}\n\t\t$matches[] = $product;\n\t}\n\tusort( $matches, static function ( $a, $b ) use ( $state ) {\n\t\tif ( in_array( $state['order'], array( 'price_asc', 'price_desc' ), true ) ) {\n\t\t\t$ap = $a->get_price( 'edit' ); $bp = $b->get_price( 'edit' );\n\t\t\tif ( '' === $ap || '' === $bp ) { $compare = ( '' === $ap ? 1 : 0 ) <=> ( '' === $bp ? 1 : 0 ); }\n\t\t\telse { $compare = (float) genosys_package_display_price( $ap, $a ) <=> (float) genosys_package_display_price( $bp, $b ); if ( 'price_desc' === $state['order'] ) { $compare *= -1; } }\n\t\t} elseif ( 'name' === $state['order'] ) { $compare = strcmp( genosys_package_list_normalize( $a->get_name() ), genosys_package_list_normalize( $b->get_name() ) ); }\n\t\telse { $ad = $a->get_date_created(); $bd = $b->get_date_created(); $compare = ( $ad ? $ad->getTimestamp() : 0 ) <=> ( $bd ? $bd->getTimestamp() : 0 ); if ( 'latest' === $state['order'] ) { $compare *= -1; } }\n\t\treturn $compare ?: ( $a->get_id() <=> $b->get_id() ) * ( 'latest' === $state['order'] ? -1 : 1 );\n\t} );\n\t$result['total'] = $result['counts']['all']; $result['filtered_total'] = count( $matches );\n\t$result['pages'] = max( 1, (int) ceil( $result['filtered_total'] / $result['per_page'] ) ); $result['page'] = min( $state['page'], $result['pages'] );\n\t$result['products'] = array_slice( $matches, ( $result['page'] - 1 ) * $result['per_page'], $result['per_page'] );\n\t$result['stats']['all'] = $result['total']; $result['stats']['published'] = $result['counts']['published']; $result['stats']['outofstock'] = $result['counts']['outofstock'];\n\treturn $result;\n}\n\nfunction genosys_package_list_canonical_id( $value ) {\n\tif ( ! is_string( $value ) && ! is_int( $value ) ) { return 0; }\n\t$value = (string) $value;\n\treturn preg_match( '/^[1-9][0-9]*$/D', $value ) && (string) (int) $value === $value ? (int) $value : 0;\n}\n\n/** Native duplication, with request/SKU metadata cleared before the new draft's first save. */\nfunction genosys_package_list_duplicate( $product ) {\n\tif ( ! class_exists( 'WC_Admin_Duplicate_Product' ) ) { require_once WC_ABSPATH . 'includes/admin/class-wc-admin-duplicate-product.php'; }\n\t$prepare = static function ( $duplicate, $original ) use ( $product ) {\n\t\tif ( $original->get_id() !== $product->get_id() || ! genosys_is_package_product( $duplicate ) ) { return; }\n\t\t$duplicate->set_sku( '' ); $duplicate->set_status( 'draft' );\n\t\tforeach ( array( '_genosys_package_request_token', '_genosys_package_request_user', '_wp_trash_meta_status', '_wp_trash_meta_time' ) as $key ) { $duplicate->delete_meta_data( $key ); }\n\t\t$term = genosys_package_special_category( true );\n\t\tif ( ! $term || is_wp_error( $term ) ) { throw new Exception( 'دسته‌بندی پکیج‌های ویژه در دسترس نیست.' ); }\n\t\t$duplicate->set_category_ids( array( (int) $term->term_id ) );\n\t};\n\tadd_action( 'woocommerce_product_duplicate_before_save', $prepare, 100, 2 );\n\ttry { $duplicate = ( new WC_Admin_Duplicate_Product() )->product_duplicate( $product ); }\n\tfinally { remove_action( 'woocommerce_product_duplicate_before_save', $prepare, 100 ); }\n\tif ( ! $duplicate || ! $duplicate->get_id() || ! genosys_is_package_product( $duplicate ) ) { throw new Exception( 'ساخت نسخه پیش‌نویس انجام نشد.' ); }\n\tgenosys_package_sync_stock( $duplicate->get_id() ); do_action( 'woocommerce_product_duplicate', $duplicate, $product );\n\treturn $duplicate;\n}\n\n/** EMPTY_TRASH_DAYS=0 must never turn our reversible action into a permanent deletion. */\nfunction genosys_package_list_trash( $id ) {\n\tif ( 'trash' === get_post_status( $id ) ) { return true; }\n\tif ( ! defined( 'EMPTY_TRASH_DAYS' ) || EMPTY_TRASH_DAYS > 0 ) { $result = wp_trash_post( $id ); return $result && 'trash' === get_post_status( $id ); }\n\t$post = get_post( $id ); if ( ! $post ) { return false; } $previous = $post->post_status;\n\t$pre = apply_filters( 'pre_trash_post', null, $post, $previous ); if ( null !== $pre ) { return $pre && 'trash' === get_post_status( $id ); }\n\tdo_action( 'wp_trash_post', $id, $previous ); update_post_meta( $id, '_wp_trash_meta_status', $previous );\n\t// No expiry metadata: zero-day cron retention must not immediately purge this reversible package.\n\tdelete_post_meta( $id, '_wp_trash_meta_time' );\n\t$result = wp_update_post( array( 'ID' => $id, 'post_status' => 'trash' ), true );\n\tif ( is_wp_error( $result ) || ! $result ) { delete_post_meta( $id, '_wp_trash_meta_status' ); return false; }\n\tdo_action( 'trashed_post', $id, $previous ); return true;\n}\n\nfunction genosys_package_list_restore( $id ) {\n\tif ( 'trash' !== get_post_status( $id ) ) { return false; }\n\t$previous = get_post_meta( $id, '_wp_trash_meta_status', true );\n\tif ( ! in_array( $previous, array( 'publish', 'private', 'draft', 'auto-draft', 'pending' ), true ) ) { $previous = 'draft'; }\n\tif ( in_array( $previous, array( 'publish', 'private' ), true ) && ! current_user_can( 'publish_products' ) ) { throw new Exception( 'اجازه بازگردانی پکیج منتشرشده را ندارید.' ); }\n\t$restore_status = static function ( $status, $post_id ) use ( $id, $previous ) { return (int) $post_id === $id ? $previous : $status; };\n\tadd_filter( 'wp_untrash_post_status', $restore_status, 100, 2 );\n\ttry { $result = wp_untrash_post( $id ); return $result && $previous === get_post_status( $id ); }\n\tfinally { remove_filter( 'wp_untrash_post_status', $restore_status, 100 ); }\n}\n\nfunction genosys_package_list_action() {\n\t$state = genosys_package_list_state( $_POST ); $notice = 'error'; $message = ''; $transaction = false; $affected = array();\n\ttry {\n\t\tif ( 'POST' !== ( $_SERVER['REQUEST_METHOD'] ?? '' ) || ! function_exists( 'wc_get_product' ) || ! current_user_can( 'manage_woocommerce' ) || ! current_user_can( 'edit_products' ) ) { throw new Exception( 'اجازه انجام این عملیات را ندارید.' ); }\n\t\t$operation = isset( $_POST['operation'] ) && is_string( $_POST['operation'] ) ? wp_unslash( $_POST['operation'] ) : '';\n\t\tif ( ! in_array( $operation, array( 'duplicate', 'trash', 'restore', 'bulk_trash' ), true ) ) { throw new Exception( 'عملیات انتخاب‌شده معتبر نیست.' ); }\n\t\t$id = 'bulk_trash' === $operation ? 0 : genosys_package_list_canonical_id( $_POST['package_id'] ?? null );\n\t\tif ( 'bulk_trash' !== $operation && ! $id ) { throw new Exception( 'شناسه پکیج معتبر نیست.' ); }\n\t\t$nonce = isset( $_POST['_wpnonce'] ) && is_string( $_POST['_wpnonce'] ) ? wp_unslash( $_POST['_wpnonce'] ) : '';\n\t\tif ( ! wp_verify_nonce( $nonce, 'genosys_package_list_action_' . $operation . '_' . $id ) ) { throw new Exception( 'درخواست منقضی یا نامعتبر است؛ صفحه را تازه کنید.' ); }\n\t\t$ids = array( $id );\n\t\tif ( 'bulk_trash' === $operation ) {\n\t\t\tif ( ! isset( $_POST['ids'] ) || ! is_array( $_POST['ids'] ) || ! $_POST['ids'] || count( $_POST['ids'] ) > 200 ) { throw new Exception( 'پکیج‌های انتخاب‌شده معتبر نیستند.' ); }\n\t\t\t$ids = array(); foreach ( $_POST['ids'] as $value ) { $parsed = genosys_package_list_canonical_id( $value ); if ( ! $parsed ) { throw new Exception( 'یکی از شناسه‌ها معتبر نیست.' ); } $ids[] = $parsed; } $ids = array_values( array_unique( $ids ) );\n\t\t}\n\t\t$products = array();\n\t\tforeach ( $ids as $package_id ) {\n\t\t\t$product = wc_get_product( $package_id );\n\t\t\tif ( ! genosys_is_package_product( $product ) || ! genosys_package_list_can_read( $package_id ) || ! current_user_can( 'edit_post', $package_id ) || ( 'duplicate' !== $operation && ! current_user_can( 'delete_post', $package_id ) ) ) { throw new Exception( 'اجازه تغییر یکی از پکیج‌ها را ندارید.' ); }\n\t\t\t$products[] = $product;\n\t\t}\n\t\tglobal $wpdb;\n\t\tif ( false === $wpdb->query( 'START TRANSACTION' ) ) { throw new Exception( 'عملیات آغاز نشد.' ); } $transaction = true;\n\t\tforeach ( $products as $product ) {\n\t\t\t$affected[] = $product->get_id();\n\t\t\tif ( 'duplicate' === $operation ) { $copy = genosys_package_list_duplicate( $product ); $affected[] = $copy->get_id(); }\n\t\t\telseif ( 'restore' === $operation ) { if ( ! genosys_package_list_restore( $product->get_id() ) ) { throw new Exception( 'بازگردانی پکیج انجام نشد.' ); } genosys_package_sync_stock( $product->get_id() ); }\n\t\t\telseif ( ! genosys_package_list_trash( $product->get_id() ) ) { throw new Exception( 'انتقال پکیج به زباله‌دان انجام نشد.' ); }\n\t\t}\n\t\tif ( false === $wpdb->query( 'COMMIT' ) ) { throw new Exception( 'ثبت عملیات انجام نشد.' ); } $transaction = false;\n\t\t$notice = array( 'duplicate' => 'duplicated', 'trash' => 'trashed', 'restore' => 'restored', 'bulk_trash' => 'bulk_trashed' )[ $operation ];\n\t} catch ( Throwable $error ) {\n\t\tif ( $transaction ) { $wpdb->query( 'ROLLBACK' ); }\n\t\tforeach ( $affected as $package_id ) { clean_post_cache( $package_id ); if ( function_exists( 'wc_delete_product_transients' ) ) { wc_delete_product_transients( $package_id ); } }\n\t\t$message = sanitize_text_field( $error->getMessage() ); $message = function_exists( 'mb_substr' ) ? mb_substr( $message, 0, 200, 'UTF-8' ) : wp_html_excerpt( $message, 200, '' );\n\t}\n\t$args = array( 'gpl_status' => $state['status'], 'gpl_search' => $state['search'], 'gpl_order' => $state['order'], 'gpl_page' => $state['page'], 'gpl_notice' => $notice );\n\tif ( $message ) { $args['gpl_message'] = $message; }\n\twp_safe_redirect( genosys_package_list_url( $args ), 303 ); exit;\n}\nadd_action( 'admin_post_genosys_package_list_action', 'genosys_package_list_action' );\nadd_action( 'admin_post_nopriv_genosys_package_list_action', 'genosys_package_list_action' );\n","sha256":"431dd7937f3d529f5158d90d07fa35b0c7d463cbae36b5484c7296a64d8ed8a1"},"inc/package-list.php":{"content":"<?php\n/** A real WooCommerce package list, using the existing shared component inventory. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_package_list_menu() {\n\tif ( ! function_exists( 'wc_get_product' ) ) { return; }\n\tglobal $submenu;\n\t$position = null;\n\tforeach ( (array) ( $submenu['woocommerce'] ?? array() ) as $index => $item ) {\n\t\tif ( 'genosys-add-package' === ( $item[2] ?? '' ) ) { $position = $index + 1; break; }\n\t}\n\tadd_submenu_page( 'woocommerce', 'لیست پکیج ها', 'لیست پکیج ها', 'manage_woocommerce', 'genosys-package-list', 'genosys_package_list_page', $position );\n}\nadd_action( 'admin_menu', 'genosys_package_list_menu', 21 );\n\nfunction genosys_package_list_assets( $hook ) {\n\tif ( 'woocommerce_page_genosys-package-list' !== $hook ) { return; }\n\twp_enqueue_style( 'genosys-package-list', get_theme_file_uri( '/assets/css/package-list.css' ), array(), '1.5.57' );\n\twp_enqueue_script( 'genosys-package-list', get_theme_file_uri( '/assets/js/package-list.js' ), array(), '1.5.57', true );\n}\nadd_action( 'admin_enqueue_scripts', 'genosys_package_list_assets' );\n\nfunction genosys_package_list_icon( $name ) {\n\t$paths = array(\n\t\t'package' => '<path d=\"m12 3 9 5v8l-9 5-9-5V8l9-5Zm-9 5 9 5 9-5M12 13v8M7.5 5.5l9 5\"/>',\n\t\t'check' => '<path d=\"m5 12 4 4L19 6\"/>',\n\t\t'alert' => '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v6m0 4h.01\"/>',\n\t\t'close' => '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"m9 9 6 6m0-6-6 6\"/>',\n\t\t'search' => '<circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 5 5\"/>',\n\t\t'chevron' => '<path d=\"m6 9 6 6 6-6\"/>',\n\t\t'edit' => '<path d=\"m15 4 5 5M4 20l4-1L20 7a2.1 2.1 0 0 0-3-3L5 16l-1 4Z\"/>',\n\t\t'eye' => '<path d=\"M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>',\n\t\t'copy' => '<rect x=\"8\" y=\"8\" width=\"12\" height=\"13\" rx=\"2\"/><path d=\"M15 4H5a2 2 0 0 0-2 2v11\"/>',\n\t\t'trash' => '<path d=\"M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7\"/>',\n\t\t'restore' => '<path d=\"M3 11a9 9 0 1 1 2 7M3 4v7h7M12 8v5l3 2\"/>',\n\t\t'plus' => '<path d=\"M12 5v14M5 12h14\"/>',\n\t\t'image' => '<rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"3\"/><circle cx=\"8\" cy=\"8\" r=\"2\"/><path d=\"m3 17 5-5 4 4 4-7 5 8\"/>',\n\t);\n\treturn '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">' . ( $paths[ $name ] ?? $paths['package'] ) . '</svg>';\n}\n\nfunction genosys_package_list_price( $value ) {\n\tif ( '' === $value || null === $value ) { return '—'; }\n\treturn wp_kses_post( genosys_checkout_localize_html( wc_price( $value ) ) );\n}\n\nfunction genosys_package_list_date( $date ) {\n\tif ( ! $date ) { return '—'; }\n\ttry {\n\t\t$parts = explode( '/', explode( ' ', genosys_shop_ascii_digits( genosys_sms_shamsi_date( $date->getTimestamp() ) ) )[0] );\n\t\t$months = array( '', 'فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند' );\n\t\treturn genosys_persian_number( (int) $parts[2] . ' ' . $months[ (int) $parts[1] ] . ' ' . $parts[0] );\n\t} catch ( Throwable $error ) {\n\t\treturn genosys_persian_number( wp_date( 'j F Y', $date->getTimestamp(), wp_timezone() ) );\n\t}\n}\n\n/** Keep referenced products visible as unavailable if they were removed or unpublished. */\nfunction genosys_package_list_components_data( $package ) {\n\t$rows = array();\n\tforeach ( genosys_package_components( $package ) as $item ) {\n\t\t$product = wc_get_product( $item['product_id'] );\n\t\tif ( $product && ( ! genosys_package_list_can_read( $product->get_id() ) || ( $product->is_type( 'variation' ) && ! genosys_package_list_can_read( $product->get_parent_id() ) ) ) ) { $product = null; }\n\t\t$data = $product ? genosys_package_catalog_payload( $product ) : null;\n\t\tif ( ! $data ) {\n\t\t\t$data = array( 'id' => $item['product_id'], 'name' => $product ? $product->get_name() : 'محصول #' . genosys_persian_number( $item['product_id'] ),\n\t\t\t\t'price' => $product && '' !== $product->get_price( 'edit' ) ? genosys_package_display_price( $product->get_price( 'edit' ), $product ) : null,\n\t\t\t\t'image' => $product && $product->get_image_id() ? wp_get_attachment_image_url( $product->get_image_id(), 'thumbnail' ) : '',\n\t\t\t\t'stock_quantity' => 0, 'stock_state' => 'outofstock', 'stock_label' => 'در دسترس نیست' );\n\t\t}\n\t\t$data['quantity'] = $item['quantity'];\n\t\t$rows[] = $data;\n\t}\n\treturn $rows;\n}\n\nfunction genosys_package_list_return_fields( $context ) {\n\tforeach ( array( 'gpl_status' => 'status', 'gpl_search' => 'search', 'gpl_order' => 'order', 'gpl_page' => 'page' ) as $field => $key ) {\n\t\techo '<input type=\"hidden\" name=\"' . esc_attr( $field ) . '\" value=\"' . esc_attr( $context[ $key ] ) . '\">';\n\t}\n}\n\nfunction genosys_package_list_action_form( $operation, $product, $context, $label, $icon, $confirm = '' ) {\n\t$id = $product->get_id();\n\t?>\n\t<form class=\"gpl__action-form\" method=\"post\" action=\"<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>\"<?php if ( $confirm ) : ?> data-package-confirm=\"<?php echo esc_attr( $confirm ); ?>\"<?php endif; ?>>\n\t\t<input type=\"hidden\" name=\"action\" value=\"genosys_package_list_action\"><input type=\"hidden\" name=\"operation\" value=\"<?php echo esc_attr( $operation ); ?>\"><input type=\"hidden\" name=\"package_id\" value=\"<?php echo esc_attr( $id ); ?>\">\n\t\t<?php wp_nonce_field( 'genosys_package_list_action_' . $operation . '_' . $id, '_wpnonce', false ); genosys_package_list_return_fields( $context ); ?>\n\t\t<button class=\"gpl__action\" type=\"submit\" title=\"<?php echo esc_attr( $label ); ?>\" aria-label=\"<?php echo esc_attr( $label . ': ' . $product->get_name() ); ?>\" data-package-operation=\"<?php echo esc_attr( $operation ); ?>\"><?php echo genosys_package_list_icon( $icon ); ?></button>\n\t</form>\n\t<?php\n}\n\nfunction genosys_package_list_details( $product, $components, $stock ) {\n\t$total = 0; $has_price = true;\n\t?>\n\t<div class=\"gpl__details\">\n\t\t<h2>محصولات داخل پکیج</h2>\n\t\t<?php if ( $components ) : ?>\n\t\t\t<div class=\"gpl__components\">\n\t\t\t\t<?php foreach ( $components as $component ) : ?>\n\t\t\t\t\t<?php if ( null === $component['price'] ) { $has_price = false; } else { $total += (float) $component['price'] * $component['quantity']; } ?>\n\t\t\t\t\t<div class=\"gpl__component\">\n\t\t\t\t\t\t<span class=\"gpl__component-image\"><?php if ( $component['image'] ) : ?><img src=\"<?php echo esc_url( $component['image'] ); ?>\" alt=\"\" loading=\"lazy\"><?php else : ?><?php echo genosys_package_builder_icon( 'bottle' ); ?><?php endif; ?></span>\n\t\t\t\t\t\t<div class=\"gpl__component-copy\"><strong class=\"gpl__component-name\" title=\"<?php echo esc_attr( $component['name'] ); ?>\"><?php echo esc_html( $component['name'] ); ?></strong><span class=\"gpl__component-price\"><?php echo genosys_package_list_price( $component['price'] ); ?></span></div>\n\t\t\t\t\t\t<div class=\"gpl__component-quantity\"><strong>×<?php echo esc_html( genosys_persian_number( $component['quantity'] ) ); ?></strong><span>تعداد</span></div>\n\t\t\t\t\t\t<div class=\"gpl__component-stock\" data-state=\"<?php echo esc_attr( $component['stock_state'] ); ?>\"><strong><?php echo esc_html( null === $component['stock_quantity'] ? ( 'outofstock' === $component['stock_state'] ? 'ناموجود' : '—' ) : genosys_persian_number( $component['stock_quantity'] ) ); ?></strong><span><?php echo esc_html( 'outofstock' === $component['stock_state'] ? $component['stock_label'] : ( null === $component['stock_quantity'] ? 'بدون مدیریت تعداد' : 'موجودی' ) ); ?></span></div>\n\t\t\t\t\t</div>\n\t\t\t\t<?php endforeach; ?>\n\t\t\t</div>\n\t\t<?php else : ?><p class=\"gpl__empty-components\">محصولی برای این پکیج انتخاب نشده است.</p><?php endif; ?>\n\t\t<div class=\"gpl__details-summary\"><span>مجموع قیمت محصولات: <strong><?php echo genosys_package_list_price( $has_price && $components ? $total : null ); ?></strong></span><span>موجودی پکیج: <strong><?php echo esc_html( null === $stock ? 'بدون مدیریت تعداد' : genosys_persian_number( $stock ) . ' عدد' ); ?></strong> (بر اساس کمترین موجودی)</span></div>\n\t</div>\n\t<?php\n}\n\nfunction genosys_package_list_row( $product, $context ) {\n\t$id = $product->get_id(); $components = genosys_package_list_components_data( $product );\n\t$stock = genosys_package_stock( $product ); $threshold = max( 0, (float) get_option( 'woocommerce_notify_low_stock_amount', 2 ) );\n\t$state = 0 === $stock ? 'outofstock' : ( null === $stock ? 'unmanaged' : ( $stock <= $threshold ? 'low' : 'available' ) );\n\t$status = $product->get_status(); $trashed = 'trash' === $status;\n\t$can_edit = ! $trashed && current_user_can( 'edit_products' ) && current_user_can( 'edit_post', $id );\n\t$can_delete = current_user_can( 'delete_post', $id );\n\t$price = '' === $product->get_price( 'edit' ) ? null : genosys_package_display_price( $product->get_price( 'edit' ), $product );\n\t$regular = '' === $product->get_regular_price( 'edit' ) ? null : genosys_package_display_price( $product->get_regular_price( 'edit' ), $product );\n\t$discount = $price !== null && $regular > 0 && $price < $regular ? (int) round( 100 * ( 1 - $price / $regular ) ) : 0;\n\t$date = $product->get_date_created(); $image = $product->get_image_id() ? wp_get_attachment_image_url( $product->get_image_id(), 'thumbnail' ) : '';\n\t$labels = array( 'publish' => 'منتشر شده', 'private' => 'خصوصی', 'draft' => 'پیش‌نویس', 'auto-draft' => 'پیش‌نویس', 'pending' => 'در انتظار بررسی', 'trash' => 'زباله‌دان' );\n\t?>\n\t<tr class=\"gpl__row\" data-package-row data-package-id=\"<?php echo esc_attr( $id ); ?>\">\n\t\t<td class=\"gpl__select-col\"><input type=\"checkbox\" class=\"gpl__checkbox\" data-package-select value=\"<?php echo esc_attr( $id ); ?>\" aria-label=\"<?php echo esc_attr( 'انتخاب ' . $product->get_name() ); ?>\"<?php disabled( $trashed || ! $can_delete ); ?>></td>\n\t\t<td class=\"gpl__package-col\"><div class=\"gpl__package\"><span class=\"gpl__image\"><?php if ( $image ) : ?><img src=\"<?php echo esc_url( $image ); ?>\" alt=\"\" loading=\"lazy\"><?php else : ?><?php echo genosys_package_list_icon( 'image' ); ?><?php endif; ?></span><div class=\"gpl__package-copy\"><strong class=\"gpl__name\"><?php if ( $can_edit ) : ?><a href=\"<?php echo esc_url( admin_url( 'admin.php?page=genosys-add-package&package_id=' . $id ) ); ?>\"><?php endif; ?><?php echo esc_html( $product->get_name() ); ?><?php if ( $can_edit ) : ?></a><?php endif; ?></strong><p class=\"gpl__meta\">شناسه: <bdi><?php echo esc_html( $product->get_sku() ?: '#' . genosys_persian_number( $id ) ); ?></bdi> · <?php if ( $date ) : ?><time datetime=\"<?php echo esc_attr( gmdate( DATE_ATOM, $date->getTimestamp() ) ); ?>\"><?php endif; ?><?php echo esc_html( genosys_package_list_date( $date ) ); ?><?php if ( $date ) : ?></time><?php endif; ?></p><?php if ( 'publish' !== $status ) : ?><span class=\"gpl__status\" data-status=\"<?php echo esc_attr( $status ); ?>\"><?php echo esc_html( $labels[ $status ] ?? $status ); ?></span><?php endif; ?></div></div></td>\n\t\t<td class=\"gpl__contents-col\"><div class=\"gpl__chips\"><?php foreach ( array_slice( $components, 0, 2 ) as $component ) : ?><span class=\"gpl__chip\"><b>×<?php echo esc_html( genosys_persian_number( $component['quantity'] ) ); ?></b><span class=\"gpl__chip-name\" title=\"<?php echo esc_attr( $component['name'] ); ?>\"><?php echo esc_html( $component['name'] ); ?></span></span><?php endforeach; ?><?php if ( count( $components ) > 2 ) : ?><span class=\"gpl__more-chip\"><?php echo esc_html( genosys_persian_number( count( $components ) - 2 ) ); ?>+ محصول</span><?php endif; ?></div><button type=\"button\" class=\"gpl__contents-toggle\" data-package-toggle aria-expanded=\"false\" aria-controls=\"gpl-details-<?php echo esc_attr( $id ); ?>\"><span data-package-toggle-label>مشاهده‌ی محتوا</span><?php echo genosys_package_list_icon( 'chevron' ); ?></button></td>\n\t\t<td class=\"gpl__price-col\"><strong class=\"gpl__price\"><?php echo genosys_package_list_price( $price ); ?></strong><?php if ( $discount ) : ?><del class=\"gpl__regular-price\"><?php echo genosys_package_list_price( $regular ); ?></del><span class=\"gpl__discount\"><?php echo esc_html( genosys_persian_number( $discount ) ); ?>٪ تخفیف</span><?php endif; ?></td>\n\t\t<td class=\"gpl__stock-col\"><div class=\"gpl__stock\" data-state=\"<?php echo esc_attr( $state ); ?>\"><strong><?php echo esc_html( null === $stock ? '—' : genosys_persian_number( $stock ) ); ?></strong><span><?php echo esc_html( 'outofstock' === $state ? 'ناموجود' : ( 'low' === $state ? 'موجودی کم' : ( 'unmanaged' === $state ? 'موجود · بدون مدیریت تعداد' : 'موجود' ) ) ); ?></span></div></td>\n\t\t<td class=\"gpl__actions-col\"><div class=\"gpl__actions\">\n\t\t\t<?php if ( $can_edit ) : ?><a class=\"gpl__action\" href=\"<?php echo esc_url( admin_url( 'admin.php?page=genosys-add-package&package_id=' . $id ) ); ?>\" title=\"ویرایش\" aria-label=\"<?php echo esc_attr( 'ویرایش ' . $product->get_name() ); ?>\" data-package-operation=\"edit\"><?php echo genosys_package_list_icon( 'edit' ); ?></a><?php endif; ?>\n\t\t\t<?php if ( ! $trashed && current_user_can( 'read_post', $id ) ) : ?><a class=\"gpl__action\" href=\"<?php echo esc_url( in_array( $status, array( 'publish', 'private' ), true ) ? $product->get_permalink() : get_preview_post_link( $id ) ); ?>\" target=\"_blank\" rel=\"noopener noreferrer\" title=\"مشاهده\" aria-label=\"<?php echo esc_attr( 'مشاهده ' . $product->get_name() ); ?>\" data-package-operation=\"view\"><?php echo genosys_package_list_icon( 'eye' ); ?></a><?php endif; ?>\n\t\t\t<?php if ( $can_edit ) { genosys_package_list_action_form( 'duplicate', $product, $context, 'کپی پکیج', 'copy' ); } ?>\n\t\t\t<?php if ( $can_delete ) { genosys_package_list_action_form( $trashed ? 'restore' : 'trash', $product, $context, $trashed ? 'بازگردانی' : 'انتقال به زباله‌دان', $trashed ? 'restore' : 'trash', $trashed ? '' : 'این پکیج به زباله‌دان منتقل شود؟' ); } ?>\n\t\t</div></td>\n\t</tr>\n\t<tr class=\"gpl__detail-row\" id=\"gpl-details-<?php echo esc_attr( $id ); ?>\" hidden><td colspan=\"6\"><?php genosys_package_list_details( $product, $components, $stock ); ?></td></tr>\n\t<?php\n}\n\nfunction genosys_package_list_page() {\n\tif ( ! current_user_can( 'manage_woocommerce' ) || ! function_exists( 'wc_get_product' ) ) { wp_die( 'اجازه دسترسی به این صفحه را ندارید.', '', array( 'response' => 403 ) ); }\n\t$context = genosys_package_list_context();\n\t$labels = array( 'all' => 'همه', 'published' => 'منتشر شده', 'draft' => 'پیش‌نویس', 'pending' => 'در انتظار بررسی', 'outofstock' => 'ناموجود', 'trash' => 'زباله‌دان' );\n\t$notice = isset( $_GET['gpl_notice'] ) && is_scalar( $_GET['gpl_notice'] ) ? sanitize_key( wp_unslash( $_GET['gpl_notice'] ) ) : '';\n\t$notices = array( 'duplicated' => 'یک نسخه پیش‌نویس از پکیج ساخته شد.', 'trashed' => 'پکیج به زباله‌دان منتقل شد.', 'restored' => 'پکیج از زباله‌دان بازگردانی شد.', 'bulk_trashed' => 'پکیج‌های انتخاب‌شده به زباله‌دان منتقل شدند.', 'error' => 'عملیات انجام نشد. صفحه را تازه کنید و دوباره تلاش کنید.' );\n\t?>\n\t<div class=\"wrap gpl\" dir=\"rtl\" data-package-list>\n\t\t<header class=\"gpl__header\"><div class=\"gpl__header-title\"><h1>پکیج‌ها</h1><span class=\"gpl__heading-count\"><?php echo esc_html( genosys_persian_number( $context['total'] ) ); ?> پکیج</span></div><?php if ( current_user_can( 'edit_products' ) ) : ?><a class=\"gpl__add\" href=\"<?php echo esc_url( admin_url( 'admin.php?page=genosys-add-package' ) ); ?>\"><?php echo genosys_package_list_icon( 'plus' ); ?>افزودن پکیج</a><?php endif; ?></header>\n\t\t<?php if ( isset( $notices[ $notice ] ) ) : ?><div class=\"gpl__notice<?php echo 'error' === $notice ? ' gpl__notice--error' : ''; ?>\" role=\"status\"><?php echo esc_html( $notices[ $notice ] ); ?></div><?php endif; ?>\n\t\t<section class=\"gpl__stats\" aria-label=\"خلاصه پکیج‌ها\">\n\t\t\t<?php foreach ( array( 'all' => array( 'total', 'کل پکیج‌ها', 'package' ), 'published' => array( 'published', 'منتشر شده', 'check' ), 'low' => array( 'low', 'موجودی کم', 'alert' ), 'outofstock' => array( 'outofstock', 'ناموجود', 'close' ) ) as $key => $stat ) : ?>\n\t\t\t\t<div class=\"gpl__stat gpl__stat--<?php echo esc_attr( $stat[0] ); ?>\"><span class=\"gpl__stat-icon\"><?php echo genosys_package_list_icon( $stat[2] ); ?></span><span class=\"gpl__stat-label\"><?php echo esc_html( $stat[1] ); ?></span><strong class=\"gpl__stat-value\"><?php echo esc_html( genosys_persian_number( $context['stats'][ $key ] ) ); ?></strong></div>\n\t\t\t<?php endforeach; ?>\n\t\t</section>\n\t\t<section class=\"gpl__panel\" aria-label=\"لیست پکیج ها\">\n\t\t\t<nav class=\"gpl__tabs\" aria-label=\"وضعیت پکیج‌ها\"><?php foreach ( $labels as $key => $label ) : ?><a class=\"gpl__tab<?php echo $key === $context['status'] ? ' is-active' : ''; ?>\" href=\"<?php echo esc_url( genosys_package_list_url( array( 'gpl_status' => $key, 'gpl_page' => 1 ) ) ); ?>\"<?php if ( $key === $context['status'] ) : ?> aria-current=\"page\"<?php endif; ?>><?php echo esc_html( $label ); ?><span class=\"gpl__tab-count\"><?php echo esc_html( genosys_persian_number( $context['counts'][ $key ] ) ); ?></span></a><?php endforeach; ?></nav>\n\t\t\t<div class=\"gpl__toolbar\">\n\t\t\t\t<form class=\"gpl__search-form\" method=\"get\" action=\"<?php echo esc_url( admin_url( 'admin.php' ) ); ?>\"><input type=\"hidden\" name=\"page\" value=\"genosys-package-list\"><input type=\"hidden\" name=\"gpl_status\" value=\"<?php echo esc_attr( $context['status'] ); ?>\"><label class=\"gpl__search-field\"><?php echo genosys_package_list_icon( 'search' ); ?><span class=\"screen-reader-text\">جستجو در پکیج‌ها با نام، شناسه یا محصولات داخل آن</span><input type=\"search\" name=\"gpl_search\" value=\"<?php echo esc_attr( $context['search'] ); ?>\" placeholder=\"جستجو در نام پکیج، شناسه یا محصولات داخل آن...\" autocomplete=\"off\"></label><label class=\"gpl__sort\"><span class=\"screen-reader-text\">مرتب‌سازی پکیج‌ها</span><select name=\"gpl_order\"><?php foreach ( array( 'latest' => 'جدیدترین', 'oldest' => 'قدیمی‌ترین', 'price_asc' => 'ارزان‌ترین', 'price_desc' => 'گران‌ترین', 'name' => 'نام پکیج' ) as $key => $label ) : ?><option value=\"<?php echo esc_attr( $key ); ?>\"<?php selected( $context['order'], $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select><?php echo genosys_package_list_icon( 'chevron' ); ?></label><button type=\"submit\" class=\"gpl__search-submit screen-reader-text\">جستجو</button></form>\n\t\t\t\t<p class=\"gpl__results\"><?php echo esc_html( 'نمایش ' . genosys_persian_number( count( $context['products'] ) ) . ' از ' . genosys_persian_number( $context['filtered_total'] ) . ' پکیج' ); ?></p>\n\t\t\t</div>\n\t\t\t<form class=\"gpl__bulk-bar\" method=\"post\" action=\"<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>\" data-package-bulk data-package-confirm=\"پکیج‌های انتخاب‌شده به زباله‌دان منتقل شوند؟\" hidden><input type=\"hidden\" name=\"action\" value=\"genosys_package_list_action\"><input type=\"hidden\" name=\"operation\" value=\"bulk_trash\"><?php wp_nonce_field( 'genosys_package_list_action_bulk_trash_0', '_wpnonce', false ); genosys_package_list_return_fields( $context ); ?><span><b data-package-selected-count>۰</b> پکیج انتخاب شده</span><span data-package-selected-inputs></span><button type=\"submit\"><?php echo genosys_package_list_icon( 'trash' ); ?>انتقال به زباله‌دان</button></form>\n\t\t\t<div class=\"gpl__table-wrap\" role=\"region\" aria-label=\"جدول پکیج‌ها\" tabindex=\"0\"><table class=\"gpl__table\"><thead><tr><th class=\"gpl__select-col\"><input type=\"checkbox\" class=\"gpl__checkbox\" data-package-select-all aria-label=\"انتخاب همه پکیج‌های این صفحه\"></th><th class=\"gpl__package-col\" scope=\"col\">پکیج</th><th class=\"gpl__contents-col\" scope=\"col\">محتوای پکیج</th><th class=\"gpl__price-col\" scope=\"col\">قیمت</th><th class=\"gpl__stock-col\" scope=\"col\">موجودی</th><th class=\"gpl__actions-col\" scope=\"col\">عملیات</th></tr></thead><tbody>\n\t\t\t\t<?php foreach ( $context['products'] as $product ) { genosys_package_list_row( $product, $context ); } ?>\n\t\t\t\t<?php if ( ! $context['products'] ) : ?><tr><td class=\"gpl__empty\" colspan=\"6\"><?php echo esc_html( 'trash' === $context['status'] ? 'پکیجی در زباله‌دان نیست.' : ( $context['search'] ? 'پکیجی با این جستجو پیدا نشد.' : 'پکیجی با این وضعیت پیدا نشد.' ) ); ?></td></tr><?php endif; ?>\n\t\t\t</tbody></table></div>\n\t\t\t<?php if ( $context['pages'] > 1 ) : ?><nav class=\"gpl__pagination\" aria-label=\"صفحه‌بندی پکیج‌ها\">\n\t\t\t\t<?php if ( $context['page'] > 1 ) : ?><a class=\"gpl__page\" href=\"<?php echo esc_url( genosys_package_list_url( array( 'gpl_page' => $context['page'] - 1 ) ) ); ?>\">قبلی</a><?php else : ?><span class=\"gpl__page is-disabled\" aria-disabled=\"true\">قبلی</span><?php endif; ?>\n\t\t\t\t<?php $visible_pages = array_unique( array_merge( array( 1 ), range( max( 1, $context['page'] - 2 ), min( $context['pages'], $context['page'] + 2 ) ), array( $context['pages'] ) ) ); $last = 0; foreach ( $visible_pages as $page ) : ?><?php if ( $last && $page > $last + 1 ) : ?><span class=\"gpl__page-gap\" aria-hidden=\"true\">…</span><?php endif; ?><a class=\"gpl__page<?php echo $page === $context['page'] ? ' is-current' : ''; ?>\" href=\"<?php echo esc_url( genosys_package_list_url( array( 'gpl_page' => $page ) ) ); ?>\"<?php if ( $page === $context['page'] ) : ?> aria-current=\"page\"<?php endif; ?>><?php echo esc_html( genosys_persian_number( $page ) ); ?></a><?php $last = $page; endforeach; ?>\n\t\t\t\t<?php if ( $context['page'] < $context['pages'] ) : ?><a class=\"gpl__page\" href=\"<?php echo esc_url( genosys_package_list_url( array( 'gpl_page' => $context['page'] + 1 ) ) ); ?>\">بعدی</a><?php else : ?><span class=\"gpl__page is-disabled\" aria-disabled=\"true\">بعدی</span><?php endif; ?>\n\t\t\t</nav><?php endif; ?>\n\t\t</section>\n\t</div>\n\t<?php\n}\n","sha256":"e6096cde64079e2d92a29757446ce2703a7f8c57ee8d8f04a76ee9ed3aaff470"},"inc/package-publishing.php":{"content":"<?php\n/** Capability-checked native WooCommerce package publishing and editing. */\ndefined( 'ABSPATH' ) || exit;\n\n/** Admin prices use the store's base rates, never an administrator's customer/VAT session. */\nfunction genosys_package_price_basis( $price, $product, $to_display ) {\n\t$amount = (float) $price; $display_includes_tax = 'incl' === get_option( 'woocommerce_tax_display_shop' );\n\t$from_includes_tax = $to_display ? wc_prices_include_tax() : $display_includes_tax;\n\t$to_includes_tax = $to_display ? $display_includes_tax : wc_prices_include_tax();\n\tif ( wc_tax_enabled() && $product->is_taxable() && $from_includes_tax !== $to_includes_tax ) {\n\t\t$rates = WC_Tax::get_base_tax_rates( $product->get_tax_class() );\n\t\t$taxes = WC_Tax::calc_tax( $amount, $rates, $from_includes_tax );\n\t\t$tax = $to_display && $to_includes_tax && 'yes' !== get_option( 'woocommerce_tax_round_at_subtotal' ) ? array_sum( array_map( 'wc_round_tax_total', $taxes ) ) : array_sum( $taxes );\n\t\t$amount += $to_includes_tax ? $tax : -$tax;\n\t}\n\treturn wc_format_decimal( max( 0, $amount ), $to_display ? wc_get_price_decimals() : wc_get_rounding_precision() );\n}\nfunction genosys_package_entered_price( $price, $product ) { return genosys_package_price_basis( $price, $product, false ); }\nfunction genosys_package_display_price( $price, $product ) { return genosys_package_price_basis( $price, $product, true ); }\n\nfunction genosys_package_builder_data( $product ) {\n\t$items = array();\n\tforeach ( genosys_package_components( $product ) as $component ) {\n\t\t$payload = genosys_package_catalog_payload( wc_get_product( $component['product_id'] ) );\n\t\tif ( ! $payload ) {\n\t\t\t$payload = array( 'id' => $component['product_id'], 'name' => 'محصول حذف‌شده یا غیرفعال', 'sku' => '', 'price_minor' => null, 'image' => '', 'stock_quantity' => 0, 'stock_pool_id' => $component['product_id'], 'stock_status' => 'outofstock', 'stock_state' => 'outofstock', 'stock_label' => 'ناموجود' );\n\t\t}\n\t\t$items[] = array( 'product' => $payload, 'quantity' => $component['quantity'] );\n\t}\n\t$visibility = 'private' === $product->get_status() ? 'private' : ( 'hidden' === $product->get_catalog_visibility() ? 'hidden' : ( in_array( $product->get_status(), array( 'draft', 'pending' ), true ) && 'private' === $product->get_meta( '_genosys_package_visibility', true ) ? 'private' : 'public' ) );\n\treturn array(\n\t\t'id' => $product->get_id(), 'name' => $product->get_name(), 'description' => $product->get_description(),\n\t\t'items' => $items, 'image' => array( 'id' => $product->get_image_id(), 'url' => $product->get_image_id() ? wp_get_attachment_image_url( $product->get_image_id(), 'large' ) : '' ),\n\t\t'price' => '' === $product->get_price( 'edit' ) ? '' : genosys_package_display_price( $product->get_price( 'edit' ), $product ), 'sku' => $product->get_sku(),\n\t\t'status' => 'private' === $product->get_status() ? 'publish' : $product->get_status(),\n\t\t'visibility' => $visibility, 'permalink' => $product->get_permalink(),\n\t);\n}\n\nfunction genosys_package_save_response( $product, $replayed = false ) {\n\treturn array( 'package_id' => $product->get_id(), 'permalink' => $product->get_permalink(), 'edit_url' => admin_url( 'admin.php?page=genosys-add-package&package_id=' . $product->get_id() ),\n\t\t'message' => $replayed ? 'این پکیج قبلاً ذخیره شده است.' : ( in_array( $product->get_status(), array( 'publish', 'private' ), true ) ? 'پکیج با موفقیت منتشر شد.' : 'پکیج با موفقیت ذخیره شد.' ),\n\t\t'replayed' => $replayed, 'package' => genosys_package_builder_data( $product ) );\n}\n\nfunction genosys_package_save_ajax() {\n\tif ( 'POST' !== ( $_SERVER['REQUEST_METHOD'] ?? '' ) ) { wp_send_json_error( array( 'message' => 'درخواست نامعتبر است.' ), 405 ); }\n\tif ( ! function_exists( 'wc_get_product' ) || ! current_user_can( 'manage_woocommerce' ) || ! current_user_can( 'edit_products' ) ) { wp_send_json_error( array( 'message' => 'اجازه ذخیره پکیج را ندارید.' ), 403 ); }\n\tif ( ! check_ajax_referer( 'genosys_package_save', 'nonce', false ) ) { wp_send_json_error( array( 'message' => 'صفحه را تازه کنید و دوباره تلاش کنید.' ), 403 ); }\n\t$string = static function ( $key ) { return isset( $_POST[ $key ] ) && is_string( $_POST[ $key ] ) ? wp_unslash( $_POST[ $key ] ) : ''; };\n\tforeach ( array( 'package_id', 'image_id' ) as $key ) {\n\t\t$value = $string( $key );\n\t\tif ( ! preg_match( '/^(?:0|[1-9][0-9]*)$/D', $value ) || (string) (int) $value !== $value ) { wp_send_json_error( array( 'message' => 'شناسه پکیج یا تصویر معتبر نیست.' ), 400 ); }\n\t}\n\t$id = absint( $string( 'package_id' ) );\n\t$token = $string( 'request_token' );\n\tif ( ! preg_match( '/^[a-zA-Z0-9-]{16,100}$/D', $token ) ) { wp_send_json_error( array( 'message' => 'شناسه درخواست معتبر نیست؛ صفحه را تازه کنید.' ), 400 ); }\n\t$product = $id ? wc_get_product( $id ) : null;\n\tif ( $id && ( ! $product || ! genosys_is_package_product( $product ) || ! current_user_can( 'edit_post', $id ) ) ) { wp_send_json_error( array( 'message' => 'پکیج برای ویرایش در دسترس نیست.' ), 403 ); }\n\t$lock = 'genosys_pkg_save_' . hash( 'sha256', $id ? 'edit:' . $id : 'create:' . get_current_user_id() . ':' . $token );\n\t$locked = add_option( $lock, time(), '', false );\n\tif ( ! $locked ) {\n\t\t$previous = get_option( $lock );\n\t\tif ( is_numeric( $previous ) && (int) $previous < time() - 180 ) {\n\t\t\tglobal $wpdb;\n\t\t\tif ( $wpdb->delete( $wpdb->options, array( 'option_name' => $lock, 'option_value' => (string) $previous ) ) ) {\n\t\t\t\twp_cache_delete( $lock, 'options' ); wp_cache_delete( 'notoptions', 'options' );\n\t\t\t\t$locked = add_option( $lock, time(), '', false );\n\t\t\t}\n\t\t}\n\t}\n\tif ( ! $locked ) { wp_send_json_error( array( 'message' => 'ذخیره همین پکیج در حال انجام است؛ کمی بعد دوباره تلاش کنید.' ), 409 ); }\n\t$transaction = false;\n\ttry {\n\t\tif ( ! $id ) {\n\t\t\t$existing = get_posts( array( 'post_type' => 'product', 'post_status' => array( 'publish', 'private', 'draft', 'pending' ), 'numberposts' => 1, 'fields' => 'ids', 'meta_query' => array( 'relation' => 'AND', array( 'key' => '_genosys_package_request_token', 'value' => $token ), array( 'key' => '_genosys_package_request_user', 'value' => get_current_user_id() ) ) ) );\n\t\t\tif ( $existing ) {\n\t\t\t\t$recovered = wc_get_product( reset( $existing ) );\n\t\t\t\tif ( ! $recovered || ! genosys_is_package_product( $recovered ) || ! current_user_can( 'edit_post', $recovered->get_id() ) ) { throw new Exception( 'پکیج برای ویرایش در دسترس نیست.' ); }\n\t\t\t\t$response = genosys_package_save_response( $recovered, true );\n\t\t\t\tdelete_option( $lock ); wp_send_json_success( $response );\n\t\t\t}\n\t\t}\n\t\t$name = sanitize_text_field( $string( 'name' ) );\n\t\tif ( '' === trim( $name ) || strlen( $name ) > 800 || count( preg_split( '//u', $name, -1, PREG_SPLIT_NO_EMPTY ) ) > 200 ) { throw new Exception( 'نام پکیج را وارد کنید (حداکثر ۲۰۰ نویسه).' ); }\n\t\t$status = $string( 'status' ); $visibility = $string( 'visibility' );\n\t\tif ( ! in_array( $status, array( 'draft', 'pending', 'publish' ), true ) || ! in_array( $visibility, array( 'public', 'private', 'hidden' ), true ) ) { throw new Exception( 'وضعیت یا نمایان بودن پکیج معتبر نیست.' ); }\n\t\tif ( 'publish' === $status && ! current_user_can( 'publish_products' ) ) { throw new Exception( 'اجازه انتشار محصول را ندارید.' ); }\n\t\tif ( $id && in_array( $product->get_status(), array( 'publish', 'private' ), true ) && ! current_user_can( 'edit_published_products' ) ) { throw new Exception( 'اجازه ویرایش پکیج منتشرشده را ندارید.' ); }\n\t\t$submitted = json_decode( $string( 'items' ), true );\n\t\tif ( ! is_array( $submitted ) || count( $submitted ) > 24 ) { throw new Exception( 'فهرست محصولات پکیج معتبر نیست.' ); }\n\t\t$items = array(); $seen = array(); $regular = 0;\n\t\tforeach ( $submitted as $item ) {\n\t\t\tif ( ! is_array( $item ) || ! isset( $item['product_id'], $item['quantity'] ) || ! is_numeric( $item['product_id'] ) || (float) $item['product_id'] !== (float) (int) $item['product_id'] || (int) $item['product_id'] < 1 || ! is_numeric( $item['quantity'] ) || (float) $item['quantity'] !== (float) (int) $item['quantity'] || (int) $item['quantity'] < 1 || (int) $item['quantity'] > 9999 ) { throw new Exception( 'تعداد یا محصول انتخاب‌شده معتبر نیست.' ); }\n\t\t\t$component = wc_get_product( absint( $item['product_id'] ) );\n\t\t\tif ( ! genosys_package_component_is_eligible( $component ) || isset( $seen[ $component->get_id() ] ) ) { throw new Exception( 'محصولات باید معتبر و متفاوت باشند؛ پکیج دیگری را نمی‌توان در پکیج قرار داد.' ); }\n\t\t\t$seen[ $component->get_id() ] = true; $items[] = array( 'product_id' => $component->get_id(), 'quantity' => (int) $item['quantity'] );\n\t\t\tif ( '' === $component->get_price() && 'draft' !== $status ) { throw new Exception( 'یکی از محصولات قیمت ندارد؛ ابتدا قیمت آن را در ووکامرس تعیین کنید.' ); }\n\t\t\t$regular += (float) genosys_package_display_price( $component->get_price( 'edit' ), $component ) * (int) $item['quantity'];\n\t\t}\n\t\t$image_id = absint( $string( 'image_id' ) );\n\t\tif ( $image_id && ( ! current_user_can( 'upload_files' ) || 'attachment' !== get_post_type( $image_id ) || ! current_user_can( 'read_post', $image_id ) || ! in_array( get_post_mime_type( $image_id ), array( 'image/jpeg', 'image/png', 'image/webp' ), true ) ) ) { throw new Exception( 'تصویر انتخاب‌شده از رسانه معتبر نیست.' ); }\n\t\tif ( $image_id ) {\n\t\t\t$metadata = wp_get_attachment_metadata( $image_id ); $file = get_attached_file( $image_id );\n\t\t\t$size = isset( $metadata['filesize'] ) ? (int) $metadata['filesize'] : ( $file && is_file( $file ) ? filesize( $file ) : 0 );\n\t\t\tif ( $size > 5 * MB_IN_BYTES ) { throw new Exception( 'حجم تصویر باید حداکثر ۵ مگابایت باشد.' ); }\n\t\t}\n\t\t$raw_price = genosys_shop_ascii_digits( trim( $string( 'price' ) ) );\n\t\tif ( '' !== $raw_price && ( ! preg_match( '/^\\d{1,15}(?:\\.\\d{1,6})?$/D', $raw_price ) || ! is_finite( (float) $raw_price ) ) ) { throw new Exception( 'قیمت پکیج معتبر نیست.' ); }\n\t\t$price = '' === $raw_price ? '' : wc_format_decimal( $raw_price, wc_get_price_decimals() );\n\t\tif ( 'draft' !== $status && ( count( $items ) < 2 || ! $image_id || '' === $price || (float) $price <= 0 ) ) { throw new Exception( 'برای انتشار، نام، حداقل دو محصول متفاوت، تصویر و قیمت پکیج را کامل کنید.' ); }\n\t\t$sku = sanitize_text_field( $string( 'sku' ) );\n\t\tif ( strlen( $sku ) > 100 || ( '' !== $sku && ! wc_product_has_unique_sku( $id, $sku ) ) ) { throw new Exception( 'شناسه SKU تکراری یا نامعتبر است.' ); }\n\t\t$term = genosys_package_special_category( true );\n\t\tif ( ! $term || is_wp_error( $term ) ) { throw new Exception( 'دسته‌بندی پکیج‌های ویژه در دسترس نیست.' ); }\n\t\tif ( ! $product ) { $product = new WC_Product_Genosys_Package(); }\n\t\t$product->set_name( $name );\n\t\t$product->set_description( wp_kses_post( $string( 'description' ) ) );\n\t\t$product->set_short_description( wp_trim_words( wp_strip_all_tags( $string( 'description' ) ), 40, '…' ) );\n\t\t$product->set_status( 'publish' === $status && 'private' === $visibility ? 'private' : $status );\n\t\t$product->set_catalog_visibility( 'hidden' === $visibility ? 'hidden' : 'visible' );\n\t\t$product->update_meta_data( '_genosys_package_visibility', $visibility );\n\t\t$product->set_category_ids( array( (int) $term->term_id ) );\n\t\t$product->set_image_id( $image_id ); $product->set_sku( $sku );\n\t\t$product->set_manage_stock( false ); $product->set_backorders( 'no' );\n\t\t$product->set_virtual( false ); $product->set_downloadable( false );\n\t\t$entered_price = '' === $price ? '' : genosys_package_entered_price( $price, $product );\n\t\t$entered_regular = '' === $price ? '' : genosys_package_entered_price( max( $regular, (float) $price ), $product );\n\t\t$product->set_regular_price( $entered_regular );\n\t\t$product->set_sale_price( '' !== $entered_price && (float) $entered_regular > (float) $entered_price ? $entered_price : '' );\n\t\t$product->set_price( $entered_price );\n\t\t$product->update_meta_data( '_genosys_package_items', $items );\n\t\t$product->delete_meta_data( '_genosys_package_component_id' );\n\t\tforeach ( $items as $item ) {\n\t\t\t$component = wc_get_product( $item['product_id'] );\n\t\t\tforeach ( array_unique( array_filter( array( $item['product_id'], $component->get_parent_id(), $component->get_stock_managed_by_id() ) ) ) as $dependency ) { $product->add_meta_data( '_genosys_package_component_id', (int) $dependency ); }\n\t\t}\n\t\tif ( ! $id ) { $product->update_meta_data( '_genosys_package_request_token', $token ); $product->update_meta_data( '_genosys_package_request_user', get_current_user_id() ); }\n\t\tglobal $wpdb;\n\t\tif ( false === $wpdb->query( 'START TRANSACTION' ) ) { throw new Exception( 'ذخیره پکیج آغاز نشد؛ دوباره تلاش کنید.' ); }\n\t\t$transaction = true;\n\t\t$product->save();\n\t\tif ( function_exists( 'genosys_package_sync_stock' ) ) { genosys_package_sync_stock( $product->get_id() ); }\n\t\tif ( false === $wpdb->query( 'COMMIT' ) ) { throw new Exception( 'ذخیره پکیج کامل نشد؛ دوباره تلاش کنید.' ); }\n\t\t$transaction = false;\n\t\t$response = genosys_package_save_response( wc_get_product( $product->get_id() ) );\n\t\tdelete_option( $lock ); wp_send_json_success( $response );\n\t} catch ( Throwable $error ) {\n\t\tif ( $transaction ) { $wpdb->query( 'ROLLBACK' ); if ( $product && $product->get_id() ) { clean_post_cache( $product->get_id() ); wc_delete_product_transients( $product->get_id() ); } }\n\t\tdelete_option( $lock ); wp_send_json_error( array( 'message' => wp_strip_all_tags( $error->getMessage() ) ), 400 );\n\t}\n}\nadd_action( 'wp_ajax_genosys_package_save', 'genosys_package_save_ajax' );\nadd_action( 'wp_ajax_nopriv_genosys_package_save', 'genosys_package_save_ajax' );\n","sha256":"a7a2f6ac20dfb1340b1fa399109975a77856ed06047b8377ce3faeaf4318f8e6"},"inc/package-visibility.php":{"content":"<?php\n/** Packages use the existing product cards, only in an explicitly selected package category. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_package_special_category( $create = false ) {\n\tif ( ! taxonomy_exists( 'product_cat' ) ) { return null; }\n\t$stored = (int) get_option( 'genosys_package_category_id', 0 );\n\t$term = $stored ? get_term( $stored, 'product_cat' ) : null;\n\tif ( $term && ! is_wp_error( $term ) ) { return $term; }\n\t$terms = get_terms( array( 'taxonomy' => 'product_cat', 'hide_empty' => false, 'orderby' => 'term_id', 'order' => 'ASC' ) );\n\tforeach ( is_wp_error( $terms ) ? array() : $terms as $candidate ) {\n\t\t$name = str_replace( array( 'ي', 'ك' ), array( 'ی', 'ک' ), $candidate->name );\n\t\t$name = preg_replace( '/[\\s\\x{200C}\\x{200D}\\x{064B}-\\x{065F}\\x{0670}ـ-]+/u', '', $name );\n\t\tif ( in_array( $name, array( 'پکیجهایویژه', 'پکیجویژه' ), true ) ) {\n\t\t\tif ( $create ) { update_option( 'genosys_package_category_id', (int) $candidate->term_id, false ); }\n\t\t\treturn $candidate;\n\t\t}\n\t}\n\tif ( ! $create ) { return null; }\n\t$result = wp_insert_term( 'پکیج‌های ویژه', 'product_cat', array( 'slug' => 'special-packages' ) );\n\tif ( is_wp_error( $result ) ) { return $result; }\n\tupdate_option( 'genosys_package_category_id', (int) $result['term_id'], false );\n\treturn get_term( $result['term_id'], 'product_cat' );\n}\n\nfunction genosys_package_category_clause( $clause, $term ) {\n\tif ( ! is_array( $clause ) || ! $term ) { return false; }\n\tif ( 'product_cat' === ( $clause['taxonomy'] ?? '' ) && in_array( strtoupper( $clause['operator'] ?? 'IN' ), array( 'IN', 'AND' ), true ) ) {\n\t\t$field = $clause['field'] ?? 'term_id';\n\t\tforeach ( (array) ( $clause['terms'] ?? array() ) as $value ) {\n\t\t\tif ( 'slug' === $field && (string) $value === $term->slug ) { return true; }\n\t\t\tif ( 'name' === $field && (string) $value === $term->name ) { return true; }\n\t\t\tif ( 'term_taxonomy_id' === $field && (int) $value === (int) $term->term_taxonomy_id ) { return true; }\n\t\t\tif ( in_array( $field, array( 'term_id', 'id' ), true ) && (int) $value === (int) $term->term_id ) { return true; }\n\t\t}\n\t}\n\tforeach ( $clause as $child ) { if ( is_array( $child ) && genosys_package_category_clause( $child, $term ) ) { return true; } }\n\treturn false;\n}\n\nfunction genosys_package_query_has_category( $query ) {\n\t$term = genosys_package_special_category();\n\tif ( ! $term || is_wp_error( $term ) ) { return false; }\n\tif ( genosys_package_category_clause( $query->get( 'tax_query' ), $term ) ) { return true; }\n\t$slug = $query->get( 'product_cat' );\n\tif ( is_string( $slug ) && in_array( $term->slug, explode( '/', $slug ), true ) ) { return true; }\n\tif ( 'product_cat' === $query->get( 'taxonomy' ) && in_array( (string) $query->get( 'term' ), array( $term->slug, (string) $term->term_id ), true ) ) { return true; }\n\tif ( $query->is_main_query() && function_exists( 'genosys_shop_is_main_query' ) && genosys_shop_is_main_query( $query ) ) {\n\t\treturn in_array( (int) $term->term_id, genosys_shop_filters()['categories'], true );\n\t}\n\treturn false;\n}\n\nfunction genosys_package_catalog_visibility( $query ) {\n\tif ( is_admin() || ! $query instanceof WP_Query || $query->is_singular() ) { return; }\n\t$type = $query->get( 'post_type' );\n\t$is_products = in_array( $type, array( 'product', 'any' ), true ) || ( is_array( $type ) && ( in_array( 'product', $type, true ) || in_array( 'any', $type, true ) ) ) || $query->is_search() || $query->is_tax( array( 'product_cat', 'product_tag' ) );\n\tif ( ! $is_products || genosys_package_query_has_category( $query ) ) { return; }\n\t$exclude = array( 'taxonomy' => 'product_type', 'field' => 'slug', 'terms' => array( 'genosys_package' ), 'operator' => 'NOT IN' );\n\t$existing = $query->get( 'tax_query' );\n\t$query->set( 'tax_query', $existing ? array( 'relation' => 'AND', $existing, $exclude ) : array( $exclude ) );\n}\nadd_action( 'pre_get_posts', 'genosys_package_catalog_visibility', 99 );\n\nfunction genosys_package_edit_link( $link, $id ) {\n\tif ( 'product' === get_post_type( $id ) && has_term( 'genosys_package', 'product_type', $id ) && current_user_can( 'edit_post', $id ) ) {\n\t\treturn admin_url( 'admin.php?page=genosys-add-package&package_id=' . (int) $id );\n\t}\n\treturn $link;\n}\nadd_filter( 'get_edit_post_link', 'genosys_package_edit_link', 10, 2 );\n\n/** Category links arrive at the existing shop grid, with its normal product-card template. */\nfunction genosys_package_category_shop_redirect() {\n\tif ( is_admin() || ! function_exists( 'is_product_category' ) || ! is_product_category() ) { return; }\n\t$special = genosys_package_special_category(); $current = get_queried_object();\n\tif ( ! $special || is_wp_error( $special ) || ! $current || (int) $current->term_id !== (int) $special->term_id ) { return; }\n\t$args = genosys_shop_query_args( genosys_shop_filters() );\n\t$args['shop_cat'] = array_values( array_unique( array_merge( (array) ( $args['shop_cat'] ?? array() ), array( (int) $special->term_id ) ) ) );\n\t$page = max( 1, (int) get_query_var( 'paged' ) ); if ( $page > 1 ) { $args['paged'] = $page; }\n\twp_safe_redirect( add_query_arg( $args, wc_get_page_permalink( 'shop' ) ), 302 ); exit;\n}\nadd_action( 'template_redirect', 'genosys_package_category_shop_redirect', 5 );\n\n/** Woo's related-product SQL does not run WP_Query; enforce the same catalog rule there. */\nfunction genosys_package_hide_related( $ids ) {\n\tif ( is_admin() ) { return $ids; }\n\treturn array_values( array_filter( (array) $ids, static function ( $id ) { return ! has_term( 'genosys_package', 'product_type', (int) $id ); } ) );\n}\nadd_filter( 'woocommerce_related_products', 'genosys_package_hide_related', 20 );\nadd_filter( 'woocommerce_product_get_upsell_ids', 'genosys_package_hide_related', 20 );\nadd_filter( 'woocommerce_product_get_cross_sell_ids', 'genosys_package_hide_related', 20 );\n","sha256":"10c695ef70eef25a9efc5ef4bbeda5007da9b973c4c9d53127ec0112ba23e904"},"inc/packages.php":{"content":"<?php\n/** WooCommerce packages use their components' inventory; the package has no independent stock. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_is_package_product( $product ) {\n\treturn $product instanceof WC_Product && 'genosys_package' === $product->get_type();\n}\n\n/** Definitions contain distinct product/variation IDs and whole units per package. */\nfunction genosys_package_components( $product ) {\n\t$product = $product instanceof WC_Product ? $product : wc_get_product( $product );\n\tif ( ! $product ) { return array(); }\n\t$raw = $product->get_meta( '_genosys_package_items', true );\n\tif ( ! is_array( $raw ) || count( $raw ) > 24 ) { return array(); }\n\t$items = array(); $seen = array();\n\tforeach ( $raw as $row ) {\n\t\tif ( ! is_array( $row ) || ! isset( $row['product_id'], $row['quantity'] ) || ! is_numeric( $row['product_id'] ) || ! is_numeric( $row['quantity'] ) ) { return array(); }\n\t\t$id = (int) $row['product_id']; $qty = (int) $row['quantity'];\n\t\tif ( $id < 1 || $qty < 1 || $qty > 9999 || (float) $row['product_id'] !== (float) $id || (float) $row['quantity'] !== (float) $qty || isset( $seen[ $id ] ) ) { return array(); }\n\t\t$seen[ $id ] = true; $items[] = array( 'product_id' => $id, 'quantity' => $qty );\n\t}\n\treturn $items;\n}\n\nfunction genosys_package_component_is_eligible( $product ) {\n\tif ( ! $product instanceof WC_Product || 'publish' !== $product->get_status() || ! $product->is_type( array( 'simple', 'variation' ) ) || genosys_is_package_product( $product ) ) { return false; }\n\tif ( $product->is_type( 'variation' ) ) {\n\t\t$parent = wc_get_product( $product->get_parent_id() );\n\t\treturn $parent && $parent->is_type( 'variable' ) && 'publish' === $parent->get_status();\n\t}\n\treturn true;\n}\n\n/** Null means all eligible components are in stock with no managed quantity limit. */\nfunction genosys_package_stock( $product ) {\n\t$components = genosys_package_components( $product );\n\tif ( count( $components ) < 2 ) { return 0; }\n\t$pools = array();\n\tforeach ( $components as $row ) {\n\t\t$component = wc_get_product( $row['product_id'] );\n\t\tif ( ! genosys_package_component_is_eligible( $component ) || ! $component->is_in_stock() ) { return 0; }\n\t\tif ( ! $component->managing_stock() ) { if ( 'instock' !== $component->get_stock_status() ) { return 0; } continue; }\n\t\t$id = (int) $component->get_stock_managed_by_id(); $pool = wc_get_product( $id );\n\t\tif ( ! $pool || ! is_numeric( $pool->get_stock_quantity() ) ) { return 0; }\n\t\tif ( ! isset( $pools[ $id ] ) ) { $pools[ $id ] = array( 'stock' => max( 0, (float) $pool->get_stock_quantity() ), 'units' => 0 ); }\n\t\t$pools[ $id ]['units'] += $row['quantity'];\n\t}\n\t$available = null;\n\tforeach ( $pools as $pool ) {\n\t\t$quantity = (int) floor( $pool['stock'] / $pool['units'] );\n\t\t$available = null === $available ? $quantity : min( $available, $quantity );\n\t}\n\treturn $available;\n}\n\nfunction genosys_package_classes() {\n\tif ( ! class_exists( 'WC_Product_Simple' ) || class_exists( 'WC_Product_Genosys_Package' ) ) { return; }\n\tclass WC_Product_Genosys_Package extends WC_Product_Simple {\n\t\tpublic function get_type() { return 'genosys_package'; }\n\t\tpublic function get_manage_stock( $context = 'view' ) { return false; }\n\t\tpublic function managing_stock() { return false; }\n\t\tpublic function get_virtual( $context = 'view' ) { return false; }\n\t\tpublic function get_downloadable( $context = 'view' ) { return false; }\n\t\tpublic function backorders_allowed() { return false; }\n\t\tpublic function is_on_backorder( $qty_in_cart = 0 ) { return false; }\n\t\tpublic function get_stock_quantity( $context = 'view' ) { return 'edit' === $context ? parent::get_stock_quantity( $context ) : genosys_package_stock( $this ); }\n\t\tpublic function get_stock_status( $context = 'view' ) { return 'edit' === $context ? parent::get_stock_status( $context ) : ( 0 === genosys_package_stock( $this ) ? 'outofstock' : 'instock' ); }\n\t\tpublic function is_in_stock() { return 0 !== genosys_package_stock( $this ); }\n\t\tpublic function is_purchasable() { return parent::is_purchasable() && count( genosys_package_components( $this ) ) >= 2; }\n\t\tpublic function has_enough_stock( $quantity ) { $stock = genosys_package_stock( $this ); return $quantity > 0 && floor( (float) $quantity ) === (float) $quantity && ( null === $stock || $stock >= $quantity ); }\n\t\tpublic function get_max_purchase_quantity() { $stock = genosys_package_stock( $this ); return $this->is_sold_individually() ? 1 : ( null === $stock ? -1 : $stock ); }\n\t\tpublic function get_weight( $context = 'view' ) {\n\t\t\tif ( 'edit' === $context ) { return parent::get_weight( $context ); }\n\t\t\t$weight = 0;\n\t\t\tforeach ( genosys_package_components( $this ) as $row ) { $component = wc_get_product( $row['product_id'] ); if ( genosys_package_component_is_eligible( $component ) ) { $weight += (float) $component->get_weight() * $row['quantity']; } }\n\t\t\treturn $weight ? (string) $weight : '';\n\t\t}\n\t\tprotected function get_availability_text() {\n\t\t\t$stock = genosys_package_stock( $this );\n\t\t\treturn 0 === $stock ? __( 'Out of stock', 'woocommerce' ) : ( null === $stock ? __( 'In stock', 'woocommerce' ) : sprintf( '%s پکیج موجود', function_exists( 'genosys_persian_number' ) ? genosys_persian_number( (string) $stock ) : $stock ) );\n\t\t}\n\t}\n\t/** Only native reservation sees these temporary inventory items; none are saved as order lines. */\n\tclass Genosys_Package_Inventory_Order extends WC_Order {\n\t\tprivate $inventory_items = array();\n\t\tpublic function set_inventory_items( $items ) { $this->inventory_items = $items; }\n\t\tpublic function get_items( $types = 'line_item' ) { return in_array( 'line_item', (array) $types, true ) ? $this->inventory_items : parent::get_items( $types ); }\n\t}\n}\nadd_action( 'woocommerce_init', 'genosys_package_classes', 0 );\nadd_filter( 'woocommerce_product_class', function ( $class, $type ) { return 'genosys_package' === $type ? 'WC_Product_Genosys_Package' : $class; }, 10, 2 );\nadd_filter( 'product_type_selector', function ( $types ) { $types['genosys_package'] = 'پکیج'; return $types; } );\nadd_action( 'woocommerce_genosys_package_add_to_cart', 'woocommerce_simple_add_to_cart' );\nadd_filter( 'woocommerce_add_to_cart_handler', function ( $type ) { return 'genosys_package' === $type ? 'simple' : $type; } );\n\nfunction genosys_package_component_snapshot( $product ) {\n\tif ( 0 === genosys_package_stock( $product ) ) { throw new Exception( 'محصولات این پکیج در حال حاضر موجود نیستند.' ); }\n\t$snapshot = array();\n\tforeach ( genosys_package_components( $product ) as $row ) {\n\t\t$component = wc_get_product( $row['product_id'] );\n\t\tif ( ! genosys_package_component_is_eligible( $component ) ) { throw new Exception( 'یکی از محصولات پکیج دیگر قابل فروش نیست.' ); }\n\t\t$snapshot[] = array( 'product_id' => $component->get_id(), 'quantity' => $row['quantity'], 'stock_pool_id' => (int) $component->get_stock_managed_by_id(), 'managed' => (bool) $component->managing_stock(), 'name' => $component->get_name(), 'sku' => $component->get_sku() );\n\t}\n\treturn $snapshot;\n}\n\nfunction genosys_package_snapshot_line_item( $item, $cart_key = '', $values = array(), $order = null ) {\n\tif ( ! $item instanceof WC_Order_Item_Product || $item->get_meta( '_genosys_package_components', true ) ) { return; }\n\t$product = isset( $values['data'] ) ? $values['data'] : $item->get_product();\n\tif ( genosys_is_package_product( $product ) ) {\n\t\t$quantity = (float) $item->get_quantity();\n\t\tif ( $quantity < 1 || floor( $quantity ) !== $quantity ) { throw new Exception( 'تعداد پکیج باید عدد صحیح و مثبت باشد.' ); }\n\t\t$item->add_meta_data( '_genosys_package_components', genosys_package_component_snapshot( $product ), true );\n\t}\n}\nadd_action( 'woocommerce_checkout_create_order_line_item', 'genosys_package_snapshot_line_item', 10, 4 );\nadd_action( 'woocommerce_new_order_item', function ( $item_id, $item ) {\n\tif ( $item instanceof WC_Order_Item_Product && genosys_is_package_product( $item->get_product() ) && ! $item->get_meta( '_genosys_package_components', true ) ) { genosys_package_snapshot_line_item( $item ); $item->save(); }\n}, 10, 2 );\n\nfunction genosys_package_order_has_packages( $order ) {\n\tif ( ! $order instanceof WC_Order ) { return false; }\n\tforeach ( $order->get_items() as $item ) { if ( $item->get_meta( '_genosys_package_components', true ) ) { return true; } }\n\treturn false;\n}\n\n/** Pools are frozen when an order first consumes stock, including ordinary lines in mixed orders. */\nfunction genosys_package_line_pools( $item ) {\n\t$ledger = $item->get_meta( '_genosys_package_stock_ledger', true );\n\tif ( is_array( $ledger ) && isset( $ledger['pools'] ) ) { return $ledger['pools']; }\n\t$snapshot = $item->get_meta( '_genosys_package_components', true ); $pools = array();\n\tif ( is_array( $snapshot ) && $snapshot ) {\n\t\tforeach ( $snapshot as $row ) {\n\t\t\tif ( empty( $row['managed'] ) ) { continue; }\n\t\t\t$id = (int) $row['stock_pool_id'];\n\t\t\tif ( ! isset( $pools[ $id ] ) ) { $pools[ $id ] = array( 'units' => 0, 'strict' => true ); }\n\t\t\t$pools[ $id ]['units'] += (float) $row['quantity'];\n\t\t}\n\t} else {\n\t\t$product = $item->get_product();\n\t\tif ( $product && $product->managing_stock() ) { $pools[ $product->get_stock_managed_by_id() ] = array( 'units' => 1, 'strict' => ! $product->backorders_allowed() ); }\n\t}\n\treturn $pools;\n}\n\nfunction genosys_package_add_demand( &$demand, $pools, $quantity ) {\n\tforeach ( $pools as $id => $pool ) {\n\t\t$id = (int) $id;\n\t\tif ( ! isset( $demand[ $id ] ) ) { $demand[ $id ] = array( 'total' => 0, 'strict' => 0 ); }\n\t\t$units = (float) $pool['units'] * $quantity;\n\t\t$demand[ $id ]['total'] += $units;\n\t\tif ( ! empty( $pool['strict'] ) ) { $demand[ $id ]['strict'] += $units; }\n\t}\n}\n\n/** A locking read sees reservations committed while this transaction waited for a pool lock. */\nfunction genosys_package_current_held_stock( $pool, $exclude_order_id ) {\n\t$previous = ! empty( $GLOBALS['genosys_package_read_current_holds'] );\n\t$GLOBALS['genosys_package_read_current_holds'] = true;\n\ttry { return wc_get_held_stock_quantity( $pool, $exclude_order_id ); }\n\tfinally { $GLOBALS['genosys_package_read_current_holds'] = $previous; }\n}\nadd_filter( 'woocommerce_query_for_reserved_stock', function ( $query ) {\n\treturn ! empty( $GLOBALS['genosys_package_read_current_holds'] ) && ! preg_match( '/FOR\\s+UPDATE\\s*$/i', $query ) ? rtrim( $query, \"; \\t\\n\\r\" ) . ' FOR UPDATE' : $query;\n}, 100 );\n\n/** Add/update/cart checks include standalone products and every package sharing the same pool. */\nfunction genosys_package_check_cart_demand( $extra_product = null, $extra_quantity = 0, $exclude_key = '' ) {\n\tif ( ! WC()->cart ) { return true; }\n\t$lines = array(); $has_package = genosys_is_package_product( $extra_product );\n\tforeach ( WC()->cart->get_cart() as $key => $values ) {\n\t\tif ( $key === $exclude_key ) { continue; }\n\t\t$lines[] = array( $values['data'], (float) $values['quantity'] );\n\t\t$has_package = $has_package || genosys_is_package_product( $values['data'] );\n\t}\n\tif ( $extra_product && $extra_quantity > 0 ) { $lines[] = array( $extra_product, (float) $extra_quantity ); }\n\tif ( ! $has_package ) { return true; }\n\t$demand = array();\n\tforeach ( $lines as $line ) {\n\t\tlist( $product, $qty ) = $line;\n\t\tif ( genosys_is_package_product( $product ) ) {\n\t\t\tif ( $qty < 1 || floor( $qty ) !== $qty ) { return new WP_Error( 'package_quantity', 'تعداد پکیج باید عدد صحیح و مثبت باشد.' ); }\n\t\t\ttry { $snapshot = genosys_package_component_snapshot( $product ); } catch ( Exception $error ) { return new WP_Error( 'packa