ount( $old['forbidden'] ) ) { $errors[] = array( 'line'=>$new['forbidden'][0]['line'],'code'=>'unsafe_execution','message'=>'eval و توقف کامپایل جدید در ویرایشگر قابل تأیید نیست.' ); }\n\t$counts = array(); foreach ( $old['calls'] as $call ) { $counts[$call['fingerprint']] = ( $counts[$call['fingerprint']] ?? 0 ) + 1; }\n\t$changed_names = array();\n\tforeach ( $new['definitions'] as $name => $defs ) {\n\t\tif ( count( $defs ) > 1 && count( $defs ) > count( $old['definitions'][$name] ?? array() ) ) { $errors[] = array( 'line'=>$defs[0]['line'],'code'=>'duplicate_function','message'=>'تابع «' . $name . '» بیش از یک بار تعریف شده است.' ); }\n\t\tif ( isset( $old['definitions'][$name] ) ) {\n\t\t\t$before = $old['definitions'][$name][0]; $after = $defs[0]; unset( $before['line'], $after['line'] );\n\t\t\tif ( $before !== $after ) { $changed_names[$name] = true; $errors[] = array( 'line'=>$defs[0]['line'],'code'=>'unsupported_signature','message'=>'تغییر امضا یا نوع بازگشت تابع بدون تحلیل همهٔ ورودی‌ها قابل تأیید نیست؛ ذخیره مسدود است.' ); }\n\t\t} elseif ( function_exists( $name ) ) { $errors[] = array( 'line'=>$defs[0]['line'],'code'=>'duplicate_function','message'=>'نام تابع جدید «' . $name . '» از قبل در محیط فعال استفاده شده است.' ); }\n\t}\n\t$strict = (bool) preg_match( '/declare\\s*\\(\\s*strict_types\\s*=\\s*1\\s*\\)/', $content );\n\t$strict_changed = $strict !== (bool) preg_match( '/declare\\s*\\(\\s*strict_types\\s*=\\s*1\\s*\\)/', $previous );\n\t$call_error_start = count( $errors );\n\tforeach ( $new['calls'] as $call ) {\n\t\t$existing = ! empty( $counts[$call['fingerprint']] );\n\t\tif ( $existing ) { $counts[$call['fingerprint']]--; }\n\t\tif ( ! $existing || $strict_changed || isset( $changed_names[$call['name']] ) ) { $errors = array_merge( $errors, genosys_php_editor_call_errors( $call, $new['definitions'], $strict ) ); }\n\t}\n\t// Compare executable-token skeletons. Only HTML/comments and verified call\n\t// names/literal arguments may differ; unknown expressions never get a pass.\n\t$skeleton = static function( $source_tokens,$model ) {\n\t\t$replace = array(); $omit = array(); $constant_calls = 0;\n\t\tforeach ( $model['calls'] as $call ) {\n\t\t\tif ( 'function' !== $call['kind'] ) { continue; }\n\t\t\t$constant = true; foreach ( $call['arguments'] as $argument ) { if ( ! genosys_php_editor_constant_argument( $argument ) ) { $constant = false; break; } }\n\t\t\tif ( $constant ) {\n\t\t\t\t$constant_calls++;\n\t\t\t\tfor ( $i = $call['start']; $i <= $call['end']; $i++ ) { $omit[$i] = true; }\n\t\t\t\t$before = $source_tokens[$call['start'] - 1] ?? array( 'id'=>0,'text'=>'' );\n\t\t\t\t$after = $source_tokens[$call['end'] + 1] ?? array( 'id'=>0,'text'=>'' );\n\t\t\t\t$statement = ( in_array( $before['id'],array( T_ECHO,T_PRINT,T_OPEN_TAG,T_OPEN_TAG_WITH_ECHO ),true ) || in_array( $before['text'],array( ';','{' ),true ) ) && ( ';' === $after['text'] || T_CLOSE_TAG === $after['id'] );\n\t\t\t\t$replace[$call['start']] = ( $statement ? '@statement:' : '@call:' ) . $call['name']; unset( $omit[$call['start']] );\n\t\t\t\tif ( ';' === ( $source_tokens[$call['end'] + 1]['text'] ?? '' ) ) { $omit[$call['end'] + 1] = true; }\n\t\t\t\tif ( T_ECHO === ( $source_tokens[$call['start'] - 1]['id'] ?? 0 ) || T_PRINT === ( $source_tokens[$call['start'] - 1]['id'] ?? 0 ) ) { $omit[$call['start'] - 1] = true; }\n\t\t\t} else {\n\t\t\t\t$cursor = $call['start'] + 2;\n\t\t\t\tforeach ( $call['arguments'] as $argument ) {\n\t\t\t\t\tif ( genosys_php_editor_constant_argument( $argument ) ) {\n\t\t\t\t\t\t$replace[$cursor] = '@constant-argument';\n\t\t\t\t\t\tfor ( $i = $cursor + 1; $i < $cursor + count( $argument ); $i++ ) { $omit[$i] = true; }\n\t\t\t\t\t}\n\t\t\t\t\t$cursor += count( $argument ) + 1;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\t$result = array();\n\t\tforeach ( $source_tokens as $i => $token ) { if ( T_INLINE_HTML === $token['id'] || isset( $omit[$i] ) ) { continue; } $result[] = $replace[$i] ?? $token['id'] . ':' . $token['text']; }\n\t\treturn array( 'tokens'=>$result,'constantCalls'=>$constant_calls );\n\t};\n\t$old_skeleton = $skeleton( $old_tokens,$old ); $new_skeleton = $skeleton( $tokens,$new );\n\t$old_index = 0;\n\tforeach ( $new_skeleton['tokens'] as $value ) {\n\t\tif ( isset( $old_skeleton['tokens'][$old_index] ) && $value === $old_skeleton['tokens'][$old_index] ) { $old_index++; }\n\t\telseif ( 0 !== strpos( $value,'@statement:' ) ) { $old_index = -1; break; }\n\t}\n\tif ( $old_index !== count( $old_skeleton['tokens'] ) || $new_skeleton['constantCalls'] < $old_skeleton['constantCalls'] ) { $errors[] = array( 'line'=>1,'code'=>'unsupported_expression','message'=>'این تغییر شامل منطق، متغیر، عملگر، ساختار یا عبارت جدیدی است که ایمنی آن به‌صورت ایستا قابل اثبات نیست. فقط تغییر HTML، توضیح و فراخوانی/پارامتر ثابتِ قابل تأیید از این مسیر پذیرفته می‌شود.' ); }\n\t$checks['calls']['status'] = count( $errors ) > $call_error_start ? 'error' : 'ok';\n\t$removed = array_diff( array_keys( $old['definitions'] ), array_keys( $new['definitions'] ) );\n\t$dependency_start = count( $errors );\n\tforeach ( $files as $metadata ) {\n\t\t$path = $metadata['path'];\n\t\ttry { $model = $path === $file ? $new : genosys_php_editor_model( genosys_php_editor_tokens( (string) @file_get_contents( genosys_php_editor_resolve( $path ) ), false ) ); }\n\t\tcatch ( Throwable $error ) { $errors[] = array( 'line'=>1,'code'=>'dependency_unverified','message'=>'خواندن وابستگی‌های «' . $path . '» ممکن نشد.' ); continue; }\n\t\tif ( $path !== $file ) { foreach ( $new['definitions'] as $name => $definition ) { if ( ! isset( $old['definitions'][$name] ) && isset( $model['definitions'][$name] ) ) { $errors[] = array( 'line'=>$definition[0]['line'],'code'=>'duplicate_function','message'=>'نام تابع جدید در «' . $path . '» نیز تعریف شده است.' ); } } }\n\t\tforeach ( $removed as $name ) {\n\t\t\t$referenced = false;\n\t\t\tforeach ( $model['calls'] as $call ) { if ( 'function' === $call['kind'] && $name === $call['name'] ) { $referenced = true; break; } }\n\t\t\tforeach ( $model['literals'] as $literal ) { if ( $name === $literal['value'] ) { $referenced = true; break; } }\n\t\t\tif ( $referenced ) { $errors[] = array( 'line'=>1,'code'=>'removed_dependency','message'=>'تابع حذف‌شدهٔ «' . $name . '» هنوز در «' . $path . '» استفاده می‌شود.' ); }\n\t\t}\n\t\tif ( $path !== $file && $changed_names ) { foreach ( $model['calls'] as $call ) { if ( isset( $changed_names[$call['name']] ) ) { $found = genosys_php_editor_call_errors( $call, $new['definitions'], false ); foreach ( $found as &$item ) { $item['message'] .= ' وابستگی: ' . $path; } unset( $item ); $errors = array_merge( $errors, $found ); } } }\n\t}\n\t$checks['dependencies']['status'] = count( $errors ) > $dependency_start || $removed && $errors ? 'error' : 'ok';\n\t$checks['safety']['status'] = $errors ? 'error' : 'ok';\n\t$checks['safety']['message'] = $errors ? 'تغییر دارای خطا یا ساختار غیرقابل تأیید است؛ ذخیره مسدود می‌ماند.' : 'در تغییرهای تحلیل‌شده، وابستگی یا فراخوانی غیرقابل تأیید شناسایی نشد.';\n\t$notices[] = 'این بررسی اثبات همهٔ مسیرهای اجرایی نیست. آزمون اجرای وردپرس روی مسیرهای بررسی‌شده خطاهای مهلک را گزارش می‌کند؛ همهٔ هشدارها و مسیرهای شرطی پوشش داده نمی‌شوند.';\n\treturn $finish();\n}\n","sha256":"452437f333b18bb28053ce3b1dfa59bf0a48aa27d8af09705472b9e7410802ed"},"inc/php-editor-view.php":{"content":"<?php\n/** Presentation for the PHP source editor. Reads, checks and writes use its API. */\ndefined( 'ABSPATH' ) || exit;\n\n/** Outline icons shared by the source editor controls. */\nfunction genosys_php_editor_icon( $name ) {\n\t$extra = array(\n\t\t'code'   => '<path d=\"m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18\"/>',\n\t\t'eye'    => '<path d=\"M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>',\n\t\t'search' => '<circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 5 5\"/>',\n\t\t'info'   => '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 11v6m0-10v.01\"/>',\n\t\t'check'  => '<path d=\"m5 12 4 4L19 6\"/>',\n\t\t'chevron'=> '<path d=\"m6 9 6 6 6-6\"/>',\n\t);\n\tif ( isset( $extra[ $name ] ) ) {\n\t\treturn '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\">' . $extra[ $name ] . '</svg>';\n\t}\n\treturn function_exists( 'genosys_css_editor_icon' ) ? genosys_css_editor_icon( $name ) : '';\n}\n\n/**\n * Render real theme PHP files, never a sample source or an executable draft.\n *\n * @param array  $files       Source file manifest from the protected editor API.\n * @param string $preview_url Signed read-only front-end preview URL.\n */\nfunction genosys_render_php_editor( $files = array(), $preview_url = '' ) {\n\t$first_file = ! empty( $files[0]['path'] ) ? (string) $files[0]['path'] : '';\n\t$preview_url = $preview_url ?: home_url( '/' );\n\t$groups = array(\n\t\t'root'           => array( 'label' => 'فایل‌های اصلی قالب', 'files' => array() ),\n\t\t'inc'            => array( 'label' => 'inc/', 'files' => array() ),\n\t\t'template-parts' => array( 'label' => 'template-parts/', 'files' => array() ),\n\t\t'woocommerce'    => array( 'label' => 'woocommerce/', 'files' => array() ),\n\t);\n\tforeach ( $files as $file ) {\n\t\t$path = isset( $file['path'] ) ? (string) $file['path'] : '';\n\t\t$folder = strpos( $path, '/' ) !== false ? strtok( $path, '/' ) : 'root';\n\t\t$key = isset( $groups[ $folder ] ) ? $folder : 'root';\n\t\t$groups[ $key ]['files'][] = $file;\n\t}\n\t$checks = array(\n\t\t'syntax'       => 'ساختار و سینتکس',\n\t\t'calls'        => 'توابع و پارامترها',\n\t\t'dependencies' => 'وابستگی فایل‌ها',\n\t\t'safety'       => 'ساختارهای قابل بررسی',\n\t\t'runtime'      => 'بررسی سرور',\n\t);\n\t?>\n\t<div class=\"gsce gspe\" data-php-editor dir=\"rtl\">\n\t\t<header class=\"gsce__heading gspe__heading\">\n\t\t\t<div><h2>ویرایشگر <span lang=\"en\" dir=\"ltr\">PHP</span></h2><p>فایل‌های PHP قالب را ببینید و ویرایش کنید؛ کد پیش از ذخیره بررسی می‌شود.</p></div>\n\t\t\t<span class=\"gsce__save-state\" data-php-save-status role=\"status\" aria-live=\"polite\">در حال بارگذاری فایل‌ها…</span>\n\t\t</header>\n\t\t<div class=\"gsce__message\" data-php-message role=\"status\" aria-live=\"polite\" hidden></div>\n\t\t<div class=\"gsce__message gspe__readonly-note\" data-php-readonly-note role=\"note\" hidden>این فایل محافظت‌شده یا فقط‌خواندنی است؛ کد آن قابل مشاهده است و ذخیره‌سازی آن در دسترس نیست.</div>\n\t\t<div class=\"gspe__workspace\">\n\t\t\t<aside class=\"gsce__files gspe__files\" aria-label=\"فایل‌های PHP قالب\">\n\t\t\t\t<button type=\"button\" class=\"gsce__panel-resize gsce__panel-resize--files gspe__files-resize\" data-php-files-resize aria-label=\"تغییر عرض فهرست فایل‌های PHP با کشیدن لبهٔ چپ\" title=\"لبهٔ چپ را برای تغییر عرض فهرست فایل‌ها بکشید\"><span aria-hidden=\"true\"></span></button>\n\t\t\t\t<h3>فایل‌های PHP قالب</h3>\n\t\t\t\t<label class=\"gspe__search\" for=\"genosys-php-file-search\"><span><?php echo genosys_php_editor_icon( 'search' ); ?></span><input id=\"genosys-php-file-search\" data-php-file-search type=\"search\" placeholder=\"جستجوی فایل…\" aria-label=\"جستجوی فایل PHP\" autocomplete=\"off\"></label>\n\t\t\t\t<div class=\"gsce__file-list gspe__file-list\" role=\"tablist\" aria-label=\"فایل‌های PHP\" aria-orientation=\"vertical\">\n\t\t\t\t\t<?php foreach ( $groups as $group_key => $group ) : if ( empty( $group['files'] ) ) { continue; } ?>\n\t\t\t\t\t\t<div class=\"gspe__file-group\" data-php-group=\"<?php echo esc_attr( $group_key ); ?>\">\n\t\t\t\t\t\t\t<h4<?php echo 'root' !== $group_key ? ' dir=\"ltr\"' : ''; ?>><?php echo esc_html( $group['label'] ); ?></h4>\n\t\t\t\t\t\t\t<?php foreach ( $group['files'] as $file ) :\n\t\t\t\t\t\t\t\t$path = isset( $file['path'] ) ? (string) $file['path'] : '';\n\t\t\t\t\t\t\t\t$label = ! empty( $file['label'] ) ? (string) $file['label'] : basename( $path );\n\t\t\t\t\t\t\t\t$is_current = $path === $first_file;\n\t\t\t\t\t\t\t\t?>\n\t\t\t\t\t\t\t\t<button type=\"button\" class=\"gsce__file gspe__file\" data-php-file=\"<?php echo esc_attr( $path ); ?>\" role=\"tab\" aria-selected=\"<?php echo $is_current ? 'true' : 'false'; ?>\" aria-controls=\"genosys-php-editor-panel\" tabindex=\"<?php echo $is_current ? '0' : '-1'; ?>\" title=\"<?php echo esc_attr( $path ); ?>\">\n\t\t\t\t\t\t\t\t\t<span class=\"gsce__file-icon\"><?php echo genosys_php_editor_icon( 'file' ); ?></span>\n\t\t\t\t\t\t\t\t\t<span class=\"gsce__file-info\"><strong><?php echo esc_html( $label ); ?></strong><code dir=\"ltr\"><?php echo esc_html( $path ); ?></code><?php if ( 'functions.php' === $path ) : ?><small class=\"gspe__file-risk\" title=\"این فایل توابع اصلی قالب را بارگذاری می‌کند\">توابع اصلی قالب</small><?php endif; ?></span>\n\t\t\t\t\t\t\t\t\t<span class=\"gspe__file-diagnostic\" data-php-file-diagnostic data-file-error hidden aria-label=\"نتیجهٔ بررسی فایل\"></span>\n\t\t\t\t\t\t\t\t\t<span class=\"gsce__file-dirty\" data-file-dirty data-php-file-dirty hidden aria-label=\"ذخیره‌نشده\"></span>\n\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t</div>\n\t\t\t\t<p class=\"gspe__empty-files\" data-php-file-empty hidden>فایلی با این نام پیدا نشد.</p>\n\t\t\t\t<div class=\"gsce__help gspe__help\"><p>ذخیره: <kbd>Ctrl</kbd> + <kbd>S</kbd></p><p>تورفتگی: <kbd>Tab</kbd></p><p>پیش‌نویس PHP اجرا نمی‌شود؛ پیش‌نمایش، کد ذخیره‌شدهٔ سایت را نشان می‌دهد.</p></div>\n\t\t\t</aside>\n\n\t\t\t<section class=\"gsce__editor gspe__editor\" id=\"genosys-php-editor-panel\" aria-label=\"ویرایش کد PHP\">\n\t\t\t\t<div class=\"gsce__toolbar gspe__toolbar\">\n\t\t\t\t\t<code class=\"gsce__current-file\" data-php-current-file dir=\"ltr\"><?php echo esc_html( $first_file ); ?></code>\n\t\t\t\t\t<div class=\"gsce__tools\" role=\"group\" aria-label=\"ابزارهای ویرایش کد PHP\">\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"undo\" title=\"واگرد\" aria-label=\"واگرد\"><?php echo genosys_php_editor_icon( 'undo' ); ?></button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"redo\" title=\"از نو\" aria-label=\"از نو\"><?php echo genosys_php_editor_icon( 'redo' ); ?></button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"copy\" title=\"کپی کد\" aria-label=\"کپی کد\"><?php echo genosys_php_editor_icon( 'copy' ); ?></button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"download\" title=\"دانلود فایل PHP\" aria-label=\"دانلود فایل PHP\"><?php echo genosys_php_editor_icon( 'download' ); ?></button>\n\t\t\t\t\t</div>\n\t\t\t\t\t<label class=\"screen-reader-text\" for=\"genosys-php-history\">تاریخچه نسخه‌ها</label><select id=\"genosys-php-history\" class=\"gsce__select\" data-php-history aria-label=\"تاریخچه نسخه‌ها\"><option value=\"\">تاریخچهٔ نسخه‌ها</option></select>\n\t\t\t\t\t<div class=\"gsce__tools\" role=\"group\" aria-label=\"نمایش ویرایشگر PHP\">\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button gsce__font-button\" data-php-action=\"font-decrease\" title=\"کوچک کردن متن\" aria-label=\"کوچک کردن متن\">−A</button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button gsce__font-button\" data-php-action=\"font-increase\" title=\"بزرگ کردن متن\" aria-label=\"بزرگ کردن متن\">+A</button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"wrap\" title=\"شکستن خط‌های بلند\" aria-label=\"شکستن خط‌های بلند\" aria-pressed=\"false\"><?php echo genosys_php_editor_icon( 'wrap' ); ?></button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"theme\" title=\"تغییر روشنایی ویرایشگر\" aria-label=\"تغییر روشنایی ویرایشگر\" aria-pressed=\"false\"><?php echo genosys_php_editor_icon( 'moon' ); ?></button>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"fullscreen\" title=\"تمام‌صفحه کردن ویرایشگر\" aria-label=\"تمام‌صفحه کردن ویرایشگر\" aria-pressed=\"false\"><?php echo genosys_php_editor_icon( 'fullscreen' ); ?></button>\n\t\t\t\t\t</div>\n\t\t\t\t\t<button type=\"button\" class=\"gsce__button gsce__button--reset\" data-php-action=\"reset\" title=\"بازیابی کد اصلی فایل انتخاب‌شده از نسخهٔ نصب‌شده؛ برای اعمال دائمی ذخیره‌سازی را بزنید\">بازنشانی</button>\n\t\t\t\t\t<button type=\"button\" class=\"gsce__button gsce__button--save\" data-php-action=\"save\" title=\"بررسی و ذخیرهٔ فایل انتخاب‌شده\" disabled>ذخیرهٔ تغییرات</button>\n\t\t\t\t</div>\n\t\t\t\t<nav class=\"gspe__tabs\" role=\"tablist\" aria-label=\"کد و پیش‌نمایش\">\n\t\t\t\t\t<button type=\"button\" class=\"gspe__tab\" data-php-tab=\"code\" role=\"tab\" id=\"genosys-php-tab-code\" aria-selected=\"true\" aria-controls=\"genosys-php-code-panel\"><?php echo genosys_php_editor_icon( 'code' ); ?><span>کد</span></button>\n\t\t\t\t\t<button type=\"button\" class=\"gspe__tab\" data-php-tab=\"preview\" role=\"tab\" id=\"genosys-php-tab-preview\" aria-selected=\"false\" aria-controls=\"genosys-php-preview-panel\" tabindex=\"-1\"><?php echo genosys_php_editor_icon( 'eye' ); ?><span>پیش‌نمایش</span></button>\n\t\t\t\t</nav>\n\t\t\t\t<div class=\"gspe__tab-panel\" data-php-tab-panel=\"code\" id=\"genosys-php-code-panel\" role=\"tabpanel\" aria-labelledby=\"genosys-php-tab-code\">\n\t\t\t\t\t<div class=\"gsce__code-area gspe__code-area\"><label class=\"screen-reader-text\" for=\"genosys-php-code\">کد PHP فایل انتخاب‌شده</label><textarea id=\"genosys-php-code\" class=\"gsce__code\" data-php-code dir=\"ltr\" spellcheck=\"false\" autocapitalize=\"off\" autocomplete=\"off\" wrap=\"off\" aria-describedby=\"genosys-php-editor-note\"></textarea></div>\n\t\t\t\t\t<footer class=\"gsce__statusbar\"><span data-php-cursor>سطر ۱، ستون ۱</span><span data-php-validation role=\"status\" aria-live=\"polite\">در انتظار بارگذاری کد</span><span class=\"gsce__status-note\" id=\"genosys-php-editor-note\">پیش‌نویس ذخیره نشده است</span></footer>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"gspe__tab-panel gspe__preview-panel\" data-php-tab-panel=\"preview\" id=\"genosys-php-preview-panel\" role=\"tabpanel\" aria-labelledby=\"genosys-php-tab-preview\" hidden>\n\t\t\t\t\t<section class=\"gsce__preview gspe__preview\" aria-label=\"پیش‌نمایش نسخهٔ ذخیره‌شدهٔ سایت\">\n\t\t\t\t\t\t<header class=\"gsce__preview-heading\"><h3>پیش‌نمایش زنده <small class=\"gspe__saved-site\">کد ذخیره‌شدهٔ سایت</small></h3><div class=\"gsce__tools\" role=\"group\" aria-label=\"اندازه پیش‌نمایش\"><button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"preview-desktop\" aria-label=\"نمایش دسکتاپ\" title=\"نمایش دسکتاپ\" aria-pressed=\"true\"><?php echo genosys_php_editor_icon( 'desktop' ); ?></button><button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"preview-mobile\" aria-label=\"نمایش موبایل\" title=\"نمایش موبایل\" aria-pressed=\"false\"><?php echo genosys_php_editor_icon( 'mobile' ); ?></button><button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"preview-fullscreen\" aria-label=\"نمایش تمام‌عرض پیش‌نمایش\" title=\"نمایش تمام‌عرض\" aria-pressed=\"false\"><?php echo genosys_php_editor_icon( 'fullscreen' ); ?></button></div></header>\n\t\t\t\t\t\t<p class=\"gspe__preview-disclosure\">پیش‌نمایش، نسخهٔ ذخیره‌شدهٔ سایت را نشان می‌دهد. برای دیدن تغییرات PHP، بررسی و ذخیره‌سازی لازم است؛ پیش‌نویس اجرا نمی‌شود.</p>\n\t\t\t\t\t\t<div class=\"gsce__preview-controls gspe__preview-controls\">\n\t\t\t\t\t\t\t<label class=\"screen-reader-text\" for=\"genosys-php-preview-page\">صفحه پیش‌نمایش</label><select id=\"genosys-php-preview-page\" class=\"gsce__select\" data-php-preview-page><option value=\"<?php echo esc_url( home_url( '/' ) ); ?>\">صفحه اصلی</option></select>\n\t\t\t\t\t\t\t<div class=\"gsce__preview-address\"><label class=\"screen-reader-text\" for=\"genosys-php-preview-path\">مسیر صفحه در همین وب‌سایت</label><input id=\"genosys-php-preview-path\" data-php-preview-path type=\"text\" value=\"/\" placeholder=\"/shop/\" dir=\"ltr\" aria-label=\"مسیر صفحه در همین وب‌سایت\"><button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"preview-open\" title=\"نمایش این مسیر\" aria-label=\"نمایش این مسیر\"><?php echo genosys_php_editor_icon( 'arrow' ); ?></button><button type=\"button\" class=\"gsce__icon-button\" data-php-action=\"preview-reload\" title=\"بارگذاری دوباره پیش‌نمایش\" aria-label=\"بارگذاری دوباره پیش‌نمایش\"><?php echo genosys_php_editor_icon( 'reload' ); ?></button></div>\n\t\t\t\t\t\t\t<div class=\"gsce__preview-dimensions\"><label for=\"genosys-php-preview-width\">عرض<input id=\"genosys-php-preview-width\" type=\"number\" min=\"240\" max=\"2560\" step=\"1\" value=\"1440\" data-php-preview-width dir=\"ltr\" inputmode=\"numeric\"><span>px</span></label><span class=\"gsce__dimensions-cross\" aria-hidden=\"true\">×</span><label for=\"genosys-php-preview-height\">ارتفاع<input id=\"genosys-php-preview-height\" type=\"number\" min=\"240\" max=\"1600\" step=\"1\" value=\"900\" data-php-preview-height dir=\"ltr\" inputmode=\"numeric\"><span>px</span></label></div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<p class=\"gsce__preview-note\" data-php-preview-note role=\"status\" aria-live=\"polite\" hidden></p>\n\t\t\t\t\t\t<div class=\"gsce__preview-stage\" data-php-preview-stage><div class=\"gsce__preview-viewport\" data-php-preview-viewport><div class=\"gsce__preview-scale\" data-php-preview-scale><iframe class=\"gsce__preview-frame\" data-php-preview-frame data-preview-src=\"<?php echo esc_url( $preview_url ); ?>\" title=\"پیش‌نمایش نسخهٔ ذخیره‌شدهٔ سایت\" sandbox=\"allow-same-origin allow-scripts\" referrerpolicy=\"same-origin\"></iframe></div><button type=\"button\" class=\"gsce__resize-handle\" data-php-preview-resize aria-label=\"تغییر اندازه پیش‌نمایش با کشیدن\" title=\"برای تغییر اندازه بکشید\"><span aria-hidden=\"true\"></span></button></div></div>\n\t\t\t\t\t\t<p class=\"gsce__preview-hint\">گوشهٔ پایین پیش‌نمایش را بکشید یا اندازهٔ دلخواه را وارد کنید.</p>\n\t\t\t\t\t</section>\n\t\t\t\t</div>\n\n\t\t\t\t<section class=\"gspe__diagnostics\" data-php-diagnostics aria-label=\"نتیجهٔ بررسی کد PHP\">\n\t\t\t\t\t<header class=\"gspe__diagnostics-heading\">\n\t\t\t\t\t\t<div class=\"gspe__validation-state\" data-php-validation-status data-status=\"pending\" role=\"status\" aria-live=\"polite\"><span class=\"gspe__status-icon\" data-php-validation-icon><?php echo genosys_php_editor_icon( 'info' ); ?></span><strong data-php-validation-label>در انتظار بررسی کد</strong></div>\n\t\t\t\t\t\t<div class=\"gspe__counts\"><span>خطا <b data-php-error-count>—</b></span><span>هشدار <b data-php-warning-count>—</b></span></div>\n\t\t\t\t\t\t<button type=\"button\" class=\"gsce__button gspe__validate\" data-php-action=\"validate\">بررسی مجدد</button>\n\t\t\t\t\t</header>\n\t\t\t\t\t<div class=\"gspe__checks\">\n\t\t\t\t\t\t<?php foreach ( $checks as $check_id => $check_label ) : ?>\n\t\t\t\t\t\t\t<div class=\"gspe__check\" data-php-check=\"<?php echo esc_attr( $check_id ); ?>\" data-status=\"pending\"><span class=\"gspe__check-icon\" data-check-icon>…</span><div><strong data-check-title><?php echo esc_html( $check_label ); ?></strong><small data-check-status>در انتظار بررسی</small></div></div>\n\t\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t</div>\n\t\t\t\t\t<div class=\"gspe__summary\" data-php-summary data-status=\"pending\" role=\"status\" aria-live=\"polite\">نتیجهٔ بررسی فایل انتخاب‌شده اینجا نمایش داده می‌شود.</div>\n\t\t\t\t\t<div class=\"gspe__issues\" data-php-issues role=\"list\" aria-label=\"خطاها و هشدارهای کد\"></div>\n\t\t\t\t\t<p class=\"gspe__diagnostic-note\"><?php echo genosys_php_editor_icon( 'info' ); ?><span>نتیجهٔ هر بخش فقط همان بررسی را پوشش می‌دهد. بررسی اجرای سرور هنگام ذخیره انجام می‌شود؛ تا آن زمان وضعیت آن تأییدشده نیست.</span></p>\n\t\t\t\t</section>\n\t\t\t</section>\n\t\t</div>\n\t</div>\n\t<?php\n}\n","sha256":"12c0439a22dcb5cb1ff56a01a4aad51d728e592757cf65137de4bce4fd81005c"},"inc/php-editor.php":{"content":"<?php\n/** Real PHP source editing with conservative analysis and WordPress fatal rollback. */\ndefined( 'ABSPATH' ) || exit;\nrequire_once __DIR__ . '/php-editor-validator.php';\nconst GENOSYS_PHP_EDITOR_BASELINE_VERSION = '1.5.86';\nconst GENOSYS_PHP_EDITOR_BASELINE_PREFIX = \"<?php\\ndefined( 'ABSPATH' ) || exit;\\n__halt_compiler();\\n\";\n\nfunction genosys_php_editor_allowed() {\n\treturn current_user_can( 'manage_options' ) && current_user_can( 'edit_themes' )\n\t\t&& ! ( defined( 'DISALLOW_FILE_EDIT' ) && DISALLOW_FILE_EDIT )\n\t\t&& ! ( defined( 'DISALLOW_FILE_MODS' ) && DISALLOW_FILE_MODS ) && wp_is_file_mod_allowed( 'genosys_php_editor' );\n}\nfunction genosys_php_editor_root() {\n\t$root = realpath( dirname( __DIR__ ) ); $active = realpath( get_template_directory() );\n\treturn $root && $active && wp_normalize_path( $root ) === wp_normalize_path( $active ) ? $root : false;\n}\nfunction genosys_php_editor_resolve( $relative ) {\n\t$root = genosys_php_editor_root();\n\tif ( ! $root || ! is_string( $relative ) || ! preg_match( '#^[A-Za-z0-9_./-]+\\.php$#D', $relative ) || false !== strpos( $relative, '..' ) || false !== strpos( $relative, '//' ) || 0 !== validate_file( $relative ) ) { return false; }\n\t$path = $root;\n\tforeach ( explode( '/', $relative ) as $piece ) { $path .= DIRECTORY_SEPARATOR . $piece; if ( is_link( $path ) ) { return false; } }\n\t$real = realpath( $path );\n\treturn $real && is_file( $real ) && 0 === strpos( wp_normalize_path( $real ), trailingslashit( wp_normalize_path( $root ) ) ) && 'php' === strtolower( pathinfo( $real, PATHINFO_EXTENSION ) ) ? $real : false;\n}\nfunction genosys_php_editor_readonly_reason( $file, $real ) {\n\tif ( preg_match( '#^inc/(?:php|css)-editor(?:-[a-z0-9-]+)?\\.php$#D', $file ) ) { return 'این فایل بخشی از موتور و محافظ ذخیرهٔ ویرایشگر است و برای حفظ امکان بازیابی فقط خواندنی است.'; }\n\tif ( ! genosys_php_editor_allowed() ) { return 'ویرایش فایل‌های قالب برای این حساب یا در تنظیمات امنیتی وردپرس مجاز نیست.'; }\n\tif ( @filesize( $real ) > 1048576 ) { return 'حجم این فایل از سقف یک مگابایت ویرایش امن بیشتر است.'; }\n\tif ( ! is_writable( $real ) || ! is_writable( dirname( $real ) ) ) { return 'فایل یا پوشهٔ آن در میزبان قابل نوشتن نیست.'; }\n\treturn '';\n}\nfunction genosys_php_editor_files() {\n\t$root = genosys_php_editor_root(); $files = array();\n\tif ( ! $root ) { return $files; }\n\ttry {\n\t\t$iterator = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $root, FilesystemIterator::SKIP_DOTS ) );\n\t\tforeach ( $iterator as $entry ) {\n\t\t\tif ( ! $entry->isFile() || $entry->isLink() || 'php' !== strtolower( $entry->getExtension() ) ) { continue; }\n\t\t\t$relative = substr( wp_normalize_path( $entry->getPathname() ), strlen( trailingslashit( wp_normalize_path( $root ) ) ) );\n\t\t\t// This guarded data archive is neither executable theme source nor editable.\n\t\t\tif ( 'inc/php-baseline.php' === $relative ) { continue; }\n\t\t\t$real = genosys_php_editor_resolve( $relative ); if ( ! $real || ! is_readable( $real ) ) { continue; }\n\t\t\t$reason = genosys_php_editor_readonly_reason( $relative, $real );\n\t\t\t$files[] = array( 'path'=>$relative,'label'=>$relative,'scope'=>0 === strpos( $relative, 'inc/' ) ? 'backend' : 'template','readonly'=>'' !== $reason,'readonlyReason'=>$reason );\n\t\t}\n\t} catch ( UnexpectedValueException $error ) { return array(); }\n\tusort( $files, static function( $a, $b ) { if ( 'functions.php' === $a['path'] ) { return -1; } if ( 'functions.php' === $b['path'] ) { return 1; } return strnatcasecmp( $a['path'], $b['path'] ); } );\n\treturn $files;\n}\nfunction genosys_php_editor_bootstrap() {\n\tstatic $editor = null;\n\tif ( null === $editor ) { $editor = genosys_php_editor_allowed() ? wp_enqueue_code_editor( array( 'type'=>'application/x-httpd-php','codemirror'=>array( 'lineNumbers'=>true,'lineWrapping'=>false,'indentUnit'=>4,'tabSize'=>4,'direction'=>'ltr','lint'=>false ) ) ) : false; }\n\t$preview = function_exists( 'genosys_css_editor_preview_url' ) ? genosys_css_editor_preview_url( home_url( '/' ) ) : '';\n\t$pages = array( array( 'label'=>'صفحه اصلی — نسخهٔ ذخیره‌شده','url'=>$preview ) );\n\tforeach ( array( '/shop/'=>'فروشگاه','/fans-club/'=>'باشگاه مشتریان','/my-account/'=>'حساب کاربری' ) as $path => $label ) { if ( function_exists( 'genosys_css_editor_preview_url' ) ) { $pages[] = array( 'label'=>$label . ' — نسخهٔ ذخیره‌شده','url'=>genosys_css_editor_preview_url( home_url( $path ) ) ); } }\n\treturn array( 'ajaxUrl'=>admin_url( 'admin-ajax.php' ),'nonce'=>wp_create_nonce( 'genosys_php_editor' ),'files'=>genosys_php_editor_files(),'codeEditor'=>$editor,'allowed'=>genosys_php_editor_allowed(),'reason'=>genosys_php_editor_allowed() ? '' : 'ویرایش فایل‌های PHP در تنظیمات امنیتی وردپرس یا برای حساب شما غیرفعال است.','maxBytes'=>1048576,'baselineVersion'=>GENOSYS_PHP_EDITOR_BASELINE_VERSION,'previewUrl'=>$preview,'previewPages'=>$pages,'previewMode'=>'saved' );\n}\nfunction genosys_php_editor_error( $code, $message, $status = 400, $extra = array() ) { wp_send_json_error( array_merge( array( 'code'=>$code,'message'=>$message ), $extra ), $status ); }\nfunction genosys_php_editor_request_file( $writable = false ) {\n\tif ( ! genosys_php_editor_allowed() ) { genosys_php_editor_error( 'forbidden','اجازهٔ ویرایش فایل‌های PHP را ندارید.',403 ); }\n\tif ( 'POST' !== ( $_SERVER['REQUEST_METHOD'] ?? '' ) ) { genosys_php_editor_error( 'method','روش درخواست معتبر نیست.',405 ); }\n\t$nonce = isset( $_POST['nonce'] ) && is_string( $_POST['nonce'] ) ? wp_unslash( $_POST['nonce'] ) : '';\n\tif ( ! wp_verify_nonce( $nonce, 'genosys_php_editor' ) ) { genosys_php_editor_error( 'nonce','نشست منقضی شده است؛ صفحه را دوباره باز کنید.',403 ); }\n\t$file = isset( $_POST['file'] ) && is_string( $_POST['file'] ) ? wp_unslash( $_POST['file'] ) : '';\n\t$files = genosys_php_editor_files(); $real = in_array( $file, wp_list_pluck( $files, 'path' ), true ) ? genosys_php_editor_resolve( $file ) : false;\n\tif ( ! $real ) { genosys_php_editor_error( 'file','فایل PHP در قالب فعال در دسترس نیست.' ); }\n\tif ( $writable && ( $reason = genosys_php_editor_readonly_reason( $file, $real ) ) ) { genosys_php_editor_error( 'readonly',$reason,403 ); }\n\treturn array( $file,$real,$files );\n}\nfunction genosys_php_editor_history_key( $file ) { return 'genosys_php_history_' . md5( wp_normalize_path( (string) genosys_php_editor_root() ) . '|' . $file ); }\nfunction genosys_php_editor_revisions( $file ) { $rows = get_option( genosys_php_editor_history_key( $file ), array() ); return is_array( $rows ) ? array_slice( $rows, 0, 5 ) : array(); }\nfunction genosys_php_editor_history_summary( $file, $current = '' ) {\n\t$result = array();\n\tforeach ( genosys_php_editor_revisions( $file ) as $row ) { if ( isset( $row['id'],$row['content'],$row['hash'],$row['date'] ) ) { $result[] = array( 'id'=>$row['id'],'date'=>$row['date'],'hash'=>$row['hash'],'user'=>$row['user'] ?? '','bytes'=>strlen( $row['content'] ),'current'=>$current === $row['hash'] ); } }\n\treturn $result;\n}\nfunction genosys_php_editor_remember( $file, $content ) {\n\t$rows = genosys_php_editor_revisions( $file ); $hash = hash( 'sha256', $content );\n\tforeach ( $rows as $row ) { if ( ( $row['hash'] ?? '' ) === $hash ) { return true; } }\n\t$user = wp_get_current_user(); array_unshift( $rows, array( 'id'=>wp_generate_uuid4(),'date'=>gmdate( 'c' ),'hash'=>$hash,'user'=>sanitize_text_field( $user->display_name ),'content'=>$content ) );\n\t$rows = array_slice( $rows,0,5 ); $key = genosys_php_editor_history_key( $file ); update_option( $key,$rows,false ); return get_option( $key ) === $rows;\n}\nfunction genosys_php_editor_payload( $file, $real, $content = null ) {\n\tif ( null === $content ) { $content = @file_get_contents( $real ); }\n\tif ( false === $content ) { genosys_php_editor_error( 'read','خواندن فایل ممکن نیست.',500 ); }\n\t$hash = hash( 'sha256',$content ); $reason = genosys_php_editor_readonly_reason( $file,$real ); clearstatcache( true,$real );\n\treturn array( 'file'=>$file,'content'=>$content,'hash'=>$hash,'bytes'=>strlen( $content ),'modified'=>(int) @filemtime( $real ),'readonly'=>'' !== $reason,'readonlyReason'=>$reason,'history'=>genosys_php_editor_history_summary( $file,$hash ) );\n}\nfunction genosys_php_editor_read() { list( $file,$real ) = genosys_php_editor_request_file(); wp_send_json_success( genosys_php_editor_payload( $file,$real ) ); }\nadd_action( 'wp_ajax_genosys_php_editor_read','genosys_php_editor_read' );\nfunction genosys_php_editor_history() { list( $file,$real ) = genosys_php_editor_request_file(); wp_send_json_success( array( 'file'=>$file,'history'=>genosys_php_editor_history_summary( $file,(string) @hash_file( 'sha256',$real ) ) ) ); }\nadd_action( 'wp_ajax_genosys_php_editor_history','genosys_php_editor_history' );\nfunction genosys_php_editor_revision() {\n\tlist( $file ) = genosys_php_editor_request_file(); $id = isset( $_POST['revision'] ) && is_string( $_POST['revision'] ) ? wp_unslash( $_POST['revision'] ) : '';\n\tforeach ( genosys_php_editor_revisions( $file ) as $row ) { if ( isset( $row['id'] ) && hash_equals( (string) $row['id'],$id ) ) { wp_send_json_success( array( 'file'=>$file,'id'=>$id,'content'=>$row['content'],'hash'=>$row['hash'],'date'=>$row['date'] ) ); } }\n\tgenosys_php_editor_error( 'revision','نسخهٔ درخواستی در تاریخچهٔ این فایل نیست.',404 );\n}\nadd_action( 'wp_ajax_genosys_php_editor_revision','genosys_php_editor_revision' );\nfunction genosys_php_editor_original() {\n\tlist( $file,$real ) = genosys_php_editor_request_file(); $root = genosys_php_editor_root(); $path = $root . '/inc/php-baseline.php'; $canonical = realpath( $path );\n\tif ( is_link( $root . '/inc' ) || is_link( $path ) || ! $canonical || ! is_file( $canonical ) || wp_normalize_path( $canonical ) !== wp_normalize_path( $path ) || ! is_readable( $canonical ) || @filesize( $canonical ) > 16777216 ) { genosys_php_editor_error( 'baseline','نسخهٔ اصلی PHP بستهٔ نصب‌شده در دسترس نیست.',500 ); }\n\t$archive = @file_get_contents( $canonical );\n\tif ( ! is_string( $archive ) || 0 !== strpos( $archive,GENOSYS_PHP_EDITOR_BASELINE_PREFIX ) ) { genosys_php_editor_error( 'baseline_container','قالب محافظت‌شدهٔ نسخهٔ اصلی PHP معتبر نیست.',500 ); }\n\t// Read the archive only. It must never be included, required or evaluated.\n\t$baseline = json_decode( substr( $archive,strlen( GENOSYS_PHP_EDITOR_BASELINE_PREFIX ) ),true,16 );\n\tif ( ! is_array( $baseline ) || JSON_ERROR_NONE !== json_last_error() || ( $baseline['version'] ?? '' ) !== GENOSYS_PHP_EDITOR_BASELINE_VERSION ) { genosys_php_editor_error( 'baseline_version','نسخهٔ اصلی PHP با بستهٔ نصب‌شده هماهنگ نیست.',500 ); }\n\t$entry = $baseline['files'][$file] ?? null;\n\tif ( ! is_array( $entry ) || ! isset( $entry['content'],$entry['sha256'] ) || ! is_string( $entry['content'] ) || ! is_string( $entry['sha256'] ) || strlen( $entry['content'] ) > 1048576 || ! preg_match( '/^[a-f0-9]{64}$/D',$entry['sha256'] ) || ! hash_equals( $entry['sha256'],hash( 'sha256',$entry['content'] ) ) ) { genosys_php_editor_error( 'baseline_content','نسخهٔ اصلی این فایل PHP معتبر نیست.',500 ); }\n\twp_send_json_success( array( 'file'=>$file,'content'=>$entry['content'],'originalHash'=>$entry['sha256'],'installedVersion'=>$baseline['version'],'current'=>genosys_php_editor_payload( $file,$real ) ) );\n}\nadd_action( 'wp_ajax_genosys_php_editor_original','genosys_php_editor_original' );\nfunction genosys_php_editor_content() {\n\tif ( ! isset( $_POST['content'],$_POST['hash'] ) || ! is_string( $_POST['content'] ) || ! is_string( $_POST['hash'] ) ) { genosys_php_editor_error( 'content','کد و نسخهٔ فعلی فایل را بارگذاری کنید.' ); }\n\t$content = wp_unslash( $_POST['content'] ); $hash = wp_unslash( $_POST['hash'] );\n\tif ( strlen( $content ) > 1048576 || false !== strpos( $content,\"\\0\" ) || ! preg_match( '//u',$content ) || ! preg_match( '/^[a-f0-9]{64}$/D',$hash ) ) { genosys_php_editor_error( 'content','کد UTF-8 با حجم حداکثر یک مگابایت و نسخهٔ معتبر فایل لازم است.' ); }\n\treturn array( $content,$hash );\n}\nfunction genosys_php_editor_validate() {\n\tlist( $file,$real,$files ) = genosys_php_editor_request_file(); list( $content,$expected ) = genosys_php_editor_content(); $previous = @file_get_contents( $real );\n\tif ( false === $previous || ! hash_equals( hash( 'sha256',$previous ),$expected ) ) { genosys_php_editor_error( 'conflict','نسخهٔ فایل در سرور تغییر کرده است؛ دوباره آن را بارگذاری کنید.',409 ); }\n\t$validation = genosys_php_editor_validate_source( $file,$content,$previous,$files );\n\t$reason = genosys_php_editor_readonly_reason( $file,$real );\n\twp_send_json_success( array( 'validation'=>$validation,'readonly'=>'' !== $reason,'readonlyReason'=>$reason ) );\n}\nadd_action( 'wp_ajax_genosys_php_editor_validate','genosys_php_editor_validate' );\n\nfunction genosys_php_editor_lock() {\n\t$directory = realpath( get_temp_dir() ); if ( ! $directory ) { return false; }\n\t$path = $directory . DIRECTORY_SEPARATOR . 'genosys-php-' . hash( 'sha256',ABSPATH . '|' . genosys_php_editor_root() ) . '.lock';\n\tif ( is_link( $path ) || ( file_exists( $path ) && ! is_file( $path ) ) ) { return false; }\n\t$handle = @fopen( $path,'c+b' ); if ( ! $handle ) { return false; }\n\tif ( is_link( $path ) || ! @flock( $handle,LOCK_EX | LOCK_NB ) ) { fclose( $handle ); return false; }\n\treturn $handle;\n}\n\n/** Parse the real WordPress shutdown scrape marker; HTTP success alone is insufficient. */\nfunction genosys_php_editor_probe( $file, $settings_only = false ) {\n\t$key = md5( wp_generate_uuid4() . wp_rand() ); $nonce = (string) wp_rand(); $transient = 'scrape_key_' . $key;\n\tset_transient( $transient,$nonce,60 );\n\tif ( get_transient( $transient ) !== $nonce ) { return new WP_Error( 'runtime_unavailable','ساخت نشست آزمون مستقل سرور ممکن نیست؛ ذخیره مسدود است.' ); }\n\t$params = array( 'wp_scrape_key'=>$key,'wp_scrape_nonce'=>$nonce );\n\t$urls = $settings_only ? array( admin_url( 'admin.php?page=genosys-theme-settings' ) ) : array( add_query_arg( array( 'theme'=>get_template(),'file'=>$file ),admin_url( 'theme-editor.php' ) ),home_url( '/' ) );\n\t$cookies = wp_unslash( $_COOKIE ); $headers = array( 'Cache-Control'=>'no-cache' );\n\tif ( isset( $_SERVER['PHP_AUTH_USER'],$_SERVER['PHP_AUTH_PW'] ) ) { $headers['Authorization']='Basic ' . base64_encode( wp_unslash( $_SERVER['PHP_AUTH_USER'] ) . ':' . wp_unslash( $_SERVER['PHP_AUTH_PW'] ) ); }\n\tif ( function_exists( 'session_status' ) && PHP_SESSION_ACTIVE === session_status() ) { session_write_close(); }\n\ttry {\n\t\tforeach ( $urls as $index => $url ) {\n\t\t\t$response = wp_remote_get( add_query_arg( $params,$url ),array( 'cookies'=>$cookies,'headers'=>$headers,'timeout'=>12,'sslverify'=>apply_filters( 'https_local_ssl_verify',false ) ) );\n\t\t\t$body = wp_remote_retrieve_body( $response ); $start = \"###### wp_scraping_result_start:$key ######\"; $end = \"###### wp_scraping_result_end:$key ######\";\n\t\t\t$position = strpos( $body,$start );\n\t\t\tif ( is_wp_error( $response ) || 200 !== (int) wp_remote_retrieve_response_code( $response ) || false === $position ) { return new WP_Error( 'runtime_unavailable','ارتباط آزمون واقعی با سایت برقرار نشد؛ هیچ ذخیرهٔ تأییدنشده‌ای مجاز نیست.' ); }\n\t\t\t$output = substr( $body,$position + strlen( $start ) ); $finish = strpos( $output,$end ); $result = false === $finish ? null : json_decode( trim( substr( $output,0,$finish ) ),true );\n\t\t\tif ( true !== $result ) { return new WP_Error( 'runtime_error','آزمون واقعی سرور خطای PHP گزارش کرد.',is_array( $result ) ? $result : array() ); }\n\t\t\tif ( ( $settings_only && false === strpos( $body,'gs-settings' ) ) || ( ! $settings_only && 0 === $index && false === strpos( $body,'id=\"template\"' ) ) ) { return new WP_Error( 'runtime_auth','صفحهٔ واقعی مدیر در آزمون قابل تأیید نیست؛ ذخیره مسدود است.' ); }\n\t\t}\n\t} finally { delete_transient( $transient ); }\n\treturn true;\n}\n\n/** Atomic full-file replacement used only for a verified backup or rollback. */\nfunction genosys_php_editor_restore( $real, $content ) {\n\t$temp = @tempnam( dirname( $real ),'.genosys-php-' );\n\tif ( ! $temp || wp_normalize_path( dirname( $temp ) ) !== wp_normalize_path( dirname( $real ) ) ) { if ( $temp ) { @unlink( $temp ); } return false; }\n\t$written = @file_put_contents( $temp,$content,LOCK_EX );\n\t$valid = strlen( $content ) === $written && hash( 'sha256',$content ) === @hash_file( 'sha256',$temp );\n\tif ( $valid && is_file( $real ) ) { @chmod( $temp,fileperms( $real ) & 0777 ); }\n\t$done = $valid && @rename( $temp,$real ); if ( ! $done ) { @unlink( $temp ); }\n\tif ( $done ) { clearstatcache( true,$real ); if ( function_exists( 'wp_opcache_invalidate' ) ) { wp_opcache_invalidate( $real,true ); } }\n\treturn $done && hash( 'sha256',$content ) === @hash_file( 'sha256',$real );\n}\n\n/** Never overwrite unrelated bytes installed by an external writer during probes. */\nfunction genosys_php_editor_restore_owned( $file,$real,$previous,$candidate ) {\n\tif ( $real !== genosys_php_editor_resolve( $file ) ) { return false; }\n\t$current = @file_get_contents( $real );\n\tif ( false === $current ) { return false; }\n\tif ( hash_equals( hash( 'sha256',$previous ),hash( 'sha256',$current ) ) ) { return true; }\n\tif ( $current !== $candidate && substr( $candidate,0,strlen( $current ) ) !== $current ) { return false; }\n\treturn genosys_php_editor_restore( $real,$previous );\n}\n\nfunction genosys_php_editor_save() {\n\tlist( $file,$real,$files ) = genosys_php_editor_request_file( true ); list( $content,$expected ) = genosys_php_editor_content();\n\t$lock = genosys_php_editor_lock(); if ( ! $lock ) { genosys_php_editor_error( 'busy','ذخیرهٔ PHP دیگری در حال بررسی است؛ بعداً دوباره تلاش کنید.',409 ); }\n\t$error = null; $payload = null; $previous = null; $confirmed = false; $may_have_written = false;\n\ttry {\n\t\tif ( $real !== genosys_php_editor_resolve( $file ) ) { throw new RuntimeException( 'path' ); }\n\t\t$previous = @file_get_contents( $real );\n\t\tif ( false === $previous || ! hash_equals( hash( 'sha256',$previous ),$expected ) ) { $error = array( 'conflict','نسخهٔ فایل در سرور تغییر کرده است؛ دوباره آن را بارگذاری کنید.',409,array() ); }\n\t\telse {\n\t\t\t$validation = genosys_php_editor_validate_source( $file,$content,$previous,$files );\n\t\t\tif ( ! $validation['valid'] ) { $error = array( 'validation','کد دارای خطا یا تغییر غیرقابل تأیید است؛ فایل ذخیره نشد.',422,array( 'validation'=>$validation ) ); }\n\t\t\telseif ( $previous === $content ) { $payload = genosys_php_editor_payload( $file,$real,$content ); $payload['validation']=$validation; $confirmed=true; }\n\t\t\telse {\n\t\t\t\tif ( ! function_exists( 'wp_edit_theme_plugin_file' ) ) { require_once ABSPATH . 'wp-admin/includes/file.php'; }\n\t\t\t\tif ( ! function_exists( 'wp_edit_theme_plugin_file' ) ) { throw new RuntimeException( 'native_unavailable' ); }\n\t\t\t\t$preflight = genosys_php_editor_probe( $file );\n\t\t\t\tif ( is_wp_error( $preflight ) ) {\n\t\t\t\t\t$validation['valid']=false;\n\t\t\t\t\t$validation['errors'][]=array( 'line'=>1,'code'=>'runtime_unavailable','message'=>$preflight->get_error_message() );\n\t\t\t\t\tforeach ( $validation['checks'] as &$check ) { if ( 'runtime' === $check['id'] ) { $check['status']='unsupported'; $check['message']=$preflight->get_error_message(); } } unset( $check );\n\t\t\t\t\t$error = array( $preflight->get_error_code(),$preflight->get_error_message(),503,array( 'validation'=>$validation ) );\n\t\t\t\t}\n\t\t\t\telseif ( ! genosys_php_editor_remember( $file,$previous ) ) { throw new RuntimeException( 'backup' ); }\n\t\t\t\telseif ( $real !== genosys_php_editor_resolve( $file ) || ! hash_equals( $expected,(string) @hash_file( 'sha256',$real ) ) ) { $error = array( 'conflict','فایل هنگام بررسی تغییر کرده است؛ ذخیره انجام نشد.',409,array() ); }\n\t\t\t\telse {\n\t\t\t\t\t// Keep a verified old snapshot and recover if this request dies mid-guard.\n\t\t\t\t\t$may_have_written = true;\n\t\t\t\t\tregister_shutdown_function( static function() use ( &$confirmed,&$may_have_written,$real,$previous,$content,$file ) {\n\t\t\t\t\t\tif ( ! $confirmed && $may_have_written ) { genosys_php_editor_restore_owned( $file,$real,$previous,$content ); }\n\t\t\t\t\t} );\n\t\t\t\t\t$result = wp_edit_theme_plugin_file( array( 'file'=>$file,'theme'=>get_template(),'newcontent'=>$content,'nonce'=>wp_create_nonce( 'edit-theme_' . get_template() . '_' . $file ) ) );\n\t\t\t\t\tif ( true === $result ) { $result = genosys_php_editor_probe( $file,true ); }\n\t\t\t\t\tif ( true !== $result || hash( 'sha256',$content ) !== @hash_file( 'sha256',$real ) ) {\n\t\t\t\t\t\t$restored = genosys_php_editor_restore_owned( $file,$real,$previous,$content ); $may_have_written = ! $restored;\n\t\t\t\t\t\t$data = is_wp_error( $result ) ? $result->get_error_data() : array();\n\t\t\t\t\t\t$validation['valid']=false; $validation['errors'][]=array( 'line'=>is_array( $data ) ? (int) ( $data['line'] ?? 1 ) : 1,'code'=>'runtime','message'=>is_wp_error( $result ) ? $result->get_error_message() : 'نتیجهٔ ذخیرهٔ سرور قابل تأیید نیست.' );\n\t\t\t\t\t\tforeach ( $validation['checks'] as &$check ) { if ( 'runtime' === $check['id'] ) { $check['status']='error'; $check['message']='آزمون اجرای واقعی ناموفق بود؛ تغییر تأیید نشد.'; } } unset( $check );\n\t\t\t\t\t\t$error = array( $restored ? 'runtime_rollback' : 'recovery_required',$restored ? 'تغییر به‌دلیل خطای اجرای PHP یا آزمون ناموفق رد شد؛ کد قبلی بازیابی شد.' : 'بازیابی خودکار کامل نشد؛ از تاریخچه و دسترسی میزبان برای بازیابی فایل استفاده کنید.',500,array( 'validation'=>$validation,'restored'=>$restored ) );\n\t\t\t\t\t} else {\n\t\t\t\t\t\t$confirmed=true; $may_have_written=false;\n\t\t\t\t\t\t$validation['runtimeVerified']=true; $validation['scope']='تجزیه و بررسی محافظه‌کارانهٔ تغییرها، به‌علاوهٔ اجرای واقعی صفحهٔ اصلی، ویرایشگر مدیر وردپرس و تنظیمات قالب؛ همهٔ مسیرهای شرطی پوشش داده نشده‌اند.';\n\t\t\t\t\t\tforeach ( $validation['checks'] as &$check ) { if ( 'runtime' === $check['id'] ) { $check['status']='ok'; $check['message']='صفحهٔ اصلی، ویرایشگر مدیر و تنظیمات قالب در آزمون واقعی بدون خطای مهلک اجرا شدند.'; } } unset( $check );\n\t\t\t\t\t\t$remembered = genosys_php_editor_remember( $file,$content ); $payload = genosys_php_editor_payload( $file,$real,$content ); $payload['validation']=$validation;\n\t\t\t\t\t\tif ( ! $remembered ) { $payload['historyWarning']='فایل تأیید و ذخیره شد؛ ثبت نسخهٔ جدید در تاریخچه ممکن نشد.'; }\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t} catch ( Throwable $exception ) {\n\t\t$restored = ! $may_have_written || null === $previous || genosys_php_editor_restore_owned( $file,$real,$previous,$content );\n\t\t$may_have_written = ! $restored;\n\t\t$error = array( $restored ? 'server_guard' : 'recovery_required',$restored ? 'ذخیرهٔ محافظت‌شده کامل نشد؛ کد قبلی حفظ یا بازیابی شد.' : 'بازیابی خودکار کامل نشد؛ فایل را از تاریخچه یا میزبان بازیابی کنید.',500,array( 'restored'=>$restored ) );\n\t} finally { @flock( $lock,LOCK_UN ); fclose( $lock ); }\n\tif ( $error ) { genosys_php_editor_error( $error[0],$error[1],$error[2],$error[3] ); }\n\twp_send_json_success( $payload );\n}\nadd_action( 'wp_ajax_genosys_php_editor_save','genosys_php_editor_save' );\n","sha256":"5ed348dabd7e89c3ae055894580fcb0945cdf37869a328a8f528fd44571a953d"},"inc/product-search.php":{"content":"<?php\n/** Product-name and SKU search layered onto WooCommerce's native main query. */\ndefined( 'ABSPATH' ) || exit;\n\n/** Generic WordPress searches, secondary queries and feeds are left alone. */\nfunction genosys_is_product_search( $query = null ) {\n\tif ( null === $query ) {\n\t\tglobal $wp_query;\n\t\t$query = $wp_query;\n\t}\n\tif ( is_admin() || ! $query instanceof WP_Query || ! $query->is_main_query() || ! $query->is_search() || $query->is_feed() || ! function_exists( 'wc_get_product' ) ) {\n\t\treturn false;\n\t}\n\t$post_type = $query->get( 'post_type' );\n\treturn 'product' === $post_type || array( 'product' ) === $post_type;\n}\n\n/** Normalize the same Persian/Arabic letters and digits in input and database values. */\nfunction genosys_product_search_character_map() {\n\treturn array(\n\t\t'ي' => 'ی', 'ى' => 'ی', 'ك' => 'ک', '‌' => ' ',\n\t\t'۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',\n\t\t'۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',\n\t\t'٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',\n\t\t'٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',\n\t);\n}\n\n/** Public template contract: a safe, bounded query string, including the value \"0\". */\nfunction genosys_product_search_term( $query = null ) {\n\tif ( null === $query ) {\n\t\tglobal $wp_query;\n\t\t$query = $wp_query;\n\t}\n\t$value = $query instanceof WP_Query ? $query->get( 's' ) : '';\n\tif ( ! is_scalar( $value ) || is_bool( $value ) ) {\n\t\treturn '';\n\t}\n\t$value = strtr( sanitize_text_field( (string) $value ), genosys_product_search_character_map() );\n\t$value = trim( (string) preg_replace( '/\\s+/u', ' ', $value ) );\n\treturn function_exists( 'mb_substr' ) ? mb_substr( $value, 0, 160, 'UTF-8' ) : wp_html_excerpt( $value, 160, '' );\n}\n\nfunction genosys_product_search_prepare_query( $query ) {\n\tif ( ! genosys_is_product_search( $query ) ) {\n\t\treturn;\n\t}\n\t$query->set( 's', genosys_product_search_term( $query ) );\n\t// Even an administrator's public search must not expose private or draft products.\n\t$query->set( 'post_status', 'publish' );\n\t$query->set( 'genosys_product_search', true );\n}\nadd_action( 'pre_get_posts', 'genosys_product_search_prepare_query', 2 );\n\n/** The expression and aliases are internal constants; every replacement is prepared. */\nfunction genosys_product_search_normalized_sql( $expression, $needle ) {\n\tglobal $wpdb;\n\tforeach ( genosys_product_search_character_map() as $from => $to ) {\n\t\t// Avoid extra SQL functions for characters that cannot affect this search.\n\t\tif ( false !== strpos( $needle, (string) $to ) ) {\n\t\t\t$expression = $wpdb->prepare( \"REPLACE({$expression}, %s, %s)\", $from, $to ); // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared -- Internal SQL expression only.\n\t\t}\n\t}\n\treturn $expression;\n}\n\n/** EXISTS keeps one result per parent and lets Woo retain its native pagination. */\nfunction genosys_product_search_sql( $query ) {\n\tglobal $wpdb;\n\t$term = genosys_product_search_term( $query );\n\tif ( '' === $term ) {\n\t\treturn '0 = 1';\n\t}\n\t$title_terms = preg_split( '/\\s+/u', $term, -1, PREG_SPLIT_NO_EMPTY );\n\t$title_sql = array();\n\tforeach ( $title_terms as $word ) {\n\t\t$title = genosys_product_search_normalized_sql( \"{$wpdb->posts}.post_title\", $word );\n\t\t$title_sql[] = $wpdb->prepare( \"{$title} LIKE %s\", '%' . $wpdb->esc_like( $word ) . '%' ); // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared -- Prepared expression.\n\t}\n\t$sku_like = '%' . $wpdb->esc_like( $term ) . '%';\n\t$product_sku = genosys_product_search_normalized_sql( 'genosys_product_sku.sku', $term );\n\t$variation_sku = genosys_product_search_normalized_sql( 'genosys_variation_sku.sku', $term );\n\t$variation_stock = 'yes' === get_option( 'woocommerce_hide_out_of_stock_items' ) ? \" AND genosys_variation_sku.stock_status <> 'outofstock'\" : '';\n\t$sku_sql = $wpdb->prepare(\n\t\t\"EXISTS (SELECT 1 FROM {$wpdb->wc_product_meta_lookup} AS genosys_product_sku\n\t\t\tWHERE genosys_product_sku.product_id = {$wpdb->posts}.ID AND {$product_sku} LIKE %s)\n\t\tOR EXISTS (SELECT 1 FROM {$wpdb->posts} AS genosys_variation\n\t\t\tINNER JOIN {$wpdb->wc_product_meta_lookup} AS genosys_variation_sku ON genosys_variation_sku.product_id = genosys_variation.ID\n\t\t\tWHERE genosys_variation.post_parent = {$wpdb->posts}.ID\n\t\t\tAND genosys_variation.post_type = 'product_variation' AND genosys_variation.post_status = 'publish'\n\t\t\tAND {$variation_sku} LIKE %s{$variation_stock})\", // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared -- Internal identifiers and prepared expressions.\n\t\t$sku_like,\n\t\t$sku_like\n\t);\n\t$sql = '((' . implode( ' AND ', $title_sql ) . ') OR (' . $sku_sql . '))';\n\tif ( ! is_user_logged_in() ) {\n\t\t$sql .= \" AND ({$wpdb->posts}.post_password = '')\";\n\t}\n\treturn $sql;\n}\n\nfunction genosys_product_search_posts_search( $search, $query ) {\n\tif ( ! genosys_is_product_search( $query ) || ! $query->get( 'genosys_product_search' ) ) {\n\t\treturn $search;\n\t}\n\treturn ' AND (' . genosys_product_search_sql( $query ) . ') ';\n}\nadd_filter( 'posts_search', 'genosys_product_search_posts_search', 20, 2 );\n\n/** Woo's price widget rebuilds text search; keep its aggregate consistent with SKU results. */\nfunction genosys_product_search_price_filter_sql( $sql ) {\n\tglobal $wpdb;\n\tif ( ! class_exists( 'WC_Query' ) ) {\n\t\treturn $sql;\n\t}\n\t$query = WC_Query::get_main_query();\n\tif ( ! $query instanceof WP_Query || ! genosys_is_product_search( $query ) || ! $query->get( 'genosys_product_search' ) ) {\n\t\treturn $sql;\n\t}\n\t$native_search = WC_Query::get_main_search_query_sql();\n\tif ( '' !== $native_search ) {\n\t\treturn str_replace( ' AND ' . $native_search, ' AND (' . genosys_product_search_sql( $query ) . ')', $sql );\n\t}\n\t// Empty searches have no native fragment; insert the restriction into the parent subquery.\n\t$publish_clause = \"AND {$wpdb->posts}.post_status = 'publish'\";\n\treturn str_replace( $publish_clause, $publish_clause . ' AND (' . genosys_product_search_sql( $query ) . ')', $sql );\n}\nadd_filter( 'woocommerce_price_filter_sql', 'genosys_product_search_price_filter_sql', 20, 1 );\n\n/** Keep a single match on the same search-results page as larger result sets. */\nfunction genosys_product_search_single_result_redirect( $redirect ) {\n\treturn genosys_is_product_search() ? false : $redirect;\n}\nadd_filter( 'woocommerce_redirect_single_search_result', 'genosys_product_search_single_result_redirect', 20, 1 );\n","sha256":"9fc65455c47b2965187b670fe37811d82380dbf8271f8f266aede353ebbd43f8"},"inc/products.php":{"content":"<?php\n/** Product presentation helpers. WooCommerce remains the only product source. */\nif ( ! defined( 'ABSPATH' ) ) { exit; }\n\nfunction genosys_latest_products() {\n    if ( ! function_exists( 'wc_get_products' ) ) {\n        return array();\n    }\n    // Query product objects through WooCommerce's data store; never duplicate catalog data.\n    $query = array(\n        'status' => 'publish',\n        'limit' => max( 1, min( 24, (int) genosys_site_setting( 'latest_count', 8 ) ) ),\n        'orderby' => 'date',\n        'order' => 'DESC',\n        'return' => 'objects',\n        'visibility' => 'catalog',\n    );\n    if ( 'yes' === get_option( 'woocommerce_hide_out_of_stock_items' ) ) {\n        $query['stock_status'] = array( 'instock', 'onbackorder' );\n    }\n    return wc_get_products( $query );\n}\n\nfunction genosys_product_discount( $product ) {\n    if ( ! $product->is_on_sale() ) { return 0; }\n    // A variable/grouped product can have different discounts: show a truthful sale label.\n    if ( ! $product->is_type( array( 'simple', 'external', 'genosys_package' ) ) ) { return 0; }\n    $regular = (float) $product->get_regular_price();\n    $current = (float) $product->get_price();\n    return $regular > 0 && $current < $regular ? (int) round( 100 * ( $regular - $current ) / $regular ) : 0;\n}\n\nfunction genosys_persian_number( $number ) {\n    return strtr( (string) $number, array( '0'=>'۰', '1'=>'۱', '2'=>'۲', '3'=>'۳', '4'=>'۴', '5'=>'۵', '6'=>'۶', '7'=>'۷', '8'=>'۸', '9'=>'۹' ) );\n}\n\nfunction genosys_product_price_html( $product ) {\n    // Localize visible numerals only; retain WooCommerce prices, currencies and markup.\n    $parts = wp_html_split( $product->get_price_html() );\n    foreach ( $parts as $index => $part ) {\n        if ( '' !== $part && '<' !== $part[0] ) {\n            $parts[ $index ] = esc_html( genosys_persian_number( html_entity_decode( $part, ENT_QUOTES, 'UTF-8' ) ) );\n        }\n    }\n    return implode( '', $parts );\n}\n","sha256":"4297e425ff9e1f50d167cb3e5733aa6d793cb64adcd0958093dda68fa09ea3fe"},"inc/receipt-admin.php":{"content":"<?php\r\n/** Private payment receipts in the WordPress dashboard. */\r\ndefined( 'ABSPATH' ) || exit;\r\n\r\n/** Both administrators and WooCommerce store managers may review receipts. */\r\nfunction genosys_receipts_admin_capability() {\r\n\treturn function_exists( 'WC' ) && current_user_can( 'manage_woocommerce' ) ? 'manage_woocommerce' : 'manage_options';\r\n}\r\n\r\nfunction genosys_receipts_add_admin_page() {\r\n\tadd_menu_page(\r\n\t\t'فیش های واریزی',\r\n\t\t'فیش های واریزی',\r\n\t\tgenosys_receipts_admin_capability(),\r\n\t\t'genosys-payment-receipts',\r\n\t\t'genosys_receipts_render_admin_page',\r\n\t\t'dashicons-media-document',\r\n\t\t62\r\n\t);\r\n}\r\nadd_action( 'admin_menu', 'genosys_receipts_add_admin_page' );\r\n\r\n/** The receipts dashboard presentation is loaded only on its existing admin page. */\r\nfunction genosys_receipts_admin_assets( $hook ) {\r\n\tif ( 'toplevel_page_genosys-payment-receipts' !== $hook ) {\r\n\t\treturn;\r\n\t}\r\n\twp_enqueue_style( 'genosys-receipts-dashboard', get_theme_file_uri( '/assets/css/receipt-admin.css' ), array(), '1.5.51' );\r\n}\r\nadd_action( 'admin_enqueue_scripts', 'genosys_receipts_admin_assets' );\r\n\r\n/** Fixed, presentation-only icons shared by dashboard controls. */\r\nfunction genosys_receipts_admin_icon( $name ) {\r\n\t$paths = array(\r\n\t\t'document' => '<path d=\"M6 2h8l5 5v15H6Z\"/><path d=\"M14 2v6h5M9 12h7M9 16h7M9 19h5\"/>',\r\n\t\t'clock'    => '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 6v6l4 2\"/>',\r\n\t\t'check'    => '<circle cx=\"12\" cy=\"12\" r=\"10\" fill=\"currentColor\" stroke=\"none\"/><path d=\"m7 12 3 3 7-7\" stroke=\"white\" stroke-width=\"2.2\"/>',\r\n\t\t'rejected' => '<path d=\"M6 2h8l5 5v15H6Z\"/><path d=\"M14 2v6h5M9 11h7m-6 4 5 5m0-5-5 5\"/>',\r\n\t\t'search'   => '<circle cx=\"10.5\" cy=\"10.5\" r=\"7\"/><path d=\"m16 16 5 5\"/>',\r\n\t\t'account'  => '<circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 22v-2a8 8 0 0 1 16 0v2\"/>',\r\n\t\t'help'     => '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M9.5 9a2.5 2.5 0 1 1 4 2c-1 .6-1.5 1-1.5 2M12 17h.01\"/>',\r\n\t\t'eye'      => '<path d=\"M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>',\r\n\t\t'download' => '<path d=\"M12 3v12m-4-4 4 4 4-4M5 17v4h14v-4\"/>',\r\n\t\t'trash'    => '<path d=\"M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7\"/>',\r\n\t\t'external' => '<path d=\"M14 3h7v7m0-7L10 14M10 5H4v16h16v-6\"/>',\r\n\t);\r\n\treturn '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">' . ( $paths[ $name ] ?? $paths['document'] ) . '</svg>';\r\n}\r\n\r\n/** Read-only totals for the same receipts/filter; the listing and stored data are untouched. */\r\nfunction genosys_receipts_admin_summary( $args, $total ) {\r\n\t$counts = array( 'total' => max( 0, (int) $total ), 'approved' => 0, 'pending' => 0, 'rejected' => 0 );\r\n\tforeach ( array( 'approved', 'rejected' ) as $status ) {\r\n\t\t$count_args = $args;\r\n\t\t$count_args['posts_per_page'] = 1;\r\n\t\t$count_args['paged'] = 1;\r\n\t\t$count_args['fields'] = 'ids';\r\n\t\t$count_args['no_found_rows'] = false;\r\n\t\t$count_args['update_post_meta_cache'] = false;\r\n\t\t$count_args['update_post_term_cache'] = false;\r\n\t\t$status_clause = array( 'key' => '_genosys_receipt_review_status', 'value' => $status, 'compare' => '=', 'type' => 'BINARY' );\r\n\t\t$count_args['meta_query'] = empty( $args['meta_query'] ) ? array( $status_clause ) : array( 'relation' => 'AND', $args['meta_query'], $status_clause );\r\n\t\t$count_query = new WP_Query( $count_args );\r\n\t\t$counts[ $status ] = max( 0, (int) $count_query->found_posts );\r\n\t}\r\n\t// The existing review helper treats missing or unknown review metadata as pending.\r\n\t$counts['pending'] = max( 0, $counts['total'] - $counts['approved'] - $counts['rejected'] );\r\n\treturn $counts;\r\n}\r\n\r\n/** Save a review without changing the order's payment, totals, or fulfillment. */\r\nfunction genosys_receipts_admin_review() {\r\n\tif ( 'POST' !== ( isset( $_SERVER['REQUEST_METHOD'] ) ? $_SERVER['REQUEST_METHOD'] : '' ) || ! genosys_receipt_can_manage() ) {\r\n\t\twp_die( 'شما اجازه تغییر وضعیت فیش را ندارید.', '', array( 'response' => 403 ) );\r\n\t}\r\n\t$receipt_id = absint( genosys_receipt_request_string( $_POST, 'receipt_id' ) );\r\n\t$nonce      = genosys_receipt_request_string( $_POST, '_wpnonce' );\r\n\tif ( ! $receipt_id || ! wp_verify_nonce( $nonce, 'genosys_receipt_review_' . $receipt_id ) ) {\r\n\t\twp_die( 'درخواست معتبر نیست. صفحه را تازه‌سازی کنید.', '', array( 'response' => 403 ) );\r\n\t}\r\n\t$result = genosys_receipt_update_review_status(\r\n\t\t$receipt_id,\r\n\t\tabsint( genosys_receipt_request_string( $_POST, 'order_id' ) ),\r\n\t\tgenosys_receipt_request_string( $_POST, 'review_status' ),\r\n\t\tgenosys_receipt_request_string( $_POST, 'previous_status' )\r\n\t);\r\n\t$notice = 'saved';\r\n\tif ( is_wp_error( $result ) ) {\r\n\t\t$notices = array( 'receipt_stale' => 'stale', 'receipt_busy' => 'busy', 'receipt_invalid' => 'invalid' );\r\n\t\t$notice  = isset( $notices[ $result->get_error_code() ] ) ? $notices[ $result->get_error_code() ] : 'error';\r\n\t}\r\n\t$args = array( 'page' => 'genosys-payment-receipts', 'receipt_notice' => $notice );\r\n\t$filter_order = absint( genosys_receipt_request_string( $_POST, 'filter_order_id' ) );\r\n\t$page_number  = max( 1, absint( genosys_receipt_request_string( $_POST, 'receipts_page' ) ) );\r\n\tif ( $filter_order ) {\r\n\t\t$args['order_id'] = $filter_order;\r\n\t}\r\n\tif ( $page_number > 1 ) {\r\n\t\t$args['paged'] = $page_number;\r\n\t}\r\n\twp_safe_redirect( add_query_arg( $args, admin_url( 'admin.php' ) ) );\r\n\texit;\r\n}\r\nadd_action( 'admin_post_genosys_receipt_review', 'genosys_receipts_admin_review' );\r\nadd_action( 'admin_post_nopriv_genosys_receipt_review', 'genosys_receipts_admin_review' );\r\n\r\n/** Protected, current-receipt deletion from the dashboard's trash control. */\r\nfunction genosys_receipts_admin_delete() {\r\n\tif ( 'POST' !== ( isset( $_SERVER['REQUEST_METHOD'] ) ? $_SERVER['REQUEST_METHOD'] : '' ) || ! genosys_receipt_can_manage() ) {\r\n\t\twp_die( 'شما اجازه حذف فیش را ندارید.', '', array( 'response' => 403 ) );\r\n\t}\r\n\t$receipt_id = absint( genosys_receipt_request_string( $_POST, 'receipt_id' ) );\r\n\t$nonce      = genosys_receipt_request_string( $_POST, '_wpnonce' );\r\n\tif ( ! $receipt_id || ! wp_verify_nonce( $nonce, 'genosys_receipt_delete_' . $receipt_id ) ) {\r\n\t\twp_die( 'درخواست معتبر نیست. صفحه را تازه‌سازی کنید.', '', array( 'response' => 403 ) );\r\n\t}\r\n\t$result = genosys_receipt_admin_delete_current( $receipt_id, absint( genosys_receipt_request_string( $_POST, 'order_id' ) ) );\r\n\t$notice = 'deleted';\r\n\tif ( is_wp_error( $result ) ) {\r\n\t\t$notices = array( 'receipt_stale' => 'stale', 'receipt_busy' => 'busy' );\r\n\t\t$notice  = isset( $notices[ $result->get_error_code() ] ) ? $notices[ $result->get_error_code() ] : 'delete_error';\r\n\t}\r\n\t$args         = array( 'page' => 'genosys-payment-receipts', 'receipt_notice' => $notice );\r\n\t$filter_order = absint( genosys_receipt_request_string( $_POST, 'filter_order_id' ) );\r\n\t$page_number  = max( 1, absint( genosys_receipt_request_string( $_POST, 'receipts_page' ) ) );\r\n\tif ( $filter_order ) {\r\n\t\t$args['order_id'] = $filter_order;\r\n\t}\r\n\tif ( $page_number > 1 ) {\r\n\t\t$args['paged'] = $page_number;\r\n\t}\r\n\twp_safe_redirect( add_query_arg( $args, admin_url( 'admin.php' ) ) );\r\n\texit;\r\n}\r\nadd_action( 'admin_post_genosys_receipt_delete', 'genosys_receipts_admin_delete' );\r\nadd_action( 'admin_post_nopriv_genosys_receipt_delete', 'genosys_receipts_admin_delete' );\r\n\r\n/** Only the current, bidirectionally linked receipt may have an editable review. */\r\nfunction genosys_receipts_render_admin_review( $receipt_id, $order, $filter_order_id, $page_number ) {\r\n\t$status  = genosys_receipt_review_status( $receipt_id );\r\n\t$labels  = genosys_receipt_status_labels();\r\n\t$current = $order ? genosys_receipt_get_current( $order ) : null;\r\n\t?>\r\n\t<td class=\"genosys-receipts__review\">\r\n\t\t<span class=\"genosys-receipts__review-label genosys-receipts__review-label--<?php echo esc_attr( $status ); ?>\"><?php echo esc_html( $labels[ $status ] ); ?></span>\r\n\t\t<?php if ( $current && (int) $current['id'] === (int) $receipt_id ) : ?>\r\n\t\t\t<form method=\"post\" action=\"<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>\" class=\"genosys-receipts__review-form\">\r\n\t\t\t\t<input type=\"hidden\" name=\"action\" value=\"genosys_receipt_review\">\r\n\t\t\t\t<input type=\"hidden\" name=\"receipt_id\" value=\"<?php echo esc_attr( $receipt_id ); ?>\">\r\n\t\t\t\t<input type=\"hidden\" name=\"order_id\" value=\"<?php echo esc_attr( $order->get_id() ); ?>\">\r\n\t\t\t\t<input type=\"hidden\" name=\"previous_status\" value=\"<?php echo esc_attr( $status ); ?>\">\r\n\t\t\t\t<input type=\"hidden\" name=\"filter_order_id\" value=\"<?php echo esc_attr( $filter_order_id ); ?>\">\r\n\t\t\t\t<input type=\"hidden\" name=\"receipts_page\" value=\"<?php echo esc_attr( $page_number ); ?>\">\r\n\t\t\t\t<?php wp_nonce_field( 'genosys_receipt_review_' . $receipt_id ); ?>\r\n\t\t\t\t<label class=\"screen-reader-text\" for=\"genosys-receipt-review-<?php echo esc_attr( $receipt_id ); ?>\">وضعیت فیش</label>\r\n\t\t\t\t<select name=\"review_status\" id=\"genosys-receipt-review-<?php echo esc_attr( $receipt_id ); ?>\">\r\n\t\t\t\t\t<?php foreach ( $labels as $value => $label ) : ?>\r\n\t\t\t\t\t\t<option value=\"<?php echo esc_attr( $value ); ?>\" <?php selected( $status, $value ); ?>><?php echo esc_html( $label ); ?></option>\r\n\t\t\t\t\t<?php endforeach; ?>\r\n\t\t\t\t</select>\r\n\t\t\t\t<button type=\"submit\" class=\"button genosys-receipts__review-save\">ذخیره</button>\r\n\t\t\t</form>\r\n\t\t<?php else : ?>\r\n\t\t\t<p class=\"description\">فیش فعلی این سفارش نیست.</p>\r\n\t\t<?php endif; ?>\r\n\t</td>\r\n\t<?php\r\n}\r\n\r\n/** Accept an exact numeric order ID, including Persian and Arabic digits. */\r\nfunction genosys_receipts_admin_order_filter() {\r\n\tif ( ! isset( $_GET['order_id'] ) || ! is_scalar( $_GET['order_id'] ) ) {\r\n\t\treturn 0;\r\n\t}\r\n\t$value = strtr(\r\n\t\ttrim( wp_unslash( (string) $_GET['order_id'] ) ),\r\n\t\tarray(\r\n\t\t\t'۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',\r\n\t\t\t'۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',\r\n\t\t\t'٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',\r\n\t\t\t'٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',\r\n\t\t)\r\n\t);\r\n\treturn preg_match( '/^[0-9]+$/D', $value ) ? absint( $value ) : 0;\r\n}\r\n\r\n/** Read order details through WooCommerce CRUD so HPOS remains supported. */\r\nfunction genosys_receipts_render_admin_order( $order, $order_id ) {\r\n\tif ( ! $order ) {\r\n\t\t?>\r\n\t\t<td class=\"genosys-receipts__order\"><strong><?php echo esc_html( '#' . $order_id ); ?></strong><p class=\"description\">سفارش در دسترس نیست.</p></td>\r\n\t\t<td class=\"genosys-receipts__customer\"><span class=\"genosys-receipts__muted\">—</span></td>\r\n\t\t<td class=\"genosys-receipts__details\"><span class=\"genosys-receipts__muted\">—</span></td>\r\n\t\t<td class=\"genosys-receipts__amount\"><span class=\"genosys-receipts__muted\">—</span></td>\r\n\t\t<td class=\"genosys-receipts__payment\"><span class=\"genosys-receipts__muted\">—</span></td>\r\n\t\t<td class=\"genosys-receipts__order-status\"><span class=\"genosys-receipts__status\">نامشخص</span></td>\r\n\t\t<?php\r\n\t\treturn;\r\n\t}\r\n\t$edit_url      = method_exists( $order, 'get_edit_order_url' ) ? $order->get_edit_order_url() : '';\r\n\t$customer_name = trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() );\r\n\t$email         = $order->get_billing_email();\r\n\t$phone         = $order->get_billing_phone();\r\n\t$shipping      = $order->get_shipping_method();\r\n\t$payment       = $order->get_payment_method_title();\r\n\t$status        = $order->get_status();\r\n\t?>\r\n\t<td class=\"genosys-receipts__order\">\r\n\t\t<?php if ( $edit_url ) : ?>\r\n\t\t\t<a class=\"genosys-receipts__order-link\" href=\"<?php echo esc_url( $edit_url ); ?>\"><?php echo esc_html( '#' . $order->get_order_number() ); ?></a>\r\n\t\t<?php else : ?>\r\n\t\t\t<strong><?php echo esc_html( '#' . $order->get_order_number() ); ?></strong>\r\n\t\t<?php endif; ?>\r\n\t\t<?php if ( (string) $order->get_order_number() !== (string) $order_id ) : ?>\r\n\t\t\t<p class=\"description\"><?php echo esc_html( 'شناسه: ' . $order_id ); ?></p>\r\n\t\t<?php endif; ?>\r\n\t</td>\r\n\t<td class=\"genosys-receipts__customer\">\r\n\t\t<strong><?php echo esc_html( $customer_name ? $customer_name : 'مشتری مهمان' ); ?></strong>\r\n\t\t<?php if ( $phone ) : ?><p dir=\"ltr\"><?php echo esc_html( $phone ); ?></p><?php endif; ?>\r\n\t\t<?php if ( $email ) : ?><p dir=\"ltr\"><?php echo esc_html( $email ); ?></p><?php endif; ?>\r\n\t</td>\r\n\t<td class=\"genosys-receipts__details\">\r\n\t\t<strong><?php echo esc_html( 'سفارش #' . $order->get_order_number() ); ?></strong>\r\n\t\t<?php if ( $shipping ) : ?><p class=\"description\"><?php echo esc_html( 'ارسال: ' . $shipping ); ?></p><?php endif; ?>\r\n\t\t<?php if ( $edit_url ) : ?><a class=\"genosys-receipts__details-link\" href=\"<?php echo esc_url( $edit_url ); ?>\"><?php echo genosys_receipts_admin_icon( 'external' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG. ?>مشاهده جزئیات</a><?php endif; ?>\r\n\t</td>\r\n\t<td class=\"genosys-receipts__amount\"><div class=\"genosys-receipts__total\"><?php echo wp_kses_post( $order->get_formatted_order_total() ); ?></div></td>\r\n\t<td class=\"genosys-receipts__payment\"><?php echo esc_html( $payment ? $payment : '—' ); ?></td>\r\n\t<td class=\"genosys-receipts__order-status\"><span class=\"genosys-receipts__status genosys-receipts__status--<?php echo esc_attr( sanitize_html_class( $status ) ); ?>\"><?php echo esc_html( wc_get_order_status_name( $status ) ); ?></span></td>\r\n\t<?php\r\n}\r\n\r\nfunction genosys_receipts_render_admin_file( $receipt_id, $order = null, $filter_order_id = 0, $page_number = 1 ) {\r\n\t$name         = (string) get_post_meta( $receipt_id, '_genosys_receipt_name', true );\r\n\t$mime         = (string) get_post_meta( $receipt_id, '_genosys_receipt_mime', true );\r\n\t$size         = max( 0, (int) get_post_meta( $receipt_id, '_genosys_receipt_size', true ) );\r\n\t$preview_url  = function_exists( 'genosys_receipt_file_url' ) ? genosys_receipt_file_url( $receipt_id, false ) : '';\r\n\t$image        = in_array( $mime, array( 'image/jpeg', 'image/png', 'image/webp' ), true );\r\n\t?>\r\n\t<div class=\"genosys-receipts__file\">\r\n\t\t<?php if ( $image && $preview_url ) : ?>\r\n\t\t\t<a class=\"genosys-receipts__preview\" href=\"<?php echo esc_url( $preview_url ); ?>\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"مشاهده فیش\">\r\n\t\t\t\t<img src=\"<?php echo esc_url( $preview_url ); ?>\" alt=\"<?php echo esc_attr( $name ); ?>\" width=\"88\" height=\"88\" loading=\"lazy\">\r\n\t\t\t\t<span class=\"genosys-receipts__preview-zoom\"><?php echo genosys_receipts_admin_icon( 'search' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG. ?></span>\r\n\t\t\t</a>\r\n\t\t<?php else : ?>\r\n\t\t\t<span class=\"genosys-receipts__document\" aria-hidden=\"true\"><?php echo esc_html( 'application/pdf' === $mime ? 'PDF' : 'فیش' ); ?></span>\r\n\t\t<?php endif; ?>\r\n\t\t<div class=\"genosys-receipts__file-info\">\r\n\t\t\t<span class=\"genosys-receipts__filename\" dir=\"auto\" title=\"<?php echo esc_attr( $name ); ?>\"><?php echo esc_html( $name ? $name : 'فیش واریزی' ); ?></span>\r\n\t\t\t<?php if ( $size ) : ?><p class=\"description\"><?php echo esc_html( size_format( $size, 1 ) ); ?></p><?php endif; ?>\r\n\t\t</div>\r\n\t</div>\r\n\t<?php\r\n}\r\n\r\n/** Existing preview/download/delete controls, presented in their own action column. */\r\nfunction genosys_receipts_render_admin_actions( $receipt_id, $order = null, $filter_order_id = 0, $page_number = 1 ) {\r\n\t$download_url = function_exists( 'genosys_receipt_file_url' ) ? genosys_receipt_file_url( $receipt_id, true ) : '';\r\n\t$preview_url  = function_exists( 'genosys_receipt_file_url' ) ? genosys_receipt_file_url( $receipt_id, false ) : '';\r\n\t$current      = $order ? genosys_receipt_get_current( $order ) : null;\r\n\t$can_delete   = $current && (int) $current['id'] === (int) $receipt_id;\r\n\t$delete_label = $order ? 'حذف فیش واریزی سفارش #' . $order->get_order_number() : 'حذف فیش واریزی';\r\n\t?>\r\n\t<div class=\"genosys-receipts__actions\">\r\n\t\t<?php if ( $preview_url ) : ?><a class=\"button genosys-receipts__view\" href=\"<?php echo esc_url( $preview_url ); ?>\" target=\"_blank\" rel=\"noopener noreferrer\"><?php echo genosys_receipts_admin_icon( 'eye' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG. ?>مشاهده</a><?php endif; ?>\r\n\t\t<?php if ( $download_url ) : ?>\r\n\t\t\t<a class=\"button genosys-receipts__download\" href=\"<?php echo esc_url( $download_url ); ?>\"><?php echo genosys_receipts_admin_icon( 'download' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG. ?>دانلود رسید</a>\r\n\t\t<?php else : ?><p class=\"description\">فایل در دسترس نیست.</p><?php endif; ?>\r\n\t\t<form method=\"post\" action=\"<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>\" class=\"genosys-receipts__delete-form\">\r\n\t\t\t\t<?php if ( $can_delete ) : ?>\r\n\t\t\t\t\t<input type=\"hidden\" name=\"action\" value=\"genosys_receipt_delete\">\r\n\t\t\t\t\t<input type=\"hidden\" name=\"receipt_id\" value=\"<?php echo esc_attr( $receipt_id ); ?>\">\r\n\t\t\t\t\t<input type=\"hidden\" name=\"order_id\" value=\"<?php echo esc_attr( $order->get_id() ); ?>\">\r\n\t\t\t\t\t<input type=\"hidden\" name=\"filter_order_id\" value=\"<?php echo esc_attr( $filter_order_id ); ?>\">\r\n\t\t\t\t\t<input type=\"hidden\" name=\"receipts_page\" value=\"<?php echo esc_attr( $page_number ); ?>\">\r\n\t\t\t\t\t<?php wp_nonce_field( 'genosys_receipt_delete_' . $receipt_id ); ?>\r\n\t\t\t\t<?php endif; ?>\r\n\t\t\t<button type=\"submit\" class=\"genosys-receipts__delete\" aria-label=\"<?php echo esc_attr( $delete_label ); ?>\" title=\"<?php echo esc_attr( $can_delete ? $delete_label : 'فیش فعلی این سفارش نیست.' ); ?>\" <?php disabled( ! $can_delete ); ?>><?php echo genosys_receipts_admin_icon( 'trash' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG. ?>حذف</button>\r\n\t\t</form>\r\n\t</div>\r\n\t<?php\r\n}\r\n\r\nfunction genosys_receipts_render_admin_page() {\r\n\tif ( ! current_user_can( 'manage_woocommerce' ) && ! current_user_can( 'manage_options' ) ) {\r\n\t\twp_die( esc_html__( 'شما اجازه مشاهده فیش‌های واریزی را ندارید.', 'genosys' ), '', array( 'response' => 403 ) );\r\n\t}\r\n\t$page_number = isset( $_GET['paged'] ) && is_scalar( $_GET['paged'] ) ? max( 1, absint( $_GET['paged'] ) ) : 1;\r\n\t$order_id    = genosys_receipts_admin_order_filter();\r\n\t$notice      = genosys_receipt_request_string( $_GET, 'receipt_notice' );\r\n\t$notices     = array(\r\n\t\t'saved'   => 'وضعیت فیش ذخیره شد.',\r\n\t\t'deleted' => 'فیش واریزی حذف شد.',\r\n\t\t'stale'   => 'فیش یا وضعیت آن در صفحه دیگری تغییر کرده است. صفحه را تازه‌سازی و دوباره تلاش کنید.',\r\n\t\t'busy'    => 'فیش در حال ذخیره شدن است. چند لحظه دیگر دوباره تلاش کنید.',\r\n\t\t'invalid' => 'وضعیت انتخاب‌شده معتبر نیست.',\r\n\t\t'error'   => 'ذخیره وضعیت فیش انجام نشد. دوباره تلاش کنید.',\r\n\t\t'delete_error' => 'حذف فیش کامل نشد. صفحه را تازه‌سازی و دوباره تلاش کنید.',\r\n\t);\r\n\t$args        = array(\r\n\t\t'post_type'      => 'genosys_receipt',\r\n\t\t'post_status'    => 'private',\r\n\t\t'posts_per_page' => 20,\r\n\t\t'paged'          => $page_number,\r\n\t\t'orderby'        => array( 'date' => 'DESC', 'ID' => 'DESC' ),\r\n\t);\r\n\tif ( $order_id ) {\r\n\t\t$args['meta_query'] = array(\r\n\t\t\tarray( 'key' => '_genosys_order_id', 'value' => $order_id, 'compare' => '=', 'type' => 'NUMERIC' ),\r\n\t\t);\r\n\t}\r\n\t$receipts   = new WP_Query( $args );\r\n\t$page_url   = admin_url( 'admin.php?page=genosys-payment-receipts' );\r\n\t$pagination = paginate_links(\r\n\t\tarray(\r\n\t\t\t'base'      => add_query_arg( 'paged', '%#%', $order_id ? add_query_arg( 'order_id', $order_id, $page_url ) : $page_url ),\r\n\t\t\t'format'    => '',\r\n\t\t\t'current'   => $page_number,\r\n\t\t\t'total'     => $receipts->max_num_pages,\r\n\t\t\t'prev_text' => 'قبلی',\r\n\t\t\t'next_text' => 'بعدی',\r\n\t\t\t'type'      => 'list',\r\n\t\t)\r\n\t);\r\n\t$summary = genosys_receipts_admin_summary( $args, $receipts->found_posts );\r\n\t$user = wp_get_current_user();\r\n\t$range_start = $receipts->post_count ? ( $page_number - 1 ) * 20 + 1 : 0;\r\n\t$range_end = $receipts->post_count ? min( (int) $receipts->found_posts, $range_start + $receipts->post_count - 1 ) : 0;\r\n\t$summary_labels = array( 'total' => 'کل رسیدها', 'approved' => 'تایید شده', 'pending' => 'در انتظار بررسی', 'rejected' => 'رد شده' );\r\n\t$summary_icons = array( 'total' => 'document', 'approved' => 'check', 'pending' => 'clock', 'rejected' => 'rejected' );\r\n\t?>\r\n\t<div class=\"wrap genosys-receipts\" dir=\"rtl\">\r\n\t\t<header class=\"genosys-receipts__topbar\">\r\n\t\t\t<div class=\"genosys-receipts__identity\">\r\n\t\t\t\t<span class=\"genosys-receipts__avatar\"><?php echo genosys_receipts_admin_icon( 'account' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG. ?></span>\r\n\t\t\t\t<div class=\"genosys-receipts__identity-text\"><strong><?php echo esc_html( $user->display_name ); ?></strong><span><?php echo esc_html( current_user_can( 'manage_options' ) ? 'مدیر کل' : 'مدیر فروشگاه' ); ?></span></div>\r\n\t\t\t</div>\r\n\t\t\t<form method=\"get\" action=\"<?php echo esc_url( admin_url( 'admin.php' ) ); ?>\" class=\"genosys-receipts__search genosys-receipts__topbar-search\">\r\n\t\t\t\t<input type=\"hidden\" name=\"page\" value=\"genosys-payment-receipts\">\r\n\t\t\t\t<div class=\"genosys-receipts__search-field\">\r\n\t\t\t\t\t<label class=\"screen-reader-text\" for=\"genosys-receipt-topbar-order-id\">شناسه سفارش</label>\r\n\t\t\t\t\t<input type=\"text\" inputmode=\"numeric\" name=\"order_id\" id=\"genosys-receipt-topbar-order-id\" value=\"<?php echo $order_id ? esc_attr( $order_id ) : ''; ?>\" placeholder=\"جستجو در رسیدها با شماره سفارش ...\">\r\n\t\t\t\t\t<button type=\"submit\" class=\"genosys-receipts__topbar-submit\" aria-label=\"جستجوی رسید با شناسه سفارش\"><?php echo genosys_receipts_admin_icon( 'search' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG. ?></button>\r\n\t\t\t\t</div>\r\n\t\t\t</form>\r\n\t\t\t<div class=\"genosys-receipts__brand\"><img src=\"<?php echo esc_url( get_theme_file_uri( '/assets/images/genosys-logo-1.1.1.svg' ) ); ?>\" alt=\"GENOSYS\" width=\"215\" height=\"47\"><small>SKIN SCIENCE FOR A BETTER YOU</small></div>\r\n\t\t</header>\r\n\t\t<?php if ( isset( $notices[ $notice ] ) ) : ?>\r\n\t\t\t<div class=\"notice <?php echo in_array( $notice, array( 'saved', 'deleted' ), true ) ? 'notice-success' : 'notice-error'; ?> is-dismissible\"><p><?php echo esc_html( $notices[ $notice ] ); ?></p></div>\r\n\t\t<?php endif; ?>\r\n\t\t<section class=\"genosys-receipts__hero\" aria-labelledby=\"genosys-receipts-title\">\r\n\t\t\t<img class=\"genosys-receipts__hero-art\" src=\"<?php echo esc_url( get_theme_file_uri( '/assets/images/receipt-dashboard-art.png' ) ); ?>\" alt=\"\" aria-hidden=\"true\" width=\"1672\" height=\"941\">\r\n\t\t\t<p class=\"genosys-receipts__hero-slogan\" lang=\"en\" dir=\"ltr\" aria-hidden=\"true\">SCIENCE<br>FOR HEALTHY<br>BEAUTIFUL SKIN</p>\r\n\t\t\t<div class=\"genosys-receipts__hero-copy\">\r\n\t\t\t\t<h1 id=\"genosys-receipts-title\">مدیریت رسیدهای پرداخت</h1>\r\n\t\t\t\t<p class=\"genosys-receipts__intro\">رسیدهای پرداخت ارسال‌شده توسط کاربران را بررسی، تأیید یا رد کنید.</p>\r\n\t\t\t\t<details class=\"genosys-receipts__help\"><summary><?php echo genosys_receipts_admin_icon( 'help' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG. ?>راهنمای این بخش</summary><p>از «مشاهده» برای بررسی فایل و از «دانلود رسید» برای دریافت آن استفاده کنید. وضعیت فیش را انتخاب و ذخیره کنید. حذف فیش، امکان بارگذاری دوباره برای مشتری را فعال می‌کند.</p></details>\r\n\t\t\t</div>\r\n\t\t</section>\r\n\t\t<section class=\"genosys-receipts__stats\" aria-label=\"خلاصه وضعیت رسیدها\">\r\n\t\t\t<?php foreach ( $summary_labels as $key => $label ) : ?>\r\n\t\t\t\t<div class=\"genosys-receipts__stat genosys-receipts__stat--<?php echo esc_attr( $key ); ?>\"><div class=\"genosys-receipts__stat-inner\"><p class=\"genosys-receipts__stat-label\"><?php echo esc_html( $label ); ?></p><strong class=\"genosys-receipts__stat-value\"><?php echo esc_html( number_format_i18n( $summary[ $key ] ) ); ?></strong><span class=\"genosys-receipts__stat-icon\"><?php echo genosys_receipts_admin_icon( $summary_icons[ $key ] ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG. ?></span></div></div>\r\n\t\t\t<?php endforeach; ?>\r\n\t\t</section>\r\n\t\t<div class=\"genosys-receipts__toolbar\">\r\n\t\t\t<div class=\"genosys-receipts__toolbar-heading\"><strong>جستجو با شناسه سفارش</strong><p><?php echo esc_html( $order_id ? 'رسیدهای سفارش #' . $order_id : 'رسیدها به ترتیب جدیدترین بارگذاری نمایش داده می‌شوند.' ); ?></p></div>\r\n\t\t\t<form method=\"get\" action=\"<?php echo esc_url( admin_url( 'admin.php' ) ); ?>\" class=\"genosys-receipts__search\">\r\n\t\t\t\t<input type=\"hidden\" name=\"page\" value=\"genosys-payment-receipts\">\r\n\t\t\t\t<div class=\"genosys-receipts__search-field\">\r\n\t\t\t\t\t<?php echo genosys_receipts_admin_icon( 'search' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG. ?>\r\n\t\t\t\t\t<label class=\"screen-reader-text\" for=\"genosys-receipt-order-id\">شناسه سفارش</label>\r\n\t\t\t\t\t<input type=\"text\" inputmode=\"numeric\" name=\"order_id\" id=\"genosys-receipt-order-id\" value=\"<?php echo $order_id ? esc_attr( $order_id ) : ''; ?>\" placeholder=\"شماره سفارش، مثلاً ۱۷۴\">\r\n\t\t\t\t</div>\r\n\t\t\t\t<button type=\"submit\" class=\"button genosys-receipts__search-button\">جستجو</button>\r\n\t\t\t\t<?php if ( $order_id ) : ?><a class=\"genosys-receipts__reset\" href=\"<?php echo esc_url( $page_url ); ?>\">نمایش همه</a><?php endif; ?>\r\n\t\t\t</form>\r\n\t\t</div>\r\n\t\t<div class=\"genosys-receipts__table-wrap\" role=\"region\" aria-label=\"جدول رسیدهای پرداخت\" tabindex=\"0\">\r\n\t\t\t<table class=\"widefat genosys-receipts__table\">\r\n\t\t\t\t<thead><tr><th scope=\"col\">#</th><th scope=\"col\">مشتری</th><th scope=\"col\">جزئیات سفارش</th><th scope=\"col\">مبلغ سفارش</th><th scope=\"col\">روش پرداخت</th><th scope=\"col\">وضعیت سفارش</th><th scope=\"col\">وضعیت فیش</th><th scope=\"col\">تصویر رسید</th><th scope=\"col\">عملیات</th><th scope=\"col\">تاریخ بارگذاری</th></tr></thead>\r\n\t\t\t\t<tbody>\r\n\t\t\t\t<?php if ( $receipts->posts ) : ?>\r\n\t\t\t\t\t<?php foreach ( $receipts->posts as $receipt ) : ?>\r\n\t\t\t\t\t\t<?php\r\n\t\t\t\t\t\t$receipt_order_id = absint( get_post_meta( $receipt->ID, '_genosys_order_id', true ) );\r\n\t\t\t\t\t\t$order            = function_exists( 'wc_get_order' ) && $receipt_order_id ? wc_get_order( $receipt_order_id ) : false;\r\n\t\t\t\t\t\t?>\r\n\t\t\t\t\t\t<tr data-receipt-id=\"<?php echo esc_attr( $receipt->ID ); ?>\">\r\n\t\t\t\t\t\t\t<?php genosys_receipts_render_admin_order( $order, $receipt_order_id ); ?>\r\n\t\t\t\t\t\t\t<?php genosys_receipts_render_admin_review( $receipt->ID, $order, $order_id, $page_number ); ?>\r\n\t\t\t\t\t\t\t<td class=\"genosys-receipts__receipt-image\"><?php genosys_receipts_render_admin_file( $receipt->ID, $order, $order_id, $page_number ); ?></td>\r\n\t\t\t\t\t\t\t<td><?php genosys_receipts_render_admin_actions( $receipt->ID, $order, $order_id, $page_number ); ?></td>\r\n\t\t\t\t\t\t\t<td class=\"genosys-receipts__date\"><time datetime=\"<?php echo esc_attr( get_post_time( 'c', true, $receipt ) ); ?>\"><?php echo esc_html( get_the_date( get_option( 'date_format' ), $receipt ) ); ?><br><span><?php echo esc_html( get_the_time( get_option( 'time_format' ), $receipt ) ); ?></span></time></td>\r\n\t\t\t\t\t\t</tr>\r\n\t\t\t\t\t<?php endforeach; ?>\r\n\t\t\t\t<?php else : ?>\r\n\t\t\t\t\t<tr><td colspan=\"10\" class=\"genosys-receipts__empty\"><span class=\"dashicons dashicons-media-document\" aria-hidden=\"true\"></span><strong><?php echo esc_html( $order_id ? 'برای این سفارش فیشی پیدا نشد.' : 'هنوز فیش واریزی ثبت نشده است.' ); ?></strong></td></tr>\r\n\t\t\t\t<?php endif; ?>\r\n\t\t\t\t</tbody>\r\n\t\t\t</table>\r\n\t\t</div>\r\n\t\t<footer class=\"genosys-receipts__pagination\">\r\n\t\t\t<p class=\"genosys-receipts__range\"><?php echo esc_html( sprintf( 'نمایش %1$s تا %2$s از %3$s مورد', number_format_i18n( $range_start ), number_format_i18n( $range_end ), number_format_i18n( $receipts->found_posts ) ) ); ?></p>\r\n\t\t\t<nav class=\"genosys-receipts__page-links\" aria-label=\"صفحه‌بندی فیش‌ها\">\r\n\t\t\t\t<?php if ( $pagination ) : ?><?php echo wp_kses_post( $pagination ); ?><?php else : ?><ul class=\"page-numbers\"><li><span aria-disabled=\"true\" aria-label=\"قبلی\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><path d=\"m9 6 6 6-6 6\"/></svg></span></li><li><span class=\"page-numbers current\" aria-current=\"page\">۱</span></li><li><span aria-disabled=\"true\" aria-label=\"بعدی\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\"><path d=\"m15 6-6 6 6 6\"/></svg></span></li></ul><?php endif; ?>\r\n\t\t\t</nav>\r\n\t\t\t<p class=\"genosys-receipts__page-size\"><span>تعداد در هر صفحه:</span><strong>۲۰</strong></p>\r\n\t\t</footer>\r\n\t</div>\r\n\t<?php\r\n}\r\n","sha256":"680370a4c0845b1ba948e27366a077bb0aad26c6ad2099fce98ce6fa98a0edef"},"inc/receipt-sms.php":{"content":"<?php\n/** Customer SMS for committed receipt approvals and rejections. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_receipt_sms_template_id( $status ) {\n\tif ( ! in_array( $status, array( 'approved', 'rejected' ), true ) ) {\n\t\treturn 0;\n\t}\n\t$value = get_option( 'genosys_receipt_' . $status . '_sms_template_id', '' );\n\tif ( ! is_scalar( $value ) || is_bool( $value ) ) {\n\t\treturn 0;\n\t}\n\t$value = genosys_checkout_ascii_digits( trim( (string) $value ) );\n\treturn preg_match( '/^[1-9][0-9]{0,9}$/D', $value ) && (float) $value <= 2147483647 ? (int) $value : 0;\n}\n\nfunction genosys_receipt_sms_log( $order_id, $reason ) {\n\tif ( function_exists( 'wc_get_logger' ) ) {\n\t\twc_get_logger()->warning( 'Receipt review SMS could not be confirmed.', array( 'source' => 'genosys-receipt-review-sms', 'order_id' => absint( $order_id ), 'reason' => sanitize_key( $reason ) ) );\n\t}\n}\n\nfunction genosys_receipt_sms_event_key( $event_id ) {\n\treturn is_string( $event_id ) && preg_match( '/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/D', $event_id ) ? '_genosys_receipt_sms_event_' . str_replace( '-', '', $event_id ) : '';\n}\n\n/** Capture once per decision; a replacement receipt cannot erase its notification. */\nfunction genosys_receipt_sms_queue( $receipt_id, $order_id, $from, $to, $event_id ) {\n\t$event_key = genosys_receipt_sms_event_key( $event_id );\n\tif ( ! $event_key || ! absint( $receipt_id ) || ! absint( $order_id ) || $from === $to || ! in_array( $from, array( 'pending', 'approved', 'rejected' ), true ) || ! in_array( $to, array( 'approved', 'rejected' ), true ) || ! function_exists( 'wc_get_order' ) ) {\n\t\treturn;\n\t}\n\ttry {\n\t\t$order = wc_get_order( $order_id );\n\t\tif ( ! $order instanceof WC_Order || 'shop_order' !== $order->get_type() ) {\n\t\t\treturn;\n\t\t}\n\t\t$order->read_meta_data( true );\n\t\t$event = $order->get_meta( $event_key, true );\n\t\tif ( function_exists( 'genosys_account_notification_order_allowed' ) && ! genosys_account_notification_order_allowed( $order, 'payment_sms', is_array( $event ) ? ( $event['phone'] ?? '' ) : '' ) ) {\n\t\t\tif ( is_array( $event ) && empty( $event['attempted_at'] ) ) {\n\t\t\t\t$event['attempted_at'] = time(); $event['status'] = 'suppressed';\n\t\t\t\t$order->update_meta_data( $event_key, $event ); $order->save_meta_data();\n\t\t\t}\n\t\t\treturn;\n\t\t}\n\t\tif ( ! $event ) {\n\t\t\t$template_id = genosys_receipt_sms_template_id( $to );\n\t\t\t$phone = genosys_sms_normalize_phone( $order->get_billing_phone() );\n\t\t\t$current = genosys_receipt_get_current( $order );\n\t\t\tif ( ! $template_id || '' === genosys_sms_api_key() || '' === $phone || ! $current || (int) $current['id'] !== absint( $receipt_id ) || $to !== $current['reviewStatus'] ) {\n\t\t\t\treturn;\n\t\t\t}\n\t\t\t$name = trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() );\n\t\t\t$event = array(\n\t\t\t\t'id' => $event_id,\n\t\t\t\t'receipt_id' => absint( $receipt_id ),\n\t\t\t\t'from' => $from,\n\t\t\t\t'to' => $to,\n\t\t\t\t'template_id' => $template_id,\n\t\t\t\t'phone' => $phone,\n\t\t\t\t'parameters' => array( array( 'name' => 'NAME', 'value' => sanitize_text_field( '' !== $name ? $name : 'مشتری' ) ) ),\n\t\t\t\t'created_at' => time(),\n\t\t\t\t'attempted_at' => 0,\n\t\t\t\t'status' => 'pending',\n\t\t\t);\n\t\t\t$order->update_meta_data( $event_key, $event );\n\t\t\t$order->save_meta_data();\n\t\t\t$order->read_meta_data( true );\n\t\t\tif ( $event !== $order->get_meta( $event_key, true ) ) {\n\t\t\t\tthrow new RuntimeException( 'snapshot_unavailable' );\n\t\t\t}\n\t\t}\n\t\tif ( ! is_array( $event ) || $event_id !== ( $event['id'] ?? '' ) || absint( $receipt_id ) !== ( $event['receipt_id'] ?? 0 ) || $from !== ( $event['from'] ?? '' ) || $to !== ( $event['to'] ?? '' ) || ! empty( $event['attempted_at'] ) ) {\n\t\t\treturn;\n\t\t}\n\t\t$args = array( (int) $order_id, $event_id );\n\t\tif ( function_exists( 'as_enqueue_async_action' ) ) {\n\t\t\t$queued = as_enqueue_async_action( 'genosys_receipt_sms_send', $args, 'genosys-receipt-review-sms', true );\n\t\t\tif ( $queued || ( function_exists( 'as_has_scheduled_action' ) && as_has_scheduled_action( 'genosys_receipt_sms_send', $args, 'genosys-receipt-review-sms' ) ) ) {\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t\tif ( ! wp_next_scheduled( 'genosys_receipt_sms_send', $args ) && ! wp_schedule_single_event( time(), 'genosys_receipt_sms_send', $args ) ) {\n\t\t\tgenosys_receipt_sms_log( $order_id, 'queue_unavailable' );\n\t\t}\n\t} catch ( Throwable $exception ) {\n\t\tgenosys_receipt_sms_log( $order_id, 'queue_unavailable' );\n\t}\n}\nadd_action( 'genosys_receipt_review_status_changed', 'genosys_receipt_sms_queue', 1, 5 );\n\n/** Claim the saved event before HTTP; retries cannot send the same decision twice. */\nfunction genosys_receipt_sms_send( $order_id, $event_id ) {\n\t$order_id = absint( $order_id );\n\t$event_key = genosys_receipt_sms_event_key( $event_id );\n\tif ( ! $order_id || ! $event_key || ! function_exists( 'wc_get_order' ) ) {\n\t\treturn;\n\t}\n\t$lock = genosys_order_sms_lock( $order_id, 'receipt_' . $event_id );\n\tif ( ! $lock ) {\n\t\treturn;\n\t}\n\ttry {\n\t\t$order = wc_get_order( $order_id );\n\t\tif ( ! $order instanceof WC_Order || 'shop_order' !== $order->get_type() ) {\n\t\t\treturn;\n\t\t}\n\t\t$order->read_meta_data( true );\n\t\t$event = $order->get_meta( $event_key, true );\n\t\t$api_key = genosys_sms_api_key();\n\t\tif ( ! is_array( $event ) || $event_id !== ( $event['id'] ?? '' ) || ! empty( $event['attempted_at'] ) || ! genosys_receipt_sms_template_id( $event['to'] ?? '' ) || '' === $api_key || empty( $event['template_id'] ) || empty( $event['phone'] ) || $event['phone'] !== genosys_sms_normalize_phone( $event['phone'] ) || ! isset( $event['parameters'] ) || ! is_array( $event['parameters'] ) || 1 !== count( $event['parameters'] ) || 'NAME' !== ( $event['parameters'][0]['name'] ?? '' ) ) {\n\t\t\treturn;\n\t\t}\n\t\tif ( function_exists( 'genosys_account_notification_order_allowed' ) && ! genosys_account_notification_order_allowed( $order, 'payment_sms', $event['phone'] ) ) {\n\t\t\t$event['attempted_at'] = time(); $event['status'] = 'suppressed';\n\t\t\t$order->update_meta_data( $event_key, $event ); $order->save_meta_data();\n\t\t\treturn;\n\t\t}\n\t\t$event['attempted_at'] = time();\n\t\t$event['status'] = 'attempting';\n\t\t$order->update_meta_data( $event_key, $event );\n\t\t$order->save_meta_data();\n\t\t$order->read_meta_data( true );\n\t\t$claim = $order->get_meta( $event_key, true );\n\t\tif ( ! is_array( $claim ) || $event['attempted_at'] !== ( $claim['attempted_at'] ?? 0 ) || 'attempting' !== ( $claim['status'] ?? '' ) ) {\n\t\t\tthrow new RuntimeException( 'claim_unavailable' );\n\t\t}\n\t\t$result = genosys_order_sms_request( $event['phone'], (int) $event['template_id'], $event['parameters'], $api_key );\n\t\t$event['status'] = $result['status'];\n\t\tif ( 'sent' === $result['status'] ) {\n\t\t\t$event['message_id'] = $result['message_id'];\n\t\t\t$event['sent_at'] = time();\n\t\t} else {\n\t\t\tgenosys_receipt_sms_log( $order_id, $result['reason'] );\n\t\t}\n\t\t$order->update_meta_data( $event_key, $event );\n\t\t$order->save_meta_data();\n\t} catch ( Throwable $exception ) {\n\t\tgenosys_receipt_sms_log( $order_id, 'send_unconfirmed' );\n\t} finally {\n\t\tgenosys_order_sms_unlock( $lock );\n\t}\n}\nadd_action( 'genosys_receipt_sms_send', 'genosys_receipt_sms_send', 10, 2 );\n","sha256":"c6ead9b695d2b000af5bed72263e02e00152590276f1a4f6f865df14c48db72e"},"inc/receipts.php":{"content":"<?php\n/**\n * Private, order-linked payment receipts. WooCommerce remains responsible for payment.\n *\n * @package Genosys\n */\n\ndefined( 'ABSPATH' ) || exit;\n\n/** Receipts have no public URLs, REST route, or default editing screen. */\nfunction genosys_receipt_register_post_type() {\n\tregister_post_type( 'genosys_receipt', array(\n\t\t'labels'              => array( 'name' => 'فیش های واریزی', 'singular_name' => 'فیش واریزی' ),\n\t\t'public'              => false,\n\t\t'publicly_queryable'  => false,\n\t\t'exclude_from_search' => true,\n\t\t'show_ui'             => false,\n\t\t'show_in_menu'        => false,\n\t\t'show_in_rest'        => false,\n\t\t'rewrite'             => false,\n\t\t'query_var'           => false,\n\t\t'supports'            => false,\n\t\t'capability_type'     => 'genosys_receipt',\n\t\t'map_meta_cap'        => false,\n\t\t// Only the dedicated, explicitly authorized UI/endpoints may access receipts.\n\t\t'capabilities'        => array(\n\t\t\t'edit_post'              => 'do_not_allow',\n\t\t\t'read_post'              => 'do_not_allow',\n\t\t\t'delete_post'            => 'do_not_allow',\n\t\t\t'edit_posts'             => 'do_not_allow',\n\t\t\t'edit_others_posts'       => 'do_not_allow',\n\t\t\t'publish_posts'          => 'do_not_allow',\n\t\t\t'read_private_posts'     => 'do_not_allow',\n\t\t\t'delete_posts'           => 'do_not_allow',\n\t\t\t'delete_private_posts'   => 'do_not_allow',\n\t\t\t'delete_published_posts' => 'do_not_allow',\n\t\t\t'delete_others_posts'    => 'do_not_allow',\n\t\t\t'edit_private_posts'     => 'do_not_allow',\n\t\t\t'edit_published_posts'   => 'do_not_allow',\n\t\t\t'create_posts'           => 'do_not_allow',\n\t\t),\n\t) );\n}\nadd_action( 'init', 'genosys_receipt_register_post_type' );\n\n/** Administrators and WooCommerce shop managers can view the private receipts. */\nfunction genosys_receipt_can_manage() {\n\treturn current_user_can( 'manage_woocommerce' ) || current_user_can( 'manage_options' );\n}\n\n/** Receipt review is separate from WooCommerce payment and order status. */\nfunction genosys_receipt_status_labels() {\n\treturn array(\n\t\t'pending'  => 'در حال بررسی',\n\t\t'approved' => 'تایید شده',\n\t\t'rejected' => 'رد شده',\n\t);\n}\n\n/** Existing receipts without review metadata start in the review queue. */\nfunction genosys_receipt_review_status( $receipt_id ) {\n\t$status = get_post_meta( absint( $receipt_id ), '_genosys_receipt_review_status', true );\n\treturn is_string( $status ) && array_key_exists( $status, genosys_receipt_status_labels() ) ? $status : 'pending';\n}\n\n/** Review the current receipt under the same lock used by upload and replacement. */\nfunction genosys_receipt_update_review_status( $receipt_id, $order_id, $status, $previous_status ) {\n\tif ( ! genosys_receipt_can_manage() ) {\n\t\treturn new WP_Error( 'receipt_forbidden', 'شما اجازه تغییر وضعیت فیش را ندارید.' );\n\t}\n\t$labels = genosys_receipt_status_labels();\n\tif ( ! is_string( $status ) || ! is_string( $previous_status ) || ! isset( $labels[ $status ], $labels[ $previous_status ] ) ) {\n\t\treturn new WP_Error( 'receipt_invalid', 'وضعیت انتخاب‌شده معتبر نیست.' );\n\t}\n\t$receipt_id = absint( $receipt_id );\n\t$order_id   = absint( $order_id );\n\tif ( ! $receipt_id || ! $order_id || ! function_exists( 'wc_get_order' ) ) {\n\t\treturn new WP_Error( 'receipt_stale', 'فیش یا سفارش در دسترس نیست. صفحه را تازه‌سازی کنید.' );\n\t}\n\t$lock = genosys_receipt_lock( $order_id );\n\tif ( is_wp_error( $lock ) ) {\n\t\treturn $lock;\n\t}\n\ttry {\n\t\t// Refresh both sides after locking so a replaced receipt cannot be reviewed.\n\t\tclean_post_cache( $receipt_id );\n\t\t$order = wc_get_order( $order_id );\n\t\tif ( $order ) {\n\t\t\t$order->read_meta_data( true );\n\t\t}\n\t\t$current = genosys_receipt_get_current( $order );\n\t\tif ( ! $current || (int) $current['id'] !== $receipt_id ) {\n\t\t\treturn new WP_Error( 'receipt_stale', 'فیش این سفارش تغییر کرده است. صفحه را تازه‌سازی کنید.' );\n\t\t}\n\t\tif ( $previous_status !== $current['reviewStatus'] ) {\n\t\t\treturn new WP_Error( 'receipt_stale', 'وضعیت فیش در صفحه دیگری تغییر کرده است. صفحه را تازه‌سازی کنید.' );\n\t\t}\n\t\tif ( $status !== $current['reviewStatus'] ) {\n\t\t\t$saved = update_post_meta( $receipt_id, '_genosys_receipt_review_status', $status );\n\t\t\tif ( false === $saved || $status !== genosys_receipt_review_status( $receipt_id ) ) {\n\t\t\t\treturn new WP_Error( 'receipt_save', 'ذخیره وضعیت فیش انجام نشد. دوباره تلاش کنید.' );\n\t\t\t}\n\t\t\t// The decision is committed; notification failures must not undo its success.\n\t\t\ttry {\n\t\t\t\tdo_action( 'genosys_receipt_review_status_changed', $receipt_id, $order_id, $current['reviewStatus'], $status, wp_generate_uuid4() );\n\t\t\t} catch ( Throwable $notification_error ) {\n\t\t\t\tif ( function_exists( 'genosys_receipt_sms_log' ) ) {\n\t\t\t\t\tgenosys_receipt_sms_log( $order_id, 'notification_unavailable' );\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn $status;\n\t} catch ( Throwable $exception ) {\n\t\treturn new WP_Error( 'receipt_save', 'ذخیره وضعیت فیش انجام نشد. دوباره تلاش کنید.' );\n\t} finally {\n\t\tgenosys_receipt_unlock( $lock );\n\t}\n}\n\n/** Managers may remove a current receipt without changing the WooCommerce order. */\nfunction genosys_receipt_admin_delete_current( $receipt_id, $order_id ) {\n\tif ( ! genosys_receipt_can_manage() ) {\n\t\treturn new WP_Error( 'receipt_forbidden', 'شما اجازه حذف فیش را ندارید.' );\n\t}\n\t$receipt_id = absint( $receipt_id );\n\t$order_id   = absint( $order_id );\n\tif ( ! $receipt_id || ! $order_id || ! function_exists( 'wc_get_order' ) ) {\n\t\treturn new WP_Error( 'receipt_stale', 'فیش یا سفارش در دسترس نیست. صفحه را تازه‌سازی کنید.' );\n\t}\n\t$lock = genosys_receipt_lock( $order_id );\n\tif ( is_wp_error( $lock ) ) {\n\t\treturn $lock;\n\t}\n\t$order    = false;\n\t$unlinked = false;\n\ttry {\n\t\tclean_post_cache( $receipt_id );\n\t\t$order = wc_get_order( $order_id );\n\t\tif ( $order && $order->get_data_store() ) {\n\t\t\t$order->get_data_store()->read( $order );\n\t\t\t$order->read_meta_data( true );\n\t\t}\n\t\t$current = genosys_receipt_get_current( $order );\n\t\tif ( ! $current || (int) $current['id'] !== $receipt_id ) {\n\t\t\treturn new WP_Error( 'receipt_stale', 'فیش این سفارش تغییر کرده است. صفحه را تازه‌سازی کنید.' );\n\t\t}\n\t\t$path = genosys_receipt_storage_path( (string) get_post_meta( $receipt_id, '_genosys_receipt_file', true ) );\n\t\t$order->delete_meta_data( '_genosys_receipt_id' );\n\t\t$unlinked = true;\n\t\tif ( ! $order->save() ) {\n\t\t\tthrow new RuntimeException( 'receipt_unlink' );\n\t\t}\n\t\t$order->read_meta_data( true );\n\t\tif ( 0 !== absint( $order->get_meta( '_genosys_receipt_id', true ) ) ) {\n\t\t\tthrow new RuntimeException( 'receipt_unlink' );\n\t\t}\n\t\tgenosys_receipt_delete_record( $receipt_id );\n\t\tclean_post_cache( $receipt_id );\n\t\tif ( get_post( $receipt_id ) || ( $path && is_file( $path ) ) ) {\n\t\t\tthrow new RuntimeException( 'receipt_cleanup' );\n\t\t}\n\t\treturn true;\n\t} catch ( Throwable $exception ) {\n\t\t// Restore the link only when a failed deletion left the original record intact.\n\t\t$post = get_post( $receipt_id );\n\t\tif ( $unlinked && $order && $post && 'genosys_receipt' === $post->post_type && 'private' === $post->post_status && (int) get_post_meta( $receipt_id, '_genosys_order_id', true ) === $order_id ) {\n\t\t\ttry {\n\t\t\t\t$order->read_meta_data( true );\n\t\t\t\tif ( 0 === absint( $order->get_meta( '_genosys_receipt_id', true ) ) ) {\n\t\t\t\t\t$order->update_meta_data( '_genosys_receipt_id', $receipt_id );\n\t\t\t\t\t$order->save();\n\t\t\t\t}\n\t\t\t} catch ( Throwable $restore_error ) {\n\t\t\t\t// Keep the private record and file available during a database failure.\n\t\t\t}\n\t\t}\n\t\treturn new WP_Error( 'receipt_delete', 'حذف فیش کامل نشد. صفحه را تازه‌سازی و دوباره تلاش کنید.' );\n\t} finally {\n\t\tgenosys_receipt_unlock( $lock );\n\t}\n}\n\n/** Read a single request value without allowing array inputs into string functions. */\nfunction genosys_receipt_request_string( $source, $key ) {\n\treturn isset( $source[ $key ] ) && is_scalar( $source[ $key ] ) ? sanitize_text_field( wp_unslash( (string) $source[ $key ] ) ) : '';\n}\n\n/** The same authorized history grants receipt access; guest keys remain supported. */\nfunction genosys_receipt_customer_authorized( $order, $order_key = '' ) {\n\tif ( ! genosys_order_access_valid_order( $order ) ) {\n\t\treturn false;\n\t}\n\tif ( genosys_order_access_can_view( $order ) ) {\n\t\treturn true;\n\t}\n\t// A registered customer's orders require that account's identity. A guest's\n\t// private received-page link remains usable on another browser.\n\tif ( 0 !== (int) $order->get_customer_id() ) {\n\t\treturn false;\n\t}\n\t$saved_key = (string) $order->get_order_key();\n\treturn '' !== $saved_key && '' !== $order_key && hash_equals( $saved_key, (string) $order_key );\n}\n\n/** Receipt display belongs to card-transfer orders, independent of review state. */\nfunction genosys_receipt_order_supports_receipts( $order ) {\n\treturn $order && 'genosys_card_to_card' === $order->get_payment_method() && ! $order->has_status( 'trash' );\n}\n\n/** Only missing or rejected receipts on non-cancelled orders may be changed. */\nfunction genosys_receipt_order_is_eligible( $order ) {\n\tif ( ! genosys_receipt_order_supports_receipts( $order ) || $order->has_status( 'cancelled' ) ) {\n\t\treturn false;\n\t}\n\t$receipt = genosys_receipt_get_current( $order );\n\treturn ! $receipt || 'rejected' === $receipt['reviewStatus'];\n}\n\n/** Resolve the dedicated storage directory, optionally creating its protection files. */\nfunction genosys_receipt_storage_directory( $create = fal