));genosys_settings_field('categories_brand_url','پیوند برند','url',array('hint'=>'خالی یعنی مقصد فعلی')); echo '</div></section>';\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'payment':\n\t\t\t\t\tgenosys_settings_card_open( 'اطلاعات کارت به کارت', 'همین اطلاعات در تسویه‌حساب و سفارش‌های بدون فیش نمایش داده می‌شود.' ); echo '<div class=\"gs-grid\">';\n\t\t\t\t\tforeach(array('genosys_checkout_card_number'=>'شماره کارت','genosys_checkout_card_holder'=>'نام و نام خانوادگی صاحب کارت','genosys_checkout_bank_name'=>'نام بانک','genosys_checkout_whatsapp'=>'شماره واتساپ') as $key=>$label){genosys_settings_field($key,$label,'text',array('name'=>$key,'value'=>get_option($key,''),'ltr'=>in_array($key,array('genosys_checkout_card_number','genosys_checkout_whatsapp'),true)));} echo '</div></section>';\n\t\t\t\t\tgenosys_settings_card_open( 'هزینه ارسال', 'هزینه با واحد پول تنظیم‌شده در ووکامرس محاسبه می‌شود.' );echo '<div class=\"gs-grid\">'; genosys_settings_field('genosys_shipping_cost','هزینه ارسال','text',array('name'=>'genosys_shipping_cost','value'=>get_option('genosys_shipping_cost',''),'ltr'=>true,'hint'=>'صفر یعنی ارسال رایگان؛ کادر خالی هزینه‌های فعلی ووکامرس را حفظ می‌کند.'));echo '</div></section>';\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'orders':\n\t\t\t\t\tgenosys_settings_card_open( 'سفارشات', 'عنوان صفحه پیگیری سفارش‌ها و دسترسی به مدیریت سفارش و فیش.' );echo '<div class=\"gs-grid\">';genosys_settings_field('orders_title','عنوان صفحه سفارشات');echo '</div><div class=\"gs-card__actions\">'; genosys_settings_link(admin_url(class_exists('Automattic\\WooCommerce\\Utilities\\OrderUtil') && \\Automattic\\WooCommerce\\Utilities\\OrderUtil::custom_orders_table_usage_is_enabled()?'admin.php?page=wc-orders':'edit.php?post_type=shop_order'),'مدیریت سفارشات');genosys_settings_link(admin_url('admin.php?page=genosys-payment-receipts'),'فیش‌های واریزی');echo '</div></section>';\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'sms':\n\t\t\t\t\tgenosys_settings_card_open( 'اتصال به سرویس', 'اطلاعات پنل پیامکی شما برای ارسال کد ورود و اطلاع‌رسانی سفارش‌ها.' ); echo '<div class=\"gs-grid\">';genosys_settings_field('sms_provider','ارائه‌دهنده','text',array('name'=>'','value'=>'sms.ir','readonly'=>true));\n\t\t\t\t\t$key_constant=defined('GENOSYS_SMSIR_API_KEY');$key_set=function_exists('genosys_sms_api_key') && ''!==genosys_sms_api_key();\n\t\t\t\t\tgenosys_settings_field('sms_api_key','کلید API','password',array('name'=>'sms_api_key','value'=>'','autocomplete'=>'new-password','readonly'=>$key_constant,'placeholder'=>$key_set?'••••••••••••••••':'کلید API را وارد کنید','hint'=>$key_constant?'کلید از wp-config.php خوانده می‌شود.':'خالی بگذارید تا کلید ذخیره‌شده حفظ شود.'));echo '</div></section>';\n\t\t\t\t\tgenosys_settings_card_open( 'کد تایید ورود', 'تنظیمات قالب پیامک ورود؛ تعداد ارقام و زمان اعتبار مطابق سیستم فعلی است.' );echo '<div class=\"gs-grid\">';genosys_settings_field('sms_template','شناسه قالب ورود','number',array('name'=>'sms_template','value'=>genosys_sms_template_id(),'min'=>1,'max'=>2147483647));genosys_settings_field('sms_parameter','نام متغیر کد در قالب','text',array('name'=>'sms_parameter','value'=>genosys_sms_parameter_name(),'ltr'=>true));genosys_settings_field('otp_digits','تعداد ارقام کد','text',array('name'=>'','value'=>'6','readonly'=>true));genosys_settings_field('otp_duration','مدت اعتبار کد (ثانیه)','text',array('name'=>'','value'=>'120','readonly'=>true));echo '</div><div class=\"gs-card__actions\">';genosys_settings_link(admin_url('options-general.php?page=genosys-sms-login'),'تنظیم شماره ورود مدیر');echo '</div></section>';\n\t\t\t\t\tgenosys_settings_card_open( 'اطلاع‌رسانی سفارش و فیش', 'کادر خالی، فقط پیامک همان رویداد را غیرفعال می‌کند. کلید API بین همه قالب‌ها مشترک است.' );echo '<div class=\"gs-grid\">';\n\t\t\t\t\tforeach(array('genosys_order_sms_template_id'=>array('شناسه قالب پیامک ثبت سفارش','متغیرها: NAME، ORDERID، DATE (شمسی)'), 'genosys_order_status_sms_template_id'=>array('شناسه قالب پیامک تغییر وضعیت سفارش','متغیرها: NAME، STATUS'), 'genosys_receipt_approved_sms_template_id'=>array('شناسه قالب پیامک تایید فیش','متغیر: NAME'), 'genosys_receipt_rejected_sms_template_id'=>array('شناسه قالب پیامک رد فیش','متغیر: NAME')) as $key=>$data){genosys_settings_field($key,$data[0],'text',array('name'=>$key,'value'=>get_option($key,''),'ltr'=>true,'hint'=>$data[1]));}echo '</div></section>';\n\t\t\t\t\tgenosys_settings_card_open( 'پیامک گروهی باشگاه', 'ذخیره تنظیمات هیچ پیامکی ارسال نمی‌کند. متن و گیرنده‌ها در صفحه اعضای باشگاه انتخاب و پیش از ارسال بررسی می‌شوند.' ); echo '<div class=\"gs-grid\">';\n\t\t\t\t\tgenosys_settings_field( 'club_sms_sender','شماره خط ارسال باشگاه','text',array('name'=>'club_sms_sender','value'=>function_exists('genosys_club_sms_sender')?genosys_club_sms_sender():'','ltr'=>true,'readonly'=>defined('GENOSYS_CLUB_SMS_SENDER'),'hint'=>defined('GENOSYS_CLUB_SMS_SENDER')?'خط ارسال از wp-config.php خوانده می‌شود.':'شماره خط فعال در SMS.ir؛ خالی یعنی پیامک گروهی غیرفعال.') ); echo '</div><div class=\"gs-card__actions\">'; genosys_settings_link( admin_url('admin.php?page=genosys-club-members'), 'مدیریت اعضا و پیامک گروهی' ); echo '</div></section>';\n\t\t\t\t\tbreak;\n\t\t\t\tcase 'club':\n\t\t\t\t\tgenosys_settings_card_open( 'انتخاب نوع عضویت', 'هر دو پرسشنامه در دسترس می‌مانند؛ فقط گزینه‌ای را انتخاب کنید که هنگام باز شدن صفحه نمایش داده شود.' ); echo '<div class=\"gs-grid\">';\n\t\t\t\t\tgenosys_settings_field( 'club_default_audience','نوع عضویت پیش‌فرض','select',array('options'=>array('clinic'=>'کلینیک‌ها و بیوتی تراپیست‌ها','consumer'=>'مصرف‌کننده')) );\n\t\t\t\t\tgenosys_settings_field( 'club_consumer_label','متن گزینه مصرف‌کننده' ); genosys_settings_field( 'club_clinic_label','متن گزینه کلینیک‌ها' ); echo '</div><div class=\"gs-card__actions\">'; genosys_settings_link( admin_url('admin.php?page=genosys-club-members'), 'مدیریت اعضای باشگاه' ); echo '</div></section>';\n\t\t\t\t\tgenosys_settings_card_open( 'معرفی برای مصرف‌کنندگان', 'این متن‌ها پس از انتخاب گزینه مصرف‌کننده در صفحه باشگاه نمایش داده می‌شوند.' );echo '<div class=\"gs-grid\">';foreach(array('club_eyebrow'=>'متن بالای عنوان','club_title_before'=>'ابتدای عنوان','club_title_highlight'=>'بخش رنگی عنوان','club_title_after'=>'ادامه عنوان','club_description_line1'=>'خط اول معرفی','club_description_line2'=>'خط دوم معرفی','club_form_title'=>'عنوان پرسشنامه','club_form_description'=>'توضیح پرسشنامه') as $key=>$label){genosys_settings_field($key,$label);}echo '</div></section>';\n\t\t\t\t\tgenosys_settings_card_open( 'معرفی برای کلینیک‌ها و بیوتی تراپیست‌ها', 'متن معرفی و عنوان پرسشنامه همکاری حرفه‌ای؛ سوال‌ها و ثبت اطلاعات تغییری نمی‌کنند.' );echo '<div class=\"gs-grid\">';foreach(array('clinic_eyebrow'=>'متن بالای عنوان','clinic_title_before'=>'ابتدای عنوان','clinic_title_highlight'=>'بخش رنگی عنوان','clinic_title_after'=>'ادامه عنوان','clinic_description_line1'=>'خط اول معرفی','clinic_description_line2'=>'خط دوم معرفی','clinic_form_title'=>'عنوان پرسشنامه','clinic_form_description'=>'توضیح پرسشنامه') as $key=>$label){genosys_settings_field($key,$label);}echo '</div></section>';\n\t\t\t\t\tbreak;\n\t\t\t}\n\t\t\t?>\n\t\t\t</div>\n\t\t\t<?php endforeach; ?>\n\t\t\t<div class=\"gs-savebar\"><span data-dirty-label role=\"status\" aria-live=\"polite\">همه تغییرات ذخیره شده‌اند</span><button type=\"submit\" class=\"gs-save\">ذخیره تغییرات</button></div>\n\t\t</form>\n\t</div>\n\t<?php\n}\n","sha256":"4ecaabc6957eb12ea8139caaeb3dc4709cff9804a0a488d6f48d8cfc63d57f6c"},"inc/shop.php":{"content":"<?php\n/** Shop presentation filters layered onto WooCommerce's native main query. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_shop_ascii_digits( $value ) {\n\treturn strtr( (string) $value, array(\n\t\t'۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',\n\t\t'۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',\n\t\t'٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',\n\t\t'٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',\n\t\t'٫' => '.',\n\t) );\n}\n\n/** Blank or malformed prices never become an accidental zero-price filter. */\nfunction genosys_shop_price( $value ) {\n\tif ( ! is_scalar( $value ) || is_bool( $value ) ) {\n\t\treturn '';\n\t}\n\t$value = genosys_shop_ascii_digits( trim( (string) $value ) );\n\t$value = preg_replace( '/[\\s\\x{00A0}\\x{200C}\\x{202F},٬،]+/u', '', $value );\n\tif ( ! is_string( $value ) || ! preg_match( '/^\\d+(?:\\.\\d+)?$/D', $value ) ) {\n\t\treturn '';\n\t}\n\tlist( $whole, $fraction ) = array_pad( explode( '.', $value, 2 ), 2, '' );\n\t$whole = ltrim( $whole, '0' );\n\t$whole = '' === $whole ? '0' : $whole;\n\t$fraction = rtrim( $fraction, '0' );\n\t$decimals = function_exists( 'wc_get_price_decimals' ) ? max( 0, (int) wc_get_price_decimals() ) : 2;\n\tif ( strlen( $whole ) > 15 || strlen( $fraction ) > $decimals ) {\n\t\treturn '';\n\t}\n\treturn $whole . ( '' === $fraction ? '' : '.' . $fraction );\n}\n\nfunction genosys_shop_category_ids( $values ) {\n\tif ( ! is_array( $values ) || ! taxonomy_exists( 'product_cat' ) ) {\n\t\treturn array();\n\t}\n\t$ids = array();\n\tforeach ( $values as $value ) {\n\t\tif ( ! is_scalar( $value ) || is_bool( $value ) ) {\n\t\t\tcontinue;\n\t\t}\n\t\t$value = genosys_shop_ascii_digits( trim( (string) $value ) );\n\t\tif ( preg_match( '/^[1-9][0-9]{0,9}$/D', $value ) && (float) $value <= 2147483647 ) {\n\t\t\t$ids[] = (int) $value;\n\t\t}\n\t}\n\t$ids = array_values( array_unique( $ids ) );\n\tif ( ! $ids ) {\n\t\treturn array();\n\t}\n\t$found = get_terms( array( 'taxonomy' => 'product_cat', 'hide_empty' => false, 'include' => $ids, 'fields' => 'ids' ) );\n\tif ( is_wp_error( $found ) ) {\n\t\treturn array();\n\t}\n\t// Keep the customer's selection order while rejecting IDs from other taxonomies.\n\treturn array_values( array_intersect( $ids, array_map( 'intval', $found ) ) );\n}\n\nfunction genosys_shop_switch( $value ) {\n\treturn is_scalar( $value ) && in_array( strtolower( trim( (string) $value ) ), array( '1', 'on', 'yes', 'true' ), true );\n}\n\n/** Public template contract: IDs, decimal strings, booleans and a native sort key. */\nfunction genosys_shop_normalize_filters( $values ) {\n\t$values = is_array( $values ) ? $values : array();\n\t$orderby = isset( $values['orderby'] ) && is_string( $values['orderby'] ) ? trim( $values['orderby'] ) : 'date';\n\tif ( ! in_array( $orderby, array( 'date', 'popularity', 'rating', 'price', 'price-desc', 'menu_order' ), true ) ) {\n\t\t$orderby = 'date';\n\t}\n\t$minimum = genosys_shop_price( $values['min_price'] ?? '' );\n\t$maximum = genosys_shop_price( $values['max_price'] ?? '' );\n\tif ( '' !== $minimum && '' !== $maximum && (float) $minimum > (float) $maximum ) {\n\t\tlist( $minimum, $maximum ) = array( $maximum, $minimum );\n\t}\n\treturn array(\n\t\t'categories' => genosys_shop_category_ids( $values['categories'] ?? ( $values['shop_cat'] ?? array() ) ),\n\t\t'min_price' => $minimum,\n\t\t'max_price' => $maximum,\n\t\t'only_in_stock' => genosys_shop_switch( $values['only_in_stock'] ?? false ),\n\t\t'only_on_sale' => genosys_shop_switch( $values['only_on_sale'] ?? false ),\n\t\t'orderby' => $orderby,\n\t);\n}\n\nfunction genosys_shop_filters() {\n\t// These controls are read-only catalogue filters; no mutation or nonce is involved.\n\treturn genosys_shop_normalize_filters( wp_unslash( $_GET ) ); // phpcs:ignore WordPress.Security.NonceVerification.Recommended\n}\n\n/** Identify the shop before WC_Query's priority-10 pre_get_posts processing. */\nfunction genosys_shop_is_main_query( $query ) {\n\tif ( is_admin() || ! $query instanceof WP_Query || ! $query->is_main_query() || $query->is_feed() || $query->is_tax() || ! function_exists( 'wc_get_page_id' ) ) {\n\t\treturn false;\n\t}\n\t$shop_id = wc_get_page_id( 'shop' );\n\treturn $query->is_post_type_archive( 'product' ) || ( $shop_id > 0 && $query->is_page( $shop_id ) ) || ( function_exists( 'genosys_is_product_search' ) && genosys_is_product_search( $query ) );\n}\n\nfunction genosys_shop_query_args( $filters ) {\n\t$args = array( 'orderby' => $filters['orderby'] );\n\tif ( function_exists( 'genosys_is_product_search' ) && genosys_is_product_search() ) {\n\t\t$args['s'] = genosys_product_search_term();\n\t\t$args['post_type'] = 'product';\n\t}\n\tif ( $filters['categories'] ) {\n\t\t$args['shop_cat'] = $filters['categories'];\n\t}\n\tforeach ( array( 'min_price', 'max_price' ) as $key ) {\n\t\tif ( '' !== $filters[ $key ] ) {\n\t\t\t$args[ $key ] = $filters[ $key ];\n\t\t}\n\t}\n\tforeach ( array( 'only_in_stock', 'only_on_sale' ) as $key ) {\n\t\tif ( $filters[ $key ] ) {\n\t\t\t$args[ $key ] = '1';\n\t\t}\n\t}\n\treturn $args;\n}\n\nfunction genosys_shop_prepare_query( $query ) {\n\tif ( ! genosys_shop_is_main_query( $query ) ) {\n\t\treturn;\n\t}\n\t$filters = genosys_shop_filters();\n\t$args = genosys_shop_query_args( $filters );\n\t// Woo reads these values directly from GET; sanitize before its native clauses run.\n\tforeach ( array( 'shop_cat', 'min_price', 'max_price', 'only_in_stock', 'only_on_sale', 'orderby' ) as $key ) {\n\t\tif ( isset( $args[ $key ] ) ) {\n\t\t\t$_GET[ $key ] = $args[ $key ];\n\t\t} else {\n\t\t\tunset( $_GET[ $key ] );\n\t\t}\n\t}\n\t$query->set( 'orderby', $filters['orderby'] );\n\t$query->set( 'posts_per_page', 12 );\n\t$query->set( 'genosys_shop_query', true );\n}\nadd_action( 'pre_get_posts', 'genosys_shop_prepare_query', 1 );\n\n/** Add restrictions without replacing Woo's visibility and extension clauses. */\nfunction genosys_shop_product_query( $query ) {\n\tif ( ! genosys_shop_is_main_query( $query ) ) {\n\t\treturn;\n\t}\n\t$filters = genosys_shop_filters();\n\t$query->set( 'posts_per_page', 12 );\n\tif ( $filters['categories'] ) {\n\t\t$clause = array( 'taxonomy' => 'product_cat', 'field' => 'term_id', 'terms' => $filters['categories'], 'operator' => 'IN', 'include_children' => true );\n\t\t$existing = $query->get( 'tax_query' );\n\t\t$query->set( 'tax_query', $existing ? array( 'relation' => 'AND', $existing, $clause ) : array( $clause ) );\n\t}\n\tif ( $filters['only_in_stock'] ) {\n\t\t$clause = array( 'key' => '_stock_status', 'value' => 'instock', 'compare' => '=' );\n\t\t$existing = $query->get( 'meta_query' );\n\t\t$query->set( 'meta_query', $existing ? array( 'relation' => 'AND', $existing, $clause ) : array( $clause ) );\n\t}\n\tif ( $filters['only_on_sale'] ) {\n\t\t$sale_ids = array_map( 'intval', wc_get_product_ids_on_sale() );\n\t\t$existing = (array) $query->get( 'post__in' );\n\t\t$ids = $existing ? array_values( array_intersect( $existing, $sale_ids ) ) : $sale_ids;\n\t\t$query->set( 'post__in', $ids ? $ids : array( 0 ) );\n\t}\n}\nadd_action( 'woocommerce_product_query', 'genosys_shop_product_query', 20, 1 );\n\n/** Category names, hierarchy and padded counts remain database-backed. */\nfunction genosys_shop_categories() {\n\tif ( ! taxonomy_exists( 'product_cat' ) ) {\n\t\treturn array();\n\t}\n\t$terms = get_terms( array( 'taxonomy' => 'product_cat', 'hide_empty' => true, 'orderby' => 'name', 'order' => 'ASC', 'pad_counts' => true ) );\n\tif ( is_wp_error( $terms ) ) {\n\t\treturn array();\n\t}\n\t// The database name sort orders siblings; traverse parents before their children.\n\t$children = array();\n\tforeach ( $terms as $term ) {\n\t\t$children[ (int) $term->parent ][] = $term;\n\t}\n\t$ordered = array();\n\t$seen = array();\n\t$walk = function ( $parent ) use ( &$walk, &$ordered, &$seen, $children ) {\n\t\tforeach ( $children[ $parent ] ?? array() as $term ) {\n\t\t\tif ( isset( $seen[ $term->term_id ] ) ) {\n\t\t\t\tcontinue;\n\t\t\t}\n\t\t\t$seen[ $term->term_id ] = true;\n\t\t\t$ordered[] = $term;\n\t\t\t$walk( $term->term_id );\n\t\t}\n\t};\n\t$walk( 0 );\n\t// Retain terms if an extension excluded their parent from this result set.\n\tforeach ( $terms as $term ) {\n\t\tif ( ! isset( $seen[ $term->term_id ] ) ) {\n\t\t\t$seen[ $term->term_id ] = true;\n\t\t\t$ordered[] = $term;\n\t\t\t$walk( $term->term_id );\n\t\t}\n\t}\n\treturn $ordered;\n}\n\n/** Reuse Woo's lookup aggregate, tax adjustments and widget extension filters. */\nfunction genosys_shop_price_bounds() {\n\tstatic $bounds = null;\n\tif ( null !== $bounds ) {\n\t\treturn $bounds;\n\t}\n\t$bounds = array( 'min' => 0.0, 'max' => 0.0, 'step' => 1.0 );\n\tif ( ! function_exists( 'WC' ) || ! WC()->query || ! WC()->query->get_main_query() || ! class_exists( 'WC_Widget_Price_Filter' ) ) {\n\t\treturn $bounds;\n\t}\n\tif ( ! class_exists( 'Genosys_Shop_Price_Lookup', false ) ) {\n\t\tclass Genosys_Shop_Price_Lookup extends WC_Widget_Price_Filter {\n\t\t\t// No widget registration or unrelated slider assets are needed by this view.\n\t\t\tpublic function __construct() {}\n\t\t\tpublic function bounds() { return $this->get_filtered_price(); }\n\t\t}\n\t}\n\t$prices = ( new Genosys_Shop_Price_Lookup() )->bounds();\n\tif ( ! $prices || null === $prices->min_price || null === $prices->max_price ) {\n\t\treturn $bounds;\n\t}\n\t$minimum = (float) $prices->min_price;\n\t$maximum = (float) $prices->max_price;\n\tif ( wc_tax_enabled() && ! wc_prices_include_tax() && 'incl' === get_option( 'woocommerce_tax_display_shop' ) ) {\n\t\t$tax_class = apply_filters( 'woocommerce_price_filter_widget_tax_class', '' );\n\t\t$rates = WC_Tax::get_rates( $tax_class );\n\t\tif ( $rates ) {\n\t\t\t$minimum += WC_Tax::get_tax_total( WC_Tax::calc_exclusive_tax( $minimum, $rates ) );\n\t\t\t$maximum += WC_Tax::get_tax_total( WC_Tax::calc_exclusive_tax( $maximum, $rates ) );\n\t\t}\n\t}\n\t$step = max( 1.0, (float) apply_filters( 'woocommerce_price_filter_widget_step', 10 ) );\n\t$minimum = (float) apply_filters( 'woocommerce_price_filter_widget_min_amount', floor( $minimum / $step ) * $step );\n\t$maximum = (float) apply_filters( 'woocommerce_price_filter_widget_max_amount', ceil( $maximum / $step ) * $step );\n\t$bounds = array( 'min' => max( 0.0, $minimum ), 'max' => max( $minimum, $maximum, 0.0 ), 'step' => $step );\n\treturn $bounds;\n}\n\n/** Clean native pagination URLs so malformed original GET data cannot reappear. */\nfunction genosys_shop_pagenum_link( $url ) {\n\tif ( is_admin() || ! function_exists( 'is_shop' ) || ( ! is_shop() && ! ( function_exists( 'genosys_is_product_search' ) && genosys_is_product_search() ) ) ) {\n\t\treturn $url;\n\t}\n\t$url = remove_query_arg( array( 'shop_cat', 'min_price', 'max_price', 'only_in_stock', 'only_on_sale', 'orderby', 'add-to-cart' ), $url );\n\treturn add_query_arg( genosys_shop_query_args( genosys_shop_filters() ), $url );\n}\nadd_filter( 'get_pagenum_link', 'genosys_shop_pagenum_link', 20 );\n\n/** Preserve native permalink pagination and any independent extension filters. */\nfunction genosys_shop_url( $overrides = array(), $page = 1 ) {\n\t$values = genosys_shop_filters();\n\tforeach ( is_array( $overrides ) ? $overrides : array() as $key => $value ) {\n\t\t$key = 'shop_cat' === $key ? 'categories' : $key;\n\t\tif ( array_key_exists( $key, $values ) ) {\n\t\t\t$values[ $key ] = $value;\n\t\t}\n\t}\n\t$filters = genosys_shop_normalize_filters( $values );\n\t$page = max( 1, absint( $page ) );\n\tif ( function_exists( 'is_shop' ) && ( is_shop() || ( function_exists( 'genosys_is_product_search' ) && genosys_is_product_search() ) ) ) {\n\t\t$url = get_pagenum_link( $page, false );\n\t} else {\n\t\t$url = function_exists( 'wc_get_page_permalink' ) ? wc_get_page_permalink( 'shop' ) : home_url( '/shop/' );\n\t\tif ( $page > 1 ) {\n\t\t\t$url = add_query_arg( 'paged', $page, $url );\n\t\t}\n\t}\n\t$url = remove_query_arg( array( 'shop_cat', 'min_price', 'max_price', 'only_in_stock', 'only_on_sale', 'orderby', 'add-to-cart' ), $url );\n\treturn add_query_arg( genosys_shop_query_args( $filters ), $url );\n}\n\nfunction genosys_shop_pagination() {\n\tglobal $wp_query;\n\t$total = $wp_query instanceof WP_Query ? (int) $wp_query->max_num_pages : 0;\n\tif ( $total <= 1 ) {\n\t\treturn array();\n\t}\n\t$big = 999999999;\n\t$args = apply_filters( 'woocommerce_pagination_args', array(\n\t\t'base' => esc_url_raw( str_replace( (string) $big, '%#%', genosys_shop_url( array(), $big ) ) ),\n\t\t'format' => '',\n\t\t'add_args' => false,\n\t\t'current' => max( 1, (int) get_query_var( 'paged' ), (int) get_query_var( 'page' ) ),\n\t\t'total' => $total,\n\t\t'prev_text' => 'قبلی',\n\t\t'next_text' => 'بعدی',\n\t\t'type' => 'array',\n\t\t'end_size' => 1,\n\t\t'mid_size' => 2,\n\t) );\n\t$args['type'] = 'array';\n\t$links = paginate_links( $args );\n\treturn is_array( $links ) ? $links : array();\n}\n\nfunction genosys_shop_template( $template ) {\n\tif ( ! is_admin() && function_exists( 'is_shop' ) && ( is_shop() || ( function_exists( 'genosys_is_product_search' ) && genosys_is_product_search() ) ) ) {\n\t\t$shop_template = get_theme_file_path( '/page-shop.php' );\n\t\tif ( is_readable( $shop_template ) ) {\n\t\t\treturn $shop_template;\n\t\t}\n\t}\n\treturn $template;\n}\nadd_filter( 'template_include', 'genosys_shop_template', 99 );\n\nfunction genosys_shop_assets() {\n\tif ( ! function_exists( 'is_shop' ) || ( ! is_shop() && ! ( function_exists( 'genosys_is_product_search' ) && genosys_is_product_search() ) ) ) {\n\t\treturn;\n\t}\n\twp_enqueue_style( 'genosys-products', get_theme_file_uri( '/assets/css/products.css' ), array( 'genosys-style' ), '1.5.80' );\n\twp_enqueue_script( 'genosys-favorites', get_theme_file_uri( '/assets/js/favorites.js' ), array(), '1.4.0', true );\n\twp_enqueue_style( 'genosys-shop', get_theme_file_uri( '/assets/css/shop.css' ), array( 'genosys-products' ), '1.5.49' );\n\twp_enqueue_script( 'genosys-shop', get_theme_file_uri( '/assets/js/shop.js' ), array(), '1.5.46', true );\n}\nadd_action( 'wp_enqueue_scripts', 'genosys_shop_assets', 20 );\n","sha256":"a3f1cf2aff95e154a37a7c1a7c0471d6f77025bd7ce2177e6b990b740ca40d51"},"inc/single-product.php":{"content":"<?php\n/** Product-only WooCommerce hooks for the Genosys single-product layout. */\n\ndefined( 'ABSPATH' ) || exit;\n\n/** Change only the related-products row size; WooCommerce still selects its products. */\nfunction genosys_single_product_related_count( $args ) {\n\t$args['posts_per_page'] = max( 1, min( 12, (int) genosys_site_setting( 'product_related_count', 4 ) ) );\n\treturn $args;\n}\nadd_filter( 'woocommerce_output_related_products_args', 'genosys_single_product_related_count', 99 );\n\n/**\n * Keep WooCommerce's native product template lifecycle, cart forms and tabs.\n * Change presentation hooks only on actual single-product requests.\n */\nfunction genosys_single_product_hooks() {\n\tif ( ! function_exists( 'is_product' ) || ! is_product() ) {\n\t\treturn;\n\t}\n\n\t// Use a dedicated page width and the real WooCommerce breadcrumb.\n\tremove_action( 'woocommerce_before_main_content', 'woocommerce_output_content_wrapper', 10 );\n\tremove_action( 'woocommerce_after_main_content', 'woocommerce_output_content_wrapper_end', 10 );\n\tadd_action( 'woocommerce_before_main_content', 'genosys_single_product_wrapper_start', 10 );\n\tadd_action( 'woocommerce_after_main_content', 'genosys_single_product_wrapper_end', 10 );\n\tremove_action( 'woocommerce_sidebar', 'woocommerce_get_sidebar', 10 );\n\n\t// The stock/gallery badge replaces WooCommerce's unstyled sale flash.\n\tremove_action( 'woocommerce_before_single_product_summary', 'woocommerce_show_product_sale_flash', 10 );\n\tadd_action( 'woocommerce_before_single_product_summary', 'genosys_single_product_badge', 5 );\n\n\t// Reorder only the visual information: category, name, excerpt, then price.\n\tadd_action( 'woocommerce_single_product_summary', 'genosys_single_product_category', 1 );\n\tremove_action( 'woocommerce_single_product_summary', 'woocommerce_template_single_price', 10 );\n\tadd_action( 'woocommerce_single_product_summary', 'genosys_single_product_price', 25 );\n\tremove_action( 'woocommerce_single_product_summary', 'woocommerce_template_single_meta', 40 );\n\tadd_action( 'woocommerce_single_product_summary', 'genosys_single_product_sku', 29 );\n}\nadd_action( 'wp', 'genosys_single_product_hooks' );\n\nfunction genosys_single_product_wrapper_start() {\n\techo '<main id=\"main\" class=\"genosys-product-page\" tabindex=\"-1\">';\n}\n\nfunction genosys_single_product_wrapper_end() {\n\techo '</main>';\n}\n\n/** Show a category from the current product, preferring a real category. */\nfunction genosys_single_product_category() {\n\tglobal $product;\n\tif ( ! $product instanceof WC_Product ) {\n\t\treturn;\n\t}\n\n\t$terms = get_the_terms( $product->get_id(), 'product_cat' );\n\tif ( empty( $terms ) || is_wp_error( $terms ) ) {\n\t\treturn;\n\t}\n\n\t$default_id = (int) get_option( 'default_product_cat' );\n\t$chosen     = null;\n\tforeach ( $terms as $term ) {\n\t\tif ( (int) $term->term_id !== $default_id ) {\n\t\t\t$chosen = $term;\n\t\t\tbreak;\n\t\t}\n\t}\n\tif ( ! $chosen ) {\n\t\t$chosen = reset( $terms );\n\t}\n\n\t$link = get_term_link( $chosen );\n\tif ( is_wp_error( $link ) ) {\n\t\treturn;\n\t}\n\techo '<a class=\"genosys-product__category\" href=\"' . esc_url( $link ) . '\">' . esc_html( $chosen->name ) . '</a>';\n}\n\n/** Keep WooCommerce's formatted price data, including variable ranges and sale markup. */\nfunction genosys_single_product_price() {\n\tglobal $product;\n\tif ( ! $product instanceof WC_Product ) {\n\t\treturn;\n\t}\n\n\t$is_available = $product->is_in_stock();\n\t$price_html   = genosys_product_price_html( $product );\n\t$discount     = genosys_product_discount( $product );\n\t$show_sale    = $is_available && $product->is_on_sale();\n\n\techo '<div class=\"genosys-product__price\" data-product-type=\"' . esc_attr( $product->get_type() ) . '\">';\n\techo '<p class=\"price' . ( $is_available ? '' : ' genosys-product__price--unavailable' ) . '\">';\n\tif ( ! $is_available ) {\n\t\techo esc_html( 'تماس بگیرید' );\n\t} elseif ( $price_html ) {\n\t\techo wp_kses_post( $price_html );\n\t} else {\n\t\techo esc_html( 'اطلاعات قیمت موجود نیست' );\n\t}\n\techo '</p>';\n\techo '<span class=\"genosys-product__discount\"' . ( $show_sale ? '' : ' hidden' ) . '>';\n\techo $show_sale ? esc_html( $discount ? genosys_persian_number( $discount ) . '٪ تخفیف' : 'تخفیف' ) : '';\n\techo '</span>';\n\techo '</div>';\n}\n\n/** Actual stock/sale state from WooCommerce, layered over its real gallery. */\nfunction genosys_single_product_badge() {\n\tglobal $product;\n\tif ( ! $product instanceof WC_Product ) {\n\t\treturn;\n\t}\n\n\t$is_in_stock = $product->is_in_stock();\n\t$is_on_sale  = $is_in_stock && $product->is_on_sale();\n\t$discount    = $is_on_sale ? genosys_product_discount( $product ) : 0;\n\t$label       = ! $is_in_stock ? 'ناموجود' : ( $is_on_sale ? ( $discount ? genosys_persian_number( $discount ) . '٪ تخفیف' : 'تخفیف' ) : '' );\n\t$classes     = 'genosys-product__gallery-badge' . ( $is_in_stock ? '' : ' genosys-product__gallery-badge--stock' );\n\techo '<span class=\"' . esc_attr( $classes ) . '\"' . ( $label ? '' : ' hidden' ) . '>' . esc_html( $label ) . '</span>';\n}\n\n/** SKU is shown only when it exists; native Woo variation JS can update it. */\nfunction genosys_single_product_sku() {\n\tglobal $product;\n\tif ( ! $product instanceof WC_Product || ! wc_product_sku_enabled() ) {\n\t\treturn;\n\t}\n\n\t$sku = $product->get_sku();\n\tif ( ! $sku && ! $product->is_type( 'variable' ) ) {\n\t\treturn;\n\t}\n\n\techo '<div class=\"product_meta genosys-product__sku\" data-base-sku=\"' . esc_attr( $sku ) . '\">';\n\tdo_action( 'woocommerce_product_meta_start' );\n\techo '<span class=\"sku_wrapper\"' . ( $sku ? '' : ' hidden' ) . '>' . esc_html( 'شناسه محصول: ' ) . '<span class=\"sku\">' . esc_html( $sku ) . '</span></span>';\n\tdo_action( 'woocommerce_product_meta_end' );\n\techo '</div>';\n}\n\n/** Label WooCommerce's existing tabs without changing their callbacks or data. */\nfunction genosys_single_product_tab_labels( $tabs ) {\n\tif ( ! function_exists( 'is_product' ) || ! is_product() ) {\n\t\treturn $tabs;\n\t}\n\tif ( isset( $tabs['description'] ) ) {\n\t\t$tabs['description']['title'] = 'توضیحات';\n\t}\n\tif ( isset( $tabs['additional_information'] ) ) {\n\t\t$tabs['additional_information']['title'] = 'توضیحات تکمیلی';\n\t}\n\tif ( isset( $tabs['reviews'] ) ) {\n\t\tglobal $product;\n\t\t$count = $product instanceof WC_Product ? $product->get_review_count() : 0;\n\t\t$tabs['reviews']['title'] = 'نظرات (' . genosys_persian_number( $count ) . ')';\n\t}\n\treturn $tabs;\n}\nadd_filter( 'woocommerce_product_tabs', 'genosys_single_product_tab_labels', 50 );\n\n/** Use the current product's name as the description section heading. */\nfunction genosys_single_product_description_heading( $heading ) {\n\tif ( ! function_exists( 'is_product' ) || ! is_product() ) {\n\t\treturn $heading;\n\t}\n\tglobal $product;\n\treturn $product instanceof WC_Product ? $product->get_name() : $heading;\n}\nadd_filter( 'woocommerce_product_description_heading', 'genosys_single_product_description_heading' );\n\n/** Keep the native review form, rating input and validation; style its wording. */\nfunction genosys_single_product_review_form( $args ) {\n\tif ( ! function_exists( 'is_product' ) || ! is_product() ) {\n\t\treturn $args;\n\t}\n\t$args['label_submit'] = 'ثبت';\n\tif ( ! empty( $args['comment_field'] ) ) {\n\t\t$args['comment_field'] = preg_replace_callback(\n\t\t\t'/<textarea\\b[^>]*>/i',\n\t\t\tfunction ( $match ) {\n\t\t\t\treturn false !== stripos( $match[0], 'placeholder=' ) ? $match[0] : substr( $match[0], 0, -1 ) . ' placeholder=\"دیدگاه شما\">';\n\t\t\t},\n\t\t\t$args['comment_field'],\n\t\t\t1\n\t\t);\n\t}\n\treturn $args;\n}\nadd_filter( 'woocommerce_product_review_comment_form_args', 'genosys_single_product_review_form', 20 );\n\n/** Match the review heading in both WooCommerce's empty and populated states. */\nfunction genosys_single_product_reviews_title( $title ) {\n\treturn function_exists( 'is_product' ) && is_product() ? 'نقد و بررسی‌ها' : $title;\n}\nadd_filter( 'woocommerce_reviews_title', 'genosys_single_product_reviews_title' );\n\nfunction genosys_single_product_empty_reviews_title( $translation, $text ) {\n\treturn function_exists( 'is_product' ) && is_product() && 'Reviews' === $text ? 'نقد و بررسی‌ها' : $translation;\n}\nadd_filter( 'gettext_woocommerce', 'genosys_single_product_empty_reviews_title', 10, 2 );\n","sha256":"f8db4c480afd3f5e4013ae465933154de4a986f74a774d2cd3a785278993d51e"},"inc/site-settings.php":{"content":"<?php\n/** Editable presentation values. Unconfigured values retain the installed design. */\ndefined( 'ABSPATH' ) || exit;\n\nfunction genosys_site_defaults() {\n    static $defaults = null;\n    if ( null !== $defaults ) { return $defaults; }\n    $image = static function ( $file ) { return get_theme_file_uri( '/assets/images/' . $file ); };\n    $defaults = array(\n        'site_name' => 'ژنوسیس', 'site_slogan' => 'Gene Re-birth System',\n        'primary_color' => '#c8103b', 'deep_color' => '#9f1536',\n        'header_logo_home' => '', 'header_logo_internal' => '', 'header_height' => 100,\n        'header_show_search' => 'auto', 'header_show_account' => 'auto', 'header_show_cart' => 'auto',\n        'header_search_placeholder' => 'نام محصول یا کد SKU...', 'header_login_text' => 'ورود / ثبت‌نام',\n        'header_icon_color_home' => '#f4f6f7', 'header_icon_color_internal' => '#3b4553', 'header_icon_hover' => '#c8103b',\n        'header_link_color_home' => '#f4f6f7', 'header_link_color_internal' => '#3b4553',\n        'header_link_hover_home' => '#f2a5b8', 'header_link_hover_internal' => '#c8103b',\n        'header_background_home' => '', 'header_background_internal' => '#ffffff',\n        'mobile_menu_background' => '', 'mobile_menu_color' => '#e9edef', 'mobile_menu_hover' => '#efafc0',\n        'slider_interval' => 6000,\n        'brand_video_id' => 0,\n        'slides' => array(\n            array( 'image' => $image( 'banner-01-skincare-1.2.2.webp' ), 'alt' => 'مجموعه کرم‌ها و محصولات مراقبت از پوست ژنوسیس روی پایه‌های سفید', 'class' => 'slide-skincare', 'title' => '', 'link' => '' ),\n            array( 'image' => $image( 'banner-02-eco-gel-1.2.2.webp' ), 'alt' => 'ژل مراقبت از پوست ژنوسیس در کنار گوی‌های شفاف و قطره‌های ژل', 'class' => 'slide-eco', 'title' => '', 'link' => '' ),\n            array( 'image' => $image( 'banner-03-hair-1.2.2.webp' ), 'alt' => 'محصولات مراقبت از مو و دستگاه ژنوسیس در برابر دیوار گرم و روشن', 'class' => 'slide-hair', 'title' => '', 'link' => '' ),\n            array( 'image' => $image( 'banner-04-roller-1.2.2.webp' ), 'alt' => 'درمارولر ژنوسیس و ویال‌های مراقبت از پوست روی سطح سنگی روشن', 'class' => 'slide-ampoules', 'title' => '', 'link' => '' ),\n        ),\n        'home_sections' => array(\n            array( 'id' => 'slider', 'visible' => 1 ), array( 'id' => 'cards', 'visible' => 1 ),\n            array( 'id' => 'latest', 'visible' => 1 ), array( 'id' => 'categories', 'visible' => 1 ), array( 'id' => 'featured', 'visible' => 1 ),\n        ),\n        'club_card_image' => '', 'club_card_title' => 'باشگاه مشتریان', 'club_card_button' => 'ورود به باشگاه', 'club_card_url' => '',\n        'products_card_image' => '', 'products_card_title' => 'محصولات ژنوسیس', 'products_card_button' => 'مشاهده محصولات', 'products_card_url' => '',\n        'latest_title' => 'جدیدترین محصولات', 'latest_count' => 8, 'latest_all_text' => 'مشاهده همه',\n        'categories_title' => 'مراقبتی که', 'categories_highlight' => 'مخصوص شماست',\n        'categories_description' => 'با محصولات تخصصی ژنوسیس، پوست و موی خود را به متخصصان بسپارید.',\n        'categories_button' => 'مشاهده دسته‌بندی‌ها', 'categories_brand_text' => 'یا با برند ما آشنا شوید', 'categories_brand_url' => '',\n        'category_cards' => array(\n            array( 'title' => 'مراقبت مو و پوست سر', 'image' => $image( 'category-hair-1.5.7.webp' ), 'size' => 'short', 'term_id' => 0, 'terms' => array( 'مراقبت مو و پوست سر', 'مراقبت از مو و پوست سر', 'محصولات مو' ) ),\n            array( 'title' => 'مراقبت پوست', 'image' => $image( 'category-skin-1.5.7.webp' ), 'size' => 'tall', 'term_id' => 0, 'terms' => array( 'مراقبت پوست', 'مراقبت از پوست', 'محصولات مراقبت از پوست' ) ),\n            array( 'title' => 'ضد آفتاب‌ها', 'image' => $image( 'category-sun-1.5.7.webp' ), 'size' => 'short', 'term_id' => 0, 'terms' => array( 'ضد آفتاب‌ها', 'ضد آفتاب', 'ضدآفتاب' ) ),\n            array( 'title' => 'میست و اسپری', 'image' => $image( 'category-mist-1.5.7.webp' ), 'size' => 'tall', 'term_id' => 0, 'terms' => array( 'میست و اسپری', 'میست', 'اسپری' ) ),\n            array( 'title' => 'محصولات آرایشی', 'image' => $image( 'category-makeup-1.5.7.webp' ), 'size' => 'short', 'term_id' => 0, 'terms' => array( 'محصولات آرایشی', 'آرایش', 'محصولات آرایش' ) ),\n            array( 'title' => 'مراقبت دور چشم', 'image' => $image( 'category-eye-1.5.7.webp' ), 'size' => 'tall', 'term_id' => 0, 'terms' => array( 'مراقبت دور چشم', 'محصولات دور چشم', 'دور چشم' ) ),\n        ),\n        'stats_visible' => 1,\n        'stats' => array(\n            array( 'count' => 16, 'label' => 'سال سابقه', 'icon' => 'calendar' ),\n            array( 'count' => 2000, 'label' => 'مشتری ثابت', 'icon' => 'people' ),\n            array( 'count' => 50, 'label' => 'محصول تخصصی', 'icon' => 'flask' ),\n            array( 'count' => 50, 'label' => 'کشور جهان', 'icon' => 'globe' ),\n        ),\n        'featured_eyebrow' => 'فروشگاه ژنوسیس', 'featured_title' => 'محصولات', 'featured_highlight' => 'منتخب', 'featured_suffix' => 'ما',\n        'featured_description' => 'دسته‌بندی موردنظرتان را انتخاب کنید و محصولات پرفروش آن را ببینید.',\n        'featured_link_text' => 'مشاهده‌ی تمامی دسته‌بندی‌ها', 'featured_count' => 6,\n        'featured_tabs' => array(\n            array( 'label' => 'پکیج‌های ویژه', 'term_id' => 0, 'names' => array( 'پکیج‌های ویژه', 'پکیج های ویژه', 'پکیج ویژه' ) ),\n            array( 'label' => 'آبرسان‌ها', 'term_id' => 0, 'names' => array( 'آبرسان‌ها', 'آبرسان ها', 'آبرسان' ) ),\n            array( 'label' => 'ضدآفتاب‌ها', 'term_id' => 0, 'names' => array( 'ضدآفتاب‌ها', 'ضد آفتاب‌ها', 'ضد آفتاب ها', 'ضدآفتاب', 'ضد آفتاب' ) ),\n        ),\n        'invitation_line1' => 'بیایید با هم، <em>پوستی</em>', 'invitation_line2' => '<em>درخشان</em> بسازیم',\n        'invitation_button' => 'دریافت کاتالوگ محصولات', 'invitation_url' => '', 'invitation_image' => '',\n        'footer_logo' => '', 'footer_description' => 'ژنوسیس، مراقبت علمی پوست و مو با تکیه بر فناوری بازسازی <br>ژنی.',\n        'footer_contact_text' => 'تماس با ما', 'footer_contact_url' => '',\n        'footer_copyright' => '© ژنوسیس — تمامی حقوق محفوظ است', 'footer_tagline' => 'GENOSYS - Gene Re-birth System',\n        'social_instagram' => '', 'social_telegram' => '', 'social_whatsapp' => '', 'social_linkedin' => '',\n        'shop_title' => 'فروشگاه', 'shop_highlight' => 'ژنوسیس', 'shop_per_page' => 12,\n        'orders_title' => 'سفارشات من',\n        'account_title' => 'حساب کاربری', 'account_profile_label' => 'اطلاعات حساب', 'account_addresses_label' => 'آدرس‌ها',\n        'account_notifications_label' => 'اعلان‌ها', 'account_club_label' => 'باشگاه مشتریان', 'account_orders_label' => 'سفارشات من',\n        'club_eyebrow' => 'باشگاه مشتریان', 'club_title_before' => 'عضو خانواده‌ی', 'club_title_highlight' => 'ژنوسیس', 'club_title_after' => 'شوید',\n        'club_description_line1' => 'پرسشنامه‌ی کوتاه زیر را تکمیل کنید تا مراقبت‌ها و پیشنهادهای ویژه‌ی باشگاه را',\n        'club_description_line2' => 'متناسب با پوست شما آماده کنیم.',\n        'club_form_title' => 'پرسشنامه‌ی عضویت', 'club_form_description' => 'حدود ۲ دقیقه زمان می‌برد. موارد دارای ستاره الزامی است.',\n        'club_default_audience' => 'clinic', 'club_consumer_label' => 'مصرف کننده', 'club_clinic_label' => 'کلینیک ها و بیوتی تراپیست ها',\n        'clinic_eyebrow' => 'باشگاه همکاران حرفه‌ای', 'clinic_title_before' => 'همراه حرفه‌ای', 'clinic_title_highlight' => 'ژنوسیس', 'clinic_title_after' => 'شوید',\n        'clinic_description_line1' => 'نیازهای کلینیک و خدمات حرفه‌ای خود را با ما در میان بگذارید',\n        'clinic_description_line2' => 'تا پیشنهادهای ژنوسیس را متناسب با مشتریان و مصرف مجموعه‌ی شما آماده کنیم.',\n        'clinic_form_title' => 'پرسشنامه‌ی همکاری حرفه‌ای', 'clinic_form_description' => 'کمی از مجموعه و نیازهای کاری خود بگویید. موارد دارای ستاره الزامی است.',\n        'product_cart_animation' => 1, 'product_related_count' => 4,\n        'product_related_title' => '', 'product_description_title' => '', 'product_information_title' => '', 'product_reviews_title' => '',\n    );\n    if ( function_exists( 'genosys_contact_defaults' ) ) { $defaults = array_merge( $defaults, genosys_contact_defaults() ); }\n    return $defaults;\n}\n\n/** Values are merged at read time; updating the panel never installs new storefront defaults. */\nfunction genosys_site_setting( $key, $fallback = null ) {\n    $defaults = genosys_site_defaults();\n    if ( null === $fallback && array_key_exists( $key, $defaults ) ) { $fallback = $defaults[ $key ]; }\n    $values = get_option( 'genosys_site_settings', array() );\n    if ( ! is_array( $values ) || ! array_key_exists( $key, $values ) ) { return $fallback; }\n    $value = $values[ $key ];\n    if ( is_array( $fallback ) ) { return is_array( $value ) ? $value : $fallback; }\n    return is_scalar( $value ) ? $value : $fallback;\n}\n\nfunction genosys_site_url( $key, $fallback ) {\n    $url = genosys_site_setting( $key, '' );\n    return is_string( $url ) && '' !== trim( $url ) ? $url : $fallback;\n}\n\nfunction genosys_site_visibility( $key, $automatic = true ) {\n    $value = genosys_site_setting( $key, 'auto' );\n    return 'auto' === $value ? (bool) $automatic : 'yes' === $value;\n}\n\nfunction genosys_home_sections() {\n    $defaults = genosys_site_defaults()['home_sections'];\n    $sections = genosys_site_setting( 'home_sections', $defaults );\n    $allowed = array_column( $defaults, 'id' );\n    $valid = array();\n    $seen = array();\n    foreach ( $sections as $section ) {\n        if ( ! is_array( $section ) || ! isset( $section['id'] ) || ! in_array( $section['id'], $allowed, true ) || in_array( $section['id'], $seen, true ) ) { continue; }\n        $seen[] = $section['id'];\n        $valid[] = array( 'id' => $section['id'], 'visible' => ! empty( $section['visible'] ) );\n    }\n    // Missing rows are restored, so a partial save cannot silently remove a section.\n    foreach ( $defaults as $section ) { if ( ! in_array( $section['id'], $seen, true ) ) { $valid[] = $section; } }\n    return $valid;\n}\n\nfunction genosys_home_has_first_slider() {\n    foreach ( genosys_home_sections() as $section ) {\n        if ( ! $section['visible'] ) { continue; }\n        return 'slider' === $section['id'] && count( genosys_site_setting( 'slides' ) ) > 0;\n    }\n    return false;\n}\n\nfunction genosys_configured_home_body_class( $classes ) {\n    if ( is_front_page() && ! is_404() && ! genosys_home_has_first_slider() ) { $classes[] = 'genosys-home-standard-header'; }\n    return $classes;\n}\nadd_filter( 'body_class', 'genosys_configured_home_body_class' );\n\n/** Apply display-only preferences after the existing catalog query has been built. */\nfunction genosys_configured_shop_page_size( $query ) {\n    if ( ! is_admin() && $query instanceof WP_Query && $query->is_main_query() && $query->get( 'genosys_shop_query' ) ) {\n        $query->set( 'posts_per_page', max( 3, min( 48, (int) genosys_site_setting( 'shop_per_page', 12 ) ) ) );\n    }\n}\nadd_action( 'pre_get_posts', 'genosys_configured_shop_page_size', 99 );\n\n/** Keep desktop, banner and mobile navigation preferences in their own contexts. */\nfunction genosys_header_preferences_css( $color, $primary ) {\n    $css = '';\n    // A home page without a leading slider uses the same header as internal pages.\n    if ( is_front_page() && ! is_404() && ! genosys_home_has_first_slider() ) {\n        $css .= 'body.home .site-header--standard{position:relative;background:#fff;color:#3b4553;}body.home .site-header--standard .header-actions .nav-icon-button{background:#f4f4f4;color:#3b4553;}';\n        $css .= '@media(min-width:821px){body.home .site-header--standard .primary-menu>li>a{color:#3b4553;}body.home .site-header--standard .primary-menu>li>a:hover,body.home .site-header--standard .primary-menu>li>a:focus-visible,body.home .site-header--standard .primary-menu>.current-menu-item>a,body.home .site-header--standard .primary-menu>.current-menu-ancestor>a{color:#c8103b;}body.home .site-header--standard .primary-menu>li>a::after{background:#c8103b;}}';\n    }\n    $icon_hover = $color( 'header_icon_hover' );\n    foreach ( array( 'home' => 'banner', 'internal' => 'standard' ) as $context => $class ) {\n        $scope = 'body .site-header.site-header--' . $class;\n        $background = $color( 'header_background_' . $context );\n        if ( $background ) { $css .= $scope . '{background:' . $background . ';}'; }\n        $text = $color( 'header_link_color_' . $context );\n        $hover = $color( 'header_link_hover_' . $context );\n        $hover = $hover ?: ( $primary ?: ( 'home' === $context ? '#f2a5b8' : '#c8103b' ) );\n        if ( $text || $color( 'header_link_hover_' . $context ) || $primary ) {\n            $link = $scope . ' .primary-menu>li:not(.menu-item-login)>a:not(.nav-login)';\n            $states = $link . ':hover,' . $link . ':focus-visible,' . $scope . ' .primary-menu>li.current-menu-item>a:not(.nav-login),' . $scope . ' .primary-menu>li.current-menu-ancestor>a:not(.nav-login)';\n            $css .= '@media(min-width:821px){';\n            if ( $text ) { $css .= $link . '{color:' . $text . ';-webkit-text-fill-color:currentColor;background-image:none;}'; }\n            $css .= $states . '{color:' . $hover . ';-webkit-text-fill-color:currentColor;background-image:none;}' . $link . '::after{background:' . $hover . ';}';\n            $css .= '}';\n        }\n        $icon = $color( 'header_icon_color_' . $context );\n        // The signed-in account button keeps its contrasting white expanded state.\n        $buttons = array( $scope . ' .header-actions .nav-icon-button:not(.nav-account-toggle)', $scope . ' .header-actions .nav-account-toggle[aria-expanded=\"false\"]', $scope . ' .header-actions .nav-account-menu--guest .nav-account-toggle[aria-expanded]' );\n        if ( $icon ) { $css .= implode( ',', $buttons ) . '{color:' . $icon . ';}'; }\n        if ( $icon || $icon_hover || $primary ) {\n            $hover_color = $icon_hover ?: ( $primary ?: ( 'home' === $context ? '#f2a5b8' : '#c8103b' ) );\n            $states = array();\n            foreach ( $buttons as $button ) { $states[] = $button . ':hover'; $states[] = $button . ':focus-visible'; }\n            $css .= implode( ',', $states ) . '{color:' . $hover_color . ';}';\n        }\n        // The menu button is separate from the hidden desktop basket on mobile.\n        if ( $icon || $icon_hover ) {\n            $css .= '@media(max-width:820px){';\n            if ( $icon ) { $css .= $scope . ' .menu-toggle{color:' . $icon . ';}'; }\n            $css .= $scope . ' .menu-toggle:hover,' . $scope . ' .menu-toggle:focus-visible{color:' . ( $icon_hover ?: '#c8103b' ) . ';}}';\n        }\n    }\n    $mobile_background = $color( 'mobile_menu_background' );\n    $mobile_text = $color( 'mobile_menu_color' );\n    $mobile_hover = $color( 'mobile_menu_hover' );\n    if ( $mobile_background || $mobile_text || $mobile_hover || $primary ) {\n        $scope = 'body .site-header .primary-navigation';\n        $link = $scope . ' .primary-menu a:not(.nav-login)';\n        $css .= '@media(max-width:820px){';\n        if ( $mobile_background ) { $css .= '.js ' . $scope . '{background:' . $mobile_background . ';}'; }\n        if ( $mobile_text ) { $css .= $link . ',' . $scope . ' .mobile-menu-close{color:' . $mobile_text . ';-webkit-text-fill-color:currentColor;background-image:none;}'; }\n        if ( $mobile_text || $mobile_hover || $primary ) {\n            $hover = $mobile_hover ?: ( $primary ?: '#efafc0' );\n            $css .= $link . ':hover,' . $link . ':focus-visible,' . $scope . ' .primary-menu .current-menu-item>a:not(.nav-login),' . $scope . ' .primary-menu .current-menu-ancestor>a:not(.nav-login),' . $scope . ' .mobile-menu-close:hover,' . $scope . ' .mobile-menu-close:focus-visible{color:' . $hover . ';-webkit-text-fill-color:currentColor;}';\n        }\n        $css .= '}';\n    }\n    return $css;\n}\n\n/** New commerce/account components share the deliberately edited brand palette. */\nfunction genosys_brand_preferences_css( $primary, $deep, $defaults ) {\n    if ( ! $primary && ! $deep ) { return ''; }\n    $css = '';\n    $modules = array(\n        '.gaccount' => array( '--gaccount-red', '--gaccount-deep' ),\n        '.gorders' => array( '--gorders-crimson', '--gorders-deep' ),\n        '.genosys-shop' => array( '--shop-crimson', '--shop-deep' ),\n        '.genosys-checkout' => array( '--gco-crimson', '--gco-deep-red' ),\n        '.gco-receipt-upload' => array( '--gcr-crimson', '' ),\n    );\n    foreach ( $modules as $selector => $variables ) {\n        $css .= 'body ' . $selector . '{';\n        if ( $primary ) { $css .= $variables[0] . ':' . $primary . ';'; }\n        if ( $deep && $variables[1] ) { $css .= $variables[1] . ':' . $deep . ';'; }\n        $css .= '}';\n    }\n    $main = $primary ?: $defaults['primary_color'];\n    $dark = $deep ?: $defaults['deep_color'];\n    $buttons = array(\n        'body .home-feature-button', 'body .genosys-categories__button', 'body .genosys-featured-products__view-all',\n        'body .genosys-featured-products__tab.is-active', 'body .fans-club-button--primary', 'body .fans-club-audience button[aria-selected=\"true\"]',\n        'body .genosys-cart-page .genosys-cart-summary__checkout', 'body .genosys-checkout #place_order', 'body .genosys-login__primary',\n        'body.single-product .genosys-product-page .genosys-product__info form.cart .single_add_to_cart_button.button.alt',\n        'body.single-product .genosys-product-page .genosys-product__info form.cart .single_add_to_cart_button',\n        'body.single-product .genosys-product-page .woocommerce-tabs #review_form input[type=\"submit\"]',\n        'body .gaccount .gaccount__button--primary', 'body .gaccount .gaccount__avatar',\n        'body .gaccount .gaccount__badge[data-membership=\"member\"]', 'body .gaccount .gaccount__nav-item.is-active', 'body .gaccount .gaccount__nav-item[aria-current=\"page\"]',\n        'body .gorders .gorders__filter.is-active', 'body .gorders .gorders__filter[aria-current=\"page\"]',\n        'body .gorders .gorder__toggle[aria-expanded=\"true\"]', 'body .gorders .gorder__receipt-picker', 'body .gorders .gorder__receipt-icon',\n        'body .product-card__badge:not(.product-card__badge--stock)',\n    );\n    $states = array();\n    foreach ( $buttons as $button ) { $states[] = $button; $states[] = $button . ':hover'; $states[] = $button . ':focus-visible'; }\n    $css .= implode( ',', $states ) . '{background-image:linear-gradient(115deg,' . $main . ',' . $dark . ');}';\n    if ( $primary ) {\n        $css .= 'body .genosys-categories__intro h2 span,body .genosys-featured-products__heading em,body .genosys-featured-products__categories-link,body .products-view-all,body .fans-club-hero h1 span:not(.fans-club-title-context),body .fans-club-hero__eyebrow,body .gaccount .gaccount__button:not(.gaccount__button--primary),body .gaccount .gaccount__nav-item:not(.is-active):not([aria-current=\"page\"]) svg{color:' . $primary . ';}';\n        $css .= 'body .gaccount .gaccount__button:not(.gaccount__button--primary){border-color:' . $primary . ';}body .gaccount .gaccount__card-header h2::before,body .gaccount .gaccount__nav-count,body .nav-count-badge,body .nav-guest-indicator,body .mobile-menu-commerce__count{background:' . $primary . ';}';\n        $css .= 'body .product-favorite[aria-pressed=\"true\"]{background:' . $primary . ';border-color:' . $primary . ';}';\n    }\n    return $css;\n}\n\n/** Only edited presentation values override the installed storefront design. */\nfunction genosys_site_settings_css() {\n    $defaults = genosys_site_defaults();\n    $deep_token = sanitize_hex_color( genosys_site_setting( 'deep_color', $defaults['deep_color'] ) ) ?: $defaults['deep_color'];\n    $css = ':root{--deep:' . $deep_token . ';}';\n    $saved = get_option( 'genosys_site_settings', array() );\n    $saved = is_array( $saved ) ? $saved : array();\n    $color = static function ( $key ) use ( $defaults, $saved ) {\n        $value = genosys_site_setting( $key );\n        // A saved navbar value is authoritative, even when it equals the field\n        // default. Untouched installs still retain their original banner styles.\n        $explicit_navigation = ( 0 === strpos( $key, 'header_' ) || 0 === strpos( $key, 'mobile_menu_' ) ) && array_key_exists( $key, $saved );\n        return is_string( $value ) && ( $explicit_navigation || $value !== $defaults[ $key ] ) && sanitize_hex_color( $value ) ? $value : '';\n    };\n    $primary = $color( 'primary_color' );\n    $deep = $color( 'deep_color' );\n    if ( $primary ) {\n        $css .= ':root{--accent:' . $primary . ';}.genosys-footer__headline em{color:' . $primary . ';}.genosys-footer__filled-button{background:' . $primary . ';border-color:' . $primary . ';}';\n    }\n    if ( $primary || $deep ) {\n        $gradient_primary = $primary ?: $defaults['primary_color'];\n        $gradient_deep = $deep ?: $defaults['deep_color'];\n        $css .= '.home-feature-button,.primary-menu .nav-login{background-image:linear-gradient(120deg,' . $gradient_primary . ',' . $gradient_deep . ',' . $gradient_primary . ');}';\n        $css .= '.nav-account-dropdown .account-panel-login{background-image:linear-gradient(110deg,' . $gradient_primary . ',' . $gradient_deep . ');}';\n        $css .= '.mobile-menu-commerce__card--login,.mobile-menu-commerce__card--login:hover,.mobile-menu-commerce__card--login:focus-visible{background-image:linear-gradient(115deg,' . $gradient_primary . ',' . $gradient_deep . ');}';\n    }\n    if ( $deep ) { $css .= '.genosys-footer__filled-button:hover{background:' . $deep . ';border-color:' . $deep . ';}'; }\n    $css .= genosys_brand_preferences_css( $primary, $deep, $defaults );\n    $height = (int) genosys_site_setting( 'header_height', 100 );\n    if ( 100 !== $height ) {\n        $height = max( 76, min( 180, $height ) );\n        $css .= '@media(min-width:821px){.site-header .header-inner{min-height:' . $height . 'px;padding-block:' . min( 12, max( 0, ( $height - 58 ) / 2 ) ) . 'px;}}';\n    }\n    $css .= genosys_header_preferences_css( $color, $primary );\n    $slides = genosys_site_setting( 'slides' );\n    foreach ( $slides as $slide ) {\n        if ( is_array( $slide ) && ( ! empty( $slide['title'] ) || ! empty( $slide['link'] ) ) ) {\n            $css .= '.hero-slide .genosys-slide-link{position:absolute;inset:0;z-index:2;display:block;}.hero-slide .genosys-slide-caption{position:absolute;inset:auto clamp(28px,7vw,120px) 16%;z-index:3;margin:0;color:#fff;font-size:clamp(24px,4vw,52px);font-weight:700;text-shadow:0 2px 18px #0009;pointer-events:none;}.hero-slide:focus-within{outline:3px solid #fff;outline-offset:-6px;}';\n            break;\n        }\n    }\n    foreach ( array( 'social_instagram', 'social_telegram', 'social_whatsapp', 'social_linkedin' ) as $social ) {\n        if ( genosys_site_setting( $social, '' ) ) { $css .= '.genosys-footer__social-icon{text-decoration:none;}'; break; }\n    }\n    if ( $css ) { echo '<style id=\"genosys-site-preferences\">' . $css . '</style>'; } // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Colors and numeric values are validated above; remaining CSS is fixed.\n}\nadd_action( 'wp_head', 'genosys_site_settings_css', 99 );\r\n\n/** An empty product label deliberately retains WooCommerce and plugin translations. */\nfunction genosys_configured_related_title( $title ) {\n    $configured = genosys_site_setting( 'product_related_title', '' );\n    return is_string( $configured ) && '' !== trim( $configured ) ? $configured : $title;\n}\nadd_filter( 'woocommerce_product_related_products_heading', 'genosys_configured_related_title', 50 );\n\nfunction genosys_configured_product_tab_titles( $tabs ) {\n    foreach ( array( 'description' => 'product_description_title', 'additional_information' => 'product_information_title', 'reviews' => 'product_reviews_title' ) as $tab => $key ) {\n        $configured = genosys_site_setting( $key, '' );\n        if ( isset( $tabs[ $tab ] ) && is_string( $configured ) && '' !== trim( $configured ) ) { $tabs[ $tab ]['title'] = $configured; }\n    }\n    return $tabs;\n}\nadd_filter( 'woocommerce_product_tabs', 'genosys_configured_product_tab_titles', 99 );\n/** Change the storefront title only after the store name is deliberately edited. */\nfunction genosys_configured_document_title( $parts ) {\n    $name = genosys_site_setting( 'site_name', 'ژنوسیس' );\n    if ( is_string( $name ) && '' !== trim( $name ) && $name !== genosys_site_defaults()['site_name'] ) {\n        if ( is_front_page() ) { $parts['title'] = $name; } else { $parts['site'] = $name; }\n    }\n    return $parts;\n}\nadd_filter( 'document_title_parts', 'genosys_configured_document_title', 99 );\n\nfunction genosys_site_footer_tagline() {\n    $defaults = genosys_site_defaults();\n    $tagline = genosys_site_setting( 'footer_tagline' );\n    $slogan = genosys_site_setting( 'site_slogan' );\n    return $tagline === $defaults['footer_tagline'] && $slogan !== $defaults['site_slogan'] ? 'GENOSYS - ' . $slogan : $tagline;\n}\n","sha256":"da7d54dc24d5ba5fafdf73e73a761251cddfee8c61e061180fec679b7ff29275"},"inc/theme-settings.php":{"content":"<?php\n/** Theme settings and their WooCommerce shipping rate. */\nif ( ! defined( 'ABSPATH' ) ) {\n\texit;\n}\n\n/**\n * Normalize a delivery price without changing the store's currency unit.\n * An empty value means WooCommerce's existing shipping setup remains in use.\n *\n * @param mixed $value Submitted option value.\n * @return string\n */\nfunction genosys_sanitize_shipping_cost( $value ) {\n\t$previous = get_option( 'genosys_shipping_cost', '' );\n\tif ( ! is_scalar( $value ) ) {\n\t\tadd_settings_error( 'genosys_shipping_cost', 'invalid_shipping_cost', 'هزینه ارسال باید یک عدد معتبر و غیرمنفی باشد.', 'error' );\n\t\treturn (string) $previous;\n\t}\n\n\t$amount = trim( (string) $value );\n\tif ( '' === $amount ) {\n\t\treturn '';\n\t}\n\n\t$amount = strtr(\n\t\t$amount,\n\t\tarray(\n\t\t\t'۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',\n\t\t\t'۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',\n\t\t\t'٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',\n\t\t\t'٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',\n\t\t\t'٫' => '.',\n\t\t)\n\t);\n\t$amount = preg_replace( '/[\\s\\x{00A0}\\x{200C}\\x{202F},٬،]+/u', '', $amount );\n\tif ( ! preg_match( '/^\\d+(?:\\.\\d+)?$/D', $amount ) ) {\n\t\tadd_settings_error( 'genosys_shipping_cost', 'invalid_shipping_cost', 'هزینه ارسال باید یک عدد معتبر و غیرمنفی باشد.', 'error' );\n\t\treturn (string) $previous;\n\t}\n\n\tlist( $whole, $fraction ) = array_pad( explode( '.', $amount, 2 ), 2, '' );\n\t$whole    = ltrim( $whole, '0' );\n\t$whole    = '' === $whole ? '0' : $whole;\n\t$fraction = rtrim( $fraction, '0' );\n\t$decimals = function_exists( 'wc_get_price_decimals' ) ? max( 0, (int) wc_get_price_decimals() ) : 2;\n\tif ( strlen( $whole ) > 15 || strlen( $fraction ) > $decimals ) {\n\t\tadd_settings_error( 'genosys_shipping_cost', 'invalid_shipping_cost', 'مبلغ واردشده بیش از حد بزرگ است یا رقم اعشار آن با تنظیمات فروشگاه سازگار نیست.', 'error' );\n\t\treturn (string) $previous;\n\t}\n\n\treturn $whole . ( '' === $fraction ? '' : '.' . $fraction );\n}\n\n/** Keep bank-transfer details editable without publishing sample card numbers. */\nfunction genosys_checkout_ascii_digits( $value ) {\n\treturn strtr( (string) $value, array(\n\t\t'۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',\n\t\t'۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',\n\t\t'٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',\n\t\t'٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',\n\t) );\n}\n\nfunction genosys_sanitize_checkout_card_number( $value ) {\n\t$number = preg_replace( '/[\\s\\-]+/u', '', genosys_checkout_ascii_digits( $value ) );\n\tif ( '' === $number || preg_match( '/^\\d{16}$/D', $number ) ) {\n\t\treturn $number;\n\t}\n\tadd_settings_error( 'genosys_checkout_card_number', 'invalid_card_number', 'شماره کارت باید ۱۶ رقم باشد.', 'error' );\n\treturn (string) get_option( 'genosys_checkout_card_number', '' );\n}\n\nfunction genosys_sanitize_checkout_whatsapp( $value ) {\n\t$number = preg_replace( '/[\\s()\\-]+/u', '', genosys_checkout_ascii_digits( $value ) );\n\tif ( '' === $number || preg_match( '/^(?:\\+?98|0)?9\\d{9}$/D', $number ) ) {\n\t\treturn $number;\n\t}\n\tadd_settings_error( 'genosys_checkout_whatsapp', 'invalid_whatsapp', 'شماره واتساپ را به شکل 09… یا +989… وارد کنید.', 'error' );\n\treturn (string) get_option( 'genosys_checkout_whatsapp', '' );\n}\n\nfunction genosys_sanitize_checkout_name( $value ) {\n\t$name = sanitize_text_field( (string) $value );\n\treturn function_exists( 'mb_substr' ) ? mb_substr( $name, 0, 100 ) : substr( $name, 0, 100 );\n}\n\n/** A blank order template disables SMS; invalid values preserve the saved ID. */\nfunction genosys_sanitize_order_sms_template_id( $value ) {\n\t$previous = get_option( 'genosys_order_sms_template_id', '' );\n\tif ( is_scalar( $value ) && ! is_bool( $value ) ) {\n\t\t$id = ltrim( genosys_checkout_ascii_digits( trim( (string) $value ) ), '0' );\n\t\tif ( '' === trim( (string) $value ) ) {\n\t\t\treturn '';\n\t\t}\n\t\tif ( preg_match( '/^[1-9][0-9]{0,9}$/D', $id ) && (float) $id <= 2147483647 ) {\n\t\t\treturn $id;\n\t\t}\n\t}\n\tadd_settings_error( 'genosys_order_sms_template_id', 'invalid_order_sms_template_id', 'شناسه قالب پیامک ثبت سفارش باید یک عدد صحیح مثبت باشد. برای غیرفعال کردن ارسال، کادر را خالی بگذارید.', 'error' );\n\treturn is_scalar( $previous ) ? (string) $previous : '';\n}\n\n/** Keep status notifications independently configurable from submission SMS. */\nfunction genosys_sanitize_order_status_sms_template_id( $value ) {\n\t$previous = get_option( 'genosys_order_status_sms_template_id', '' );\n\tif ( is_scalar( $value ) && ! is_bool( $value ) ) {\n\t\t$id = ltrim( genosys_checkout_ascii_digits( trim( (string) $value ) ), '0' );\n\t\tif ( '' === trim( (string) $value ) ) {\n\t\t\treturn '';\n\t\t}\n\t\tif ( preg_match( '/^[1-9][0-9]{0,9}$/D', $id ) && (float) $id <= 2147483647 ) {\n\t\t\treturn $id;\n\t\t}\n\t}\n\tadd_settings_error( 'genosys_order_status_sms_template_id', 'invalid_order_status_sms_template_id', 'شناسه قالب پیامک تغییر وضعیت سفارش باید یک عدد صحیح مثبت باشد. برای غیرفعال کردن ارسال، کادر را خالی بگذارید.', 'error' );\n\treturn is_scalar( $previous ) ? (string) $previous : '';\n}\n\n/** Validate the two receipt templates without changing other SMS settings. */\nfunction genosys_sanitize_receipt_sms_template_id( $value, $status ) {\n\t$option = 'genosys_receipt_' . $status . '_sms_template_id';\n\t$previous = get_option( $option, '' );\n\tif ( is_scalar( $value ) && ! is_bool( $value ) ) {\n\t\t$id = ltrim( genosys_checkout_ascii_digits( trim( (string) $value ) ), '0' );\n\t\tif ( '' === trim( (string) $value ) ) {\n\t\t\treturn '';\n\t\t}\n\t\tif ( preg_match( '/^[1-9][0-9]{0,9}$/D', $id ) && (float) $id <= 2147483647 ) {\n\t\t\treturn $id;\n\t\t}\n\t}\n\t$label = 'approved' === $status ? 'تایید فیش' : 'رد فیش';\n\tadd_settings_error( $option, 'invalid_receipt_' . $status . '_sms_template_id', 'شناسه قالب پیامک ' . $label . ' باید یک عدد صحیح مثبت باشد. برای غیرفعال کردن ارسال، کادر را خالی بگذارید.', 'error' );\n\treturn is_scalar( $previous ) ? (string) $previous : '';\n}\n\nfunction genosys_sanitize_receipt_approved_sms_template_id( $value ) {\n\treturn genosys_sanitize_receipt_sms_template_id( $value, 'approved' );\n}\n\nfunction genosys_sanitize_receipt_rejected_sms_template_id( $value ) {\n\treturn genosys_sanitize_receipt_sms_template_id( $value, 'rejected' );\n}\n\n/** Register the setting with WordPress' capability and nonce-protected settings form. */\nfunction genosys_register_theme_settings() {\n\tregister_setting(\n\t\t'genosys_theme_settings',\n\t\t'genosys_shipping_cost',\n\t\tarray(\n\t\t\t'type'              => 'string',\n\t\t\t'sanitize_callback' => 'genosys_sanitize_shipping_cost',\n\t\t\t'default'           => '',\n\t\t)\n\t);\n\tregister_setting( 'genosys_theme_settings', 'genosys_checkout_card_number', array( 'type' => 'string', 'sanitize_callback' => 'genosys_sanitize_checkout_card_number', 'default' => '' ) );\n\tregister_setting( 'genosys_theme_settings', 'genosys_checkout_card_holder', array( 'type' => 'string', 'sanitize_callback' => 'genosys_sanitize_checkout_name', 'default' => '' ) );\n\tregister_setting( 'genosys_theme_settings', 'genosys_checkout_bank_name', array( 'type' => 'string', 'sanitize_callback' => 'genosys_sanitize_checkout_name', 'default' => '' ) );\n\tregister_setting( 'genosys_theme_settings', 'genosys_checkout_whatsapp', array( 'type' => 'string', 'sanitize_callback' => 'genosys_sanitize_checkout_whatsapp', 'default' => '' ) );\n\tregister_setting( 'genosys_theme_settings', 'genosys_order_sms_template_id', array( 'type' => 'string', 'sanitize_callback' => 'genosys_sanitize_order_sms_template_id', 'default' => '' ) );\n\tregister_setting( 'genosys_theme_settings', 'genosys_order_status_sms_template_id', array( 'type' => 'string', 'sanitize_callback' => 'genosys_sanitize_order_status_sms_template_id', 'default' => '' ) );\n\tregister_setting( 'genosys_theme_settings', 'genosys_receipt_approved_sms_template_id', array( 'type' => 'string', 'sanitize_callback' => 'genosys_sanitize_receipt_approved_sms_template_id', 'default' => '' ) );\n\tregister_setting( 'genosys_theme_settings', 'genosys_receipt_rejected_sms_template_id', array( 'type' => 'string', 'sanitize_callback' => 'genosys_sanitize_receipt_rejected_sms_template_id', 'default' => '' ) );\n}\nadd_action( 'admin_init', 'genosys_register_theme_settings' );\n\nfunction genosys_add_theme_settings_page() {\n\tadd_menu_page(\n\t\t'تنظیمات قالب',\n\t\t'تنظیمات قالب',\n\t\t'manage_options',\n\t\t'genosys-theme-settings',\n\t\t'genosys_render_theme_settings_page',\n\t\t'dashicons-admin-generic',\n\t\t61\n\t);\n}\nadd_action( 'admin_menu', 'genosys_add_theme_settings_page' );\n\n/**\n * Apply the configured amount to WooCommerce's enabled flat-rate method.\n * The regular WooCommerce rate calculation still determines shipping taxes.\n */\nfunction genosys_flat_rate_cost( $args, $method ) {\n\t$cost = get_option( 'genosys_shipping_cost', '' );\n\tif ( ! is_object( $method ) || ! isset( $method->id ) || 'flat_rate' !== $method->id || ! method_exists( $method, 'get_rate_id' ) || ! isset( $args['id'] ) || $args['id'] !== $method->get_rate_id() || '' === $cost || ! is_numeric( $cost ) || (float) $cost < 0 ) {\n\t\treturn $args;\n\t}\n\n\t$args['cost'] = (string) $cost;\n\treturn $args;\n}\nadd_filter( 'woocommerce_shipping_method_add_rate_args', 'genosys_flat_rate_cost', 10, 2 );\n\n/**\n * A WooCommerce flat-rate method with an empty native cost creates no rate.\n * Add its existing rate when the theme setting supplies a cost instead.\n */\nfunction genosys_add_configured_flat_rate( $method, $rate ) {\n\t$cost = get_option( 'genosys_shipping_cost', '' );\n\tif ( ! is_object( $method ) || ! isset( $method->id, $method->rates ) || 'flat_rate' !== $method->id || ! is_array( $rate ) || ! isset( $rate['id'] ) || '' === $cost || ! is_numeric( $cost ) || (float) $cost < 0 ) {\n\t\treturn;\n\t}\n\n\tif ( ! isset( $method->rates[ $rate['id'] ] ) ) {\n\t\t$rate['cost'] = (string) $cost;\n\t\t$method->add_rate( $rate );\n\t}\n}\nadd_action( 'woocommerce_flat_rate_shipping_add_rate', 'genosys_add_configured_flat_rate', 10, 2 );\n\n/**\n * Offer the saved delivery cost as a real WooCommerce rate in the Iran zone.\n * The store currently uses Free Shipping there, so a flat-rate-only override\n * cannot affect the cart or checkout totals. Keep coupon-granted free shipping\n * and any existing paid or pickup methods available.\n *\n * @param array $rates   Calculated WooCommerce rates for one package.\n * @param array $package The package and its destination.\n * @return array\n */\nfunction genosys_configured_delivery_rate( $rates, $package ) {\n\t$cost = get_option( 'genosys_shipping_cost', '' );\n\tif ( ! is_array( $rates ) || ! is_array( $package ) || ! class_exists( 'WC_Shipping_Rate' ) || '' === $cost || ! is_numeric( $cost ) || (float) $cost < 0 ) {\n\t\treturn $rates;\n\t}\n\n\t$country = isset( $package['destination']['country'] ) ? strtoupper( (string) $package['destination']['country'] ) : '';\n\tif ( '' !== $country && 'IR' !== $country ) {\n\t\treturn $rates;\n\t}\n\n\t$has_free_rate = false;\n\t$has_delivery  = false;\n\tforeach ( $rates as $rate ) {\n\t\tif ( ! $rate instanceof WC_Shipping_Rate ) {\n\t\t\tcontinue;\n\t\t}\n\t\t$method_id = $rate->get_method_id();\n\t\t$has_free_rate = $has_free_rate || 'free_shipping' === $method_id;\n\t\t$has_delivery  = $has_delivery || ! in_array( $method_id, array( 'free_shipping', 'local_pickup', 'legacy_local_pickup' ), true );\n\t}\n\n\t// An explicit free-shipping coupon must keep WooCommerce's existing behavior.\n\tif ( $has_free_rate && function_exists( 'WC' ) && WC()->cart && method_exists( WC()->cart, 'get_coupons' ) ) {\n\t\tforeach ( WC()->cart->get_coupons() as $coupon ) {\n\t\t\tif ( is_object( $coupon ) && method_exists( $coupon, 'get_free_shipping' ) && $coupon->get_free_shipping() ) {\n\t\t\t\treturn $rates;\n\t\t\t}\n\t\t}\n\t}\n\n\t// An enabled Flat Rate already receives the saved cost via the hooks above.\n\tif ( ! $has_free_rate && $has_delivery ) {\n\t\treturn $rates;\n\t}\n\n\tforeach ( $rates as $rate_id => $rate ) {\n\t\tif ( $rate instanceof WC_Shipping_Rate && 'free_shipping' === $rate->get_method_id() ) {\n\t\t\tunset( $rates[ $rate_id ] );\n\t\t}\n\t}\n\n\t$taxes = array();\n\tif ( function_exists( 'wc_tax_enabled' ) && wc_tax_enabled() && class_exists( 'WC_Tax' ) && function_exists( 'WC' ) && WC()->customer && ! WC()->customer->get_is_vat_exempt() ) {\n\t\t$taxes = WC_Tax::calc_shipping_tax( (float) $cost, WC_Tax::get_shipping_tax_rates() );\n\t}\n\n\t$rate = new WC_Shipping_Rate( 'genosys_delivery', 'هزینه ارسال', (float) $cost, $taxes, 'genosys_delivery' );\n\treturn array( $rate->get_id() => $rate ) + $rates;\n}\nadd_filter( 'woocommerce_package_rates', 'genosys_configured_delivery_rate', 10, 2 );\n\n/** Recalculate an existing cart's cached rates when this shipping fix is installed. */\nfunction genosys_shipping_package_cache_key( $packages ) {\n\t$cost = get_option( 'genosys_shipping_cost', '' );\n\tif ( ! is_array( $packages ) || '' === $cost ) {\n\t\treturn $packages;\n\t}\n\n\tforeach ( $packages as &$package ) {\n\t\tif ( is_array( $package ) ) {\n\t\t\t$package['genosys_delivery_rate_version'] = '1:' . $cost;\n\t\t}\n\t}\n\tunset( $package );\n\treturn $packages;\n}\nadd_filter( 'woocommerce_cart_shipping_packages', 'genosys_shipping_package_cache_key' );\n\n/** Recalculate WooCommerce's cached shipping rates after this setting changes. */\nfunction genosys_refresh_shipping_cache_for_setting( $option ) {\n\tif ( 'genosys_shipping_cost' === $option && class_exists( 'WC_Cache_Helper' ) ) {\n\t\tWC_Cache_Helper::get_transient_version( 'shipping', true );\n\t}\n}\nadd_action( 'updated_option', 'genosys_refresh_shipping_cache_for_setting' );\nadd_action( 'added_option', 'genosys_refresh_shipping_cache_for_setting' );\n\nfunction genosys_render_theme_settings_page() {\n\tgenosys_render_settings_dashboard();\n}\r\n","sha256":"0519e70e937cf998c1866d54fee5ed31a4a7fbf07839229cc3c7bd8466fef0d8"},"index.php":{"content":"<?php\n/** Minimal required fallback template; page content is deferred. */\nget_header();\n?>\n<main id=\"main\" class=\"site-main\" tabindex=\"-1\"></main>\n<?php get_footer(); ?>\n","sha256":"c516d099c58a019ccb587e2f43489248cbec22903acc20cce1ee92dc52bcae7c"},"page-account-dashboard.php":{"content":"<?php\n/** Current customer's private account dashboard. Native Woo endpoints retain their own views. */\ndefined( 'ABSPATH' ) || exit;\n\n$account = genosys_account_dashboard_context();\n$digits = 'genosys_account_dashboard_digits';\n$requested_tab = isset( $_GET['ga_tab'] ) && is_string( $_GET['ga_tab'] ) ? sanitize_key( wp_unslash( $_GET['ga_tab'] ) ) : 'profile';\n$is_address_endpoint = is_wc_endpoint_url( 'edit-address' );\n$address_type = $is_address_endpoint ? (string) get_query_var( 'edit-address' ) : '';\n$active_tab = $is_address_endpoint ? 'addresses' : ( in_array( $requested_tab, array( 'profile', 'addresses', 'notifications' ), true ) ? $requested_tab : 'profile' );\n$initial = function_exists( 'mb_substr' ) ? mb_substr( $account['displayName'], 0, 1, 'UTF-8' ) : preg_replace( '/^(.).*$/us', '$1', $account['displayName'] );\n$months = array( 1 => 'فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند' );\n$current_year = (int) substr( genosys_account_dashboard_shamsi( time() ), 0, 4 );\n$icon = static function ( $name ) {\n\t$paths = array(\n\t\t'user' => '<circle cx=\"12\" cy=\"7\" r=\"4\"/><path d=\"M4 21v-2a8 8 0 0 1 16 0v2\"/>',\n\t\t'pin' => '<path d=\"M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z\"/><circle cx=\"12\" cy=\"10\" r=\"3\"/>',\n\t\t'bell' => '<path d=\"M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4\"/>',\n\t\t'gift' => '<path d=\"M3 8h18v4H3zM5 12v9h14v-9M12 8v13\"/><path d=\"M12 8C5 8 5 1 8 2c3 0 4 6 4 6Zm0 0c7 0 7-7 4-6-3 0-4 6-4 6Z\"/>',\n\t\t'bag' => '<path d=\"M5 8h14l-1 13H6L5 8ZM9 8V5a3 3 0 0 1 6 0v3\"/>',\n\t\t'logout' => '<path d=\"M10 4H4v16h6m-1-8h13m-5-5 5 5-5 5\"/>',\n\t\t'star' => '<path d=\"m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z\"/>',\n\t\t'sparkle' => '<path d=\"m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z\"/>',\n\t\t'medal' => '<circle cx=\"12\" cy=\"8\" r=\"5\"/><path d=\"m9 12-1 9 4-3 4 3-1-9\"/>',\n\t\t'check' => '<path d=\"m5 12 4 4L19 6\"/>',\n\t);\n\techo '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">' . ( $paths[ $name ] ?? '' ) . '</svg>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG constants.\n};\n$badge = static function () use ( $account, $icon ) {\n\t?><span class=\"gaccount__badge\" data-membership=\"<?php echo esc_attr( $account['membershipType'] ); ?>\"><?php $icon( 'member' === $account['membershipType'] ? 'star' : ( 'returning' === $account['membershipType'] ? 'medal' : 'sparkle' ) ); ?><span><?php echo esc_html( $account['membershipLabel'] ); ?></span></span><?php\n};\n$avatar = static function ( $modifier ) use ( $account, $initial ) {\n\t?><div class=\"gaccount__avatar gaccount__avatar--<?php echo esc_attr( $modifier ); ?>\" data-account-avatar><?php if ( $account['avatarUrl'] ) : ?><img src=\"<?php echo esc_url( $account['avatarUrl'] ); ?>\" alt=\"\" width=\"130\" height=\"130\"><?php else : ?><span data-account-avatar-initial><?php echo esc_html( $initial ); ?></span><?php endif; ?></div><?php\n};\n$navigation = array(\n\tarray( 'key' => 'profile', 'label' => genosys_site_setting( 'account_profile_label', 'اطلاعات حساب' ), 'icon' => 'user', 'url' => $account['accountUrl'], 'count' => 0 ),\n\tarray( 'key' => 'addresses', 'label' => genosys_site_setting( 'account_addresses_label', 'آدرس‌ها' ), 'icon' => 'pin', 'url' => add_query_arg( 'ga_tab', 'addresses', $account['accountUrl'] ), 'count' => $account['addressCount'] ),\n\tarray( 'key' => 'notifications', 'label' => genosys_site_setting( 'account_notifications_label', 'اعلان‌ها' ), 'icon' => 'bell', 'url' => add_query_arg( 'ga_tab', 'notifications', $account['accountUrl'] ), 'count' => 0 ),\n\tarray( 'key' => 'club', 'label' => genosys_site_setting( 'account_club_label', 'باشگاه مشتریان' ), 'icon' => 'gift', 'url' => $account['clubUrl'], 'count' => 0 ),\n\tarray( 'key' => 'orders', 'label' => genosys_site_setting( 'account_orders_label', 'سفارشات من' ), 'icon' => 'bag', 'url' => $account['ordersUrl'], 'count' => $account['ordersActiveCount'] ),\n);\n$navigation_labels = array_column( $navigation, 'label', 'key' );\nget_header();\n?>\n<main id=\"main\" class=\"gaccount\" data-account-dashboard dir=\"rtl\" tabindex=\"-1\">\n\t<div class=\"gaccount__container\">\n\t\t<nav class=\"gaccount__breadcrumb\" aria-label=\"مسیر صفحه\"><a href=\"<?php echo esc_url( home_url( '/' ) ); ?>\">خانه</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\"><?php echo esc_html( genosys_site_setting( 'account_title', 'حساب کاربری' ) ); ?></span></nav>\n\t\t<h1 class=\"gaccount__title\"><?php echo esc_html( genosys_site_setting( 'account_title', 'حساب کاربری' ) ); ?></h1>\n\t\t<div class=\"gaccount__layout\">\n\t\t\t<aside class=\"gaccount__sidebar\" aria-label=\"حساب مشتری\">\n\t\t\t\t<section class=\"gaccount__identity\">\n\t\t\t\t\t<?php $avatar( 'sidebar' ); ?>\n\t\t\t\t\t<h2 data-account-display-name><?php echo esc_html( $account['displayName'] ); ?></h2>\n\t\t\t\t\t<p class=\"gaccount__phone-small\" data-account-phone><?php echo esc_html( $account['phone'] ? $digits( $account['phone'] ) : 'شماره‌ای ثبت نشده است' ); ?></p>\n\t\t\t\t\t<?php $badge(); ?>\n\t\t\t\t\t<p class=\"gaccount__membership-date\"><?php echo esc_html( $account['clubActive'] && $account['clubSinceText'] ? 'عضو باشگاه از ' . $account['clubSinceText'] : 'عضویت: ' . $account['memberDurationText'] ); ?></p>\n\t\t\t\t</section>\n\t\t\t\t<nav class=\"gaccount__nav\" aria-label=\"بخش‌های حساب کاربری\">\n\t\t\t\t\t<?php foreach ( $navigation as $item ) : ?>\n\t\t\t\t\t\t<a class=\"gaccount__nav-item<?php echo $active_tab === $item['key'] ? ' is-active' : ''; ?>\" href=\"<?php echo esc_url( $item['url'] ); ?>\"<?php if ( $active_tab === $item['key'] ) : ?> aria-current=\"page\"<?php endif; ?>><?php $icon( $item['icon'] ); ?><span><?php echo esc_html( $item['label'] ); ?></span><?php if ( $item['count'] ) : ?><span class=\"gaccount__nav-count\"><?php echo esc_html( $digits( $item['count'] ) ); ?></span><?php endif; ?></a>\n\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t<a class=\"gaccount__nav-item gaccount__nav-item--logout\" href=\"<?php echo esc_url( $account['logoutUrl'] ); ?>\"><?php $icon( 'logout' ); ?><span>خروج از حساب</span></a>\n\t\t\t\t</nav>\n\t\t\t</aside>\n\t\t\t<section class=\"gaccount__content\" aria-label=\"<?php echo esc_attr( $navigation_labels[ $active_tab ] ); ?>\">\n\t\t\t\t<?php if ( 'profile' === $active_tab ) : ?>\n\t\t\t\t\t<article class=\"gaccount__hero\">\n\t\t\t\t\t\t<?php $avatar( 'hero' ); ?>\n\t\t\t\t\t\t<div class=\"gaccount__hero-copy\">\n\t\t\t\t\t\t\t<div class=\"gaccount__hero-heading\"><h2 data-account-display-name><?php echo esc_html( $account['displayName'] ); ?></h2><?php $badge(); ?></div>\n\t\t\t\t\t\t\t<p class=\"gaccount__hero-subtitle\"><?php echo esc_html( 'امروز' === $account['memberDurationText'] ? 'از امروز عضو ژنوسیس هستید' : 'عضو ژنوسیس از ' . $account['memberDurationText'] ); ?></p>\n\t\t\t\t\t\t\t<div class=\"gaccount__avatar-actions\"><button type=\"button\" class=\"gaccount__button\" data-avatar-pick>تغییر عکس</button><button type=\"button\" class=\"gaccount__button\" data-avatar-remove<?php disabled( ! $account['avatarUrl'] ); ?>>حذف عکس</button><input type=\"file\" accept=\"image/jpeg,image/png,image/webp\" data-avatar-file hidden aria-label=\"انتخاب عکس حساب\"></div>\n\t\t\t\t\t\t\t<div class=\"gaccount__stats\">\n\t\t\t\t\t\t\t\t<div class=\"gaccount__stat\"><strong data-account-orders-count><?php echo esc_html( $digits( $account['ordersCount'] ) ); ?></strong><span>سفارش ثبت‌شده</span></div>\n\t\t\t\t\t\t\t\t<div class=\"gaccount__stat\"><strong data-account-membership-days><?php echo esc_html( $digits( $account['daysMember'] ) ); ?></strong><span>روز عضویت</span></div>\n\t\t\t\t\t\t\t\t<?php if ( $account['clubActive'] ) : ?><div class=\"gaccount__stat\"><strong>فعال</strong><span><?php echo esc_html( $navigation_labels['club'] ); ?></span></div><?php endif; ?>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</article>\n\t\t\t\t\t<section class=\"gaccount__card gaccount__personal\">\n\t\t\t\t\t\t<div class=\"gaccount__card-header\"><h2>اطلاعات شخصی</h2><button type=\"button\" class=\"gaccount__button\" data-profile-edit>ویرایش اطلاعات</button></div>\n\t\t\t\t\t\t<form data-profile-form data-mode=\"view\" novalidate>\n\t\t\t\t\t\t\t<div class=\"gaccount__fields\">\n\t\t\t\t\t\t\t\t<div class=\"gaccount__field\"><label for=\"gaccount-first\">نام <span class=\"gaccount__required\">*</span></label><input id=\"gaccount-first\" name=\"first_name\" autocomplete=\"given-name\" value=\"<?php echo esc_attr( $account['firstName'] ); ?>\" maxlength=\"100\" required readonly></div>\n\t\t\t\t\t\t\t\t<div class=\"gaccount__field\"><label for=\"gaccount-last\">نام خانوادگی <span class=\"gaccount__required\">*</span></label><input id=\"gaccount-last\" name=\"last_name\" autocomplete=\"family-name\" value=\"<?php echo esc_attr( $account['lastName'] ); ?>\" maxlength=\"100\" required readonly></div>\n\t\t\t\t\t\t\t\t<div class=\"gaccount__field gaccount__field--wide\"><label for=\"gaccount-email\">ایمیل <small>(اختیاری)</small></label><input id=\"gaccount-email\" name=\"email\" type=\"email\" autocomplete=\"email\" value=\"<?php echo esc_attr( $account['email'] ); ?>\" maxlength=\"100\" dir=\"ltr\" readonly></div>\n\t\t\t\t\t\t\t\t<div class=\"gaccount__field gaccount__field--wide\"><label id=\"gaccount-birth-label\">تاریخ تولد <small>(اختیاری)</small></label><div class=\"gaccount__birth-fields\" role=\"group\" aria-labelledby=\"gaccount-birth-label\">\n\t\t\t\t\t\t\t\t\t<select name=\"birth_day\" aria-label=\"روز تولد\" disabled><option value=\"\">روز</option><?php for ( $day = 1; $day <= 31; $day++ ) : ?><option value=\"<?php echo esc_attr( $day ); ?>\"<?php selected( $account['birth']['day'], (string) $day ); ?>><?php echo esc_html( $digits( $day ) ); ?></option><?php endfor; ?></select>\n\t\t\t\t\t\t\t\t\t<select name=\"birth_month\" aria-label=\"ماه تولد\" disabled><option value=\"\">ماه</option><?php foreach ( $months as $month => $label ) : ?><option value=\"<?php echo esc_attr( $month ); ?>\"<?php selected( $account['birth']['month'], (string) $month ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select>\n\t\t\t\t\t\t\t\t\t<select name=\"birth_year\" aria-label=\"سال تولد\" disabled><option value=\"\">سال</option><?php for ( $year = $current_year; $year >= 1200; $year-- ) : ?><option value=\"<?php echo esc_attr( $year ); ?>\"<?php selected( $account['birth']['year'], (string) $year ); ?>><?php echo esc_html( $digits( $year ) ); ?></option><?php endfor; ?></select>\n\t\t\t\t\t\t\t\t</div></div>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<p class=\"gaccount__error\" role=\"alert\" data-profile-error hidden></p>\n\t\t\t\t\t\t\t<div class=\"gaccount__profile-actions\" data-profile-actions hidden><button type=\"submit\" class=\"gaccount__button gaccount__button--primary\">ذخیره تغییرات</button><button type=\"button\" class=\"gaccount__button\" data-profile-cancel>انصراف</button></div>\n\t\t\t\t\t\t</form>\n\t\t\t\t\t</section>\n\t\t\t\t\t<section class=\"gaccount__card gaccount__phone-card\">\n\t\t\t\t\t\t<div class=\"gaccount__card-header\"><h2>شماره موبایل</h2><button type=\"button\" class=\"gaccount__button\" data-phone-open>تغییر شماره</button></div>\n\t\t\t\t\t\t<p class=\"gaccount__phone-description\" data-account-phone-description><?php echo esc_html( $account['phoneVerified'] ? 'شماره‌ی شما برای ورود با کد تأیید و دریافت پیامک سفارش‌ها استفاده می‌شود.' : ( $account['phone'] ? 'این شماره برای تماس و اطلاع‌رسانی سفارش‌ها ثبت شده است و هنوز برای ورود تأیید نشده است.' : 'هنوز شماره موبایلی برای این حساب ثبت نشده است.' ) ); ?></p>\n\t\t\t\t\t\t<div class=\"gaccount__phone-summary\"><strong class=\"gaccount__phone-number\" data-account-phone><?php echo esc_html( $account['phone'] ? $digits( $account['phone'] ) : 'شماره‌ای ثبت نشده است' ); ?></strong><span class=\"gaccount__verified\" data-account-phone-verified<?php echo $account['phoneVerified'] ? '' : ' hidden'; ?>><?php $icon( 'check' ); ?>تأیید شده</span></div>\n\t\t\t\t\t</section>\n\t\t\t\t<?php elseif ( 'addresses' === $active_tab ) : ?>\n\t\t\t\t\t<section class=\"gaccount__card\"><div class=\"gaccount__card-header\"><h2><?php echo esc_html( $navigation_labels['addresses'] ); ?></h2><?php if ( in_array( $address_type, array( 'billing', 'shipping' ), true ) ) : ?><a class=\"gaccount__button\" href=\"<?php echo esc_url( add_query_arg( 'ga_tab', 'addresses', $account['accountUrl'] ) ); ?>\">بازگشت به آدرس‌ها</a><?php endif; ?></div><?php wc_print_notices(); ?><?php if ( in_array( $address_type, array( 'billing', 'shipping' ), true ) ) : ?><div class=\"woocommerce gaccount__native-address\"><?php WC_Shortcode_My_Account::edit_address( $address_type ); ?></div><?php else : ?><div class=\"gaccount__address-list\"><?php foreach ( $account['addresses'] as $address ) : ?><article class=\"gaccount__address\"><h3><?php echo esc_html( $address['label'] ); ?></h3><p><?php echo $address['exists'] ? nl2br( esc_html( $address['formatted'] ) ) : 'آدرسی ثبت نشده است.'; ?></p><a class=\"gaccount__button\" href=\"<?php echo esc_url( $address['editUrl'] ); ?>\"><?php echo $address['exists'] ? 'ویرایش آدرس' : 'افزودن آدرس'; ?></a></article><?php endforeach; ?></div><?php endif; ?></section>\n\t\t\t\t<?php else : ?>\n\t\t\t\t\t<?php\n\t\t\t\t\t$notification_preferences = $account['notificationPreferences'] ?? array();\n\t\t\t\t\t$notification_rows = array(\n\t\t\t\t\t\t'order_status_sms' => array( 'title' => 'پیامک وضعیت سفارش', 'description' => 'با هر تغییر وضعیت سفارش، پیامک دریافت کنید.' ),\n\t\t\t\t\t\t'payment_sms' => array( 'title' => 'پیامک تأیید پرداخت', 'description' => 'پس از بررسی فیش واریزی شما.' ),\n\t\t\t\t\t\t'promotions' => array( 'title' => 'پیشنهادهای ویژه و تخفیف‌ها', 'description' => 'اطلاع‌رسانی از محصولات جدید و کدهای تخفیف.' ),\n\t\t\t\t\t\t'newsletter' => array( 'title' => 'ایمیل خبرنامه', 'description' => 'گزیده‌ی مطالب و محصولات، ماهی یک‌بار.' ),\n\t\t\t\t\t);\n\t\t\t\t\t?>\n\t\t\t\t\t<section class=\"gaccount__card gaccount__preferences\" data-notification-preferences aria-labelledby=\"gaccount-notifications-title\">\n\t\t\t\t\t\t<div class=\"gaccount__card-header\"><h2 id=\"gaccount-notifications-title\"><?php echo esc_html( $navigation_labels['notifications'] ); ?></h2></div>\n\t\t\t\t\t\t<p class=\"gaccount__preferences-help\">هر تغییر به‌صورت خودکار ذخیره می‌شود.</p>\n\t\t\t\t\t\t<div class=\"gaccount__preferences-list\">\n\t\t\t\t\t\t\t<?php foreach ( $notification_rows as $preference => $row ) : ?>\n\t\t\t\t\t\t\t\t<div class=\"gaccount__preference\" data-notification-row>\n\t\t\t\t\t\t\t\t\t<div class=\"gaccount__preference-copy\">\n\t\t\t\t\t\t\t\t\t\t<label id=\"gaccount-notification-<?php echo esc_attr( $preference ); ?>-label\" for=\"gaccount-notification-<?php echo esc_attr( $preference ); ?>\"><?php echo esc_html( $row['title'] ); ?></label>\n\t\t\t\t\t\t\t\t\t\t<p id=\"gaccount-notification-<?php echo esc_attr( $preference ); ?>-description\"><?php echo esc_html( $row['description'] ); ?></p>\n\t\t\t\t\t\t\t\t\t\t<p class=\"gaccount__preference-feedback\" role=\"alert\" data-notification-feedback hidden></p>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t<span class=\"gaccount__preference-switch\">\n\t\t\t\t\t\t\t\t\t\t<input id=\"gaccount-notification-<?php echo esc_attr( $preference ); ?>\" type=\"checkbox\" role=\"switch\" name=\"<?php echo esc_attr( $preference ); ?>\" value=\"1\" data-notification-preference=\"<?php echo esc_attr( $preference ); ?>\" aria-labelledby=\"gaccount-notification-<?php echo esc_attr( $preference ); ?>-label\" aria-describedby=\"gaccount-notification-<?php echo esc_attr( $preference ); ?>-description\"<?php checked( ! empty( $notification_preferences[ $preference ] ) ); ?> disabled>\n\t\t\t\t\t\t\t\t\t\t<span class=\"gaccount__preference-track\" aria-hidden=\"true\"></span>\n\t\t\t\t\t\t\t\t\t</span>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<p class=\"gaccount__preference-status screen-reader-text\" role=\"status\" aria-live=\"polite\" data-notification-status></p>\n\t\t\t\t\t\t<noscript><p class=\"gaccount__error\">برای ذخیره تنظیمات اعلان‌ها، جاوااسکریپت مرورگر را فعال کنید.</p></noscript>\n\t\t\t\t\t</section>\n\t\t\t\t<?php endif; ?>\n\t\t\t</section>\n\t\t</div>\n\t</div>\n\t<div class=\"gaccount__notice\" role=\"status\" aria-live=\"polite\" data-account-notice hidden></div>\n\t<?php if ( 'profile' === $active_tab ) : ?>\n\t\t<dialog class=\"gaccount__dialog\" data-phone-dialog aria-labelledby=\"gaccount-phone-title\" aria-describedby=\"gaccount-phone-help\">\n\t\t\t<div class=\"gaccount__dialog-card\">\n\t\t\t\t<h2 id=\"gaccount-phone-title\">تغییر شماره موبایل</h2>\n\t\t\t\t<p id=\"gaccount-phone-help\" class=\"gaccount__dialog-description\" data-phone-notice role=\"status\">کد تأیید به شماره‌ی جدید ارسال می‌شود.</p>\n\t\t\t\t<div class=\"gaccount__phone-step\" data-phone-step=\"number\"><label for=\"gaccount-new-phone\">شماره‌ی جدید</label><input id=\"gaccount-new-phone\" type=\"tel\" inputmode=\"tel\" autocomplete=\"tel\" placeholder=\"09123456789\" maxlength=\"17\" data-phone-number><div class=\"gaccount__dialog-actions\"><button type=\"button\" class=\"gaccount__button gaccount__button--primary\" data-phone-request>دریافت کد</button><button type=\"button\" class=\"gaccount__button\" data-phone-close>انصراف</button></div></div>\n\t\t\t\t<div class=\"gaccount__phone-step\" data-phone-step=\"code\" hidden><p class=\"gaccount__otp-caption\">کد ۶ رقمی را برای <strong data-phone-preview-number></strong> وارد کنید.</p><div class=\"gaccount__otp\" dir=\"ltr\" role=\"group\" aria-label=\"کد تأیید شش رقمی\"><?php for ( $position = 1; $position <= 6; $position++ ) : ?><input type=\"text\" inputmode=\"numeric\" maxlength=\"<?php echo 1 === $position ? '6' : '1'; ?>\" autocomplete=\"<?php echo 1 === $position ? 'one-time-code' : 'off'; ?>\" aria-label=\"<?php echo esc_attr( 'رقم ' . $digits( $position ) ); ?>\" data-phone-digit><?php endfor; ?></div><div class=\"gaccount__phone-meta\"><button type=\"button\" data-phone-back>ویرایش شماره</button><button type=\"button\" data-phone-resend disabled>ارسال مجدد <span data-phone-timer></span></button></div><div class=\"gaccount__dialog-actions\"><button type=\"button\" class=\"gaccount__button gaccount__button--primary\" data-phone-confirm>تأیید شماره</button></div></div>\n\t\t\t</div>\n\t\t</dialog>\n\t<?php endif; ?>\n</main>\n<?php get_footer(); ?>\n","sha256":"db5cd1e8e728d5016238bb1515c537a7f1d2d0c4ff9f86ec2d1fa79edfb713be"},"page-account-orders.php":{"content":"<?php\n/** Authorized WooCommerce orders; only the orders endpoint uses this view. */\ndefined( 'ABSPATH' ) || exit;\n\n$context = genosys_customer_orders_context();\n$has_access = genosys_order_access_has_proof();\n$show_lookup = ! is_user_logged_in() || ! genosys_sms_normalize_phone( (string) get_user_meta( get_current_user_id(), 'genosys_phone', true ) );\n$access_config = $show_lookup ? genosys_order_access_client_config() : null;\n$digits  = 'genosys_customer_orders_digits';\n$account_url = wc_get_page_permalink( 'myaccount' );\n$shop_url = wc_get_page_id( 'shop' ) > 0 ? wc_get_page_permalink( 'shop' ) : home_url( '/products/' );\n$icon = static function ( $name ) {\n\t$paths = array(\n\t\t'bag' => '<path d=\"M5 8h14l-1.2 12H6.2L5 8Z\"/><path d=\"M9 8V5a3 3 0 0 1 6 0v3\"/>',\n\t\t'check' => '<path d=\"m5 12 4 4 10-10\"/>',\n\t\t'alert' => '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v6m0 3h.01\"/>',\n\t\t'clock' => '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/>',\n\t\t'close' => '<path d=\"m6 6 12 12M18 6 6 18\"/>',\n\t\t'chevron' => '<path d=\"m5 9 7 7 7-7\"/>',\n\t\t'upload' => '<path d=\"M12 16V3m-5 5 5-5 5 5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5\"/>',\n\t);\n\techo '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">' . ( isset( $paths[ $name ] ) ? $paths[ $name ] : '' ) . '</svg>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG paths only.\n};\nget_header();\n?>\n<main id=\"main\" class=\"gorders\" dir=\"rtl\" tabindex=\"-1\" data-time-zone=\"<?php echo esc_attr( wp_timezone_string() ); ?>\" data-time-offset=\"<?php echo esc_attr( wp_timezone()->getOffset( new DateTimeImmutable( 'now' ) ) / 60 ); ?>\">\n\t<div class=\"gorders__container\">\n\t\t<nav class=\"gorders__breadcrumb\" aria-label=\"مسیر صفحه\"><a href=\"<?php echo esc_url( home_url( '/' ) ); ?>\">خانه</a><span aria-hidden=\"true\">/</span><a href=\"<?php echo esc_url( $account_url ); ?>\">حساب کاربری</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">سفارشات</span></nav>\n\t\t<header class=\"gorders__title-row\"><h1 class=\"gorders__title\"><?php echo esc_html( genosys_site_setting( 'orders_title', 'سفارشات من' ) ); ?></h1><?php if ( $has_access ) : ?><span class=\"gorders__count\"><?php echo esc_html( $digits( number_format_i18n( $context['total'] ) ) ); ?> سفارش</span><?php endif; ?></header>\n\t\t<?php if ( $show_lookup ) : ?>\n\t\t\t<details class=\"gorders-access\" data-orders-access data-orders-url=\"<?php echo esc_url( genosys_customer_orders_url() ); ?>\"<?php if ( ! $has_access || ! $context['total'] ) : ?> open<?php endif; ?>>\n\t\t\t\t<summary><span class=\"gorders-access__icon\"><?php $icon( 'bag' ); ?></span><span><?php echo esc_html( $has_access && $context['total'] ? 'مشاهده سفارش‌های دیگر' : 'مشاهده سفارش‌های مهمان' ); ?></span><?php $icon( 'chevron' ); ?></summary>\n\t\t\t\t<div class=\"gorders-access__body\">\n\t\t\t\t\t<p>شماره موبایلی را که هنگام ثبت سفارش وارد کرده‌اید بنویسید. با تأیید کد پیامکی، سفارش‌های مهمان شما نمایش داده می‌شوند.</p>\n\t\t\t\t\t<form class=\"gorders-access__form\" data-orders-access-form novalidate>\n\t\t\t\t\t\t<div data-access-phone-step><label for=\"gorders-access-phone\">شماره موبایل</label><input id=\"gorders-access-phone\" name=\"phone\" type=\"tel\" inputmode=\"tel\" autocomplete=\"tel\" dir=\"ltr\" placeholder=\"09123456789\" required data-access-phone></div>\n\t\t\t\t\t\t<div data-access-code-step hidden><label for=\"gorders-access-code\">کد تأیید پیامکی</label><input id=\"gorders-access-code\" name=\"code\" type=\"text\" inputmode=\"numeric\" autocomplete=\"one-time-code\" dir=\"ltr\" maxlength=\"6\" data-access-code disabled><small data-access-sent></small></div>\n\t\t\t\t\t\t<button type=\"submit\" class=\"gorders-access__submit\" data-access-submit>دریافت کد تأیید</button>\n\t\t\t\t\t\t<div class=\"gorders-access__actions\" data-access-actions hidden><button type=\"button\" data-access-change>تغییر شماره</button><button type=\"button\" data-access-resend disabled>ارسال دوباره کد</button></div>\n\t\t\t\t\t\t<p class=\"gorders-access__message\" role=\"status\" aria-live=\"polite\" data-access-message hidden></p>\n\t\t\t\t\t</form>\n\t\t\t\t\t<?php if ( ! is_user_logged_in() && $has_access ) : ?><button type=\"button\" class=\"gorders-access__clear\" data-access-clear>پایان مشاهده سفارش‌ها</button><?php endif; ?>\n\t\t\t\t\t<noscript><p>برای دریافت کد تأیید، جاوااسکریپت مرورگر را فعال کنید.</p></noscript>\n\t\t\t\t\t<script type=\"application/json\" data-orders-access-config><?php echo wp_json_encode( $access_config, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Safe script-context JSON. ?></script>\n\t\t\t\t</div>\n\t\t\t</details>\n\t\t<?php endif; ?>\n\t\t<?php if ( $has_access ) : ?>\n\t\t\t<?php if ( $context['missingCount'] ) : ?>\n\t\t\t\t<div class=\"gorders__notice\" role=\"status\">\n\t\t\t\t\t<div class=\"gorders__notice-copy\"><?php $icon( 'alert' ); ?><strong><?php echo esc_html( $digits( $context['missingCount'] ) ); ?> سفارش شما منتظر بارگذاری فیش واریزی است.</strong></div>\n\t\t\t\t\t<a class=\"gorders__notice-button\" href=\"<?php echo esc_url( $context['missingOrderURL'] ); ?>\" data-missing-receipts>مشاهده</a>\n\t\t\t\t</div>\n\t\t\t<?php endif; ?>\n\t\t\t<nav class=\"gorders__filters\" aria-label=\"فیلتر وضعیت سفارشات\">\n\t\t\t\t<?php foreach ( $context['filters'] as $key => $filter ) : ?>\n\t\t\t\t\t<a class=\"gorders__filter<?php echo $context['filter'] === $key ? ' is-active' : ''; ?>\" href=\"<?php echo esc_url( $filter['url'] ); ?>\"<?php if ( $context['filter'] === $key ) : ?> aria-current=\"page\"<?php endif; ?>><span><?php echo esc_html( $filter['label'] ); ?></span><span class=\"gorders__filter-count\"><?php echo esc_html( $digits( number_format_i18n( $filter['count'] ) ) ); ?></span></a>\n\t\t\t\t<?php endforeach; ?>\n\t\t\t</nav>\n\t\t\t<div class=\"gorders__list\">\n\t\t\t\t<?php foreach ( $context['orders'] as $order ) : ?>\n\t\t\t\t\t<?php\n\t\t\t\t\t$view = genosys_customer_order_presentation( $order );\n\t\t\t\t\tif ( ! $view ) { continue; }\n\t\t\t\t\t$order_id = $order->get_id();\n\t\t\t\t\t$details_id = 'gorder-details-' . $order_id;\n\t\t\t\t\t$receipt = $view['receipt'];\n\t\t\t\t\t$receipt_review = $receipt ? $receipt['reviewStatus'] : '';\n\t\t\t\t\t$receipt_rejected = $receipt && 'rejected' === $receipt_review;\n\t\t\t\t\t$receipt_state = $receipt ? ( $receipt_rejected ? 'rejected' : 'saved' ) : ( $view['receiptEligible'] ? 'missing' : 'none' );\n\t\t\t\t\t$receipt_can_upload = $view['receiptEligible'] && ( ! $receipt || $receipt_rejected );\n\t\t\t\t\t$receipt_locked = $receipt && ! $receipt_rejected;\n\t\t\t\t\t$receipt_icon = $receipt ? ( 'approved' === $receipt_review ? 'check' : ( 'rejected' === $receipt_review ? 'close' : 'clock' ) ) : 'alert';\n\t\t\t\t\t$payment_card = '';\n\t\t\t\t\t$payment_holder = '';\n\t\t\t\t\tif ( $receipt_can_upload && 'genosys_card_to_card' === $order->get_payment_method() ) {\n\t\t\t\t\t\t$has_snapshot = $order->meta_exists( '_genosys_payment_card' ) || $order->meta_exists( '_genosys_payment_holder' );\n\t\t\t\t\t\t$payment_card = genosys_checkout_card_digits( $has_snapshot ? $order->get_meta( '_genosys_payment_card', true ) : get_option( 'genosys_checkout_card_number', '' ) );\n\t\t\t\t\t\t$payment_holder = trim( (string) ( $has_snapshot ? $order->get_meta( '_genosys_payment_holder', true ) : get_option( 'genosys_checkout_card_holder', '' ) ) );\n\t\t\t\t\t}\n\t\t\t\t\t$tax_included = 'incl' === get_option( 'woocommerce_tax_display_cart', 'excl' );\n\t\t\t\t\t$recipient = trim( $order->get_shipping_first_name() . ' ' . $order->get_shipping_last_name() );\n\t\t\t\t\tif ( '' === $recipient ) { $recipient = trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() ); }\n\t\t\t\t\t$phone = method_exists( $order, 'get_shipping_phone' ) ? $order->get_shipping_phone() : '';\n\t\t\t\t\tif ( '' === $phone ) { $phone = $order->get_billing_phone(); }\n\t\t\t\t\t$address_type = $order->get_shipping_address_1() ? 'shipping' : 'billing';\n\t\t\t\t\t$address_data = $order->get_address( $address_type );\n\t\t\t\t\t$city = isset( $address_data['city'] ) ? $address_data['city'] : '';\n\t\t\t\t\t$state = isset( $address_data['state'] ) ? $address_data['state'] : '';\n\t\t\t\t\t$states = WC()->countries->get_states( isset( $address_data['country'] ) ? $address_data['country'] : '' );\n\t\t\t\t\tif ( is_array( $states ) && isset( $states[ $state ] ) ) { $state = $states[ $state ]; }\n\t\t\t\t\t$address = implode( '، ', array_filter( array( $city, $state !== $city ? $state : '', isset( $address_data['address_1'] ) ? $address_data['address_1'] : '', isset( $address_data['address_2'] ) ? $address_data['address_2'] : '' ) ) );\n\t\t\t\t\t$shipping_name = $order->get_shipping_method();\n\t\t\t\t\t$tipax = false;\n\t\t\t\t\tforeach ( $order->get_shipping_methods() as $shipping_item ) {\n\t\t\t\t\t\t$tipax = $tipax || 'genosys_tipax' === $shipping_item->get_method_id();\n\t\t\t\t\t}\n\t\t\t\t\tif ( $tipax ) { $shipping_name .= ' (پس‌کرایه)'; }\n\t\t\t\t\t?>\n\t\t\t\t\t<article class=\"gorder\" id=\"gco-order-<?php echo esc_attr( $order_id ); ?>\" data-order-id=\"<?php echo esc_attr( $order_id ); ?>\" data-status=\"<?php echo esc_attr( $view['group'] ); ?>\" data-receipt-state=\"<?php echo esc_attr( $receipt_state ); ?>\">\n\t\t\t\t\t\t<div class=\"gorder__summary\">\n\t\t\t\t\t\t\t<div class=\"gorder__heading\"><span class=\"gorder__icon\"><?php $icon( 'bag' ); ?></span><div class=\"gorder__identity\"><h2>سفارش <bdi>#<?php echo esc_html( $digits( $order->get_order_number() ) ); ?></bdi></h2><time datetime=\"<?php echo esc_attr( $view['dateISO'] ); ?>\" data-orders-date><?php echo esc_html( $view['dateText'] ); ?></time></div></div>\n\t\t\t\t\t\t\t<div class=\"gorder__total\"><span>مبلغ کل</span><strong><?php echo wp_kses_post( genosys_customer_orders_price( $order->get_total(), $order->get_currency() ) ); ?></strong></div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div class=\"gorder__toolbar\">\n\t\t\t\t\t\t\t<div class=\"gorder__badges\"><span class=\"gorder__status gorder__status--<?php echo esc_attr( in_array( $view['group'], array( 'pending', 'review', 'preparing', 'shipped', 'delivered', 'cancelled' ), true ) ? $view['group'] : 'other' ); ?>\"><span class=\"gorder__status-dot\" aria-hidden=\"true\"></span><?php echo esc_html( $view['label'] ); ?></span><span class=\"gorder__receipt-badge gorder__receipt-badge--<?php echo esc_attr( $receipt_state ); ?><?php if ( $receipt ) { echo ' gorder__receipt-badge--' . esc_attr( $receipt_review ); } ?>\"<?php if ( $receipt ) : ?> data-receipt-review-status=\"<?php echo esc_attr( $receipt_review ); ?>\"<?php endif; ?>><?php if ( 'none' !== $receipt_state ) { $icon( $receipt_icon ); } ?><?php echo esc_html( $receipt ? 'فیش: ' . $receipt['reviewLabel'] : ( $view['receiptEligible'] ? 'فیش بارگذاری نشده' : 'بدون فیش' ) ); ?></span></div>\n\t\t\t\t\t\t\t<button type=\"button\" class=\"gorder__toggle\" aria-expanded=\"true\" aria-controls=\"<?php echo esc_attr( $details_id ); ?>\"><span data-toggle-label>بستن جزئیات</span><?php $icon( 'chevron' ); ?></button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div class=\"gorder__details\" id=\"<?php echo esc_attr( $details_id ); ?>\">\n\t\t\t\t\t\t\t<section class=\"gorder__section\"><h3>وضعیت سفارش</h3>\n\t\t\t\t\t\t\t\t<?php if ( 0 === $view['stage'] ) : ?><p class=\"gorder__status-note\"><?php echo esc_html( $view['label'] ); ?></p><?php endif; ?>\n\t\t\t\t\t\t\t\t<ol class=\"gorder__timeline\" aria-label=\"مراحل سفارش\">\n\t\t\t\t\t\t\t\t\t<?php foreach ( array( 1 => 'ثبت سفارش', 2 => 'تأیید پرداخت', 3 => 'آماده‌سازی', 4 => 'ارسال', 5 => 'تحویل' ) as $stage => $label ) : ?>\n\t\t\t\t\t\t\t\t\t\t<?php $done = $stage < $view['stage'] || ( 5 === $view['stage'] && 5 === $stage ); ?>\n\t\t\t\t\t\t\t\t\t\t<li class=\"gorder__step<?php echo $done ? ' gorder__step--done' : ( $stage === $view['stage'] ? ' gorder__step--current' : '' ); ?>\"<?php if ( $stage === $view['stage'] ) : ?> aria-current=\"step\"<?php endif; ?>><span class=\"gorder__step-number\"><?php if ( $done ) { $icon( 'check' ); } else { echo esc_html( $digits( $stage ) ); } ?></span><span class=\"gorder__step-label\"><?php echo esc_html( $label ); ?></span><?php if ( $stage === $view['stage'] && $view['stageNote'] ) : ?><small class=\"gorder__step-note\"><?php echo esc_html( $view['stageNote'] ); ?></small><?php endif; ?></li>\n\t\t\t\t\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t\t\t\t</ol>\n\t\t\t\t\t\t\t</section>\n\t\t\t\t\t\t\t<section class=\"gorder__section\"><h3>کالاهای سفارش</h3><div class=\"gorder__products\">\n\t\t\t\t\t\t\t\t<?php foreach ( $order->get_items() as $item ) : ?>\n\t\t\t\t\t\t\t\t\t<?php $product = $item->get_product(); $product_url = $product && $product->is_visible() ? $product->get_permalink() : ''; ?>\n\t\t\t\t\t\t\t\t\t<div class=\"gorder__product\"><div class=\"gorder__product-image\"><?php echo wp_kses_post( $product ? $product->get_image( 'woocommerce_thumbnail', array( 'loading' => 'lazy', 'alt' => $item->get_name() ) ) : wc_placeholder_img( 'woocommerce_thumbnail', array( 'alt' => $item->get_name() ) ) ); ?><span class=\"gorder__product-quantity\"><?php echo esc_html( $digits( $item->get_quantity() ) ); ?></span></div><div class=\"gorder__product-copy\"><h4><?php if ( $product_url ) : ?><a href=\"<?php echo esc_url( $product_url ); ?>\"><?php endif; ?><?php echo esc_html( $item->get_name() ); ?><?php if ( $product_url ) : ?></a><?php endif; ?></h4><span class=\"gorder__product-unit\"><?php echo wp_kses_post( genosys_customer_orders_price( $order->get_item_total( $item, $tax_included ), $order->get_currency() ) ); ?></span><?php wc_display_item_meta( $item ); ?></div><strong class=\"gorder__product-total\"><?php echo wp_kses_post( genosys_customer_orders_price( $order->get_line_total( $item, $tax_included ), $order->get_currency() ) ); ?></strong></div>\n\t\t\t\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t\t\t</div></section>\n\t\t\t\t\t\t\t<section class=\"gorder__section\"><h3>اطلاعات ارسال</h3><div class=\"gorder__info-grid\">\n\t\t\t\t\t\t\t\t<div class=\"gorder__info\"><span class=\"gorder__info-label\">گیرنده</span><span class=\"gorder__info-value\"><?php echo esc_html( $recipient ? $recipient : '—' ); ?></span></div>\n\t\t\t\t\t\t\t\t<div class=\"gorder__info\"><span class=\"gorder__info-label\">شماره تماس</span><span class=\"gorder__info-value\"><bdi dir=\"ltr\"><?php echo esc_html( $phone ? $digits( $phone ) : '—' ); ?></bdi></span></div>\n\t\t\t\t\t\t\t\t<div class=\"gorder__info gorder__info--wide\"><span class=\"gorder__info-label\">آدرس</span><span class=\"gorder__info-value\"><?php echo esc_html( $address ? $digits( $address ) : '—' ); ?></span></div>\n\t\t\t\t\t\t\t\t<div class=\"gorder__info\"><span class=\"gorder__info-label\">روش ارسال</span><span class=\"gorder__info-value\"><?php echo esc_html( $shipping_name ? $shipping_name : '—' ); ?></span></div>\n\t\t\t\t\t\t\t\t<div class=\"gorder__info\"><span class=\"gorder__info-label\">روش پرداخت</span><span class=\"gorder__info-value\"><?php echo esc_html( $order->get_payment_method_title() ? $order->get_payment_method_title() : '—' ); ?></span></div>\n\t\t\t\t\t\t\t</div></section>\n\t\t\t\t\t\t\t<section class=\"gorder__section\"><h3>فیش واریزی</h3>\n\t\t\t\t\t\t\t\t<?php if ( $receipt_rejected ) : ?>\n\t\t\t\t\t\t\t\t\t<div class=\"gorder__receipt-rejected-notice\" role=\"status\" data-orders-rejected-notice>\n\t\t\t\t\t\t\t\t\t\t<span class=\"gorder__receipt-rejected-icon\"><?php $icon( 'alert' ); ?></span><div><strong>فیش قبلی رد شده است؛ لطفاً فیش جدید را بارگذاری کنید.</strong><p><a href=\"<?php echo esc_url( $receipt['downloadUrl'] ); ?>\" dir=\"auto\"><?php echo esc_html( $receipt['name'] ); ?></a> · <time datetime=\"<?php echo esc_attr( $receipt['uploadedAt'] ); ?>\" data-orders-date><?php echo esc_html( $digits( wp_date( 'j F Y، ساعت H:i', strtotime( $receipt['uploadedAt'] ) ) ) ); ?></time></p></div>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<?php endif; ?>\n\t\t\t\t\t\t\t\t<?php if ( 16 === strlen( $payment_card ) && '' !== $payment_holder ) : ?>\n\t\t\t\t\t\t\t\t\t<div class=\"gorder__deposit-card\" aria-label=\"اطلاعات کارت برای واریز\">\n\t\t\t\t\t\t\t\t\t\t<p class=\"gorder__deposit-card-note\">مبلغ سفارش را به کارت زیر واریز کنید و سپس فیش را بارگذاری کنید.</p>\n\t\t\t\t\t\t\t\t\t\t<div class=\"gorder__deposit-card-fields\"><div><span class=\"gorder__deposit-card-label\">شماره کارت</span><bdi class=\"gorder__deposit-card-number\" dir=\"ltr\"><?php echo esc_html( trim( chunk_split( $payment_card, 4, ' ' ) ) ); ?></bdi></div><div><span class=\"gorder__deposit-card-label\">نام و نام خانوادگی صاحب کارت</span><strong class=\"gorder__deposit-card-holder\"><?php echo esc_html( $payment_holder ); ?></strong></div></div>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<?php endif; ?>\n\t\t\t\t\t\t\t\t<div class=\"gorder__receipt\" data-orders-receipt data-state=\"<?php echo $receipt_locked ? 'saved' : 'idle'; ?>\"<?php if ( $receipt ) : ?> data-review-status=\"<?php echo esc_attr( $receipt_review ); ?>\"<?php endif; ?>>\n\t\t\t\t\t\t\t\t\t<span class=\"gorder__receipt-icon\"><?php $icon( $receipt_locked ? $receipt_icon : 'upload' ); ?></span>\n\t\t\t\t\t\t\t\t\t<div class=\"gorder__receipt-copy\"><h4><?php echo esc_html( $receipt_locked ? 'وضعیت فیش: ' . $receipt['reviewLabel'] : ( $receipt_can_upload ? ( $receipt_rejected ? 'فیش جدید را بارگذاری کنید' : 'فیش واریزی را بارگذاری کنید' ) : 'فیش واریزی ثبت نشده است' ) ); ?></h4>\n\t\t\t\t\t\t\t\t\t\t<?php if ( $receipt_locked ) : ?><p><a href=\"<?php echo esc_url( $receipt['downloadUrl'] ); ?>\" dir=\"auto\"><?php echo esc_html( $receipt['name'] ); ?></a> · <time datetime=\"<?php echo esc_attr( $receipt['uploadedAt'] ); ?>\" data-orders-date><?php echo esc_html( $digits( wp_date( 'j F Y، ساعت H:i', strtotime( $receipt['uploadedAt'] ) ) ) ); ?></time></p><?php else : ?><p><?php echo esc_html( $receipt_can_upload ? 'JPG · PNG · WebP · PDF — حداکثر ۵ مگابایت' : ( 'genosys_card_to_card' === $order->get_payment_method() ? 'امکان بارگذاری فیش برای این سفارش وجود ندارد.' : 'برای این روش پرداخت نیازی به بارگذاری فیش نیست.' ) ); ?></p><?php endif; ?>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t<?php if ( $receipt_can_upload && $view['receiptConfig'] ) : ?>\n\t\t\t\t\t\t\t\t\t\t<button type=\"button\" class=\"gorder__receipt-picker\" data-orders-picker>انتخاب فایل</button><input type=\"file\" accept=\"image/jpeg,image/png,image/webp,application/pdf,.jpg,.jpeg,.png,.webp,.pdf\" data-orders-file hidden aria-label=\"انتخاب فیش واریزی\">\n\t\t\t\t\t\t\t\t\t\t<script type=\"application/json\" data-orders-receipt-config><?php echo wp_json_encode( $view['receiptConfig'], JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- JSON_HEX safely encodes script context. ?></script>\n\t\t\t\t\t\t\t\t\t<?php endif; ?>\n\t\t\t\t\t\t\t\t\t<p class=\"gorder__receipt-error\" role=\"alert\" data-orders-error hidden></p>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t</section>\n\t\t\t\t\t\t\t<section class=\"gorder__section\"><h3>خلاصه‌ی مبلغ</h3><div class=\"gorder__amount-summary\">\n\t\t\t\t\t\t\t\t<?php foreach ( $order->get_order_item_totals() as $key => $row ) : ?>\n\t\t\t\t\t\t\t\t\t<?php if ( 'payment_method' === $key ) { continue; } ?>\n\t\t\t\t\t\t\t\t\t<div class=\"gorder__amount-row<?php echo 'order_total' === $key ? ' gorder__amount-row--total' : ''; ?>\"><span><?php echo esc_html( 'cart_subtotal' === $key ? 'جمع کالاها' : ( 'shipping' === $key ? 'هزینه‌ی ارسال' : ( 'order_total' === $key ? 'مبلغ کل' : rtrim( wp_strip_all_tags( $row['label'] ), ':：' ) ) ) ); ?></span><strong><?php echo 'shipping' === $key && $tipax && 0.0 === (float) $order->get_shipping_total() ? 'پس‌کرایه' : wp_kses_post( genosys_checkout_localize_html( $row['value'] ) ); ?></strong></div>\n\t\t\t\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t\t\t</div></section>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</article>\n\t\t\t\t<?php endforeach; ?>\n\t\t\t</div>\n\t\t\t<?php if ( ! $context['orders'] ) : ?><div class=\"gorders__empty\"><span class=\"gorders__empty-icon\"><?php $icon( 'bag' ); ?></span><h2><?php echo esc_html( $context['total'] ? 'سفارشی با این وضعیت پیدا نشد' : 'هنوز سفارشی ثبت نکرده‌اید' ); ?></h2><a class=\"gorders__primary-button\" href=\"<?php echo esc_url( $context['total'] ? genosys_customer_orders_url() : $shop_url ); ?>\"><?php echo esc_html( $context['total'] ? 'مشاهده همه سفارشات' : 'مشاهده محصولات' ); ?></a></div><?php endif; ?>\n\t\t\t<?php if ( $context['pages'] > 1 ) : ?><nav class=\"gorders__pagination\" aria-label=\"صفحه‌بندی سفارشات\"><?php for ( $page_number = 1; $page_number <= $context['pages']; $page_number++ ) : ?><a href=\"<?php echo esc_url( genosys_customer_orders_url( $context['filter'], $page_number ) ); ?>\"<?php if ( $context['currentPage'] === $page_number ) : ?> aria-current=\"page\"<?php endif; ?>><?php echo esc_html( $digits( $page_number ) ); ?></a><?php endfor; ?></nav><?php endif; ?>\n\t\t<?php endif; ?>\n\t</div>\n</main>\n<?php get_footer(); ?>\n","sha256":"80279c4309298aa27c8cf109163cf8faccccbdcd1a87e7f89b0960ae6d13d07c"},"page-brand.php":{"content":"<?php\n/** The Genosys brand: complementary professional skin care. */\ndefined( 'ABSPATH' ) || exit;\n$brand_video = genosys_brand_uploaded_video();\nget_header();\n?>\n<main id=\"main\" class=\"gs-brand\" tabindex=\"-1\">\n\t<h1 id=\"gs-brand-hero-title\" class=\"screen-reader-text\">برند ژنوسیس</h1>\n\t<section class=\"gs-brand-hero\" aria-labelledby=\"gs-brand-hero-title\">\n\t\t<img class=\"gs-brand-hero__poster\" src=\"<?php echo esc_url( get_template_directory_uri() . '/assets/images/brand-film-1.5.73.jpg' ); ?>\" alt=\"\" width=\"1280\" height=\"720\" fetchpriority=\"high\" decoding=\"async\">\n\t\t<?php if ( $brand_video ) : ?>\n\t\t\t<div class=\"gs-brand-hero__video\" aria-hidden=\"true\"><video class=\"gs-brand-hero__hosted\" data-brand-hosted-video autoplay muted loop playsinline preload=\"auto\" tabindex=\"-1\" aria-hidden=\"true\" inert controlslist=\"nodownload nofullscreen noremoteplayback\" disablepictureinpicture disableremoteplayback poster=\"<?php echo esc_url( get_template_directory_uri() . '/assets/images/brand-film-1.5.73.jpg' ); ?>\"><source src=\"<?php echo esc_url( $brand_video['url'] ); ?>\" type=\"<?php echo esc_attr( $brand_video['type'] ); ?>\"></video></div>\n\t\t<?php else : ?>\n\t\t\t<div class=\"gs-brand-hero__video\" data-brand-background-video=\"1044239323\" aria-hidden=\"true\"></div>\n\t\t<?php endif; ?>\n\t\t<div class=\"gs-brand-hero__shade\" aria-hidden=\"true\"></div>\n\t</section>\n\t<section class=\"gs-brand-banner\" aria-labelledby=\"gs-brand-title\">\n\t\t<img class=\"gs-brand-banner__image\" src=\"<?php echo esc_url( get_template_directory_uri() . '/assets/images/brand-banner-1.5.72.webp' ); ?>\" alt=\"مراقبت از پوست با ابزار میکرونیدلینگ ژنوسیس\" width=\"1920\" height=\"1080\" loading=\"lazy\" decoding=\"async\">\n\t\t<div class=\"gs-brand-banner__content\">\n\t\t\t<div class=\"gs-brand-treatments\">\n\t\t\t\t<section class=\"gs-brand-treatment\" aria-labelledby=\"gs-brand-internal-title\" dir=\"rtl\">\n\t\t\t\t\t<h2 id=\"gs-brand-internal-title\">درمان از درون<br><span>(میکرونیدلینگ)</span></h2>\n\t\t\t\t\t<p>تحریک طبیعی تولید کلاژن<br>سامانهٔ انتقال از راه پوست</p>\n\t\t\t\t</section>\n\t\t\t\t<section class=\"gs-brand-treatment\" aria-labelledby=\"gs-brand-external-title\" dir=\"rtl\">\n\t\t\t\t\t<h2 id=\"gs-brand-external-title\">مراقبت از بیرون<br><span>(محصولات آرایشی و مراقبتی)</span></h2>\n\t\t\t\t\t<p>فرمولاسیون سازگار با پوست<br>ترکیبات مؤثر با عملکرد بالا</p>\n\t\t\t\t</section>\n\t\t\t</div>\n\t\t\t<a class=\"gs-brand-next\" href=\"#gs-brand-introduction\" aria-label=\"دربارهٔ برند ژنوسیس بیشتر بخوانید\"><svg viewBox=\"0 0 72 40\" fill=\"none\" aria-hidden=\"true\" focusable=\"false\"><path d=\"m4 4 32 31L68 4\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></a>\n\t\t\t<h2 id=\"gs-brand-title\">مقابله با پیری پوست</h2>\n\t\t\t<p class=\"gs-brand-banner__description\">میکرونیدلینگ روشی مؤثر است که برای رفع دغدغه‌های پوستی، مانند پیری پوست یا جای زخم، ابداع شده است. این روش با ایجاد زخم‌های بسیار ریز در پوست و فعال‌کردن فرایند ترمیم طبیعی آن، به بازسازی پوست و تولید طبیعی کلاژن کمک می‌کند. همچنین با افزایش چشمگیر نفوذپذیری پوست برای جذب مواد مغذی، به مقابله با پیری پوست می‌انجامد.</p>\n\t\t</div>\n\t</section>\n\t<section id=\"gs-brand-introduction\" class=\"gs-brand-introduction\" aria-labelledby=\"gs-brand-introduction-title\" tabindex=\"-1\">\n\t\t<p class=\"gs-brand-eyebrow\">دربارهٔ ژنوسیس</p>\n\t\t<h2 id=\"gs-brand-introduction-title\">سامانهٔ باززایی ژنی</h2>\n\t\t<p class=\"gs-brand-introduction__subtitle\">نخستین برند تخصصی میکرونیدلینگ در جهان</p>\n\t\t<p class=\"gs-brand-introduction__description\">ژنوسیس نخستین برند تخصصی میکرونیدلینگ در جهان است؛ برندی که از ترکیب میکرونیدلینگ با محصولات آرایشی‌درمانی، با فرمولاسیونی ویژهٔ این روش، پدید آمده است تا اثربخشی مراقبت از پوست را به بهترین سطح برساند.</p>\n\t</section>\n\t<section class=\"gs-brand-features gs-brand-shell\" aria-label=\"رویکرد مکمل ژنوسیس به مراقبت از پوست\">\n\t\t<article class=\"gs-brand-treatment-row\" aria-labelledby=\"gs-brand-internal-feature-title\">\n\t\t\t<div class=\"gs-brand-treatment-copy\"><h2 id=\"gs-brand-internal-feature-title\">درمان از درون <span>(میکرونیدلینگ)</span></h2><ul><li>تحریک فرایند طبیعی ترمیم پوست و کمک به تولید کلاژن.</li><li>ایجاد مسیرهای ریز برای افزایش نفوذپذیری پوست و رساندن مواد مغذی.</li></ul></div>\n\t\t\t<div class=\"gs-brand-media\">\n\t\t\t\t<div class=\"gs-brand-video\"><button class=\"gs-brand-video__button\" type=\"button\" data-brand-video=\"1029545187\" data-brand-video-title=\"درمان از درون با میکرونیدلینگ\" aria-label=\"پخش ویدئوی درمان از درون با میکرونیدلینگ\" disabled><img src=\"<?php echo esc_url( get_template_directory_uri() . '/assets/images/brand-internal-1.5.73.jpg' ); ?>\" alt=\"\" width=\"1280\" height=\"720\" loading=\"lazy\" decoding=\"async\"><span class=\"gs-brand-video__play\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" focusable=\"false\"><path d=\"m9 5 10 7-10 7Z\" fill=\"currentColor\"/></svg></span><span class=\"gs-brand-video__label\">پخش ویدئو</span></button></div>\n\t\t\t\t<a class=\"gs-brand-video__fallback\" href=\"https://vimeo.com/1029545187\" target=\"_blank\" rel=\"noopener noreferrer\">تماشای ویدئو</a>\n\t\t\t</div>\n\t\t</article>\n\t\t<article class=\"gs-brand-treatment-row gs-brand-treatment-row--reverse\" aria-labelledby=\"gs-brand-external-feature-title\">\n\t\t\t<div class=\"gs-brand-treatment-copy\"><h2 id=\"gs-brand-external-feature-title\">مراقبت از بیرون <span>(محصولات آرایشی و مراقبتی)</span></h2><ul><li>فرمولاسیون بدون افزودنی‌های مضر، متناسب با نفوذ عمیق‌تر ترکیبات پس از میکرونیدلینگ.</li><li>استفاده از ترکیبات مؤثر برای تکمیل نتیجهٔ مراقبت از پوست.</li></ul></div>\n\t\t\t<div class=\"gs-brand-media\">\n\t\t\t\t<div class=\"gs-brand-video\"><button class=\"gs-brand-video__button\" type=\"button\" data-brand-video=\"1030958117\" data-brand-video-title=\"مراقبت از بیرون با محصولات ژنوسیس\" aria-label=\"پخش ویدئوی مراقبت از بیرون با محصولات ژنوسیس\" disabled><img src=\"<?php echo esc_url( get_template_directory_uri() . '/assets/images/brand-external-1.5.73.jpg' ); ?>\" alt=\"\" width=\"1280\" height=\"720\" loading=\"lazy\" decoding=\"async\"><span class=\"gs-brand-video__play\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" focusable=\"false\"><path d=\"m9 5 10 7-10 7Z\" fill=\"currentColor\"/></svg></span><span class=\"gs-brand-video__label\">پخش ویدئو</span></button></div>\n\t\t\t\t<a class=\"gs-brand-video__fallback\" href=\"https://vimeo.com/1030958117\" target=\"_blank\" rel=\"noopener noreferrer\">تماشای ویدئو</a>\n\t\t\t</div>\n\t\t</article>\n\t</section>\n\t<section class=\"gs-brand-comparisons gs-brand-shell\" aria-labelledby=\"gs-brand-comparisons-title\">\n\t\t<header class=\"gs-brand-comparisons__header\"><h2 id=\"gs-brand-comparisons-title\">مقایسه‌های ارائه‌شده توسط ژنوسیس</h2><p>بازنمایی نمودارهای معرفی برند</p></header>\n\t\t<div class=\"gs-brand-comparison-panels\">\n\t\t\t<article class=\"gs-brand-comparison\" aria-labelledby=\"gs-brand-collagen-title\">\n\t\t\t\t<h3 id=\"gs-brand-collagen-title\">تحریک طبیعی تولید کلاژن</h3>\n\t\t\t\t<figure class=\"gs-brand-histology\"><div class=\"gs-brand-histology__crop\"><img src=\"<?php echo esc_url( get_template_directory_uri() . '/assets/images/brand-histology-1.5.73.png' ); ?>\" alt=\"مقایسهٔ تصاویر بافت‌شناسی گروه کنترل، آی‌پی‌ال و ژنوسیس، از چپ به راست\" width=\"388\" height=\"121\" loading=\"lazy\" decoding=\"async\"></div><div class=\"gs-brand-histology__labels\" aria-hidden=\"true\"><span>گروه کنترل</span><span>آی‌پی‌ال</span><span>ژنوسیس</span></div><figcaption>بررسی بافت‌شناسی با رنگ‌آمیزی ام‌تی، بزرگ‌نمایی ۱۰۰ برابر</figcaption></figure>\n\t\t\t\t<figure class=\"gs-brand-bar-figure\"><div class=\"gs-brand-bars gs-brand-bars--collagen\" role=\"img\" aria-label=\"بازنمایی نمودار مقایسهٔ کلاژن در گروه کنترل، آی‌پی‌ال و ژنوسیس\"><div class=\"gs-brand-bar\" aria-hidden=\"true\"><span class=\"gs-brand-bar__column\"></span><span class=\"gs-brand-bar__label\">گروه کنترل</span></div><div class=\"gs-brand-bar\" aria-hidden=\"true\"><span class=\"gs-brand-bar__column\"></span><span class=\"gs-brand-bar__label\">آی‌پی‌ال</span></div><div class=\"gs-brand-bar\" aria-hidden=\"true\"><span class=\"gs-brand-bar__column\"></span><span class=\"gs-brand-bar__label\">ژنوسیس</span></div></div><figcaption>تحلیل کمّی کلاژن</figcaption></figure>\n\t\t\t</article>\n\t\t\t<article class=\"gs-brand-comparison\" aria-labelledby=\"gs-brand-delivery-title\">\n\t\t\t\t<h3 id=\"gs-brand-delivery-title\">انتقال مواد مغذی از راه پوست</h3>\n\t\t\t\t<figure class=\"gs-brand-delivery\"><div class=\"gs-brand-delivery__legend\"><span><i class=\"gs-brand-key gs-brand-key--red\" aria-hidden=\"true\"></i>ژنوسیس</span><span><i class=\"gs-brand-key gs-brand-key--blue\" aria-hidden=\"true\"></i><bdi dir=\"ltr\">NON</bdi></span></div>\n\t\t\t\t\t<svg class=\"gs-brand-delivery__chart\" viewBox=\"0 0 352 204\" role=\"img\" aria-labelledby=\"gs-brand-delivery-chart-title gs-brand-delivery-chart-desc\" focusable=\"false\"><title id=\"gs-brand-delivery-chart-title\">نمودار عمق نفوذ در گذر زمان</title><desc id=\"gs-brand-delivery-chart-desc\">بازنمایی مسیرهای نمودار ژنوسیس و NON در معرفی برند؛ محور افقی زمان از صفر تا ۶۰ دقیقه و محور عمودی عمق نفوذ از صفر تا ۳۵۰۰ میکرومتر است.</desc>\n\t\t\t\t\t\t<g class=\"gs-brand-chart-grid\" fill=\"none\"><path d=\"M60 15H311M60 36H311M60 56H311M60 77H311M60 98H311M60 119H311M60 140H311\"/><path class=\"gs-brand-chart-axis\" d=\"M60 6V154H311\"/></g>\n\t\t\t\t\t\t<g class=\"gs-brand-chart-ticks\" text-anchor=\"end\"><text x=\"53\" y=\"19\">۳۵۰۰</text><text x=\"53\" y=\"40\">۳۰۰۰</text><text x=\"53\" y=\"60\">۲۵۰۰</text><text x=\"53\" y=\"81\">۲۰۰۰</text><text x=\"53\" y=\"102\">۱۵۰۰</text><text x=\"53\" y=\"123\">۱۰۰۰</text><text x=\"53\" y=\"144\">۵۰۰</text><text x=\"53\" y=\"158\">۰</text></g>\n\t\t\t\t\t\t<g class=\"gs-brand-chart-ticks\" text-anchor=\"middle\"><text x=\"60\" y=\"171\">۰</text><text x=\"102\" y=\"171\">۱۰</text><text x=\"144\" y=\"171\">۲۰</text><text x=\"185\" y=\"171\">۳۰</text><text x=\"227\" y=\"171\">۴۰</text><text x=\"269\" y=\"171\">۵۰</text><text x=\"311\" y=\"171\">۶۰</text></g>\n\t\t\t\t\t\t<g class=\"gs-brand-chart-labels\" text-anchor=\"middle\"><text x=\"187\" y=\"196\" direction=\"rtl\">زمان (دقیقه)</text><text x=\"14\" y=\"83\" transform=\"rotate(-90 14 83)\" direction=\"rtl\">عمق نفوذ (میکرومتر)</text></g>\n\t\t\t\t\t\t<g class=\"gs-brand-chart-genosys\" transform=\"translate(80 36)\" fill=\"none\" stroke=\"currentColor\"><path d=\"M0.705078 99.9198L20.121 90.079L58.872 68.9823L96.9278 78.4264L135.841 21.4305L174.341 11.1818L212.346 1.00146\" stroke-width=\"1.3\"/><g fill=\"currentColor\" stroke=\"none\"><rect x=\"-1.8\" y=\"97.4\" width=\"5\" height=\"5\"/><rect x=\"17.6\" y=\"87.6\" width=\"5\" height=\"5\"/><rect x=\"56.4\" y=\"66.5\" width=\"5\" height=\"5\"/><rect x=\"94.4\" y=\"75.9\" width=\"5\" height=\"5\"/><rect x=\"133.3\" y=\"18.9\" width=\"5\" height=\"5\"/><rect x=\"171.8\" y=\"8.7\" width=\"5\" height=\"5\"/><rect x=\"209.8\" y=\"-1.5\" width=\"5\" height=\"5\"/></g></g>\n\t\t\t\t\t\t<g transform=\"translate(80 129)\" fill=\"none\" stroke=\"#00aeef\"><path d=\"M0.705078 16.1088L20.121 18.9905L58.872 17.407L96.9278 12.4253L135.841 8.03416L174.341 2.87838L212.346 0.336182\" stroke-width=\"1.3\"/><g fill=\"#00aeef\" stroke=\"none\"><circle cx=\".705078\" cy=\"16.1088\" r=\"2.6\"/><circle cx=\"20.121\" cy=\"18.9905\" r=\"2.6\"/><circle cx=\"58.872\" cy=\"17.407\" r=\"2.6\"/><circle cx=\"96.9278\" cy=\"12.4253\" r=\"2.6\"/><circle cx=\"135.841\" cy=\"8.03416\" r=\"2.6\"/><circle cx=\"174.341\" cy=\"2.87838\" r=\"2.6\"/><circle cx=\"212.346\" cy=\".336182\" r=\"2.6\"/></g></g>\n\t\t\t\t\t</svg><figcaption>عمق نفوذ در گذر زمان</figcaption>\n\t\t\t\t</figure>\n\t\t\t\t<figure class=\"gs-brand-bar-figure gs-brand-bar-figure--absorption\"><div class=\"gs-brand-bars gs-brand-bars--absorption\" role=\"img\" aria-label=\"بازنمایی نمودار مقایسهٔ جذب با مرطوب‌کننده، لیپوزوم، یونتوفورزیس و ژنوسیس\"><div class=\"gs-brand-bar\" aria-hidden=\"true\"><span class=\"gs-brand-bar__column\"></span><span class=\"gs-brand-bar__label\">مرطوب‌کننده</span></div><div class=\"gs-brand-bar\" aria-hidden=\"true\"><span class=\"gs-brand-bar__column\"></span><span class=\"gs-brand-bar__label\">لیپوزوم</span></div><div class=\"gs-brand-bar\" aria-hidden=\"true\"><span class=\"gs-brand-bar__column\"></span><span class=\"gs-brand-bar__label\">یونتوفورزیس</span></div><div class=\"gs-brand-bar\" aria-hidden=\"true\"><span class=\"gs-brand-bar__column\"></span><span class=\"gs-brand-bar__label\">ژنوسیس</span></div></div><figcaption>جذب</figcaption></figure>\n\t\t\t</article>\n\t\t</div>\n\t</section>\n\t<section class=\"gs-brand-closing\" aria-labelledby=\"gs-brand-closing-title\"><h2 id=\"gs-brand-closing-title\">مقابله با پیری پوست</h2><p>بازسازی پوست، تولید طبیعی کلاژن و جذب بهتر مواد مغذی؛ سه بخش مکمل در رویکرد ژنوسیس به مراقبت از پوست.</p><a class=\"gs-brand-source\" href=\"http://genosys.info/en/page/11\" target=\"_blank\" rel=\"noopener noreferrer\">منبع: معرفی برند ژنوسیس</a></section>\n</main>\n<?php get_footer(); ?>\n","sha256":"83004f76077ec6a2c29d1b7c84719e98b5fd07e2e028c8863aae1eea1956c624"},"page-cart.php":{"content":"<?php\n/**\n * Cart page. WooCommerce owns the cart session, prices, coupons and checkout.\n *\n * @package Genosys\n */\n\ndefined( 'ABSPATH' ) || exit;\n\n$cart      = function_exists( 'WC' ) && WC() ? WC()->cart : null;\n$cart_url  = function_exists( 'wc_get_cart_url' ) ? wc_get_cart_url() : home_url( '/cart/' );\n$shop_url  = function_exists( 'wc_get_page_permalink' ) && wc_get_page_id( 'shop' ) > 0 ? wc_get_page_permalink( 'shop' ) : home_url( '/products/' );\n$cart_count = $cart ? $cart->get_cart_contents_count() : 0;\n$localize_digits = static function ( $html ) {\n\tif ( ! function_exists( 'genosys_persian_number' ) ) {\n\t\treturn $html;\n\t}\n\t$parts = function_exists( 'wp_html_split' ) ? wp_html_split( $html ) : array( $html );\n\tforeach ( $parts as &$part ) {\n\t\tif ( '' !== $part && '<' !== $part[0] ) {\n\t\t\t$part = esc_html( genosys_persian_number( html_entity_decode( $part, ENT_QUOTES, 'UTF-8' ) ) );\n\t\t}\n\t}\n\treturn implode( '', $parts );\n};\n\nget_header();\n?>\n<main id=\"main\" class=\"genosys-cart-page\" dir=\"rtl\" tabindex=\"-1\">\n\t<div class=\"genosys-cart-container\">\n\t\t<nav class=\"genosys-cart-breadcrumb\" aria-label=\"مسیر صفحه\">\n\t\t\t<a href=\"<?php echo esc_url( home_url( '/' ) ); ?>\">خانه</a>\n\t\t\t<span aria-hidden=\"true\">/</span>\n\t\t\t<span aria-current=\"page\">سبد خرید</span>\n\t\t</nav>\n\t\t<header class=\"genosys-cart-heading\">\n\t\t\t<h1>سبد خرید</h1>\n\t\t\t<span class=\"genosys-cart-count\"><?php echo esc_html( $localize_digits( number_format_i18n( $cart_count ) ) ); ?> کالا</span>\n\t\t</header>\n\n\t\t<?php if ( function_exists( 'wc_print_notices' ) ) { wc_print_notices(); } ?>\n\n\t\t<?php if ( ! $cart || $cart->is_empty() ) : ?>\n\t\t\t<div class=\"genosys-cart-empty\">\n\t\t\t\t<h2>سبد خرید شما خالی است</h2>\n\t\t\t\t<p>محصولات مورد علاقه‌تان را انتخاب کنید و به سبد خرید اضافه کنید.</p>\n\t\t\t\t<a href=\"<?php echo esc_url( $shop_url ); ?>\">مشاهده محصولات</a>\n\t\t\t</div>\n\t\t<?php else : ?>\n\t\t\t<?php\n\t\t\t$show_tax_in_prices = method_exists( $cart, 'display_prices_including_tax' ) && $cart->display_prices_including_tax();\n\t\t\t$sale_savings       = 0.0;\n\t\t\tforeach ( $cart->get_cart() as $saved_item ) {\n\t\t\t\t$saved_product = isset( $saved_item['data'] ) ? $saved_item['data'] : null;\n\t\t\t\tif ( ! $saved_product || ! $saved_product->exists() ) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\t$regular_price = $saved_product->get_regular_price();\n\t\t\t\tif ( '' !== $regular_price && (float) $regular_price > (float) $saved_product->get_price() ) {\n\t\t\t\t\t$sale_savings += max( 0, wc_get_price_to_display( $saved_product, array( 'price' => (float) $regular_price, 'display_context' => 'cart' ) ) - wc_get_price_to_display( $saved_product, array( 'display_context' => 'cart' ) ) ) * (int) $saved_item['quantity'];\n\t\t\t\t}\n\t\t\t}\n\t\t\t$cart_subtotal = (float) $cart->get_subtotal() + ( $show_tax_in_prices ? (float) $cart->get_subtotal_tax() : 0 );\n\t\t\t$coupon_savings = (float) $cart->get_discount_total() + ( $show_tax_in_prices ? (float) $cart->get_discount_tax() : 0 );\n\t\t\t// Cart preview excludes delivery; the selected rate remains payable at checkout.\n\t\t\t$cart_total_without_shipping = max( 0, (float) $cart->get_total( 'edit' ) - (float) $cart->get_shipping_total() - (float) $cart->get_shipping_tax() );\n\t\t\t?>\n\t\t\t<div class=\"genosys-cart-layout\">\n\t\t\t\t<div class=\"genosys-cart-items\">\n\t\t\t\t\t<form id=\"genosys-cart-form\" class=\"genosys-cart-items__form\" action=\"<?php echo esc_url( $cart_url ); ?>\" method=\"post\" data-genosys-cart-form>\n\t\t\t\t\t\t<?php foreach ( $cart->get_cart() as $cart_item_key => $cart_item ) : ?>\n\t\t\t\t\t\t\t<?php\n\t\t\t\t\t\t\t$product = isset( $cart_item['data'] ) ? $cart_item['data'] : null;\n\t\t\t\t\t\t\tif ( ! $product || ! $product->exists() || (int) $cart_item['quantity'] < 1 ) {\n\t\t\t\t\t\t\t\tcontinue;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t$quantity       = (int) $cart_item['quantity'];\n\t\t\t\t\t\t\t$product_url    = $product->is_visible() ? $product->get_permalink( $cart_item ) : '';\n\t\t\t\t\t\t\t$regular_price  = $product->get_regular_price();\n\t\t\t\t\t\t\t$current_price  = (float) $product->get_price();\n\t\t\t\t\t\t\t$on_sale        = '' !== $regular_price && (float) $regular_price > $current_price;\n\t\t\t\t\t\t\t$discount       = $on_sale ? round( ( (float) $regular_price - $current_price ) / (float) $regular_price * 100 ) : 0;\n\t\t\t\t\t\t\t$category_terms = get_the_terms( $product->get_parent_id() ?: $product->get_id(), 'product_cat' );\n\t\t\t\t\t\t\t$category       = is_array( $category_terms ) && ! empty( $category_terms ) ? $category_terms[0]->name : '';\n\t\t\t\t\t\t\t?>\n\t\t\t\t\t\t\t<article class=\"genosys-cart-item\">\n\t\t\t\t\t\t\t\t<div class=\"genosys-cart-item__thumb\">\n\t\t\t\t\t\t\t\t\t<?php if ( $product_url ) : ?><a href=\"<?php echo esc_url( $product_url ); ?>\" aria-label=\"<?php echo esc_attr( $product->get_name() ); ?>\"><?php endif; ?>\n\t\t\t\t\t\t\t\t\t<?php echo wp_kses_post( $product->get_image( 'woocommerce_thumbnail', array( 'loading' => 'lazy' ) ) ); ?>\n\t\t\t\t\t\t\t\t\t<?php if ( $product_url ) : ?></a><?php endif; ?>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<div class=\"genosys-cart-item__details\">\n\t\t\t\t\t\t\t\t\t<?php if ( $category ) : ?><span class=\"genosys-cart-item__category\"><?php echo esc_html( $category ); ?></span><?php endif; ?>\n\t\t\t\t\t\t\t\t\t<h2 class=\"genosys-cart-item__title\">\n\t\t\t\t\t\t\t\t\t\t<?php if ( $product_url ) : ?><a href=\"<?php echo esc_url( $product_url ); ?>\"><?php endif; ?>\n\t\t\t\t\t\t\t\t\t\t<?php echo esc_html( $product->get_name() ); ?>\n\t\t\t\t\t\t\t\t\t\t<?php if ( $product_url ) : ?></a><?php endif; ?>\n\t\t\t\t\t\t\t\t\t</h2>\n\t\t\t\t\t\t\t\t\t<?php echo wp_kses_post( wc_get_formatted_cart_item_data( $cart_item ) ); ?>\n\t\t\t\t\t\t\t\t\t<div class=\"genosys-cart-item__price\">\n\t\t\t\t\t\t\t\t\t\t<?php echo wp_kses_post( $localize_digits( wc_price( wc_get_price_to_display( $product, array( 'display_context' => 'cart' ) ) ) ) ); ?>\n\t\t\t\t\t\t\t\t\t\t<?php if ( $on_sale ) : ?>\n\t\t\t\t\t\t\t\t\t\t\t<del class=\"genosys-cart-item__old-price\"><?php echo wp_kses_post( $localize_digits( wc_price( wc_get_price_to_display( $product, array( 'price' => (float) $regular_price, 'display_context' => 'cart' ) ) ) ) ); ?></del>\n\t\t\t\t\t\t\t\t\t\t\t<span class=\"genosys-cart-item__discount\"><?php echo esc_html( $localize_digits( number_format_i18n( $discount ) ) ); ?>٪ تخفیف</span>\n\t\t\t\t\t\t\t\t\t\t<?php endif; ?>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<div class=\"genosys-cart-item__actions\">\n\t\t\t\t\t\t\t\t\t<strong class=\"genosys-cart-item__subtotal\"><?php echo wp_kses_post( $localize_digits( $cart->get_product_subtotal( $product, $quantity ) ) ); ?></strong>\n\t\t\t\t\t\t\t\t\t<div class=\"genosys-cart-item__quantity\">\n\t\t\t\t\t\t\t\t\t\t<?php\n\t\t\t\t\t\t\t\t\t\tif ( $product->is_sold_individually() ) {\n\t\t\t\t\t\t\t\t\t\t\techo '<span>۱</span><input type=\"hidden\" name=\"cart[' . esc_attr( $cart_item_key ) . '][qty]\" value=\"1\">';\n\t\t\t\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\t\t\t\t?><button class=\"genosys-cart-item__step genosys-cart-item__step--minus\" type=\"button\" data-cart-quantity-change=\"-1\" aria-label=\"کاهش تعداد <?php echo esc_attr( $product->get_name() ); ?>\">−</button><?php\n\t\t\t\t\t\t\t\t\t\t\techo woocommerce_quantity_input( array(\n\t\t\t\t\t\t\t\t\t\t\t'input_name'  => \"cart[{$cart_item_key}][qty]\",\n\t\t\t\t\t\t\t\t\t\t\t'input_value' => $quantity,\n\t\t\t\t\t\t\t\t\t\t\t'max_value'   => $product->get_max_purchase_quantity(),\n\t\t\t\t\t\t\t\t\t\t\t'min_value'   => 0,\n\t\t\t\t\t\t\t\t\t\t\t'product_name' => $product->get_name(),\n\t\t\t\t\t\t\t\t\t\t), $product, false ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- WooCommerce's quantity template escapes the generated fields.\n\t\t\t\t\t\t\t\t\t\t\t?><button class=\"genosys-cart-item__step genosys-cart-item__step--plus\" type=\"button\" data-cart-quantity-change=\"1\" aria-label=\"افزایش تعداد <?php echo esc_attr( $product->get_name() ); ?>\">+</button><?php\n\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t\t\t?>\n\t\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t<a class=\"genosys-cart-item__remove\" href=\"<?php echo esc_url( wc_get_cart_remove_url( $cart_item_key ) ); ?>\" aria-label=\"حذف <?php echo esc_attr( $product->get_name() ); ?> از سبد خرید\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 7h16M9 7V4h6v3m3 0-1 13H7L6 7m4 4v5m4-5v5\"/></svg> حذف</a>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t</article>\n\t\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t\t<button class=\"genosys-cart-update\" type=\"submit\" name=\"update_cart\" value=\"1\">به‌روزرسانی سبد خرید</button>\n\t\t\t\t\t\t<?php wp_nonce_field( 'woocommerce-cart', 'woocommerce-cart-nonce' ); ?>\n\t\t\t\t\t</form>\n\t\t\t\t\t<a class=\"genosys-cart-continue\" href=\"<?php echo esc_url( $shop_url ); ?>\"><span aria-hidden=\"true\">‹</span> ادامه‌ی خرید</a>\n\t\t\t\t</div>\n\n\t\t\t\t<aside class=\"genosys-cart-summary\" aria-labelledby=\"genosys-cart-summary-title\">\n\t\t\t\t\t<h2 class=\"genosys-cart-summary__title\" id=\"genosys-cart-summary-title\">خلاصه‌ی سفارش</h2>\n\t\t\t\t\t<div class=\"genosys-cart-summary__row\"><span>جمع کالاها</span><strong><?php echo wp_kses_post( $localize_digits( wc_price( $cart_subtotal + $sale_savings ) ) ); ?></strong></div>\n\t\t\t\t\t<?php if ( $sale_savings + $coupon_savings > 0 ) : ?>\n\t\t\t\t\t\t<div class=\"genosys-cart-summary__row genosys-cart-summary__row--discount\"><span>سود شما از تخفیف</span><strong><?php echo wp_kses_post( $localize_digits( wc_price( $sale_savings + $coupon_savings ) ) ); ?></strong></div>\n\t\t\t\t\t<?php endif; ?>\n\t\t\t\t\t<?php foreach ( $cart->get_fees() as $fee ) : ?>\n\t\t\t\t\t\t<div class=\"genosys-cart-summary__row\"><span><?php echo esc_html( $fee->name ); ?></span><strong><?php echo wp_kses_post( $localize_digits( wc_price( $fee->total + ( $show_tax_in_prices ? $fee->tax : 0 ) ) ) ); ?></strong></div>\n\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t<?php if ( ! $show_tax_in_prices && $cart->get_total_tax() - $cart->get_shipping_tax() > 0 ) : ?>\n\t\t\t\t\t\t<div class=\"genosys-cart-summary__row\"><span>مالیات</span><strong><?php echo wp_kses_post( $localize_digits( wc_price( $cart->get_total_tax() - $cart->get_shipping_tax() ) ) ); ?></strong></div>\n\t\t\t\t\t<?php endif; ?>\n\t\t\t\t\t<?php if ( function_exists( 'wc_coupons_enabled' ) && wc_coupons_enabled() ) : ?>\n\t\t\t\t\t\t<div class=\"genosys-cart-summary__coupon\">\n\t\t\t\t\t\t\t<label class=\"screen-reader-text\" for=\"genosys-cart-coupon\">کد تخفیف</label>\n\t\t\t\t\t\t\t<input id=\"genosys-cart-coupon\" name=\"coupon_code\" type=\"text\" placeholder=\"کد تخفیف دارید؟\" form=\"genosys-cart-form\">\n\t\t\t\t\t\t\t<button type=\"submit\" name=\"apply_coupon\" value=\"1\" form=\"genosys-cart-form\">اعمال</button>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<?php foreach ( $cart->get_applied_coupons() as $code ) : ?>\n\t\t\t\t\t\t\t<p class=\"genosys-cart-summary__applied-coupon\"><?php echo esc_html( $code ); ?> <a href=\"<?php echo esc_url( add_query_arg( 'remove_coupon', rawurlencode( $code ), $cart_url ) ); ?>\" aria-label=\"حذف کد تخفیف <?php echo esc_attr( $code ); ?>\">حذف</a></p>\n\t\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t<?php endif; ?>\n\t\t\t\t\t<div class=\"genosys-cart-summary__total\"><span>مبلغ قابل پرداخت</span><strong><?php echo wp_kses_post( $localize_digits( wc_price( $cart_total_without_shipping ) ) ); ?></strong></div>\n\t\t\t\t\t<button class=\"genosys-cart-summary__checkout\" type=\"submit\" name=\"proceed\" value=\"1\" form=\"genosys-cart-form\">ادامه جهت تسویه حساب</button>\n\t\t\t\t\t<div class=\"genosys-cart-summary__trust\"><span>✓ ضمانت اصالت کالا</span><span>✓ پرداخت امن</span><span>✓ ارسال سریع</span></div>\n\t\t\t\t</aside>\n\t\t\t</div>\n\t\t<?php endif; ?>\n\t</div>\n</main>\n<?php get_footer(); ?>\n","sha256":"dad586f3b6a7ca30417f5406919525ac84cb360624918c089639aabba67cf021"},"page-checkout.php":{"content":"<?php\n/** The WooCommerce shortcode retains checkout, order-pay, and order-received flows. */\ndefined( 'ABSPATH' ) || exit;\nget_header();\n?>\n<main id=\"main\" class=\"genosys-checkout\" dir=\"rtl\" tabindex=\"-1\">\n\t<div class=\"gco-container\">\n\t\t<?php if ( function_exists( 'WC' ) ) : ?>\n\t\t\t<?php echo do_shortcode( '[woocommerce_checkout]' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- WooCommerce owns checkout rendering. ?>\n\t\t<?php else : ?>\n\t\t\t<p class=\"woocommerce-info\">تسویه‌حساب در حال حاضر در دسترس نیست.</p>\n\t\t<?php endif; ?>\n\t</div>\n</main>\n<?php get_footer(); ?>\n","sha256":"c86e40bd4fecf89dfb7806b5f9f0a32350e4d41e5569ae573b3105064d214526"},"page-company.php":{"content":"<?php\n/** Company story translated from the supplied Genosys company reference. */\ndefined( 'ABSPATH' ) || exit;\n$company_history = array(\n\tarray( 'year' => '2024', 'items' => array( array( 'text' => 'عرضهٔ ژنو ال‌ای‌دی آی‌آر ۲', 'image' => 'assets/images/company-history-2024-01-1.5.77.jpg' ), array( 'text' => 'عرضهٔ ژنو ای‌تی‌جی', 'image' => 'assets/images/company-history-2024-02-1.5.77.jpg' ) ) ),\n\tarray( 'year' => '2021', 'items' => array( array( 'text' => 'عرضهٔ بوستر هیرژن', 'image' => 'assets/images/company-history-2021-01-1.5.77.jpg' ), array( 'text' => 'انتخاب مزوسیس به‌عنوان «محصول برتر» در جوایز سئول (اس‌بی‌ای)', 'image' => '' ), array( 'text' => 'انتخاب به‌عنوان «شرکت کوچکِ پیشرو کره»', 'image' => '' ) ) ),\n\tarray( 'year' => '2020', 'items' => array( array( 'text' => 'انتخاب به‌عنوان «شرکت تازه‌وارد برتر دورهٔ اول» (اس‌بی‌ای)', 'image' => '' ), array( 'text' => 'کسب مدال برنز نمایشگاه اختراعات و پتنت کره برای هیر جنترون', 'image' => '' ) ) ),\n\tarray( 'year' => '2019', 'items' => array( array( 'text' => 'عرضهٔ هیر جنترون', 'image' => 'assets/images/company-history-2019-01-1.5.77.jpg' ) ) ),\n\tarray( 'year' => '2018', 'items' => array( array( 'text' => 'عرضهٔ محفظهٔ یکپارچه با میکرونیدل', 'image' => '' ) ) ),\n\tarray( 'year' => '2017', 'items' => array( array( 'text' => 'انتقال دفتر مرکزی و توسعهٔ تأسیسات تولید و انبار', 'image' => '' ) ) ),\n\tarray( 'year' => '2016', 'items' => array( array( 'text' => 'عرضهٔ ژنو ال‌ای‌دی', 'image' => 'assets/images/company-history-2016-01-1.5.77.jpg' ) ) ),\n\tarray( 'year' => '2015', 'items' => array( array( 'text' => 'معرفی برند مزوتراکس', 'image' => 'assets/images/company-history-2015-01-1.5.77.jpg' ) ) ),\n\tarray( 'year' => '2014', 'items' => array( array( 'text' => 'معرفی برند مزوسیس', 'image' => 'assets/images/company-history-2014-01-1.5.77.jpg' ) ) ),\n\tarray( 'year' => '2013', 'items' => array( array( 'text' => 'تأسیس مرکز تحقیق و توسعه و دریافت تأییدیهٔ آن', 'image' => '' ), array( 'text' => 'انتخاب به‌عنوان «بنگاه نوآور در فناوری»', 'image' => '' ) ) ),\n\tarray( 'year' => '2012', 'items' => array( array( 'text' => 'انتخاب به‌عنوان «شرکت صادراتی آینده‌دار»', 'image' => '' ) ) ),\n\tarray( 'year' => '2011', 'items' => array( array( 'text' => 'راه‌اندازی مرکز تحقیق و توسعه و دریافت تأییدیهٔ آن', 'image' => '' ), array( 'text' => 'دریافت تأییدیهٔ کسب‌وکار نوآور و تأییدیهٔ جی‌ام‌پی', 'image' => '' ), array( 'text' => 'انتخاب در برنامهٔ ۵۰۰ محصول برگزیدهٔ هیت', 'image' => '' ), array( 'text' => 'دریافت تأییدیهٔ ایزو ۱۳۴۸۵ برای رولر ژنوسیس', 'image' => '' ), array( 'text' => 'انتخاب در جمع شرکت‌های برند های سئول', 'image' => '' ) ) ),\n\tarray( 'year' => '2010', 'items' => array( array( 'text' => 'معرفی برند ژنوسیس', 'image' => 'assets/images/company-history-2010-01-1.5.77.jpg' ), array( 'text' => 'انتقال دفتر مرکزی و توسعهٔ تأسیسات تولید با نصب اتاق تمیز', 'image' => '' ) ) ),\n\tarray( 'year' => '2009', 'items' => array( array( 'text' => 'تأسیس شرکت دی‌تی‌اس ام‌جی', 'image' => 'assets/images/company-history-2009-01-1.5.77.jpg' ), array( 'text' => 'عرضهٔ رولر سوزنی دیسکی', 'image' => '' ) ) )\n);\n$company_regions = array(\n\tarray( 'key' => 'asia', 'title' => 'آسیا', 'countries' => array( 'چین', 'هنگ‌کنگ', 'هند', 'اندونزی', 'کره', 'مالزی', 'میانمار', 'سنگاپور', 'تایلند', 'ویتنام' ) ),\n\tarray( 'key' => 'america', 'title' => 'آمریکا', 'countries' => array( 'کانادا', 'شیلی', 'کلمبیا', 'ایالات متحدهٔ آمریکا' ) ),\n\tarray( 'key' => 'africa', 'title' => 'آفریقا', 'countries' => array( 'آفریقای جنوبی', 'تانزانیا' ) ),\n\tarray( 'key' => 'europe', 'title' => 'اروپا', 'countries' => array( 'اتریش', 'ارمنستان', 'جمهوری آذربایجان', 'بلاروس', 'بلژیک', 'بوسنی', 'بلغارستان', 'کرواسی', 'قبرس', 'چک', 'استونی', 'فنلاند', 'فرانسه', 'گرجستان', 'آلمان', 'یونان', 'مجارستان', 'ایرلند', 'لتونی', 'لیتوانی', 'لوکزامبورگ', 'مقدونیه', 'هلند', 'نروژ', 'لهستان', 'رومانی', 'روسیه', 'صربستان', 'اسلواکی', 'اسلوونی', 'ترکیه', 'بریتانیا', 'اوکراین' ) ),\n\tarray( 'key' => 'middleeast', 'title' => 'خاورمیانه', 'countries' => array( 'ایران', 'عراق', 'اردن', 'قزاقستان', 'کویت', 'عربستان سعودی', 'امارات متحدهٔ عربی', 'ازبکستان' ) ),\n\tarray( 'key' => 'oceania', 'title' => 'اقیانوسیه', 'countries' => array( 'نیوزیلند' ) )\n);\n$company_digits = static function ( $value ) { return strtr( (string) $value, array( '0'=>'۰','1'=>'۱','2'=>'۲','3'=>'۳','4'=>'۴','5'=>'۵','6'=>'۶','7'=>'۷','8'=>'۸','9'=>'۹' ) ); };\nget_header();\n?>\n<main id=\"main\" class=\"gs-company\" tabindex=\"-1\">\n    <section class=\"gs-company-intro\" aria-labelledby=\"gs-company-intro-title\">\n        <div class=\"gs-company-shell\">\n        <p class=\"gs-company-intro__eyebrow\">دربارهٔ شرکت ژنوسیس</p>\n        <h1 id=\"gs-company-intro-title\"><span>زیبایی طبیعی</span> خود را بیدار کنید</h1>\n        <p>با فناوری ویژه‌ای که پوست شما به آن نیاز دارد،<br>با فناوری و محصولاتی برای سلامت پوست،<br>زیبایی طبیعی خود را بیدار کنید.</p>\n        </div>\n    </section>\n    <section class=\"gs-company-history\" aria-labelledby=\"gs-company-history-title\">\n        <div class=\"gs-company-shell\">\n            <div class=\"gs-company-history__top\">\n                <header><h2 id=\"gs-company-history-title\">دی‌تی‌اس ام‌جی</h2><p>سامانهٔ درمان با سوزن‌های دیسکی<br>گروه پزشکی</p></header>\n                <div class=\"gs-company-history__controls\" data-history-controls hidden>\n                    <button type=\"button\" data-history-prev aria-label=\"رویدادهای جدیدتر\" aria-controls=\"gs-company-history-track\"><svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"m8 4 8 8-8 8\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></button>\n                    <button type=\"button\" data-history-next aria-label=\"رویدادهای قدیمی‌تر\" aria-controls=\"gs-company-history-track\"><svg viewBox=\"0 0 24 24\" fill=\"none\" aria-hidden=\"true\"><path d=\"m16 4-8 8 8 8\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></button>\n                </div>\n            </div>\n            <div id=\"gs-company-history-track\" class=\"gs-company-history__track\" data-history-track tabindex=\"0\" role=\"region\" aria-label=\"تاریخچهٔ شرکت؛ پیمایش با کلیدهای جهتی\">\n                <?php foreach ( $company_history as $year ) : ?>\n                <article class=\"gs-company-history__year\" aria-labelledby=\"gs-company-year-<?php echo esc_attr( $year['year'] ); ?>\">\n                    <h3 id=\"gs-company-year-<?php echo esc_attr( $year['year'] ); ?>\"><time datetime=\"<?php echo esc_attr( $year['year'] ); ?>\"><?php echo esc_html( $company_digits( $year['year'] ) ); ?></time></h3>\n                    <ul><?php foreach ( $year['items'] as $item ) : ?><li><p><?php echo esc_html( $item['text'] ); ?></p><?php if ( $item['image'] ) : ?><img src=\"<?php echo esc_url( get_theme_file_uri( '/' . $item['image'] ) ); ?>\" alt=\"\" width=\"400\" height=\"160\" loading=\"lazy\" decoding=\"async\" draggable=\"false\"><?php endif; ?></li><?php endforeach; ?></ul>\n                </article>\n                <?php endforeach; ?>\n            </div>\n        </div>\n    </section>\n    <section class=\"gs-company-business gs-company-shell\" aria-labelledby=\"gs-company-business-title\">\n        <header class=\"gs-company-section-heading\"><h2 id=\"gs-company-business-title\">حضور جهانی</h2><p>با حضور در همایش‌های علمی و نمایشگاه‌های بین‌المللی، شناخته‌شدن برند خود را به‌عنوان برندی حرفه‌ای و نوآور گسترش داده‌ایم<br>و اکنون محصولاتمان را به بیش از ۵۰ کشور جهان صادر می‌کنیم.</p></header>\n        <div class=\"gs-company-business__content\">\n            <div class=\"gs-company-business__map\"><img src=\"<?php echo esc_url( get_theme_file_uri( '/assets/images/company-world-map-1.5.77.png' ) ); ?>\" alt=\"نقشهٔ پراکندگی جهانی صادرات ژنوسیس\" width=\"1078\" height=\"494\" loading=\"lazy\" decoding=\"async\"><div class=\"gs-company-business__count\" aria-label=\"صادرات به بیش از ۵۰ کشور\"><strong data-company-counter aria-hidden=\"true\">۵۰</strong><span aria-hidden=\"true\">کشور</span></div></div>\n            <div class=\"gs-company-regions\"><?php foreach ( $company_regions as $region ) : ?><section class=\"gs-company-region gs-company-region--<?php echo esc_attr( $region['key'] ); ?>\" aria-labelledby=\"gs-company-region-<?php echo esc_attr( $region['key'] ); ?>\"><h3 id=\"gs-company-region-<?php echo esc_attr( $region['key'] ); ?>\"><?php echo esc_html( $region['title'] ); ?></h3><ul><?php foreach ( $region['countries'] as $country ) : ?><li><?php echo esc_html( $country ); ?></li><?php endforeach; ?></ul></section><?php endforeach; ?></div>\n        </div>\n    </section>\n    <section class=\"gs-company-facility gs-company-shell\" aria-labelledby=\"gs-company-facility-title\">\n        <header class=\"gs-company-section-heading\"><h2 id=\"gs-company-facility-title\">تأسیسات تولید</h2></header>\n        <figure><div class=\"gs-company-facility__image\"><img src=\"<?php echo esc_url( get_theme_file_uri( '/assets/images/company-facility-1.5.77.jpg' ) ); ?>\" alt=\"خط تولید و اتاق تمیز اختصاصی شرکت ژنوسیس با نشان‌های تأییدیهٔ جی‌ام‌پی و ایزو\" width=\"1656\" height=\"932\" loading=\"lazy\" decoding=\"async\"></div><figcaption>ما تأسیسات تولید و اتاق تمیز اختصاصی خود را با تأییدیه‌های جی‌ام‌پی و ایزو در اختیار داریم.</figcaption></figure>\n    </section>\n</main>\n<?php get_footer(); ?>\n","sha256":"4ffc6ba0578aeb0208df15f1290a077636396940a041dbadeb7afede331aba3f"},"page-contact.php":{"content":"<?php\n/** Contact channels, weekly availability and the private support form. */\ndefined( 'ABSPATH' ) || exit;\n$contact = genosys_contact_page_data();\n$contact_icon = static function ( $name ) {\n\t$paths = array(\n\t\t'phone' => '<path d=\"m8 3 3 5-3 2a14 14 0 0 0 6 6l2-3 5 3-1 5C10 23 1 14 3 4Z\"/>',\n\t\t'whatsapp' => '<path d=\"m3 21 1.5-5A9 9 0 1 1 8 20Z\"/><path d=\"m9 7 2 3-1.5 1a8 8 0 0 0 3.5 3.5l1-1.5 3 2c-1 3-4 2-6 1-3-2-6-6-3-9Z\"/>',\n\t\t'telegram' => '<path d=\"m3 11 18-8-4 18-6-5-3 3 1-6 10-8-12 7Z\"/>',\n\t\t'email' => '<rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"3\"/><path d=\"m4 7 8 6 8-6\"/>',\n\t\t'clock' => '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 6v6l4 2\"/>',\n\t\t'pin' => '<path d=\"M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z\"/><circle cx=\"12\" cy=\"10\" r=\"2.5\"/>',\n\t\t'postal' => '<rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"1\"/><path d=\"M3 9h18\"/>',\n\t\t'attachment' => '<path d=\"m8 13 7-7a3 3 0 0 1 4 4l-9 9a5 5 0 0 1-7-7L13 2m-7 13 9-9\"/>',\n\t\t'instagram' => '<rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M17.5 6.5h.01\"/>',\n\t\t'linkedin' => '<path d=\"M5 9v11M5 5v.01M10 20V9m0 5c0-7 9-7 9 0v6\"/>',\n\t\t'close' => '<path d=\"m6 6 12 12M18 6 6 18\"/>',\n\t);\n\techo '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\">' . ( $paths[ $name ] ?? $paths['email'] ) . '</svg>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed local SVG paths only.\n};\nget_header();\n?>\n<main id=\"main\" class=\"gs-contact\" tabindex=\"-1\" data-contact-page>\n\t<section class=\"gs-contact-hero\" aria-labelledby=\"gs-contact-title\">\n\t\t<svg class=\"gs-contact-wave\" viewBox=\"0 0 280 120\" fill=\"none\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M17 86C65-5 96 24 132 77s74 25 126-57\" stroke=\"#1d1d22\" stroke-width=\"29\" stroke-linecap=\"round\"/><path d=\"M17 74C65-17 96 12 132 65s74 25 126-57\" stroke=\"#fff\" stroke-width=\"29\" stroke-linecap=\"round\"/></svg>\n\t\t<span class=\"gs-contact-disc\" aria-hidden=\"true\"></span>\n\t\t<div class=\"gs-contact-shell\">\n\t\t\t<div class=\"gs-contact-status<?php echo $contact['status']['open'] ? ' is-open' : ''; ?>\"><span class=\"gs-contact-status__dot\" aria-hidden=\"true\"></span><strong><?php echo esc_html( $contact['status']['label'] ); ?></strong><?php if ( '' !== $contact['status']['detail'] ) : ?><span class=\"gs-contact-status__detail\"><?php echo esc_html( $contact['status']['detail'] ); ?></span><?php endif; ?></div>\n\t\t\t<h1 id=\"gs-contact-title\"><?php echo esc_html( $contact['hero_before'] ); ?> <span class=\"gs-contact-highlight\"><?php echo esc_html( $contact['hero_highlight'] ); ?><svg viewBox=\"0 0 270 26\" fill=\"none\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M5 19C40 0 79 28 119 15S200 1 265 15\" stroke=\"currentColor\" stroke-width=\"7\" stroke-linecap=\"round\"/></svg></span> <?php echo esc_html( $contact['hero_after'] ); ?></h1>\n\t\t\t<p class=\"gs-contact-intro\"><?php echo esc_html( $contact['description_line1'] ); ?><br><?php echo esc_html( $contact['description_line2'] ); ?></p>\n\t\t\t<div class=\"gs-contact-channels\">\n\t\t\t\t<?php foreach ( $contact['channels'] as $channel_key => $channel ) : ?>\n\t\t\t\t<article class=\"gs-contact-channel<?php echo 'phone' === $channel_key ? ' gs-contact-channel--featured' : ''; ?>\">\n\t\t\t\t\t<span class=\"gs-contact-channel__icon\"><?php $contact_icon( $channel_key ); ?></span>\n\t\t\t\t\t<h2><?php echo esc_html( $channel['label'] ); ?></h2><p class=\"gs-contact-channel__value<?php echo '' === $channel['value'] ? ' is-empty' : ''; ?>\" dir=\"<?php echo '' === $channel['value'] ? 'rtl' : 'ltr'; ?>\"><?php echo esc_html( '' !== $channel['value'] ? $channel['value'] : $contact['empty_label'] ); ?></p>\n\t\t\t\t\t<div class=\"gs-contact-channel__actions\"><?php if ( '' !== $channel['url'] ) : ?><a class=\"gs-contact-button\" href=\"<?php echo esc_url( $channel['url'], array( 'http', 'https', 'tel', 'mailto' ) ); ?>\"<?php if ( in_array( $channel_key, array( 'whatsapp', 'telegram' ), true ) ) : ?> target=\"_blank\" rel=\"noopener noreferrer\"<?php endif; ?>><?php echo esc_html( $channel['button'] ); ?></a><?php else : ?><button class=\"gs-contact-button\" type=\"button\" disabled><?php echo esc_html( $channel['button'] ); ?></button><?php endif; ?><button class=\"gs-contact-button gs-contact-button--outline\" type=\"button\" data-contact-copy=\"<?php echo esc_attr( $channel['copy'] ); ?>\" data-copied-label=\"<?php echo esc_attr( $contact['copied_label'] ); ?>\" aria-label=\"<?php echo esc_attr( $contact['copy_label'] . ' ' . $channel['label'] ); ?>\"<?php disabled( '', $channel['copy'] ); ?>><?php echo esc_html( $contact['copy_label'] ); ?></button></div>\n\t\t\t\t</article>\n\t\t\t\t<?php endforeach; ?>\n\t\t\t</div>\n\t\t\t<p class=\"gs-contact-copy-status gs-contact-sr-only\" role=\"status\" aria-live=\"polite\" data-contact-copy-status></p>\n\t\t</div>\n\t</section>\n\t<section class=\"gs-contact-main gs-contact-shell\" aria-labelledby=\"gs-contact-form-title\">\n\t\t<div class=\"gs-contact-form-card\">\n\t\t\t<header><h2 id=\"gs-contact-form-title\"><?php echo esc_html( $contact['form']['title'] ); ?></h2><p><?php echo esc_html( $contact['form']['description'] ); ?></p></header>\n\t\t\t<form class=\"gs-contact-form\" data-contact-form method=\"post\" action=\"<?php echo esc_url( admin_url( 'admin-ajax.php' ) ); ?>\" enctype=\"multipart/form-data\" novalidate>\n\t\t\t\t<input type=\"hidden\" name=\"action\" value=\"genosys_contact_submit\"><input type=\"hidden\" name=\"nonce\" value=\"<?php echo esc_attr( wp_create_nonce( 'genosys_contact_submit' ) ); ?>\">\n\t\t\t\t<label class=\"gs-contact-honeypot\" aria-hidden=\"true\">وب‌سایت<input name=\"website\" type=\"text\" tabindex=\"-1\" autocomplete=\"off\"></label>\n\t\t\t\t<fieldset class=\"gs-contact-topics\"><legend><?php echo esc_html( $contact['form']['topic_label'] ); ?></legend><div class=\"gs-contact-topic-list\"><?php $topic_index = 0; foreach ( $contact['form']['topics'] as $topic_id => $topic_label ) : ?><label class=\"gs-contact-topic\"><input type=\"radio\" name=\"topic\" value=\"<?php echo esc_attr( $topic_id ); ?>\"<?php checked( 0, $topic_index++ ); ?> required><span><svg viewBox=\"0 0 18 18\" fill=\"none\" aria-hidden=\"true\"><path d=\"m4 9 3 3 7-7\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg><?php echo esc_html( $topic_label ); ?></span></label><?php endforeach; ?></div><p class=\"gs-contact-field-error\" data-contact-error=\"topic\" hidden></p></fieldset>\n\t\t\t\t<div class=\"gs-contact-field-row\">\n\t\t\t\t\t<div class=\"gs-contact-field\"><label for=\"gs-contact-name\" class=\"gs-contact-sr-only\"><?php echo esc_html( $contact['form']['name_label'] ); ?></label><input id=\"gs-contact-name\" type=\"text\" name=\"fullname\" autocomplete=\"name\" maxlength=\"100\" placeholder=\"<?php echo esc_attr( $contact['form']['name_label'] ); ?>\" aria-describedby=\"gs-contact-name-error\" required><p id=\"gs-contact-name-error\" class=\"gs-contact-field-error\" data-contact-error=\"fullname\" hidden></p></div>\n\t\t\t\t\t<div class=\"gs-contact-field\"><label for=\"gs-contact-phone\" class=\"gs-contact-sr-only\"><?php echo esc_html( $contact['form']['mobile_label'] ); ?></label><input id=\"gs-contact-phone\" type=\"tel\" name=\"mobile\" autocomplete=\"tel\" inputmode=\"tel\" maxlength=\"25\" placeholder=\"<?php echo esc_attr( $contact['form']['mobile_label'] ); ?>\" aria-describedby=\"gs-contact-phone-error\" required><p id=\"gs-contact-phone-error\" class=\"gs-contact-field-error\" data-contact-error=\"mobile\" hidden></p></div>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"gs-contact-field\"><label for=\"gs-contact-email\" class=\"gs-contact-sr-only\"><?php echo esc_html( $contact['form']['email_label'] ); ?></label><input id=\"gs-contact-email\" name=\"email\" type=\"email\" autocomplete=\"email\" maxlength=\"254\" placeholder=\"<?php echo esc_attr( $contact['form']['email_label'] ); ?>\" aria-describedby=\"gs-contact-email-error\"><p id=\"gs-contact-email-error\" class=\"gs-contact-field-error\" data-contact-error=\"email\" hidden></p></div>\n\t\t\t\t<div class=\"gs-contact-field\"><label for=\"gs-contact-message\" class=\"gs-contact-sr-only\"><?php echo esc_html( $contact['form']['message_label'] ); ?></label><div class=\"gs-contact-message-wrap\"><textarea id=\"gs-contact-message\" name=\"message\" rows=\"6\" maxlength=\"500\" placeholder=\"<?php echo esc_attr( $contact['form']['message_label'] ); ?>\" aria-describedby=\"gs-contact-message-error gs-contact-counter\" required></textarea><span class=\"gs-contact-counter\" id=\"gs-contact-counter\"><span data-contact-count>۰</span> / ۵۰۰</span></div><p id=\"gs-contact-message-error\" class=\"gs-contact-field-error\" data-contact-error=\"message\" hidden></p></div>\n\t\t\t\t<div class=\"gs-contact-attachment-wrap\"><label class=\"gs-contact-attachment\" for=\"gs-contact-file\"><?php $contact_icon( 'attachment' ); ?><span><strong><?php echo esc_html( $contact['form']['attachment_label'] ); ?></strong> <span data-contact-file-label><?php echo esc_html( $contact['form']['attachment_hint'] ); ?></span></span><input id=\"gs-contact-file\" type=\"file\" name=\"attachment\" accept=\"image/jpeg,image/png,image/webp,application/pdf\" aria-describedby=\"gs-contact-file-error\"></label><button class=\"gs-contact-file-remove\" type=\"button\" data-contact-file-remove aria-label=\"حذف فایل پیوست\" hidden><?php $contact_icon( 'close' ); ?></button><p id=\"gs-contact-file-error\" class=\"gs-contact-field-error\" data-contact-error=\"attachment\" hidden></p></div>\n\t\t\t\t<div class=\"gs-contact-form-actions\"><div class=\"gs-contact-consent\"><label><input type=\"checkbox\" name=\"consent\" value=\"1\" required aria-describedby=\"gs-contact-consent-error\"><span><?php echo esc_html( $contact['form']['consent_before'] ); ?> <?php if ( '' !== $contact['form']['privacy_url'] ) : ?><a href=\"<?php echo esc_url( $contact['form']['privacy_url'] ); ?>\" target=\"_blank\" rel=\"noopener noreferrer\"><?php echo esc_html( $contact['form']['privacy_label'] ); ?></a><?php else : ?><span class=\"gs-contact-privacy-label\"><?php echo esc_html( $contact['form']['privacy_label'] ); ?></span><?php endif; ?> <?php echo esc_html( $contact['form']['consent_after'] ); ?></span></label><p id=\"gs-contact-consent-error\" class=\"gs-contact-field-error\" data-contact-error=\"consent\" hidden></p></div><button class=\"gs-contact-button gs-contact-submit\" type=\"submit\"><span data-contact-submit-label><?php echo esc_html( $contact['form']['submit_label'] ); ?></span><?php $contact_icon( 'telegram' ); ?></button></div>\n\t\t\t\t<p class=\"gs-contact-form-status\" data-contact-form-status role=\"status\" aria-live=\"polite\" tabindex=\"-1\" hidden></p>\n\t\t\t</form>\n\t\t</div>\n\t\t<aside class=\"gs-contact-sidebar\" aria-label=\"اطلاعات تماس و ساعات پاسخگویی\">\n\t\t\t<section class=\"gs-contact-hours\" aria-labelledby=\"gs-contact-hours-title\"><h2 id=\"gs-contact-hours-title\"><?php $contact_icon( 'clock' ); ?><span><?php echo esc_html( $contact['hours_title'] ); ?></span></h2><ul><?php foreach ( $contact['hours'] as $day ) : ?><li<?php echo $day['today'] ? ' class=\"is-today\" aria-current=\"date\"' : ''; ?>><span><?php echo esc_html( $day['label'] ); ?><?php if ( $day['today'] ) : ?> <span>(<?php echo esc_html( $day['today_label'] ); ?>)</span><?php endif; ?></span><span><?php echo esc_html( $day['text'] ); ?></span></li><?php endforeach; ?></ul></section>\n\t\t\t<section class=\"gs-contact-address\" aria-label=\"نشانی و شبکه‌های اجتماعی\"><div class=\"gs-contact-address-row\"><span class=\"gs-contact-address-icon\"><?php $contact_icon( 'pin' ); ?></span><div><h2><?php echo esc_html( $contact['address_label'] ); ?></h2><p><?php echo esc_html( '' !== $contact['address'] ? $contact['address'] : $contact['empty_label'] ); ?></p></div></div><div class=\"gs-contact-address-row\"><span class=\"gs-contact-address-icon\"><?php $contact_icon( 'postal' ); ?></span><div><h2><?php echo esc_html( $contact['postal_label'] ); ?></h2><p class=\"gs-contact-postal\" dir=\"<?php echo '' === $contact['postal'] ? 'rtl' : 'ltr'; ?>\"><?php echo esc_html( '' !== $contact['postal'] ? $contact['postal'] : $contact['empty_label'] ); ?></p></div></div><div class=\"gs-contact-socials\"><?php foreach ( $contact['socials'] as $network => $social_url ) : if ( '' === $social_url ) { continue; } $social_names = array( 'instagram' => 'اینستاگرام', 'telegram' => 'تلگرام', 'whatsapp' => 'واتساپ', 'linkedin' => 'لینکدین' ); ?><a href=\"<?php echo esc_url( $social_url ); ?>\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"<?php echo esc_attr( $social_names[ $network ] ?? $network ); ?>\"><?php $contact_icon( $network ); ?></a><?php endforeach; ?></div></section>\n\t\t</aside>\n\t</section>\n\t<?php if ( ! empty( $contact['faq']['items'] ) ) : ?>\n\t<section class=\"gs-contact-faq gs-contact-shell\" aria-labelledby=\"gs-contact-faq-title\"><header><h2 id=\"gs-contact-faq-title\"><?php echo esc_html( $contact['faq']['before'] ); ?> <span><?php echo esc_html( $contact['faq']['highlight'] ); ?></span> <?php echo esc_html( $contact['faq']['after'] ); ?></h2><p><?php echo esc_html( $contact['faq']['description'] ); ?></p></header><div class=\"gs-contact-faq-list\"><?php foreach ( $contact['faq']['items'] as $faq ) : ?><details class=\"gs-contact-faq-item\" data-contact-faq><summary><span><?php echo esc_html( $faq['question'] ); ?></span><span class=\"gs-contact-faq-toggle\" aria-hidden=\"true\">+</span></summary><div class=\"gs-contact-faq-answer\"><p><?php echo nl2br( esc_html( $faq['answer'] ) ); ?></p></div></details><?php endforeach; ?></div></section>\n\t<?php endif; ?>\n</main>\n<?php get_footer(); ?>\n","sha256":"5fd58644f3e74cfbda0e49897ea4b48017933b642896a6d42b38774aba11b055"},"page-fans-club.php":{"content":"<?php\n/** Consumer and professional club enrollment questionnaires. */\ndefined( 'ABSPATH' ) || exit;\n$fans_club_context = genosys_club_enrollment_context();\n$fans_club_can_submit = ! empty( $fans_club_context['canSubmit'] );\n$fans_club_types = $fans_club_context['audiences'];\n$fans_club_phone = (string) $fans_club_context['phone'];\n$fans_club_name = (string) $fans_club_context['fullName'];\n$fans_club_account_url = function_exists( 'wc_get_page_permalink' ) ? wc_get_page_permalink( 'myaccount' ) : home_url( '/' );\n$fans_club_back_url = wp_validate_redirect( wp_get_referer() ?: home_url( '/' ), home_url( '/' ) );\n$fans_club_audience = 'consumer' === genosys_site_setting( 'club_default_audience', 'clinic' ) ? 'consumer' : 'clinic';\nif ( empty( $fans_club_types[ $fans_club_audience ]['canSubmit'] ) ) {\n\t$available_type = 'consumer' === $fans_club_audience ? 'clinic' : 'consumer';\n\tif ( ! empty( $fans_club_types[ $available_type ]['canSubmit'] ) ) { $fans_club_audience = $available_type; }\n}\n$fans_club_selected_available = ! empty( $fans_club_types[ $fans_club_audience ]['canSubmit'] );\n$fans_club_is_clinic = 'clinic' === $fans_club_audience;\n$fans_club_copy = static function ( $consumer_key, $clinic_key ) use ( $fans_club_is_clinic ) {\n\t$consumer = (string) genosys_site_setting( $consumer_key );\n\t$clinic = (string) genosys_site_setting( $clinic_key );\n\techo ' data-consumer=\"' . esc_attr( $consumer ) . '\" data-clinic=\"' . esc_attr( $clinic ) . '\">' . esc_html( $fans_club_is_clinic ? $clinic : $consumer );\n};\n$fans_club_membership_panel = static function ( $audience ) use ( $fans_club_types, $fans_club_account_url, $fans_club_context ) {\n\t$state = $fans_club_types[ $audience ];\n\t$other = 'consumer' === $audience ? 'clinic' : 'consumer';\n\t?>\n\t<section class=\"fans-club-membership\" data-fans-membership=\"<?php echo esc_attr( $audience ); ?>\" aria-labelledby=\"fans-club-membership-<?php echo esc_attr( $audience ); ?>\"<?php if ( ! empty( $state['canSubmit'] ) ) : ?> hidden<?php endif; ?>>\n\t\t<span class=\"fans-club-membership__icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1-4.4-4.3 6.1-.9Z\"/><path d=\"m9 11.9 2 2 4-4\"/></svg></span>\n\t\t<h2 id=\"fans-club-membership-<?php echo esc_attr( $audience ); ?>\" tabindex=\"-1\"><?php echo 'consumer' === $audience ? 'عضویت مصرف کننده' : 'عضویت کلینیک / بیوتی تراپیست'; ?></h2>\n\t\t<p class=\"fans-club-membership__message\" data-fans-membership-message role=\"status\" aria-live=\"polite\"><?php echo esc_html( (string) ( $state['message'] ?: ( $fans_club_context['message'] ?: 'برای بررسی وضعیت عضویت، صفحه را دوباره بارگذاری کنید.' ) ) ); ?></p>\n\t\t<p class=\"fans-club-membership__note\">هر حساب و شماره موبایل در هر نوع عضویت، فقط یک بار امکان ثبت‌نام دارد.</p>\n\t\t<div class=\"fans-club-membership__actions\"><a class=\"fans-club-button fans-club-button--primary\" href=\"<?php echo esc_url( home_url( '/fans-club/' ) ); ?>\" data-fans-reload hidden>شروع پرسشنامه</a><button class=\"fans-club-button fans-club-button--primary\" type=\"button\" data-fans-switch-to=\"<?php echo esc_attr( $other ); ?>\"<?php if ( empty( $fans_club_types[ $other ]['canSubmit'] ) ) : ?> hidden<?php endif; ?>><?php echo 'clinic' === $other ? 'عضویت کلینیک / بیوتی تراپیست' : 'عضویت مصرف کننده'; ?></button><a class=\"fans-club-button fans-club-button--secondary\" href=\"<?php echo esc_url( $fans_club_account_url ); ?>\">حساب کاربری</a></div>\n\t</section>\n\t<?php\n};\nget_header();\n?>\n<main id=\"main\" class=\"fans-club-page<?php echo $fans_club_selected_available ? '' : ' fans-club-page--membership'; ?>\" tabindex=\"-1\" data-fans-club data-audience=\"<?php echo esc_attr( $fans_club_audience ); ?>\" data-enrollment-state=\"<?php echo $fans_club_can_submit ? 'available' : 'unavailable'; ?>\">\n\t<nav class=\"fans-club-topbar\" aria-label=\"بازگشت\"><a class=\"fans-club-back\" href=\"<?php echo esc_url( $fans_club_back_url ); ?>\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 12h14m-6-6 6 6-6 6\"/></svg><span>بازگشت</span></a></nav>\n\t<section class=\"fans-club-hero\" aria-labelledby=\"<?php echo $fans_club_selected_available ? 'fans-club-title' : 'fans-club-member-title'; ?>\">\n\t\t<div class=\"fans-club-hero__content\">\n\t\t\t<div class=\"fans-club-audience\" role=\"tablist\" aria-label=\"نوع عضویت در باشگاه\">\n\t\t\t\t<?php foreach ( array( 'consumer', 'clinic' ) as $type ) : $registered = ! empty( $fans_club_types[ $type ]['alreadySubmitted'] ); ?>\n\t\t\t\t<button type=\"button\" role=\"tab\" id=\"fans-audience-<?php echo esc_attr( $type ); ?>\" aria-controls=\"fans-club-<?php echo esc_attr( $type ); ?>\" aria-selected=\"<?php echo $type === $fans_club_audience ? 'true' : 'false'; ?>\" tabindex=\"<?php echo $type === $fans_club_audience ? '0' : '-1'; ?>\" data-fans-audience=\"<?php echo esc_attr( $type ); ?>\" data-registered=\"<?php echo $registered ? 'true' : 'false'; ?>\"><span><?php echo esc_html( genosys_site_setting( 'consumer' === $type ? 'club_consumer_label' : 'club_clinic_label', 'consumer' === $type ? 'مصرف کننده' : 'کلینیک ها و بیوتی تراپیست ها' ) ); ?></span><small data-fans-registration-badge<?php if ( ! $registered ) : ?> hidden<?php endif; ?>>ثبت شده</small></button>\n\t\t\t\t<?php endforeach; ?>\n\t\t\t</div>\n\t\t\t<div data-fans-hero-join<?php if ( ! $fans_club_selected_available ) : ?> hidden<?php endif; ?>>\n\t\t\t<span class=\"fans-club-hero__eyebrow\" data-fans-copy<?php $fans_club_copy( 'club_eyebrow', 'clinic_eyebrow' ); ?></span>\n\t\t\t<h1 id=\"fans-club-title\"><span class=\"fans-club-title-context\" data-fans-copy<?php $fans_club_copy( 'club_title_before', 'clinic_title_before' ); ?></span> <span data-fans-copy<?php $fans_club_copy( 'club_title_highlight', 'clinic_title_highlight' ); ?></span> <span class=\"fans-club-title-context\" data-fans-copy<?php $fans_club_copy( 'club_title_after', 'clinic_title_after' ); ?></span></h1>\n\t\t\t<p><span data-fans-copy<?php $fans_club_copy( 'club_description_line1', 'clinic_description_line1' ); ?></span><br class=\"fans-club-desktop-break\"> <span data-fans-copy<?php $fans_club_copy( 'club_description_line2', 'clinic_description_line2' ); ?></span></p>\n\t\t\t</div>\n\t\t\t<div data-fans-hero-member<?php if ( $fans_club_selected_available ) : ?> hidden<?php endif; ?>>\n\t\t\t<span class=\"fans-club-hero__eyebrow\">باشگاه مشتریان ژنوسیس</span>\n\t\t\t<h1 id=\"fans-club-member-title\"><span class=\"fans-club-title-context\">همراه</span> <span>ژنوسیس</span></h1>\n\t\t\t<p>اطلاعات عضویت شما در این بخش نمایش داده می‌شود.</p>\n\t\t\t</div>\n\t\t</div>\n\t</section>\n\t<section class=\"fans-club-band\" aria-label=\"عضویت در باشگاه مشتریان ژنوسیس\">\n\t\t<div class=\"fans-club-layout\">\n\t\t\t<div class=\"fans-club-form-card\" id=\"fans-club-form-card\">\n\t\t\t\t<div class=\"fans-club-panel\" id=\"fans-club-consumer\" data-fans-panel=\"consumer\" role=\"tabpanel\" aria-labelledby=\"fans-audience-consumer\"<?php if ( $fans_club_is_clinic ) : ?> hidden<?php endif; ?>>\n\t\t\t\t<?php $fans_club_membership_panel( 'consumer' ); ?>\n\t\t\t\t<?php if ( ! empty( $fans_club_types['consumer']['canSubmit'] ) ) : ?>\n\t\t\t\t<header class=\"fans-club-form-card__header\">\n\t\t\t\t\t<h2><?php echo esc_html( genosys_site_setting( 'club_form_title' ) ); ?></h2>\n\t\t\t\t\t<p><?php echo esc_html( genosys_site_setting( 'club_form_description' ) ); ?></p>\n\t\t\t\t</header>\n\t\t\t\t<ol class=\"fans-club-progress\" aria-label=\"مراحل پرسشنامه\">\n\t\t\t\t\t<li class=\"is-current\" data-progress=\"0\" aria-current=\"step\"><span class=\"fans-club-progress__bar\"></span><span>۱. اطلاعات شما</span></li>\n\t\t\t\t\t<li data-progress=\"1\"><span class=\"fans-club-progress__bar\"></span><span>۲. پوست و علایق</span></li>\n\t\t\t\t\t<li data-progress=\"2\"><span class=\"fans-club-progress__bar\"></span><span>۳. نظر شما</span></li>\n\t\t\t\t</ol>\n\t\t\t\t<form class=\"fans-club-form\" id=\"fans-club-form\" data-fans-wizard=\"consumer\" novalidate>\n\t\t\t\t\t<label class=\"fans-club-honeypot\" aria-hidden=\"true\">وب‌سایت<input type=\"text\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\"></label>\n\t\t\t\t\t<div class=\"fans-club-step\" data-step=\"0\">\n\t\t\t\t\t\t<div class=\"fans-club-field\">\n\t\t\t\t\t\t\t<label for=\"fans-name\">نام و نام خانوادگی <span class=\"fans-club-required\">*</span></label>\n\t\t\t\t\t\t\t<input id=\"fans-name\" name=\"full_name\" type=\"text\" value=\"<?php echo esc_attr( $fans_club_name ); ?>\" autocomplete=\"name\" aria-required=\"true\" aria-describedby=\"fans-name-error\">\n\t\t\t\t\t\t\t<p class=\"fans-club-error\" id=\"fans-name-error\" hidden>نام خود را وارد کنید.</p>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div class=\"fans-club-field-grid\">\n\t\t\t\t\t\t\t<div class=\"fans-club-field\">\n\t\t\t\t\t\t\t\t<label for=\"fans-phone\">شماره موبایل <span class=\"fans-club-required\">*</span></label>\n\t\t\t\t\t\t\t\t<input id=\"fans-phone\" name=\"phone\" type=\"tel\" value=\"<?php echo esc_attr( $fans_club_phone ); ?>\" inputmode=\"tel\" autocomplete=\"tel\" readonly aria-readonly=\"true\" data-fans-account-phone aria-required=\"true\" aria-describedby=\"fans-phone-help fans-phone-error\">\n\t\t\t\t\t\t\t\t<p class=\"fans-club-field-help\" id=\"fans-phone-help\">شماره تأییدشده‌ی حساب کاربری شما؛ در این فرم قابل تغییر نیست.</p>\n\t\t\t\t\t\t\t\t<p class=\"fans-club-error\" id=\"fans-phone-error\" hidden>شماره موبایل معتبر نیست (مثل 09123456789).</p>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div class=\"fans-club-field\">\n\t\t\t\t\t\t\t\t<label for=\"fans-email\">ایمیل</label>\n\t\t\t\t\t\t\t\t<input id=\"fans-email\" name=\"email\" type=\"email\" autocomplete=\"email\">\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div class=\"fans-club-field-grid\">\n\t\t\t\t\t\t\t<div class=\"fans-club-field\">\n\t\t\t\t\t\t\t\t<label for=\"fans-city\">شهر</label>\n\t\t\t\t\t\t\t\t<input id=\"fans-city\" name=\"city\" type=\"text\" autocomplete=\"address-level2\">\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t<div class=\"fans-club-field\">\n\t\t\t\t\t\t\t\t<label for=\"fans-age\">بازه‌ی سنی</label>\n\t\t\t\t\t\t\t\t<span class=\"fans-club-select\"><select id=\"fans-age\" name=\"age_range\"><option value=\"\">انتخاب کنید</option><option value=\"under-18\">زیر ۱۸ سال</option><option value=\"18-24\">۱۸ تا ۲۴ سال</option><option value=\"25-34\">۲۵ تا ۳۴ سال</option><option value=\"35-44\">۳۵ تا ۴۴ سال</option><option value=\"45-54\">۴۵ تا ۵۴ سال</option><option value=\"55-plus\">۵۵ سال به بالا</option></select></span>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t<div class=\"fans-club-actions\"><button class=\"fans-club-button fans-club-button--primary\" type=\"button\" data-next>مرحله‌ی بعد</button></div>\n\t\t\t\t\t</div>\n\t\t\t\t\t<div class=\"fans-club-step\" data-step=\"1\" hidden>\n\t\t\t\t\t\t<fieldset class=\"fans-club-choice-group\" data-choice-group=\"skin\" data-single=\"true\">\n\t\t\t\t\t\t\t<legend>نوع پوست شما <span class=\"fans-club-required\">*</span></legend>\n\t\t\t\t\t\t\t<div class=\"fans-club-choices\">\n