ia-describedby=\"clinic-consent-error\"><span>با دریافت اطلاعات همکاری و پیشنهادهای حرفه‌ای ژنوسیس موافقم. <span class=\"fans-club-required\">*</span></span></label><p class=\"fans-club-error\" id=\"clinic-consent-error\" hidden>برای ادامه، موافقت خود را با دریافت اطلاعات همکاری مشخص کنید.</p>\n\t\t\t\t\t\t\t<div class=\"fans-club-actions\"><button class=\"fans-club-button fans-club-button--primary\" type=\"button\" data-register>تکمیل پرسشنامه</button><button class=\"fans-club-button fans-club-button--secondary\" type=\"button\" data-prev>قبلی</button></div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</form>\n\t\t\t\t\t<p class=\"fans-club-feedback\" role=\"status\" data-fans-feedback hidden></p>\n\t\t\t\t<?php endif; ?>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t\t<aside class=\"fans-club-benefits\" aria-label=\"مزایای باشگاه مشتریان\">\n\t\t\t\t<div class=\"fans-club-benefit\"><span class=\"fans-club-benefit__icon\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M3 10h18v11H3zM2 7h20v4H2zM12 7v14M12 7H8.4C6 7 5 6 5 4.6 5 3.3 6 2.5 7.2 2.5 9.1 2.5 11 5.3 12 7Zm0 0h3.6C18 7 19 6 19 4.6c0-1.3-1-2.1-2.2-2.1C14.9 2.5 13 5.3 12 7Z\" /></svg></span><span><strong data-fans-copy data-consumer=\"هدیه و تخفیف اختصاصی\" data-clinic=\"پیشنهادهای ویژه‌ی همکاران\">پیشنهادهای ویژه‌ی همکاران</strong><small data-fans-copy data-consumer=\"پیشنهادهای ویژه‌ی اعضای باشگاه\" data-clinic=\"متناسب با حجم مصرف و نیاز مجموعه‌ی شما\">متناسب با حجم مصرف و نیاز مجموعه‌ی شما</small></span></div>\n\t\t\t\t<div class=\"fans-club-benefit\"><span class=\"fans-club-benefit__icon\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"7\" r=\"3.2\"/><path d=\"M5 21v-2.1c0-4.1 2.5-6.2 7-6.2s7 2.1 7 6.2V21\"/></svg></span><span><strong data-fans-copy data-consumer=\"مشاوره‌ی تخصصی پوست\" data-clinic=\"راهنمای انتخاب محصولات حرفه‌ای\">راهنمای انتخاب محصولات حرفه‌ای</strong><small data-fans-copy data-consumer=\"پیشنهاد محصول بر اساس نیاز شما\" data-clinic=\"هماهنگ با نوع خدمات و نیاز مشتریان شما\">هماهنگ با نوع خدمات و نیاز مشتریان شما</small></span></div>\n\t\t\t\t<div class=\"fans-club-benefit\"><span class=\"fans-club-benefit__icon\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m12 2.6 2.8 5.8 6.4.9-4.6 4.5 1.1 6.4-5.7-3-5.7 3 1.1-6.4-4.6-4.5 6.4-.9Z\"/></svg></span><span><strong data-fans-copy data-consumer=\"دسترسی زودتر به محصولات جدید\" data-clinic=\"آشنایی با محصولات و پروتکل‌ها\">آشنایی با محصولات و پروتکل‌ها</strong><small data-fans-copy data-consumer=\"اولین نفری باشید که امتحان می‌کنید\" data-clinic=\"برای تکمیل خدمات تخصصی کلینیک و بیوتی تراپیست‌ها\">برای تکمیل خدمات تخصصی کلینیک و بیوتی تراپیست‌ها</small></span></div>\n\t\t\t</aside>\n\t\t</div>\n\t</section>\n\t<script type=\"application/json\" data-fans-context><?php echo wp_json_encode( $fans_club_context, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT ); ?></script>\n</main>\n<?php wp_footer(); ?>\n</body>\n</html>\n","sha256":"c039cb9e58b44487d909f7430a48ef60f19f0b4f6ab82a9d0c65ba08c366c623"},"page-login.php":{"content":"<?php\n/** Phone and verification-code screens for SMS sign-in. */\ndefined( 'ABSPATH' ) || exit;\n?><!doctype html>\n<html <?php language_attributes(); ?>>\n<head>\n\t<meta charset=\"<?php bloginfo( 'charset' ); ?>\">\n\t<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\t<?php wp_head(); ?>\n</head>\n<body <?php body_class(); ?>>\n<?php wp_body_open(); ?>\n<main id=\"main\" class=\"genosys-login\" dir=\"rtl\">\n\t<div class=\"genosys-login__background\" aria-hidden=\"true\">\n\t\t<svg viewBox=\"0 0 1920 880\" preserveAspectRatio=\"none\" focusable=\"false\">\n\t\t\t<path fill=\"#fff\" d=\"M0 806C387 923 926 723 1335 658c231-37 428-76 585-128v350H0Z\"/>\n\t\t\t<path fill=\"#cc6d82\" d=\"M0 743C398 843 915 706 1294 657c264-35 469-84 626-154v67c-292 76-472 120-633 146C859 785 420 923 0 813Z\"/>\n\t\t</svg>\n\t</div>\n\t<section class=\"genosys-login__card\" aria-labelledby=\"genosys-login-title\" data-login-card>\n\t\t<header class=\"genosys-login__header\">\n\t\t\t<img class=\"genosys-login__mark\" src=\"<?php echo esc_url( get_theme_file_uri( '/assets/images/genosys-mark.svg' ) ); ?>\" width=\"76\" height=\"76\" alt=\"\">\n\t\t\t<div>\n\t\t\t\t<h1 id=\"genosys-login-title\" data-login-title>ورود به حساب کاربری</h1>\n\t\t\t\t<p data-login-subtitle>به دنیای ژنوسیس خوش آمدید</p>\n\t\t\t</div>\n\t\t</header>\n\n\t\t<form class=\"genosys-login__form\" id=\"genosys-phone-form\" novalidate>\n\t\t\t<p class=\"genosys-login__lead\">شماره تماس خود را وارد کنید تا کد تأیید برای شما ارسال شود.</p>\n\t\t\t<div class=\"genosys-login__field\">\n\t\t\t\t<label for=\"genosys-login-phone\">شماره تماس</label>\n\t\t\t\t<div class=\"genosys-login__phone-wrap\">\n\t\t\t\t\t<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><rect x=\"7\" y=\"2.5\" width=\"10\" height=\"19\" rx=\"2\"/><path d=\"M11 18.5h2\"/></svg>\n\t\t\t\t\t<input id=\"genosys-login-phone\" name=\"phone\" type=\"tel\" inputmode=\"tel\" autocomplete=\"tel-national\" placeholder=\"09123456789\" maxlength=\"16\" aria-describedby=\"genosys-phone-error\" aria-invalid=\"false\">\n\t\t\t\t</div>\n\t\t\t\t<p class=\"genosys-login__error\" id=\"genosys-phone-error\" role=\"alert\" hidden>شماره تماس معتبر نیست (مثال: 09123456789).</p>\n\t\t\t</div>\n\t\t\t<button class=\"genosys-login__primary\" type=\"submit\">دریافت کد</button>\n\t\t</form>\n\n\t\t<form class=\"genosys-login__form genosys-login__form--code\" id=\"genosys-code-form\" novalidate hidden>\n\t\t\t<p class=\"genosys-login__lead\">کد ۶ رقمی ارسال‌شده به <strong id=\"genosys-code-phone\" dir=\"ltr\"></strong> را وارد کنید.</p>\n\t\t\t<div class=\"genosys-login__code-fields\" dir=\"ltr\" role=\"group\" aria-label=\"کد تأیید ۶ رقمی\" aria-describedby=\"genosys-code-error\">\n\t\t\t\t<input type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]*\" autocomplete=\"one-time-code\" maxlength=\"1\" aria-label=\"رقم اول کد تأیید\">\n\t\t\t\t<input type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]*\" maxlength=\"1\" aria-label=\"رقم دوم کد تأیید\">\n\t\t\t\t<input type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]*\" maxlength=\"1\" aria-label=\"رقم سوم کد تأیید\">\n\t\t\t\t<input type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]*\" maxlength=\"1\" aria-label=\"رقم چهارم کد تأیید\">\n\t\t\t\t<input type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]*\" maxlength=\"1\" aria-label=\"رقم پنجم کد تأیید\">\n\t\t\t\t<input type=\"text\" inputmode=\"numeric\" pattern=\"[0-9]*\" maxlength=\"1\" aria-label=\"رقم ششم کد تأیید\">\n\t\t\t</div>\n\t\t\t<p class=\"genosys-login__error genosys-login__code-error\" id=\"genosys-code-error\" role=\"alert\" hidden>کد ۶ رقمی را کامل وارد کنید.</p>\n\t\t\t<div class=\"genosys-login__code-actions\">\n\t\t\t\t<button type=\"button\" class=\"genosys-login__text-button\" id=\"genosys-edit-phone\">ویرایش شماره</button>\n\t\t\t\t<button type=\"button\" class=\"genosys-login__resend\" id=\"genosys-resend-code\" disabled>ارسال مجدد کد <span id=\"genosys-code-timer\" dir=\"ltr\">۰۲:۰۰</span></button>\n\t\t\t</div>\n\t\t\t<button class=\"genosys-login__primary\" type=\"submit\">تأیید شماره</button>\n\t\t</form>\n\n\t\t<form class=\"genosys-login__form genosys-login__form--profile\" id=\"genosys-profile-form\" novalidate hidden>\n\t\t\t<p class=\"genosys-login__lead\">برای ساخت حساب کاربری، نام و نام خانوادگی خود را وارد کنید.</p>\n\t\t\t<div class=\"genosys-login__field\">\n\t\t\t\t<label for=\"genosys-profile-first-name\">نام</label>\n\t\t\t\t<div class=\"genosys-login__input-wrap\">\n\t\t\t\t\t<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"7\" r=\"3.5\"/><path d=\"M4.5 21v-2a7.5 7.5 0 0 1 15 0v2\"/></svg>\n\t\t\t\t\t<input id=\"genosys-profile-first-name\" name=\"first_name\" type=\"text\" autocomplete=\"given-name\" maxlength=\"60\" aria-describedby=\"genosys-profile-first-name-error\" aria-invalid=\"false\" required>\n\t\t\t\t</div>\n\t\t\t\t<p class=\"genosys-login__error\" id=\"genosys-profile-first-name-error\" role=\"alert\" hidden>نام را وارد کنید.</p>\n\t\t\t</div>\n\t\t\t<div class=\"genosys-login__field\">\n\t\t\t\t<label for=\"genosys-profile-last-name\">نام خانوادگی</label>\n\t\t\t\t<div class=\"genosys-login__input-wrap\">\n\t\t\t\t\t<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"7\" r=\"3.5\"/><path d=\"M4.5 21v-2a7.5 7.5 0 0 1 15 0v2\"/></svg>\n\t\t\t\t\t<input id=\"genosys-profile-last-name\" name=\"last_name\" type=\"text\" autocomplete=\"family-name\" maxlength=\"60\" aria-describedby=\"genosys-profile-last-name-error\" aria-invalid=\"false\" required>\n\t\t\t\t</div>\n\t\t\t\t<p class=\"genosys-login__error\" id=\"genosys-profile-last-name-error\" role=\"alert\" hidden>نام خانوادگی را وارد کنید.</p>\n\t\t\t</div>\n\t\t\t<div class=\"genosys-login__field\">\n\t\t\t\t<label for=\"genosys-profile-email\">ایمیل <span class=\"genosys-login__optional\">(اختیاری)</span></label>\n\t\t\t\t<div class=\"genosys-login__input-wrap\">\n\t\t\t\t\t<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><rect x=\"2\" y=\"4\" width=\"20\" height=\"16\" rx=\"2\"/><path d=\"m3 6 9 7 9-7\"/></svg>\n\t\t\t\t\t<input id=\"genosys-profile-email\" name=\"email\" type=\"email\" inputmode=\"email\" autocomplete=\"email\" placeholder=\"name@example.com\" maxlength=\"100\" aria-describedby=\"genosys-profile-email-error\" aria-invalid=\"false\">\n\t\t\t\t</div>\n\t\t\t\t<p class=\"genosys-login__error\" id=\"genosys-profile-email-error\" role=\"alert\" hidden>ایمیل معتبر وارد کنید.</p>\n\t\t\t</div>\n\t\t\t<p class=\"genosys-login__error genosys-login__profile-error\" id=\"genosys-profile-error\" role=\"alert\" hidden></p>\n\t\t\t<button class=\"genosys-login__primary\" type=\"submit\">ثبت و ادامه</button>\n\t\t</form>\n\n\t\t<div class=\"genosys-login__brand\" aria-label=\"GENOSYS · Gene Re-birth System\">\n\t\t\t<img src=\"<?php echo esc_url( get_theme_file_uri( '/assets/images/genosys-logo-1.1.1.svg' ) ); ?>\" width=\"90\" height=\"20\" alt=\"GENOSYS\">\n\t\t\t<span aria-hidden=\"true\">· Gene Re-birth System</span>\n\t\t</div>\n\t</section>\n</main>\n<?php wp_footer(); ?>\n</body>\n</html>\n","sha256":"af340858299c3be631d510215dde5908e665477bc9508218700deed70793ca8a"},"page-shop.php":{"content":"<?php\n/** Shop only: the native WooCommerce catalog query and shared homepage cards. */\ndefined( 'ABSPATH' ) || exit;\nif ( ! function_exists( 'genosys_shop_filters' ) || ! function_exists( 'wc_get_product' ) ) {\n\tget_header();\n\techo '<main id=\"main\" class=\"site-main\" tabindex=\"-1\"><h1>فروشگاه</h1></main>';\n\tget_footer();\n\treturn;\n}\n\nglobal $wp_query;\n$filters = genosys_shop_filters();\n$categories = genosys_shop_categories();\n$bounds = genosys_shop_price_bounds();\n// Keep an active selection visible even when another filter narrows the catalog.\nforeach ( array( 'min_price', 'max_price' ) as $price_key ) {\n\tif ( '' !== $filters[ $price_key ] ) {\n\t\t$bounds['min'] = min( $bounds['min'], (float) $filters[ $price_key ] );\n\t\t$bounds['max'] = max( $bounds['max'], (float) $filters[ $price_key ] );\n\t}\n}\n$shop_url = wc_get_page_permalink( 'shop' );\n$is_product_search = function_exists( 'genosys_is_product_search' ) && genosys_is_product_search();\n$search_term = $is_product_search ? genosys_product_search_term() : '';\n$filter_url = $is_product_search ? home_url( '/' ) : $shop_url;\n$reset_url = $is_product_search ? add_query_arg( array( 's' => $search_term, 'post_type' => 'product' ), $filter_url ) : $shop_url;\n$page = max( 1, (int) get_query_var( 'paged', 1 ) );\n$per_page = max( 1, (int) $wp_query->get( 'posts_per_page' ) );\n$total = (int) $wp_query->found_posts;\n$first = $total ? ( $page - 1 ) * $per_page + 1 : 0;\n$last = min( $total, $page * $per_page );\n$currency = wp_strip_all_tags( html_entity_decode( get_woocommerce_currency_symbol(), ENT_QUOTES, 'UTF-8' ) );\n$price_text = static function ( $number ) {\n\treturn genosys_persian_number( number_format_i18n( (float) $number, wc_get_price_decimals() ) );\n};\n$icon = static function ( $name ) {\n\t$paths = array(\n\t\t'chevron' => '<path d=\"m5 9 7 7 7-7\"/>',\n\t\t'close' => '<path d=\"m6 6 12 12M18 6 6 18\"/>',\n\t\t'filter' => '<path d=\"M4 7h16M4 17h16\"/><circle cx=\"9\" cy=\"7\" r=\"3\" fill=\"white\"/><circle cx=\"15\" cy=\"17\" r=\"3\" fill=\"white\"/>',\n\t);\n\techo '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">' . ( $paths[ $name ] ?? '' ) . '</svg>'; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Fixed SVG only.\n};\n$order_labels = array(\n\t'date' => 'جدیدترین',\n\t'popularity' => 'پرفروش‌ترین',\n\t'rating' => 'بالاترین امتیاز',\n\t'price' => 'ارزان‌ترین',\n\t'price-desc' => 'گران‌ترین',\n\t'menu_order' => 'مرتب‌سازی پیش‌فرض',\n);\n$base_args = array();\nparse_str( (string) wp_parse_url( $shop_url, PHP_URL_QUERY ), $base_args );\nif ( $is_product_search ) {\n\t$base_args = array( 's' => $search_term, 'post_type' => 'product' );\n}\n// Preserve WooCommerce's validated attribute/rating filters alongside our controls.\nforeach ( WC_Query::get_layered_nav_chosen_attributes() as $taxonomy => $selection ) {\n\t$attribute = wc_attribute_taxonomy_slug( $taxonomy );\n\t$base_args[ 'filter_' . $attribute ] = implode( ',', $selection['terms'] );\n\tif ( in_array( $selection['query_type'], array( 'and', 'or' ), true ) ) {\n\t\t$base_args[ 'query_type_' . $attribute ] = $selection['query_type'];\n\t}\n}\nif ( isset( $_GET['rating_filter'] ) && is_scalar( $_GET['rating_filter'] ) && ! is_bool( $_GET['rating_filter'] ) ) {\n\t$ratings = array_values( array_unique( array_intersect( array_map( 'absint', explode( ',', wp_unslash( (string) $_GET['rating_filter'] ) ) ), array( 1, 2, 3, 4, 5 ) ) ) );\n\tif ( $ratings ) {\n\t\t$base_args['rating_filter'] = implode( ',', $ratings );\n\t}\n}\nget_header();\n?>\n<main id=\"main\" class=\"genosys-shop\" dir=\"rtl\" tabindex=\"-1\" data-shop>\n\t<div class=\"genosys-shop__container\">\n\t\t<nav class=\"genosys-shop__breadcrumb\" aria-label=\"مسیر صفحه\"><a href=\"<?php echo esc_url( home_url( '/' ) ); ?>\">خانه</a><span aria-hidden=\"true\">/</span><?php if ( $is_product_search ) : ?><a href=\"<?php echo esc_url( $shop_url ); ?>\">فروشگاه</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">جستجوی محصولات</span><?php else : ?><span aria-current=\"page\">فروشگاه</span><?php endif; ?></nav>\n\t\t<?php if ( $is_product_search ) : ?>\n\t\t\t<div class=\"genosys-shop__heading\"><h1 class=\"genosys-shop__title\">نتایج <em>جستجو</em></h1><p class=\"genosys-shop__description\">محصولات مطابق با «<bdi><?php echo esc_html( $search_term ); ?></bdi>»</p></div>\n\t\t<?php else : ?>\n\t\t\t<h1 class=\"genosys-shop__heading genosys-shop__title\"><?php echo esc_html( genosys_site_setting( 'shop_title' ) ); ?> <em><?php echo esc_html( genosys_site_setting( 'shop_highlight' ) ); ?></em></h1>\n\t\t<?php endif; ?>\n\t\t<div class=\"genosys-shop__layout\">\n\t\t\t<button class=\"genosys-shop__backdrop\" type=\"button\" data-shop-backdrop aria-label=\"بستن فیلترها\" tabindex=\"-1\" hidden></button>\n\t\t\t<aside class=\"genosys-shop__sidebar\" id=\"genosys-shop-filters\" data-shop-sidebar aria-label=\"فیلترهای فروشگاه\" tabindex=\"-1\">\n\t\t\t\t<div class=\"genosys-shop__drawer-header\"><h2 id=\"genosys-shop-filter-title\">فیلتر محصولات</h2><button type=\"button\" data-shop-close aria-label=\"بستن فیلترها\"><?php $icon( 'close' ); ?></button></div>\n\t\t\t\t<form id=\"genosys-shop-filter-form\" class=\"genosys-shop__filter-form\" data-shop-filter-form method=\"get\" action=\"<?php echo esc_url( $filter_url ); ?>\">\n\t\t\t\t\t<?php foreach ( $base_args as $key => $value ) : ?>\n\t\t\t\t\t\t<?php if ( is_scalar( $value ) ) : ?><input type=\"hidden\" name=\"<?php echo esc_attr( $key ); ?>\" value=\"<?php echo esc_attr( (string) $value ); ?>\"><?php endif; ?>\n\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t<details class=\"genosys-shop__panel\" open>\n\t\t\t\t\t\t<summary class=\"genosys-shop__panel-heading\"><span>دسته‌بندی محصولات</span><?php $icon( 'chevron' ); ?></summary>\n\t\t\t\t\t\t<div class=\"genosys-shop__panel-body genosys-shop__categories\">\n\t\t\t\t\t\t\t<?php if ( $categories ) : ?>\n\t\t\t\t\t\t\t\t<?php foreach ( $categories as $category ) : ?>\n\t\t\t\t\t\t\t\t\t<label class=\"genosys-shop__category-row\" style=\"--category-depth:<?php echo esc_attr( min( 4, count( get_ancestors( $category->term_id, 'product_cat', 'taxonomy' ) ) ) ); ?>\">\n\t\t\t\t\t\t\t\t\t\t<input type=\"checkbox\" name=\"shop_cat[]\" value=\"<?php echo esc_attr( $category->term_id ); ?>\" <?php checked( in_array( (int) $category->term_id, $filters['categories'], true ) ); ?> data-shop-autosubmit>\n\t\t\t\t\t\t\t\t\t\t<span class=\"genosys-shop__category-name\"><?php echo esc_html( $category->name ); ?></span>\n\t\t\t\t\t\t\t\t\t\t<span class=\"genosys-shop__category-count\"><?php echo esc_html( genosys_persian_number( number_format_i18n( $category->count ) ) ); ?></span>\n\t\t\t\t\t\t\t\t\t</label>\n\t\t\t\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t\t\t<?php else : ?><p class=\"genosys-shop__muted\">هنوز دسته‌بندی محصولی وجود ندارد.</p><?php endif; ?>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</details>\n\t\t\t\t\t<details class=\"genosys-shop__panel\" open>\n\t\t\t\t\t\t<summary class=\"genosys-shop__panel-heading\"><span>محدوده‌ی قیمت</span><?php $icon( 'chevron' ); ?></summary>\n\t\t\t\t\t\t<div class=\"genosys-shop__panel-body\">\n\t\t\t\t\t\t\t<div class=\"genosys-shop__price-controls\" data-shop-price data-min=\"<?php echo esc_attr( $bounds['min'] ); ?>\" data-max=\"<?php echo esc_attr( $bounds['max'] ); ?>\">\n\t\t\t\t\t\t\t\t<div class=\"genosys-shop__price-range\">\n\t\t\t\t\t\t\t\t<div class=\"genosys-shop__range-track\">\n\t\t\t\t\t\t\t\t\t<span class=\"genosys-shop__price-fill\" data-price-fill aria-hidden=\"true\"></span>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t\t<input type=\"range\" min=\"<?php echo esc_attr( $bounds['min'] ); ?>\" max=\"<?php echo esc_attr( $bounds['max'] ); ?>\" step=\"<?php echo esc_attr( $bounds['step'] ); ?>\" value=\"<?php echo esc_attr( '' !== $filters['min_price'] ? max( $bounds['min'], min( $bounds['max'], (float) $filters['min_price'] ) ) : $bounds['min'] ); ?>\" data-price-range=\"min\" aria-label=\"حداقل قیمت\">\n\t\t\t\t\t\t\t\t\t<input type=\"range\" min=\"<?php echo esc_attr( $bounds['min'] ); ?>\" max=\"<?php echo esc_attr( $bounds['max'] ); ?>\" step=\"<?php echo esc_attr( $bounds['step'] ); ?>\" value=\"<?php echo esc_attr( '' !== $filters['max_price'] ? max( $bounds['min'], min( $bounds['max'], (float) $filters['max_price'] ) ) : $bounds['max'] ); ?>\" data-price-range=\"max\" aria-label=\"حداکثر قیمت\">\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<div class=\"genosys-shop__price-values\">\n\t\t\t\t\t\t\t\t\t<label class=\"genosys-shop__price-box\"><span>از</span><input type=\"text\" inputmode=\"decimal\" name=\"min_price\" data-price-input=\"min\" value=\"<?php echo esc_attr( '' !== $filters['min_price'] ? $price_text( $filters['min_price'] ) : '' ); ?>\" placeholder=\"<?php echo esc_attr( $price_text( $bounds['min'] ) ); ?>\" autocomplete=\"off\" aria-label=\"قیمت از\"></label>\n\t\t\t\t\t\t\t\t\t<label class=\"genosys-shop__price-box\"><span>تا</span><input type=\"text\" inputmode=\"decimal\" name=\"max_price\" data-price-input=\"max\" value=\"<?php echo esc_attr( '' !== $filters['max_price'] ? $price_text( $filters['max_price'] ) : '' ); ?>\" placeholder=\"<?php echo esc_attr( $price_text( $bounds['max'] ) ); ?>\" autocomplete=\"off\" aria-label=\"قیمت تا\"></label>\n\t\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t\t\t<p class=\"genosys-shop__price-currency\"><?php echo esc_html( 'قیمت‌ها به ' . $currency ); ?></p>\n\t\t\t\t\t\t\t</div>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</details>\n\t\t\t\t\t<details class=\"genosys-shop__panel\" open>\n\t\t\t\t\t\t<summary class=\"genosys-shop__panel-heading\"><span>وضعیت</span><?php $icon( 'chevron' ); ?></summary>\n\t\t\t\t\t\t<div class=\"genosys-shop__panel-body genosys-shop__status\">\n\t\t\t\t\t\t\t<label class=\"genosys-shop__status-row\"><span>فقط کالاهای موجود</span><input type=\"checkbox\" name=\"only_in_stock\" value=\"1\" <?php checked( $filters['only_in_stock'] ); ?> data-shop-autosubmit><span class=\"genosys-shop__switch\" aria-hidden=\"true\"></span></label>\n\t\t\t\t\t\t\t<label class=\"genosys-shop__status-row\"><span>فقط کالاهای تخفیف‌دار</span><input type=\"checkbox\" name=\"only_on_sale\" value=\"1\" <?php checked( $filters['only_on_sale'] ); ?> data-shop-autosubmit><span class=\"genosys-shop__switch\" aria-hidden=\"true\"></span></label>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</details>\n\t\t\t\t\t<button class=\"genosys-shop__apply\" type=\"submit\" data-shop-apply>اعمال فیلترها</button>\n\t\t\t\t\t<a class=\"genosys-shop__reset\" href=\"<?php echo esc_url( $reset_url ); ?>\">حذف همه‌ی فیلترها</a>\n\t\t\t\t</form>\n\t\t\t</aside>\n\t\t\t<section class=\"genosys-shop__main\" aria-label=\"محصولات فروشگاه\">\n\t\t\t\t<div class=\"genosys-shop__toolbar\">\n\t\t\t\t\t<p class=\"genosys-shop__count\" aria-live=\"polite\">نمایش <strong><?php echo esc_html( genosys_persian_number( $first ) ); ?></strong> تا <strong><?php echo esc_html( genosys_persian_number( $last ) ); ?></strong> از <strong><?php echo esc_html( genosys_persian_number( $total ) ); ?></strong> محصول</p>\n\t\t\t\t\t<div class=\"genosys-shop__toolbar-actions\">\n\t\t\t\t\t\t<button class=\"genosys-shop__filter-toggle\" type=\"button\" data-shop-open aria-expanded=\"false\" aria-controls=\"genosys-shop-filters\"><?php $icon( 'filter' ); ?><span>فیلترها</span></button>\n\t\t\t\t\t\t<label class=\"genosys-shop__sort\"><span class=\"screen-reader-text\">مرتب‌سازی محصولات</span><select name=\"orderby\" form=\"genosys-shop-filter-form\" data-shop-autosubmit aria-label=\"مرتب‌سازی محصولات\"><?php foreach ( $order_labels as $value => $label ) : ?><option value=\"<?php echo esc_attr( $value ); ?>\" <?php selected( $filters['orderby'], $value ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select><?php $icon( 'chevron' ); ?></label>\n\t\t\t\t\t</div>\n\t\t\t\t</div>\n\t\t\t\t<?php if ( have_posts() ) : ?>\n\t\t\t\t\t<div class=\"genosys-shop__grid\">\n\t\t\t\t\t\t<?php while ( have_posts() ) : the_post(); ?>\n\t\t\t\t\t\t\t<?php get_template_part( 'template-parts/product/card', null, array( 'product' => wc_get_product( get_the_ID() ) ) ); ?>\n\t\t\t\t\t\t<?php endwhile; ?>\n\t\t\t\t\t</div>\n\t\t\t\t\t<?php $pagination = genosys_shop_pagination(); ?>\n\t\t\t\t\t<?php if ( $pagination ) : ?>\n\t\t\t\t\t\t<nav class=\"genosys-shop__pagination\" aria-label=\"صفحه‌های محصولات\">\n\t\t\t\t\t\t\t<?php if ( 1 === $page ) : ?><span class=\"page-numbers prev is-disabled\" aria-disabled=\"true\">قبلی</span><?php endif; ?>\n\t\t\t\t\t\t\t<?php foreach ( $pagination as $link ) : ?>\n\t\t\t\t\t\t\t\t<?php\n\t\t\t\t\t\t\t\t$parts = wp_html_split( $link );\n\t\t\t\t\t\t\t\tforeach ( $parts as $part_index => $part ) {\n\t\t\t\t\t\t\t\t\tif ( '' !== $part && '<' !== $part[0] ) {\n\t\t\t\t\t\t\t\t\t\t$parts[ $part_index ] = genosys_persian_number( $part );\n\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\techo wp_kses_post( implode( '', $parts ) );\n\t\t\t\t\t\t\t\t?>\n\t\t\t\t\t\t\t<?php endforeach; ?>\n\t\t\t\t\t\t\t<?php if ( $page >= (int) $wp_query->max_num_pages ) : ?><span class=\"page-numbers next is-disabled\" aria-disabled=\"true\">بعدی</span><?php endif; ?>\n\t\t\t\t\t\t</nav>\n\t\t\t\t\t<?php endif; ?>\n\t\t\t\t<?php else : ?>\n\t\t\t\t\t<div class=\"genosys-shop__empty\"><h2>محصولی یافت نشد</h2><p><?php echo $is_product_search ? 'نام محصول یا کد SKU دیگری را جستجو کنید، یا فیلترها را تغییر دهید.' : 'برای دیدن محصولات، فیلترهای انتخاب‌شده را تغییر دهید.'; ?></p><a class=\"genosys-shop__reset\" href=\"<?php echo esc_url( $is_product_search ? $shop_url : $reset_url ); ?>\"><?php echo $is_product_search ? 'مشاهده همه محصولات' : 'حذف همه‌ی فیلترها'; ?></a></div>\n\t\t\t\t<?php endif; ?>\n\t\t\t\t<p class=\"screen-reader-text\" role=\"status\" aria-live=\"polite\" data-favorites-status></p>\n\t\t\t</section>\n\t\t</div>\n\t</div>\n</main>\n<?php get_footer(); ?>\n","sha256":"64eef634d94aed391d735ddc15aaed7a5f07f30d432a46b2be0f1b017772c96e"},"template-parts/home/categories.php":{"content":"<?php\n/** Homepage category showcase, using the saved cards and native WooCommerce terms. */\ndefined( 'ABSPATH' ) || exit;\n$category_cards = genosys_site_setting( 'category_cards' );\n$default_cards = genosys_site_defaults()['category_cards'];\n$products_url = genosys_home_card_url( 'products' );\n?>\n<section class=\"genosys-categories\" aria-labelledby=\"genosys-categories-title\">\n\t<div class=\"genosys-categories__intro\">\n\t\t<h2 id=\"genosys-categories-title\"><?php echo esc_html( genosys_site_setting( 'categories_title' ) ); ?> <span><?php echo esc_html( genosys_site_setting( 'categories_highlight' ) ); ?></span></h2>\n\t\t<p><?php echo esc_html( genosys_site_setting( 'categories_description' ) ); ?></p>\n\t\t<a class=\"genosys-categories__button\" href=\"<?php echo esc_url( home_url( '/shop/' ) ); ?>\"><?php echo esc_html( genosys_site_setting( 'categories_button' ) ); ?></a>\n\t\t<a class=\"genosys-categories__brand\" href=\"<?php echo esc_url( genosys_site_url( 'categories_brand_url', home_url( '/brand/' ) ) ); ?>\"><?php echo esc_html( genosys_site_setting( 'categories_brand_text' ) ); ?></a>\n\t</div>\n\t<div class=\"genosys-categories__stage\">\n\t\t<div id=\"genosys-category-row\" class=\"genosys-categories__row latest-products__row\" role=\"region\" aria-label=\"دسته‌بندی محصولات ژنوسیس، فهرست افقی\" tabindex=\"0\">\n\t\t\t<?php foreach ( $category_cards as $index => $card ) : ?>\n\t\t\t\t<?php\n                if ( ! is_array( $card ) ) { continue; }\n\t\t\t\t$url = $products_url;\n                $term_id = absint( $card['term_id'] ?? 0 );\n                if ( $term_id ) {\n                    $term = get_term( $term_id, 'product_cat' );\n                    $term_url = $term && ! is_wp_error( $term ) ? get_term_link( $term ) : null;\n                    if ( is_string( $term_url ) ) { $url = $term_url; }\n                } else {\n\t\t\t\t\tforeach ( ( $card['terms'] ?? array() ) as $term_name ) {\n\t\t\t\t\t\t$term = get_term_by( 'name', $term_name, 'product_cat' );\n\t\t\t\t\t\tif ( ! $term || is_wp_error( $term ) ) { continue; }\n\t\t\t\t\t\t$term_url = get_term_link( $term );\n\t\t\t\t\t\tif ( ! is_wp_error( $term_url ) ) { $url = $term_url; break; }\n\t\t\t\t\t}\n                }\n                $size = isset( $card['size'] ) && 'tall' === $card['size'] ? 'tall' : 'short';\n\t\t\t\t?>\n\t\t\t\t<a class=\"genosys-categories__card genosys-categories__card--<?php echo esc_attr( $size ); ?>\" href=\"<?php echo esc_url( $url ); ?>\">\n\t\t\t\t\t<img src=\"<?php echo esc_url( ! empty( $card['image'] ) ? $card['image'] : ( $default_cards[ $index ]['image'] ?? '' ) ); ?>\" alt=\"\" width=\"536\" height=\"536\" loading=\"lazy\" decoding=\"async\" draggable=\"false\">\n\t\t\t\t\t<span class=\"genosys-categories__card-title\"><?php echo esc_html( $card['title'] ?? '' ); ?></span>\n\t\t\t\t</a>\n\t\t\t<?php endforeach; ?>\n\t\t</div>\n\t\t<?php get_template_part( 'template-parts/home/category-stats' ); ?>\n\t</div>\n</section>\n","sha256":"b0eda9760f40c1b4e8970c3ff804a279e777a87598a4f818272c46de3489f426"},"template-parts/home/category-stats.php":{"content":"<?php\n/** Animated homepage statistics beneath the category cards. */\ndefined( 'ABSPATH' ) || exit;\n\nif ( ! genosys_site_setting( 'stats_visible', 1 ) ) { return; }\n$genosys_stats = genosys_site_setting( 'stats' );\nforeach ( $genosys_stats as &$stat ) {\n    $stat['count'] = max( 0, min( 1000000, (int) ( $stat['count'] ?? 0 ) ) );\n    $stat['display'] = genosys_persian_number( $stat['count'] );\n}\nunset( $stat );\n?>\n<div class=\"genosys-category-stats\" role=\"list\" aria-label=\"آمار ژنوسیس\">\n\t<?php foreach ( $genosys_stats as $stat ) : ?>\n\t\t<div class=\"genosys-category-stats__item\" role=\"listitem\" aria-label=\"<?php echo esc_attr( $stat['display'] . '+ ' . $stat['label'] ); ?>\">\n\t\t\t<svg class=\"genosys-category-stats__ring\" viewBox=\"0 0 340 340\" aria-hidden=\"true\" focusable=\"false\">\n\t\t\t\t<circle class=\"genosys-category-stats__track\" cx=\"170\" cy=\"170\" r=\"148\" />\n\t\t\t\t<circle class=\"genosys-category-stats__progress\" cx=\"170\" cy=\"170\" r=\"148\" pathLength=\"100\" />\n\t\t\t</svg>\n\t\t\t<div class=\"genosys-category-stats__content\" aria-hidden=\"true\">\n\t\t\t\t<span class=\"genosys-category-stats__icon\">\n\t\t\t\t\t<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\" focusable=\"false\">\n\t\t\t\t\t\t<?php if ( 'calendar' === $stat['icon'] ) : ?>\n\t\t\t\t\t\t\t<rect x=\"3.5\" y=\"5.5\" width=\"17\" height=\"15\" rx=\"2\" /><path d=\"M7.5 3v5M16.5 3v5M3.5 10h17\" />\n\t\t\t\t\t\t<?php elseif ( 'people' === $stat['icon'] ) : ?>\n\t\t\t\t\t\t\t<circle cx=\"9\" cy=\"8\" r=\"3\" /><circle cx=\"17\" cy=\"9\" r=\"2.3\" /><path d=\"M3.5 20v-1.2c0-3 2.2-5 5.5-5s5.5 2 5.5 5V20M15 14.8c3.4-.1 5.5 1.8 5.5 4.7V20\" />\n\t\t\t\t\t\t<?php elseif ( 'flask' === $stat['icon'] ) : ?>\n\t\t\t\t\t\t\t<path d=\"M9 3h6M10 3v7l-5.3 8.3A1.8 1.8 0 0 0 6.2 21h11.6a1.8 1.8 0 0 0 1.5-2.7L14 10V3M8 16h8\" />\n\t\t\t\t\t\t<?php else : ?>\n\t\t\t\t\t\t\t<circle cx=\"12\" cy=\"12\" r=\"9\" /><path d=\"M3 12h18M12 3c-2.5 2.4-3.8 5.4-3.8 9s1.3 6.6 3.8 9M12 3c2.5 2.4 3.8 5.4 3.8 9s-1.3 6.6-3.8 9\" />\n\t\t\t\t\t\t<?php endif; ?>\n\t\t\t\t\t</svg>\n\t\t\t\t</span>\n\t\t\t\t<span class=\"genosys-category-stats__value\" dir=\"ltr\"><span class=\"genosys-category-stats__plus\">+</span><span class=\"genosys-category-stats__number\" data-count=\"<?php echo esc_attr( $stat['count'] ); ?>\"><?php echo esc_html( $stat['display'] ); ?></span></span>\n\t\t\t\t<span class=\"genosys-category-stats__label\"><?php echo esc_html( $stat['label'] ); ?></span>\n\t\t\t</div>\n\t\t</div>\n\t<?php endforeach; ?>\n</div>\n","sha256":"9817f80e3d2c96327fd5bc787cf9fbed2927b9ec33add8156d38b6d5f905afac"},"template-parts/home/feature-cards.php":{"content":"<?php\n/** The two established homepage cards with editable images, labels and destinations. */\ndefined( 'ABSPATH' ) || exit;\n$club_url = genosys_site_url( 'club_card_url', home_url( '/fans-club/' ) );\n$products_url = genosys_site_url( 'products_card_url', home_url( '/shop/' ) );\n?>\n    <section class=\"home-feature-section\" aria-label=\"باشگاه مشتریان و محصولات ژنوسیس\">\n        <div class=\"home-feature-grid\">\n            <article class=\"home-feature-card home-feature-club\" aria-labelledby=\"home-club-title\">\n                <img class=\"home-feature-image\" src=\"<?php echo esc_url( genosys_site_url( 'club_card_image', get_theme_file_uri( '/assets/images/customer-club-1.3.1.webp' ) ) ); ?>\" alt=\"\" width=\"1672\" height=\"941\" loading=\"lazy\" decoding=\"async\">\n                <div class=\"home-feature-content\">\n                    <h2 id=\"home-club-title\" class=\"home-feature-title\"><a class=\"home-feature-title-link\" href=\"<?php echo esc_url( $club_url ); ?>\"><?php echo esc_html( genosys_site_setting( 'club_card_title' ) ); ?></a></h2>\n                    <a class=\"home-feature-button\" href=\"<?php echo esc_url( $club_url ); ?>\"><?php echo esc_html( genosys_site_setting( 'club_card_button' ) ); ?></a>\n                </div>\n            </article>\n            <article class=\"home-feature-card home-feature-products\" aria-labelledby=\"home-products-title\">\n                <img class=\"home-feature-image\" src=\"<?php echo esc_url( genosys_site_url( 'products_card_image', get_theme_file_uri( '/assets/images/products-card-1.3.2.webp' ) ) ); ?>\" alt=\"\" width=\"1974\" height=\"797\" loading=\"lazy\" decoding=\"async\">\n                <div class=\"home-feature-content\">\n                    <h2 id=\"home-products-title\" class=\"home-feature-title\"><a class=\"home-feature-title-link\" href=\"<?php echo esc_url( $products_url ); ?>\"><?php echo esc_html( genosys_site_setting( 'products_card_title' ) ); ?></a></h2>\n                    <a class=\"home-feature-button\" href=\"<?php echo esc_url( $products_url ); ?>\"><?php echo esc_html( genosys_site_setting( 'products_card_button' ) ); ?></a>\n                </div>\n            </article>\n        </div>\n    </section>\n","sha256":"d8578a28cbdf2977324a05068076c897810cff8ec9415deb7986b2cb9510487b"},"template-parts/home/featured-products.php":{"content":"<?php\n/** Featured homepage tabs backed by real WooCommerce product categories. */\ndefined( 'ABSPATH' ) || exit;\nif ( ! function_exists( 'wc_get_products' ) || ! taxonomy_exists( 'product_cat' ) ) { return; }\n\n$featured_tabs = genosys_site_setting( 'featured_tabs' );\nif ( ! $featured_tabs ) { return; }\n$catalog_terms = get_terms( array( 'taxonomy' => 'product_cat', 'hide_empty' => false ) );\nif ( is_wp_error( $catalog_terms ) ) { $catalog_terms = array(); }\n$normalize_name = static function ( $name ) {\n    $name = str_replace( array( 'ي', 'ك' ), array( 'ی', 'ک' ), (string) $name );\n    return preg_replace( '/[\\s\\x{200C}\\x{200D}\\x{064B}-\\x{065F}\\x{0670}ـ-]+/u', '', $name );\n};\n\nforeach ( $featured_tabs as &$tab ) {\n    $tab['term'] = null;\n    $tab['url'] = '';\n    $tab['products'] = array();\n    $selected_id = absint( $tab['term_id'] ?? 0 );\n    if ( $selected_id ) {\n        foreach ( $catalog_terms as $term ) { if ( $selected_id === (int) $term->term_id ) { $tab['term'] = $term; break; } }\n    }\n    foreach ( $selected_id ? array() : ( $tab['names'] ?? array() ) as $name ) {\n        foreach ( $catalog_terms as $term ) {\n            if ( $normalize_name( $term->name ) === $normalize_name( $name ) ) {\n                $tab['term'] = $term;\n                break 2;\n            }\n        }\n    }\n    if ( ! $tab['term'] ) { continue; }\n\n    $term_url = get_term_link( $tab['term'] );\n    if ( ! is_wp_error( $term_url ) ) { $tab['url'] = $term_url; }\n    $query = array(\n        'status' => 'publish',\n        'limit' => max( 1, min( 24, (int) genosys_site_setting( 'featured_count', 6 ) ) ),\n        'orderby' => 'date',\n        'order' => 'DESC',\n        'return' => 'objects',\n        'visibility' => 'catalog',\n        'category' => array( $tab['term']->slug ),\n    );\n    if ( 'yes' === get_option( 'woocommerce_hide_out_of_stock_items' ) ) {\n        $query['stock_status'] = array( 'instock', 'onbackorder' );\n    }\n    $tab['products'] = wc_get_products( $query );\n}\nunset( $tab );\n?>\n<section class=\"genosys-featured-products\" aria-labelledby=\"genosys-featured-products-title\" data-featured-products>\n    <div class=\"genosys-featured-products__layout\">\n        <div class=\"genosys-featured-products__sidebar\">\n            <span class=\"genosys-featured-products__eyebrow\"><?php echo esc_html( genosys_site_setting( 'featured_eyebrow' ) ); ?></span>\n            <h2 id=\"genosys-featured-products-title\" class=\"genosys-featured-products__heading\"><?php echo esc_html( genosys_site_setting( 'featured_title' ) ); ?> <em><?php echo esc_html( genosys_site_setting( 'featured_highlight' ) ); ?></em> <?php echo esc_html( genosys_site_setting( 'featured_suffix' ) ); ?></h2>\n            <p class=\"genosys-featured-products__description\"><?php echo esc_html( genosys_site_setting( 'featured_description' ) ); ?></p>\n            <div class=\"genosys-featured-products__tabs\" role=\"tablist\" aria-label=\"دسته‌بندی محصولات منتخب\" aria-orientation=\"vertical\">\n                <?php foreach ( $featured_tabs as $index => $tab ) : ?>\n                    <button class=\"genosys-featured-products__tab<?php echo 0 === $index ? ' is-active' : ''; ?>\" type=\"button\" role=\"tab\" id=\"genosys-featured-tab-<?php echo esc_attr( $index ); ?>\" aria-controls=\"genosys-featured-panel-<?php echo esc_attr( $index ); ?>\" aria-selected=\"<?php echo 0 === $index ? 'true' : 'false'; ?>\" tabindex=\"<?php echo 0 === $index ? '0' : '-1'; ?>\" data-featured-tab>\n                        <span><?php echo esc_html( $tab['label'] ); ?></span>\n                        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"m15 5-7 7 7 7\"/></svg>\n                    </button>\n                <?php endforeach; ?>\n            </div>\n            <a class=\"genosys-featured-products__categories-link\" href=\"<?php echo esc_url( home_url( '/shop/' ) ); ?>\">\n                <span><?php echo esc_html( genosys_site_setting( 'featured_link_text' ) ); ?></span>\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M20 12H4m6-6-6 6 6 6\"/></svg>\n            </a>\n        </div>\n\n        <div class=\"genosys-featured-products__panels\">\n            <?php foreach ( $featured_tabs as $index => $tab ) : ?>\n                <div class=\"genosys-featured-products__panel\" id=\"genosys-featured-panel-<?php echo esc_attr( $index ); ?>\" role=\"tabpanel\" aria-labelledby=\"genosys-featured-tab-<?php echo esc_attr( $index ); ?>\" tabindex=\"0\" data-featured-panel<?php echo 0 === $index ? '' : ' hidden'; ?>>\n                    <?php if ( $tab['products'] ) : ?>\n                        <div class=\"genosys-featured-products__grid\" data-featured-rail tabindex=\"0\" role=\"region\" aria-label=\"<?php echo esc_attr( 'محصولات ' . $tab['label'] ); ?>\">\n                            <?php foreach ( $tab['products'] as $product ) : ?>\n                                <?php get_template_part( 'template-parts/product/card', null, array( 'product' => $product ) ); ?>\n                            <?php endforeach; ?>\n                        </div>\n                    <?php else : ?>\n                        <p class=\"genosys-featured-products__empty\"><?php echo esc_html( $tab['term'] ? 'هنوز محصولی در این دسته‌بندی ثبت نشده است.' : 'این دسته‌بندی هنوز در فروشگاه ثبت نشده است.' ); ?></p>\n                    <?php endif; ?>\n                    <?php if ( $tab['url'] ) : ?>\n                        <a class=\"genosys-featured-products__view-all\" href=\"<?php echo esc_url( $tab['url'] ); ?>\">\n                            <span>مشاهده همه</span>\n                            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M20 12H4m6-6-6 6 6 6\"/></svg>\n                        </a>\n                    <?php endif; ?>\n                </div>\n            <?php endforeach; ?>\n        </div>\n    </div>\n</section>\n","sha256":"c8d2b1768d6b238b8a3dadf91386bb1be72c27eb89c460aee27285b080df053d"},"template-parts/home/hero-banner.php":{"content":"<?php\n/** Editable homepage slider; the default photographs and markup are unchanged. */\ndefined( 'ABSPATH' ) || exit;\n$slides = array_values( array_filter( genosys_site_setting( 'slides' ), static function ( $slide ) { return is_array( $slide ) && ! empty( $slide['image'] ); } ) );\nif ( ! $slides ) { return; }\n$slide_total = genosys_persian_number( count( $slides ) );\n?>\n    <section class=\"hero-banner\" aria-label=\"تصاویر محصولات ژنوسیس\" aria-roledescription=\"اسلایدر\" data-interval=\"<?php echo esc_attr( max( 2000, min( 20000, (int) genosys_site_setting( 'slider_interval', 6000 ) ) ) ); ?>\">\n        <div id=\"banner-slides\" class=\"hero-slides\">\n            <?php foreach ( $slides as $index => $slide ) : ?>\n                <?php $slide_class = isset( $slide['class'] ) && in_array( $slide['class'], array( 'slide-skincare', 'slide-eco', 'slide-hair', 'slide-ampoules' ), true ) ? $slide['class'] : ''; ?>\n                <figure class=\"hero-slide <?php echo esc_attr( $slide_class ); ?><?php echo 0 === $index ? ' is-active' : ''; ?>\" role=\"group\" aria-roledescription=\"اسلاید\" aria-label=\"<?php echo esc_attr( genosys_persian_number( $index + 1 ) . ' از ' . $slide_total ); ?>\" aria-hidden=\"<?php echo 0 === $index ? 'false' : 'true'; ?>\">\n                    <img src=\"<?php echo esc_url( $slide['image'] ); ?>\" alt=\"<?php echo esc_attr( $slide['alt'] ?? '' ); ?>\" width=\"1672\" height=\"941\" loading=\"eager\" decoding=\"async\" fetchpriority=\"<?php echo 0 === $index ? 'high' : 'low'; ?>\" draggable=\"false\">\n                    <?php if ( ! empty( $slide['link'] ) ) : ?><a class=\"genosys-slide-link\" href=\"<?php echo esc_url( $slide['link'] ); ?>\" aria-label=\"<?php echo esc_attr( ! empty( $slide['title'] ) ? $slide['title'] : ( ! empty( $slide['alt'] ) ? $slide['alt'] : 'مشاهده محصولات' ) ); ?>\"></a><?php endif; ?>\n                    <?php if ( ! empty( $slide['title'] ) ) : ?><figcaption class=\"genosys-slide-caption\"><?php echo esc_html( $slide['title'] ); ?></figcaption><?php endif; ?>\n                </figure>\n            <?php endforeach; ?>\n        </div>\n        <div class=\"banner-controls\">\n            <button class=\"banner-arrow banner-previous\" type=\"button\" aria-label=\"اسلاید قبلی\" aria-controls=\"banner-slides\">\n                <svg viewBox=\"0 0 32 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\" focusable=\"false\"><path d=\"m8 6 18 18L8 42\"/></svg>\n            </button>\n            <button class=\"banner-arrow banner-next\" type=\"button\" aria-label=\"اسلاید بعدی\" aria-controls=\"banner-slides\">\n                <svg viewBox=\"0 0 32 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M24 6 6 24l18 18\"/></svg>\n            </button>\n            <div class=\"banner-pagination\" role=\"group\" aria-label=\"انتخاب اسلاید\">\n                <?php foreach ( $slides as $index => $slide ) : ?>\n                    <button class=\"banner-dot\" type=\"button\" data-slide=\"<?php echo esc_attr( $index ); ?>\" aria-label=\"<?php echo esc_attr( 'نمایش اسلاید ' . genosys_persian_number( $index + 1 ) ); ?>\" aria-pressed=\"<?php echo 0 === $index ? 'true' : 'false'; ?>\" aria-controls=\"banner-slides\"><span aria-hidden=\"true\"></span></button>\n                <?php endforeach; ?>\n                <button class=\"banner-playback\" type=\"button\" aria-label=\"توقف پخش خودکار\" aria-controls=\"banner-slides\">\n                    <svg class=\"banner-pause-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M8 5v14M16 5v14\"/></svg>\n                    <svg class=\"banner-play-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" aria-hidden=\"true\" focusable=\"false\"><path d=\"m8 5 11 7-11 7Z\"/></svg>\n                </button>\n            </div>\n        </div>\n        <p class=\"screen-reader-text banner-status\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\"></p>\n    </section>","sha256":"cc300d98b8405ff6cb0fb929c6b62dd3702fa31826b3e7a67d98617fda079557"},"template-parts/home/latest-products.php":{"content":"<?php\n/** Latest catalog products in a native RTL scroll row. */\nif ( ! defined( 'ABSPATH' ) || ! function_exists( 'wc_get_products' ) ) { return; }\n$latest_products = genosys_latest_products();\n?>\n<section class=\"latest-products\" aria-labelledby=\"latest-products-title\">\n    <h2 id=\"latest-products-title\" class=\"latest-products__title\"><?php echo esc_html( genosys_site_setting( 'latest_title' ) ); ?></h2>\n    <?php if ( $latest_products ) : ?>\n        <div class=\"latest-products__row\" role=\"region\" aria-label=\"جدیدترین محصولات، فهرست افقی\" tabindex=\"0\">\n            <?php foreach ( $latest_products as $latest_product ) : ?>\n                <?php get_template_part( 'template-parts/product/card', null, array( 'product' => $latest_product ) ); ?>\n            <?php endforeach; ?>\n            <?php if ( count( $latest_products ) >= max( 1, min( 24, (int) genosys_site_setting( 'latest_count', 8 ) ) ) ) : ?>\n                <a class=\"products-view-all\" href=\"<?php echo esc_url( home_url( '/shop/' ) ); ?>\">\n                    <span><?php echo esc_html( genosys_site_setting( 'latest_all_text', 'مشاهده همه' ) ); ?></span>\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M20 12H4m6-6-6 6 6 6\"/></svg>\n                </a>\n            <?php endif; ?>\n        </div>\n        <p class=\"screen-reader-text\" role=\"status\" aria-live=\"polite\" data-favorites-status></p>\n    <?php else : ?>\n        <p class=\"latest-products__empty\">هنوز محصولی برای نمایش موجود نیست.</p>\n    <?php endif; ?>\n</section>\n","sha256":"ca9cb67ff37f6a80af46328a12dd152232982de65e7a6ab6943ea424db502102"},"template-parts/product/card.php":{"content":"<?php\n/** Reusable WooCommerce card. Pass a WC_Product in the template's product argument. */\nif ( ! defined( 'ABSPATH' ) ) { exit; }\n$card_product = isset( $args['product'] ) ? $args['product'] : null;\nif ( ! $card_product instanceof WC_Product ) { return; }\n$name = $card_product->get_name();\n$permalink = $card_product->get_permalink();\n$category_names = array();\n$categories = get_the_terms( $card_product->get_id(), 'product_cat' );\nif ( $categories && ! is_wp_error( $categories ) ) {\n    foreach ( $categories as $category ) { $category_names[] = $category->name; }\n}\n$category_text = implode( '، ', $category_names );\n$price_html = genosys_product_price_html( $card_product );\n$discount = genosys_product_discount( $card_product );\n?>\n<article class=\"product-card<?php echo $card_product->get_image_id() ? '' : ' product-card--placeholder'; ?>\" data-product-id=\"<?php echo esc_attr( $card_product->get_id() ); ?>\">\n    <a class=\"product-card__photo\" href=\"<?php echo esc_url( $permalink ); ?>\" aria-label=\"<?php echo esc_attr( $name ); ?>\" tabindex=\"-1\" aria-hidden=\"true\">\n        <?php echo wp_kses_post( $card_product->get_image( 'large', array( 'class' => 'product-card__image', 'alt' => '', 'loading' => 'lazy', 'decoding' => 'async', 'draggable' => 'false' ), true ) ); ?>\n    </a>\n    <?php if ( ! $card_product->is_in_stock() ) : ?>\n        <span class=\"product-card__badge product-card__badge--stock\">ناموجود</span>\n    <?php elseif ( $card_product->is_on_sale() ) : ?>\n        <span class=\"product-card__badge\"><?php echo esc_html( $discount ? genosys_persian_number( $discount ) . '٪ تخفیف' : 'تخفیف' ); ?></span>\n    <?php endif; ?>\n    <button class=\"product-favorite\" type=\"button\" data-favorite-id=\"<?php echo esc_attr( $card_product->get_id() ); ?>\" aria-pressed=\"false\" aria-label=\"<?php echo esc_attr( 'افزودن ' . $name . ' به علاقه‌مندی‌ها' ); ?>\" data-product-name=\"<?php echo esc_attr( $name ); ?>\" hidden>\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z\"/></svg>\n    </button>\n    <div class=\"product-card__info\">\n        <h3 class=\"product-card__name\"><a href=\"<?php echo esc_url( $permalink ); ?>\" title=\"<?php echo esc_attr( $name ); ?>\"><?php echo esc_html( $name ); ?></a></h3>\n        <?php if ( $category_text ) : ?><p class=\"product-card__category\" title=\"<?php echo esc_attr( $category_text ); ?>\"><?php echo esc_html( $category_text ); ?></p><?php endif; ?>\n        <div class=\"product-card__price<?php echo ! $card_product->is_in_stock() ? ' product-card__price--unavailable' : ( $price_html ? '' : ' product-card__price--empty' ); ?>\">\n            <span class=\"product-card__price-value\"><?php echo ! $card_product->is_in_stock() ? esc_html( 'تماس بگیرید' ) : ( $price_html ? wp_kses_post( $price_html ) : esc_html( 'اطلاعات قیمت موجود نیست' ) ); ?></span>\n        </div>\n    </div>\n</article>\n","sha256":"50cb2973aa7bbf4b2ceb234ce9da5c2bbaec6b191b59262ae94d495509091e11"},"woocommerce/checkout/form-checkout.php":{"content":"<?php\n/** Classic WooCommerce checkout form with the Genosys layout. */\ndefined( 'ABSPATH' ) || exit;\n\n// The coupon control is integrated into the order summary below.\nremove_action( 'woocommerce_before_checkout_form', 'woocommerce_checkout_coupon_form', 10 );\ndo_action( 'woocommerce_before_checkout_form', $checkout );\n\nif ( ! $checkout->is_registration_enabled() && $checkout->is_registration_required() && ! is_user_logged_in() ) {\n\techo esc_html( apply_filters( 'woocommerce_checkout_must_be_logged_in_message', __( 'You must be logged in to checkout.', 'woocommerce' ) ) );\n\treturn;\n}\n\n?>\n<ol class=\"gco-steps\" aria-label=\"مراحل ثبت سفارش\">\n\t<li class=\"gco-step gco-step--complete\"><span class=\"gco-step__number\" aria-hidden=\"true\">✓</span><span>سبد خرید</span></li>\n\t<li class=\"gco-steps__line gco-steps__line--complete\" aria-hidden=\"true\"></li>\n\t<li class=\"gco-step gco-step--current\" aria-current=\"step\"><span class=\"gco-step__number\" aria-hidden=\"true\">۲</span><span>اطلاعات و ارسال</span></li>\n\t<li class=\"gco-steps__line\" aria-hidden=\"true\"></li>\n\t<li class=\"gco-step\"><span class=\"gco-step__number\" aria-hidden=\"true\">۳</span><span>تکمیل سفارش</span></li>\n</ol>\n\n<form name=\"checkout\" method=\"post\" class=\"checkout woocommerce-checkout gco-layout\" action=\"<?php echo esc_url( wc_get_checkout_url() ); ?>\" enctype=\"multipart/form-data\" aria-label=\"تسویه‌حساب\">\n\t<input type=\"hidden\" name=\"genosys_checkout_layout\" value=\"1\">\n\t<div class=\"gco-main\" id=\"customer_details\">\n\t\t<?php do_action( 'woocommerce_checkout_before_customer_details' ); ?>\n\t\t<section class=\"gco-panel gco-contact\" aria-labelledby=\"gco-contact-heading\">\n\t\t\t<h2 class=\"gco-panel__heading\" id=\"gco-contact-heading\"><span class=\"gco-panel__number\">۱</span>اطلاعات تماس</h2>\n\t\t\t<?php do_action( 'woocommerce_before_checkout_billing_form', $checkout ); ?>\n\t\t\t<div class=\"gco-fields\">\n\t\t\t\t<?php genosys_checkout_render_field( $checkout, 'billing_first_name', array( 'label' => 'نام', 'class' => array( 'form-row', 'gco-field' ) ) ); ?>\n\t\t\t\t<?php genosys_checkout_render_field( $checkout, 'billing_last_name', array( 'label' => 'نام خانوادگی', 'class' => array( 'form-row', 'gco-field' ) ) ); ?>\n\t\t\t\t<?php genosys_checkout_render_field( $checkout, 'billing_phone', array( 'label' => 'شماره موبایل', 'class' => array( 'form-row', 'gco-field' ), 'placeholder' => '09123456789' ) ); ?>\n\t\t\t\t<?php genosys_checkout_render_field( $checkout, 'billing_email', array( 'label' => 'ایمیل', 'class' => array( 'form-row', 'gco-field' ), 'placeholder' => 'name@example.com' ) ); ?>\n\t\t\t</div>\n\t\t\t<?php if ( ! is_user_logged_in() && $checkout->is_registration_enabled() ) : ?>\n\t\t\t\t<div class=\"gco-account-fields woocommerce-account-fields\">\n\t\t\t\t\t<?php if ( ! $checkout->is_registration_required() ) : ?>\n\t\t\t\t\t\t<p class=\"form-row create-account\"><label class=\"woocommerce-form__label woocommerce-form__label-for-checkbox checkbox\"><input class=\"woocommerce-form__input woocommerce-form__input-checkbox input-checkbox\" id=\"createaccount\" <?php checked( true === $checkout->get_value( 'createaccount' ) || true === apply_filters( 'woocommerce_create_account_default_checked', false ) ); ?> type=\"checkbox\" name=\"createaccount\" value=\"1\"><span>ساخت حساب کاربری برای این سفارش</span></label></p>\n\t\t\t\t\t<?php endif; ?>\n\t\t\t\t\t<?php do_action( 'woocommerce_before_checkout_registration_form', $checkout ); ?>\n\t\t\t\t\t<?php if ( $checkout->get_checkout_fields( 'account' ) ) : ?><div class=\"create-account gco-account-fields__details\"><?php genosys_checkout_render_extra_fields( $checkout, 'account' ); ?></div><?php endif; ?>\n\t\t\t\t\t<?php do_action( 'woocommerce_after_checkout_registration_form', $checkout ); ?>\n\t\t\t\t</div>\n\t\t\t<?php endif; ?>\n\t\t</section>\n\n\t\t<section class=\"gco-panel gco-address\" aria-labelledby=\"gco-address-heading\">\n\t\t\t<h2 class=\"gco-panel__heading\" id=\"gco-address-heading\"><span class=\"gco-panel__number\">۲</span>آدرس تحویل</h2>\n\t\t\t<input type=\"hidden\" name=\"billing_country\" id=\"billing_country\" value=\"IR\">\n\t\t\t<div class=\"gco-fields gco-fields--address\">\n\t\t\t\t<?php genosys_checkout_render_field( $checkout, 'billing_state', array( 'label' => 'استان', 'country' => 'IR', 'class' => array( 'form-row', 'gco-field' ) ) ); ?>\n\t\t\t\t<?php genosys_checkout_render_field( $checkout, 'billing_city', array( 'label' => 'شهر', 'class' => array( 'form-row', 'gco-field' ) ) ); ?>\n\t\t\t\t<?php genosys_checkout_render_field( $checkout, 'billing_address_1', array( 'label' => 'آدرس کامل', 'type' => 'textarea', 'placeholder' => 'خیابان، کوچه، پلاک، واحد', 'class' => array( 'form-row', 'gco-field', 'gco-field--wide' ) ) ); ?>\n\t\t\t\t<?php genosys_checkout_render_field( $checkout, 'billing_postcode', array( 'label' => 'کد پستی', 'placeholder' => '۱۰ رقم', 'class' => array( 'form-row', 'gco-field', 'gco-field--postal' ) ) ); ?>\n\t\t\t</div>\n\t\t\t<?php genosys_checkout_render_extra_fields( $checkout, 'billing', array( 'billing_first_name', 'billing_last_name', 'billing_phone', 'billing_email', 'billing_country', 'billing_state', 'billing_city', 'billing_address_1', 'billing_postcode', 'billing_company', 'billing_address_2' ) ); ?>\n\t\t\t<?php foreach ( array( 'billing_company', 'billing_address_2' ) as $preserved_key ) : ?>\n\t\t\t\t<?php if ( $checkout->get_value( $preserved_key ) ) : ?><input type=\"hidden\" name=\"<?php echo esc_attr( $preserved_key ); ?>\" value=\"<?php echo esc_attr( $checkout->get_value( $preserved_key ) ); ?>\"><?php endif; ?>\n\t\t\t<?php endforeach; ?>\n\t\t\t<?php do_action( 'woocommerce_after_checkout_billing_form', $checkout ); ?>\n\t\t</section>\n\t\t<?php do_action( 'woocommerce_checkout_after_customer_details' ); ?>\n\n\t\t<section class=\"gco-panel gco-shipping\" aria-labelledby=\"gco-shipping-heading\">\n\t\t\t<h2 class=\"gco-panel__heading\" id=\"gco-shipping-heading\"><span class=\"gco-panel__number\">۳</span>روش ارسال</h2>\n\t\t\t<div class=\"gco-shipping-options\"><?php genosys_checkout_render_shipping_methods(); ?></div>\n\t\t\t<div class=\"gco-order-notes\">\n\t\t\t\t<?php genosys_checkout_render_field( $checkout, 'order_comments', array( 'label' => 'توضیحات سفارش', 'type' => 'textarea', 'placeholder' => 'مثلاً: ساعت تحویل، یادداشت برای ارسال...', 'class' => array( 'form-row', 'gco-field', 'gco-field--wide' ) ) ); ?>\n\t\t\t\t<?php genosys_checkout_render_extra_fields( $checkout, 'order', array( 'order_comments' ) ); ?>\n\t\t\t</div>\n\t\t</section>\n\t\t<?php // Keep Woo's payment field in the form for checkout AJAX and order processing. ?>\n\t\t<?php woocommerce_checkout_payment(); ?>\n\t</div>\n\n\t<?php do_action( 'woocommerce_checkout_before_order_review' ); ?>\n\t<aside id=\"order_review\" class=\"gco-summary woocommerce-checkout-review-order\" aria-labelledby=\"gco-summary-heading\">\n\t\t<div class=\"gco-summary-inner woocommerce-checkout-review-order-table\"><?php genosys_checkout_render_summary(); ?></div>\n\t\t<div class=\"gco-summary__terms\"><?php wc_get_template( 'checkout/terms.php' ); ?></div>\n\t\t<?php do_action( 'woocommerce_review_order_before_submit' ); ?>\n\t\t<?php $order_button_text = apply_filters( 'woocommerce_order_button_text', 'ثبت سفارش' ); ?>\n\t\t<?php echo apply_filters( 'woocommerce_order_button_html', '<button type=\"submit\" class=\"gco-submit button alt\" name=\"woocommerce_checkout_place_order\" id=\"place_order\" value=\"' . esc_attr( $order_button_text ) . '\" data-value=\"' . esc_attr( $order_button_text ) . '\">' . esc_html( $order_button_text ) . '</button>' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- WooCommerce gateway integrations filter this button. ?>\n\t\t<?php do_action( 'woocommerce_review_order_after_submit' ); ?>\n\t\t<?php wp_nonce_field( 'woocommerce-process_checkout', 'woocommerce-process-checkout-nonce' ); ?>\n\t\t<a class=\"gco-summary__back\" href=\"<?php echo esc_url( wc_get_cart_url() ); ?>\">بازگشت به سبد خرید</a>\n\t</aside>\n\t<?php do_action( 'woocommerce_checkout_after_order_review' ); ?>\n</form>\n\n<?php do_action( 'woocommerce_after_checkout_form', $checkout ); ?>\n","sha256":"60a52898430577280d546f37edbd1581549b9a56c06ac47e8c5400e3eec4e478"},"woocommerce/checkout/payment.php":{"content":"<?php\n/** Keep WooCommerce's payment selection in the checkout form without a payment panel. */\ndefined( 'ABSPATH' ) || exit;\n\nif ( ! wp_doing_ajax() ) {\n\tdo_action( 'woocommerce_review_order_before_payment' );\n}\n\n$needs_payment = WC()->cart && WC()->cart->needs_payment();\n$card_gateway = $needs_payment && isset( $available_gateways['genosys_card_to_card'] );\n?>\n<div id=\"payment\" class=\"woocommerce-checkout-payment gco-payment-processing<?php echo $needs_payment && ! $card_gateway ? ' gco-payment-processing--unavailable' : ''; ?>\">\n\t<?php if ( $card_gateway ) : ?>\n\t\t<ul class=\"wc_payment_methods payment_methods methods\">\n\t\t\t<li class=\"wc_payment_method payment_method_genosys_card_to_card\">\n\t\t\t\t<input id=\"payment_method_genosys_card_to_card\" type=\"radio\" class=\"input-radio\" name=\"payment_method\" value=\"genosys_card_to_card\" checked=\"checked\" aria-hidden=\"true\" tabindex=\"-1\">\n\t\t\t</li>\n\t\t</ul>\n\t<?php elseif ( $needs_payment ) : ?>\n\t\t<p class=\"woocommerce-error gco-payment-unavailable\" role=\"alert\">پرداخت کارت به کارت هنوز برای این فروشگاه تنظیم نشده است. لطفاً با پشتیبانی تماس بگیرید.</p>\n\t<?php endif; ?>\n</div>\n<?php\nif ( ! wp_doing_ajax() ) {\n\tdo_action( 'woocommerce_review_order_after_payment' );\n}\n","sha256":"b879248629cc09c1fd72e39c266b2ea454c2acfa7e25ed2230d72ac490c1f4df"},"woocommerce/checkout/receipt-uploader.php":{"content":"<?php\n/**\n * Order-linked receipt picker. Uploads are saved separately from payment processing.\n *\n * @package Genosys\n */\n\ndefined('ABSPATH') || exit;\n$receipt_order = isset($args['receipt_order']) ? $args['receipt_order'] : null;\n$receipt_config = function_exists('genosys_receipt_customer_context') && $receipt_order\n    ? genosys_receipt_customer_context($receipt_order) : null;\n?>\n<div class=\"gco-receipt-upload\" data-gco-receipt-upload>\n    <script type=\"application/json\" data-gco-receipt-config><?php echo wp_json_encode($receipt_config, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT); ?></script>\n    <p class=\"gco-receipt-upload__label\" id=\"gco-receipt-label\">\n        <?php esc_html_e('بارگذاری فیش واریزی', 'genosys'); ?>\n        <span class=\"gco-receipt-upload__required\" aria-hidden=\"true\">*</span>\n    </p>\n    <input type=\"file\" id=\"gco-receipt-file\" data-gco-receipt-input accept=\".jpg,.jpeg,.png,.webp,.pdf,image/jpeg,image/png,image/webp,application/pdf\" tabindex=\"-1\" hidden>\n    <div class=\"gco-receipt-box\" data-gco-receipt-box data-state=\"idle\" role=\"button\" tabindex=\"0\" aria-labelledby=\"gco-receipt-label\" aria-describedby=\"gco-receipt-hint gco-receipt-error\">\n        <div class=\"gco-receipt-idle\" data-gco-receipt-idle>\n            <span class=\"gco-receipt-idle__icon\" data-gco-receipt-icon aria-hidden=\"true\">\n                <svg viewBox=\"0 0 40 40\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M20 27V7m0 0L11.5 15.5M20 7l8.5 8.5M7 24v9a2 2 0 0 0 2 2h22a2 2 0 0 0 2-2v-9\" stroke=\"currentColor\" stroke-width=\"3.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n            </span>\n            <p class=\"gco-receipt-idle__title\"><?php esc_html_e('تصویر فیش واریزی را اینجا رها کنید', 'genosys'); ?></p>\n            <p class=\"gco-receipt-idle__hint\"><?php esc_html_e('یا برای انتخاب فایل کلیک کنید', 'genosys'); ?></p>\n            <span class=\"gco-receipt-idle__formats\" id=\"gco-receipt-hint\"><bdi>JPG · PNG · WEBP · PDF</bdi><span aria-hidden=\"true\">—</span><?php esc_html_e('حداکثر ۵ مگابایت', 'genosys'); ?></span>\n        </div>\n        <div class=\"gco-receipt-busy\" data-gco-receipt-busy aria-hidden=\"true\" hidden>\n            <div class=\"gco-receipt-envelope\" data-gco-envelope>\n                <div class=\"gco-receipt-envelope__back\" data-gco-envelope-back></div>\n                <div class=\"gco-receipt-envelope__paper-track\">\n                    <div class=\"gco-receipt-envelope__paper\" data-gco-envelope-paper>\n                        <div class=\"gco-receipt-envelope__preview\" data-gco-envelope-preview></div>\n                    </div>\n                </div>\n                <svg class=\"gco-receipt-envelope__front\" data-gco-envelope-front viewBox=\"0 0 288 200\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\">\n                    <defs><linearGradient id=\"gco-receipt-pocket-gradient\" x1=\"100\" y1=\"48\" x2=\"177\" y2=\"220\" gradientUnits=\"userSpaceOnUse\"><stop stop-color=\"#d84460\"/><stop offset=\"1\" stop-color=\"#a0082c\"/></linearGradient></defs>\n                    <path d=\"M0 50L135 122Q144 128 153 122L288 50V183Q288 200 271 200H17Q0 200 0 183V50Z\" fill=\"url(#gco-receipt-pocket-gradient)\"/>\n                    <path d=\"M0 50L135 122Q144 128 153 122L288 50\" stroke=\"#ef8c9d\" stroke-width=\"2\"/>\n                </svg>\n                <svg class=\"gco-receipt-envelope__flap\" data-gco-envelope-flap viewBox=\"0 0 288 124\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\">\n                    <defs><linearGradient id=\"gco-receipt-flap-gradient\" x1=\"144\" y1=\"0\" x2=\"144\" y2=\"124\" gradientUnits=\"userSpaceOnUse\"><stop stop-color=\"#c50932\"/><stop offset=\"1\" stop-color=\"#df4561\"/></linearGradient></defs>\n                    <path d=\"M14 0H274Q288 0 277 12L152 119Q144 125 136 119L11 12Q0 0 14 0Z\" fill=\"url(#gco-receipt-flap-gradient)\"/>\n                </svg>\n                <div class=\"gco-receipt-envelope__seal\" data-gco-envelope-seal>\n                    <span class=\"gco-receipt-envelope__ripple\" data-gco-envelope-ripple></span>\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\"><path d=\"m6.5 12 3.5 3.5 7.5-7.5\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n                </div>\n            </div>\n        </div>\n        <div class=\"gco-receipt-result\" data-gco-receipt-result aria-hidden=\"true\" hidden>\n            <div class=\"gco-receipt-result__thumb\" data-gco-receipt-thumb aria-hidden=\"true\">\n                <svg class=\"gco-receipt-fallback\" viewBox=\"0 0 32 32\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M9 3h10l6 6v20l-4-2-5 2-5-2-4 2V5a2 2 0 0 1 2-2Z\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linejoin=\"round\"/><path d=\"M19 3v7h6M11 15h10M11 20h7\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n            </div>\n            <div class=\"gco-receipt-result__info\">\n                <span class=\"gco-receipt-result__success\">\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"12\" fill=\"currentColor\"/><path d=\"m6.8 12 3.5 3.5 6.9-7\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n                    <?php esc_html_e('فیش با موفقیت بارگذاری شد', 'genosys'); ?>\n                </span>\n                <p class=\"gco-receipt-result__name\" data-gco-receipt-name dir=\"auto\"></p>\n                <p class=\"gco-receipt-result__meta\" data-gco-receipt-meta></p>\n            </div>\n            <div class=\"gco-receipt-result__actions\">\n                <button type=\"button\" class=\"gco-receipt-result__button\" data-gco-receipt-change>\n                    <svg viewBox=\"0 0 20 20\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\"><path d=\"M15.5 7a6 6 0 1 0 .2 5M15.5 3.5V7h-3.6\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n                    <?php esc_html_e('تغییر فایل', 'genosys'); ?>\n                </button>\n                <button type=\"button\" class=\"gco-receipt-result__button\" data-gco-receipt-remove>\n                    <svg viewBox=\"0 0 20 20\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" aria-hidden=\"true\"><path d=\"M4 5.5h12M7.5 5.5V3.8h5v1.7M6 5.5l.7 11h6.6l.7-11M8.3 8.5v5M11.7 8.5v5\" stroke=\"currentColor\" stroke-width=\"1.45\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n                    <?php esc_html_e('حذف', 'genosys'); ?>\n                </button>\n            </div>\n        </div>\n    </div>\n    <p class=\"gco-receipt-upload__error\" id=\"gco-receipt-error\" data-gco-receipt-error role=\"alert\" hidden></p>\n    <span class=\"gco-receipt-upload__status\" data-gco-receipt-status role=\"status\" aria-live=\"polite\"></span>\n</div>\n","sha256":"a579a889815e16d364d313fd9fba78469f787ba584c829ae412c8845865df1bc"},"woocommerce/content-single-product.php":{"content":"<?php\n/**\n * Single product layout. WooCommerce owns the current product, gallery, cart form,\n * variation controls, descriptions and reviews through its normal hooks.\n *\n * @package Genosys\n */\n\ndefined( 'ABSPATH' ) || exit;\n\nglobal $product;\n\ndo_action( 'woocommerce_before_single_product' );\n\nif ( post_password_required() ) {\n\techo get_the_password_form(); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped\n\treturn;\n}\n?>\n<div id=\"product-<?php the_ID(); ?>\" <?php wc_product_class( 'genosys-product', $product ); ?>>\n\t<div class=\"genosys-product__hero\">\n\t\t<div class=\"genosys-product__gallery\">\n\t\t\t<?php\n\t\t\t/** The real responsive WooCommerce gallery and our dynamic sale/stock badge. */\n\t\t\tdo_action( 'woocommerce_before_single_product_summary' );\n\t\t\t?>\n\t\t</div>\n\n\t\t<div class=\"genosys-product__info summary entry-summary\">\n\t\t\t<?php\n\t\t\t/** Native WooCommerce title, excerpt, price, cart form and structured data. */\n\t\t\tdo_action( 'woocommerce_single_product_summary' );\n\t\t\t?>\n\t\t</div>\n\t</div>\n\n\t<?php\n\t/** Native WooCommerce description, attributes and review tabs. */\n\tdo_action( 'woocommerce_after_single_product_summary' );\n\t?>\n</div>\n<?php do_action( 'woocommerce_after_single_product' ); ?>\n","sha256":"69a2f99d62f9f2bd7d282de23de8c4a095209a1469fc4853fca81123e05b0768"},"woocommerce/single-product/related.php":{"content":"<?php\n/**\n * Related products retain WooCommerce's selected products and use the shared card.\n *\n * @package Genosys\n * @version 9.6.0\n */\n\ndefined( 'ABSPATH' ) || exit;\n\nif ( $related_products ) :\n\t$heading = apply_filters( 'woocommerce_product_related_products_heading', __( 'Related products', 'woocommerce' ) );\n\t?>\n\t<section class=\"related products genosys-related-products\">\n\t\t<?php if ( $heading ) : ?>\n\t\t\t<h2><?php echo esc_html( $heading ); ?></h2>\n\t\t<?php endif; ?>\n\t\t<div class=\"latest-products__row\" role=\"region\" aria-label=\"<?php echo esc_attr( 'محصولات مرتبط، فهرست افقی' ); ?>\" tabindex=\"0\">\n\t\t\t<?php foreach ( $related_products as $related_product ) : ?>\n\t\t\t\t<?php get_template_part( 'template-parts/product/card', null, array( 'product' => $related_product ) ); ?>\n\t\t\t<?php endforeach; ?>\n\t\t</div>\n\t\t<p class=\"screen-reader-text\" role=\"status\" aria-live=\"polite\" data-favorites-status></p>\n\t</section>\n\t<?php\nendif;\n\nwp_reset_postdata();\n","sha256":"22b0d59fe8923ed9b28918db1823eb1e4140128ab61347a6988797be728c0fd8"}}}
